template <typename ListPathPool>
class Path {
public:
    Path() = default;
    Path(const Path& parent, const std::string& pathName) : parent_(&parent), pathName_(pathName) {}
    bool isUnique() const {
        if (parent_ == nullptr) {
            return true;  // Root path is always unique
        }
        const auto& paths = parent_->getPaths();
        return paths.find(pathName_) == paths.end();
    }
    void printPath() const {
        if (parent_ != nullptr) {
            parent_->printPath();
            std::cout << "/" << pathName_;
        } else {
            std::cout << "/" << pathName_;
        }
    }
private:
    const Path* parent_ = nullptr;
    std::string pathName_;
    const ListPathPool& getPaths() const {
        return ListPathPool::getInstance();
    }
};
template <typename T>
class ListPathPool {
public:
    static const ListPathPool& getInstance() {
        static ListPathPool instance;
        return instance;
    }
    std::unordered_set<std::string> paths;
private:
    ListPathPool() = default;
};
int main() {
    using Path = Path<ListPathPool<std::string>>;
    Path root;
    Path p1 { root, "path1" };
    Path p2 { root, "path2" };
    Path p3 { root, "path1" };
    Path p4 { p2, "path1" };
    p1.printPath();  // Output: /path1
    std::cout << std::endl;
    p2.printPath();  // Output: /path2
    std::cout << std::endl;
    p3.printPath();  // Output: /path1
    std::cout << std::endl;
    p4.printPath();  // Output: /path2/path1
    std::cout << std::endl;
    std::cout << "p1 is unique: " << (p1.isUnique() ? "true" : "false") << std::endl;  // Output: true
    std::cout << "p2 is unique: " << (p2.isUnique() ? "true" : "false") << std::endl;  // Output: true
    std::cout << "p3 is unique: " << (p3.isUnique() ? "true" : "false") << std::endl;  // Output: false
    std::cout << "p4 is unique: " << (p4.isUnique() ? "true" : "false") << std::endl;  // Output: true
    return 0;
}

#include <mcpputil/mcpputil/pointer_utils.hpp>
#include <unordered_set>
#include <iostream>
class CustomAllocator {
public:
    void* allocate(size_t size) {
        void* ptr = mcpputil::pointer_utils::allocate(size);
        m_allocated_memory.insert(ptr);
        m_total_memory_usage += size;
        return ptr;
    }
    void deallocate(void* ptr, size_t size) {
        auto it = m_allocated_memory.find(ptr);
        if (it != m_allocated_memory.end()) {
            mcpputil::pointer_utils::deallocate(ptr, size);
            m_allocated_memory.erase(it);
            m_total_memory_usage -= size;
        }
    }
    ~CustomAllocator() {
        for (auto ptr : m_allocated_memory) {
            std::cerr << "Memory leak detected at address: " << ptr << std::endl;
            mcpputil::pointer_utils::deallocate(ptr, /* size */); // Deallocate without size information for demonstration purposes
        }
    }
    size_t getMemoryUsage() const {
        return m_total_memory_usage;
    }
private:
    std::unordered_set<void*> m_allocated_memory;
    size_t m_total_memory_usage = 0;
};
int main() {
    CustomAllocator allocator;
    // Allocate memory
    void* mem1 = allocator.allocate(100);
    void* mem2 = allocator.allocate(200);
    // Deallocate memory
    allocator.deallocate(mem1, 100);
    // mem2 is not deallocated intentionally to demonstrate a memory leak
    // Get memory usage
    std::cout << "Total memory usage: " << allocator.getMemoryUsage() << " bytes" << std::endl;
    // Destructor of CustomAllocator will detect and report the memory leak
    return 0;
}

