    // Method to simulate receiving HTTP request event
    void simulateEvent(HTTPRequestHandle request, HTTPRequestEvent event) {
        if (requestCallbacks.find(request) != requestCallbacks.end()) {
            // Simulate asynchronous response handling and callback invocation
            AsyncCallback callback = requestCallbacks[request];
            callback(request);
        }
    }
};
int main() {
    AsyncHTTPManager manager;
    // Send an HTTP request and register a callback for handling the response
    HTTPRequestHandle request = 123;
    SteamAPICall_t callHandle = manager.sendHTTPRequest(request);
    manager.registerCallback(request, [](SteamAPICall_t callHandle) {
        std::cout << "Asynchronous response received for call handle: " << callHandle << std::endl;
    });
    // Simulate receiving HTTP request events
    manager.simulateEvent(request, HTTPRequestEvent::HeadersReceived);
    manager.simulateEvent(request, HTTPRequestEvent::DataReceived);
    return 0;
}

