#include <iostream>
struct Quaternion {
    double w, x, y, z;
    Quaternion(double w, double x, double y, double z) : w(w), x(x), y(y), z(z) {}
    Quaternion operator*(const Quaternion& q) const {
        return Quaternion(
            w * q.w - x * q.x - y * q.y - z * q.z,
            w * q.x + x * q.w + y * q.z - z * q.y,
            w * q.y - x * q.z + y * q.w + z * q.x,
            w * q.z + x * q.y - y * q.x + z * q.w
        );
    }
    bool operator==(const Quaternion& q) const {
        return w == q.w && x == q.x && y == q.y && z == q.z;
    }
};
struct TestCase {
    Quaternion q1, q2, expected;
};
void testQuaternionMultiplication(const TestCase* cases, size_t numCases) {
    for (size_t i = 0; i < numCases; ++i) {
        const auto& item = cases[i];
        Quaternion result = item.q1 * item.q2;
        if (result == item.expected) {
            std::cout << "Test case " << i + 1 << " passed\n";
        } else {
            std::cout << "Test case " << i + 1 << " failed\n";
        }
    }
}
int main() {
    TestCase cases[] = {
        {Quaternion(0, 1, 0, 0), Quaternion(0, 1, 0, 0), Quaternion(-1, 0, 0, 0)},
        {Quaternion(0, 0, 1, 0), Quaternion(0, 0, 1, 0), Quaternion(-1, 0, 0, 0)},
        {Quaternion(0, 0, 0, 1), Quaternion(0, 0, 0, 1), Quaternion(-1, 0, 0, 0)},
        {Quaternion(1, 0, 0, 0), Quaternion(1, 0, 0, 0), Quaternion(1, 0, 0, 0)},
        {Quaternion(4, 1, 2, 3), Quaternion(8, 5, 6, 7), Quaternion(-6, 24, 48, 48)},
        {Quaternion(8, 5, 6, 7), Quaternion(4, 1, 2, 3), Quaternion(-6, 32, 32, 56)},
    };
    testQuaternionMultiplication(cases, sizeof(cases) / sizeof(cases[0]));
    return 0;
}

