using namespace std;
class WordFrequency {
private:
    map<string, int> wordFreq;
public:
    WordFrequency(const string& filename) {
        ifstream file(filename);
        if (file.is_open()) {
            string word;
            while (file >> word) {
                // Remove punctuation from the word
                word.erase(remove_if(word.begin(), word.end(), ::ispunct), word.end());
                // Convert word to lowercase
                transform(word.begin(), word.end(), word.begin(), ::tolower);
                wordFreq[word]++;
            }
            file.close();
        } else {
            cerr << "Error: Unable to open file" << endl;
        }
    }
    int frequency(const string& word) {
        string lowerWord = word;
        transform(lowerWord.begin(), lowerWord.end(), lowerWord.begin(), ::tolower);
        return wordFreq[lowerWord];
    }
};
int main() {
    WordFrequency wf("input.txt");
    cout << "Frequency of 'the': " << wf.frequency("the") << endl;
    cout << "Frequency of 'fox': " << wf.frequency("fox") << endl;
    return 0;
}

