// Define a helper struct to extract the function pointer type from a callable object
template <typename T>
struct function_pointer_traits;
// Specialization for function pointers
template <typename ReturnType, typename... Args>
struct function_pointer_traits<ReturnType (*)(Args...)> {
    using type = ReturnType (*)(Args...);
};
// Specialization for std::function
template <typename ReturnType, typename... Args>
struct function_pointer_traits<std::function<ReturnType(Args...)>> {
    using type = ReturnType (*)(Args...);
};
// Specialization for lambda functions
template <typename Callable>
struct function_pointer_traits {
    using type = typename function_pointer_traits<decltype(&Callable::operator())>::type;
};
// Helper function to convert a callable object to a function pointer
template <typename Callable>
auto convertToFunctionPointer(Callable c) -> typename function_pointer_traits<Callable>::type {
    return +c;  // Using unary plus to convert to function pointer
}
// Test the conversion
int main() {
    // Define a lambda function
    auto lambda = [](int x, int y) { return x + y; };
    // Convert the lambda to a function pointer
    auto funcPtr = convertToFunctionPointer(lambda);
    // Call the function pointer
    std::cout << funcPtr(3, 4) << std::endl;  // Output: 7
    return 0;
}

