// Function to generate a random number from a normal distribution with mean 0 and standard deviation 1
double generateRandomNumber(std::default_random_engine& engine) {
    std::normal_distribution<double> distribution(0.0, 1.0);
    return distribution(engine);
}
int main() {
    // Initialize parameters
    double v = 0.0;  // Initial velocity
    double x = 0.0;  // Initial position
    double sigmaV = 0.1;  // Standard deviation for velocity updates
    double sigmaX = 0.2;  // Standard deviation for position updates
    int numSteps = 100;  // Number of time steps
    std::default_random_engine engine;  // Random number generator
    // Data structure for storing simulation results
    std::map<std::string, double> table;
    int i = 0;  // Index for recording the data
    double t = 0.0;  // Current time
    // Simulate the motion of the particle for the specified number of time steps
    for (int step = 0; step < numSteps; ++step) {
        // Update the velocity and position using the Euler-Maruyama method
        v += sigmaV * generateRandomNumber(engine);
        x += sigmaX * generateRandomNumber(engine);
        // Record the data in the table
        table["I"] = i++;
        table["Time"] = t;
        table["Velocity"] = v;
        table["Position"] = x;
        table["SigmaX"] = sigmaX;
        table["SigmaV"] = sigmaV;
        // Print the captured data
        for (const auto& entry : table) {
            std::cout << entry.first << ": " << entry.second << std::endl;
        }
        // Increment the time
        t += 1.0;
        // Clear the table for the next time step
        table.clear();
    }
    return 0;
}

