#include <Windows.h>
class TicketSystem {
private:
    int totalTickets;
    HANDLE semaphore;
public:
    TicketSystem(int initialTickets) : totalTickets(initialTickets) {
        semaphore = CreateSemaphore(NULL, initialTickets, 0x7FFFFFFF, NULL);
    }
    void AddTickets(int numTickets) {
        totalTickets += numTickets;
        ReleaseSemaphore(semaphore, numTickets, NULL);
    }
    bool BuyTickets(int numTickets) {
        if (WaitForSingleObject(semaphore, 0) == WAIT_OBJECT_0) {
            if (totalTickets >= numTickets) {
                totalTickets -= numTickets;
                ReleaseSemaphore(semaphore, numTickets, NULL);
                return true;
            }
            ReleaseSemaphore(semaphore, 1, NULL);
        }
        return false;
    }
};
void SellerThread(TicketSystem& system, int numTickets) {
    system.AddTickets(numTickets);
}
void BuyerThread(TicketSystem& system, int numTickets) {
    if (system.BuyTickets(numTickets)) {
        std::cout << "Tickets purchased: " << numTickets << std::endl;
    } else {
        std::cout << "Tickets not available" << std::endl;
    }
}
int main() {
    TicketSystem ticketSystem(10);
    std::vector<std::thread> threads;
    for (int i = 0; i < 5; ++i) {
        threads.emplace_back(SellerThread, std::ref(ticketSystem), 3);
        threads.emplace_back(BuyerThread, std::ref(ticketSystem), 2);
    }
    for (auto& t : threads) {
        t.join();
    }
    std::cout << "Remaining tickets: " << ticketSystem.BuyTickets(0) << std::endl;
    return 0;
}

#include <skizzay/fsm/guarded_action_transition.h>
#include <iostream>
using namespace skizzay::fsm;
// Define the guarded action transition class
template <typename EventType, typename GuardCondition, typename Action>
class MyGuardedActionTransition : public guarded_action_transition<EventType> {
public:
    MyGuardedActionTransition(EventType event_type, GuardCondition guard_condition, Action action)
        : guarded_action_transition<EventType>(event_type), guard_condition_(guard_condition), action_(action) {}
    bool guard() const {
        return guard_condition_();
    }
    void execute() const {
        action_();
    }
private:
    GuardCondition guard_condition_;
    Action action_;
};
// Define the FSM states and events
enum class State { START, END };
enum class Event { TRIGGER };
int main() {
    // Create the guarded action transition
    auto guard_condition = []() { return true; };
    auto action = []() { std::cout << "Transition action performed" << std::endl; };
    MyGuardedActionTransition<Event, decltype(guard_condition), decltype(action)> transition(Event::TRIGGER, guard_condition, action);
    // Create the FSM and add the transition
    finite_state_machine<State, Event> fsm(State::START);
    fsm.add_transition(State::START, Event::TRIGGER, State::END, transition);
    // Trigger the event to test the transition
    fsm.process_event(Event::TRIGGER);
    return 0;
}

