public:
    Output(Node* node, int index, Tensor* tensor) : m_node(node), m_index(index), m_tensor(tensor) {}
    // Add an input to the vector of inputs that use this output.
    void add_input(Input* input) {
        // Keep the inputs in insertion order to keep sorts deterministic
        if (std::find(m_inputs.begin(), m_inputs.end(), input) == m_inputs.end()) {
            m_inputs.push_back(input);
        }
    }
    void remove_input(Input* input) {
        auto it = std::find(m_inputs.begin(), m_inputs.end(), input);
        if (it != m_inputs.end()) {
            m_inputs.erase(it);
        }
    }
private:
    Node* m_node;
    int m_index;
    Tensor* m_tensor;
    std::vector<Input*> m_inputs;
};
