#include <fcppt/math/matrix/binary_map.hpp>
#include <fcppt/math/matrix/comparison.hpp>
template <typename T, fcppt::math::size_type R, fcppt::math::size_type C>
bool compare_matrices(
    fcppt::math::matrix::object<T, R, C> const &matrix1,
    fcppt::math::matrix::object<T, R, C> const &matrix2,
    fcppt::math::matrix::object<T, R, C> const &expected_result)
{
    auto const result = fcppt::math::matrix::binary_map(
        matrix1,
        matrix2,
        [](T const &elem1, T const &elem2) { return elem1 + elem2; });
    return fcppt::math::matrix::comparison(result, expected_result);
}

