                property.SetValue(value);
            } else if (property.type == PropertyType::Float) {
                float value = property.GetValue<float>();
                ImGui::InputFloat(property.name.c_str(), &value);
                property.SetValue(value);
            } // Handle other property types as needed
        }
    }
