#include <iostream>
#include <stack>
using namespace std;
class Stack {
private:
    stack<int> mainStack;
    stack<int> minStack;
public:
    void push(int x) {
        // Add element to main stack
        mainStack.push(x);

        // Update minStack if the added element is smaller or equal to the current minimum
        if (minStack.empty() || x <= minStack.top()) {
            minStack.push(x);
        }
    }
    void pop() {
        // Remove element from main stack
        if (mainStack.top() == minStack.top()) {
            minStack.pop();
        }
        mainStack.pop();
    }
    int top() {
        return mainStack.top();
    }
    bool isEmpty() {
        return mainStack.empty();
    }
    int getMin() {
        return minStack.top();
    }
};

