#include <vector>
#include <stack>
std::vector<int> next_larger_element(int n, const std::vector<int>& nums) {
    std::vector<int> result(n, -1);  // Initialize result array with -1
    std::stack<int> stack;  // Stack to store indices of elements
    for (int i = 0; i < n; i++) {
        while (!stack.empty() && nums[i] > nums[stack.top()]) {
            result[stack.top()] = nums[i];  // Update result for elements with next larger element
            stack.pop();  // Pop the index as it has been processed
        }
        stack.push(i);  // Push the current index onto the stack
    }
    return result;
}

