public:
    // Process audio signal by folding the waveform
    float process(float input, float threshold) {
        if (input > threshold) {
            return 2 * threshold - input;
        } else if (input < -threshold) {
            return 2 * (-threshold) - input;
        } else {
            return input;
        }
    }
};
