std::tuple<int, int, int> getHighestResolutionMode(const std::vector<std::tuple<int, int, int>>& videoModes) {
    std::tuple<int, int, int> highestMode = videoModes[0];  // Initialize with the first mode
    for (const auto& mode : videoModes) {
        if (std::get<0>(mode) > std::get<0>(highestMode) ||  // Check for higher resolution
            (std::get<0>(mode) == std::get<0>(highestMode) && std::get<1>(mode) > std::get<1>(highestMode)) ||  // Check for same resolution but higher refresh rate
            (std::get<0>(mode) == std::get<0>(highestMode) && std::get<1>(mode) == std::get<1>(highestMode) && std::get<2>(mode) > std::get<2>(highestMode))) {  // Check for same resolution and refresh rate but higher refresh rate
            highestMode = mode;  // Update highest mode
        }
    }
    return highestMode;
}

template <typename Real>
Real CalculateSquaredDistance(const Triangle3<Real>* mTriangle, Real t, const Vector3<Real>& velocity1, const Segment3<Real>* mSegment) {
    // Calculate the moved vertices of the triangle
    Vector3<Real> movedV0 = mTriangle->V[0] + t * velocity1;
    Vector3<Real> movedV1 = mTriangle->V[1] + t * velocity1;
    Vector3<Real> movedV2 = mTriangle->V[2] + t * velocity1;
    // Create the moved segment and triangle
    Segment3<Real> movedSeg(mSegment->Center + t * mSegment->Direction, mSegment->Direction, mSegment->Extent);
    Triangle3<Real> movedTriangle(movedV0, movedV1, movedV2);
    // Calculate the squared distance between the moved segment and triangle
    return DistSegment3Triangle3<Real>(movedSeg, movedTriangle).GetSquared();
}

void SMExtractRGBI(IplImage* inputImage, CvMat* &R, CvMat* &G, CvMat* &B, CvMat* &I)
{
    // Convert input image to OpenCV Mat
    Mat inputMat(inputImage);
    // Split the input image into its RGB components
    vector<Mat> rgbChannels;
    split(inputMat, rgbChannels);
    // Convert RGB channels to floating point format
    Mat R_float, G_float, B_float;
    rgbChannels[2].convertTo(R_float, CV_32F);
    rgbChannels[1].convertTo(G_float, CV_32F);
    rgbChannels[0].convertTo(B_float, CV_32F);
    // Calculate intensity (I) as the average of RGB channels
    Mat I_float = (R_float + G_float + B_float) / 3.0;
    // Allocate memory for output matrices
    R = cvCreateMat(inputImage->height, inputImage->width, CV_32FC1);
    G = cvCreateMat(inputImage->height, inputImage->width, CV_32FC1);
    B = cvCreateMat(inputImage->height, inputImage->width, CV_32FC1);
    I = cvCreateMat(inputImage->height, inputImage->width, CV_32FC1);
    // Copy data from OpenCV Mat to CvMat
    memcpy(R->data.fl, R_float.data, R_float.total() * sizeof(float));
    memcpy(G->data.fl, G_float.data, G_float.total() * sizeof(float));
    memcpy(B->data.fl, B_float.data, B_float.total() * sizeof(float));
    memcpy(I->data.fl, I_float.data, I_float.total() * sizeof(float);
}

void OptimizeDataFlow(Graph* graph) {
  for (auto&& item : graph->nodes) {
    for (auto&& output : item.outputs) {
      if (output.output_id == Node::kDependency) {
        continue;
      }
      Device* src_device = item.arg.device;
      Device* dst_device = graph->nodes[output.node_id].arg.device;
      if (src_device != dst_device) {
        // Check if a direct connection exists between src_device and dst_device
        if (CheckDirectConnection(src_device, dst_device)) {
          // If direct connection exists, no need for a device converter
          continue;
        } else {
          // If no direct connection, create a device converter
          XDL_CHECK_STATUS(CreateDeviceConverter(src_device, dst_device));
        }
      }
      for (int input_id = 0; input_id < graph->nodes[output.node_id].inputs.size(); ++input_id) {
        if (input_id >= graph->nodes[output.node_id].arg.input_devices.size()) break;
        // Additional logic for data flow optimization
      }
    }
  }
}

