            for (auto& s : socks) {
                close_socket(s);
            }
            close_socket(sock);
            return;
        }
        socks.push_back(sock);
    }
    // Send packet to each connection
    for (auto& sock : socks) {
        char* packet = new char[packetSize];
        // Populate packet with data
        // ...
        if (send(sock, packet, packetSize, 0) != packetSize) {
            std::cerr << "Error sending packet on socket " << sock << std::endl;
            // Handle error and continue sending to other sockets
        }
        delete[] packet;
    }
    // Close all opened sockets
    for (auto& sock : socks) {
        close_socket(sock);
    }
}

#include <iostream>
class Operand {
public:
  Operand(const std::string& value) : value_(value) {}
  friend std::ostream& operator<<(std::ostream& os, const Operand& operand) {
    os << operand.value_;
    return os;
  }
private:
  std::string value_;
};
class Operator {
public:
  Operator(const std::string& symbol) : symbol_(symbol) {}
  friend std::ostream& operator<<(std::ostream& os, const Operator& op) {
    os << op.symbol_;
    return os;
  }
private:
  std::string symbol_;
};
void printExpression(std::ostream& os, bool post_, const Operand& expr_, const Operator& op_) {
  if (post_)
    os << expr_ << " " << op_;
  else
    os << op_ << " " << expr_;
}
int main() {
  Operand expr("5");
  Operator op("+");
  std::cout << "Postfix format: ";
  printExpression(std::cout, true, expr, op);
  std::cout << std::endl;
  std::cout << "Prefix format: ";
  printExpression(std::cout, false, expr, op);
  std::cout << std::endl;
  return 0;
}

bool CommandRemoveRagdollJoint::Execute(const MCore::CommandLine& parameters, AZStd::string& outResult)
{
    AZ_UNUSED(parameters);
    Actor* actor = GetActor(this, outResult);
    if (!actor)
    {
        return false;
    }
    const AZStd::shared_ptr<PhysicsSetup>& physicsSetup = actor->GetPhysicsSetup();
    // Assuming the ragdoll joint name is provided as a parameter in the command line
    AZStd::string ragdollJointName;
    if (!parameters.GetValue("jointName", ragdollJointName))
    {
        outResult = "Error: Ragdoll joint name not provided.";
        return false;
    }
    // Check if the ragdoll joint exists in the physics setup
    if (!physicsSetup->HasRagdollJoint(ragdollJointName))
    {
        outResult = "Error: Ragdoll joint '" + ragdollJointName + "' does not exist in the physics setup.";
        return false;
    }
    // Remove the specified ragdoll joint from the physics setup
    physicsSetup->RemoveRagdollJoint(ragdollJointName);
    outResult = "Ragdoll joint '" + ragdollJointName + "' successfully removed from the physics setup.";
    return true;
}

