#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
// Function to map characters 'A'-'Z', '0'-'9' to an integer index [0, 35]
inline int char_to_int(char c) {
    if (c >= 'A' && c <= 'Z') {
        return c - 'A';
    }
    // Assumes c is a digit '0'-'9' based on problem constraints
    return c - '0' + 26;
}
// The core greedy algorithm
// Iterates through s_iterate and finds the earliest possible match for each character
// based on precomputed character positions `pos_search`.
// This is an O(|s_iterate| + |s_search|) implementation where |s_search| is the
// length of the string from which pos_search was built.
std::string solve_greedy(const std::string& s_iterate, const std::vector<std::vector<int>>& pos_search) {
    std::string res;
    if (s_iterate.empty()) {
        return res;
    }
    res.reserve(s_iterate.length());

    int last_search_idx = -1;
    std::vector<int> ptrs(36, 0);
    for (char c_iterate : s_iterate) {
        int char_idx = char_to_int(c_iterate);

        const std::vector<int>& positions = pos_search[char_idx];
        int& p = ptrs[char_idx];

        // Advance pointer to the first available position
        while (static_cast<size_t>(p) < positions.size() && positions[p] <= last_search_idx) {
            p++;
        }

        if (static_cast<size_t>(p) < positions.size()) {
            res.push_back(c_iterate);
            last_search_idx = positions[p];
            p++;
        }
    }
    return res;
}
int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
    std::string s1, s2;
    std::cin >> s1 >> s2;
    // Precompute character positions for both strings
    std::vector<std::vector<int>> pos1(36);
    std::vector<std::vector<int>> pos2(36);
    for (size_t i = 0; i < s1.length(); ++i) {
        pos1[char_to_int(s1[i])].push_back(i);
    }
    for (size_t i = 0; i < s2.length(); ++i) {
        pos2[char_to_int(s2[i])].push_back(i);
    }
    // Run greedy algorithm in both directions:
    // 1. Iterate through s1, search in s2
    // 2. Iterate through s2, search in s1
    std::string res1 = solve_greedy(s1, pos2);
    std::string res2 = solve_greedy(s2, pos1);
    // Output the longer result
    if (res1.length() >= res2.length()) {
        std::cout << res1 << '\n';
    } else {
        std::cout << res2 << '\n';
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>
#include <random>
#include <chrono>
using namespace std;
int main() {
    // Optimize I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n;
    if (!(cin >> n)) return 0;
    int target1 = n / 2;
    int target2 = n / 2 + 1;
    // Candidates initially contains all indices 1 to n
    vector<int> candidates(n);
    iota(candidates.begin(), candidates.end(), 1);
    // To store a pair {small, large} that we have successfully discarded
    // This is needed for padding when we reach k=4 candidates
    vector<int> last_discarded_pair;
    // Random number generator
    mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());
    // We continue until we have identified the two medians
    // The loop handles reducing candidates size until we find the answer
    while (candidates.size() > 2) {
        // Pick two distinct indices from candidates at random
        vector<int> p(candidates.size());
        iota(p.begin(), p.end(), 0);
        shuffle(p.begin(), p.end(), rng);
        int idx1 = p[0];
        int idx2 = p[1];

        // These are the values (original indices in permutation) we are tentatively removing/testing
        int val1 = candidates[idx1];
        int val2 = candidates[idx2];
        vector<int> query;
        if (candidates.size() > 4) {
            // Strategy: Try to remove two elements.
            // If the two removed elements are one Small (< n/2) and one Large (> n/2+1),
            // the medians of the remaining set will remain n/2 and n/2+1.
            // We query all candidates except the two chosen.
            for (size_t i = 0; i < candidates.size(); ++i) {
                if ((int)i == idx1 || (int)i == idx2) continue;
                query.push_back(candidates[i]);
            }
        } else {
            // candidates.size() == 4
            // We cannot query a subsequence of length 2 (since k >= 4).
            // We use a previously discarded pair (which we know is one Small, one Large) to pad the query to length 4.
            // If the remaining 2 candidates (kept in query) are the Medians,
            // then {Median1, Median2, Pad_Small, Pad_Large} will have medians Median1 and Median2.

            // Add the kept candidates
            for (size_t i = 0; i < candidates.size(); ++i) {
                if ((int)i == idx1 || (int)i == idx2) continue;
                query.push_back(candidates[i]);
            }
            // Add padding
            query.push_back(last_discarded_pair[0]);
            query.push_back(last_discarded_pair[1]);
        }
        // Print query
        cout << "0 " << query.size();
        for (int x : query) cout << " " << x;
        cout << endl;
        // Read response
        int m1, m2;
        cin >> m1 >> m2;
        if (m1 == target1 && m2 == target2) {
            // Success condition: the medians are preserved
            if (candidates.size() > 4) {
                // We found a (Small, Large) pair to discard
                last_discarded_pair = {val1, val2};

                // Update candidates by permanently removing val1 and val2
                vector<int> next_candidates;
                for (size_t i = 0; i < candidates.size(); ++i) {
                    if ((int)i == idx1 || (int)i == idx2) continue;
                    next_candidates.push_back(candidates[i]);
                }
                candidates = next_candidates;
            } else {
                // candidates.size() == 4
                // We kept the true Medians in the query (along with padding)
                // So the candidates we DIDN'T remove (the ones in the query from candidates) are the answer
                vector<int> ans;
                for (size_t i = 0; i < candidates.size(); ++i) {
                    if ((int)i == idx1 || (int)i == idx2) continue;
                    ans.push_back(candidates[i]);
                }
                cout << "1 " << ans[0] << " " << ans[1] << endl;
                return 0;
            }
        } else {
            // Failure: the pair we picked was not (Small, Large) or (for size 4) we removed a Median
            // Do nothing, just loop again to pick a different random pair
        }
    }
    return 0;
}

#include "flareqt/updatechecker.h"
#include <QNetworkReply>
UpdateChecker::UpdateChecker(QUrl const& updateUrl)
    : manager_(new QNetworkAccessManager(this),
               &QNetworkAccessManager::deleteLater) {
  connect(manager_.data(), SIGNAL(finished(QNetworkReply*)), this,
          SLOT(httpRequestFinished(QNetworkReply*)));
  manager_->get(QNetworkRequest(updateUrl));
}
void UpdateChecker::httpRequestFinished(QNetworkReply* pReply) {
  QSharedPointer<QNetworkReply> reply(pReply, &QNetworkReply::deleteLater);
  // If there was an error, don't bother doing the check
  if (reply->error() != QNetworkReply::NoError) {
    emit done(true);
    return;
  }
  // Convert the response from a QByteArray into a QString
  QString candidateVersion = QString(reply->readAll()).trimmed();
  // TODO: Verify that the response was valid by ensuring we have a single line
  // in the format x.x[.x]*
  if (candidateVersion.indexOf(".") < 0) {
    // There was some invalid response, so we'll ignore the check for now
    emit done(true);
    return;
  }
  // Completed with no errors
  m_latestVersion = candidateVersion;
  emit done(false);
}

#include <iostream>
#include <istream>
#include <ostream>
#include <string>
#include <asio.hpp>
using asio::ip::tcp;
int main(int argc, char* argv[])
{
  try
  {
    if (argc != 3)
    {
      std::cout << "Usage: sync_client <server> <path>\n";
      std::cout << "Example:\n";
      std::cout << "  sync_client www.boost.org /LICENSE_1_0.txt\n";
      return 1;
    }
    asio::io_context io_context;
    // Get a list of endpoints corresponding to the server name.
    tcp::resolver resolver(io_context);
    tcp::resolver::results_type endpoints = resolver.resolve(argv[1], "http");
    // Try each endpoint until we successfully establish a connection.
    tcp::socket socket(io_context);
    asio::connect(socket, endpoints);
    // Form the request. We specify the "Connection: close" header so that the
    // server will close the socket after transmitting the response. This will
    // allow us to treat all data up until the EOF as the content.
    asio::streambuf request;
    std::ostream request_stream(&request);
    request_stream << "GET " << argv[2] << " HTTP/1.0\r\n";
    request_stream << "Host: " << argv[1] << "\r\n";
    request_stream << "Accept: */*\r\n";
    request_stream << "Connection: close\r\n\r\n";
    // Send the request.
    asio::write(socket, request);
    // Read the response status line. The response streambuf will automatically
    // grow to accommodate the entire line. The growth may be limited by passing
    // a maximum size to the streambuf constructor.
    asio::streambuf response;
    asio::read_until(socket, response, "\r\n");
    // Check that response is OK.
    std::istream response_stream(&response);
    std::string http_version;
    response_stream >> http_version;
    unsigned int status_code;
    response_stream >> status_code;
    std::string status_message;
    std::getline(response_stream, status_message);
    if (!response_stream || http_version.substr(0, 5) != "HTTP/")
    {
      std::cout << "Invalid response\n";
      return 1;
    }
    if (status_code != 200)
    {
      std::cout << "Response returned with status code " << status_code << "\n";
      return 1;
    }
    // Read the response headers, which are terminated by a blank line.
    asio::read_until(socket, response, "\r\n\r\n");
    // Process the response headers.
    std::string header;
    while (std::getline(response_stream, header) && header != "\r")
      std::cout << header << "\n";
    std::cout << "\n";
    // Write whatever content we already have to output.
    if (response.size() > 0)
      std::cout << &response;
    // Read until EOF, writing data to output as we go.
    asio::error_code error;
    while (asio::read(socket, response,
          asio::transfer_at_least(1), error))
      std::cout << &response;
    if (error != asio::error::eof)
      throw asio::system_error(error);
  }
  catch (std::exception& e)
  {
    std::cout << "Exception: " << e.what() << "\n";
  }
  return 0;
}

