        std::shared_ptr<SMTParser::DAGNode> result = parser->mkExpr(expr);
        assert(result && (result->isTrue() || result->isFalse()));
        std::cout << "  Result: " << parser->toString(result) << std::endl;
        std::cout << std::endl;
    }
}
