    SMTParser::ParserPtr parser = SMTParser::newParser();

    test_bitvector_constants(parser);
    test_bv_logical_operations(parser);
    test_bv_arithmetic_operations(parser);
    test_bv_comparison_operations(parser);

    return 0;
}

