#include "linux/dbus.hpp"
namespace srouter::dns::sd
{
    void Platform::set_resolver(unsigned int if_ndx, quic::Address dns, bool global)
    {
        linux::DBUS _dbus{"org.freedesktop.resolve1", "/org/freedesktop/resolve1", "org.freedesktop.resolve1.Manager"};
        // This passing address by bytes and using two separate calls for ipv4/ipv6 is gross, but
        // the alternative is to build up a bunch of crap with va_args, which is slightly more
        // gross.
        _dbus("SetLinkDefaultRoute", "ib", (int32_t)if_ndx, false);
        _dbus("SetLinkDNSOverTLS", "is", (int32_t)if_ndx, "off");
        if (dns.is_ipv6())
        {
            auto& a = dns.in6().sin6_addr.s6_addr;
            static_assert(sizeof(a) == 16);
            _dbus(
                "SetLinkDNSEx",
                "ia(iayqs)",
                (int32_t)if_ndx,
                (int)1,             // number of "iayqs"s we are passing
                (int32_t)AF_INET6,  // network address type
                (int)16,            // network addr byte size
                // clang-format off
                a[0], a[1], a[2],  a[3],  a[4],  a[5],  a[6],  a[7],
                a[8], a[9], a[10], a[11], a[12], a[13], a[14], a[15], // yuck
                // clang-format on
                dns.port(),
                nullptr  // dns server name (for TLS SNI which we don't care about)
            );
        }
        else
        {
            std::span<const uint8_t, 4> a{reinterpret_cast<const uint8_t*>(&dns.in4().sin_addr.s_addr), 4};
            _dbus(
                "SetLinkDNSEx",
                "ia(iayqs)",
                (int32_t)if_ndx,
                (int)1,            // number of "iayqs"s we are passing
                (int32_t)AF_INET,  // network address type
                (int)4,            // network addr byte size
                // clang-format off
                a[0], a[1], a[2], a[3], // yuck
                // clang-format on
                dns.port(),
                nullptr  // dns server name (for TLS SNI which we don't care about)
            );
        }
        if (global)
            // Setting "." as a routing domain gives this DNS server higher priority in resolution
            // compared to dns servers that are set without a domain (e.g. the default for a
            // DHCP-configured DNS server)
            _dbus(
                "SetLinkDomains",
                "ia(sb)",
                (int32_t)if_ndx,
                (int)1,  // array size
                "."      // global DNS root
            );
        else
            // Only resolve .sesh/.loki/.snode through Session Router (so you keep using your local DNS
            // server for everything else, which is nicer than forcing everything though Session Router's
            // upstream DNS).
            _dbus(
                "SetLinkDomains",
                "ia(sb)",
                (int32_t)if_ndx,
                (int)3,   // array size
                "sesh",   // domain
                (int)1,   // routing domain = true
                "snode",  // domain
                (int)1,   // routing domain = true
                "loki",   // domain
                (int)1    // routing domain = true
            );
    }
}  // namespace srouter::dns::sd
#endif

#include "server/stdio_server_transport.hpp"
#include "protocol/mcp_message.hpp"
#include "duckdb/common/exception.hpp"
#include "duckdb_mcp_logging.hpp"
#include <iostream>
namespace duckdb {
FdServerTransport::FdServerTransport() : connected(false) {
}
FdServerTransport::~FdServerTransport() {
	Disconnect();
}
bool FdServerTransport::Connect() {
	lock_guard<mutex> lock(io_mutex);
	if (connected) {
		return true;
	}
	connected = true;
	return true;
}
void FdServerTransport::Disconnect() {
	lock_guard<mutex> lock(io_mutex);
	connected = false;
}
bool FdServerTransport::IsConnected() const {
	return connected;
}
void FdServerTransport::Send(const MCPMessage &message) {
	if (!IsConnected()) {
		MCP_LOG_ERROR("stdio", "Send called but not connected");
		throw IOException("Not connected");
	}
	lock_guard<mutex> lock(io_mutex);
	try {
		string json = message.ToJSON();
		MCP_LOG_DEBUG("stdio", "Sending response: %s", json.substr(0, 100).c_str());
		// Write directly to stdout and flush immediately
		std::cout << json << std::endl;
		std::cout.flush();
		MCP_LOG_DEBUG("stdio", "Response sent and flushed");
	} catch (const std::exception &e) {
		MCP_LOG_ERROR("stdio", "Failed to send message: %s", e.what());
		throw IOException("Failed to send message: " + string(e.what()));
	}
}
MCPMessage FdServerTransport::Receive() {
	if (!IsConnected()) {
		MCP_LOG_ERROR("stdio", "Receive called but not connected");
		throw IOException("Not connected");
	}
	lock_guard<mutex> lock(io_mutex);
	try {
		MCP_LOG_DEBUG("stdio", "Waiting for input on stdin...");
		// Use std::getline which blocks until a line is available
		// This properly handles iostream buffering without mixing with poll()
		string line;
		if (!std::getline(std::cin, line)) {
			MCP_LOG_DEBUG("stdio", "EOF or error on stdin");
			throw IOException("End of input stream");
		}
		MCP_LOG_DEBUG("stdio", "Received line (%zu chars): %s", line.length(), line.substr(0, 100).c_str());
		if (line.empty()) {
			MCP_LOG_WARN("stdio", "Received empty line");
			throw IOException("Received empty message");
		}
		return MCPMessage::FromJSON(line);
	} catch (const IOException &) {
		throw;
	} catch (const std::exception &e) {
		MCP_LOG_ERROR("stdio", "Failed to receive/parse message: %s", e.what());
		throw IOException("Failed to receive message: " + string(e.what()));
	}
}
MCPMessage FdServerTransport::SendAndReceive(const MCPMessage &message) {
	// For server mode, this doesn't make sense - we send responses, not requests
	throw NotImplementedException("SendAndReceive not supported in server mode");
}
bool FdServerTransport::Ping() {
	return IsConnected();
}
string FdServerTransport::GetConnectionInfo() const {
	return "stdio server transport (stdin/stdout)";
}
} // namespace duckdb

