    UInt32 GPE0Block;
    UInt32 GPE1Block;
    UInt8  PM1EventLength;
    UInt8  PM1ControlLength;
    UInt8  PM2ControlLength;
    UInt8  PMTimerLength;
    UInt8  GPE0Length;
    UInt8  GPE1Length;
    UInt8  GPE1Base;
