#include "lib/common/demangle.hpp"
#include <gtest/gtest.h>
#include <string_view>
#include <utility>
TEST(common, demangling)
{
    // the purpose of this test is to verify the cxx_demangle function.
    // We want to make sure that the function produces the right demangling
    // when it is a correctly mangled string and does not change the string
    // when demangling fails
    using strview_pair_t = std::pair<std::string_view, std::string_view>;
    for(auto [mangled, demangled] :
        {strview_pair_t{"_ZN11rocprofiler8internal18correlation_config22get_unique_internal_idEv",
                        "rocprofiler::internal::correlation_config::get_unique_internal_id()"},
         strview_pair_t{"_ZN11rocprofiler8internal18get_active_configsEv",
                        "rocprofiler::internal::get_active_configs()"},
         strview_pair_t{"_ZN11rocprofiler8internal22get_registered_configsEv",
                        "rocprofiler::internal::get_registered_configs()"},
         strview_pair_t{
             "_ZZN11rocprofiler8internal18correlation_config22get_unique_internal_idEvE2_v",
             "rocprofiler::internal::correlation_config::get_unique_internal_id()::_v"},
         strview_pair_t{"_ZZN11rocprofiler8internal18get_active_configsEvE2_v",
                        "rocprofiler::internal::get_active_configs()::_v"},
         strview_pair_t{"_ZZN11rocprofiler8internal22get_registered_configsEvE2_v",
                        "rocprofiler::internal::get_registered_configs()::_v"}})
    {
        // verify the demangling works
        EXPECT_EQ(rocprofiler::common::cxx_demangle(mangled), demangled)
            << "failed to demangle '" << mangled << "'";
        // verify we get same string in when improperly mangled string
        auto bad_mangled = std::string{"_Z"} + std::string{mangled};
        EXPECT_EQ(rocprofiler::common::cxx_demangle(bad_mangled), bad_mangled)
            << "demangling succeeded for '" << bad_mangled << "'";
    }
}
TEST(common, truncate)
{
    // this test is verify that the truncate_name function correctly finds the function
    // name in a complex template instantiation
    auto mangled = std::string_view{"_ZSt16__do_uninit_copyIPKSt4pairINSt7__cxx1112basic_"
                                    "stringIcSt11char_traitsIcESaIcEEES6_EPS7_ET0_T_SC_SB_"};
    auto untruncated = std::string_view{
        "std::pair<std::__cxx11::basic_string<char, std::char_traits<char>, std::allocator<char> "
        ">, std::__cxx11::basic_string<char, std::char_traits<char>, std::allocator<char> > >* "
        "std::__do_uninit_copy<std::pair<std::__cxx11::basic_string<char, std::char_traits<char>, "
        "std::allocator<char> >, std::__cxx11::basic_string<char, std::char_traits<char>, "
        "std::allocator<char> > > const*, std::pair<std::__cxx11::basic_string<char, "
        "std::char_traits<char>, std::allocator<char> >, std::__cxx11::basic_string<char, "
        "std::char_traits<char>, std::allocator<char> > "
        ">*>(std::pair<std::__cxx11::basic_string<char, std::char_traits<char>, "
        "std::allocator<char> >, std::__cxx11::basic_string<char, std::char_traits<char>, "
        "std::allocator<char> > > const*, std::pair<std::__cxx11::basic_string<char, "
        "std::char_traits<char>, std::allocator<char> >, std::__cxx11::basic_string<char, "
        "std::char_traits<char>, std::allocator<char> > > const*, "
        "std::pair<std::__cxx11::basic_string<char, std::char_traits<char>, std::allocator<char> "
        ">, std::__cxx11::basic_string<char, std::char_traits<char>, std::allocator<char> > >*)"};
    EXPECT_EQ(rocprofiler::common::cxx_demangle(mangled), untruncated);
    EXPECT_EQ(rocprofiler::common::truncate_name(untruncated),
              std::string_view{"__do_uninit_copy"});
    EXPECT_EQ(rocprofiler::common::truncate_name(rocprofiler::common::cxx_demangle(mangled)),
              std::string_view{"__do_uninit_copy"});
}

#include <cstdlib>
#include <iostream>
#include <boost/bind.hpp>
#include "asio.hpp"
#include "asio/ssl.hpp"
enum { max_length = 1024 };
class client
{
public:
  client(asio::io_context& io_context,
      asio::ssl::context& context,
      asio::ip::tcp::resolver::results_type endpoints)
    : socket_(io_context, context)
  {
    socket_.set_verify_mode(asio::ssl::verify_peer);
    socket_.set_verify_callback(
        boost::bind(&client::verify_certificate, this, _1, _2));
    asio::async_connect(socket_.lowest_layer(), endpoints,
        boost::bind(&client::handle_connect, this,
          asio::placeholders::error));
  }
  bool verify_certificate(bool preverified,
      asio::ssl::verify_context& ctx)
  {
    // The verify callback can be used to check whether the certificate that is
    // being presented is valid for the peer. For example, RFC 2818 describes
    // the steps involved in doing this for HTTPS. Consult the OpenSSL
    // documentation for more details. Note that the callback is called once
    // for each certificate in the certificate chain, starting from the root
    // certificate authority.
    // In this example we will simply print the certificate's subject name.
    char subject_name[256];
    X509* cert = X509_STORE_CTX_get_current_cert(ctx.native_handle());
    X509_NAME_oneline(X509_get_subject_name(cert), subject_name, 256);
    std::cout << "Verifying " << subject_name << "\n";
    return preverified;
  }
  void handle_connect(const asio::error_code& error)
  {
    if (!error)
    {
      socket_.async_handshake(asio::ssl::stream_base::client,
          boost::bind(&client::handle_handshake, this,
            asio::placeholders::error));
    }
    else
    {
      std::cout << "Connect failed: " << error.message() << "\n";
    }
  }
  void handle_handshake(const asio::error_code& error)
  {
    if (!error)
    {
      std::cout << "Enter message: ";
      std::cin.getline(request_, max_length);
      size_t request_length = strlen(request_);
      asio::async_write(socket_,
          asio::buffer(request_, request_length),
          boost::bind(&client::handle_write, this,
            asio::placeholders::error,
            asio::placeholders::bytes_transferred));
    }
    else
    {
      std::cout << "Handshake failed: " << error.message() << "\n";
    }
  }
  void handle_write(const asio::error_code& error,
      size_t bytes_transferred)
  {
    if (!error)
    {
      asio::async_read(socket_,
          asio::buffer(reply_, bytes_transferred),
          boost::bind(&client::handle_read, this,
            asio::placeholders::error,
            asio::placeholders::bytes_transferred));
    }
    else
    {
      std::cout << "Write failed: " << error.message() << "\n";
    }
  }
  void handle_read(const asio::error_code& error,
      size_t bytes_transferred)
  {
    if (!error)
    {
      std::cout << "Reply: ";
      std::cout.write(reply_, bytes_transferred);
      std::cout << "\n";
    }
    else
    {
      std::cout << "Read failed: " << error.message() << "\n";
    }
  }
private:
  asio::ssl::stream<asio::ip::tcp::socket> socket_;
  char request_[max_length];
  char reply_[max_length];
};
int main(int argc, char* argv[])
{
  try
  {
    if (argc != 3)
    {
      std::cerr << "Usage: client <host> <port>\n";
      return 1;
    }
    asio::io_context io_context;
    asio::ip::tcp::resolver resolver(io_context);
    asio::ip::tcp::resolver::results_type endpoints =
      resolver.resolve(argv[1], argv[2]);
    asio::ssl::context ctx(asio::ssl::context::sslv23);
    ctx.load_verify_file("ca.pem");
    client c(io_context, ctx, endpoints);
    io_context.run();
  }
  catch (std::exception& e)
  {
    std::cerr << "Exception: " << e.what() << "\n";
  }
  return 0;
}

#include "jemalloc/internal/jemalloc_preamble.h"
#include "jemalloc/internal/jemalloc_internal_includes.h"
#include "jemalloc/internal/prof_stats.h"
bool opt_prof_stats = false;
malloc_mutex_t prof_stats_mtx;
static prof_stats_t prof_stats_live[PROF_SC_NSIZES];
static prof_stats_t prof_stats_accum[PROF_SC_NSIZES];
static void
prof_stats_enter(tsd_t *tsd, szind_t ind) {
	assert(opt_prof && opt_prof_stats);
	assert(ind < SC_NSIZES);
	malloc_mutex_lock(tsd_tsdn(tsd), &prof_stats_mtx);
}
static void
prof_stats_leave(tsd_t *tsd) {
	malloc_mutex_unlock(tsd_tsdn(tsd), &prof_stats_mtx);
}
void
prof_stats_inc(tsd_t *tsd, szind_t ind, size_t size) {
	cassert(config_prof);
	prof_stats_enter(tsd, ind);
	prof_stats_live[ind].req_sum += size;
	prof_stats_live[ind].count++;
	prof_stats_accum[ind].req_sum += size;
	prof_stats_accum[ind].count++;
	prof_stats_leave(tsd);
}
void
prof_stats_dec(tsd_t *tsd, szind_t ind, size_t size) {
	cassert(config_prof);
	prof_stats_enter(tsd, ind);
	prof_stats_live[ind].req_sum -= size;
	prof_stats_live[ind].count--;
	prof_stats_leave(tsd);
}
void
prof_stats_get_live(tsd_t *tsd, szind_t ind, prof_stats_t *stats) {
	cassert(config_prof);
	prof_stats_enter(tsd, ind);
	memcpy(stats, &prof_stats_live[ind], sizeof(prof_stats_t));
	prof_stats_leave(tsd);
}
void
prof_stats_get_accum(tsd_t *tsd, szind_t ind, prof_stats_t *stats) {
	cassert(config_prof);
	prof_stats_enter(tsd, ind);
	memcpy(stats, &prof_stats_accum[ind], sizeof(prof_stats_t));
	prof_stats_leave(tsd);
}

#include "EventTimer.hpp"
#include <algorithm>
#include <limits>
#include <iostream>
#include "debug.hpp"
//#include "cpu.hpp"
// Constructor implementation
/* EventTimer::EventTimer(cpu_state *cpu) : cpu(cpu) {
} */
// Destructor implementation 
EventTimer::~EventTimer() = default;
inline void EventTimer::updateNextEventCycle() {
    // Update next_event_cycle to the earliest event's trigger time
    next_event_cycle = events.empty() ? std::numeric_limits<uint64_t>::max() : events.front().triggerCycles;
}
// Add a new event to the queue
void EventTimer::scheduleEvent(uint64_t triggerCycles, void (*callback)(uint64_t, void*), uint64_t instanceID, void* userData) {
    if (DEBUG(DEBUG_EVENT_TIMER)) std::cout << "scheduleEvent: " << triggerCycles << " InstanceID: " << instanceID << std::endl;
    if (clock && triggerCycles < clock->get_cycles()) {
        std::cout << "scheduleEvent: Event in the past, skipping" << std::endl;
        return;
    }
    // Check if an event with the same instanceID already exists
    auto existingEvent = std::find_if(events.begin(), events.end(), 
        [instanceID](const Event& event) { return event.instanceID == instanceID; });

    if (existingEvent != events.end()) {
        // Replace the existing event with the new one
        existingEvent->triggerCycles = triggerCycles;
        existingEvent->triggerCallback = callback;
        existingEvent->userData = userData;

        // Rebuild the heap after modifying an element
        std::make_heap(events.begin(), events.end(), [](const Event& a, const Event& b) {
            return a.triggerCycles > b.triggerCycles;
        });
    } else {
        // Add a new event to the queue
        Event newEvent{triggerCycles, callback, instanceID, userData};
        events.push_back(newEvent);
        std::push_heap(events.begin(), events.end(), [](const Event& a, const Event& b) {
            return a.triggerCycles > b.triggerCycles; // Reverse for priority queue (earliest first)
        });
    }
    updateNextEventCycle();
}
// Process all events that should trigger by the given cycle count
void EventTimer::processEvents(uint64_t currentCycles) {
    /* std::cout << "processEvents: " << currentCycles << "Front: " << events.front().triggerCycles << std::endl;
    // Print how many events are on the queue
    if (!events.empty()) {
        std::cout << "Events on queue: " << events.size() << std::endl;
    } */
    while (!events.empty() && events.front().triggerCycles <= currentCycles) {
        Event event = events.front();
        std::pop_heap(events.begin(), events.end(), [](const Event& a, const Event& b) {
            return a.triggerCycles > b.triggerCycles;
        });
        events.pop_back();
        if (DEBUG(DEBUG_EVENT_TIMER)) std::cout << "Processing event: " << event.triggerCycles << " InstanceID: " << event.instanceID << std::endl;
        // Call the callback function
        if (event.triggerCallback) {
            event.triggerCallback(event.instanceID, event.userData);
        }
    }
    updateNextEventCycle();
}
// Cancel all events for a specific instance
void EventTimer::cancelEvents(uint64_t instanceID) {
    auto newEnd = std::remove_if(events.begin(), events.end(),
        [instanceID](const Event& event) { return event.instanceID == instanceID; });

    if (newEnd != events.end()) {
        events.erase(newEnd, events.end());
        // Rebuild the heap after removing elements
        std::make_heap(events.begin(), events.end(), [](const Event& a, const Event& b) {
            return a.triggerCycles > b.triggerCycles;
        });
    }
    updateNextEventCycle();
}
// Check if there are any pending events
bool EventTimer::hasPendingEvents() const {
    return !events.empty();
}
// Get the cycle count of the next event
uint64_t EventTimer::getNextEventCycle() const {
    return next_event_cycle;
}

