#include <algorithm>
/**
 * @brief Sends a query to the judge and returns the response.
 * 
 * @param x The slice number to toggle.
 * @return int The number of distinct mineral kinds in the device.
 */
int query(int x) {
    std::cout << "? " << x << std::endl;
    int r;
    std::cin >> r;
    if (r == -1) exit(0); // Exit if judge reports an error
    return r;
}
/**
 * @brief Announces a found pair to the judge.
 * 
 * @param a The first slice in the pair.
 * @param b The second slice in the pair.
 */
void answer(int a, int b) {
    std::cout << "! " << a << " " << b << std::endl;
}
int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
    int n;
    std::cin >> n;
    std::vector<bool> paired(2 * n + 1, false);
    std::vector<int> unmatched_in_device;
    int current_distinct_kinds = 0;
    for (int i = 1; i <= 2 * n; ++i) {
        if (paired[i]) {
            continue;
        }
        int new_distinct_kinds = query(i);
        if (new_distinct_kinds > current_distinct_kinds) {
            // This is a "starter" slice of a new kind.
            unmatched_in_device.push_back(i);
            current_distinct_kinds = new_distinct_kinds;
        } else { 
            // This is a "finisher" slice. Its pair is in unmatched_in_device.
            int base_kinds_for_search = new_distinct_kinds;

            // Linearly scan unmatched_in_device to find the pair.
            // Scanning from the end is often a good heuristic.
            for (int j = unmatched_in_device.size() - 1; j >= 0; --j) {
                int u = unmatched_in_device[j];
                int test_kinds = query(u);

                if (test_kinds == base_kinds_for_search) {
                    // Found the pair: (i, u).
                    // Removing u did not change the number of kinds, because i has the same kind.
                    answer(i, u);
                    paired[i] = true;
                    paired[u] = true;

                    unmatched_in_device.erase(unmatched_in_device.begin() + j);
                    current_distinct_kinds = test_kinds;
                    break;
                } else {
                    // Not a pair. Put u back into the device to restore the state for the next check.
                    query(u);
                }
            }
        }
    }
    return 0;
}

#include "ReduceFunctionBodies.h"
#include "Delta.h"
#include "Utils.h"
#include "llvm/IR/GlobalValue.h"
#include "llvm/IR/Instructions.h"
using namespace llvm;
/// Removes all the bodies of defined functions that aren't inside any of the
/// desired Chunks.
static void extractFunctionBodiesFromModule(Oracle &O,
                                            ReducerWorkItem &WorkItem) {
  // Delete out-of-chunk function bodies
  for (auto &F : WorkItem.getModule()) {
    if (!F.isDeclaration() && !hasAliasUse(F) && !O.shouldKeep()) {
      F.deleteBody();
      F.setComdat(nullptr);
    }
  }
}
void llvm::reduceFunctionBodiesDeltaPass(TestRunner &Test) {
  runDeltaPass(Test, extractFunctionBodiesFromModule,
               "Reducing Function Bodies");
}
static void reduceFunctionData(Oracle &O, ReducerWorkItem &WorkItem) {
  for (Function &F : WorkItem.getModule()) {
    if (F.hasPersonalityFn()) {
      if (none_of(F,
                  [](const BasicBlock &BB) {
                    return BB.isEHPad() || isa<ResumeInst>(BB.getTerminator());
                  }) &&
          !O.shouldKeep()) {
        F.setPersonalityFn(nullptr);
      }
    }
    if (F.hasPrefixData() && !O.shouldKeep())
      F.setPrefixData(nullptr);
    if (F.hasPrologueData() && !O.shouldKeep())
      F.setPrologueData(nullptr);
  }
}
void llvm::reduceFunctionDataDeltaPass(TestRunner &Test) {
  runDeltaPass(Test, reduceFunctionData, "Reducing Function Data");
}

#include <stdlib.h>
#include <stdio.h>
#include <stdarg.h>
#include "abort_message.h"
#ifdef __BIONIC__
#  include <syslog.h>
extern "C" void android_set_abort_message(const char* msg);
#endif // __BIONIC__
#if defined(__APPLE__) && __has_include(<CrashReporterClient.h>)
#   include <CrashReporterClient.h>
#   define _LIBCXXABI_USE_CRASHREPORTER_CLIENT
#endif
void __abort_message(const char* format, ...)
{
    // Write message to stderr. We do this before formatting into a
    // variable-size buffer so that we still get some information if
    // formatting into the variable-sized buffer fails.
#if !defined(NDEBUG) || !defined(LIBCXXABI_BAREMETAL)
    {
#if defined(__EMSCRIPTEN__) && defined(NDEBUG)
        // Just trap in a non-debug build. These internal libcxxabi assertions are
        // very rare, and it's not worth linking in vfprintf stdio support or
        // even minimal logging for them, as we'll have a proper call stack, which
        // will show a call into "abort_message", and can help debugging. (In a
        // debug build that won't be inlined.)
        abort();
#else
        fprintf(stderr, "libc++abi: ");
        va_list list;
        va_start(list, format);
        vfprintf(stderr, format, list);
        va_end(list);
        fprintf(stderr, "\n");
#endif
    }
#endif
    // Format the arguments into an allocated buffer. We leak the buffer on
    // purpose, since we're about to abort() anyway.
#if defined(_LIBCXXABI_USE_CRASHREPORTER_CLIENT)
    char* buffer;
    va_list list;
    va_start(list, format);
    vasprintf(&buffer, format, list);
    va_end(list);
    CRSetCrashLogMessage(buffer);
#elif defined(__BIONIC__)
    char* buffer;
    va_list list;
    va_start(list, format);
    vasprintf(&buffer, format, list);
    va_end(list);
    // Show error in tombstone.
    android_set_abort_message(buffer);
    // Show error in logcat.
    openlog("libc++abi", 0, 0);
    syslog(LOG_CRIT, "%s", buffer);
    closelog();
#endif // __BIONIC__
    abort();
}

#include <iostream>
#include <vector>
#include <utility>
#include <algorithm>
// Global variables for board size and state
int N;
// Using 1-based indexing for convenience to match problem statement.
// Global arrays are zero-initialized, which works perfectly for 'unvisited'.
int board[667][667]; 
// Knight's move offsets (8 directions, ordered clockwise)
const int dr[] = {-2, -1, 1, 2, 2, 1, -1, -2};
const int dc[] = {1, 2, 2, 1, -1, -2, -2, -1};
// Check if a square (r, c) is on the board and unvisited.
// Inlining can give a minor performance boost.
inline bool isValid(int r, int c) {
    return r >= 1 && r <= N && c >= 1 && c <= N && board[r][c] == 0;
}
// Calculate the number of available moves from a square (Warnsdorff's rule).
// This is the 'degree' of the vertex in the graph of unvisited squares.
int getDegree(int r, int c) {
    int count = 0;
    for (int i = 0; i < 8; ++i) {
        if (isValid(r + dr[i], c + dc[i])) {
            count++;
        }
    }
    return count;
}
int main() {
    // Use fast I/O
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
    int start_r, start_c;
    std::cin >> N >> start_r >> start_c;
    // `path` will store the sequence of visited squares.
    std::vector<std::pair<int, int>> path;

    // Set the starting position.
    int r = start_r;
    int c = start_c;
    // Mark the starting square as visited (step 1).
    board[r][c] = 1;
    path.push_back({r, c});
    // Generate the rest of the path, up to N*N-1 more moves.
    for (int move_count = 2; move_count <= N * N; ++move_count) {
        int next_r = -1;
        int next_c = -1;
        // Max possible degree is 8, so 9 is a safe initial value for min_degree.
        int min_degree = 9;
        // Apply Warnsdorff's rule: find the next move that has the minimum number of onward moves.
        for (int i = 0; i < 8; ++i) {
            int nr = r + dr[i];
            int nc = c + dc[i];
            if (isValid(nr, nc)) {
                int degree = getDegree(nr, nc);
                if (degree < min_degree) {
                    min_degree = degree;
                    next_r = nr;
                    next_c = nc;
                }
            }
        }
        // If next_r is -1, it means we are stuck and cannot make any more moves.
        if (next_r == -1) {
            break; 
        }
        // Make the chosen move.
        r = next_r;
        c = next_c;
        board[r][c] = move_count;
        path.push_back({r, c});
    }
    // Output the length of the path found.
    std::cout << path.size() << "\n";
    // Output the coordinates of each square in the path.
    for (const auto& p : path) {
        std::cout << p.first << " " << p.second << "\n";
    }
    return 0;
}

