#include <iostream>
#include <vector>
#include <string>
using namespace std;
int main() {
    // We construct a "Snake" pattern on the 20x20 grid.
    // This creates a long induced path (Hamiltonian-like path on the tree of empty cells).
    // The length of this path is approximately 210 cells.
    // The random moves (U, D, L, R) will cause the set of kangaroos to behave like a 1D random walk
    // along this path. Moves perpendicular to the current corridor (e.g., U/D in horizontal rows) 
    // are blocked by walls, effectively reducing the number of "active" steps by half.
    // With 50,000 total steps, we have ~25,000 effective steps.
    // The expected range of a random walk with 25,000 steps is around 250.
    // Since our path length (210) is somewhat less than the expected range (250), there is a significant
    // probability (based on the distribution of the range) that the random walk will fail to cover
    // the entire path (and thus fail to synchronize all agents to a single cell) in many test cases.
    // This maximizes the number of failed synchronizations.
    int n = 20;
    int m = 20;

    // Output dimensions
    cout << n << " " << m << endl;
    // Initialize grid with walls ('0')
    vector<string> grid(n, string(m, '0'));
    // Construct the snake pattern
    for (int r = 0; r < n; ++r) {
        if (r % 2 == 0) {
            // Even rows (0, 2, ..., 18) are full horizontal corridors
            for (int c = 0; c < m; ++c) {
                grid[r][c] = '1';
            }
        } else {
            // Odd rows (1, 3, ..., 19) contain a single empty cell to connect the even rows.
            // We alternate the position of this connector to create a winding path.
            // Row 1 connects Row 0 and Row 2 at the Right end.
            // Row 3 connects Row 2 and Row 4 at the Left end.
            // Pattern repeats.
            if (r % 4 == 1) {
                // Connect at the right end (column 19)
                grid[r][m - 1] = '1';
            } else {
                // Connect at the left end (column 0)
                grid[r][0] = '1';
            }
        }
    }
    // Print the map
    for (int i = 0; i < n; ++i) {
        cout << grid[i] << endl;
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <stack>
using namespace std;
// LeetCode 210: Course Schedule II
// This problem requires us to return the order of courses to finish all courses given the prerequisites.
// We will use DFS to perform a topological sort on the directed graph formed by the courses and their prerequisites.
class Solution {
public:
      // Cycle Detection Utility Function
      bool isCyclicUtil(int src, vector<bool>& visited, vector<bool>& recStack, const vector<vector<int>>& edges) {
        visited[src] = true;
        recStack[src] = true;

        // we want to find the correct neighbors from the edges list
        for (int i = 0; i < edges.size(); i++) {
            int v = edges[i][0];
            int u = edges[i][1];

            // If the current edge starts from the source node
            if (u == src) {
                if (!visited[v]) {
                    if (isCyclicUtil(v, visited, recStack, edges)) {
                        return true; // Cycle detected
                    }
                } else if (recStack[v]) {
                    return true; // Cycle detected(back edge)
                }
            }
        }
        recStack[src] = false; // Remove the vertex from recursion stack
        return false;
    }

    // Topological Sort Utility Function
    void topologicalSortUtil(int v, vector<bool>& visited, stack<int>& Stack, const vector<vector<int>>& edges) {
        visited[v] = true;
        for (int i = 0; i < edges.size(); i++) {
            int neigh = edges[i][0];
            int u = edges[i][1];
            if (u == v && !visited[neigh]) {
                topologicalSortUtil(neigh, visited, Stack, edges);
            }
        }
        Stack.push(v);
    }
    vector<int> findOrder(int numCourses, vector<vector<int>>& prerequisites) {
        vector<bool> visited(numCourses, false);
        vector<bool> recStack(numCourses, false);
        // First, check for cycles in the graph
        for(int i = 0; i < numCourses; i++) {
            if (!visited[i]) {
                if (isCyclicUtil(i, visited, recStack, prerequisites)) {
                    return {}; // Cycle detected, cannot finish all courses, return empty list
                }
            }
        }
        // If no cycles, perform topological sort
        visited.assign(numCourses, false);  // Reset visited for topological sort
        stack<int> Stack;   // Stack to store the topological order in reverse
        vector<int> result;

        // Perform DFS for topological sorting for each unvisited node
        for (int i = 0; i < numCourses; i++) {
            if (!visited[i]) {
                topologicalSortUtil(i, visited, Stack, prerequisites);
            }
        }

        // Populating result from stack in reverse order
        while (!Stack.empty()) {
            result.push_back(Stack.top());
            Stack.pop();
        }
        return result;  
    }
};

#include <RegexPayloadProcessorHTTP.h>
#include <spdlog/spdlog.h>
void RegexPayloadProcessorHTTP::Process(http::request<http::string_body> const& req, tcp::socket& sock) {
    http::response<http::string_body> res;
    res.version(req.version());
    res.keep_alive(req.keep_alive());
    res.result(http::status::ok);
    res.set(http::field::content_type, "application/json; charset=UTF-8");
    res.set(http::field::vary, "Origin");
    for (const auto& [regex, payload] : m_resMap) {
        if (std::regex_search(req.body(), regex.m_rx)) {
            res.body() = payload->dump();
            res.prepare_payload();
            http::write(sock, res);
            return;
        }
    }
    spdlog::error("Regex processor {} failed to find any valid response for the packet, dropping the packet.\nPacket contents: {}", GetRoute(), req.body());
}

#include <iostream>
