{
    long this_delta;  // delta to this pointer
    long vtbl_offset; // offset in vtable (-1: not a virtual function)
    union
    {
        void* func_addr;    // nonvirtual function address
        long ventry_offset; // of virtual function entry in vtable
    } func_data;
