  lwz r7, PTMF.func_data(ptmf)
  li r3, 1
  cmpwi cr0, r5, 0
  cmpwi cr6, r6, 0
  cmpwi cr7, r7, 0
  bnelr cr0
  bnelr cr6
  bnelr cr7
  li r3, 0
  blr
