#include "ReduceFunctions.h"
#include "Delta.h"
#include "Utils.h"
#include "llvm/ADT/STLExtras.h"
#include "llvm/Transforms/Utils/ModuleUtils.h"
#include <iterator>
using namespace llvm;
/// Removes all the Defined Functions
/// that aren't inside any of the desired Chunks.
static void extractFunctionsFromModule(Oracle &O, ReducerWorkItem &WorkItem) {
  Module &Program = WorkItem.getModule();
  // Record all out-of-chunk functions.
  SmallPtrSet<Constant *, 8> FuncsToRemove;
  for (Function &F : Program.functions()) {
    // Intrinsics don't have function bodies that are useful to
    // reduce. Additionally, intrinsics may have additional operand
    // constraints. But, do drop intrinsics that are not referenced.
    if ((!F.isIntrinsic() || F.use_empty()) && !hasAliasOrBlockAddressUse(F) &&
        !O.shouldKeep())
      FuncsToRemove.insert(&F);
  }
  removeFromUsedLists(Program, [&FuncsToRemove](Constant *C) {
    return FuncsToRemove.count(C);
  });
  // Then, drop body of each of them. We want to batch this and do nothing else
  // here so that minimal number of remaining exteranal uses will remain.
  for (Constant *F : FuncsToRemove)
    F->dropAllReferences();
  // And finally, we can actually delete them.
  for (Constant *F : FuncsToRemove) {
    // Replace all *still* remaining uses with the default value.
    F->replaceAllUsesWith(getDefaultValue(F->getType()));
    // And finally, fully drop it.
    cast<Function>(F)->eraseFromParent();
  }
}
void llvm::reduceFunctionsDeltaPass(TestRunner &Test) {
  runDeltaPass(Test, extractFunctionsFromModule, "Reducing Functions");
}

#include "Alias/TPA/Context/Context.h"
#include "Alias/TPA/Context/ProgramPoint.h"
using namespace llvm;
namespace context {
// Pushes a new context frame onto the current context stack.
// This version takes a ProgramPoint, extracting the context and instruction from it.
const Context *Context::pushContext(const ProgramPoint &pp) {
  return pushContext(pp.getContext(), pp.getInstruction());
}
// Pushes a new context frame.
// Parameters:
//   ctx - The current (caller's) context.
//   inst - The call instruction (call site) invoking the function.
// Returns: A pointer to the unique interned Context object representing the new state.
const Context *Context::pushContext(const Context *ctx,
                                    const Instruction *inst) {
  // Create a temporary context object
  auto newCtx = Context(inst, ctx);
  // Insert into the set. If it exists, 'itr' points to the existing one.
  // If not, it points to the newly inserted one.
  auto itr = ctxSet.insert(newCtx).first;
  return &(*itr);
}
// Pops the most recent context frame.
// Returns the predecessor context (the caller's context).
const Context *Context::popContext(const Context *ctx) {
  assert(ctx->sz != 0 && "Trying to pop an empty context");
  return ctx->predContext;
}
// Retrieves the singleton Global Context.
// Used for global variables and the entry point of the analysis.
const Context *Context::getGlobalContext() {
  auto itr = ctxSet.insert(Context()).first;
  return &(*itr);
}
// Helper to retrieve all created contexts.
// Useful for debugging or statistics.
std::vector<const Context *> Context::getAllContexts() {
  std::vector<const Context *> ret;
  ret.reserve(ctxSet.size());
  for (auto const &ctx : ctxSet)
    ret.push_back(&ctx);
  return ret;
}
} // namespace context

class Solution {
public:
    int findContentChildren(vector<int>& g, vector<int>& s) {
        int n1=g.size();
        int n2=s.size();
        sort(g.begin(),g.end());
        sort(s.begin(),s.end());
        int i=0;
        int j=0;
        int count=0;
        while(i<n1 && j<n2){
            if(g[i]<=s[j]){
                count++;
                i++;
                j++;
            }
            else{
                j++;
            }
        }
        return count;      
    }
};

#include "Tokenizer.h"
#include "../String.h"
namespace Gorgon :: String {

	const Tokenizer Tokenizer::endit;
	std::string FixLineEndings(const std::string &in, LineEnding type) {
		if(type == LineEnding::Mixed) return in;
		std::string ret;
		ret.reserve(in.length());
		for(auto it = in.begin(); it!=in.end(); ++it) {
			if(*it == '\x0d') {
				//check for lf
				++it;
				if(it!=in.end()) {
					//if lf is not there, dont skip the next char
					if(*it!='\x0a') --it; 
				}
				if((int)type&(int)LineEnding::CR)
					ret.push_back('\x0d');
				if((int)type&(int)LineEnding::LF)
					ret.push_back('\x0a');
			}
			else if(*it >= '\x0a' && *it <= '\x0c') {
				if((int)type&(int)LineEnding::CR)
					ret.push_back('\x0d');
				if((int)type&(int)LineEnding::LF)
					ret.push_back('\x0a');
			}
			else {
				ret.push_back(*it);
			}
		}
		return ret;
	}

}

#include "comms/torchcomms/ncclx/TorchWorkNCCLX.hpp"
namespace torch::comms {
TorchWorkNCCLX::WorkStatus TorchWorkNCCLXQueue::garbageCollectLocked() {
  TorchWorkNCCLX::WorkStatus last_status =
      TorchWorkNCCLX::WorkStatus::COMPLETED;
  // Keep popping completed elements until we hit an in-progress element
  // or the queue is empty
  // Use an iterator to safely remove empty queues while iterating
  auto it = stream_work_queues_.begin();
  while (it != stream_work_queues_.end()) {
    auto& work_queue = it->second;
    while (!work_queue.empty()) {
      // Get the first work object in the queue
      auto work = work_queue.front();
      // Use the checkStatus function to determine the work status
      TorchWorkNCCLX::WorkStatus status = work->checkStatus();
      last_status = status;
      if (status == TorchWorkNCCLX::WorkStatus::COMPLETED) {
        // Work is completed, remove it from the work queue
        work_queue.pop();
        // Continue to the next element in the queue
      } else if (
          status == TorchWorkNCCLX::WorkStatus::TIMEDOUT ||
          status == TorchWorkNCCLX::WorkStatus::ERROR) {
        // Return the error status immediately
        return status;
      } else {
        // NOT_STARTED or INPROGRESS - stop processing this queue
        break;
      }
    }
    // If the queue is now empty, remove it from the map
    if (work_queue.empty()) {
      it = stream_work_queues_.erase(it);
    } else {
      ++it;
    }
  }
  return last_status;
}
// Thread-safety: This method is called from the timeout watchdog thread while
// the main thread may be enqueuing work via enqueueWork(). The
// work_queues_mutex_ ensures proper synchronization - both garbageCollect() and
// enqueueWork() acquire the mutex before accessing stream_work_queues_.
TorchWorkNCCLX::WorkStatus TorchWorkNCCLXQueue::garbageCollect() {
  std::lock_guard<std::mutex> lock(work_queues_mutex_);
  return garbageCollectLocked();
}
TorchWorkNCCLX::WorkStatus TorchWorkNCCLXQueue::finalize() {
  // Because this function is typically called after the timeout thread has
  // already joined, we might not need to lock here.  But doing the lock anyway,
  // as defensive programming, just in case someone moves the thread join order
  // later.  The cost of the lock itself should be small on modern linux systems
  // (uncontended locks are typically just an atomic operation).
  std::lock_guard<std::mutex> lock(work_queues_mutex_);
  // Initialize the status to COMPLETED to cover the case where the queue is
  // empty
  TorchWorkNCCLX::WorkStatus status = TorchWorkNCCLX::WorkStatus::COMPLETED;
  while (!stream_work_queues_.empty()) {
    status = garbageCollectLocked();
    if (status == TorchWorkNCCLX::WorkStatus::ERROR ||
        status == TorchWorkNCCLX::WorkStatus::TIMEDOUT ||
        status == TorchWorkNCCLX::WorkStatus::COMPLETED) {
      break;
    }
  }
  // Clear all work queues & completed work queue.
  //
  // NOTE: finalize MUST return without holding references to any work object,
  // otherwise it may leak object and cause side effects.
  stream_work_queues_.clear();
  return status;
}
void TorchWorkNCCLXQueue::enqueueWork(
    c10::intrusive_ptr<TorchWorkNCCLX> work,
    cudaStream_t stream) {
  // Add work to stream's queue after events have been recorded
  std::lock_guard<std::mutex> lock(work_queues_mutex_);
  stream_work_queues_[stream].push(std::move(work));
}
} // namespace torch::comms

#include <iostream>
int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
    // Phase 1: Setup.
    // The input string is sSt.
    // First, change S to Q and create a backup of t, separated by #.
    // The backup t will use alphabet {X, Y, Z}.
    std::cout << "S=Q#" << std::endl;
    std::cout << "#a=a#X" << std::endl;
    std::cout << "#b=b#Y" << std::endl;
    std::cout << "#c=c#Z" << std::endl;
    // After these, string is `s Q t # t_XYZ`.
    // Now, introduce a marker `P` at the very beginning of s.
    std::cout << "a=Da" << std::endl;
    std::cout << "b=Db" << std::endl;
    std::cout << "c=Dc" << std::endl;
    std::cout << "D=P" << std::endl;
    // Now string is `P s Q t # t_XYZ`. P is the sliding window pointer.
    // Phase 2: Main loop.
    // At each position of P, try to match.
    // Start match: P becomes M.
    std::cout << "P=M" << std::endl;
    // Matching rules:
    std::cout << "MaQa=M" << std::endl;
    std::cout << "MbQb=M" << std::endl;
    std::cout << "McQc=M" << std::endl;

    // Success: M has consumed all of t.
    std::cout << "MQ#=(return)1" << std::endl;

    // Mismatch rules:
    std::cout << "MaQb=F" << std::endl;
    std::cout << "MaQc=F" << std::endl;
    std::cout << "MbQa=F" << std::endl;
    std::cout << "MbQc=F" << std::endl;
    std::cout << "McQa=F" << std::endl;
    std::cout << "McQb=F" << std::endl;

    // Mismatch recovery:
    // F will clean up the partially consumed t and s, then restore t and advance P.
    // `s_done M s_rem_match F s_rem_rest Q t_rem # t_XYZ`
    std::cout << "aF=Fa" << std::endl;
    std::cout << "bF=Fb" << std::endl;
    std::cout << "cF=Fc" << std::endl;
    std::cout << "MF=FM" << std::endl; // Move F past the original M position.

    // Once F is at the beginning of where s_rem was:
    // `s_done F M s_rem ...` -> advance `P`'s logical position.
    // `FM=P`. This effectively removes one char from s and restarts search.
    std::cout << "FM=P" << std::endl;

    // Reset `t`. When `P` is set, `t` needs to be restored.
    std::cout << "PaQ=PaR" << std::endl;
    std::cout << "PbQ=PbR" << std::endl;
    std::cout << "PcQ=PcR" << std::endl;
    std::cout << "P#=P_R" << std::endl; // Also for case when t is empty

    // R (restore) state.
    std::cout << "Ra=R" << std::endl;
    std::cout << "Rb=R" << std::endl;
    std::cout << "Rc=R" << std::endl;
    std::cout << "R#=T" << std::endl;

    // T copies from backup.
    std::cout << "TX=aT" << std::endl;
    std::cout << "TY=bT" << std::endl;
    std::cout << "TZ=cT" << std::endl;

    // When T is done, it becomes Q again.
    // Need to handle end of backup string.
    std::cout << "aT=aQ" << std::endl;
    std::cout << "bT=bQ" << std::endl;
    std::cout << "cT=cQ" << std::endl;
    std::cout << "T=Q" << std::endl;

    // Termination: P has scanned the entire string s.
    std::cout << "PQ=(return)0" << std::endl;
    return 0;
}

#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <map>
// Using a map for memoization for queried cell values.
std::map<std::pair<int, int>, long long> memo;
long long n_val;
// Function to perform a query and cache the result.
long long do_query(int r, int c) {
    if (memo.count({r, c})) {
        return memo[{r, c}];
    }
    std::cout << "QUERY " << r << " " << c << std::endl;
    long long v;
    std::cin >> v;
    if (std::cin.fail()) {
        // In case of an error from the judge or unexpected termination.
        exit(0);
    }
    return memo[{r, c}] = v;
}
// Counts the number of elements in the matrix less than or equal to `val`.
// This uses a "staircase" search pattern, making at most 2n new queries.
long long count_le(long long val) {
    long long count = 0;
    int c = n_val;
    for (int r = 1; r <= n_val; ++r) {
        while (c > 0 && do_query(r, c) > val) {
            c--;
        }
        count += c;
    }
    return count;
}
int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
    long long k_val;
    std::cin >> n_val >> k_val;
    long long lo, hi;
    if (n_val > 0) {
        // Initialize search range with min and max possible values.
        lo = do_query(1, 1);
        hi = do_query(n_val, n_val);
    } else {
        // Edge case for n=0, though constraints likely prevent this.
        std::cout << "DONE " << 0 << std::endl;
        return 0;
    }
    long long ans = hi;
    // Binary search for the k-th smallest value.
    while (lo <= hi) {
        long long mid = lo + (hi - lo) / 2;

        if (count_le(mid) >= k_val) {
            ans = mid;
            hi = mid - 1;
        } else {
            lo = mid + 1;
        }
    }
    std::cout << "DONE " << ans << std::endl;
    return 0;
}

