// Creates a new byte array output stream. The buffer capacity is initially 32
// bytes, though its size increases if necessary.
ByteArrayOutputStream::ByteArrayOutputStream() {
    count = 0;
    buf   = byteArray(32);
}
// Creates a new byte array output stream, with a buffer capacity of the
// specified size, in bytes. Parameters: size - the initial size.
ByteArrayOutputStream::ByteArrayOutputStream(unsigned int size) {
    count = 0;
    buf   = byteArray(size);
}
ByteArrayOutputStream::~ByteArrayOutputStream() {
    if (buf.data != NULL) delete[] buf.data;
}
// Writes the specified byte to this byte array output stream.
// Parameters:
// b - the byte to be written.
void ByteArrayOutputStream::write(unsigned int b) {
    // If we will fill the buffer we need to make it bigger
    if (count + 1 >= buf.length) buf.resize(buf.length * 2);
    buf[count] = (byte)b;
    count++;
}
// Writes b.length bytes from the specified byte array to this output stream.
// The general contract for write(b) is that it should have exactly the same
// effect as the call write(b, 0, b.length).
void ByteArrayOutputStream::write(byteArray b) { write(b, 0, b.length); }
// Writes len bytes from the specified byte array starting at offset off to this
// byte array output stream. Parameters: b - the data. off - the start offset in
// the data. len - the number of bytes to write.
void ByteArrayOutputStream::write(
    byteArray    b,
    unsigned int offset,
    unsigned int length
) {
    assert(b.length >= offset + length);
    // If we will fill the buffer we need to make it bigger
    if (count + length >= buf.length)
        buf.resize(std::max(count + length + 1, buf.length * 2));
    XMemCpy(&buf[count], &b[offset], length);
    // std::copy( b->data+offset, b->data+offset+length, buf->data + count ); //
    // Or this instead?
    count += length;
}
// Closing a ByteArrayOutputStream has no effect.
// The methods in this class can be called after the stream has been closed
// without generating an IOException.
void ByteArrayOutputStream::close() {}
// Creates a newly allocated byte array. Its size is the current size of this
// output stream and the valid contents of the buffer have been copied into it.
// Returns:
// the current contents of this output stream, as a byte array.
byteArray ByteArrayOutputStream::toByteArray() {
    byteArray out(count);
    memcpy(out.data, buf.data, count);
    return out;
}

#include <sm/vvec>
#include <mplot/Visual.h>
#include <mplot/GraphVisual.h>
#include <mplot/unicode.h>
// Make an equation string for the legend
std::string make_legend_str (double k, double x0)
{
    // We'll use mathplot's awesome unicode chars for the subscript 0 on x0
    namespace uc = mplot::unicode;
    std::stringstream ktxt;
    if (k != 1.0) { ktxt << k; }
    std::stringstream brtxt;
    std::stringstream ostxt;
    if (x0 != 0.0) {
        brtxt << "(";
        if (x0 > 0.0) {
            ostxt << " - " << x0 <<")";
        } else {
            ostxt << " + " << -x0 <<")";
        }
    }
    std::stringstream eqn;
    eqn << "k="<<k<<", x" << uc::toUtf8(uc::subs0) << "=" << x0;
    eqn << ": f(x) = 1 / [1 + exp (-"<< ktxt.str() << brtxt.str() << "x" << ostxt.str() << ")]";
    return eqn.str();
}
int main()
{
    // Set up a mplot::Visual 'scene environment'.
    mplot::Visual v(1024, 768, "Logistic functions");
    // Create a GraphVisual object (obtaining a unique_ptr to the object) with a spatial offset within the scene of 0,0,0
    auto gv = std::make_unique<mplot::GraphVisual<double>> (sm::vec<float>({-0.5f,-0.5f,0.0f}));
    v.bindmodel (gv);
    // Data for the x axis. A vvec is like std::vector, but with built-in maths methods
    sm::vvec<double> x;
    // This works like numpy's linspace() (the 3 args are "start", "end" and "num"):
    x.linspace (-100, 30, 200);
    // Logistic functions. Args are parameters to the function: (k, x0)
    // vvec::logistic() returns a new vvec with the logistic function-transformed values:
    gv->setdata (x, x.logistic(0.1, -10), make_legend_str (0.1, -10));
    // For this one, demonstrate use of logistic_inplace():
    sm::vvec<double> xlogistic = x;
    xlogistic.logistic_inplace(0.25, -5);
    gv->setdata (x, xlogistic, make_legend_str (0.25, -5));
    gv->setdata (x, x.logistic(0.5, 0), make_legend_str (0.5, 0));
    gv->setdata (x, x.logistic(1, 5), make_legend_str (1, 5));
    gv->setdata (x, x.logistic(2, 10), make_legend_str (2, 10));
    // finalize() makes the GraphVisual compute the vertices of the OpenGL model
    gv->finalize();
    // Add the GraphVisual OpenGL model to the Visual scene, transferring ownership of the unique_ptr
    v.addVisualModel (gv);
    // Render the scene on the screen until user quits with 'Ctrl-q'
    v.keepOpen();
    return 0;
}

