#include <iostream>
#include <vector>
#include <string>
#include <numeric>
#include <algorithm>
// Function to print a query for a given set S
void ask_query(const std::vector<int>& s) {
    std::cout << "? " << s.size();
    for (int x : s) {
        std::cout << " " << x;
    }
    std::cout << std::endl;
}
// Function to print a guess
void make_guess(int g) {
    std::cout << "! " << g << std::endl;
}
int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
    int n;
    std::cin >> n;
    // P: set of candidates assuming the last answer was true
    // Q: set of candidates assuming the last answer was false
    std::vector<int> p(n);
    std::iota(p.begin(), p.end(), 1);
    std::vector<int> q;
    // We can solve for x if the total number of candidates is at most 2, using our 2 guesses.
    // The loop reduces the candidate sets until they are small enough.
    while (p.size() + q.size() > 2) {
        // Split P and Q into two halves to construct the query set S.
        size_t pA_size = p.size() / 2;
        size_t qA_size = q.size() / 2;

        std::vector<int> s;
        // The query set S is formed by taking the first half of P and the first half of Q.
        if (pA_size > 0) {
            s.insert(s.end(), p.begin(), p.begin() + pA_size);
        }
        if (qA_size > 0) {
            s.insert(s.end(), q.begin(), q.begin() + qA_size);
        }

        // The loop condition |P|+|Q| > 2 ensures S will be non-empty.
        ask_query(s);
        std::string response;
        std::cin >> response;
        // Create the partitions of P and Q to be used for constructing the next state.
        std::vector<int> pA(p.begin(), p.begin() + pA_size);
        std::vector<int> pB(p.begin() + pA_size, p.end());
        std::vector<int> qA(q.begin(), q.begin() + qA_size);
        std::vector<int> qB(q.begin() + qA_size, q.end());

        std::vector<int> next_p, next_q;
        if (response == "YES") {
            // New P: candidates from old P and Q that are in S.
            next_p.reserve(pA.size() + qA.size());
            next_p.insert(next_p.end(), pA.begin(), pA.end());
            next_p.insert(next_p.end(), qA.begin(), qA.end());
            // New Q: candidates from old P that are NOT in S.
            next_q = pB;
        } else { // NO
            // New P: candidates from old P and Q NOT in S.
            next_p.reserve(pB.size() + qB.size());
            next_p.insert(next_p.end(), pB.begin(), pB.end());
            next_p.insert(next_p.end(), qB.begin(), qB.end());
            // New Q: candidates from old P that ARE in S.
            next_q = pA;
        }
        p = std::move(next_p);
        q = std::move(next_q);
    }
    // Once the total number of candidates is 2 or less, make guesses.
    std::vector<int> final_candidates;
    final_candidates.insert(final_candidates.end(), p.begin(), p.end());
    final_candidates.insert(final_candidates.end(), q.begin(), q.end());

    for (int candidate : final_candidates) {
        make_guess(candidate);
        std::string response;
        std::cin >> response;
        if (response == ":)") {
            return 0;
        }
    }
    return 0;
}

#include "llvm/Transforms/IPO/ElimAvailExtern.h"
#include "llvm/ADT/STLExtras.h"
#include "llvm/ADT/Statistic.h"
#include "llvm/IR/Constant.h"
#include "llvm/IR/DebugInfoMetadata.h"
#include "llvm/IR/Function.h"
#include "llvm/IR/GlobalValue.h"
#include "llvm/IR/GlobalVariable.h"
#include "llvm/IR/MDBuilder.h"
#include "llvm/IR/Module.h"
#include "llvm/Support/CommandLine.h"
#include "llvm/Transforms/IPO.h"
#include "llvm/Transforms/Utils/GlobalStatus.h"
#include "llvm/Transforms/Utils/ModuleUtils.h"
using namespace llvm;
#define DEBUG_TYPE "elim-avail-extern"
cl::opt<bool> ConvertToLocal(
    "avail-extern-to-local", cl::Hidden,
    cl::desc("Convert available_externally into locals, renaming them "
             "to avoid link-time clashes."));
STATISTIC(NumRemovals, "Number of functions removed");
STATISTIC(NumConversions, "Number of functions converted");
STATISTIC(NumVariables, "Number of global variables removed");
void deleteFunction(Function &F) {
  // This will set the linkage to external
  F.deleteBody();
  ++NumRemovals;
}
/// Create a copy of the thinlto import, mark it local, and redirect direct
/// calls to the copy. Only direct calls are replaced, so that e.g. indirect
/// call function pointer tests would use the global identity of the function.
///
/// Currently, Value Profiling ("VP") MD_prof data isn't updated to refer to the
/// clone's GUID (which will be different, because the name and linkage is
/// different), under the assumption that the last consumer of this data is
/// upstream the pipeline (e.g. ICP).
static void convertToLocalCopy(Module &M, Function &F) {
  assert(F.hasAvailableExternallyLinkage());
  assert(!F.isDeclaration());
  // If we can't find a single use that's a call, just delete the function.
  if (F.uses().end() == llvm::find_if(F.uses(), [&](Use &U) {
        return isa<CallBase>(U.getUser());
      }))
    return deleteFunction(F);
  auto OrigName = F.getName().str();
  // Build a new name. We still need the old name (see below).
  // We could just rely on internal linking allowing 2 modules have internal
  // functions with the same name, but that just creates more trouble than
  // necessary e.g. distinguishing profiles or debugging. Instead, we append the
  // module identifier.
  auto NewName = OrigName + ".__uniq" + getUniqueModuleId(&M);
  F.setName(NewName);
  if (auto *SP = F.getSubprogram())
    SP->replaceLinkageName(MDString::get(F.getParent()->getContext(), NewName));
  F.setLinkage(GlobalValue::InternalLinkage);
  // Now make a declaration for the old name. We'll use it if there are non-call
  // uses. For those, it would be incorrect to replace them with the local copy:
  // for example, one such use could be taking the address of the function and
  // passing it to an external function, which, in turn, might compare the
  // function pointer to the original (non-local) function pointer, e.g. as part
  // of indirect call promotion.
  auto *Decl =
      Function::Create(F.getFunctionType(), GlobalValue::ExternalLinkage,
                       F.getAddressSpace(), OrigName, F.getParent());
  F.replaceUsesWithIf(Decl,
                      [&](Use &U) { return !isa<CallBase>(U.getUser()); });
  ++NumConversions;
}
static bool eliminateAvailableExternally(Module &M) {
  bool Changed = false;
  // Drop initializers of available externally global variables.
  for (GlobalVariable &GV : M.globals()) {
    if (!GV.hasAvailableExternallyLinkage())
      continue;
    if (GV.hasInitializer()) {
      Constant *Init = GV.getInitializer();
      GV.setInitializer(nullptr);
      if (isSafeToDestroyConstant(Init))
        Init->destroyConstant();
    }
    GV.removeDeadConstantUsers();
    GV.setLinkage(GlobalValue::ExternalLinkage);
    ++NumVariables;
    Changed = true;
  }
  // Drop the bodies of available externally functions.
  for (Function &F : llvm::make_early_inc_range(M)) {
    if (F.isDeclaration() || !F.hasAvailableExternallyLinkage())
      continue;
    if (ConvertToLocal)
      convertToLocalCopy(M, F);
    else
      deleteFunction(F);
    F.removeDeadConstantUsers();
    Changed = true;
  }
  return Changed;
}
PreservedAnalyses
EliminateAvailableExternallyPass::run(Module &M, ModuleAnalysisManager &) {
  if (!eliminateAvailableExternally(M))
    return PreservedAnalyses::all();
  return PreservedAnalyses::none();
}

