  EXPECT_TRUE(remove_prefix(ref, "prefix_"));
  EXPECT_EQ(ref, "value");
  std::string other = "value";
  StringRef ref2(other);
  EXPECT_FALSE(remove_prefix(ref2, "prefix_"));
  EXPECT_EQ(ref2, "value");
}
