  std::string out;
  llvm::raw_string_ostream os(out);
  draw_separate_line(os, 5, '*', false);
  os.flush();
  EXPECT_EQ(out, "*****");
  std::string out_with_newline;
  llvm::raw_string_ostream os2(out_with_newline);
  draw_separate_line(os2, 3, '-', true);
  os2.flush();
  EXPECT_EQ(out_with_newline, "---\n");
}
