  std::string out;
  llvm::raw_string_ostream os(out);
  output_padded_text(os, "hi", 10, '-', false);
  os.flush();
  EXPECT_EQ(out, "----hi----");
  std::string no_padding;
  llvm::raw_string_ostream os2(no_padding);
  output_padded_text(os2, "abcdef", 3, '.', false);
  os2.flush();
  EXPECT_EQ(no_padding, "abcdef\n");
}
