  EXPECT_STREQ(ordinal_suffix(2), "nd");
  EXPECT_STREQ(ordinal_suffix(3), "rd");
  EXPECT_STREQ(ordinal_suffix(4), "th");
  EXPECT_STREQ(ordinal_suffix(11), "th");
  EXPECT_STREQ(ordinal_suffix(12), "th");
  EXPECT_STREQ(ordinal_suffix(13), "th");
