#include <iostream>
#include "sophus/geometry.hpp"
int main() {
  // The following demonstrates the group multiplication of rotation matrices
  // Create rotation matrices from rotations around the x and y and z axes:
  const double kPi = Sophus::Constants<double>::pi();
  Sophus::SO3d R1 = Sophus::SO3d::rotX(kPi / 4);
  Sophus::SO3d R2 = Sophus::SO3d::rotY(kPi / 6);
  Sophus::SO3d R3 = Sophus::SO3d::rotZ(-kPi / 3);
  std::cout << "The rotation matrices are" << std::endl;
  std::cout << "R1:\n" << R1.matrix() << std::endl;
  std::cout << "R2:\n" << R2.matrix() << std::endl;
  std::cout << "R3:\n" << R3.matrix() << std::endl;
  std::cout << "Their product R1*R2*R3:\n"
            << (R1 * R2 * R3).matrix() << std::endl;
  std::cout << std::endl;
  // Rotation matrices can act on vectors
  Eigen::Vector3d x;
  x << 0.0, 0.0, 1.0;
  std::cout << "Rotation matrices can act on vectors" << std::endl;
  std::cout << "x\n" << x << std::endl;
  std::cout << "R2*x\n" << R2 * x << std::endl;
  std::cout << "R1*(R2*x)\n" << R1 * (R2 * x) << std::endl;
  std::cout << "(R1*R2)*x\n" << (R1 * R2) * x << std::endl;
  std::cout << std::endl;
  // SO(3) are internally represented as unit quaternions.
  std::cout << "R1 in matrix form:\n" << R1.matrix() << std::endl;
  std::cout << "R1 in unit quaternion form:\n"
            << R1.unit_quaternion().coeffs() << std::endl;
  // Note that the order of coefficients of Eigen's quaternion class is
  // (imag0, imag1, imag2, real)
  std::cout << std::endl;
}

namespace engine::store::filter::filesys::filesys {
//-----------------------------------------------------------------
// Register the filesys protocol config with the Url system. This
// allows call Url::toPath(...), Url::toUrl(...), etc. Note that
// we only provide the osPath since the service manager will
// register generic toPath, toUrl and capabilities
//-----------------------------------------------------------------
static url::UrlConfig urlConfig{
    {//------------------------------------------------------------
     /// @details
     ///	Define the protocol type
     //------------------------------------------------------------
     .protocol = Type,
     //-------------------------------------------------------------
     /// @details
     ///		This function will convert a path, with the prefix
     ///		removed, to a fully qualified path that can be sent
     ///		to the OS.
     ///
     ///		For Linux:
     ///			path: ("usr", "dir", "file.txt")
     ///			ouputs: /usr/dir/file
     ///
     ///		For Windows:
     ///			path: ("C:", "dir", "file.txt")
     ///			ouputs: //./C:/dir/file.txt
     ///
     ///	@param[in] fromUrl
     ///		The url
     ///	@param[out]	osPath
     ///		Receives the text representation of the path
     ///	@returns
     ///		Error
     //------------------------------------------------------------
     .osPath = [](const Url &fromUrl, Text &toPath) -> Error {
         // Get the path
         Path fromPath;
         if (auto ccode = urlConfig.toPath(fromUrl, fromPath)) return ccode;
#ifdef ROCKETRIDE_PLAT_WIN
         // For Windows, we can just use the plat function for now
         toPath = fromPath.plat();
#else
         // For Linux, the path comes from a url, so it does not contain
         // the leading /. For example, filesys://FileSystem/dir/file.txt
         // the path passed will be dir/file.txt. This is okay for Windows
         // since the first component is the drive letter, but for Linux
         // we must add the leading /
         if (!fromPath.isAbsolute())
             toPath = "/" + fromPath.plat();
         else
             toPath = fromPath.plat();
#endif
         return {};
     }}};
}  // namespace engine::store::filter::filesys::filesys

