template<class BufferSequence>
class consumer_param : public consumer<
    is_mutable_buffer_sequence_v<BufferSequence>>
{
    BufferSequence bs_;
    decltype(begin(bs_)) it_;
    decltype(end(bs_)) end_;
public:
