#include <cstdlib>
#include <iostream>
#include <memory>
#include <utility>
#include <asio/ts/buffer.hpp>
#include <asio/ts/internet.hpp>
using asio::ip::tcp;
class session
  : public std::enable_shared_from_this<session>
{
public:
  session(tcp::socket socket)
    : socket_(std::move(socket))
  {
  }
  void start()
  {
    do_read();
  }
private:
  void do_read()
  {
    auto self(shared_from_this());
    socket_.async_read_some(asio::buffer(data_, max_length),
        [this, self](std::error_code ec, std::size_t length)
        {
          if (!ec)
          {
            do_write(length);
          }
        });
  }
  void do_write(std::size_t length)
  {
    auto self(shared_from_this());
    asio::async_write(socket_, asio::buffer(data_, length),
        [this, self](std::error_code ec, std::size_t /*length*/)
        {
          if (!ec)
          {
            do_read();
          }
        });
  }
  tcp::socket socket_;
  enum { max_length = 1024 };
  char data_[max_length];
};
class server
{
public:
  server(asio::io_context& io_context, short port)
    : acceptor_(io_context, tcp::endpoint(tcp::v4(), port)),
      socket_(io_context)
  {
    do_accept();
  }
private:
  void do_accept()
  {
    acceptor_.async_accept(socket_,
        [this](std::error_code ec)
        {
          if (!ec)
          {
            std::make_shared<session>(std::move(socket_))->start();
          }
          do_accept();
        });
  }
  tcp::acceptor acceptor_;
  tcp::socket socket_;
};
int main(int argc, char* argv[])
{
  try
  {
    if (argc != 2)
    {
      std::cerr << "Usage: async_tcp_echo_server <port>\n";
      return 1;
    }
    asio::io_context io_context;
    server s(io_context, std::atoi(argv[1]));
    io_context.run();
  }
  catch (std::exception& e)
  {
    std::cerr << "Exception: " << e.what() << "\n";
  }
  return 0;
}

#include "NVPTX.h"
#include "llvm/IR/Function.h"
#include "llvm/IR/GlobalVariable.h"
#include "llvm/IR/LegacyPassManager.h"
#include "llvm/IR/Module.h"
#include "llvm/Support/raw_ostream.h"
#include <string>
using namespace llvm;
namespace {
/// NVPTXAssignValidGlobalNames
class NVPTXAssignValidGlobalNames : public ModulePass {
public:
  static char ID;
  NVPTXAssignValidGlobalNames() : ModulePass(ID) {}
  bool runOnModule(Module &M) override;
  /// Clean up the name to remove symbols invalid in PTX.
  std::string cleanUpName(StringRef Name);
};
}
char NVPTXAssignValidGlobalNames::ID = 0;
namespace llvm {
void initializeNVPTXAssignValidGlobalNamesPass(PassRegistry &);
}
INITIALIZE_PASS(NVPTXAssignValidGlobalNames, "nvptx-assign-valid-global-names",
                "Assign valid PTX names to globals", false, false)
bool NVPTXAssignValidGlobalNames::runOnModule(Module &M) {
  for (GlobalVariable &GV : M.globals()) {
    // We are only allowed to rename local symbols.
    if (GV.hasLocalLinkage()) {
      // setName doesn't do extra work if the name does not change.
      // Note: this does not create collisions - if setName is asked to set the
      // name to something that already exists, it adds a proper postfix to
      // avoid collisions.
      GV.setName(cleanUpName(GV.getName()));
    }
  }
  // Do the same for local functions.
  for (Function &F : M.functions())
    if (F.hasLocalLinkage())
      F.setName(cleanUpName(F.getName()));
  return true;
}
std::string NVPTXAssignValidGlobalNames::cleanUpName(StringRef Name) {
  std::string ValidName;
  raw_string_ostream ValidNameStream(ValidName);
  for (char C : Name) {
    if (C == '.' || C == '@' || C == '<' || C == '>') {
      ValidNameStream << "_$_";
    } else {
      ValidNameStream << C;
    }
  }
  return ValidNameStream.str();
}
ModulePass *llvm::createNVPTXAssignValidGlobalNamesPass() {
  return new NVPTXAssignValidGlobalNames();
}

#include <iostream>
#include <vector>
#include <string>
// This program generates a specific map for the "Kangaroos" problem.
// The map is a 20x20 grid with a "double-sided comb" structure.
// This structure is a tree, as required, and is designed to make it
// difficult for agents to congregate under random movements.
// It consists of a central horizontal "backbone" and many vertical "teeth"
// connected to it. This segregates agent movement: agents on the backbone
// primarily respond to L/R commands, while agents on teeth respond to U/D.
// Moving between these sections requires being at an intersection and receiving
// the appropriate command, which is unlikely to happen for all agents
// in a coordinated way with random commands. The numerous dead-ends also
// help trap agents, preventing them from easily gathering.
void solve() {
    int n = 20;
    int m = 20;
    std::cout << n << " " << m << std::endl;
    std::vector<std::string> map(n, std::string(m, '0'));
    // The backbone is placed on a central row. For n=20, row 9 is chosen.
    int backbone_row = n / 2 - 1;
    for (int j = 0; j < m; ++j) {
        map[backbone_row][j] = '1';
    }
    // The teeth are placed on every second column (even indices) to ensure they
    // do not connect to each other, maintaining the tree structure.
    for (int j = 0; j < m; ++j) {
        if (j % 2 == 0) {
            // Upper teeth, from the top of the grid down to the backbone.
            for (int i = 0; i < backbone_row; ++i) {
                map[i][j] = '1';
            }
            // Lower teeth, from below the backbone to the bottom of the grid.
            for (int i = backbone_row + 1; i < n; ++i) {
                map[i][j] = '1';
            }
        }
    }
    // Print the generated map to standard output.
    for (int i = 0; i < n; ++i) {
        std::cout << map[i] << std::endl;
    }
}
int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
    solve();
    return 0;
}

#include <iostream>
#include <fstream>
#include <vector>
#include <string>
#include <bitset>

// Reads a 2-bit encoded file and returns decoded sequences
std::vector<std::string> read2BitFile(const std::string& fileName)
{
    std::ifstream file(fileName, std::ios::binary);
    if (!file.is_open())
    {
        throw std::runtime_error("Failed to open file: " + fileName);
    }

    // Read header
    int sequenceCount;
    file.read(reinterpret_cast<char*>(&sequenceCount), sizeof(sequenceCount));

    std::vector<std::string> sequenceNames(sequenceCount);
    for (int i = 0; i < sequenceCount; ++i)
    {
        int nameLength;
        file.read(reinterpret_cast<char*>(&nameLength), sizeof(nameLength));
        sequenceNames[i].resize(nameLength);
        file.read(&sequenceNames[i][0], nameLength);
    }

    // Read encoded sequences
    std::vector<std::string> decodedSequences;
    for (const auto & seqName : sequenceNames)
    {
        int sequenceLength;
        file.read(reinterpret_cast<char*>(&sequenceLength), sizeof(sequenceLength));

        std::string encodedSequence;
        encodedSequence.resize(sequenceLength);
        file.read(&encodedSequence[0], sequenceLength);

        // Decode the 2-bit encoded sequence
        std::string decodedSequence;
        for (char c : encodedSequence)
        {
            std::bitset<2> bits(c);
            decodedSequence += "ACGT"[bits.to_ulong()];
        }
        decodedSequences.push_back(decodedSequence);
    }

    file.close();
    return decodedSequences;
}

#include <iostream>
#include <string>
#include <unordered_set>

// Template class for path representation
template <typename ListPathPool>
class Path {
public:
    Path() = default;

    // Constructor with parent and path name
    Path(const Path& parent, const std::string& pathName) : parent_(&parent), pathName_(pathName) {}

    // Check if the current path is unique
    bool isUnique() const {
        if (parent_ == nullptr) {
            return true;  // Root path is always unique
        }
        const auto& paths = parent_->getPaths();
        return paths.find(pathName_) == paths.end();
    }

    // Print the full path
    void printPath() const {
        if (parent_ != nullptr) {
            parent_->printPath();
            std::cout << "/" << pathName_;
        } else {
            std::cout << "/" << pathName_;
        }
    }

private:
    const Path* parent_ = nullptr;
    std::string pathName_;

    // Get the list of paths from the pool
    const ListPathPool& getPaths() const {
        return ListPathPool::getInstance();
    }
};

// Template class for managing path pools
template <typename T>
class ListPathPool {
public:
    static const ListPathPool& getInstance() {
        static ListPathPool instance;
        return instance;
    }

    std::unordered_set<std::string> paths;

private:
    ListPathPool() = default;
};

// Main function
int main() {
    using Path = Path<ListPathPool<std::string>>;

    Path root;
    Path p1 { root, "path1" };
    Path p2 { root, "path2" };
    Path p3 { root, "path1" };
    Path p4 { p2, "path1" };

    // Print paths
    p1.printPath();  // Output: /path1
    std::cout << std::endl;

    p2.printPath();  // Output: /path2
    std::cout << std::endl;

    p3.printPath();  // Output: /path1
    std::cout << std::endl;

    p4.printPath();  // Output: /path2/path1
    std::cout << std::endl;

    // Print uniqueness checks
    std::cout << "p1 is unique: " << (p1.isUnique() ? "true" : "false") << std::endl;  // Output: true
    std::cout << "p2 is unique: " << (p2.isUnique() ? "true" : "false") << std::endl;  // Output: true
    std::cout << "p3 is unique: " << (p3.isUnique() ? "true" : "false") << std::endl;  // Output: false
    std::cout << "p4 is unique: " << (p4.isUnique() ? "true" : "false") << std::endl;  // Output: true

    return 0;
}

#include <mcpputil/mcpputil/pointer_utils.hpp>
#include <unordered_set>
#include <iostream>

// Custom memory allocator class for tracking allocations
class CustomAllocator {
public:
    // Allocates memory and tracks it
    void* allocate(size_t size)
    {
        void* ptr = mcpputil::pointer_utils::allocate(size);
        m_allocated_memory.insert(ptr);
        m_total_memory_usage += size;
        return ptr;
    }

    // Deallocates memory if it was previously allocated
    void deallocate(void* ptr, size_t size)
    {
        auto it = m_allocated_memory.find(ptr);
        if (it != m_allocated_memory.end())
        {
            mcpputil::pointer_utils::deallocate(ptr, size);
            m_allocated_memory.erase(it);
            m_total_memory_usage -= size;
        }
    }

    // Destructor: reports any remaining allocated memory as leaks
    ~CustomAllocator()
    {
        for (auto ptr : m_allocated_memory)
        {
            std::cerr << "Memory leak detected at address: " << ptr << std::endl;
            mcpputil::pointer_utils::deallocate(ptr, /* size */ 0); // Deallocate without size information for demonstration purposes
        }
    }

    // Returns current total tracked memory usage
    size_t getMemoryUsage() const
    {
        return m_total_memory_usage;
    }

private:
