        void* p, 
        class_id src, 
        class_id target, 
        class_id dynamic_id, 
        void const* dynamic_ptr) const;
};

// Implementation of the cast method
std::pair<void*, int> cast_graph::cast(
    void* p, 
    class_id src, 
    class_id target, 
    class_id dynamic_id, 
    void const* dynamic_ptr) const 
{
    if (dynamic_id == src) 
    {
        void* casted_ptr = dynamic_cast<void*>(p);

        if (casted_ptr != nullptr && dynamic_id == target) 
