#include <vector>
#include <algorithm>

// Backtracking function to find combinations
void backtrack(std::vector<std::vector<int>>& res, std::vector<int>& combination, std::vector<int>& candidates, int target, int start)
{
    // Base case: if target is negative, return
    if(target < 0) return;

    // Base case: if target is zero, we found a valid combination
    if(target == 0)
    {
        res.push_back(combination);
        return;
    }

    // Iterate through candidates starting from 'start' index
    for(int i = start; i < candidates.size(); ++i)
    {
        // Skip duplicates
        if(i > start && candidates[i] == candidates[i - 1]) continue;

        // Include current candidate in combination
        combination.push_back(candidates[i]);

        // Recursively search with updated target and next index
        backtrack(res, combination, candidates, target - candidates[i], i + 1);

        // Backtrack by removing the last added element
        combination.pop_back();
    }
}

// Main function to find all combinations that sum to target
std::vector<std::vector<int>> combinationSum(std::vector<int>& candidates, int target)
{
    // Sort candidates to handle duplicates
    std::sort(candidates.begin(), candidates.end());

    // Initialize result vector and temporary combination vector
    std::vector<std::vector<int>> res;
    std::vector<int> combination;

    // Call backtracking function
    backtrack(res, combination, candidates, target, 0);

    return res;
}

