void ParticleEmitter::updateParticles(float dt)
{
    // Update all particles
    for (auto it = particles.begin(); it != particles.end();)
    {
        it->x += it->vx * dt;  // Update x position
        it->y += it->vy * dt;  // Update y position
        it->lifetime -= dt;    // Decrease lifetime

        // Check if particle has expired
        if (it->lifetime <= 0.0f)
        {
            it = particles.erase(it);  // Remove expired particle
        }
        else
        {
            ++it;  // Move to next particle
        }
    }
}

