// Process text commands to build origin and keyword strings
std::pair<std::string, std::string> processText(const std::vector<std::pair<int, std::string>>& commands)
{
    std::string origin;
    std::string keyword;

    // Iterate through all commands
    for(const auto& cmd : commands)
    {
        switch(cmd.first)
        {
            case 1:
                if(!origin.empty()) origin += " ";
                origin += cmd.second;
                break;

            case 2:
                if(!keyword.empty()) keyword += " ";
                keyword += cmd.second;
                break;

            case 3:
                origin.clear();
                break;

            case 4:
                keyword.clear();
                break;

            // additional cases can be handled here
        }
    }

    // Return the pair of origin and keyword
    return std::make_pair(origin, keyword);
}

