// Function to calculate total problems to solve
long long totalProblemsToSolve(long long n, long long k, long long d)
{
    // Calculate the total number of days required to solve k problems
    ll totalDays = (k + d - 1) / d;

    // Calculate the total number of problems to solve all topics in totalDays
    ll totalProblems = n * totalDays;

    // Return the maximum of totalProblems and k
    // as the student may not need to solve all problems for each topic
    return std::max(totalProblems, k);
}

