#include <vector>

// Class for flood fill algorithm
class CFill {
private:
    std::vector<std::vector<int>> grid;
    int rows;
    int cols;

    // Helper function for recursive filling
    void fillHelper(int x, int y, int oldColor, int newColor)
    {
        if (x < 0 || x >= rows || y < 0 || y >= cols || grid[x][y] != oldColor) {
            return;
        }
        grid[x][y] = newColor;
        fillHelper(x + 1, y, oldColor, newColor);
        fillHelper(x - 1, y, oldColor, newColor);
        fillHelper(x, y + 1, oldColor, newColor);
        fillHelper(x, y - 1, oldColor, newColor);
    }

public:
    // Constructor initializes grid with default values
    CFill() : rows(10), cols(10), grid(std::vector<std::vector<int>>(10, std::vector<int>(10, 0)))
    {
        // Initialize the grid with default size and color values
    }

    // Public method to perform flood fill
    void fill(int x, int y, int newColor)
    {
        if (x < 0 || x >= rows || y < 0 || y >= cols) {
            return;
        }
        int oldColor = grid[x][y];
        if (oldColor == newColor) {
            return;
        }
        fillHelper(x, y, oldColor, newColor);
    }
};

