// Define the types used for the delegate and callable objects
using Callable = std::function<void()>;

template <typename ReturnType, typename... Args>
using DelegateType = std::function<ReturnType(Args...)>;

class DelegateManager
{
public:
    // Store a callable object of type std::function<void()>
    void StoreAction(std::function<void()> action)
    {
        m_Action = action;
    }

    // Store a delegate of type std::function<int(int, bool)>
    void StoreDelegate(std::function<int(int, bool)> delegate)
    {
        m_Delegate = delegate;
    }

    // Execute the stored callable object
    void ExecuteAction()
    {
        if (m_Action)
        {
            m_Action();
        }
    }

    // Execute the stored delegate with the given arguments
    int ExecuteDelegate(int arg1, bool arg2)
    {
        if (m_Delegate)
        {
            return m_Delegate(arg1, arg2);
        }
        return 0; // Default return value if delegate is not set
    }

private:
    std::function<void()> m_Action;
    std::function<int(int, bool)> m_Delegate;
};

