#include <openssl/bn.h>
#include <iostream>

// Verifies cryptographic operation using BIGNUM operations
bool verifyCryptographicOperation(BIGNUM* XT, BIGNUM* salt, BIGNUM* d, BIGNUM* e2, BIGNUM* add, BIGNUM* t4, BIGNUM* e, BIGNUM* n, BIGNUM* m, BIGNUM* T, BN_CTX* ctx)
{
    // Add salt to XT
    BN_add(XT, XT, salt);

    // Compute d = XT mod e2
    BN_mod(d, XT, e2, ctx);

    // Add add to d
    BN_add(d, d, add);

    // Compute t4 = t4^e mod n
    BN_mod_exp(t4, t4, e, n, ctx);

    // Compute XT = m^d mod n
    BN_mod_exp(XT, m, d, n, ctx);

    // Multiply XT by T mod n
    BN_mod_mul(XT, XT, T, n, ctx);

    // Verify XT equals t4
    if(BN_cmp(XT, t4) != 0)
    {
        std::cout << "BN_cmp(XT, t4) failed" << std::endl;
        BN_CTX_free(ctx);
        return false;
    }

    BN_CTX_free(ctx);
    return true;
}

