  struct OutPoint {
    // Implementation details of OutPoint
  };

  OutPoint prevOut;
  std::vector<uint8_t> scriptSig;
  uint32_t sequence;

 public:
  // Method to serialize the TxIn object into a byte stream
  std::vector<uint8_t> serialize()
  {
    std::vector<uint8_t> serializedData;

    // Serialize the prevOut struct into the byte stream
    std::vector<uint8_t> prevOutData(
        reinterpret_cast<uint8_t*>(&prevOut), 
        reinterpret_cast<uint8_t*>(&prevOut) + sizeof(OutPoint)
    );
    serializedData.insert(serializedData.end(), prevOutData.begin(), prevOutData.end());

    // Append the scriptSig vector to the byte stream
    serializedData.insert(serializedData.end(), scriptSig.begin(), scriptSig.end());

    // Append the sequence value to the byte stream
    uint32_t sequenceLE = htobe32(sequence);  // Convert to big-endian
    uint8_t* sequenceBytes = reinterpret_cast<uint8_t*>(&sequenceLE);
    serializedData.insert(serializedData.end(), sequenceBytes, sequenceBytes + SEQUENCE_SIZE);

    return serializedData;
  }
};

