// Direction enum for board reading
enum class Direction { Horizontal, Vertical };

class Board {
private:
    std::vector<std::vector<char>> grid;
public:
    // Constructor with initializer list
    Board(const std::vector<std::vector<char>>& initialGrid) : grid(initialGrid) {}

    // Read a word from the board in specified direction and length
    std::string read(int row, int col, Direction direction, int length) {
        std::string word;

        if (direction == Direction::Horizontal) {
            for(int i=col; i<col+length; ++i) {
                word += grid[row][i];
            }
        } else if (direction == Direction::Vertical) {
            for(int i=row; i<row+length; ++i) {
                word += grid[i][col];
            }
        }

        return word;
    }
};

