// Group class definition
class group
{
public:
    // Type aliases
    typedef std::vector<std::string>::const_iterator const_iterator;
    typedef std::vector<std::string>::size_type size_type;

    // Key-value store using unordered map
    std::unordered_map<std::string, std::string> data;

    // Template function to retrieve value with exception on missing key
    template<typename T>
    T get(const std::string& key) const 
    {
        auto it = data.find(key);
        if (it != data.end()) 
        {
            try 
            {
                return convert<T>(it->second);
            } 
            catch (const std::invalid_argument&) 
            {
                throw std::invalid_argument("Value cannot be converted to the requested type");
            }
        } 
        else 
        {
            throw std::out_of_range("Key does not exist");
        }
    }

    // Template function to retrieve value with default fallback
    template<typename T>
    T get(const std::string& key, const T& def) const 
    {
        auto it = data.find(key);
        if (it != data.end()) 
        {
            try 
            {
                return convert<T>(it->second);
            } 
            catch (const std::invalid_argument&) 
            {
                throw std::invalid_argument("Value cannot be converted to the requested type");
            }
        } 
        else 
        {
            return def;
        }
    }

private:
    // Helper function for type conversion
    template<typename T>
    T convert(const std::string& value) const 
    {
        if (std::is_same<T, int>::value) 
        {
            return std::stoi(value);
        } 
        else if (std::is_same<T, double>::value) 
        {
            return std::stod(value);
        } 
        else if (std::is_same<T, std::string>::value) 
        {
            return value;
        } 
        else 
        {
            throw std::invalid_argument("Unsupported type conversion");
        }
    }
};

