#include <set>

class Solution {
public:
    // Set to store remainders (not used in current implementation)
    set<int> ss;

    // Function to find the length of smallest repunit divisible by K
    int smallestRepunitDivByK(int K)
    {
        // If K is divisible by 2 or 5, no repunit can be divisible by K
        if (K % 2 == 0 || K % 5 == 0)
        {
            return -1;
        }

        int remainder = 0;

        // Iterate up to K times to find the solution
        for (int length = 1; length <= K; length++)
        {
            // Update remainder using modular arithmetic
            remainder = (remainder * 10 + 1) % K;

            // If remainder is zero, we found our answer
            if (remainder == 0)
            {
                return length;
            }
        }

        // If no solution found within K iterations, return -1
        return -1;
    }
};

