// Renders lights into camera buffers
void RenderLights(const std::vector<LightData>& lights, std::vector<CameraConstantBuffer>& cameraBuffers)
{
    for (const auto& lightData : lights)
    {
        if (lightData.m_lightType == ELightType::Directional)
        {
            // Process directional light
            int renderTargetOffset = lightData.m_renderTargetOffset;
            CameraConstantBuffer cameraBuffer;
            cameraBuffer.m_viewProjection = lightData.m_viewProjection;
            cameraBuffers.push_back(cameraBuffer);
        }
        else if (lightData.m_lightType == ELightType::Point)
        {
            int renderCount = 6;
            // Handle point light rendering for 6 faces of cube map
            for (int i = 0; i < renderCount; ++i)
            {
                CameraConstantBuffer cameraBuffer;
                // Populate cameraBuffer with appropriate view and projection matrices for each direction
                Vector3 lightPosition = lightData.m_position;
                Vector3 lookDirections[] = { Vector3(1, 0, 0), Vector3(-1, 0, 0), Vector3(0, 1, 0),
                                             Vector3(0, -1, 0), Vector3(0, 0, 1), Vector3(0, 0, -1) };
                Vector3 upDirection = Vector3(0, 1, 0);
                Matrix viewMatrix = CalculateViewMatrix(lightPosition, lightPosition + lookDirections[i], upDirection);
                Matrix projectionMatrix = CalculateProjectionMatrixForDirection(90.0f, 1.0f, 0.1f, 100.0f);
                cameraBuffer.m_viewProjection = viewMatrix * projectionMatrix;
                cameraBuffers.push_back(cameraBuffer);
            }
        }
    }
}

