// Convert FILETIME to ULONGLONG
ULONGLONG ft2ull(const FILETIME& ft)
{
    return ((ULONGLONG)ft.dwHighDateTime << 32) | ft.dwLowDateTime;
}

// Global map to store status information
std::map<std::string, double> status_info_map;

// Function to calculate CPU usage and update status_info_map
void calculateCPUUsage(const FILETIME& idle,
                       const FILETIME& kernel,
                       const FILETIME& user,
                       const FILETIME& prev_idle,
                       const FILETIME& prev_kernel,
                       const FILETIME& prev_user)
{
    status_info_map.clear(); // Clear the map before updating

    ULONGLONG userTime = ft2ull(user) - ft2ull(prev_user);
    ULONGLONG kernelTime = ft2ull(kernel) - ft2ull(prev_kernel);
    ULONGLONG idleTime = ft2ull(idle) - ft2ull(prev_idle);

    double cpuUsage = 100.0 * (userTime + kernelTime) / (userTime + kernelTime + idleTime);
    status_info_map["CPU Usage"] = cpuUsage; // Update status_info_map with CPU usage
}

int main()
{
    // Example usage
