    // Obtain system times and previous system times
    // Call calculateCPUUsage function
    calculateCPUUsage(idle, kernel, user, prev_idle, prev_kernel, prev_user);

    // Access CPU usage from status_info_map
    double cpuUsage = status_info_map["CPU Usage"];

    // Use the CPU usage information as needed
    return 0;
}

