#ifndef INCLUDE_BA_LOG_DETAIL_EXCEPTION_TRANSLATOR_HPP
#define INCLUDE_BA_LOG_DETAIL_EXCEPTION_TRANSLATOR_HPP

#include <exception>
#include <functional>
#include <map>

// Exception translator class
class ExceptionTranslator {
public:
    // Translate function with exception handling
    template <typename Func>
    void translate(Func func)
    {
        try {
            func();
        } catch (const std::exception& ex) {
            auto it = exceptionMap.find(typeid(ex).name());
            if (it != exceptionMap.end()) {
                throw it->second();
            } else {
                throw;
            }
        }
    }

    // Map exception types
    template <typename From, typename To>
    void map()
    {
        exceptionMap[typeid(From).name()] = []() { return To(); };
    }

private:
    std::map<std::string, std::function<std::exception()>> exceptionMap;
};

// Macro for translating exceptions
#define TRANSLATE_EXCEPTION(translator, func) translator.translate([&]() { func; })

#endif // INCLUDE_BA_LOG_DETAIL_EXCEPTION_TRANSLATOR_HPP

