#include <cmath>
#include <limits>

// Compares two floating-point numbers for equality within a specified ULP tolerance
bool almost_equal(const float x, const float y, int ulp)
{
    // Convert the floating-point numbers to their integer representations
    int x_int = *reinterpret_cast<const int*>(&x);
    int y_int = *reinterpret_cast<const int*>(&y);

    // Adjust integer representations for negative numbers to match their floating-point ordering
    if (x_int < 0)
        x_int = std::numeric_limits<int>::max() - x_int + 1;
    if (y_int < 0)
        y_int = std::numeric_limits<int>::max() - y_int + 1;

    // Compute the absolute difference in ULPs
    int ulp_diff = std::abs(x_int - y_int);

    // Determine if the difference is within the allowed tolerance
    return ulp_diff <= ulp;
}

