// Guard class to ensure dlclose is called
class DlCloseGuard {
public:
    explicit DlCloseGuard(void* handle) : handle_(handle) {}

    ~DlCloseGuard() {
        if (handle_) {
            dlclose(handle_);
        }
    }

private:
    void* handle_;
};

int main()
{
