#include <vector>
#include <functional>
#include <mutex>
#include <condition_variable>

// TaskScheduler class definition
class TaskScheduler {
public:
    // Constructor initializes counter to 0
    TaskScheduler() : counter(0) {}

    // Schedule a new task
    void schedule(const std::function<void()>& task) {
        std::unique_lock<std::mutex> lock(mutex);
        tasks.push_back(task);
    }

    // Execute all scheduled tasks concurrently
    void execute() {
        std::vector<std::thread> threads;

        // Launch threads for each task
        for (int i = 0; i < tasks.size(); ++i) {
            threads.emplace_back([this, i] {
                std::unique_lock<std::mutex> lock(mutex);
                if (i < tasks.size()) {
                    tasks[i]();
                    ++counter;
                }
                cv.notify_one();
            });
        }

        // Wait for all threads to complete
        for (auto& t : threads) {
            t.join();
        }
    }

    // Get the current counter value
    int getCounter() const {
        return counter;
    }

private:
    std::vector<std::function<void()>> tasks;
    std::mutex mutex;
    std::condition_variable cv;
    int counter;
};

// Main function
int main() {
    TaskScheduler scheduler;

    // Schedule tasks
    scheduler.schedule([] { std::cout << "Task 1 executed" << std::endl; });
    scheduler.schedule([] { std::cout << "Task 2 executed" << std::endl; });
    scheduler.schedule([] { std::cout << "Task 3 executed" << std::endl; });

    // Execute tasks concurrently
    scheduler.execute();

    // Verify the counter
    std::cout << "Total tasks executed: " << scheduler.getCounter() << std::endl;

    return 0;
}

#include <QObject>
#include <QThread>
#include <QVector>
#include <complex>
#include <fftw3.h>

// FFT processing worker class
class FFTWorker : public QObject {
    Q_OBJECT

public:
    // Constructor with FFT length parameter
    FFTWorker(int fftLength) : m_fftLength(fftLength) {
        m_inputSignal.resize(fftLength);
        m_outputResult.resize(fftLength);

        // Initialize and configure FFTW plans
        m_fftPlan = fftw_plan_dft_1d(
            fftLength,
            reinterpret_cast<fftw_complex*>(m_inputSignal.data()),
            reinterpret_cast<fftw_complex*>(m_outputResult.data()),
            FFTW_FORWARD,
            FFTW_ESTIMATE
        );
    }

    // Destructor - clean up FFTW plan
    ~FFTWorker() {
        fftw_destroy_plan(m_fftPlan);
    }

public slots:
    // Process input signal in a separate thread
    void processInputSignal(const QVector<double>& inputSignal) {
        // Copy input signal to member variable for processing
        std::copy(inputSignal.begin(), inputSignal.end(), m_inputSignal.begin());

        // Perform FFT computation in a separate thread
        m_fftThread = new QThread();
        moveToThread(m_fftThread);

        connect(m_fftThread, &QThread::started, this, &FFTWorker::computeFFT);
        connect(this, &FFTWorker::fftResultReady, m_fftThread, &QThread::quit);
        connect(this, &FFTWorker::fftResultReady, this, &FFTWorker::deleteLater);
        connect(m_fftThread, &QThread::finished, m_fftThread, &QThread::deleteLater);

        m_fftThread->start();
    }

signals:
    // Signal emitted when FFT result is ready
    void fftResultReady(const QVector<std::complex<double>>& result);

private:
    int m_fftLength;
    QVector<double> m_inputSignal;
    QVector<std::complex<double>> m_outputResult;
    fftw_plan m_fftPlan;
    QThread* m_fftThread;

    // Compute FFT (executed in worker thread)
    void computeFFT() {
        // Execute the FFT computation
        fftw_execute(m_fftPlan);

        // Convert the output to QVector<std::complex<double>> for emitting the result
        QVector<std::complex<double>> result(m_fftLength);
        for (int i = 0; i < m_fftLength; ++i) {
            result[i] = std::complex<double>(m_outputResult[i].real(), m_outputResult[i].imag());
        }

        // Emit the computed FFT result
        emit fftResultReady(result);
    }
};

