// Base class for shapes
class Shape {
public:
    virtual double getArea() const = 0;
    virtual double getPerimeter() const = 0;
    virtual ~Shape() {}
};

// 2D point representation
class Point2D {
    double x, y;
public:
    Point2D(double x, double y) : x(x), y(y) {}
    double getX() const { return x; }
    double getY() const { return y; }
};

// Polygon shape implementation
class Polygon : public Shape {
    std::vector<Point2D> points;
public:
    Polygon(const std::vector<Point2D>& points) : points(points) {}

    // Calculate area using the shoelace formula
    double getArea() const override {
        // Implement area calculation for polygon based on points
        // Return the calculated area
        if (points.size() < 3) return 0.0;

        double area = 0.0;
        int n = points.size();
        for (int i = 0; i < n; ++i) {
            int j = (i + 1) % n;
            area += points[i].getX() * points[j].getY();
            area -= points[j].getX() * points[i].getY();
        }
        return std::abs(area) / 2.0;
    }

    // Calculate perimeter by summing edge lengths
    double getPerimeter() const override {
        // Implement perimeter calculation for polygon based on points
        // Return the calculated perimeter
        if (points.size() < 2) return 0.0;

        double perimeter = 0.0;
        int n = points.size();
        for (int i = 0; i < n; ++i) {
            int j = (i + 1) % n;
            double dx = points[j].getX() - points[i].getX();
            double dy = points[j].getY() - points[i].getY();
            perimeter += std::sqrt(dx * dx + dy * dy);
        }
        return perimeter;
    }
};

// Circle shape implementation
class Circle : public Shape {
    double radius;
public:
    Circle(double radius) : radius(radius) {}

    double getArea() const override {
        return M_PI * radius * radius; // Area calculation for circle
    }

    double getPerimeter() const override {
        return 2 * M_PI * radius; // Perimeter calculation for circle
    }
};

