// Function to find next larger elements
std::vector<int> next_larger_element(int n, const std::vector<int>& nums)
{
    // Initialize result array with -1
    std::vector<int> result(n, -1);
    // Stack to store indices of elements
    std::stack<int> stack;

    for(int i=0; i<n; i++)
    {
        // Process elements while stack is not empty and current element is greater
        while(!stack.empty() && nums[i] > nums[stack.top()])
        {
            // Update result for elements with next larger element
            result[stack.top()] = nums[i];
            // Pop the index as it has been processed
            stack.pop();
        }
        // Push the current index onto the stack
        stack.push(i);
    }

    return result;
}

