// Weighted Directed Graph implementation
class WeightedDirectedGraph {
private:
    struct Item {
        std::vector<std::pair<Item*, int>> children;
    };
    std::vector<Item*> items;

public:
    // Adds a new item to the graph
    void add_item() {
        items.push_back(new Item());
    }

    // Adds a directed link with given weight from 'from' to 'to'
    void add_link(Item* from, Item* to, int weight) {
        auto& children = from->children;
        children.emplace_back(to, weight);
    }

    // Computes shortest path using Dijkstra's algorithm
    int shortest_weight(Item* from, Item* to) {
        // Distance vector initialized to infinity
        std::vector<int> dist(items.size(), INT_MAX);
        dist[from - &items[0]] = 0;

        // Visited tracking
        std::vector<bool> visited(items.size(), false);

        // Main loop: process all but last node
        for (size_t i = 0; i < items.size() - 1; ++i) {
            int u = -1;

            // Find minimum distance unvisited node
            for (size_t j = 0; j < items.size(); ++j) {
                if (!visited[j] && (u == -1 || dist[j] < dist[u])) {
                    u = j;
                }
            }

            // Mark selected node as visited
            visited[u] = true;

            // Update distances to neighbors
            for (const auto& child : items[u]->children) {
                int v = child.first - &items[0];
                int weight = child.second;

                if (!visited[v] && dist[u] != INT_MAX && dist[u] + weight < dist[v]) {
                    dist[v] = dist[u] + weight;
                }
            }
        }

        return dist[to - &items[0]];
    }
};

// Main function demonstrating usage
int main() {
    WeightedDirectedGraph graph;

    // Add two items
    graph.add_item(); // Item 1
    graph.add_item(); // Item 2

    // Add weighted directed edge from item 1 to item 2
    graph.add_link(graph.items[0], graph.items[1], 5);

    // Output the shortest weight between the items
    std::cout << "Shortest weight from item 1 to item 2: "
              << graph.shortest_weight(graph.items[0], graph.items[1])
              << std::endl;

    return 0;
}

