// Updates the sent messages count
void updateSentMessages(const std::string& reply, int msgs, ClientConnection& fdref, Server* serv)
{
    // Adjust for trailing CRLF if present
    if (reply.find_last_of(CRLF) != reply.length() - 1)
        msgs--;

    // Update client's sent message count
    fdref.sentmsgs += msgs;

    // Update server's file descriptor sent message count if socket is valid
    if (fdref.sock > 0)
        serv->fds[fdref.sock].sentmsgs += msgs;

}

