    std::cout << warning1.HasCWE() << std::endl;  // Output: 0 (false)

    // Test case 2: MISRA.C.2004
    Warning warning2;
    warning2.misra = "MISRA.C.2004";
    std::cout << warning2.GetMISRAStringWithLanguagePrefix() << std::endl;  // Output: C MISRA.C.2004
