void SMExtractRGBI(IplImage* inputImage, CvMat* &R, CvMat* &G, CvMat* &B, CvMat* &I)
{
    // Convert input image to OpenCV Mat
    cv::Mat inputMat(inputImage);

    // Split the input image into its RGB components
    std::vector<cv::Mat> rgbChannels;
    cv::split(inputMat, rgbChannels);

    // Convert RGB channels to floating point format
    cv::Mat R_float, G_float, B_float;
    rgbChannels[2].convertTo(R_float, CV_32F);
    rgbChannels[1].convertTo(G_float, CV_32F);
    rgbChannels[0].convertTo(B_float, CV_32F);

