// Inventory class to manage items
class Inventory {
private:
    // Map to store items with unique identifier as key
    std::map<int, std::pair<std::string, int>> items;

public:
    void addItem(int id, const std::string& name, int quantity, double price) {
        if (items.find(id) != items.end()) {
            // Update quantity if item already exists
            items[id].second += quantity;
        } else {
            // Add new item to inventory
            items[id] = std::make_pair(name, quantity);
        }
    }

    void removeItem(int id, int quantity) {
        if (items.find(id) != items.end()) {
            if (items[id].second <= quantity) {
                // Remove item if quantity to be removed exceeds available quantity
                items.erase(id);
            } else {
                // Update quantity
                items[id].second -= quantity;
            }
        }
    }

    void displayInventory() {
        std::cout << "Inventory:\n";
        for (const auto& item : items) {
            std::cout << "ID: " << item.first
                      << ", Name: " << item.second.first
                      << ", Quantity: " << item.second.second
                      << std::endl;
        }
    }
};

