    storeInventory.addItem(2, "Pants", 30, 39.99);
    storeInventory.addItem(1, "Shirt", 20, 25.99); // Update quantity of existing item

    storeInventory.displayInventory();

    storeInventory.removeItem(1, 30); // Remove 30 shirts

    storeInventory.displayInventory();

