};

int main(int argc, char* argv[])
{
    // Check command line arguments
    if (argc != 3)
    {
        std::cerr << "Usage: ./proxy <path> <number>\n";
        return -1;
    }

    unsigned int NodeNum;
    // Parse the number argument
    if (sscanf(argv[2], "%u", &NodeNum) == 0)
    {
        std::cerr << "Invalid number format\n";
        return -1;
    }

    // Allocate array of LocalNode pointers
    LocalNode** local_nodes = new LocalNode*[NodeNum];

    // Create pipe for communication between main and child processes
    int pipe_main_child[2];
    if (pipe(pipe_main_child) == -1)
    {
        perror("Pipe creation error");
        return -1;
    }

    // Open the input file
    int file_fd = open(argv[1], O_RDONLY);
    if (file_fd == -1)
    {
        perror("File open error");
        return -1;
    }

    // Fork child processes
    for (int i = 0; i < NodeNum; i++)
    {
        int pipe_child_main[2];
        if (pipe(pipe_child_main) == -1)
        {
            perror("Pipe creation error");
            return -1;
        }

        pid_t pid = fork();
        if (pid == -1)
        {
            perror("Fork error");
            return -1;
        }

        if (pid == 0)  // Child process
        {
            close(pipe_child_main[1]);  // Close write end
            close(pipe_main_child[0]);  // Close read end of main-child pipe

            // Read data from the main process through the pipe
            char buffer[1024];
            ssize_t bytes_read = read(pipe_child_main[0], buffer, sizeof(buffer));
            if (bytes_read == -1)
            {
                perror("Read error");
                return -1;
            }

            // Process the received data independently
            // ...

            close(pipe_child_main[0]);  // Close read end after reading
            exit(0);
        }
        else  // Main process
        {
            close(pipe_child_main[0]);  // Close read end

            // Read data from the file
            char file_buffer[1024];
            ssize_t bytes_read = read(file_fd, file_buffer, sizeof(file_buffer));
            if (bytes_read == -1)
            {
                perror("File read error");
                return -1;
            }

            // Send data to the child process through the pipe
            ssize_t bytes_written = write(pipe_child_main[1], file_buffer, bytes_read);
            if (bytes_written == -1)
            {
                perror("Write error");
                return -1;
            }

            close(pipe_child_main[1]);  // Close write end after writing
        }
    }

    close(file_fd);  // Close the file descriptor

    // Wait for all child processes to complete
    for (int i = 0; i < NodeNum; i++)
    {
        wait(NULL);
    }

    delete[] local_nodes;  // Free allocated memory
    return 0;
}

#include <unordered_set>

// Checks if an instance ID is usable
bool isInstanceIdUsable(int instance, std::unordered_set<int>* seen_instance_ids, bool* usable)
{
    // Check if the instance ID is already in the set of seen instance IDs
    if(seen_instance_ids->find(instance) != seen_instance_ids->end())
    {
        // Instance ID already seen, reject it.
        *usable = false;
    }
    else
    {
        // This instance ID is new, mark it as seen and return that it's usable
        seen_instance_ids->insert(instance);
        *usable = true;
    }
    // Return the usability status
    return *usable;
}

