namespace randest {
    // Template class for generating random data
    template<typename OutputT>
    class data_provider {
    private:
        std::mt19937 rng;  // Mersenne Twister random number engine

    public:
        // Constructor with seed initialization
        data_provider(int seed) : rng(seed) {}

        // Generate a vector of random values
        std::vector<OutputT> generate(int count) {
            std::vector<OutputT> result;
            // Default distribution for non-integer types
            std::uniform_real_distribution<double> dist(0.0, 1.0);

            for (int i = 0; i < count; ++i) {
                result.push_back(static_cast<OutputT>(dist(rng)));
            }

            return result;
        }

        // Set new seed for the random number generator
        void set_seed(int seed) {
            rng.seed(seed);
        }
    };
}

