// Enum for log levels
enum class LogLevel {
    Info,
    Warning,
    Error
};

// Custom logger wrapper using spdlog
class Logger {
public:
    // Constructor initializes the logger with name and pattern
    Logger(const std::string& name, const std::string& pattern)
    {
        logger_ = spdlog::stdout_color_mt(name);
        logger_->set_pattern(pattern);
    }

    // Adds a console sink for colored output
    void addConsoleSink()
    {
        logger_->sinks().emplace_back(std::make_shared<spdlog::sinks::stdout_color_sink_mt>());
    }

    // Adds a file sink to log to a specified file
    void addFileSink(const std::string& filename)
    {
        logger_->sinks().emplace_back(std::make_shared<spdlog::sinks::basic_file_sink_mt>(filename, true));
    }

    // Logs a message at the specified level
    void log(LogLevel level, const std::string& message)
    {
        switch (level) {
            case LogLevel::Info:
                logger_->info(message);
                break;
            case LogLevel::Warning:
                logger_->warn(message);
                break;
            case LogLevel::Error:
                logger_->error(message);
                break;
        }
    }

private:
    std::shared_ptr<spdlog::logger> logger_;
};

