// Class definition for tdouble
class tdouble {
private:
    double data;
public:
    // Constructor
    tdouble(double value) : data(value) {}

    // Comparison operators
    constexpr friend bool operator==(const tdouble& lhs, const tdouble& rhs) {
        return lhs.data == rhs.data;
    }

    constexpr friend bool operator!=(const tdouble& lhs, const tdouble& rhs) {
        return lhs.data != rhs.data;
    }

    constexpr friend bool operator<(const tdouble& lhs, const tdouble& rhs) {
        return lhs.data < rhs.data;
    }

    constexpr friend bool operator>(const tdouble& lhs, const tdouble& rhs) {
        return lhs.data > rhs.data;
    }

    constexpr friend bool operator<=(const tdouble& lhs, const tdouble& rhs) {
        return lhs.data <= rhs.data;
    }

    constexpr friend bool operator>=(const tdouble& lhs, const tdouble& rhs) {
        return lhs.data >= rhs.data;
    }
};

