        // Apply Canny edge detection if enabled
        if (use_canny) 
        {
            cv::Mat gray;
            cv::cvtColor(frame, gray, cv::COLOR_BGR2GRAY);
            cv::Canny(gray, frame, low_threshold, high_threshold);
        }

        // Update UI and display
        cvui::update();
        cv::imshow(WINDOW_NAME, frame);

        // Exit on ESC key
        if (cv::waitKey(30) == 27) 
        {
            break;
        }
    }

