// Image processor class for handling image operations and display
class ImageProcessor {
public:
    // Constructor initializes the input file
    ImageProcessor(const std::string& inputFile) : inputFile(inputFile) {}

    // Adds an operation to be performed on the image
    void addOperation(const std::string& operation) {
        operations.push_back(operation);
    }

    // Sets display configuration parameters
    void setDisplaySettings(int width, int height, int fps) {
        displayWidth = width;
        displayHeight = height;
        framesPerSecond = fps;
    }

    // Processes and displays the image using OpenGL
    void processAndDisplay() {
        // Prepare arguments for sprite initialization
        std::vector<std::string> args;
        args.push_back(inputFile);

        // Add all operations to the argument list
        for (const auto& op : operations) {
            args.push_back(op);
        }

        // Initialize sprite with arguments and frame rate
        Sprite::instance().init(args, framesPerSecond);

        // Load and use shader program
        Shader shader("./Shader/vertexShader.glsl", "./Shader/fragmentShader.glsl");
        glUseProgram(shader.id);

        // Verify no OpenGL errors occurred
        assert(glGetError() == 0);

        // Main display loop
        while (1) {
            // Display logic using OpenGL
        }
    }

private:
    std::string inputFile;
    std::vector<std::string> operations;
    int displayWidth;
    int displayHeight;
    int framesPerSecond;
};

// Main entry point
int main(int argc, char* argv[]) {
    // Check command line arguments
    if (argc < 2) {
        std::cerr << "Usage: " << argv[0] << " <input_image_file>" << std::endl;
        return 1;
    }

    // Get input file from command line
    std::string inputFile = argv[1];

    // Create processor and configure operations
    ImageProcessor processor(inputFile);
    processor.addOperation("grayscale");
    processor.addOperation("blur");
    processor.setDisplaySettings(800, 600, 30);

    // Process and display the image
    processor.processAndDisplay();

    return 0;
}

