{
    App app;

    // Add screens
    app.addScreen(new ExampleScreen(1, "Welcome to the app"));
    app.addScreen(new ExampleScreen(2, "Settings screen"));

    // Show screens
    app.showScreen(1);
    app.showScreen(2);

    // Remove and try to show again
    app.removeScreen(1);
    app.showScreen(1);

    return 0;
}

