// Event listener class
class EventListener {
private:
    std::vector<void (*)()> handlers;

public:
    // Register a new handler
    void registerHandler(void (*handler)()) {
        handlers.push_back(handler);
    }

    // Fire all registered handlers
    void fireEvent() {
        for(auto handler : handlers) {
            handler();
        }
    }
};

int main() {
