    // Register event handlers
    listener.registerHandler([]() { std::cout << "Event handler 1 called" << std::endl; });
    listener.registerHandler([]() { std::cout << "Event handler 2 called" << std::endl; });

    // Trigger the event
    listener.fireEvent();

    return 0;
}

