  friend std::ostream& operator<<(std::ostream& os, const Operator& op) {
    os << op.symbol_;
    return os;
  }

private:
  std::string symbol_;
};

// Function to print expression in prefix or postfix format
void printExpression(std::ostream& os, bool post_, const Operand& expr_, const Operator& op_) {
  if (post_)
    os << expr_ << " " << op_;
  else
    os << op_ << " " << expr_;
}

// Main function
