  Operand expr("5");
  Operator op("+");

  std::cout << "Postfix format: ";
  printExpression(std::cout, true, expr, op);
  std::cout << std::endl;

  std::cout << "Prefix format: ";
  printExpression(std::cout, false, expr, op);
  std::cout << std::endl;

