// Function to calculate maximum weight after connecting ropes
int maxWeightAfterConnectingRopes(int weight[], int rope, int n)
{
    // Sort the array of rope weights
    std::sort(weight, weight + rope);

    // Array to store the results after multiplying weights by n
    int result[rope];

    // Multiply each weight by n and store the result
    for (int j = rope - 1; j >= 0; j--)
    {
        result[j] = weight[j] * n;
        n++;
    }

    // Sort the array of results
    std::sort(result, result + rope);

    // Get the maximum weight achieved after connecting the ropes
    int max = result[rope - 1];
    return max;
}

int main()
{
    int weight[] = {4, 3, 2, 6};
    int rope = 4;
    int n = 1;

    // Output: 29
    std::cout << maxWeightAfterConnectingRopes(weight, rope, n) << std::endl;

    return 0;
}

