// Structure to hold parsed command-line arguments
struct ParsedArgs {
    infiniDevice_t device_type;
};

// Prints usage information and exits the program
void printUsage() {
    std::cout << "Usage:" << std::endl
              << std::endl;
    std::cout << "infiniccl-test --<device>" << std::endl
              << std::endl;
    std::cout << "  --<device>" << std::endl;
    std::cout << "    Specify the device type --(nvidia|cambricon|ascend|metax|moore|iluvatar|qy|kunlun|hygon|ali)." << std::endl
              << std::endl;
    std::cout << "The program will run tests on all visible devices of the specified device type."
              << " Use Environmental Variables such as CUDA_VSIBLE_DEVICES to limit visible device IDs.";
    exit(-1);
}

// Macro to simplify device argument parsing
#define PARSE_DEVICE(FLAG, DEVICE) \
    if (arg == FLAG) {             \
        args.device_type = DEVICE; \
    }

// Parses command-line arguments and returns parsed configuration
ParsedArgs parseArgs(int argc, char *argv[]) {
    if (argc != 2) {
        printUsage();
    }

    // Handle help flags
    if (std::string(argv[1]) == "--help" || std::string(argv[1]) == "-h") {
        printUsage();
    }

    ParsedArgs args;
    try {
        std::string arg = argv[1];
        // clang-format off
        PARSE_DEVICE("--nvidia", INFINI_DEVICE_NVIDIA)
        else PARSE_DEVICE("--cambricon", INFINI_DEVICE_CAMBRICON)
        else PARSE_DEVICE("--ascend", INFINI_DEVICE_ASCEND)
        else PARSE_DEVICE("--metax", INFINI_DEVICE_METAX)
        else PARSE_DEVICE("--moore", INFINI_DEVICE_MOORE)
        else PARSE_DEVICE("--iluvatar", INFINI_DEVICE_ILUVATAR)
        else PARSE_DEVICE("--qy", INFINI_DEVICE_QY)
        else PARSE_DEVICE("--kunlun", INFINI_DEVICE_KUNLUN)
        else PARSE_DEVICE("--hygon", INFINI_DEVICE_HYGON)
        else PARSE_DEVICE("--ali", INFINI_DEVICE_ALI)
        else {
            printUsage();
        }
        // clang-format on
    } catch (const std::exception &) {
        printUsage();
    }
    return args;
}

// Main entry point
int main(int argc, char *argv[]) {
    ParsedArgs args = parseArgs(argc, argv);

    int ndevice = 0;
    infinirtInit();

    // Get number of devices for the specified type
    if (infinirtGetDeviceCount(args.device_type, &ndevice) != INFINI_STATUS_SUCCESS) {
        std::cout << "Failed to get device count" << std::endl;
        return -1;
    }

    // Check if any devices were found
    if (ndevice == 0) {
        std::cout << "No devices found. Tests skipped." << std::endl;
        return 0;
    } else {
        std::cout << "Found " << ndevice << " devices. Running tests..." << std::endl;
    }

    // Run tests and track failures
    int failed = 0;
    failed += testAllReduce(args.device_type, ndevice);

    return failed;
}

#ifndef _GNU_SOURCE // pthread_getattr_np
#define _GNU_SOURCE
#endif

#include <pthread.h>
#include "libcgo.h"

// Get stack bounds for current thread
void
x_cgo_getstackbound(uintptr bounds[2])
{
    pthread_attr_t attr;
    void *addr;
    size_t size;

    // Initialize attribute structure
    pthread_attr_init(&attr);

#if defined(__GLIBC__) || defined(__BIONIC__) || (defined(__sun) && !defined(__illumos__))
    // pthread_getattr_np is a GNU extension supported in glibc.
    // Solaris is not glibc but does support pthread_getattr_np
    // (and the fallback doesn't work...). Illumos does not.
    pthread_getattr_np(pthread_self(), &attr);  // GNU extension
    pthread_attr_getstack(&attr, &addr, &size); // low address
#elif defined(__illumos__)
    pthread_attr_get_np(pthread_self(), &attr);
    pthread_attr_getstack(&attr, &addr, &size); // low address
#else
    // We don't know how to get the current stacks, leave it as
    // 0 and the caller will use an estimate based on the current
    // SP.
    addr = 0;
    size = 0;
#endif

    pthread_attr_destroy(&attr);

    // bounds points into the Go stack. TSAN can't see the synchronization
    // in Go around stack reuse.
    _cgo_tsan_acquire();
    bounds[0] = (uintptr)addr;
    bounds[1] = (uintptr)addr + size;
    _cgo_tsan_release();
}

#include "ReduceGlobalVarInitializers.h"
#include "llvm/IR/Constants.h"
#include "llvm/IR/GlobalValue.h"

using namespace llvm;

/// Removes all the Initialized GVs that aren't inside the desired Chunks.
static void extractGVsFromModule(Oracle &O, ReducerWorkItem &WorkItem)
{
    // Drop initializers of out-of-chunk GVs
    for (auto &GV : WorkItem.getModule().globals())
        if (GV.hasInitializer() && !O.shouldKeep())
        {
            GV.setInitializer(nullptr);
            GV.setLinkage(GlobalValue::LinkageTypes::ExternalLinkage);
            GV.setComdat(nullptr);
        }
}

void llvm::reduceGlobalsInitializersDeltaPass(TestRunner &Test)
{
    runDeltaPass(Test, extractGVsFromModule, "Reducing GV Initializers");
}

