size_t TLogBackend::QueueSize() const {
    ythrow yexception() << "Not implemented.";
}

#include <iostream>
#include <vector>
#include <utility>
#include <numeric>

// Global variables for number of pillars and balls per pillar
int n, m;
std::vector<int> pillars[55];
std::vector<std::pair<int, int>> moves;

// Move a single ball from one pillar to another
void move_ball(int from, int to) {
    if (from == to || pillars[from].empty()) {
        return;
    }
    int ball = pillars[from].back();
    pillars[from].pop_back();
    pillars[to].push_back(ball);
    moves.push_back({from, to});
}

// Move all balls from one pillar to another
void move_all(int from, int to) {
    while (!pillars[from].empty()) {
        move_ball(from, to);
    }
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    // Read input values
    std::cin >> n >> m;
    for (int i = 1; i <= n; ++i) {
        pillars[i].resize(m);
        for (int j = 0; j < m; ++j) {
            std::cin >> pillars[i][j];
        }
    }

    // Strategy: Sort colors one by one. For color i, move all balls of color i to pillar i.
    // Pillars 1 to i-1 are already sorted.
    for (int i = 1; i <= n; ++i) {
        // First, move all balls from unsorted pillars (i to n) to the buffer pillar (n+1).
        for (int j = i; j <= n; ++j) {
            move_all(j, n + 1);
        }

        // Now, redistribute balls from n+1.
        // Balls of color i go to pillar i.
        // Balls of other colors k > i go to pillar k (as temporary storage for the next steps).
        while (!pillars[n + 1].empty()) {
            int ball_color = pillars[n + 1].back();
            if (ball_color == i) {
                move_ball(n + 1, i);
            } else {
                move_ball(n + 1, ball_color);
            }
        }

        // At this point, pillar i is sorted and full.
        // The remaining balls are on their respective destination pillars, ready for the next iteration.
    }

    // Output the result
    std::cout << moves.size() << "\n";
    for (const auto& move : moves) {
        std::cout << move.first << " " << move.second << "\n";
    }

    return 0;
}

#include <asio/io_context.hpp>
#include <asio/ip/tcp.hpp>
#include <asio/spawn.hpp>
#include <asio/steady_timer.hpp>
#include <asio/write.hpp>
#include <iostream>
#include <memory>

using asio::ip::tcp;

// Session class for handling client connections
class session : public std::enable_shared_from_this<session>
{
public:
  explicit session(tcp::socket socket)
    : socket_(std::move(socket)),
      timer_(socket_.get_io_context()),
      strand_(socket_.get_io_context())
  {
  }

  void go()
  {
    auto self(shared_from_this());

    // Echo handler coroutine
    asio::spawn(strand_,
        [this, self](asio::yield_context yield)
        {
          try
          {
            char data[128];
            for (;;)
            {
              timer_.expires_from_now(std::chrono::seconds(10));
              std::size_t n = socket_.async_read_some(asio::buffer(data), yield);
              asio::async_write(socket_, asio::buffer(data, n), yield);
            }
          }
          catch (std::exception& e)
          {
            socket_.close();
            timer_.cancel();
          }
        });

    // Timeout handler coroutine
    asio::spawn(strand_,
        [this, self](asio::yield_context yield)
        {
          while (socket_.is_open())
          {
            asio::error_code ignored_ec;
            timer_.async_wait(yield[ignored_ec]);
            if (timer_.expires_from_now() <= std::chrono::seconds(0))
              socket_.close();
          }
        });
  }

private:
  tcp::socket socket_;
  asio::steady_timer timer_;
  asio::io_context::strand strand_;
};

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 2)
    {
      std::cerr << "Usage: echo_server <port>\n";
      return 1;
    }

    asio::io_context io_context;

    // Main acceptor coroutine
    asio::spawn(io_context,
        [&](asio::yield_context yield)
        {
          tcp::acceptor acceptor(io_context,
            tcp::endpoint(tcp::v4(), std::atoi(argv[1])));
          for (;;)
          {
            asio::error_code ec;
            tcp::socket socket(io_context);
            acceptor.async_accept(socket, yield[ec]);
            if (!ec) std::make_shared<session>(std::move(socket))->go();
          }
        });

    io_context.run();
  }
  catch (std::exception& e)
  {
    std::cerr << "Exception: " << e.what() << "\n";
  }

  return 0;
}

