#include <vector>
#include <bit>

class Solution {
public:
    // Precomputed values for expSum4
    long long expSum4[18] = {1};

    // Helper function to compute expSum
    long long expSum(unsigned x) {
        if (x == 0) return 0;
        int log4 = (31 - countl_zero(x)) / 2;
        int r = x - (1 << (2 * log4));
        return expSum4[log4] + r * (log4 + 1LL);
    }

    long long minOperations(vector<vector<int>>& queries) {
        // Fill expSum4 array
        for (int i = 1; i < 18; i++) {
            expSum4[i] = expSum4[i - 1] + 3LL * i * (1LL << (2 * (i - 1))) + 1;
        }

        long long op = 0;
        for (auto& q : queries) {
            int l = q[0] - 1, r = q[1];
            op += (expSum(r) - expSum(l) + 1) / 2;
        }
        return op;
    }
};

