// Forward declare the "fuzz target" interface.
// We deliberately keep this interface simple and header-free.
extern "C" int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size);

// Main function to process input files and feed them to the fuzz target
int main(int argc, char **argv)
{
    for (int i = 1; i < argc; i++)
    {
        std::ifstream in(argv[i]);
        in.seekg(0, in.end);
        size_t length = static_cast<size_t>(in.tellg());
        in.seekg(0, in.beg);
        std::cout << "Reading " << length << " bytes from " << argv[i] << std::endl;
        // Allocate exactly length bytes so that we reliably catch buffer overflows.
        std::vector<char> bytes(length);
        in.read(bytes.data(), static_cast<std::streamsize>(bytes.size()));
        LLVMFuzzerTestOneInput(reinterpret_cast<const uint8_t *>(bytes.data()),
                               bytes.size());
        std::cout << "Execution successful" << std::endl;
    }
    std::cout << "Execution finished" << std::endl;
    return 0;
}

#include <iostream>
using namespace std;

// Main function to navigate based on distance queries
int main()
{
    int curDist;
    cin >> curDist;

    // color of the edge we arrived from, -1 initially
    int lastMove = -1;

    while (curDist > 0)
    {
        // try the two colors that are not the one we came from
        for (int c = 0; c < 3; ++c)
        {
            if (c == lastMove) continue;

            // move along color c
            cout << "move " << c << endl;
            int moveResult;
            cin >> moveResult;

            if (moveResult == 1)
            {
                // reached the exit
                return 0;
            }

            // query the new distance
            cout << "query" << endl;
            int newDist;
            cin >> newDist;

            if (newDist < curDist)
            {
                // this move decreased the distance
                curDist = newDist;
                lastMove = c;  // remember the edge we used
                break;         // proceed to the next step
            }
            else
            {
                // this move increased the distance, move back
                cout << "move " << c << endl;
                cin >> moveResult;

                if (moveResult == 1)
                {
                    // reached the exit while moving back (unlikely but handled)
                    return 0;
                }

                // after moving back we are at the original node, distance unchanged
            }
        }
    }

    // If curDist becomes 0, we are already at the exit.
    return 0;
}

