#include <vector>
#include <string>
#include <unordered_map>

class Solution {
public:
    // Removes anagrams from the list
    vector<string> removeAnagrams(vector<string>& words) {
        // Frequency map for each word
        vector<unordered_map<char, int>> freq(words.size());

        // Build frequency maps
        for (int i = 0; i < words.size(); i++) {
            for (char ch : words[i]) {
                freq[i][ch]++;
            }
        }

        vector<string> ans;
        // Always include the first word
        ans.push_back(words[0]);

        // Compare with previous word's frequency map
        for (int i = 1; i < words.size(); i++) {
            if (freq[i] != freq[i - 1]) {
                ans.push_back(words[i]);
            }
        }

        return ans;
    }
};

