namespace Karm::Aio {

// Adapter for making types conform to Reader/Writer interface
export template <typename T>
struct Adapter : Reader, Writer {
    T& _inner;

    // Constructor
    Adapter(T& inner)
        : _inner(inner) {}

    // Write implementation
    Async::Task<usize> writeAsync(Bytes buf, Async::CancellationToken) override {
        if constexpr (Io::Writable<T>) {
            co_return _inner.write(buf);
        } else {
            co_return Ok(buf.len());
        }
    }

    // Read implementation
    Async::Task<usize> readAsync(MutBytes buf, Async::CancellationToken) override {
        if constexpr (Io::Readable<T>) {
            co_return _inner.read(buf);
        } else {
            co_return Ok(0);
        }
    }
};

// Helper function to create an adapter
export template <typename T>
Adapter<T> adapt(T& t) {
    return {t};
}

} // namespace Karm::Aio

#include "wifi_power.h"
#include <WiFi.h>
#include <Preferences.h>
// Additional includes for WiFi functionality
#include "wifi_power.h"
#include "wifi_store.h"

// Applies Wi-Fi power settings based on enable flag
void applyWifiPower(bool enable)
{
    if (!enable) 
    {
        // Disable Wi-Fi auto-reconnect and disconnect
        WiFi.setAutoReconnect(false);
        WiFi.disconnect(true, true);
        WiFi.mode(WIFI_OFF);
        return;
    }

    // Enable Wi-Fi in station mode
    WiFi.mode(WIFI_STA);
    WiFi.setAutoReconnect(true);

    String ssid, pass;
    if (wifiStoreLoad(ssid, pass)) 
    {
        // Connect using stored credentials
        WiFi.begin(ssid.c_str(), pass.c_str());
    } 
    else 
    {
        // No credentials stored => do NOT attempt connection
        WiFi.setAutoReconnect(false);
        WiFi.disconnect(true, true);
    }
}

// Resets Wi-Fi settings by clearing stored credentials
void wifiResetSettings()
{
    // Clear stored credentials (matches console code namespace/keys)
    Preferences prefs;
    prefs.begin("rh_wifi", false);
    prefs.putString("ssid", "");
    prefs.putString("pass", "");
    prefs.end();

    // Disconnect from current network
    WiFi.disconnect(true, true);
    delay(50);
}

