#include <mplot/HexGridVisual.h>

// Main function demonstrating grid resampling and visualization
int main()
{
    // Create visualizer with specified dimensions and title
    mplot::Visual v(1400, 1300, "Demo of grid showing a resampled image");

    // Set scene transformation (camera position)
    v.setSceneTrans(sm::vec<float,3>({-2.60691f, 1.39885f, -11.1f}));

    // Define scaling factor for grid resolution
    unsigned int scaledown = 2U;

    // Original grid spacing
    sm::vec<float, 2> dx = {0.02f, 0.02f};

    // Coarser grid spacing after resampling
    sm::vec<float, 2> dx2 = dx * scaledown;

    // Top left to bottom right order matches image loaded by loadpng and avoids the need for a
    // vec<bool, 2> flip arg to mplot::loadpng.

    // Create original grid g1 with 256x64 cells
    sm::grid g1(256U, 64U, dx);
    std::cout << "g1 extents: (xmin,xmax,ymin,ymax): " << g1.extents() << std::endl;

    // Create coarser grid g2 by reducing cell count
    sm::grid g2(256U/scaledown, 64U/scaledown, dx2);
    std::cout << "g2 extents: (xmin,xmax,ymin,ymax): " << g2.extents() << std::endl;

    // Load image from file
    std::string fn = "../examples/bike256_64.png";
    sm::vvec<float> image_data; // image loaded BLTR by default
    sm::vec<unsigned int, 2> dims = mplot::loadpng(fn, image_data);
    std::cout << "Image dims: " << dims << std::endl;

    // Validate image dimensions
    if (dims[0] != 256) {
        std::cerr << "Wrong image width!\n";
        return -1;
    }

    // Resample image onto coarser grid
    // Scale factors for resampling (no scaling in this case)
    sm::vec<float,2> image_scale = {1.0f, 1.0f};

    // Optional offset for image positioning (none here)
    sm::vec<float,2> image_offset = {0.0f, 0.0f};

    // Perform resampling on regular grid
    sm::vvec<float> img_resampled = g2.resample_image(image_data, dims[0], image_scale, image_offset);

    // Also resample onto hexagonal grid for comparison
    sm::vec<float, 2> g2_dx = g2.get_dx();
    sm::hexgrid hg(g2_dx[0], g2.width()*2.0f, 0.0f);

    // Set rectangular boundary matching g2's dimensions
    hg.setRectangularBoundary(g2.width(), g2.height());

    // Hexgrid-specific resampling parameters
    // Note: hexgrids require special scaling since they're not naturally rectangular
    sm::vec<float,2> hex_image_scale = {g2.width(), g2.width()};
    sm::vvec<float> hex_image_data = hg.resampleImage(image_data, dims[0], hex_image_scale, image_offset);

    // Visualize original image using GridVisual
    auto gv1 = std::make_unique<mplot::GridVisual<float>>(&g1, sm::vec<float>({0,0,0}));
    v.bindmodel(gv1);
    gv1->gridVisMode = mplot::GridVisMode::RectInterp;
    gv1->setScalarData(&image_data);
    gv1->cm.setType(mplot::ColourMapType::GreyscaleInv); // Inverse greyscale for monochrome images
    gv1->zScale.null_scaling(); // Disable relief effect for flat image display
    gv1->addLabel("Original", {0, -0.2, 0}, mplot::TextFeatures(0.1f));
    gv1->finalize();
    v.addVisualModel(gv1);

    // Visualize resampled grid data
    auto gv2 = std::make_unique<mplot::GridVisual<float>>(&g2, sm::vec<float>{0.0f, -2.0f, 0.0f});
    v.bindmodel(gv2);
    gv2->gridVisMode = mplot::GridVisMode::RectInterp;
    gv2->setScalarData(&img_resampled);
    gv2->cm.setType(mplot::ColourMapType::GreyscaleInv);
    gv2->zScale.null_scaling();
    gv2->addLabel("Resampled to coarser grid", {0, -0.2, 0}, mplot::TextFeatures(0.1f));
    gv2->finalize();
    v.addVisualModel(gv2);

    // Visualize hexgrid resampling result
    auto hgv = std::make_unique<mplot::HexGridVisual<float>>(&hg, sm::vec<float>{g2.width()/2.0f, g2.height()/2.0f - 4.0f, 0.0f});
    v.bindmodel(hgv);
    hgv->setScalarData(&hex_image_data);
    hgv->cm.setType(mplot::ColourMapType::GreyscaleInv);
    hgv->zScale.null_scaling();
    hgv->addLabel("Resampled to hexgrid", {-g2.width()/2.0f, -0.2f - g2.height()/2.0f, 0}, mplot::TextFeatures(0.1f));
    hgv->finalize();
    v.addVisualModel(hgv);

    // Keep window open until user closes it
    v.keepOpen();

    return 0;
}

#include "llvm/IR/DiagnosticHandler.h"
#include "llvm/Support/CommandLine.h"
#include "llvm/Support/Regex.h"

using namespace llvm;

namespace {

/// Regular expression corresponding to the value given in one of the
/// -pass-remarks* command line flags. Passes whose name matches this regexp
/// will emit a diagnostic when calling the associated diagnostic function
/// (emitOptimizationRemark, emitOptimizationRemarkMissed or
/// emitOptimizationRemarkAnalysis).
struct PassRemarksOpt {
  std::shared_ptr<Regex> Pattern;

  void operator=(const std::string &Val) {
    // Create a regexp object to match pass names for emitOptimizationRemark.
    if (!Val.empty()) {
      Pattern = std::make_shared<Regex>(Val);
      std::string RegexError;
      if (!Pattern->isValid(RegexError))
        report_fatal_error(Twine("Invalid regular expression '") + Val +
                               "' in -pass-remarks: " + RegexError,
                           false);
    }
  }
};

static PassRemarksOpt PassRemarksPassedOptLoc;
static PassRemarksOpt PassRemarksMissedOptLoc;
static PassRemarksOpt PassRemarksAnalysisOptLoc;

// -pass-remarks
//    Command line flag to enable emitOptimizationRemark()
static cl::opt<PassRemarksOpt, true, cl::parser<std::string>> PassRemarks(
    "pass-remarks", cl::value_desc("pattern"),
    cl::desc("Enable optimization remarks from passes whose name match "
             "the given regular expression"),
    cl::Hidden, cl::location(PassRemarksPassedOptLoc), cl::ValueRequired);

// -pass-remarks-missed
//    Command line flag to enable emitOptimizationRemarkMissed()
static cl::opt<PassRemarksOpt, true, cl::parser<std::string>> PassRemarksMissed(
    "pass-remarks-missed", cl::value_desc("pattern"),
    cl::desc("Enable missed optimization remarks from passes whose name match "
             "the given regular expression"),
    cl::Hidden, cl::location(PassRemarksMissedOptLoc), cl::ValueRequired);

// -pass-remarks-analysis
//    Command line flag to enable emitOptimizationRemarkAnalysis()
static cl::opt<PassRemarksOpt, true, cl::parser<std::string>>
    PassRemarksAnalysis(
        "pass-remarks-analysis", cl::value_desc("pattern"),
        cl::desc(
            "Enable optimization analysis remarks from passes whose name match "
            "the given regular expression"),
        cl::Hidden, cl::location(PassRemarksAnalysisOptLoc), cl::ValueRequired);

}

bool DiagnosticHandler::isAnalysisRemarkEnabled(StringRef PassName) const {
  return (PassRemarksAnalysisOptLoc.Pattern &&
          PassRemarksAnalysisOptLoc.Pattern->match(PassName));
}

bool DiagnosticHandler::isMissedOptRemarkEnabled(StringRef PassName) const {
  return (PassRemarksMissedOptLoc.Pattern &&
          PassRemarksMissedOptLoc.Pattern->match(PassName));
}

bool DiagnosticHandler::isPassedOptRemarkEnabled(StringRef PassName) const {
  return (PassRemarksPassedOptLoc.Pattern &&
          PassRemarksPassedOptLoc.Pattern->match(PassName));
}

bool DiagnosticHandler::isAnyRemarkEnabled() const {
  return (PassRemarksPassedOptLoc.Pattern || PassRemarksMissedOptLoc.Pattern ||
          PassRemarksAnalysisOptLoc.Pattern);
}

#include "Alias/TPA/PointerAnalysis/Engine/GlobalState.h"
#include "Alias/TPA/PointerAnalysis/Engine/TransferFunction.h"
#include "Alias/TPA/PointerAnalysis/Program/CFG/CFG.h"

namespace tpa {

// Evaluates entry node for transfer function
void TransferFunction::evalEntryNode(const ProgramPoint &pp,
                                     EvalResult &evalResult)
{
    assert(localState != nullptr);

    // Add top-level and memory-level successors
    addTopLevelSuccessors(pp, evalResult);
    addMemLevelSuccessors(pp, *localState, evalResult);

    // To prevent the analysis from converging before a newly added return edge
    // is processed, we need to force the analysis to check the return targets
    // whenever a function is entered.
    //
    // Note: this unconditional enqueue is intentional. The SemiSparsePropagator
    // uses a memoization table (Memo) and will only actually re-process the exit
    // node if the store state at that point has changed. So while this enqueues
    // the exit node on every entry visit, the propagator suppresses redundant
    // work via memo-table checks, keeping the overall fixpoint correct and
    // terminating.

    auto &cfg = pp.getCFGNode()->getCFG();
    if (!cfg.doesNotReturn())
        evalResult.addTopLevelProgramPoint(
            ProgramPoint(pp.getContext(), cfg.getExitNode()));
}

} // namespace tpa

#define SOL_ALL_SAFETIES_ON 1
#include <sol/sol.hpp>
#include <vector>
#include <iostream>

// Main function entry point
int main(int, char**)
{
    std::cout << "=== containers ===" << std::endl;

    // Create Lua state and open libraries
    sol::state lua;
    lua.open_libraries();

    // Define Lua function f to print container contents
    lua.script(R"(
function f (x)
	print("container has:")
	for k=1,#x do
		v = x[k]
		print("\t", k, v)
	end
	print()
end
	)");

    // Get the Lua function
    sol::function f = lua["f"];

    // Set global variable 'arr' to a vector of 5 elements
    lua["arr"] = std::vector<int> { 2, 4, 6, 8, 10 };

    // Call function with initial vector
    f(lua["arr"]);

    // Access and modify vector in C++
    // Containers are stored as userdata unless using sol::as_table
    std::vector<int>& reference_to_arr = lua["arr"];
    reference_to_arr.push_back(12);

    // Call function after modification - now 6 elements
    f(lua["arr"]);

    // Add element via Lua method
    lua.script(R"(
arr:add(28)
	)");

    // Call function - now 7 elements
    f(lua["arr"]);

    // Clear the array in Lua
    lua.script(R"(
arr:clear()
	)");

    // Now it's empty
    f(lua["arr"]);

    std::cout << std::endl;
    return 0;
}

#include <hip/hip_runtime.h>
#include <cstddef>
#include <cstdlib>
#include <iostream>

// Main function demonstrating HIP per-thread stream usage
int main()
{
    // Initialize the HIP runtime
    if(auto err = hipInit(0); err != hipSuccess)
    {
        std::cerr << "Failed to initialize HIP runtime." << std::endl;
        return EXIT_FAILURE;
    }

    // Get the per-thread default stream
    hipStream_t stream = hipStreamPerThread;

    // Use the stream for some operation
    // For example, allocate memory on the device
    void* d_ptr;
    std::size_t size = 1024;

    if(auto err = hipMalloc(&d_ptr, size); err != hipSuccess)
    {
        std::cerr << "Failed to allocate memory." << std::endl;
        return EXIT_FAILURE;
    }

    // Perform some operation using the stream
    // For example, set memory on the device
    if(auto err = hipMemsetAsync(d_ptr, 0, size, stream); err != hipSuccess)
    {
        std::cerr << "Failed to set memory." << std::endl;
        return EXIT_FAILURE;
    }

    // Synchronize the stream
    if(auto err = hipStreamSynchronize(stream); err != hipSuccess)
    {
        std::cerr << "Failed to synchronize stream." << std::endl;
        return EXIT_FAILURE;
    }

    // Free the allocated memory
    if(auto err = hipFree(d_ptr); err != hipSuccess)
    {
        std::cerr << "Failed to free memory." << std::endl;
        return EXIT_FAILURE;
    }

    std::cout << "Operation completed successfully using per-thread default stream." << std::endl;
    return EXIT_SUCCESS;
}

