// Flip the color
EnumSwitchQualified::Outer::color
EnumSwitchQualified::Outer::flip(const EnumSwitchQualified::Outer::color c)
{
    return [&](void) {
        switch (c) {
            case color::Red: {
                return color::Blue;
            }
            case color::Blue: {
                return color::Red;
            }
        }
    }();
}

// Get code for color
unsigned int
EnumSwitchQualified::Outer::code(const EnumSwitchQualified::Outer::color c)
{
    return [&](void) {
        switch (c) {
            case color::Red: {
                return (0 + 1);
            }
            case color::Blue: {
                return ((0 + 1) + 1);
            }
        }
    }();
}

