using asio::post;
using asio::thread_pool;

// Traditional active object pattern.
// Member functions do not block.
class bank_account
{
  int balance_ = 0;
  mutable thread_pool pool_{1};

public:
  void deposit(int amount)
  {
    post(pool_, [=]
      {
        balance_ += amount;
      });
  }

  void withdraw(int amount)
  {
    post(pool_, [=]
      {
        if (balance_ >= amount)
          balance_ -= amount;
      });
  }

  void print_balance() const
  {
    post(pool_, [=]
      {
        std::cout << "balance = " << balance_ << "\n";
      });
  }

  ~bank_account()
  {
    pool_.join();
  }
};

int main()
{
  bank_account acct;
  acct.deposit(20);
  acct.withdraw(10);
  acct.print_balance();

  return 0;
}

#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>

// Function to perform a swap operation via interaction.
void do_swap(int i, int j)
{
    if (i == j) return;
    std::cout << "2 " << i << " " << j << std::endl;
    int dummy;
    std::cin >> dummy;
}

// Function to perform a query operation via interaction.
int do_ask(int l, int r)
{
    std::cout << "1 " << l << " " << r << std::endl;
    int res;
    std::cin >> res;
    return res;
}

// Function to output the final answer.
void do_answer(const std::vector<int>& p)
{
    std::cout << "3";
    for (size_t i = 1; i < p.size(); ++i)
    {
        std::cout << " " << p[i];
    }
    std::cout << std::endl;
}

int main()
{
    // Fast I/O
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    int n, l1, l2;
    std::cin >> n >> l1 >> l2;

    // `pos[i]` stores the original index of the element currently at position `i`.
    // Initially, the element at position `i` is the one that started at index `i`.
    std::vector<int> pos(n + 1);
    std::iota(pos.begin(), pos.end(), 0);

    // The core strategy is to build a chain of value-adjacent elements one by one.
    // We place the elements of this chain at positions 1, 2, 3, ...
    // At step `i`, we have a chain of `i` elements at positions 1 to `i`.
    // We then find a value-neighbor of the element at position `i` from the
    // remaining elements (at positions `i+1` to `n`) and move it to position `i+1`.
    for (int i = 1; i < n; ++i)
    {
        // The element at position `i` is our current pivot. We search for its neighbor.
        // The search space for the neighbor is positions `i+1` through `n`.
        for (int j = i + 1; j <= n; ++j)
        {
            // Bring the element from position `j` to position `i+1` to test it.
            do_swap(i + 1, j);
            std::swap(pos[i + 1], pos[j]);

            // A query on `[i, i+1]` can tell us if `p[i]` and `p[i+1]` have adjacent values.
            // `ask(i, i+1)` returns the number of value-contiguous subsegments in `p[i..i+1]`.
            // These are `[p[i]]`, `[p[i+1]]`, and potentially `[p[i], p[i+1]]`.
            // So, `ask(i, i+1)` is 3 if `p[i]` and `p[i+1]` are value-adjacent, and 2 otherwise.
            if (do_ask(i, i + 1) == 3)
            {
                // We found a neighbor. It's now at position `i+1`. We leave it there
                // and proceed to extend the chain from this new element.
                break;
            }

            // If it's not a neighbor, we swap back to restore the original state of this step
            // to correctly test the next candidate from its original position.
            do_swap(i + 1, j);
            std::swap(pos[i + 1], pos[j]);
        }
    }

    // After the loops, the elements at positions 1, 2, ..., n form a chain
    // of value-adjacent numbers. This means their original values form a
    // monotonic sequence of consecutive integers. Since it's a permutation of 1 to n,
    // this sequence must be either (1, 2, ..., n) or (n, n-1, ..., 1).
    // Let's assume one of these, say (1, 2, ..., n).
    // The element originally at `pos[i]` is now at position `i`, so we assign it value `i`.
    std::vector<int> ans(n + 1);
    for (int i = 1; i <= n; ++i)
    {
        ans[pos[i]] = i;
    }

    // The problem statement guarantees that `p` and `n+1-p` are indistinguishable.
    // Our constructed answer is one of these two possibilities.
    do_answer(ans);

    return 0;
}

#include <format>
#include <sm/vvec>
#include <mplot/Visual.h>
#include <mplot/GraphVisual.h>

int main()
{
    // Set up a mplot::Visual 'scene environment'.
    mplot::Visual v(1024, 768, "Made with mplot::GraphVisual");

    // Create a GraphVisual object (obtaining a unique_ptr to the object) with a spatial offset within the scene of 0,0,0
    auto gv = std::make_unique<mplot::GraphVisual<double>>(sm::vec<float>{0.0f, 0.0f, 0.0f});

    // This mandatory line of boilerplate code sets the parent pointer in GraphVisual and binds some functions
    v.bindmodel(gv);

    // Data for the x axis. A vvec is like std::vector, but with built-in maths methods
    sm::vvec<double> x;

    // This works like numpy's linspace() (the 3 args are "start", "end" and "num"):
    x.linspace(0, 10, 11);

    // Hand chosen numbers
    sm::vvec<double> y = {5, 8, 2, 9, 1, 2, 4, 5, 8, 3, 1};

    // Choose a line graph by creating a lines stylepolicy datasetstyle.
    mplot::DatasetStyle ds(mplot::stylepolicy::lines);
    ds.linecolour = mplot::colour::crimson;

    // For this graph, set manual y axis limits
    gv->setlimits_y(0, 10);

    // Now set the data
    gv->setdata(x, y, ds);

    // A second DatasetStyle is used to specify a colour and linewidth for a horizontal line at y=7.
    mplot::DatasetStyle ds_horz(mplot::stylepolicy::lines);
    ds_horz.linecolour = mplot::colour::grey68;
    ds_horz.linewidth = ds.linewidth * 0.6f;

    // Find, and annotate with vertical lines, the locations where the graph crosses
    // y=7. The x values of the crossing points are returned.
    sm::vvec<double> xcross = gv->add_y_crossing_lines(x, y, 7, ds, ds_horz);

    // Use results in xcross to annotate the graph
    size_t n = xcross.size();
    std::stringstream ss;

    if (n > 0)
    {
        // Loop through the elements of xcross, formatting a string
        for (size_t i = 0; i < n; ++i)
        {
            ss << std::format("{}{}{:.2f}", ((i == 0 || i == n - 1) ? "" : ", "), (i == (n - 1) ? " and " : ""), xcross[i]);
        }
    }
    else
    {
        ss << "[no values]";
    }

    // Add a label at location {.05, .05, 0} with fontsize 0.03
    gv->addLabel(std::format("y=7 at x = {:s}", ss.str()), {0.05f, 0.05f, 0.0f}, mplot::TextFeatures(0.03f));

    // finalize() makes the GraphVisual compute the vertices of the OpenGL model
    gv->finalize();

    // Add the GraphVisual OpenGL model to the Visual scene, transferring ownership of the unique_ptr
    v.addVisualModel(gv);

    // Render the scene on the screen until user quits with 'Ctrl-q'
    v.keepOpen();

    // Because v owns the unique_ptr to the GraphVisual, its memory will be deallocated when v goes out of scope.
    return 0;
}

#include <iostream>
