using namespace db;

// PipelineExecutor constructor
PipelineExecutor::PipelineExecutor(PipelineV2* pipeline,
                                   ExecutionContext* ctxt)
    : _pipeline(pipeline),
      _ctxt(ctxt)
{
}

// Destructor
PipelineExecutor::~PipelineExecutor()
{
}

// Initialize the executor by pushing all source processors onto the active stack
void PipelineExecutor::init()
{
    auto& activeStack = _activeStack;
    for (Processor* source : _pipeline->sources())
    {
        activeStack.push(source);
    }
}

// Execute the entire pipeline until no more work remains
void PipelineExecutor::execute()
{
    init();
    while (!_activeStack.empty())
    {
        executeCycle();
    }
}

// Execute a single cycle of the pipeline
void PipelineExecutor::executeCycle()
{
    auto& activeStack = _activeStack;
    auto& updateQueue = _updateQueue;

    // Find the first processor that can execute in _activeStack.
    // We may add processors to the activeStack such as count, that are not finished,
    // but cannot execute because they have no inputs yet.
    //
    // Processors that cannot execute have to be popped off to prevent the stack from growing too large.
    // They will be re-executed later via the update queue propagation.
    //
    // We do not lose processors by popping them off because eventually the remaining
    // processors will be source processors at the bottom of the stack.
    {
        while (!_activeStack.empty())
        {
            Processor* proc = _activeStack.top();
            _activeStack.pop();
            if (proc->canExecute())
            {
                _updateQueue.push(proc);
                break;
            }
        }
    }

    // Execute processors from the update queue
    while (!updateQueue.empty())
    {
        Processor* currentProc = updateQueue.front();
        updateQueue.pop();

        if (!currentProc->isPrepared())
        {
            currentProc->prepare(_ctxt);
        }

        if (currentProc->isFinished())
        {
            currentProc->reset();
        }

        currentProc->execute();

        // If the processor is not finished after this step, push it back to the active stack
        if (!currentProc->isFinished())
        {
            activeStack.push(currentProc);
        }

        currentProc->setScheduled(false);

        // Add all ready successors to the update queue
        for (PipelineOutputPort* output : currentProc->outputs())
        {
            PipelineInputPort* connectedPort = output->getConnectedPort();
            if (connectedPort)
            {
                Processor* nextProc = connectedPort->getProcessor();
                if (!nextProc->isScheduled() && nextProc->canExecute())
                {
                    updateQueue.push(nextProc);
                    nextProc->setScheduled(true);
                }
            }
        }
    }
}

