// Function to create and write to file
void create()
{
    ofstream adc;
    char str[80], ch;
    adc.open("hello");
    if(adc.fail())
    {
        cout << "unable to open the file" << endl;
        getch();
        exit(1);
    }
    do
    {
        cout << "enter the text to store";
        fflush(stdin);
        gets(str);
        //cin.getline(str,80);
        adc << str << endl;
        cout << "would you like to continue....(y/n)";
        fflush(stdin);
        cin >> ch;
    } while(ch == 'y' || ch == 'Y');
    adc.close();
}

// Function to display file contents
void display()
{
    ifstream pqr;
    char ch;
    cout << "the contents of the file are" << endl;
    pqr.open("hello");
    if(pqr.fail())
    {
        getch();
        exit(1);
    }
    while(!pqr.eof())
    {
        pqr.get(ch);
        //cout<<ch;
        cout.put(ch);
    }
    pqr.close();
}

int main()
{
    create();
    display();
    return 0;
}

