MainWindow::MainWindow(QWidget *parent)
    : QMainWindow(parent)
    , ui(new Ui::MainWindow)
{
    // Initialize UI and visualization components
    ui->setupUi(this);
    this->viswidget_init();
    // Set up initial HexGridVisual
    this->setupHexGridVisual();
}

MainWindow::~MainWindow()
{
    delete ui;
}

void MainWindow::setupHexGridVisual()
{
    // First set up the hexgrid
    this->hg = std::make_unique<sm::hexgrid>(0.01f, 3.0f, 0.0f);
    this->hg->setCircularBoundary(0.6f);

    // Make some dummy data (with sine waves) to make a non-flat surface
    this->data.resize(this->hg->num(), 0.0f);
    for(unsigned int ri=0; ri<this->hg->num(); ++ri)
    {
        // Compute scalar field using product of sine functions
        this->data[ri] = 0.05f + 0.05f*std::sin(20.0f*hg->d_x[ri]) * std::sin(10.0f*hg->d_y[ri]);
    }

    // Now create the HexGridVisual
    sm::vec<float, 3> offset = {0.0f, -0.05f, 0.0f};
    auto hgv = std::make_unique<mplot::HexGridVisual<float, mplot::qt::gl_version>>(hg.get(), offset);

    // Bind model before finalize() — important for shader access and parent context
    static_cast<mplot::qt::viswidget<0>*>(this->p_vw)->v.bindmodel(hgv);

    // Assign scalar data to the visual
    hgv->setScalarData(&this->data);

    // Cast to base VisualModel type and add to list
    std::unique_ptr<mplot::VisualModel<mplot::qt::gl_version>> vmp = std::move(hgv);
    static_cast<mplot::qt::viswidget<0>*>(this->p_vw)->newvisualmodels.push_back(std::move(vmp));
}

void MainWindow::viswidget_init()
{
    // Create OpenGL visualization widget
    mplot::qt::viswidget<0>* vw = new mplot::qt::viswidget<0>(this->parentWidget());

    // Enable lighting effects
    vw->v.lightingEffects();

    // Add widget to layout
    this->ui->verticalLayout->addWidget(vw);

    // Store pointer for later use
    this->p_vw = vw;
}

void MainWindow::on_pushButton_clicked()
{
    std::cout << "Adding a GraphVisual...\n";

    // Create new GraphVisual instance
    auto gv = std::make_unique<mplot::GraphVisual<double, mplot::qt::gl_version>>(this->graphlocn);

    // Bind to main visual environment
    static_cast<mplot::qt::viswidget<0>*>(this->p_vw)->v.bindmodel(gv);

    // Configure as 3D graph
    gv->twodimensional(false);

    // Generate x data and compute y = x^2
    sm::vvec<double> x;
    x.linspace(-1.5, 1.5, 25);
    gv->setdata(x, x.pow(2));

    // Cast and add to visual models list
    std::unique_ptr<mplot::VisualModel<mplot::qt::gl_version>> vmp = std::move(gv);
    static_cast<mplot::qt::viswidget<0>*>(this->p_vw)->newvisualmodels.push_back(std::move(vmp));

    // Force immediate render update
    this->p_vw->update();

    // Shift next graph vertically
    this->graphlocn[1] += 1.2f;
}

void MainWindow::on_actionQuit_triggered()
{
    close();
}

#define BOOST_TEST_MODULE elias_fano
#include "test_common.hpp"
#include "test_rank_select_common.hpp"
#include <cstdlib>
#include <boost/foreach.hpp>
#include "mapper.hpp"
#include "elias_fano.hpp"

// Test case for elias_fano compression
BOOST_AUTO_TEST_CASE(elias_fano)
{
    srand(42);
    size_t N = 10000;

    {
        // Random bitmap
        for (size_t d = 1; d < 8; ++d) {
            double density = 1.0 / (1 << d);
            std::vector<bool> v = random_bit_vector(N, density);
            succinct::bit_vector_builder bvb;
            for (size_t i = 0; i < v.size(); ++i) {
                bvb.push_back(v[i]);
            }
            succinct::elias_fano bitmap(&bvb);
            test_equal_bits(v, bitmap, "Random bitmap");
            test_rank_select1(v, bitmap, "Random bitmap");
            test_delta(bitmap, "Random bitmap");
            test_select_enumeration(v, bitmap, "Random bitmap");
        }
    }

    {
        // Empty bitmap
        succinct::bit_vector_builder bvb(N);
        succinct::elias_fano bitmap(&bvb);
        BOOST_REQUIRE_EQUAL(0U, bitmap.num_ones());
        test_equal_bits(std::vector<bool>(N), bitmap, "Empty bitmap");
        test_select_enumeration(std::vector<bool>(N), bitmap, "Empty bitmap");
    }

    {
        // Only one value
        std::vector<bool> v(N);
        succinct::bit_vector_builder bvb(N);
        bvb.set(37, 1);
        v[37] = 1;
        succinct::elias_fano bitmap(&bvb);
        test_equal_bits(v, bitmap, "Only one value");
        test_rank_select1(v, bitmap, "Only one value");
        test_delta(bitmap, "Only one value");
        test_select_enumeration(v, bitmap, "Only one value");
        BOOST_REQUIRE_EQUAL(1U, bitmap.num_ones());
    }

    {
        // Full bitmap
        std::vector<bool> v(N, 1);
        succinct::bit_vector_builder bvb;
        for (size_t i = 0; i < N; ++i) {
            bvb.push_back(1);
        }
        succinct::elias_fano bitmap(&bvb);
        test_equal_bits(v, bitmap, "Full bitmap");
        test_rank_select1(v, bitmap, "Full bitmap");
        test_delta(bitmap, "Full bitmap");
        test_select_enumeration(v, bitmap, "Full bitmap");
    }
}

#include "utl/JsonEncode.h"

// Encodes a string for JSON representation
void JSONStrEncode(const char *cc, String &str)
{
    int length = strlen(cc);
    for(int i=0;i<length;i++)
    {
        unsigned char cur = cc[i];
        if(cur == '"')
        {
            str += "\\\"";
        }
        else if(cur == '\\')
        {
            str += "\\\\";
        }
        else if(cur == '/')
        {
            str += "\\/";
        }
        else if(cur == '\b')
        {
            str += "\\b";
        }
        else if(cur == '\r')
        {
            str += "\\r";
        }
        else if(cur == '\n')
        {
            str += "\\n";
        }
        else if(cur == '\t')
        {
            str += "\\t";
        }
        else if(cur < ' ')
        {
            str += "\\u00";
            str += "0123456789ABCDEF"[cur >> 4];
            str += "0123456789ABCDEF"[cur & 0xF];
        }
        else
        {
            str += cur;
        }
    }
}

