#include <algorithm>
#include <climits>

class Solution {
public:
    // Calculates the minimum number of beans to remove
    long long minimumRemoval(vector<int>& beans) {
        sort(beans.begin(), beans.end());
        long long total = 0;
        for (int x : beans) total += x;

        long long ans = LLONG_MAX;
        int n = beans.size();

        for (int i = 0; i < n; i++) {
            long long kp = 1LL * beans[i] * (n - i);
            long long rm = total - kp;
            ans = min(ans, rm);
        }

        return ans;
    }
};

class Solution {
public:
    // Finds the pivot index in the array
    int pivotIndex(vector<int>& nums)
    {
        int n = nums.size();
        int totalSum = 0;
        int leftSum = 0;

        // Calculate total sum of the array
        for(int x : nums) {
            totalSum += x;
        }

        // Check for pivot index
        for(int i = 0; i < n; i++) {
            if(leftSum == totalSum - leftSum - nums[i]) {
                return i;
            }
            leftSum += nums[i];
        }

        return -1;
    }
};

