class Solution {
public:
    // Merges nums2 into nums1 and sorts the result
    void merge(vector<int>& nums1, int m, vector<int>& nums2, int n) 
    {
        int n1 = nums1.size();
        int n2 = nums2.size();

        // Copy elements from nums2 to nums1
        for(int i = 0; i < n; ++i)
        {
            nums1[m + i] = nums2[i];
        }

        // Sort the merged array
        sort(nums1.begin(), nums1.end());
        return;
    }
};

