using namespace std;

// Function to find all subset sums
void findSubsetSum(vector<int>& arr, int index, int n, int sum, vector<int>& ans)
{
    // Base condition: when we've processed all elements
    if(index == n)
    {
        ans.push_back(sum);
        return;
    }

    // Include current element in the sum and move forward
    findSubsetSum(arr, index+1, n, sum + arr[index], ans);
    // Exclude current element from the sum and move forward
    findSubsetSum(arr, index+1, n, sum, ans);
}

// Wrapper function to initiate subset sum calculation
vector<int> subsetSums(vector<int>& arr)
{
    // Your code here

    vector<int> ans;
    findSubsetSum(arr, 0, arr.size(), 0, ans);
    return ans;
}

