	case TMMSDTransferMode::TransferCSWIn:
		MLOGNOTE("MMSDEndpoint","Begin Transfer In  nlen= %i",nLength);
		CDWUSBGadgetEndpoint::BeginTransfer (TTransferMode::TransferDataIn, pBuffer, nLength);
		break;
	default:
		assert(0);
		break;
	}
