#include <mplot/qt/viswidget.h>
#include <mplot/GraphVisual.h>

// Build a widget based mplot app
int main(int argc, char **argv)
{
    QApplication app(argc, argv);

    // Create widget. The GL version to be used is set inside viswidget. It's accessible as
    // mplot::qt::gl_version. You have to give an index to your widget (0 for the first, 1 for the next one, etc)
    mplot::qt::viswidget<0> widget;

    // Calling show ensures initializeGL() method gets called. The alternative to
    // calling show() at the start of the main() function, is to set viswidget's
    // buildmodels callback (see app2).
    widget.show();

    // We can now add VisualModels to the Visual inside the Widget. Create a GraphVisual
    // object (obtaining a unique_ptr to the object) with a spatial offset within the
    // scene of 0,0,0
    auto gv = std::make_unique<mplot::GraphVisual<double, mplot::qt::gl_version>>(sm::vec<float>({0, 0, 0}));

    // This mandatory line of boilerplate code sets the parent pointer in GraphVisual and binds some functions
    widget.v.bindmodel(gv);

    // Allow 3D
    gv->twodimensional(false);

    // Data for the x axis. A vvec is like std::vector, but with built-in maths methods
    sm::vvec<double> x;

    // This works like numpy's linspace() (the 3 args are "start", "end" and "num"):
    x.linspace(-0.5, 0.8, 14);

    // Set a graph up of y = x^3
    gv->setdata(x, x.pow(3));

    // finalize() makes the GraphVisual compute the vertices of the OpenGL model
    gv->finalize();

    // Add the GraphVisual OpenGL model to the Visual scene, transferring ownership of the unique_ptr
    widget.v.addVisualModel(gv);

    return app.exec();
}

#include <iostream>
#include <queue>
using namespace std;

// Main function demonstrating priority queue usage
int main()
{
    // Create a max heap (default behavior)
    priority_queue<int> pq;

    // Push elements into the max heap
    pq.push(1); // push 1 onto the priority queue
    pq.push(2); // push 2 onto the priority queue
    pq.push(3); // push 3 onto the priority queue
    pq.push(4); // push 4 onto the priority queue

    // Emplace element (in-place construction)
    pq.emplace(5); // emplace 5 onto the priority queue (in-place object creation)

    // Print all elements in descending order (max heap behavior)
    while(!pq.empty()) { // while the priority queue is not empty
        cout << pq.top() << " "; // print the top element (highest priority)
        pq.pop(); // pop the top element
    }
    cout << endl; // print a newline

    // Check size and emptiness after full popping
    cout << "Size of priority queue after popping all elements: " << pq.size() << endl; // print the size of the priority queue (0)
    cout << "Is priority queue empty? " << (pq.empty() ? "Yes" : "No") << endl; // check if the priority queue is empty

    // Create a min heap using greater<int> comparator
    priority_queue<int, vector<int>, greater<int>> minHeap; // min heap

    // Push elements into the min heap
    minHeap.push(1); // push 1 onto the min heap
    minHeap.push(2); // push 2 onto the min heap
    minHeap.push(3); // push 3 onto the min heap
    minHeap.push(4); // push 4 onto the min heap

    // Emplace additional elements
    minHeap.emplace(5); // emplace 5 onto the min heap (in-place object creation)
    minHeap.emplace(6); // emplace 6 onto the min heap (in-place object creation)

    // Print all elements in ascending order (min heap behavior)
    while(!minHeap.empty()) { // while the min heap is not empty
        cout << minHeap.top() << " "; // print the top element (lowest priority)
        minHeap.pop(); // pop the top element
    }
    cout << endl; // print a newline

    // Check size and emptiness after full popping
    cout << "Size of min heap after popping all elements: " << minHeap.size() << endl; // print the size of the min heap (0)
    cout << "Is min heap empty? " << (minHeap.empty() ? "Yes" : "No") << endl; // check if the min heap is empty

    // greater<int> is a functor that is used to compare the elements in the priority queue. It is used to create a min heap.
    // By default, the priority queue is a max heap, which means that the largest element is at the top.

    return 0;
}

