#include <vector>
#include <string>

// Solution class for generating valid parentheses combinations
class Solution {
public:
    // Recursive helper function to build valid parentheses
    void recursiveF(int op, int cl, std::string s, std::vector<std::string> &ans) {
        // Base case: when no closing parentheses remain
        if (cl == 0) {
            ans.push_back(s);
        }

        // Add closing parenthesis if we have more closing than opening remaining
        if (cl > op) {
            recursiveF(op, cl - 1, s + ')', ans);
        }

        // Add opening parenthesis if we still have opening parentheses left
        if (op > 0) {
            recursiveF(op - 1, cl, s + '(', ans);
        }
    }

    // Main function to generate all valid parentheses combinations
    std::vector<std::string> generateParenthesis(int n) {
        int op = n, cl = n;
        std::string s = "";
        std::vector<std::string> ans;
        recursiveF(op, cl, s, ans);
        return ans;
    }
};

