namespace {

/// NVPTXAssignValidGlobalNames
class NVPTXAssignValidGlobalNames : public ModulePass {
public:
  static char ID;

  NVPTXAssignValidGlobalNames() : ModulePass(ID) {}

  bool runOnModule(Module &M) override;

  /// Clean up the name to remove symbols invalid in PTX.
  std::string cleanUpName(StringRef Name);
};

}

char NVPTXAssignValidGlobalNames::ID = 0;

namespace llvm {
void initializeNVPTXAssignValidGlobalNamesPass(PassRegistry &);
}

INITIALIZE_PASS(NVPTXAssignValidGlobalNames, "nvptx-assign-valid-global-names",
                "Assign valid PTX names to globals", false, false)

bool NVPTXAssignValidGlobalNames::runOnModule(Module &M) {
  for (GlobalVariable &GV : M.globals()) {
    // We are only allowed to rename local symbols.
    if (GV.hasLocalLinkage()) {
      // setName doesn't do extra work if the name does not change.
      // Note: this does not create collisions - if setName is asked to set the
      // name to something that already exists, it adds a proper postfix to
      // avoid collisions.
      GV.setName(cleanUpName(GV.getName()));
    }
  }

  // Do the same for local functions.
  for (Function &F : M.functions())
    if (F.hasLocalLinkage())
      F.setName(cleanUpName(F.getName()));

  return true;
}

std::string NVPTXAssignValidGlobalNames::cleanUpName(StringRef Name) {
  std::string ValidName;
  raw_string_ostream ValidNameStream(ValidName);

  for (char C : Name) {
    if (C == '.' || C == '@' || C == '<' || C == '>') {
      ValidNameStream << "_$_";
    } else {
      ValidNameStream << C;
    }
  }

  return ValidNameStream.str();
}

ModulePass *llvm::createNVPTXAssignValidGlobalNamesPass() {
  return new NVPTXAssignValidGlobalNames();
}

#include <iostream>
#include <vector>
#include <string>

// This program generates a specific map for the "Kangaroos" problem.
// The map is a 20x20 grid with a "double-sided comb" structure.
// This structure is a tree, as required, and is designed to make it
// difficult for agents to congregate under random movements.
// It consists of a central horizontal "backbone" and many vertical "teeth"
// connected to it. This segregates agent movement: agents on the backbone
// primarily respond to L/R commands, while agents on teeth respond to U/D.
// Moving between these sections requires being at an intersection and receiving
// the appropriate command, which is unlikely to happen for all agents
// in a coordinated way with random commands. The numerous dead-ends also
// help trap agents, preventing them from easily gathering.

void solve()
{
    int n = 20;
    int m = 20;
    std::cout << n << " " << m << std::endl;

    std::vector<std::string> map(n, std::string(m, '0'));

    // The backbone is placed on a central row. For n=20, row 9 is chosen.
    int backbone_row = n / 2 - 1;

    for(int j = 0; j < m; ++j)
    {
        map[backbone_row][j] = '1';
    }

    // The teeth are placed on every second column (even indices) to ensure they
    // do not connect to each other, maintaining the tree structure.
    for(int j = 0; j < m; ++j)
    {
        if(j % 2 == 0)
        {
            // Upper teeth, from the top of the grid down to the backbone.
            for(int i = 0; i < backbone_row; ++i)
            {
                map[i][j] = '1';
            }

            // Lower teeth, from below the backbone to the bottom of the grid.
            for(int i = backbone_row + 1; i < n; ++i)
            {
                map[i][j] = '1';
            }
        }
    }

    // Print the generated map to standard output.
    for(int i = 0; i < n; ++i)
    {
        std::cout << map[i] << std::endl;
    }
}

int main()
{
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
    solve();
    return 0;
}

#include <iostream>
#include <fstream>
#include <vector>
#include <string>
#include <bitset>

// Function to read and decode a 2-bit encoded sequence file
std::vector<std::string> loadTwoBitSequences(const std::string& filePath) {
    std::ifstream inputStream(filePath, std::ios::binary);
    if (!inputStream.is_open()) {
        throw std::runtime_error("Unable to open file: " + filePath);
    }

    // Read number of sequences in the file
    int numSequences;
    inputStream.read(reinterpret_cast<char*>(&numSequences), sizeof(numSequences));

    std::vector<std::string> seqNames(numSequences);
    for (int idx = 0; idx < numSequences; ++idx) {
        int nameSize;
        inputStream.read(reinterpret_cast<char*>(&nameSize), sizeof(nameSize));
        seqNames[idx].resize(nameSize);
        inputStream.read(&seqNames[idx][0], nameSize);
    }

    // Process each sequence: read encoded data and decode to nucleotides
    std::vector<std::string> resultSequences;
    for (const auto& name : seqNames) {
        int seqLen;
        inputStream.read(reinterpret_cast<char*>(&seqLen), sizeof(seqLen));

        std::string rawData;
        rawData.resize(seqLen);
        inputStream.read(&rawData[0], seqLen);

        // Convert 2-bit encoding to actual nucleotide characters
        std::string decodedData;
        for (unsigned char byteVal : rawData) {
            std::bitset<8> bitPattern(byteVal);
            // Extract each 2-bit group from the byte
            for (int bitPos = 6; bitPos >= 0; bitPos -= 2) {
                unsigned short twoBits = (bitPattern.to_ulong() >> bitPos) & 0x3;
                decodedData += "ACGT"[twoBits];
            }
        }
        resultSequences.push_back(decodedData);
    }

    inputStream.close();
    return resultSequences;
}

#include <iostream>
#include <string>
#include <unordered_set>

// Template class representing a hierarchical path structure
template <typename PathRegistry>
class FilePath {
public:
    FilePath() = default;

    // Constructor creates a child path from a parent with a given name
    FilePath(const FilePath& origin, const std::string& segment) 
        : parent_(&origin), segmentName_(segment) {}

    // Check if this path segment is unique among siblings
    bool isDistinct() const {
        if (parent_ == nullptr) {
            return true;  // Root path is always distinct
        }
        const auto& registeredPaths = parent_->getRegisteredPaths();
        return registeredPaths.find(segmentName_) == registeredPaths.end();
    }

    // Print the full path from root to current node
    void displayPath() const {
        if (parent_ != nullptr) {
            parent_->displayPath();
            std::cout << "/" << segmentName_;
        } else {
            std::cout << "/" << segmentName_;
        }
    }

private:
    const FilePath* parent_ = nullptr;
    std::string segmentName_;

    // Access the registry of sibling paths
    const PathRegistry& getRegisteredPaths() const {
        return PathRegistry::getSingleton();
    }
};

// Registry class that maintains a set of path segments for each level
template <typename T>
class PathRegistry {
public:
    static const PathRegistry& getSingleton() {
        static PathRegistry instance;
        return instance;
    }

    std::unordered_set<std::string> registeredSegments;

private:
    PathRegistry() = default;
};

int main() {
    using FilePath = FilePath<PathRegistry<std::string>>;

    // Create path instances
    FilePath base;
    FilePath branch1 { base, "folderA" };
    FilePath branch2 { base, "folderB" };
    FilePath branch3 { base, "folderA" };  // Duplicate of branch1
    FilePath nested { branch2, "subfolder" };

    // Display paths
    branch1.displayPath();   // Output: /folderA
    std::cout << std::endl;

    branch2.displayPath();   // Output: /folderB
    std::cout << std::endl;

    branch3.displayPath();   // Output: /folderA
    std::cout << std::endl;

    nested.displayPath();    // Output: /folderB/subfolder
    std::cout << std::endl;

    // Check uniqueness of each path
    std::cout << "branch1 is distinct: " << (branch1.isDistinct() ? "true" : "false") << std::endl;  // Output: true
    std::cout << "branch2 is distinct: " << (branch2.isDistinct() ? "true" : "false") << std::endl;  // Output: true
    std::cout << "branch3 is distinct: " << (branch3.isDistinct() ? "true" : "false") << std::endl;  // Output: false
    std::cout << "nested is distinct: " << (nested.isDistinct() ? "true" : "false") << std::endl;    // Output: true

    return 0;
}

#include <mcpputil/mcpputil/pointer_utils.hpp>
#include <unordered_set>
#include <iostream>

// Custom memory allocator with tracking capabilities
class MemoryTracker {
public:
    void* requestMemory(size_t bytes) {
        void* addr = mcpputil::pointer_utils::allocate(bytes);
        m_tracked_pointers.insert(addr);
        m_cumulative_usage += bytes;
        return addr;
    }

    void releaseMemory(void* addr, size_t bytes) {
        auto iter = m_tracked_pointers.find(addr);
        if (iter != m_tracked_pointers.end()) {
            mcpputil::pointer_utils::deallocate(addr, bytes);
            m_tracked_pointers.erase(iter);
            m_cumulative_usage -= bytes;
        }
    }

    ~MemoryTracker() {
        for (auto location : m_tracked_pointers) {
            std::cerr << "Unreleased memory block at: " << location << std::endl;
            mcpputil::pointer_utils::deallocate(location, /* size */); // Cleanup without known size
        }
    }

    size_t getCurrentUsage() const {
        return m_cumulative_usage;
    }

private:
    std::unordered_set<void*> m_tracked_pointers;
    size_t m_cumulative_usage = 0;
};

int main() {
    MemoryTracker tracker;
    // Request memory blocks
    void* blockA = tracker.requestMemory(128);
    void* blockB = tracker.requestMemory(256);
    // Release first block
    tracker.releaseMemory(blockA, 128);
    // blockB intentionally left allocated to simulate leak
    // Report current usage
    std::cout << "Current memory usage: " << tracker.getCurrentUsage() << " bytes" << std::endl;
    // Destructor will report remaining leaked memory
    return 0;
}

