// Interface for executable actions with undo/redo support
class IAction {
public:
    virtual void perform() = 0;
    virtual void revert() = 0;
    virtual void repeat() = 0;
};

// Concrete implementation for selecting all elements
class SelectEverythingAction : public IAction {
private:
    std::vector<Item> currentSelection;     // Holds currently selected items
    std::vector<Item> lastState;            // Stores the state before last operation

public:
    SelectEverythingAction(const std::vector<Item>& items) : currentSelection(items) {}

    void perform() override {
        // Save current state before making changes
        lastState = currentSelection;
        // Replace with full list of available items
        currentSelection = retrieveAllElements();
        std::cout << "All elements have been chosen" << std::endl;
    }

    void revert() override {
        // Restore previous selection state
        currentSelection = lastState;
        std::cout << "Previous selection restored" << std::endl;
    }

    void repeat() override {
        // Re-execute the selection operation
        perform();
    }

    std::vector<Item> retrieveAllElements() {
        // Method to fetch all accessible items from the system
        // Implementation details omitted
        return std::vector<Item>();
    }
};

int main() {
