// Decrypts a single character using Caesar cipher with given shift
char decryptChar(char ch, int shift) {
    char base = (islower(ch)) ? 'a' : 'A';
    ch = (isalpha(ch)) ? (ch - base + (26 - shift)) % 26 + base : ch;
    return ch;
}

int main() {
    std::string textLine;
    int shiftValue;

    std::cout << "Please enter a message to decode:\n";
    std::getline(std::cin, textLine);

    std::cout << "Enter the shift amount used for encryption (1-25):\n";
    std::cin >> shiftValue;

    while (shiftValue < 1 || shiftValue > 25) {
        std::cout << "Invalid shift. Enter a number between 1 and 25:\n";
        std::cin >> shiftValue;
    }

    std::string result;
    for (char letter : textLine) {
        result += decryptChar(letter, shiftValue);
    }

    std::cout << "Decrypted message: " << result << std::endl;
    return 0;
}

