using namespace std;

class DiningPhilosophers {
public:
    DiningPhilosophers(int count) : forks(count) {}

    void wantsToEat(int philosopher, 
                    function<void()> takeLeftStick, 
                    function<void()> takeRightStick, 
                    function<void()> consume, 
                    function<void()> releaseLeftStick, 
                    function<void()> releaseRightStick) {

        int leftFork = philosopher;
        int rightFork = (philosopher + 1) % forks.size();

        if (philosopher % 2 == 0) {
            forks[leftFork].lock();
            takeLeftStick();
            forks[rightFork].lock();
            takeRightStick();
            consume();
            releaseRightStick();
            forks[rightFork].unlock();
            releaseLeftStick();
            forks[leftFork].unlock();
        } else {
            forks[rightFork].lock();
            takeRightStick();
            forks[leftFork].lock();
            takeLeftStick();
            consume();
            releaseLeftStick();
            forks[leftFork].unlock();
            releaseRightStick();
            forks[rightFork].unlock();
        }
    }

private:
    vector<mutex> forks;
};

