// Define type_tag as a unique identifier for each type
using type_tag = int;

class type_converter {
public:
    type_converter();
    ~type_converter();

    std::pair<void*, int> convert(
        void* ptr, type_tag source_type, type_tag target_type, 
        type_tag actual_type, void const* actual_ptr) const;
};

std::pair<void*, int> type_converter::convert(
    void* ptr, type_tag source_type, type_tag target_type, 
    type_tag actual_type, void const* actual_ptr) const {

    if (actual_type == source_type) {
        void* converted_ptr = dynamic_cast<void*>(ptr);
        if (converted_ptr != nullptr && actual_type == target_type) {
            return std::make_pair(converted_ptr, 1);  // Conversion succeeded
        }
    }

    return std::make_pair(nullptr, 0);  // Conversion failed
}

