// Compute the molar mass of a given chemical compound
double CalculateMolarMass(std::istream& input) {
  // Dictionary mapping element symbols to their atomic masses
  std::map<std::string, double> elementMasses = {
    {"H", 1.008}, {"C", 12.011}, {"O", 15.999}, {"N", 14.007}
    // Extend with additional elements and corresponding weights if required
  };

  double cumulativeMass = 0.0;
  char symbol;
  int quantity;

  // Parse the chemical formula from the input stream
  while (input >> symbol >> quantity) {
    std::string elementSymbol(1, symbol);
    auto it = elementMasses.find(elementSymbol);
    if (it != elementMasses.end()) {
      cumulativeMass += it->second * quantity;
    } else {
      std::cerr << "Warning: Unrecognized element " << elementSymbol << std::endl;
      return -1.0;  // Indicates an error due to unknown element
    }
  }
  return cumulativeMass;
}

int main() {
  // Demonstration usage
  std::string compound = "H2O";
  std::istringstream inputStream(compound);
  double mass = CalculateMolarMass(inputStream);
  std::cout << "Molar mass of " << compound << " is " << mass << std::endl;
  return 0;
}

