#include <vector>
#include <algorithm>

// Determine if there exist two trees with a distance of exactly k between them
bool canFormTreePair(std::vector<int> positions, int targetDistance) {
    std::sort(positions.begin(), positions.end()); // Sort the tree positions in ascending order
    int left = 0;
    int right = positions.size() - 1;

    while (left < right) {
        int currentSum = positions[left] + targetDistance;

        if (currentSum < positions[right]) {
            left++; // Move to the next tree position from the left
        } else if (currentSum > positions[right]) {
            right--; // Move to the next tree position from the right
        } else {
            return true; // Found two trees with distance targetDistance
        }
    }

    return false; // No such pair of trees found
}

