// Structure representing a quaternion with components w, x, y, z
struct Quaternion {
    double w, x, y, z;

    // Constructor to initialize quaternion components
    Quaternion(double w_val, double x_val, double y_val, double z_val) 
        : w(w_val), x(x_val), y(y_val), z(z_val) {}

    // Overloaded multiplication operator for quaternion multiplication
    Quaternion operator*(const Quaternion& other) const {
        return Quaternion(
            w * other.w - x * other.x - y * other.y - z * other.z,
            w * other.x + x * other.w + y * other.z - z * other.y,
            w * other.y - x * other.z + y * other.w + z * other.x,
            w * other.z + x * other.y - y * other.x + z * other.w
        );
    }

    // Equality operator to compare two quaternions
    bool operator==(const Quaternion& other) const {
        return w == other.w && x == other.x && y == other.y && z == other.z;
    }
};

// Structure to hold test case data for quaternion multiplication
struct TestEntry {
    Quaternion first, second, result;
};

// Function to run multiple test cases for quaternion multiplication
void runQuaternionTests(const TestEntry* tests, size_t count) {
    for (size_t index = 0; index < count; ++index) {
        const auto& current = tests[index];
        Quaternion computed = current.first * current.second;
        if (computed == current.result) {
            std::cout << "Test " << index + 1 << " succeeded\n";
        } else {
            std::cout << "Test " << index + 1 << " failed\n";
        }
    }
}

int main() {
    // Define test cases: pairs of quaternions and their expected product
    TestEntry tests[] = {
        {Quaternion(0, 1, 0, 0), Quaternion(0, 1, 0, 0), Quaternion(-1, 0, 0, 0)},
        {Quaternion(0, 0, 1, 0), Quaternion(0, 0, 1, 0), Quaternion(-1, 0, 0, 0)},
        {Quaternion(0, 0, 0, 1), Quaternion(0, 0, 0, 1), Quaternion(-1, 0, 0, 0)},
        {Quaternion(1, 0, 0, 0), Quaternion(1, 0, 0, 0), Quaternion(1, 0, 0, 0)},
        {Quaternion(4, 1, 2, 3), Quaternion(8, 5, 6, 7), Quaternion(-6, 24, 48, 48)},
        {Quaternion(8, 5, 6, 7), Quaternion(4, 1, 2, 3), Quaternion(-6, 32, 32, 56)},
    };

    // Execute all test cases
    runQuaternionTests(tests, sizeof(tests) / sizeof(tests[0]));
    return 0;
}

