class PseudoRandomGenerator {
private:
    mt19937 generator;  // Mersenne Twister pseudo-random generator
    uniform_int_distribution<int> rangeDistribution;
public:
    PseudoRandomGenerator(int lowerBound, int upperBound) 
        : generator(system_clock::now().time_since_epoch().count()), 
          rangeDistribution(lowerBound, upperBound) {}

    int produce() {
        return rangeDistribution(generator);
    }

    void adjustRange(int newLower, int newUpper) {
        rangeDistribution = uniform_int_distribution<int>(newLower, newUpper);
    }
};

int main() {
    PseudoRandomGenerator prng(1, 100);  // Create a random number generator with range [1, 100]

    for (int index = 0; index < 10; ++index) {
        cout << prng.produce() << " ";  // Generate and print 10 random numbers within the specified range
    }
    cout << endl;

    prng.adjustRange(50, 150);  // Change the range to [50, 150]

    for (int index = 0; index < 10; ++index) {
        cout << prng.produce() << " ";  // Generate and print 10 random numbers within the new range
    }
