#include <vector>
#include <algorithm>

// Backtracking helper function to find all unique combinations that sum to target
void searchCombinations(std::vector<std::vector<int>>& results, 
                        std::vector<int>& currentPath, 
                        std::vector<int>& availableNumbers, 
                        int remainingSum, 
                        int startIndex) {
    if (remainingSum < 0) return;

    if (remainingSum == 0) {
        results.push_back(currentPath);
        return;
    }

    for (int index = startIndex; index < availableNumbers.size(); ++index) {
        // Skip duplicate values to avoid duplicate combinations
        if (index > startIndex && availableNumbers[index] == availableNumbers[index - 1]) 
            continue;

        currentPath.push_back(availableNumbers[index]);
        searchCombinations(results, currentPath, availableNumbers, 
                          remainingSum - availableNumbers[index], index + 1);
        currentPath.pop_back();
    }
}

// Main function to compute combination sums
std::vector<std::vector<int>> findCombinations(std::vector<int>& numbers, int desiredSum) {
    std::sort(numbers.begin(), numbers.end());
    std::vector<std::vector<int>> allResults;
    std::vector<int> currentCombination;

    searchCombinations(allResults, currentCombination, numbers, desiredSum, 0);
    return allResults;
}

