namespace math_utils {
    // Computes the factorial of a non-negative integer input
    int computeFactorial(int value) {
        if (value == 0 || value == 1) {
            return 1;
        } else {
            int accumulator = 1;
            for (int index = 2; index <= value; ++index) {
                accumulator *= index;
            }
            return accumulator;
        }
    }
}

