void ParticleEmitter::updateParticles(float deltaTime)
{
    for (auto iter = particles.begin(); iter != particles.end();)
    {
        iter->positionX += iter->velocityX * deltaTime;  // Update position based on velocity
        iter->positionY += iter->velocityY * deltaTime;
        iter->remainingTime -= deltaTime;  // Reduce remaining lifetime
        if (iter->remainingTime <= 0.0f)
        {
            iter = particles.erase(iter);  // Remove particle if lifetime has expired
        }
        else
        {
            ++iter;
        }
    }
}

