void waterfill(const Grid& input_grid, int start_x, int start_y, Grid& result_grid) {
    // Initialize a queue for BFS traversal
    std::queue<std::pair<int, int>> bfs_queue;
    bfs_queue.push({start_x, start_y});

    // Mark the source tile as filled with water
    result_grid[start_x][start_y] = Filled;

    // Define the possible directions for spreading water (reordered)
    const std::vector<std::pair<int, int>> movement_dirs = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    // Perform BFS traversal to spread water to neighboring tiles
    while (!bfs_queue.empty()) {
        auto current = bfs_queue.front();
        bfs_queue.pop();
        int x = current.first;
        int y = current.second;

        // Check and spread water to neighboring tiles
        for (const auto& offset : movement_dirs) {
            int adj_x = x + offset.first;
            int adj_y = y + offset.second;

            // Check if the neighboring tile is within bounds and not already filled with water
            if (adj_x >= 0 && adj_x < input_grid.size() && 
                adj_y >= 0 && adj_y < input_grid[0].size() &&
                result_grid[adj_x][adj_y] != Filled) {

                // Check if the neighboring tile satisfies the specific condition for waterfill
                if (TileRoutines::waterfill_touch_right(input_grid[x][y], input_grid[adj_x][adj_y], tile)) {
                    // Mark the neighboring tile as filled with water and add it to the queue for further spreading
                    result_grid[adj_x][adj_y] = Filled;
                    bfs_queue.push({adj_x, adj_y});
                }
            }
        }
    }
}

