class SyncManager {
public:
    void AddSyncPoint(int syncId) {
        std::unique_lock<std::mutex> guard(_mtx);
        _syncIds.push_back(syncId);
        _syncStates.push_back(false);
    }

    void SetSyncPoint(int syncId) {
        std::unique_lock<std::mutex> guard(_mtx);
        auto iter = std::find(_syncIds.begin(), _syncIds.end(), syncId);
        if (iter != _syncIds.end()) {
            size_t pos = std::distance(_syncIds.begin(), iter);
            _syncStates[pos] = true;
            _cond.notify_all();
        }
    }

    void AwaitSyncPoint(int syncId) {
        std::unique_lock<std::mutex> guard(_mtx);
        auto iter = std::find(_syncIds.begin(), _syncIds.end(), syncId);
        if (iter != _syncIds.end()) {
            size_t pos = std::distance(_syncIds.begin(), iter);
            _cond.wait(guard, [this, pos]() { return _syncStates[pos]; });
        }
    }

private:
    std::vector<int> _syncIds;
    std::vector<bool> _syncStates;
    std::mutex _mtx;
    std::condition_variable _cond;
};

int main() {
    SyncManager manager;

    // Register synchronization points
    manager.AddSyncPoint(10);
    manager.AddSyncPoint(20);
    manager.AddSyncPoint(30);

    // Trigger synchronization from separate threads
    std::thread worker1([&manager] { manager.SetSyncPoint(10); });
    std::thread worker2([&manager] { manager.SetSyncPoint(20); });
    std::thread worker3([&manager] { manager.SetSyncPoint(30); });

    worker1.join();
    worker2.join();
    worker3.join();

    // Wait for all synchronization points to be reached
    manager.AwaitSyncPoint(10);
    manager.AwaitSyncPoint(20);
    manager.AwaitSyncPoint(30);

    std::cout << "All sync points reached." << std::endl;
    return 0;
}

