enum class SeverityLevel { TRACE, NOTICE, CRITICAL, VERBOSE };

class LoggingSystem {
public:
    void trace(const std::string& msg) {
        record(SeverityLevel::TRACE, msg);
    }

    void notice(const std::string& msg) {
        record(SeverityLevel::NOTICE, msg);
    }

    void critical(const std::string& msg) {
        record(SeverityLevel::CRITICAL, msg);
    }

    void verbose(const std::string& msg) {
        record(SeverityLevel::VERBOSE, msg);
    }

    void validate(bool check, const std::string& description) {
        if (!check) {
            critical("Validation error: " + description);
            haltExecution();
        }
    }

    void redirectStream(std::ostream& stream) {
        destination_ = &stream;
    }

private:
    std::ostream* destination_ = &std::cout;

    void record(SeverityLevel level, const std::string& message) {
        std::string severityString;
        switch (level) {
            case SeverityLevel::TRACE:
                severityString = "TRACE";
                break;
            case SeverityLevel::NOTICE:
                severityString = "NOTICE";
                break;
            case SeverityLevel::CRITICAL:
                severityString = "CRITICAL";
                break;
            case SeverityLevel::VERBOSE:
                severityString = "VERBOSE";
                break;
        }
        (*destination_) << "[" << severityString << "] " << message << std::endl;
    }

    void haltExecution() {
        throw std::runtime_error("Execution stopped due to validation failure");
    }
};

int main() {
    LoggingSystem logger;
    logger.critical("Critical issue detected");
    logger.verbose("Verbose diagnostic data");
    logger.redirectStream(std::cerr);
    logger.notice("This is a notice");
    logger.validate(3 * 3 == 10, "Arithmetic check failed");
    logger.trace("This trace message should not appear");
    return 0;
}

