class String {
private:
    char* data;
public:
    // Constructor from C-style string
    String(const char* inputStr) {
        data = new char[strlen(inputStr) + 1];
        strcpy(data, inputStr);
    }

    // Copy constructor
    String(const String& source) {
        data = new char[strlen(source.data) + 1];
        strcpy(data, source.data);
    }

    // Assignment operator
    String& operator=(const String& rightOperand) {
        if (this != &rightOperand) {
            delete[] data;
            data = new char[strlen(rightOperand.data) + 1];
            strcpy(data, rightOperand.data);
        }
        return *this;
    }

    // Concatenation operator
    String operator+(const String& rhs) const {
        char* tempBuffer = new char[strlen(data) + strlen(rhs.data) + 1];
        strcpy(tempBuffer, data);
        strcat(tempBuffer, rhs.data);
        String concatenated(tempBuffer);
        delete[] tempBuffer;
        return concatenated;
    }

    // Comparison operators
    bool operator==(const String& other) const {
        return strcmp(data, other.data) == 0;
    }

    bool operator!=(const String& other) const {
        return strcmp(data, other.data) != 0;
    }

    // Indexing operator
    char& operator[](size_t position) {
        return data[position];
    }

    // Destructor
    ~String() {
        delete[] data;
    }
};

