class FunctionManager {
private:
    std::unordered_map<std::string, std::function<void()>> functionTable;
public:
    void addFunction(const std::string& funcName, const std::function<void()>& funcPtr) {
        if (functionTable.find(funcName) != functionTable.end()) {
            throw std::invalid_argument("Function named " + funcName + " already exists");
        }
        functionTable[funcName] = funcPtr;
    }

    template<typename... Parameters>
    void callFunction(const std::string& funcName, Parameters&&... params) {
        if (functionTable.find(funcName) == functionTable.end()) {
            throw std::invalid_argument("Function named " + funcName + " is not registered");
        }
        functionTable[funcName](std::forward<Parameters>(params)...);
    }
};

