        : m_isEnabled(enabled), m_pFileMonitor(fileMonitor), m_fCooldownBeforeNextCompile(cooldownBeforeNextCompile), m_fSpamProtectionTimer(spamProtectionTimer) {}

    void Update(float deltaTime) {
        if (m_isEnabled) {
            m_pFileMonitor->update();
            m_fCooldownBeforeNextCompile = std::max(0.0f, m_fCooldownBeforeNextCompile - deltaTime);
            m_fSpamProtectionTimer = std::max(0.0f, m_fSpamProtectionTimer - deltaTime);
        }
    }
};

