// Function to verify if a JSON value is well-formed
bool checkJSONStructure(Json::Value jData) {
    // Serialize the JSON value to string and re-parse it to validate
    Json::StreamWriterBuilder builderWriter;
    std::string jsonString = Json::writeString(builderWriter, jData);

    Json::CharReaderBuilder builderReader;
    std::istringstream inputStream(jsonString);
    Json::Value resultJson;
    std::string errorMessage;

    bool parseOk = Json::parseFromStream(builderReader, inputStream, &resultJson, &errorMessage);

    if (parseOk) {
        // JSON structure is correct
        return true;
    } else {
        // JSON structure has issues
        std::cerr << "JSON parsing error: " << errorMessage << std::endl;
        return false;
    }
}

