// Determine the minimum total problems required across all topics
long long computeTotalProblems(long long topicsCount, long long minRequired, long long dailyCapacity) {
    long long daysNeeded = (minRequired + dailyCapacity - 1) / dailyCapacity;  // Compute days needed using ceiling division
    long long problemsFromTopics = topicsCount * daysNeeded;  // Total problems from covering all topics
    return std::max(problemsFromTopics, minRequired);  // Return the larger value between topic-based count and minimum requirement
}

