#include <vector>

class FloodFill {
private:
    std::vector<std::vector<int>> matrix;
    int height;
    int width;

    void expand(int row, int col, int prevColor, int fillColor) {
        if (row < 0 || row >= height || col < 0 || col >= width || matrix[row][col] != prevColor) {
            return;
        }

        matrix[row][col] = fillColor;

        expand(row + 1, col, prevColor, fillColor);
        expand(row - 1, col, prevColor, fillColor);
        expand(row, col + 1, prevColor, fillColor);
        expand(row, col - 1, prevColor, fillColor);
    }

public:
    FloodFill() : height(10), width(10), 
                  matrix(std::vector<std::vector<int>>(10, std::vector<int>(10, 0))) {
        // Initialize the matrix with default dimensions and zero values
    }

    void performFill(int x, int y, int newColor) {
        if (x < 0 || x >= height || y < 0 || y >= width) {
            return;
        }

        int originalColor = matrix[x][y];
        if (originalColor == newColor) {
            return;
        }

        expand(x, y, originalColor, newColor);
    }
};

