// Process range queries to find k-th smallest elements in sorted subarrays
std::vector<int> handleRangeQueries(std::vector<Query>& inputQueries, std::vector<int>& dataArray) {
    std::vector<int> outputResults;

    for (const auto& currentQuery : inputQueries) {
        // Extract the subarray from position l to r (inclusive)
        std::vector<int> tempArray(dataArray.begin() + currentQuery.left, 
                                   dataArray.begin() + currentQuery.right + 1);

        // Sort the extracted subarray
        std::sort(tempArray.begin(), tempArray.end());

        // Add the k-th smallest element (1-indexed) to results
        outputResults.push_back(tempArray[currentQuery.position - 1]);
    }

    return outputResults;
}

