// Helper structure to deduce the function pointer signature from various callable types
template <typename T>
struct callable_signature_extractor;

// Specialization for raw function pointers
template <typename R, typename... P>
struct callable_signature_extractor<R(*)(P...)> {
    using type = R(*)(P...);
};

// Specialization for std::function objects
template <typename R, typename... P>
struct callable_signature_extractor<std::function<R(P...)>> {
    using type = R(*)(P...);
};

// General case: for lambdas and other callables with operator()
template <typename F>
struct callable_signature_extractor {
    using type = typename callable_signature_extractor<
        decltype(&F::operator())
    >::type;
};

// Utility function template to transform a callable into a plain function pointer
template <typename Func>
auto adapt_to_function_pointer(Func f) -> typename callable_signature_extractor<Func>::type {
    return +f;  // Unary plus triggers lambda-to-function-pointer conversion
}

// Demonstration of the conversion mechanism
int main() {
    // Create a simple lambda that adds two integers
    auto adder = [](int a, int b) { return a + b; };

    // Convert the lambda into a function pointer
    auto fn_ptr = adapt_to_function_pointer(adder);

    // Use the resulting function pointer
    std::cout << fn_ptr(10, 20) << std::endl;  // Expected output: 30

    return 0;
}

