// Function to generate a random number from a normal distribution with mean 0 and standard deviation 1
double generateRandomNumber(std::default_random_engine& engine) {
    std::normal_distribution<double> dist(0.0, 1.0);
    return dist(engine);
}

int main() {
    // Initialize parameters
    double velocity = 0.0;   // Initial velocity
    double position = 0.0;   // Initial position
    double velStdDev = 0.1;  // Standard deviation for velocity updates
    double posStdDev = 0.2;  // Standard deviation for position updates
    int totalSteps = 100;    // Number of time steps
    std::default_random_engine rng;  // Random number generator

    // Data structure for storing simulation results
    std::map<std::string, double> record;
    int stepIndex = 0;       // Index for recording the data
    double currentTime = 0.0; // Current time

    // Simulate the motion of the particle for the specified number of time steps
    for (int step = 0; step < totalSteps; ++step) {
        // Update the velocity and position using the Euler-Maruyama method
        velocity += velStdDev * generateRandomNumber(rng);
        position += posStdDev * generateRandomNumber(rng);

        // Record the data in the table
        record["I"] = stepIndex++;
        record["Time"] = currentTime;
        record["Velocity"] = velocity;
        record["Position"] = position;
        record["SigmaX"] = posStdDev;
        record["SigmaV"] = velStdDev;

        // Print the captured data
        for (const auto& item : record) {
            std::cout << item.first << ": " << item.second << std::endl;
        }

        // Increment the time
        currentTime += 1.0;

        // Clear the table for the next time step
        record.clear();
    }

    return 0;
}

