#include <queue>
#include <mutex>
#include <condition_variable>
#include <memory>

template <typename DataType>
class ConcurrentQueue {
public:
    void add(const DataType& item) {
        std::unique_lock<std::mutex> guard(mtx);
        dataQueue.push(item);
        guard.unlock();
        cv.notify_one();
    }

    std::shared_ptr<DataType> remove() {
        std::unique_lock<std::mutex> guard(mtx);
        cv.wait(guard, [this] { return !dataQueue.empty(); });
        auto result = std::make_shared<DataType>(dataQueue.front());
        dataQueue.pop();
        return result;
    }

private:
    std::queue<DataType> dataQueue;
    std::mutex mtx;
    std::condition_variable cv;
};

