// Convert PathLocation to PBF format for API response
void PathLocation::toPBF(const PathLocation& input_location, valhalla::Location* output_pbf, const valhalla::baldr::GraphReader& graph_reader) {
  // Transform the geographic coordinate into the PBF structure
  output_pbf->mutable_ll()->set_lng(input_location.latlng_.lng());
  output_pbf->mutable_ll()->set_lat(input_location.latlng_.lat());

  // Serialize associated edges into the PBF correlation data
  for (const auto& edge_data : input_location.edges) {
    auto* route_edge = output_pbf->mutable_correlation()->add_edges();
    route_edge->set_id(edge_data.id);
    route_edge->set_percent_along(edge_data.percent_along);
    route_edge->mutable_ll()->set_lng(edge_data.ll.lng());
    route_edge->mutable_ll()->set_lat(edge_data.ll.lat());
    route_edge->set_distance(edge_data.distance);
  }

  // Serialize filtered edges into the PBF correlation data
  for (const auto& restricted_edge : input_location.filtered_edges) {
    auto* blocked_edge = output_pbf->mutable_correlation()->add_filtered_edges();
    blocked_edge->set_id(restricted_edge.id);
    blocked_edge->set_percent_along(restricted_edge.percent_along);
    blocked_edge->mutable_ll()->set_lng(restricted_edge.ll.lng());
    blocked_edge->mutable_ll()->set_lat(restricted_edge.ll.lat());
    blocked_edge->set_distance(restricted_edge.distance);
  }
}

