// Manages bidirectional mapping between IDs and string identifiers
class StringRegistry {
private:
    std::unordered_map<tCIDLib::TCard4, std::string> idToStringMap;
    std::unordered_map<std::string, tCIDLib::TCard4> stringToIdMap;
    tCIDLib::TCard4 nextIdentifier = 1;

public:
    // Insert a new string with an automatically assigned unique ID
    void registerString(const std::string& strName) {
        idToStringMap[nextIdentifier] = strName;
        stringToIdMap[strName] = nextIdentifier;
        nextIdentifier++;
    }

    // Get the string associated with a given ID
    std::string getString(tCIDLib::TCard4 c4Id) {
        if (idToStringMap.find(c4Id) != idToStringMap.end()) {
            return idToStringMap[c4Id];
        }
        return "";  // Return empty string if ID not found
    }

    // Remove a string entry by its ID
    void unregisterString(tCIDLib::TCard4 c4Id) {
        if (idToStringMap.find(c4Id) != idToStringMap.end()) {
            stringToIdMap.erase(idToStringMap[c4Id]);
            idToStringMap.erase(c4Id);
        }
    }

    // Get the ID associated with a given string
    tCIDLib::TCard4 getId(const std::string& strName) {
        if (stringToIdMap.find(strName) != stringToIdMap.end()) {
            return stringToIdMap[strName];
        }
        return 0;  // Return 0 if string not found
    }
};

