namespace fs = std::filesystem;

// Locate the resources directory by traversing upward from the given path
fs::path DirectoryUtils::searchResourceDirectory(const fs::path& basePath) {
    // Begin searching from the provided base path
    fs::path currentPath = basePath;
    // Move up the directory tree until the resources folder is located
    while (!currentPath.empty()) {
        fs::path candidatePath = currentPath / "resources";
        if (fs::exists(candidatePath) && fs::is_directory(candidatePath)) {
            return candidatePath;
        }
        currentPath = currentPath.parent_path();
    }
    // If no resources directory is found, return an empty path
    return fs::path();
}

