// Function to create a Buffer object from a string
Buffer* make_buffer(const std::string& text) {
    // Allocate memory for the Buffer object
    Buffer* buffer = new Buffer;
    // Set size and allocate memory for content
    buffer->size = text.length();
    buffer->content = new char[buffer->size + 1];  // +1 for null terminator
    // Copy input string to Buffer content
    std::strcpy(buffer->content, text.c_str());
    return buffer;
}

