#include <iostream>
#include <thread>
#include <vector>
#include <mutex>
#include <Windows.h>

class EventTicketManager {
private:
    int availableSeats;
    HANDLE eventSemaphore;
public:
    EventTicketManager(int initialSeats) : availableSeats(initialSeats) {
        eventSemaphore = CreateSemaphore(NULL, initialSeats, 0x7FFFFFFF, NULL);
    }

    void RestockTickets(int count) {
        availableSeats += count;
        ReleaseSemaphore(eventSemaphore, count, NULL);
    }

    bool ReserveTickets(int requestedCount) {
        if (WaitForSingleObject(eventSemaphore, 0) == WAIT_OBJECT_0) {
            if (availableSeats >= requestedCount) {
                availableSeats -= requestedCount;
                ReleaseSemaphore(eventSemaphore, requestedCount, NULL);
                return true;
            }
            ReleaseSemaphore(eventSemaphore, 1, NULL);
        }
        return false;
    }
};

void VendorThread(EventTicketManager& manager, int quantity) {
    manager.RestockTickets(quantity);
}

void CustomerThread(EventTicketManager& manager, int quantity) {
    if (manager.ReserveTickets(quantity)) {
        std::cout << "Successfully bought: " << quantity << " tickets" << std::endl;
    } else {
        std::cout << "Insufficient tickets for request of " << quantity << std::endl;
    }
}

int main() {
    EventTicketManager manager(15);
    std::vector<std::thread> workerThreads;

    for (int index = 0; index < 4; ++index) {
        workerThreads.emplace_back(VendorThread, std::ref(manager), 4);
        workerThreads.emplace_back(CustomerThread, std::ref(manager), 3);
    }

    for (auto& thread : workerThreads) {
        thread.join();
    }

    std::cout << "Final availability check: " << manager.ReserveTickets(0) << std::endl;
    return 0;
}

