// Custom guarded action transition implementation
template <typename EventType, typename GuardPredicate, typename PerformAction>
class CustomGuardedTransition : public skizzay::fsm::guarded_action_transition<EventType> {
public:
    CustomGuardedTransition(EventType evt, GuardPredicate pred, PerformAction act)
        : skizzay::fsm::guarded_action_transition<EventType>(evt), 
          predicate_(pred), 
          action_(act) {}

    bool check_guard() const {
        return predicate_();
    }

    void run_action() const {
        action_();
    }

private:
    GuardPredicate predicate_;
    PerformAction action_;
};

// State and event enumerations
enum class MachineState { INITIAL, FINAL };
enum class Signal { ACTIVATE };

int main() {
    // Define guard and action lambdas
    auto guard_predicate = []() { return true; };
    auto perform_action = []() { std::cout << "Action executed successfully" << std::endl; };

    // Instantiate the custom transition
    CustomGuardedTransition<Signal, decltype(guard_predicate), decltype(perform_action)> 
        my_transition(Signal::ACTIVATE, guard_predicate, perform_action);

    // Set up the finite state machine
    skizzay::fsm::finite_state_machine<MachineState, Signal> machine(MachineState::INITIAL);
    machine.add_transition(MachineState::INITIAL, Signal::ACTIVATE, MachineState::FINAL, my_transition);

    // Process the triggering event
    machine.process_event(Signal::ACTIVATE);

    return 0;
}

