#include <cmath>

class ComplexNumber {
private:
    double realPart;
    double imagPart;
public:
    ComplexNumber(double r, double i) : realPart(r), imagPart(i) {}

    ComplexNumber operator+(const ComplexNumber& rhs) const {
        return ComplexNumber(realPart + rhs.realPart, imagPart + rhs.imagPart);
    }

    ComplexNumber operator-(const ComplexNumber& rhs) const {
        return ComplexNumber(realPart - rhs.realPart, imagPart - rhs.imagPart);
    }

    ComplexNumber operator*(const ComplexNumber& rhs) const {
        return ComplexNumber(
            realPart * rhs.realPart - imagPart * rhs.imagPart,
            realPart * rhs.imagPart + imagPart * rhs.realPart
        );
    }

    ComplexNumber operator/(const ComplexNumber& rhs) const {
        double denom = rhs.realPart * rhs.realPart + rhs.imagPart * rhs.imagPart;
        return ComplexNumber(
            (realPart * rhs.realPart + imagPart * rhs.imagPart) / denom,
            (imagPart * rhs.realPart - realPart * rhs.imagPart) / denom
        );
    }

    ComplexNumber power(int exponent) const {
        double magnitude = std::pow(std::sqrt(realPart * realPart + imagPart * imagPart), exponent);
        double angle = std::atan2(imagPart, realPart);
        return ComplexNumber(magnitude * std::cos(exponent * angle), magnitude * std::sin(exponent * angle));
    }
};

