class custom_exception : public std::runtime_error {
public:
    custom_exception(const char *format, ...) : std::runtime_error("") {
        va_list parameters;
        va_start(parameters, format);
        char temp_buffer[256];  // Buffer size for formatted message
        vsnprintf(temp_buffer, sizeof(temp_buffer), format, parameters);
        va_end(parameters);
        formatted_text = temp_buffer;
    }
    const char* what() const noexcept override {
        return formatted_text.c_str();
    }
private:
    std::string formatted_text;
};

int main() {
