// Define the enumeration for data types
enum class EDataType { Enum, Bitmask, Text };

// Base class for data wrappers
class CDataWrapper {
public:
    virtual ~CDataWrapper() {}
};

// Class for enumeration data
class CEnumData : public CDataWrapper {
public:
    int Get(void* pData) {
        // Implementation to retrieve the value of the enumeration data
        return *static_cast<int*>(pData);
    }
};

// Class for bitmask data
class CBitmaskData : public CDataWrapper {
public:
    int Get(void* pData) {
        // Implementation to retrieve the value of the bitmask data
        return *static_cast<int*>(pData);
    }
};

// Class for text data
class CTextData : public CDataWrapper {
public:
    std::string Get(void* pData) {
        // Implementation to retrieve the value of the text data
        return *static_cast<std::string*>(pData);
    }
};

// Data serializer class
class DataSerializer {
public:
    void WriteData(EDataType kind, CDataWrapper* pData, std::ostream& rOutput) {
        switch (kind) {
            case EDataType::Enum: {
                CEnumData* pEnum = dynamic_cast<CEnumData*>(pData);
                if (pEnum) {
                    rOutput << pEnum->Get(nullptr);
                }
                break;
            }
            case EDataType::Bitmask: {
                CBitmaskData* pMask = dynamic_cast<CBitmaskData*>(pData);
                if (pMask) {
                    rOutput << pMask->Get(nullptr);
                }
                break;
            }
            case EDataType::Text: {
                CTextData* pText = dynamic_cast<CTextData*>(pData);
                if (pText) {
                    rOutput << pText->Get(nullptr);
                }
                break;
            }
        }
    }
};

int main() {
    // Example usage of DataSerializer
    DataSerializer writer;

    // Create and serialize an enumeration data
    CEnumData enumData;
    int enumVal = 42;
    writer.WriteData(EDataType::Enum, &enumData, std::cout);

    // Create and serialize a bitmask data
    CBitmaskData maskData;
    int maskVal = 123;
    writer.WriteData(EDataType::Bitmask, &maskData, std::cout);

    // Create and serialize a text data
    CTextData stringData;
    std::string textValue = "Hello, World!";
    writer.WriteData(EDataType::Text, &stringData, std::cout);

    return 0;
}

