// Compute derived components from dynamic state variables
std::vector<double> computeDynamicTerms(const DVec<double>& stateDeriv, const DVec<double>& bodyRates, const DVec<double>& accel) {
    // Partition the state derivative vector into subsystems
    DVec<double> bodyDynPart = stateDeriv.segment(0, 6);
    DVec<double> jointAccelPart = stateDeriv.segment(6, 12);

    // Prepare container for computed terms
    std::vector<double> dynamicTerms;

    // Perform element-wise combination of subsystem values
    for (int idx = 0; idx < 6; ++idx) {
        dynamicTerms.push_back(bodyDynPart[idx] * jointAccelPart[idx]);
    }

    return dynamicTerms;
}

int main() {
    // Demonstration usage
    DVec<double> stateDeriv(18);   // Assume stateDeriv is initialized with proper data
    DVec<double> bodyRates(6);     // Assume bodyRates is initialized appropriately
    DVec<double> jointAccel(12);   // Assume jointAccel is initialized appropriately

    std::vector<double> output = computeDynamicTerms(stateDeriv, bodyRates, jointAccel);

    // Display results
    for (double term : output) {
        std::cout << term << " ";
    }
    std::cout << std::endl;

    return 0;
}

