// Class definitions for tensor computation graph
class Tensor {};
class Node {};
class Input {};

class Output {
public:
    // Constructor initializes the output with node, index, and tensor
    Output(Node* node_ptr, int idx, Tensor* tensor_ptr) : m_node(node_ptr), m_index(idx), m_tensor(tensor_ptr) {}

    // Add an input to the list of connected inputs
    void add_input(Input* new_input) {
        // Ensure no duplicates by checking if input already exists
        bool found = false;
        for (auto& item : m_inputs) {
            if (item == new_input) {
                found = true;
                break;
            }
        }
        if (!found) {
            m_inputs.push_back(new_input);
        }
    }

    // Remove a specific input from the list
    void remove_input(Input* target_input) {
        for (size_t i = 0; i < m_inputs.size(); ++i) {
            if (m_inputs[i] == target_input) {
                m_inputs.erase(m_inputs.begin() + i);
                break;
            }
        }
    }

    // Return the count of connected inputs
    int get_num_inputs() const {
        return static_cast<int>(m_inputs.size());
    }

private:
    Node* m_node;
    int m_index;
    Tensor* m_tensor;
    std::vector<Input*> m_inputs;
};

int main() {
    // Create nodes and tensors for the computation graph
    Node* node_obj = new Node();
    Tensor* tensor_obj = new Tensor();

    // Initialize output with node, index 0, and tensor
    Output out(node_obj, 0, tensor_obj);

    // Create input objects
    Input* inp1 = new Input();
    Input* inp2 = new Input();

    // Connect inputs to the output
    out.add_input(inp1);
    out.add_input(inp2);

    std::cout << "Input count after additions: " << out.get_num_inputs() << std::endl;

    // Disconnect one input
    out.remove_input(inp1);

    std::cout << "Input count after removal: " << out.get_num_inputs() << std::endl;

    return 0;
}

