using ActionFunc = std::function<void()>;
template <typename ResultType, typename... Parameters>
using FunctionSignature = std::function<ResultType(Parameters...)>;

class DelegateHandler
{
public:
    // Store a callable object of type std::function<void()>
    void AssignAction(std::function<void()> func)
    {
        m_Callback = func;
    }

    // Store a delegate of type std::function<double(double, char)>
    void AssignFunction(std::function<double(double, char)> func)
    {
        m_Function = func;
    }

    // Execute the stored callable object
    void RunAction()
    {
        if (m_Callback)
        {
            m_Callback();
        }
    }

    // Execute the stored delegate with the given arguments
    double RunFunction(double value, char flag)
    {
        if (m_Function)
        {
            return m_Function(value, flag);
        }
        return 0.0; // Default return value if function is not set
    }

private:
    std::function<void()> m_Callback;
    std::function<double(double, char)> m_Function;
};

