GLuint ConvertToGLTexture(const TextureData& texData) {
    GLuint textureHandle;
    glGenTextures(1, &textureHandle);
    glBindTexture(GL_TEXTURE_2D, textureHandle);

    glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA, texData.imgWidth, texData.imgHeight, 0, GL_RGBA, GL_UNSIGNED_BYTE, &texData.pixels[0]);

    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_LINEAR);
