class Projectile {
public:
    Projectile(Ogre::Entity* model, Ogre::SceneManager* manager);
    void tick(float timeStep);
    void exertForce(Ogre::Vector2 impulse);
    void checkBoundaryCollision(int windowWidth, int windowHeight);
private:
    Ogre::SceneNode* projectileNode;
    Ogre::Vector2 projectileSpeed;
    Ogre::Vector2 projectilePos;
};

Projectile::Projectile(Ogre::Entity* model, Ogre::SceneManager* manager) {
    // Initialize projectile
    // Set initial position and scale
    projectileNode = manager->getRootSceneNode()->createChildSceneNode();
    projectileNode->setPosition(0, 30, 0); // near center of screen
    projectileNode->setScale(0.15f, 0.15f, 0.15f);
    projectileNode->attachObject(model);
    // Initialize velocity and position to zero
    projectileSpeed = Ogre::Vector2(0.0f, 0.0f);
    projectilePos = Ogre::Vector2(0.0f, 0.0f);
}

void Projectile::tick(float timeStep) {
    // Update projectile's position based on its speed and elapsed time
    projectilePos += projectileSpeed * timeStep;
    projectileNode->setPosition(projectilePos.x, 30, projectilePos.y); // assuming Y is vertical axis
}

void Projectile::exertForce(Ogre::Vector2 impulse) {
    // Apply an impulse to the projectile, modifying its speed
    projectileSpeed += impulse;
}

void Projectile::checkBoundaryCollision(int windowWidth, int windowHeight) {
    // Handle collisions with screen edges
    if (projectilePos.x < 0 || projectilePos.x > windowWidth) {
        projectileSpeed.x *= -1; // Flip horizontal direction
    }
    if (projectilePos.y < 0 || projectilePos.y > windowHeight) {
        projectileSpeed.y *= -1; // Flip vertical direction
    }
}

