#include <queue>
#include <mutex>
#include <condition_variable>
#include <thread>

class WorkManager {
public:
    WorkManager(size_t thread_count) : active_(true), active_tasks_(0) {
        for (size_t idx = 0; idx < thread_count; ++idx) {
            workers_.emplace_back([this] { workerLoop(); });
        }
    }

    void processTask() {
        std::unique_lock<std::mutex> lock(mutex_);
        // If the manager is still active, there must be at least one task available after reacquiring the lock
        if (active_) {
            Task current_task = tasks_.front();
            tasks_.pop();
            lock.unlock();
            ++active_tasks_;
            // Run the task
            current_task();  // Task is a callable (function, lambda, or functor)
            lock.lock();
            --active_tasks_;
            cv_.notify_one();
        }
    }

    void shutdown() {
        {
            std::lock_guard<std::mutex> guard(mutex_);
            active_ = false;
        }
        cv_.notify_all();
        for (auto& worker : workers_) {
            worker.join();
        }
    }

private:
    using Task = std::function<void()>;
    std::queue<Task> tasks_;
    std::vector<std::thread> workers_;
    std::mutex mutex_;
    std::condition_variable cv_;
    bool active_;
    size_t active_tasks_;

    void workerLoop() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            cv_.wait(lock, [this] { return !active_ || !tasks_.empty(); });
            if (!active_ && tasks_.empty()) {
                return;
            }
            processTask();
        }
    }
};

