#include <functional>

// Approximate the definite integral using the trapezoidal rule
double trapezoidalApproximation(std::function<double(double)> func, double leftBound, double rightBound, int segments) {
    double stepSize = (rightBound - leftBound) / segments;  // Width of each subinterval
    double result = 0.5 * (func(leftBound) + func(rightBound));  // Initialize with endpoints
    for (int index = 1; index < segments; index++) {
        double xValue = leftBound + index * stepSize;  // Current x position
        result += func(xValue);  // Accumulate function values
    }
    return stepSize * result;  // Multiply by step size for final approximation
}

