    void GatewayMain(int argc, char* argv[]) {
        int listeningPort = 0;
        bool showHelp = false;

        for (int index = 1; index < argc; ++index) {
            std::string currentArg = argv[index];

            if (currentArg == "-p" || currentArg == "--port") {
                if (index + 1 < argc) {
                    listeningPort = std::atoi(argv[index + 1]);

                    if (listeningPort <= 0) {
                        std::cerr << "Error: Invalid port number" << std::endl;
                        return;
                    }

                    ++index;  // Skip the next argument as it has been processed
                } else {
                    std::cerr << "Error: Port number is missing" << std::endl;
                    return;
                }
            } else if (currentArg == "-h" || currentArg == "--help") {
                showHelp = true;
            } else {
                std::cerr << "Error: Unknown option '" << currentArg << "'" << std::endl;
                return;
            }
        }

        if (showHelp) {
            std::cout << "Usage: gateway_app [-p <port> | --port <port>] [-h | --help]" << std::endl;
