namespace MemoryManagement
{
    template<size_t CAPACITY>
    class LinearAllocator
    {
    public:
        LinearAllocator() : current_(0) {
            static_assert(CAPACITY > 0, "CAPACITY must be positive");
            static_assert((CAPACITY & (CAPACITY - 1)) == 0, "CAPACITY must be a power of two");
            static_assert(CAPACITY <= UINT32_MAX, "CAPACITY exceeds uint32_t limit");
            static_assert(alignof(std::max_align_t) <= 8, "Alignment constraint not satisfied");
        }

        void* requestMemory(size_t sizeInBytes) {
            assert(current_ + sizeInBytes <= CAPACITY && "Memory exhausted");
            void* address = &storage_[current_];
            current_ = current_ + sizeInBytes;
            return address;
        }

        void releaseMemory(void* address, size_t sizeInBytes) {
            assert(sizeInBytes <= current_ && "Invalid size for deallocation");
            assert(address == &storage_[current_ - sizeInBytes] && "Pointer mismatch");
            current_ = current_ - sizeInBytes;
        }

    private:
        uint8_t storage_[CAPACITY];
        size_t current_;
    };
}

int main() {
    MemoryManagement::LinearAllocator<2048> memPool;

    // Request memory for an integer value
    double* doublePtr = static_cast<double*>(memPool.requestMemory(sizeof(double)));
    *doublePtr = 3.14159;

    // Release the allocated memory block
    memPool.releaseMemory(doublePtr, sizeof(double));

    return 0;
}

