// Perform a sliding-window averaging filter on the input image
void imageProcessingOperation(const Image& srcImage, Image& dstImage, const Size& kernelSize) {
    for (int row = 0; row < srcImage.height(); ++row) {
        for (int col = 0; col < srcImage.width(); ++col) {
            // Compute the mean pixel intensity within the local neighborhood
            int accumulator = 0;
            for (int ky = 0; ky < kernelSize.height(); ++ky) {
                for (int kx = 0; kx < kernelSize.width(); ++kx) {
                    accumulator += srcImage.pixelAt(col + kx, row + ky);
                }
            }
            int meanValue = accumulator / (kernelSize.width() * kernelSize.height());
            dstImage.setPixel(col, row, meanValue);
        }
    }
}

