template<typename T, typename Idx>
class podarray {
private:
    T* elements;  // Pointer to the dynamically allocated storage
    Idx capacity;  // Number of elements currently stored
public:
    // Constructor: creates array by copying from external buffer
    explicit podarray(const T* source, const Idx count) {
        capacity = count;
        elements = new T[capacity];
        for (Idx index = 0; index < capacity; ++index) {
            elements[index] = source[index];
        }
    }

    // Constructor: initializes from proxy expression template
    template<typename Expr>
    explicit podarray(const Proxy<Expr>& expr_proxy) {
        capacity = expr_proxy.size();
        elements = new T[capacity];
        for (Idx idx = 0; idx < capacity; ++idx) {
            elements[idx] = expr_proxy[idx];
        }
    }

    // Subscript operator for read-write access
    T& operator[] (const Idx pos) {
        return elements[pos];
    }

    // Subscript operator for read-only access
    T operator[] (const Idx pos) const {
        return elements[pos];
    }

    // Function call operator for mutable element access
    T& operator() (const Idx pos) {
        return elements[pos];
    }

    // Function call operator for constant element access
    T operator() (const Idx pos) const {
        return elements[pos];
    }

    // Adjusts the container size, preserving existing elements when possible
    void resize(const Idx new_size) {
        T* temp_storage = new T[new_size];
        Idx copy_limit = (new_size < capacity) ? new_size : capacity;
        for (Idx i = 0; i < copy_limit; ++i) {
            temp_storage[i] = elements[i];
        }
        delete[] elements;
        elements = temp_storage;
        capacity = new_size;
    }

    // Clears the container by releasing memory and resetting size indicator
    void clear() {
        delete[] elements;
        elements = nullptr;
        capacity = 0;
    }

    // Releases allocated memory upon object destruction
    ~podarray() {
        delete[] elements;
    }
};

int main() {
    // Demonstration of the podarray class functionality
    int buffer[] = {10, 20, 30, 40, 50};
    podarray<int, std::size_t> container(buffer, 5);
    std::cout << container[2] << std::endl;  // Output: 30
    container.resize(3);
    std::cout << container[4] << std::endl;  // Output: Undefined behavior / garbage
    container.clear();
    return 0;
}

