#include <openssl/bn.h>
#include <iostream>

// Verify cryptographic computation using modular exponentiation and multiplication
bool checkCryptographicResult(BIGNUM* X, BIGNUM* s, BIGNUM* d_val, BIGNUM* e2_val, 
                              BIGNUM* offset, BIGNUM* t_temp, BIGNUM* exp, 
                              BIGNUM* modulus, BIGNUM* base_m, BIGNUM* T_val, BN_CTX* context) {
    BN_add(X, X, s);
    BN_mod(d_val, X, e2_val, context);
    BN_add(d_val, d_val, offset);
    BN_mod_exp(t_temp, t_temp, exp, modulus, context);
    BN_mod_exp(X, base_m, d_val, modulus, context);
    BN_mod_mul(X, X, T_val, modulus, context);

    if (BN_cmp(X, t_temp) != 0) {
        std::cout << "Verification failed: X != t_temp" << std::endl;
        BN_CTX_free(context);
        return false;
    }

    BN_CTX_free(context);
    return true;
}

