#include "Font/LoadPSF.hpp"
#include <SDL.h>
#include <iostream>

// Renders a PSF font texture to the renderer with scaling
SDL_Texture* RenderPSFFont(const char* fontPath, SDL_Renderer* renderTarget, int scaleFactor) {
    // Load the PSF font data from file
    PSFFont loadedFont = LoadPSF(fontPath);

    // Extract character dimensions from the font header
    int charPixelWidth = loadedFont.header->width;
    int charPixelHeight = loadedFont.header->height;

    // Create an off-screen surface for rendering font glyphs
    SDL_Surface* glyphSurface = SDL_CreateRGBSurface(0, charPixelWidth, charPixelHeight, 32, 0, 0, 0, 0);

    // Process each of the 256 possible characters
    for (int charIndex = 0; charIndex < 256; charIndex++) {
        // Retrieve the bitmap for the current character
        const uint8_t* charBitmap = loadedFont.chars[charIndex];

        // Iterate over each pixel in the character grid
        for (int row = 0; row < charPixelHeight; row++) {
            for (int col = 0; col < charPixelWidth; col++) {
                // Extract individual bit representing the pixel state
                uint8_t isSet = (charBitmap[row] >> (7 - col)) & 1;
                // Assign white for set pixels, black for unset
                uint32_t pixelColor = isSet ? 0xFFFFFFFF : 0x00000000;

                // Write the pixel to the surface buffer
                *((uint32_t*)glyphSurface->pixels + row * charPixelWidth + col) = pixelColor;
            }
        }

        // Convert the surface into a texture for rendering
        SDL_Texture* charTexture = SDL_CreateTextureFromSurface(renderTarget, glyphSurface);

        // Define destination rectangle for scaled placement
        SDL_Rect positionRect = { charIndex * charPixelWidth * scaleFactor, 0, 
                                  charPixelWidth * scaleFactor, charPixelHeight * scaleFactor };

        // Copy the character texture to the main renderer
        SDL_RenderCopy(renderTarget, charTexture, NULL, &positionRect);

        // Release temporary texture resources
        SDL_DestroyTexture(charTexture);
    }

    // Release the temporary surface after all characters are processed
    SDL_FreeSurface(glyphSurface);

    // Return the last created texture (note: this may be undefined behavior if no texture was created)
    return charTexture;
}

