template <typename Value, fcppt::math::size_type Rows, fcppt::math::size_type Cols>
bool matrix_equality_check(
    fcppt::math::matrix::object<Value, Rows, Cols> const &first_matrix,
    fcppt::math::matrix::object<Value, Rows, Cols> const &second_matrix,
    fcppt::math::matrix::object<Value, Rows, Cols> const &expected)
{
    auto const computed = fcppt::math::matrix::binary_map(
        first_matrix,
        second_matrix,
        [](Value const &left, Value const &right) { return left + right; });
    return fcppt::math::matrix::comparison(computed, expected);
}

