const uint32_t DEFAULT_TX_SEQUENCE = 0xFFFFFFFF;
const size_t SEQUENCE_BYTE_COUNT = sizeof(uint32_t);

class TransactionInput {
 private:
  struct PreviousOutput {
    // Implementation details of PreviousOutput
  };
  PreviousOutput previousOutput;
  std::vector<uint8_t> signatureScript;
  uint32_t txSequence;
 public:
  // Method to convert the TransactionInput object into a byte array
  std::vector<uint8_t> toBytes() {
    std::vector<uint8_t> outputBuffer;
    // Serialize the previousOutput struct into the byte array
    std::vector<uint8_t> prevOutBytes(reinterpret_cast<uint8_t*>(&previousOutput), 
                                      reinterpret_cast<uint8_t*>(&previousOutput) + sizeof(PreviousOutput));
    outputBuffer.insert(outputBuffer.end(), prevOutBytes.begin(), prevOutBytes.end());
    // Append the signatureScript vector to the byte array
    outputBuffer.insert(outputBuffer.end(), signatureScript.begin(), signatureScript.end());
    // Append the txSequence value to the byte array
    uint32_t sequenceBE = htobe32(txSequence);  // Convert to big-endian
    uint8_t* sequenceData = reinterpret_cast<uint8_t*>(&sequenceBE);
    outputBuffer.insert(outputBuffer.end(), sequenceData, sequenceData + SEQUENCE_BYTE_COUNT);
    return outputBuffer;
  }
};

