#include <fcppt/math/vector/object.hpp>
#include <fcppt/math/vector/static.hpp>

// Compute the cross product of two 3-dimensional vectors
template <typename T, typename Storage1, typename Storage2>
fcppt::math::vector::static_<T, 3> cross_product(
    fcppt::math::vector::object<T, 3, Storage1> const &first_vector,
    fcppt::math::vector::object<T, 3, Storage2> const &second_vector)
{
  return fcppt::math::vector::static_<T, 3>(
      first_vector[1] * second_vector[2] - first_vector[2] * second_vector[1],
      first_vector[2] * second_vector[0] - first_vector[0] * second_vector[2],
      first_vector[0] * second_vector[1] - first_vector[1] * second_vector[0]);
}

