// Hash table implementation using separate chaining for collision resolution
class HashMap {
private:
    struct Entry {
        LPVOID key;
        LPVOID value;
        Entry* next;  // Next entry in the chain
    };
    Entry** buckets;  // Array of bucket pointers
    size_t capacity;
    size_t size;
    double maxLoadFactor;

    // Compute hash index for a given key
    size_t computeIndex(LPVOID pKey, size_t keySize) {
        // Simple hash computation: sum of bytes modulo capacity
        unsigned long hash = 0;
        unsigned char* bytes = static_cast<unsigned char*>(pKey);
        for (size_t i = 0; i < keySize; ++i) {
            hash = hash * 31 + bytes[i];
        }
        return hash % capacity;
    }

    // Insert new entry at the front of the chain when collision occurs
    void resolveCollision(size_t pos, LPVOID pKey, LPVOID pData) {
        Entry* freshEntry = new Entry;
        freshEntry->key = pKey;
        freshEntry->value = pData;
        freshEntry->next = buckets[pos];
        buckets[pos] = freshEntry;
    }

    // Expand the internal storage and rehash all entries
    void expandBuckets() {
        size_t newCapacity = capacity * 2;
        Entry** newBuckets = new Entry*[newCapacity];
        std::memset(newBuckets, 0, sizeof(Entry*) * newCapacity);

        for (size_t i = 0; i < capacity; ++i) {
            Entry* current = buckets[i];
            while (current != nullptr) {
                size_t newIndex = computeIndex(current->key, /* keySize */ 0); // Simplified
                Entry* temp = current->next;
                current->next = newBuckets[newIndex];
                newBuckets[newIndex] = current;
                current = temp;
            }
        }

        delete[] buckets;
        buckets = newBuckets;
        capacity = newCapacity;
    }

public:
    HashMap(size_t initialCapacity, double loadLimit) {
        capacity = initialCapacity;
        maxLoadFactor = loadLimit;
        buckets = new Entry*[capacity];
        std::memset(buckets, 0, sizeof(Entry*) * capacity);
        size = 0;
    }

    ~HashMap() {
        // Clean up all dynamically allocated entries
        for (size_t i = 0; i < capacity; ++i) {
            Entry* current = buckets[i];
            while (current != nullptr) {
                Entry* next = current->next;
                delete current;
                current = next;
            }
        }
        delete[] buckets;
    }

    // Add or update a key-value mapping
    void put(LPVOID pKey, size_t keyLen, LPVOID pData) {
        if ((double)size / capacity > maxLoadFactor) {
            expandBuckets();
        }

        size_t position = computeIndex(pKey, keyLen);
        if (buckets[position] == nullptr) {
            buckets[position] = new Entry;
            buckets[position]->key = pKey;
            buckets[position]->value = pData;
            buckets[position]->next = nullptr;
        } else {
            resolveCollision(position, pKey, pData);
        }
        ++size;
    }

    // Find the value associated with the given key
    LPVOID get(LPVOID pKey, size_t keyLen) {
        size_t position = computeIndex(pKey, keyLen);
        Entry* probe = buckets[position];
        while (probe != nullptr) {
            // Assuming pointer equality for key comparison (can be extended)
            if (probe->key == pKey) {
                return probe->value;
            }
            probe = probe->next;
        }
        return nullptr;  // Key not found
    }

    // Delete a key-value pair from the map
    void erase(LPVOID pKey, size_t keyLen) {
        size_t position = computeIndex(pKey, keyLen);
        Entry* prev = nullptr;
        Entry* current = buckets[position];

        while (current != nullptr) {
            if (current->key == pKey) {
                if (prev == nullptr) {
                    buckets[position] = current->next;
                } else {
                    prev->next = current->next;
                }
                delete current;
                --size;
                return;
            }
            prev = current;
            current = current->next;
        }
    }
};

