// Render the properties of components belonging to the chosen entity
void RenderInspector(Entity* activeEntity) {
    // Retrieve all components associated with the active entity
    std::vector<Component*> componentList = activeEntity->GetComponents();
    // Traverse each component and display its editable attributes in the inspector panel
    for (Component* comp : componentList) {
        ImGui::Text("Component: %s", comp->GetName().c_str());
        // Display and enable editing of individual component fields
        for (auto& field : comp->GetProperties()) {
            if (field.type == PropertyType::Integer) {
                int currentValue = field.GetValue<int>();
                ImGui::InputInt(field.name.c_str(), &currentValue);
                field.SetValue(currentValue);
            } else if (field.type == PropertyType::Float) {
                float currentValue = field.GetValue<float>();
                ImGui::InputFloat(field.name.c_str(), &currentValue);
                field.SetValue(currentValue);
            } // Additional property types can be handled similarly
        }
    }
}

