// Forward declarations for dependencies
class GraphicsContext;
class FileSystem;

// Base class for all resources
class Resource {
public:
    virtual ~Resource() {}
    // Core resource lifecycle methods
    virtual void Initialize() = 0;
    virtual void Release() = 0;
};

// Manager responsible for handling resource lifecycle and access
class ResourceManager {
private:
    std::unordered_map<std::string, Resource*> resourceTable;
    GraphicsContext* pGraphicsSystem;
    FileSystem* pStorageSystem;
public:
    ResourceManager(GraphicsContext* graphicsSystem, FileSystem* storageSystem)
        : pGraphicsSystem(graphicsSystem), pStorageSystem(storageSystem) {}

    // Add a new resource to the manager
    void AddToRegistry(const std::string& identifier, Resource* resource) {
        resourceTable[identifier] = resource;
    }

    // Load/initialize a resource by name
    void InitializeAsset(const std::string& identifier) {
        if (!pGraphicsSystem || !pStorageSystem) {
            std::cerr << "Required systems not available for asset initialization" << std::endl;
            return;
        }
        auto iter = resourceTable.find(identifier);
        if (iter != resourceTable.end()) {
            iter->second->Initialize();
        } else {
            std::cerr << "Asset '" << identifier << "' does not exist in registry" << std::endl;
        }
    }

    // Unload/release a resource by name
    void ReleaseAsset(const std::string& identifier) {
        auto iter = resourceTable.find(identifier);
        if (iter != resourceTable.end()) {
            iter->second->Release();
        } else {
            std::cerr << "Asset '" << identifier << "' does not exist in registry" << std::endl;
        }
    }

    // Retrieve a pointer to an initialized resource
    Resource* FetchAsset(const std::string& identifier) {
        auto iter = resourceTable.find(identifier);
        if (iter != resourceTable.end()) {
            return iter->second;
        } else {
            std::cerr << "Asset '" << identifier << "' does not exist in registry" << std::endl;
            return nullptr;
        }
    }
};

