    Texture* imageTexture = new Texture();
    assetManager.AddToRegistry("MainTexture", imageTexture);
    assetManager.InitializeAsset("MainTexture");

    // Retrieve and use the loaded asset
    Resource* activeTexture = assetManager.FetchAsset("MainTexture");
    if (activeTexture) {
        // Perform operations with the loaded texture
    }

    // Cleanup allocated resources
    delete pGraphicsSystem;
    delete pStorageSystem;
    delete imageTexture;
    return 0;
}

#include <type_traits>

// Define a type list structure
template<typename...>
struct sequence {};

// Comparison metafunction to check if first type is smaller than second
template<typename T, typename U>
struct size_compare : std::integral_constant<bool, sizeof(T) < sizeof(U)> {};

// Helper for merging two sorted type lists
template<typename L1, typename L2, typename L3, typename Compare>
struct _merge_helper;

// Base case: first list empty, second list non-empty
template<typename... elements>
struct _merge_helper<sequence<>, sequence<elements...>, sequence<elements...>, size_compare>
{
    using type = sequence<elements...>;
};

// Base case: first list non-empty, second list empty
template<typename... elements>
struct _merge_helper<sequence<elements...>, sequence<>, sequence<elements...>, size_compare>
{
    using type = sequence<elements...>;
};

// Recursive case: both lists non-empty
template<typename head1, typename... tail1,
         typename head2, typename... tail2,
         typename... accumulated, typename Comp>
struct _merge_helper<sequence<head1, tail1...>,
                     sequence<head2, tail2...>,
                     sequence<accumulated...>,
                     Comp>
    : std::conditional_t<
        Comp::template apply<head1, head2>::value,
        _merge_helper<sequence<tail1...>, sequence<head2, tail2...>, sequence<accumulated..., head1>, Comp>,
        _merge_helper<sequence<head1, tail1...>, sequence<tail2...>, sequence<accumulated..., head2>, Comp>
    >
{};

int main() {
    // Merge two sorted sequences of types based on their sizes
    using result_sequence = typename _merge_helper<
        sequence<int, double, char>,
        sequence<float, short, long>,
        sequence<>,
        size_compare
    >::type;

    // result_sequence will contain types ordered by increasing sizeof()
    return 0;
}

