using namespace eosio;

// Token contract named "MyToken" with basic issuance and transfer capabilities
class [[eosio::contract]] MyToken : public contract {
public:
  using contract::contract;

  // Create a new token type with given issuer and max supply
  [[eosio::action]]
  void create(name issuer, asset max_supply) {
    require_auth(_self);
    auto token_symbol = max_supply.symbol;
    check(token_symbol.is_valid(), "symbol name is invalid");
    check(max_supply.is_valid(), "supply configuration is invalid");
    check(max_supply.amount > 0, "maximum supply must be greater than zero");

    stats stat_table(_self, token_symbol.code().raw());
    auto existing_entry = stat_table.find(token_symbol.code().raw());
    check(existing_entry == stat_table.end(), "token with this symbol already exists");

    stat_table.emplace(_self, [&](auto& entry) {
      entry.supply.symbol = max_supply.symbol;
      entry.max_supply = max_supply;
      entry.issuer = issuer;
    });
  }

  // Issue additional tokens to a recipient up to the remaining supply
  [[eosio::action]]
  void issue(name receiver, asset amount, std::string note) {
    auto token_symbol = amount.symbol;
    check(token_symbol.is_valid(), "symbol name is invalid");
    check(note.length() <= 128, "note exceeds maximum length of 128 bytes");

    stats stat_table(_self, token_symbol.code().raw());
    auto existing_entry = stat_table.find(token_symbol.code().raw());
    check(existing_entry != stat_table.end(), "no token with this symbol has been created");

    const auto& token_info = *existing_entry;
    require_auth(token_info.issuer);

    check(amount.is_valid(), "amount is not valid");
    check(amount.amount > 0, "must issue a positive amount");
    check(amount.symbol == token_info.supply.symbol, "symbol precision mismatch");
    check(amount.amount <= token_info.max_supply.amount - token_info.supply.amount,
          "requested amount exceeds available supply");

    stat_table.modify(token_info, same_payer, [&](auto& entry) {
      entry.supply += amount;
    });

    add_balance(token_info.issuer, amount, token_info.issuer);

    if (receiver != token_info.issuer) {
      SEND_INLINE_ACTION(*this, transfer, {token_info.issuer, "active"_n},
                         {token_info.issuer, receiver, amount, note});
    }
  }

  // Transfer tokens from one account to another
  [[eosio::action]]
  void transfer(name sender, name recipient, asset amount, std::string note) {
    check(sender != recipient, "cannot transfer to self");
    require_auth(sender);
    check(is_account(recipient), "recipient account does not exist");

    auto symbol_code = amount.symbol.code();
    stats stat_table(_self, symbol_code.raw());
    const auto& token_info = stat_table.get(symbol_code.raw());

    require_recipient(sender);
    require_recipient(recipient);

    check(amount.is_valid(), "invalid amount");
    check(amount.amount > 0, "transfer amount must be positive");
    check(note.length() <= 256, "note exceeds maximum allowed length");

    sub_balance(sender, amount);
    add_balance(recipient, amount, sender);
  }

  // Print the balance of a specific account (requires auth)
  [[eosio::action]]
  void balance(name account_holder) {
    require_auth(account_holder);
    accounts account_table(_self, account_holder.value);
    const auto& user_account = account_table.get(account_holder.value);
    print("Current balance: ", user_account.balance);
  }

private:
  struct [[eosio::table]] user_account {
    asset balance;
    uint64_t primary_key() const { return balance.symbol.code().raw(); }
  };

  struct [[eosio::table]] token_statistics {
    asset supply;
    asset max_supply;
    name issuer;
    uint64_t primary_key() const { return supply.symbol.code().raw(); }
  };

  typedef multi_index<"accounts"_n, user_account> accounts;
  typedef multi_index<"stat"_n, token_statistics> stats;

  // Deduct balance from an account; erase if zero
  void sub_balance(name owner, asset deduction) {
    accounts from_accounts(_self, owner.value);
    const auto& holder = from_accounts.get(deduction.symbol.code().raw(), "no balance record found");
    check(holder.balance.amount >= deduction.amount, "insufficient balance");

    if (holder.balance.amount == deduction.amount) {
      from_accounts.erase(holder);
    } else {
      from_accounts.modify(holder, owner, [&](auto& record) {
        record.balance -= deduction;
      });
    }
  }

  // Add balance to an account; create if needed
  void add_balance(name owner, asset addition, name payer) {
    accounts to_accounts(_self, owner.value);
    auto existing = to_accounts.find(addition.symbol.code().raw());

    if (existing == to_accounts.end()) {
      to_accounts.emplace(payer, [&](auto& record) {
        record.balance = addition;
      });
    } else {
      to_accounts.modify(existing, same_payer, [&](auto& record) {
        record.balance += addition;
      });
    }
  }
};

