    const char* currentPtr = dataStream;
    const char* finalPtr = dataStream + 11;  // Total length of dataStream

    while (currentPtr != finalPtr) {
        int status = ParseSegment(*currentPtr, currentPtr + 1, finalPtr);
        if (status != 0) {
            std::cerr << "Failed to process segment" << std::endl;
            return 1;
        }
    }
    return 0;
}

