// Abstract interface for file handling operations
class file_handler {
public:
  virtual bool load() = 0;
  virtual bool save() = 0;
  virtual ~file_handler() {}
};

// Singleton factory for generating file handlers
class handler_factory {
public:
  static handler_factory& get() {
    static handler_factory instance;
    return instance;
  }

  using generator_func = file_handler* (*)();

  bool addHandler(const std::string& name, generator_func func) {
    return handlers_.insert({name, func}).second;
  }

  file_handler* produce(const std::string& kind, const std::string& path) {
    auto iter = handlers_.find(kind);
    if (iter != handlers_.end()) {
      file_handler* handler = iter->second();
      handler->setPath(path);
      return handler;
    }
    return nullptr;
  }

private:
  handler_factory() = default;
  std::unordered_map<std::string, generator_func> handlers_;
};

