enum class Orientation { Horizontal, Vertical };

class GridManager {
private:
    std::vector<std::vector<char>> matrix;
public:
    GridManager(const std::vector<std::vector<char>>& startGrid) : matrix(startGrid) {}

    std::string extract(int row, int col, Orientation dir, int len) {
        std::string result;
        if (dir == Orientation::Horizontal) {
            for (int j = col; j < col + len; ++j) {
                result += matrix[row][j];
            }
        } else if (dir == Orientation::Vertical) {
            for (int j = row; j < row + len; ++j) {
                result += matrix[j][col];
            }
        }
        return result;
    }
};

