// Function to serialize string data using cereal library
std::string serializeData(const std::string& inputData) {
#if defined ENABLE_BOOST_IOSTREAMS && !defined DISABLE_BOOST_IOSTREAMS
    // Serialize using Boost.IOStreams when available
    std::string resultString;
    boost::iostreams::back_insert_device<std::string> inserter(resultString);
    boost::iostreams::stream<boost::iostreams::back_insert_device<std::string>> outputStream(inserter);
    {
        cereal::BinaryOutputArchive archive(outputStream);
        archive(inputData);
    }
    outputStream.flush();
    return resultString;
#else
    // Fallback to standard C++ stringstream for serialization
    std::stringstream bufferStream;
    {
        cereal::BinaryOutputArchive archive(bufferStream);
        archive(inputData);
    }
    return bufferStream.str();
#endif
}

#include <vector>
#include <string>
#include <unordered_map>
#include <type_traits>
#include <stdexcept>

class group_data
{
public:
    using iterator_type = std::vector<std::string>::const_iterator;
    using size_type = std::vector<std::string>::size_type;

    // Key-value storage implemented with unordered_map
    std::unordered_map<std::string, std::string> store;

    // Template method to fetch value for a specific key
    template<typename ResultType>
    ResultType fetch(const std::string& identifier) const {
        auto position = store.find(identifier);
        if (position != store.end()) {
            try {
                return transform<ResultType>(position->second);
            } catch (const std::invalid_argument&) {
                throw std::invalid_argument("Conversion to requested type failed");
            }
        } else {
            throw std::out_of_range("Specified key not found");
        }
    }

    // Template method to fetch value with fallback default
    template<typename ResultType>
    ResultType fetch(const std::string& identifier, const ResultType& fallback) const {
        auto position = store.find(identifier);
        if (position != store.end()) {
            try {
                return transform<ResultType>(position->second);
            } catch (const std::invalid_argument&) {
                throw std::invalid_argument("Conversion to requested type failed");
            }
        } else {
            return fallback;
        }
    }

private:
    // Internal utility to convert string representation to desired type
    template<typename TargetType>
    TargetType transform(const std::string& input) const {
        if (std::is_same<TargetType, int>::value) {
            return std::stoi(input);
        } else if (std::is_same<TargetType, double>::value) {
            return std::stod(input);
        } else if (std::is_same<TargetType, std::string>::value) {
            return input;
        } else {
            throw std::invalid_argument("Type conversion not supported");
        }
    }
};

