#include <iostream>
#include <map>

// MemoryManager class for tracking and managing dynamic memory allocations
class MemoryManager {
private:
    std::map<void*, size_t> allocatedBlocks; // Stores pointer-address pairs with their sizes

public:
    // Allocate raw memory block of given size
    void* requestMemory(size_t blockSize) {
        void* address = new char[blockSize];
        allocatedBlocks[address] = blockSize;
        return address;
    }

    // Release a previously allocated memory block
    void releaseMemory(void* address) {
        if (allocatedBlocks.find(address) != allocatedBlocks.end()) {
            delete[] static_cast<char*>(address);
            allocatedBlocks.erase(address);
        }
    }

    // Create and allocate a single object of type T
    template <typename T>
    T* createInstance() {
        return new T;
    }

    // Destroy and deallocate a single object of type T
    template <typename T>
    void destroyInstance(T* obj) {
        delete obj;
    }

    // Cleanup all remaining allocations upon destruction
    ~MemoryManager() {
        for (const auto& block : allocatedBlocks) {
            delete[] static_cast<char*>(block.first);
        }
        allocatedBlocks.clear();
    }
};

int main() {
    MemoryManager memController;

    // Request memory for an instance of DataStructure_X
    DataStructure_X* xObj = static_cast<DataStructure_X*>(memController.requestMemory(sizeof(DataStructure_X)));

    // Create a standalone pointer to DataStructure_X
    DataStructure_X* pxObj = memController.createInstance<DataStructure_X>();

    // Request memory for an instance of Record_Y
    Record_Y* yRecord = static_cast<Record_Y*>(memController.requestMemory(sizeof(Record_Y)));

    // Create a standalone pointer to Record_Y
    Record_Y* pyRecord = memController.createInstance<Record_Y>();

    // Clean up all allocated resources
    memController.releaseMemory(xObj);
    memController.destroyInstance(pxObj);
    memController.releaseMemory(yRecord);
    memController.destroyInstance(pyRecord);

    return 0;
}

