#include <set>

class Solution {
public:
    std::set<int> seenRemainders;

    int findMinOnesDivisibleBy(int divisor) {
        // If divisor ends in 0, 2, 4, 5, 6, or 8, no repunit can be divisible by it
        if (divisor % 2 == 0 || divisor % 5 == 0) {
            return -1;
        }

        int currentRemainder = 0;
        for (int numDigits = 1; numDigits <= divisor; numDigits++) {
            currentRemainder = (currentRemainder * 10 + 1) % divisor;
            if (currentRemainder == 0) {
                return numDigits;
            }
        }
        return -1;
    }
};

#include <vector>

// Function to render different types of lights into camera buffers
void RenderLights(const std::vector<LightData>& lightList, std::vector<CameraConstantBuffer>& bufferList)
{
    for (const auto& currentLight : lightList)
    {
        if (currentLight.m_lightType == ELightType::Directional)
        {
            int targetIndex = currentLight.m_renderTargetOffset;
            CameraConstantBuffer camBuffer;
            camBuffer.m_viewProjection = currentLight.m_viewProjection;
            bufferList.push_back(camBuffer);
        }
        else if (currentLight.m_lightType == ELightType::Point)
        {
            int faceCount = 6;
            // Process each cubemap face for point light
            for (int faceIdx = 0; faceIdx < faceCount; ++faceIdx)
            {
                CameraConstantBuffer camBuffer;
                // Set up view and projection matrices per cubemap face
                Vector3 lightPos = currentLight.m_position;
                Vector3 viewDirs[] = { Vector3(1, 0, 0), Vector3(-1, 0, 0), Vector3(0, 1, 0), Vector3(0, -1, 0), Vector3(0, 0, 1), Vector3(0, 0, -1) };
                Vector3 worldUp = Vector3(0, 1, 0);
                Matrix viewMat = BuildViewMatrix(lightPos, lightPos + viewDirs[faceIdx], worldUp);
                Matrix projMat = BuildProjectionMatrixForFace(90.0f, 1.0f, 0.1f, 100.0f); // Standard FOV, aspect, near/far
                camBuffer.m_viewProjection = viewMat * projMat;
                bufferList.push_back(camBuffer);
            }
        }
    }
}

