#include <windows.h>

// Delayed Procedure Call wrapper for Windows timer-based execution
class DeferredCall {
public:
    using Callback = void(*)(void*);
    DeferredCall(Callback callback, void* userData) : callback_(callback), data_(userData), timerHandle_(0) {}

    void StartTimer(unsigned int intervalMs) {
        timerHandle_ = SetTimer(NULL, 0, intervalMs, OnTimer);
    }

    void Stop() {
        if (timerHandle_ != 0) {
            KillTimer(NULL, timerHandle_);
            timerHandle_ = 0;
        }
    }

    ~DeferredCall() {
        Stop();
    }

private:
    static void CALLBACK OnTimer(HWND, UINT, UINT_PTR eventID, DWORD) {
        DeferredCall* instance = reinterpret_cast<DeferredCall*>(eventID);
        instance->callback_(instance->data_);
    }

    Callback callback_;
    void* data_;
    UINT_PTR timerHandle_;
};

