int main() {
    std::queue<std::string> commands;
    std::stack<int> jumpStack;
    std::string cmd;
    int currentLine = 20;

    while (std::cin >> cmd) {
        commands.push(cmd);
        if (cmd == "GOTO" || cmd == "GOSUB") {
            int value;
            std::cin >> value;
            jumpStack.push(value);
        }
        std::cin >> currentLine;
    }

    while (!commands.empty()) {
        std::cout << currentLine << ' ' << commands.front();
        if (commands.front() == "GOTO" || commands.front() == "GOSUB") {
            std::cout << ' ' << jumpStack.top();
            jumpStack.pop();
        }
        std::cout << std::endl;
        commands.pop();
        currentLine += 20;
    }

    return 0;
}

