void processAndModifyDefinitions(smtk::attribute::DefinitionPtr targetDef, smtk::attribute::DefinitionPtr sourceDef) {
    // Ensure both definitions are valid
    if (targetDef && sourceDef) {
        // Look for an item definition named "Input String" in targetDef
        smtk::attribute::StringItemDefinitionPtr inputStringDef = targetDef->itemDefinition("Input String");
        if (!inputStringDef) {
            // Create and add a new string item definition if not found
            inputStringDef = smtk::attribute::StringItemDefinition::New("Input String");
            targetDef->addItemDefinition(inputStringDef);
        }

        // Check for an item definition named "Source String" in sourceDef
        smtk::attribute::StringItemDefinitionPtr sourceStringDef = sourceDef->itemDefinition("Source String");
        if (sourceStringDef) {
            // Remove the "Source String" item definition from sourceDef
            sourceDef->removeItemDefinition(sourceStringDef);
        }
    }
}

