#include <array>

namespace detail {
    template <typename U, std::size_t N, std::size_t pos>
    struct RecursiveTransformReduce {
        static constexpr auto apply(const std::array<U, N> &first,
                                   const std::array<U, N> &second,
                                   const OpTransformer &op_transform,
                                   const OpReducer &op_reduce) {
            return op_reduce(op_transform(first[pos], second[pos]),
                            RecursiveTransformReduce<U, N, pos - 1>::apply(first, second, op_transform, op_reduce));
        }
    };

    template <typename U, std::size_t N>
    struct RecursiveTransformReduce<U, N, 0> {
        static constexpr auto apply(const std::array<U, N> &first,
                                   const std::array<U, N> &second,
                                   const OpTransformer &op_transform,
                                   const OpReducer &op_reduce) {
            return op_reduce(op_transform(first[0], second[0]), U{});
        }
    };
} // namespace detail

template <typename T, std::size_t len, typename TransformerFunc, typename ReducerFunc>
constexpr auto transform_accumulate(const std::array<T, len> &arr1,
                                   const std::array<T, len> &arr2,
                                   TransformerFunc transformer_func,
                                   ReducerFunc reducer_func) -> decltype(transformer_func(arr1[0], arr2[0])) {
    static_assert(len > 0, "array must have at least one element");
    return detail::RecursiveTransformReduce<T, len, len - 1>::apply(arr1, arr2, transformer_func, reducer_func);
}

