class WindowCycleManager {
public:
    enum MoveMode { NEXT, PREV };

    void ProcessWindowCycle(MoveMode mode, bool enableWrap) {
        if (System::GetActive()->manager()->IsDisplayLocked()) {
            // Skip cycling if display is locked
            return;
        }

        // Acquire current list of windows
        std::vector<Window*> openList = RetrieveActiveWindows();

        // Locate the currently focused window
        auto currentFocus = std::find_if(openList.begin(), openList.end(),
            [](Window* w) { return w->isActive; });

        if (currentFocus != openList.end()) {
            // Determine next active window based on direction
            if (mode == NEXT) {
                currentFocus = (currentFocus == openList.end() - 1) ? openList.begin() : currentFocus + 1;
            } else {
                currentFocus = (currentFocus == openList.begin()) ? openList.end() - 1 : currentFocus - 1;
            }

            // Update activation flags for all windows
            for (auto& win : openList) {
                win->isActive = (win == *currentFocus);
            }
        }

        // Apply wrap-around behavior when requested and multiple windows exist
        if (enableWrap && openList.size() > 1) {
            for (auto& win : openList) {
                win->isActive = false;
            }
            openList[0]->isActive = true;
        }
    }

