int main() {
    std::ifstream inputFile("verification_times.txt");
    if (!inputFile) {
        std::cerr << "Error opening file" << std::endl;
        return 1;
    }

    std::map<std::string, double> durationMap;
    std::string phase;
    double duration;

    while (inputFile >> phase >> duration) {
        durationMap[phase] += duration;
    }

    for (auto& item : durationMap) {
        item.second /= 1.0;  // Assuming there is a valid count for each phase
        std::cout << "Average time for " << item.first << ": " << item.second << " milliseconds" << std::endl;
    }

    auto slowestPhase = std::max_element(durationMap.begin(), durationMap.end(),
        [](const auto& x, const auto& y) { return x.second < y.second; });

    std::cout << "Stage with longest time: " << slowestPhase->first << " (" << slowestPhase->second << " milliseconds)" << std::endl;

    return 0;
}

