#include <boost/safe_float/policy/check_addition_overflow.hpp>
#include <boost/safe_float/policy/check_addition_underflow.hpp>
#include <boost/safe_float/policy/check_addition_inexact.hpp>
#include <boost/safe_float/policy/check_addition_invalid_result.hpp>

// Wrapper class for safe floating-point operations
template <typename FloatType>
class FloatingPointWrapper {
public:
    using SafeFloatImpl = boost::safe_float::safe_float<FloatType>;

    FloatingPointWrapper(FloatType val) : safe_value_(val) {}

    // Perform addition with specified policies
    SafeFloatImpl performAddition(const SafeFloatImpl& operand) {
        SafeFloatImpl temp = safe_value_ + operand;
        return temp;
    }

    // Display all error flags from the result
    void displayStatus(const SafeFloatImpl& res) {
        std::cout << "Overflow detected: " << res.error().overflow() << std::endl;
        std::cout << "Underflow detected: " << res.error().underflow() << std::endl;
        std::cout << "Inexact result: " << res.error().inexact() << std::endl;
        std::cout << "Invalid operation: " << res.error().invalid_result() << std::endl;
    }

private:
    SafeFloatImpl safe_value_;
};

int main() {
    // Initialize with different values
    FloatingPointWrapper<double> fpw1(3.14);
    FloatingPointWrapper<double> fpw2(2.71);

    // First addition with overflow and inexact checks enabled
    FloatingPointWrapper<double>::SafeFloatImpl res_a = fpw1.performAddition(fpw2.safe_value_, 
        boost::safe_float::policy::check_addition_overflow{}, 
        boost::safe_float::policy::check_addition_inexact{});
    fpw1.displayStatus(res_a);

    // Second addition with underflow and invalid result checks enabled
    FloatingPointWrapper<double>::SafeFloatImpl res_b = fpw1.performAddition(fpw2.safe_value_, 
        boost::safe_float::policy::check_addition_underflow{}, 
        boost::safe_float::policy::check_addition_invalid_result{});
    fpw1.displayStatus(res_b);

    return 0;
}

