// Helper function to convert FILETIME structure to 64-bit unsigned integer
ULONGLONG convertFileTimeToULL(const FILETIME& ft) {
    return (((ULONGLONG)ft.dwHighDateTime) << 32) | ft.dwLowDateTime;
}

// Global map to hold performance metrics
std::map<std::string, double> performance_metrics;

// Function to compute CPU utilization and store in performance_metrics
void computeCPUUtilization(const FILETIME& current_idle, const FILETIME& current_kernel,
                           const FILETIME& current_user, const FILETIME& prev_idle,
                           const FILETIME& prev_kernel, const FILETIME& prev_user) {
    performance_metrics.clear(); // Reset the map before populating new values

    ULONGLONG user_delta = convertFileTimeToULL(current_user) - convertFileTimeToULL(prev_user);
    ULONGLONG kernel_delta = convertFileTimeToULL(current_kernel) - convertFileTimeToULL(prev_kernel);
    ULONGLONG idle_delta = convertFileTimeToULL(current_idle) - convertFileTimeToULL(prev_idle);

    double utilization = 100.0 * (user_delta + kernel_delta) / (user_delta + kernel_delta + idle_delta);
    performance_metrics["CPU Utilization"] = utilization; // Store computed value
}

