class ExceptionHandler {
public:
    template <typename Callable>
    void process(Callable action) {
        try {
            action();
        } catch (const std::exception& e) {
            auto iter = mapping.find(typeid(e).name());
            if (iter != mapping.end()) {
                throw iter->second();
            } else {
                throw;
            }
        }
    }

    template <typename Source, typename Target>
    void registerMapping() {
        mapping[typeid(Source).name()] = []() { return Target(); };
    }

private:
    std::map<std::string, std::function<std::exception()>> mapping;
};

#define HANDLE_EXCEPTION(handler, code) handler.process([&]() { code; })
