// Helper to find the index of a type in a sequence
template<typename T, template <typename...> class Seq, typename... Elements>
struct FindIndex;

// Base case: when the type is found at position 0
template<typename T, template <typename...> class Seq, typename First, typename... Rest>
struct FindIndex<T, Seq<First, Rest...>, std::size_t Pos> 
    : std::integral_constant<std::size_t, Pos> {};

// Recursive case: type not found yet, continue searching
template<typename T, template <typename...> class Seq, typename First, typename... Rest, std::size_t Pos>
struct FindIndex<T, Seq<First, Rest...>, Pos> 
    : std::integral_constant<std::size_t, 
        (std::is_same_v<T, First> ? Pos : FindIndex<T, Seq<Rest...>, Pos + 1>::value)> {};

// Entry point for FindIndex - uses default starting position 0
template<typename T, template <typename...> class Seq, typename... Elements>
struct FindIndex<T, Seq<Elements...>> 
    : std::integral_constant<std::size_t, 
        (FindIndex<T, Seq<Elements...>, 0>::value == sizeof...(Elements) 
         ? std::numeric_limits<std::size_t>::max() 
         : FindIndex<T, Seq<Elements...>, 0>::value)> {};

// Check if a type exists in the sequence
template<typename T, template <typename...> class Seq, typename... Elements>
struct Contains : std::disjunction<std::is_same<T, Elements>...> {};

