// Function to perform an HTTP GET request and parse the JSON response
Json::Value executeHttpGet(const std::string& serverAddress, int serverPort, const std::string& path) {
    http_client httpClient("http://" + serverAddress + ":" + std::to_string(serverPort));
    uri_builder requestUri(path);
