#include <cmath>
#include <limits>

// Determine if two floating-point numbers are nearly equal within a given ULP tolerance
bool nearly_identical(const float a, const float b, int max_ulp)
{
    // Reinterpret the bit patterns of the floats as integers
    int a_bits = *reinterpret_cast<const int*>(&a);
    int b_bits = *reinterpret_cast<const int*>(&b);

    // Adjust for signed magnitude representation to match floating-point ordering
    if (a_bits < 0)
        a_bits = std::numeric_limits<int>::max() - a_bits + 1;
    if (b_bits < 0)
        b_bits = std::numeric_limits<int>::max() - b_bits + 1;

    // Compute the absolute difference in terms of ULPs
    int ulp_gap = std::abs(a_bits - b_bits);

    // Return true if the ULP difference is within the allowed tolerance
    return ulp_gap <= max_ulp;
}

