TInt64 CliTask::command_lsahci(TInt argc, char **argv) {
  if (argc != 2) {
    Error("lsahci requires precisely one parameter");
    return -1;
  }

  std::string dirPath = argv[1];

  if (!std::filesystem::exists(dirPath)) {
    Error("Specified directory does not exist");
    return -1;
  }

  if (!std::filesystem::is_directory(dirPath)) {
    Error("Provided path is not a directory");
    return -1;
  }

  mWindow->WriteFormatted("Directory '%s' contents:\n", dirPath.c_str());

  for (const auto& item : std::filesystem::directory_iterator(dirPath)) {
    mWindow->WriteFormatted("%s\n", item.path().filename().string().c_str());
  }

  return 0;
}

