class LibraryCloser {
public:
    explicit LibraryCloser(void* lib_handle) : lib_handle_(lib_handle) {}
    ~LibraryCloser() {
        if (lib_handle_) {
            dlclose(lib_handle_);
        }
    }
private:
    void* lib_handle_;
};

int main() {
    // Load the shared library
    void* lib_handle = dlopen("./libexample.so", RTLD_NOW);
    if (!lib_handle) {
        std::cerr << "Failed to open library: " << dlerror() << std::endl;
        return 1;
    }

    LibraryCloser closer{lib_handle};

    dlerror(); // Clear any existing error

    // Define function pointer type for the exported function
    typedef void (*exported_function)();

    // Retrieve the symbol
    exported_function func = reinterpret_cast<exported_function>(dlsym(lib_handle, "exported_func"));
    const char* error = dlerror();
    if (error) {
        std::cerr << "Symbol lookup failed: " << error << std::endl;
        return 1;
    }

    // Execute the loaded function
    func();
    return 0;
}

#include <thread>
#include <iostream>
#include <gtest/gtest.h>

class OrderedPrinter {
public:
    OrderedPrinter() : nextNumber(1) {}

    void executeFirst() {
        displayNumber(1);
    }

    void executeSecond() {
        displayNumber(2);
    }

    void executeThird() {
        displayNumber(3);
    }

private:
    int nextNumber;
    std::mutex mtx;
    std::condition_variable cv;

    void displayNumber(int value) {
        std::unique_lock<std::mutex> guard(mtx);
        cv.wait(guard, [this, value] { return nextNumber == value; });
        std::cout << value << std::endl;
        nextNumber++;
        cv.notify_all();
    }
};

TEST(OrderedPrinterTest, SequenceVerification) {
    OrderedPrinter printer;
    std::thread worker1(&OrderedPrinter::executeFirst, &printer);
    std::thread worker2(&OrderedPrinter::executeSecond, &printer);
    std::thread worker3(&OrderedPrinter::executeThird, &printer);

    worker1.join();
    worker2.join();
    worker3.join();

    std::string result = testing::internal::GetCapturedStdout();
    ASSERT_EQ(result, "123\n");
}

int main(int argc, char** args) {
    testing::InitGoogleTest(&argc, args);
    return RUN_ALL_TESTS();
}

#include <iostream>
#include <thread>
#include <vector>
#include <functional>
#include <mutex>
#include <condition_variable>

class WorkDispatcher {
public:
    WorkDispatcher() : completedCount(0) {}

    void addTask(const std::function<void()>& workItem) {
        std::unique_lock<std::mutex> guard(mtx);
        pendingTasks.push_back(workItem);
    }

    void runAll() {
        std::vector<std::thread> workerThreads;

        for (int index = 0; index < pendingTasks.size(); ++index) {
            workerThreads.emplace_back([this, index] {
                std::unique_lock<std::mutex> lock(mtx);
                if (index < pendingTasks.size()) {
                    pendingTasks[index]();
                    ++completedCount;
                }
                condition.notify_one();
            });
        }

        for (auto& threadRef : workerThreads) {
            threadRef.join();
        }
    }

    int getCompletedCount() const {
        return completedCount;
    }

private:
    std::vector<std::function<void()>> pendingTasks;
    std::mutex mtx;
    std::condition_variable condition;
    int completedCount;
};

int main() {
    WorkDispatcher dispatcher;

    // Add tasks to the dispatcher
    dispatcher.addTask([] { std::cout << "First job done" << std::endl; });
    dispatcher.addTask([] { std::cout << "Second job done" << std::endl; });
    dispatcher.addTask([] { std::cout << "Third job done" << std::endl; });

    // Execute all scheduled tasks concurrently
    dispatcher.runAll();

    // Display the number of completed tasks
    std::cout << "Number of completed tasks: " << dispatcher.getCompletedCount() << std::endl;

    return 0;
}

#include <QObject>
#include <QThread>
#include <QVector>
#include <complex>
#include <fftw3.h>

class FFTProcessor : public QObject {
    Q_OBJECT
public:
    FFTProcessor(int size) : m_size(size) {
        m_inputData.resize(size);
        m_outputData.resize(size);
        // Setup FFTW plan with specified length and flags
        m_plan = fftw_plan_dft_1d(size, reinterpret_cast<fftw_complex*>(m_inputData.data()),
                                  reinterpret_cast<fftw_complex*>(m_outputData.data()), FFTW_BACKWARD, FFTW_ESTIMATE);
    }
    ~FFTProcessor() {
        fftw_destroy_plan(m_plan);
    }

public slots:
    void handleInput(const QVector<double>& data) {
        // Transfer incoming data to internal buffer
        std::copy(data.begin(), data.end(), m_inputData.begin());
        // Launch processing in dedicated thread
        m_workerThread = new QThread();
        moveToThread(m_workerThread);
        connect(m_workerThread, &QThread::started, this, &FFTProcessor::runFFT);
        connect(this, &FFTProcessor::processingDone, m_workerThread, &QThread::quit);
        connect(this, &FFTProcessor::processingDone, this, &FFTProcessor::deleteLater);
        connect(m_workerThread, &QThread::finished, m_workerThread, &QThread::deleteLater);
        m_workerThread->start();
    }

signals:
    void processingDone(const QVector<std::complex<double>>& output);

private:
    int m_size;
    QVector<double> m_inputData;
    QVector<std::complex<double>> m_outputData;
    fftw_plan m_plan;
    QThread* m_workerThread;

    void runFFT() {
        // Execute the actual FFT computation
        fftw_execute(m_plan);
        // Prepare result vector from internal buffer
        QVector<std::complex<double>> result(m_size);
        for (int idx = 0; idx < m_size; ++idx) {
            result[idx] = std::complex<double>(m_outputData[idx].real(), m_outputData[idx].imag());
        }
        // Notify completion with result
        emit processingDone(result);
    }
};

