#include <iostream>
#include <stack>
using namespace std;

class MinStack {
private:
    stack<int> dataStack;
    stack<int> minTracker;
public:
    void push(int value) {
        // Insert new element into the primary stack
        dataStack.push(value);

        // Maintain minimum tracking stack
        if (minTracker.empty() || value <= minTracker.top()) {
            minTracker.push(value);
        }
    }

    void pop() {
        // Remove top element from main stack
        if (dataStack.top() == minTracker.top()) {
            minTracker.pop();
        }
        dataStack.pop();
    }

    int peek() {
        return dataStack.top();
    }

    bool isEmpty() {
        return dataStack.empty();
    }

    int findMin() {
        return minTracker.top();
    }
};

