using namespace std;

const int MAX_NODES = 1005; // Maximum number of nodes in the graph
int adjMatrix[MAX_NODES][MAX_NODES]; // Adjacency matrix for the graph
int inDegree[MAX_NODES];             // Array to track incoming edges count per node
int numNodes;                        // Total number of nodes

// Perform topological sort using Kahn's algorithm
int topoSort() {
    vector<int> resultOrder; // Stores the final topological sequence
    queue<int> processQueue; // Queue for BFS processing

    // Initialize: enqueue all nodes with zero in-degree
    for (int node = 0; node < numNodes; node++) {
        if (inDegree[node] == 0) {
            processQueue.push(node);
        }
    }

    // Process nodes in BFS manner
    while (!processQueue.empty()) {
        int current = processQueue.front();
        processQueue.pop();
        resultOrder.push_back(current); // Add current node to result

        // Check all possible neighbors
        for (int neighbor = 0; neighbor < numNodes; neighbor++) {
            if (adjMatrix[current][neighbor] != 0) { // Edge exists
                inDegree[neighbor]--;                 // Reduce in-degree
                if (inDegree[neighbor] == 0) {       // If in-degree becomes zero
                    processQueue.push(neighbor);     // Add to queue
                }
            }
        }
    }

    // Check if all nodes were processed (no cycle)
    if (resultOrder.size() != numNodes) {
        return -1; // Cycle detected, topological sort not possible
    } else {
        return resultOrder.size(); // Return count of sorted nodes
    }
}

int main() {
    // Read graph data and initialize in-degrees
    // ...

    int outcome = topoSort();
    if (outcome == -1) {
        cout << "Impossible\n";
    } else {
        cout << outcome << '\n';
    }

    return 0;
}

