template<typename ResultType, typename SourceOperator, typename Operator>
struct lift_traits
{
    using result_value_type = std::remove_cv_t<std::remove_reference_t<ResultType>>;
    using source_operator_type = std::remove_cv_t<std::remove_reference_t<SourceOperator>>;
    using operator_type = std::remove_cv_t<std::remove_reference_t<Operator>>;
    using source_value_type = typename source_operator_type::value_type;
