// Compute the HPCP (Harmonic Pitch Class Profile) from frequencies and magnitudes
std::vector<double> computeHPCP(const std::vector<double>& freqs, const std::vector<double>& mags) {
    std::vector<double> result(12, 0.0);  // Create HPCP vector initialized to zero

    // Process each frequency-magnitude pair
    for (size_t idx = 0; idx < freqs.size(); ++idx) {
        double freq = freqs[idx];
        double mag = mags[idx];

        // Determine the pitch class using logarithmic scaling relative to A4 (440 Hz)
        int pc_index = static_cast<int>(12.0 * std::log2(freq / 440.0) + 0.5) % 12;

        // Accumulate magnitude into the appropriate pitch class bin
        result[pc_index] += mag;
    }

    return result;
}

