class Shape {
public:
    virtual double calculateArea() const = 0;
    virtual double calculateBoundaryLength() const = 0;
    virtual ~Shape() {}
};

class Coordinate2D {
    double xCoordinate, yCoordinate;
public:
    Coordinate2D(double x, double y) : xCoordinate(x), yCoordinate(y) {}
    double getX() const { return xCoordinate; }
    double getY() const { return yCoordinate; }
};

class Polyline : public Shape {
    std::vector<Coordinate2D> vertices;
public:
    Polyline(const std::vector<Coordinate2D>& coords) : vertices(coords) {}
    double calculateArea() const override {
        // Compute area using the shoelace formula
        if (vertices.size() < 3) return 0.0;
        double area = 0.0;
        size_t n = vertices.size();
        for (size_t i = 0; i < n; ++i) {
            size_t j = (i + 1) % n;
            area += vertices[i].getX() * vertices[j].getY();
            area -= vertices[j].getX() * vertices[i].getY();
        }
        return std::abs(area) / 2.0;
    }
    double calculateBoundaryLength() const override {
        // Compute perimeter by summing edge lengths
        if (vertices.size() < 2) return 0.0;
        double length = 0.0;
        size_t n = vertices.size();
        for (size_t i = 0; i < n; ++i) {
            size_t j = (i + 1) % n;
            double dx = vertices[j].getX() - vertices[i].getX();
            double dy = vertices[j].getY() - vertices[i].getY();
            length += std::sqrt(dx * dx + dy * dy);
        }
        return length;
    }
};

class Disk : public Shape {
    double radiusValue;
public:
    Disk(double r) : radiusValue(r) {}
    double calculateArea() const override {
        return M_PI * radiusValue * radiusValue;
    }
    double calculateBoundaryLength() const override {
        return 2.0 * M_PI * radiusValue;
    }
};

