class ComplexNumber {
private:
    double realPart;
    double imaginaryPart;
public:
    // Constructor
    ComplexNumber(double r, double i) : realPart(r), imaginaryPart(i) {}

    // Accessor methods
    double getReal() const { return realPart; }
    double getImag() const { return imaginaryPart; }

    // Addition operation
    ComplexNumber operator+(const ComplexNumber& rhs) const {
        return ComplexNumber(realPart + rhs.realPart, imaginaryPart + rhs.imaginaryPart);
    }

    // Subtraction operation
    ComplexNumber operator-(const ComplexNumber& rhs) const {
        return ComplexNumber(realPart - rhs.realPart, imaginaryPart - rhs.imaginaryPart);
    }

    // Multiplication operation
    ComplexNumber operator*(const ComplexNumber& rhs) const {
        return ComplexNumber(
            realPart * rhs.realPart - imaginaryPart * rhs.imaginaryPart,
            realPart * rhs.imaginaryPart + imaginaryPart * rhs.realPart
        );
    }

    // Compute complex conjugate
    ComplexNumber getConjugate() const {
        return ComplexNumber(realPart, -imaginaryPart);
    }
};

