std::vector<int> find_next_greater(int size, const std::vector<int>& input_array) {
    std::vector<int> output(size, -1);  // Initialize output array with -1
    std::stack<int> index_stack;  // Stack to store indices of elements
    for (int position = 0; position < size; position++) {
        while (!index_stack.empty() && input_array[position] > input_array[index_stack.top()]) {
            output[index_stack.top()] = input_array[position];  // Update output for elements with next greater element
            index_stack.pop();  // Remove the index as it has been processed
        }
        index_stack.push(position);  // Push the current position onto the stack
    }
    return output;
}

