#include <vector>

// Binary Indexed Tree (Fenwick Tree) implementation
template <typename T>
class binary_indexed_tree {
  std::vector<T> tree;
  T combine(T left, T right) const { return left + right; }

public:
  // Constructor for BIT with size N
  binary_indexed_tree(size_t size) : tree(size + 1, IDENTITY) {}

  // Constructor that initializes all elements with value val
  binary_indexed_tree(size_t size, T val) : tree(size + 1, IDENTITY) {
    for (int index = 0; index < (int)size; index++) {
      modify(index, val);
    }
  }

  // Update the value at position idx by adding val
  void modify(int position, T value) {
    position++;
    while (position < tree.size()) {
      tree[position] = combine(tree[position], value);
      position += position & -position;
    }
  }

  // Query prefix sum from index 0 to idx-1
  T prefix_query(int position) const {
    T result = IDENTITY;
    while (position > 0) {
      result = combine(result, tree[position]);
      position -= position & -position;
    }
    return result;
  }
};

