// Binary tree class with implicit conversion to unsigned int
class TreeStructure {
private:
    struct TreeNode {
        int data;
        TreeNode* leftChild;
        TreeNode* rightChild;
        TreeNode(int val) : data(val), leftChild(nullptr), rightChild(nullptr) {}
    };

    TreeNode* rootNode;

    // Recursive helper to build the tree from array representation
    TreeNode* buildTreeRecursively(const std::vector<int>& nodeValues, int currentIndex) {
        if (currentIndex < static_cast<int>(nodeValues.size())) {
            TreeNode* current = new TreeNode(nodeValues[currentIndex]);
            current->leftChild = buildTreeRecursively(nodeValues, 2 * currentIndex + 1);
            current->rightChild = buildTreeRecursively(nodeValues, 2 * currentIndex + 2);
            return current;
        }
        return nullptr;
    }

public:
    // Public interface to construct the tree
    void initializeTree(const std::vector<int>& values) {
        rootNode = buildTreeRecursively(values, 0);
    }

    // Conversion operator to allow implicit cast to unsigned integer
    operator unsigned int() const {
        return static_cast<unsigned int>(rootNode->data);
    }
};

int main() {
    TreeStructure myTree;
    myTree.initializeTree({1, 2, 3, 4, 5, 6, 7});
    unsigned int rootData = myTree; // Implicit conversion occurs here
    std::cout << "Root data: " << rootData << std::endl;
    return 0;
}

