// Map to track client requests: IP -> (count, last_request_time)
std::unordered_map<std::string, std::pair<int, std::chrono::time_point<std::chrono::steady_clock>>> clientRequestTracker;
std::mutex trackerMutex;

// Handle the _v1_all endpoint with rate limiting logic
void _v1_all(const Rest::Request& req, Http::ResponseWriter resp) {
    std::string clientAddr = req.address().host();
    std::lock_guard<std::mutex> guard(trackerMutex);

    auto now = std::chrono::steady_clock::now();

    if (clientRequestTracker.find(clientAddr) == clientRequestTracker.end() || 
        now - clientRequestTracker[clientAddr].second >= std::chrono::seconds(TIME_WINDOW)) {
        // Reset counter when time window expires or for new clients
        clientRequestTracker[clientAddr] = {1, now};
    } else {
        // Increment existing counter within the same time window
        clientRequestTracker[clientAddr].first++;
    }

    if (clientRequestTracker[clientAddr].first > MAX_REQUESTS) {
        // Block request exceeding rate limit
        resp.headers().add<Http::Header::AccessControlAllowOrigin>("*");
        resp.send(Pistache::Http::Code::Too_Many_Requests, "Rate limit exceeded");
    } else {
        // Continue processing valid request
        // ...
    }
}

