#include <iostream>
#include <cmath>

class ComplexNumber {
private:
    double realPart;
    double imagPart;

public:
    // Default constructor
    ComplexNumber() : realPart(0.0), imagPart(0.0) {}

    // Parameterized constructor
    ComplexNumber(double r, double i) : realPart(r), imagPart(i) {}

    // Addition operator overloading
    ComplexNumber operator+(const ComplexNumber& rhs) const {
        return ComplexNumber(realPart + rhs.realPart, imagPart + rhs.imagPart);
    }

    // Subtraction operator overloading
    ComplexNumber operator-(const ComplexNumber& rhs) const {
        return ComplexNumber(realPart - rhs.realPart, imagPart - rhs.imagPart);
    }

    // Multiplication operator overloading
    ComplexNumber operator*(const ComplexNumber& rhs) const {
        return ComplexNumber(
            realPart * rhs.realPart - imagPart * rhs.imagPart,
            realPart * rhs.imagPart + imagPart * rhs.realPart
        );
    }

    // Division operator overloading
    ComplexNumber operator/(const ComplexNumber& rhs) const {
        double denom = rhs.realPart * rhs.realPart + rhs.imagPart * rhs.imagPart;
        return ComplexNumber(
            (realPart * rhs.realPart + imagPart * rhs.imagPart) / denom,
            (imagPart * rhs.realPart - realPart * rhs.imagPart) / denom
        );
    }

    // Output stream insertion operator overloading
    friend std::ostream& operator<<(std::ostream& os, const ComplexNumber& num) {
        os << num.realPart << (num.imagPart >= 0 ? " + " : " - ") 
           << std::abs(num.imagPart) << "i";
        return os;
    }

    // Method to compute the magnitude of the complex number
    double absValue() const {
        return std::sqrt(realPart * realPart + imagPart * imagPart);
    }
};

int main() {
    ComplexNumber x;
    ComplexNumber y(8.0, 0.0);
    ComplexNumber z(0.0, -4.0);
    ComplexNumber w(29.99, 88.44);

    std::cout << "Complex number x: " << x << std::endl;
    std::cout << "Complex number y: " << y << std::endl;
    std::cout << "Complex number z: " << z << std::endl;
    std::cout << "Complex number w: " << w << std::endl;

    ComplexNumber resultSum = y + z;
    ComplexNumber resultDiff = y - z;
    ComplexNumber resultProd = y * z;
    ComplexNumber resultQuo = y / z;

    std::cout << "Sum of y and z: " << resultSum << std::endl;
    std::cout << "Difference of y and z: " << resultDiff << std::endl;
    std::cout << "Product of y and z: " << resultProd << std::endl;
    std::cout << "Quotient of y and z: " << resultQuo << std::endl;
    std::cout << "Magnitude of y: " << y.absValue() << std::endl;

    return 0;
}

