#include <vector>
#include <string>
using namespace std;

class Solution {
private:
    void explore(vector<string>& output, string& digits, int goal, string& currentExpr, long long prevOperand, long long currentVal, int index) {
        if (index == digits.length()) {
            if (currentVal == goal) {
                output.push_back(currentExpr);
            }
            return;
        }

        for (int j = index; j < digits.length(); j++) {
            if (j != index && digits[index] == '0') {
                break;
            }
            string segment = digits.substr(index, j - index + 1);
            long long number = stoll(segment);

            if (index == 0) {
                explore(output, digits, goal, currentExpr + segment, number, number, j + 1);
            } else {
                explore(output, digits, goal, currentExpr + "+" + segment, number, currentVal + number, j + 1);
                explore(output, digits, goal, currentExpr + "-" + segment, -number, currentVal - number, j + 1);
                explore(output, digits, goal, currentExpr + "*" + segment, prevOperand * number, (currentVal - prevOperand) + prevOperand * number, j + 1);
            }
        }
    }

public:
    vector<string> addOperators(string digits, int goal) {
        vector<string> results;
        string expression;
        for (int i = 0; i < digits.length(); i++) {
            if (i != 0 && digits[0] == '0') {
                break;
            }
            string part = digits.substr(0, i + 1);
            long long value = stoll(part);
            explore(results, digits, goal, part, value, value, i + 1);
        }
        return results;
    }
};

#include <iostream>
#include <vector>
#include <algorithm>
#include <climits>

class DirectedWeightedNetwork {
private:
    struct Node {
        std::vector<std::pair<Node*, int>> successors;
    };
    std::vector<Node*> nodes;
public:
    void insert_node() {
        nodes.push_back(new Node());
    }
    void connect(Node* source, Node* destination, int cost) {
        auto& succ = source->successors;
        succ.emplace_back(destination, cost);
    }
    int minimum_cost(Node* start, Node* end) {
        // Dijkstra's algorithm to compute the minimum cost path
        std::vector<int> distance(nodes.size(), INT_MAX);
        distance[start - &nodes[0]] = 0;
        std::vector<bool> processed(nodes.size(), false);
        for (size_t iteration = 0; iteration < nodes.size() - 1; ++iteration) {
            int current = -1;
            for (size_t idx = 0; idx < nodes.size(); ++idx) {
                if (!processed[idx] && (current == -1 || distance[idx] < distance[current])) {
                    current = idx;
                }
            }
            processed[current] = true;
            for (const auto& edge : nodes[current]->successors) {
                int target = edge.first - &nodes[0];
                int edge_weight = edge.second;
                if (!processed[target] && distance[current] != INT_MAX && distance[current] + edge_weight < distance[target]) {
                    distance[target] = distance[current] + edge_weight;
                }
            }
        }
        return distance[end - &nodes[0]];
    }
};

int main() {
    DirectedWeightedNetwork network;
    network.insert_node(); // Insert node A
    network.insert_node(); // Insert node B
    // Add a directed connection from node A to node B with cost 5
    network.connect(network.nodes[0], network.nodes[1], 5);
    // Retrieve the minimum cost from node A to node B
    std::cout << "Minimum cost from node A to node B: " << network.minimum_cost(network.nodes[0], network.nodes[1]) << std::endl;
    return 0;
}

