#include <iostream>
#include <vector>
#include <stack>

// Helper function for DFS-based topological sorting
void Graph::dfsHelper(int currentVertex, bool markedNodes[], std::stack<int> &resultStack) {
    // Mark this vertex as processed
    markedNodes[currentVertex] = true;

    // Explore all adjacent vertices
    for (auto neighbor = neighbors[currentVertex].begin(); neighbor != neighbors[currentVertex].end(); ++neighbor) {
        if (!markedNodes[*neighbor]) {
            dfsHelper(*neighbor, markedNodes, resultStack);
        }
    }

    // Add current vertex to the front of processing sequence
    resultStack.push(currentVertex);
}

// Perform topological ordering of the graph
std::vector<int> Graph::performTopoSort() {
    std::stack<int> resultStack;

    // Initialize all vertices as unvisited
    bool *markedNodes = new bool[verticesCount];
    for (int index = 0; index < verticesCount; index++) {
        markedNodes[index] = false;
    }

    // Process each unvisited vertex
    for (int index = 0; index < verticesCount; index++) {
        if (!markedNodes[index]) {
            dfsHelper(index, markedNodes, resultStack);
        }
    }

    // Build the final ordering from stack contents
    std::vector<int> orderResult;

    // Extract elements from stack to form the topological sequence
    while (!resultStack.empty()) {
        orderResult.push_back(resultStack.top());
        resultStack.pop();
    }

    delete[] markedNodes;
    return orderResult;
}

