#include <cmath>

// Minimum divisor threshold to prevent division by zero
const float MIN_DIVISOR_THRESHOLD = 0.0001f;

// Calculate sphere thickness at a given position using inverse matrix and squared thickness
float calculateSphereThickness(const float inverseMatrix[16], const float pointPosition[3], float squaredThickness) {
    // Extract translation part from the inverse matrix and add position coordinates
    const float dx = inverseMatrix[12] + pointPosition[0];
    const float dy = inverseMatrix[13] + pointPosition[1];
    const float dz = inverseMatrix[14] + pointPosition[2];

    // Compute normalized thickness using squared distance with minimum divisor safeguard
    return squaredThickness / (dx * dx + dy * dy + dz * dz + MIN_DIVISOR_THRESHOLD);
}

