std::vector<double> computeEdgeWeights(const Graph& network, 
                                       const std::vector<double>& feature0, 
                                       const std::vector<double>& feature1, 
                                       const std::vector<bool>& mask) {
    std::vector<double> weightData;

    if (!network.hasEdgeIds()) {
        throw std::runtime_error("edges have not been indexed - call indexEdges first");
    }

    weightData.resize(network.upperEdgeIdBound());

    network.parallelForEdges([&](node src, node dst, edgeid edgeIndex) {
        weightData[edgeIndex] = (mask[edgeIndex] ? feature1[edgeIndex] : feature0[edgeIndex]);
    });

    return weightData;
}

