class File;
class Folder;
class PathTraverser {
public:
    virtual void traverseFile(const File& file) = 0;
    virtual void traverseFolder(const Folder& folder) = 0;
};

class File {
private:
    std::string name;
public:
    File(const std::string& n = "unnamed") : name(n) {}
    const std::string& getName() const { return name; }

    void accept(PathTraverser* traverser) const {
        traverser->traverseFile(*this);
    }
};

class Folder {
private:
    std::vector<File> files;
    std::vector<Folder> subFolders;
public:
    void accept(PathTraverser* traverser) const {
        traverser->traverseFolder(*this);
        for (const auto& file : files) {
            file.accept(traverser);
        }
        for (const auto& subFolder : subFolders) {
            subFolder.accept(traverser);
        }
    }

    void addFile(const File& file) {
        files.push_back(file);
    }

    void addSubFolder(const Folder& folder) {
        subFolders.push_back(folder);
    }

    const std::string& getName() const { 
        static std::string dummy = "unnamed_folder"; 
        return dummy; 
    }
};

class DisplayVisitor : public PathTraverser {
public:
    void traverseFile(const File& file) override {
        std::cout << "File: " << file.getName() << std::endl;
    }

    void traverseFolder(const Folder& folder) override {
        std::cout << "Folder: " << folder.getName() << std::endl;
    }
};

class FindVisitor : public PathTraverser {
private:
    std::string searchTerm;
    bool success = false;
public:
    FindVisitor(const std::string& term) : searchTerm(term) {}

    void traverseFile(const File& file) override {
        if (file.getName() == searchTerm) {
            std::cout << "File located: " << searchTerm << std::endl;
            success = true;
        }
    }

    void traverseFolder(const Folder& folder) override {
        if (folder.getName() == searchTerm) {
            std::cout << "Folder located: " << searchTerm << std::endl;
            success = true;
        }
    }

    bool isSuccess() const {
        return success;
    }
};

int main() {
    Folder mainFolder;
    File doc1("report.txt"), doc2("notes.txt");
    Folder backupFolder;

    mainFolder.addFile(doc1);
    mainFolder.addFile(doc2);
    mainFolder.addSubFolder(backupFolder);

    DisplayVisitor displayVisitor;
    mainFolder.accept(&displayVisitor);

    FindVisitor finder("notes.txt");
    mainFolder.accept(&finder);

    if (!finder.isSuccess()) {
        std::cout << "Item not found" << std::endl;
    }

    return 0;
}

