template <typename T>
struct AdaptiveTree {
  struct TreeNode {
    T data;
    int count;
    TreeNode *leftChild, *rightChild;
  };

  TreeNode *head;

  // Insert a new element into the tree
  void add(TreeNode *&current, const T &item) {
    if (current == nullptr) {
      current = new TreeNode{item, 1, nullptr, nullptr};
    } else if (item < current->data) {
      add(current->leftChild, item);
    } else {
      add(current->rightChild, item);
    }
    adjust(current);
  }

  // Delete an element from the tree
  void erase(TreeNode *&current, const T &item) {
    if (current == nullptr) return;
    if (item < current->data) {
      erase(current->leftChild, item);
    } else if (item > current->data) {
      erase(current->rightChild, item);
    } else {
      if (current->leftChild == nullptr) {
        TreeNode *holder = current->rightChild;
        delete current;
        current = holder;
      } else if (current->rightChild == nullptr) {
        TreeNode *holder = current->leftChild;
        delete current;
        current = holder;
      } else {
        TreeNode *successor = getMinimum(current->rightChild);
        current->data = successor->data;
        current->count = successor->count;
        erase(current->rightChild, successor->data);
      }
    }
    adjust(current);
  }

  // Find the node with minimum value in subtree
  TreeNode *getMinimum(TreeNode *node) {
    while (node->leftChild != nullptr) {
      node = node->leftChild;
    }
    return node;
  }

  // Rebalance the tree when needed
  void adjust(TreeNode *&node) {
    if (node == nullptr) return;
    int leftCount = node->leftChild == nullptr ? 0 : node->leftChild->count;
    int rightCount = node->rightChild == nullptr ? 0 : node->rightChild->count;

    if (leftCount > 3 * rightCount || rightCount > 3 * leftCount) {
      std::vector<T> elements;
      gather(node, elements);
      node = construct(elements, 0, elements.size());
    } else {
      node->count = leftCount + rightCount + 1;
    }
  }

  // Collect all values in sorted order
  void gather(TreeNode *node, std::vector<T> &elements) {
    if (node == nullptr) return;
    gather(node->leftChild, elements);
    elements.push_back(node->data);
    gather(node->rightChild, elements);
  }

  // Build balanced tree from sorted array
  TreeNode *construct(const std::vector<T> &elements, int begin, int finish) {
    if (begin >= finish) return nullptr;
    int middle = (begin + finish) / 2;
    TreeNode *node = new TreeNode{elements[middle], 1, nullptr, nullptr};
    node->leftChild = construct(elements, begin, middle);
    node->rightChild = construct(elements, middle + 1, finish);
    node->count = (node->leftChild == nullptr ? 0 : node->leftChild->count) +
                  (node->rightChild == nullptr ? 0 : node->rightChild->count) + 1;
    return node;
  }

  // Get total number of nodes
  int count(TreeNode *node) {
    return node == nullptr ? 0 : node->count;
  }

  // Calculate sum of values within given range
  T rangeSum(TreeNode *node, const T &minVal, const T &maxVal) {
    if (node == nullptr) return T();
    if (node->data < minVal) {
      return rangeSum(node->rightChild, minVal, maxVal);
    } else if (node->data > maxVal) {
      return rangeSum(node->leftChild, minVal, maxVal);
    } else {
      return node->data + rangeSum(node->leftChild, minVal, node->data) +
             rangeSum(node->rightChild, node->data, maxVal);
    }
  }
};

int main() {
  AdaptiveTree<int> tree;
  tree.add(tree.head, 5);
  tree.add(tree.head, 3);
  tree.add(tree.head, 7);
  tree.add(tree.head, 2);
  tree.add(tree.head, 4);
  tree.add(tree.head, 6);
  tree.add(tree.head, 8);

  std::cout << "Total nodes: " << tree.count(tree.head) << std::endl;
  std::cout << "Sum in range [3, 7]: " << tree.rangeSum(tree.head, 3, 7) << std::endl;

  tree.erase(tree.head, 5);
  std::cout << "Nodes after deletion: " << tree.count(tree.head) << std::endl;

  return 0;
}

