class FoldProcessor {
public:
    // Apply waveform folding based on threshold
    float applyFold(float signal, float limit) {
        if (signal > limit) {
            return 2 * limit - signal;
        } else if (signal < -limit) {
            return -2 * limit - signal;
        } else {
            return signal;
        }
    }
};

