// Compute the length of any container using range-based operations
template <typename Container>
typename qsboost::range_size<Container>::type computeContainerLength(const Container& container) {
    using std::begin;
    using std::end;
    using qsboost::range_size;
    auto start_it = begin(container);
    auto end_it = end(container);
    return range_size<Container>::type(end_it - start_it);
}

int main() {
    std::vector<int> dataVec = {11, 12, 13, 14, 15};
    int numbers[] = {16, 17, 18, 19, 20};
    std::cout << "Vector length: " << computeContainerLength(dataVec) << std::endl;
    std::cout << "Array length: " << computeContainerLength(numbers) << std::endl;
    return 0;
}

