class Alert {
private:
    std::string rule;
    static const std::string RulePrefixCpp;
    static const std::string RulePrefixC;
public:
    std::string GetRuleStringWithLanguagePrefix() const {
        if (rule.find('-') != std::string::npos)
            return RulePrefixCpp + rule;
        else if (rule.find('.') != std::string::npos)
            return RulePrefixC + rule;
        else
            return "";
    }
    bool ContainsCWE() const {
        return (rule.find("CWE") != std::string::npos);
    }
};
const std::string Alert::RulePrefixCpp = "C++ ";
const std::string Alert::RulePrefixC = "C ";

int main() {
    Alert alert1;
    alert1.rule = "MISRA-C++-2008";
    std::cout << alert1.GetRuleStringWithLanguagePrefix() << std::endl;  // Output: C++ MISRA-C++-2008
    std::cout << alert1.ContainsCWE() << std::endl;  // Output: 0 (false)

    Alert alert2;
    alert2.rule = "MISRA.C.2004";
    std::cout << alert2.GetRuleStringWithLanguagePrefix() << std::endl;  // Output: C MISRA.C.2004
    std::cout << alert2.ContainsCWE() << std::endl;  // Output: 0 (false)

    Alert alert3;
    alert3.rule = "MISRA-2004";
    std::cout << alert3.GetRuleStringWithLanguagePrefix() << std::endl;  // Output: C++ MISRA-2004
    std::cout << alert3.ContainsCWE() << std::endl;  // Output: 0 (false)

    Alert alert4;
    alert4.rule = "MISRA-CWE-119";
    std::cout << alert4.GetRuleStringWithLanguagePrefix() << std::endl;  // Output: C++ MISRA-CWE-119
