class StockManager {
private:
    std::map<int, std::pair<std::string, int, double>> stock; // Map to store products with unique ID as key
public:
    void addProduct(int productId, const std::string& productName, int count, double unitCost) {
        if (stock.find(productId) != stock.end()) {
            stock[productId].second += count; // Increase quantity if product already exists
        } else {
            stock[productId] = std::make_pair(productName, count, unitCost); // Add new product to stock
        }
    }

    void deleteProduct(int productId, int amount) {
        if (stock.find(productId) != stock.end()) {
            if (stock[productId].second <= amount) {
                stock.erase(productId); // Remove product entirely if removal exceeds available stock
            } else {
                stock[productId].second -= amount; // Decrease quantity
            }
        }
    }

    void showStock() {
        std::cout << "Current Stock:\n";
        for (const auto& entry : stock) {
            std::cout << "ID: " << entry.first 
                      << ", Name: " << entry.second.first
                      << ", Count: " << entry.second.second 
                      << ", Price: $" << entry.second.third << std::endl;
        }
    }
};

