    warehouse.addProduct(102, "Pen", 200, 1.25);
    warehouse.addProduct(101, "Notebook", 50, 4.50); // Update quantity of existing product
    warehouse.showStock();
    warehouse.deleteProduct(101, 75); // Sell 75 notebooks
    warehouse.showStock();
    return 0;
