// Function to extract parts from a SQL-like SELECT statement
void extractQueryParts(const std::string& sqlStatement) {
    std::string fieldList, tableName, filterClause;
    std::istringstream stream(sqlStatement);
    std::string keyword1, keyword2, keyword3;

    stream >> keyword1 >> fieldList >> keyword2 >> tableName >> keyword3 >> filterClause;

    // Strip trailing comma from field list if exists
    if (!fieldList.empty() && fieldList.back() == ',') {
        fieldList.pop_back();
    }

    // Output parsed components
    std::cout << "Target Table: " << tableName << std::endl;
    std::cout << "Selected Fields:" << std::endl;

    std::istringstream fieldStream(fieldList);
    std::string fieldName;
    while (std::getline(fieldStream, fieldName, ',')) {
        std::cout << fieldName << std::endl;
    }

    std::cout << "Filter Criteria: " << filterClause << std::endl;
}

