class ModuleController {
private:
    std::vector<std::string> modules;
    std::mutex mtx;
public:
    void registerModule(const std::string& moduleName) {
        CHECK_NOT_NULL(&moduleName);
        std::lock_guard<std::mutex> guard(mtx);
        modules.push_back(moduleName);
    }
    void unregisterModule(const std::string& moduleName) {
        CHECK_NOT_NULL(&moduleName);
        std::lock_guard<std::mutex> guard(mtx);
        modules.erase(std::remove(modules.begin(), modules.end(), moduleName), modules.end());
    }
    std::vector<std::string> listModules() {
        std::lock_guard<std::mutex> guard(mtx);
        return modules;
    }
