// Helper function to get size of OpenGL data types
int getTypeSize(int type) {
    switch (type) {
        case GL_FLOAT:
            return sizeof(GLfloat);
        case GL_INT:
            return sizeof(GLint);
        // Additional cases can be added for other supported types
        default:
            throw std::invalid_argument("Unsupported data type");
    }
}

class VertexArray {
public:
    VertexArray(ag::span<VertexAttribute> attributes) {
        // Compute the total byte stride needed for all vertex attributes
        int strideBytes = 0;
        for (const auto& attr : attributes) {
            strideBytes += attr.count * getTypeSize(attr.dataType);
        }

        // Create and bind the vertex array object
        glGenVertexArrays(1, &vaoID);
        glBindVertexArray(vaoID);

        // Set up each vertex attribute with proper configuration
        int byteOffset = 0;
        for (size_t index = 0; index < attributes.size(); ++index) {
            const auto& attr = attributes[index];
            glEnableVertexAttribArray(static_cast<GLuint>(index));
            glVertexAttribPointer(
                static_cast<GLuint>(index),
                attr.count,
                attr.dataType,
                GL_FALSE,
                strideBytes,
                reinterpret_cast<void*>(byteOffset)
            );
            byteOffset += attr.count * getTypeSize(attr.dataType);
        }

        // Release the vertex array binding
        glBindVertexArray(0);
    }

private:
    GLuint vaoID;

    // Internal helper method to determine type size
    int getTypeSize(int type) {
        switch (type) {
            case GL_FLOAT:
                return sizeof(GLfloat);
            case GL_INT:
                return sizeof(GLint);
            default:
                throw std::invalid_argument("Unsupported data type");
        }
    }
};

