#include <mutex>
#include <condition_variable>
#include <queue>

template <typename DataType>
class ConcurrentQueue {
public:
    void add(const DataType& item) {
        std::unique_lock<std::mutex> guard(m_mutex);
        m_data.push(item);
        guard.unlock();  // Release lock before signaling to reduce contention
        m_cv.notify_one();
    }

    DataType remove() {
        std::unique_lock<std::mutex> guard(m_mutex);
        m_cv.wait(guard, [this] { return !m_data.empty(); });
        DataType result = m_data.front();
        m_data.pop();
        return result;
    }

    bool is_empty() const {
        std::lock_guard<std::mutex> guard(m_mutex);
        return m_data.empty();
    }

private:
    std::queue<DataType> m_data;
    mutable std::mutex m_mutex;
    std::condition_variable m_cv;
};

