class StockSpanner {
    stack<pair<int, int>> spans; // stores price and corresponding span count
public:
    StockSpanner() {

    }

    int next(int currentPrice) {
        int spanValue = 1;
        while (!spans.empty() && spans.top().first <= currentPrice) {
            spanValue += spans.top().second;
            spans.pop();
        }
        spans.push(make_pair(currentPrice, spanValue));
        return spanValue;        
    }
};

