void computeTimeEvolution(const Scalar& alpha,
                          const Tensor& K,
                          Tensor& dt_g,
                          const Vector& beta,
                          const Tensor& dgamma,
                          const Tensor& gamma,
                          const Tensor& dbeta) {
  // Number of spatial dimensions
  const size_t Dim = gamma.dimension();
  // Iterate over all index pairs for the symmetric tensor
  for (size_t a = 0; a < Dim; ++a) {
    for (size_t b = 0; b < Dim; ++b) {
      // Initialize with the main contribution from the lapse and extrinsic curvature
      dt_g.get(a, b) = -2. * alpha * K.get(a, b);
      // Add contributions from shift advection and connection terms
      for (size_t c = 0; c < Dim; ++c) {
        dt_g.get(a, b) +=
            beta.get(c) * dgamma.get(c, a, b) +
            gamma.get(c, a) * dbeta.get(b, c) +
            gamma.get(c, b) * dbeta.get(a, c);
      }
    }
  }
}

