#include <boost/asio.hpp>
#include <boost/thread.hpp>
#include <boost/bind.hpp>
#include <boost/ptr_container/ptr_vector.hpp>

class ThreadPoolManager {
public:
    ThreadPoolManager(size_t threadCount) : m_services(threadCount), m_tasks(threadCount) {
        for (size_t idx = 0; idx < threadCount; ++idx) {
            m_tasks.push_back(new boost::asio::io_service::work(m_services[idx]));
            m_pool.create_thread(boost::bind(&boost::asio::io_service::run, &m_services[idx]));
        }
    }

    void enqueueJob(const std::function<void()>& job) {
        size_t slot = m_roundRobin.fetch_add(1) % m_services.size();
        m_services[slot].post(job);
    }

    void shutdownAll() {
        for (size_t k = 0; k < m_services.size(); ++k) {
            m_tasks[k].reset();  // Release work to let services finish pending tasks
            m_services[k].stop();  // Halt the I/O service
        }
        m_pool.join_all();  // Synchronize with all worker threads
    }

private:
    boost::ptr_vector<boost::asio::io_service> m_services;
    boost::ptr_vector<boost::asio::io_service::work> m_tasks;
    boost::thread_group m_pool;
    boost::atomic<size_t> m_roundRobin{0};
};

// Demonstration of usage
int main() {
    ThreadPoolManager pool(4);  // Initialize a pool with 4 io_service instances
    // Enqueue multiple jobs
    for (int taskNum = 0; taskNum < 10; ++taskNum) {
        pool.enqueueJob([taskNum](){
            std::cout << "Job " << taskNum << " processed by thread " << boost::this_thread::get_id() << std::endl;
        });
    }
    // Gracefully terminate all services
    pool.shutdownAll();
    return 0;
}

