#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>

class TaskManager {
public:
    TaskManager() : active(true) {}

    void beginWorker() {
        workerThread = std::thread([this] { this->process(); });
    }

    void enqueueTask(void (*func)()) {
        std::unique_lock<std::mutex> guard(mtx);
        taskQueue.push(func);
        cv.notify_one();
    }

    void process() {
        while (active) {
            std::unique_lock<std::mutex> guard(mtx);
            cv.wait(guard, [this] { return !taskQueue.empty() || !active; });

            if (!taskQueue.empty()) {
                auto currentTask = taskQueue.front();
                taskQueue.pop();
                guard.unlock();  // Unlock before executing the task

                currentTask();  // Run the task
            }
        }
    }

    ~TaskManager() {
        active = false;
        cv.notify_one();  // Wake up the worker thread to terminate
        if (workerThread.joinable()) {
            workerThread.join();
        }
    }

private:
    std::queue<void (*)()> taskQueue;
    std::mutex mtx;
    std::condition_variable cv;
    std::thread workerThread;
    bool active;
};

void taskOne() {
    std::cout << "taskOne(): signal" << std::endl;
