// Check if a binary tree satisfies BST properties
bool checkValidTree(TreeNode* head) {
    return validateTree(head, nullptr, nullptr);
}

bool validateTree(TreeNode* current, TreeNode* lowerBound, TreeNode* upperBound) {
    if (current == nullptr) {
        return true;
    }

    if ((lowerBound != nullptr && current->val <= lowerBound->val) || 
        (upperBound != nullptr && current->val >= upperBound->val)) {
        return false;
    }

    return validateTree(current->left, lowerBound, current) && 
           validateTree(current->right, current, upperBound);
}

