    template<typename T>
    void transpose_inplace(Array<T> &input, const bool do_conjugate)
    {
        dim4 iDims = input.dims();
        if(do_conjugate) {
            if(iDims[0] % kernel::TILE_DIM == 0 && iDims[1] % kernel::TILE_DIM == 0)
                kernel::transpose_inplace<T, true, true>(input);
            else
                kernel::transpose_inplace<T, true, false>(input);
        } else {
            if(iDims[0] % kernel::TILE_DIM == 0 && iDims[1] % kernel::TILE_DIM == 0)
                kernel::transpose_inplace<T, false, true>(input);
            else
                kernel::transpose_inplace<T, false, false>(input);
        }
    }
}

