    ConcreteObserver obs1, obs2;
    pub.registerObserver(&obs1);
    pub.registerObserver(&obs2);
    pub.dispatch("Message A");
    pub.deregisterObserver(&obs1);
    pub.dispatch("Message B");
    return 0;
}

#include <algorithm>  // Added for swap function

void moveZerosToEnd(int arr[], int size) {
    int pos = 0;  // Initialize a pointer to track where non-zero elements should be placed
    for (int j = 0; j < size; j++) {
        if (arr[j] != 0) {
            // Place non-zero element at position pos and increment pos
            std::swap(arr[pos], arr[j]);
            pos++;
        }
    }
}

