// Define the MSRIO class
class MSRIO {
public:
    virtual void write_msr(int core_id, uint64_t reg_addr, uint64_t data_val, uint64_t bit_mask) = 0;
};

// Define the MSR class
class MSR {
public:
    enum operation_mode {
        MODE_RATIO_SCALE
    };
};

// Define the MSRFieldControl class
class MSRFieldControl {
public:
    MSRFieldControl(std::shared_ptr<MSRIO> io_handler, int cpu_id, uint64_t reg_offset,
                    int start_bit, int stop_bit, MSR::operation_mode op, double scale_factor)
        : m_io(io_handler), m_core(cpu_id), m_reg(reg_offset), m_start(start_bit),
          m_stop(stop_bit), m_op(op), m_scale(scale_factor) {}

    void write(double input_value) {
        // Compute mask and field value for writing to the specified MSR bit range
        uint64_t bit_width = m_stop - m_start + 1;
        uint64_t field_mask = (1ULL << bit_width) - 1;
        uint64_t scaled_value = static_cast<uint64_t>(input_value / m_scale);
        scaled_value <<= m_start;
        field_mask <<= m_start;
        m_io->write_msr(m_core, m_reg, scaled_value, field_mask);
    }

private:
    std::shared_ptr<MSRIO> m_io;
    int m_core;
    uint64_t m_reg;
    int m_start;
    int m_stop;
    MSR::operation_mode m_op;
    double m_scale;
};

