// Function to retrieve a registry string value
std::string fetchRegistryString(const std::string& regKey, const std::string& valName) {
    HKEY hKeyHandle;
    std::string resultValue;

    // Attempt to open the specified registry key with read access
    if (RegOpenKeyExA(HKEY_LOCAL_MACHINE, regKey.c_str(), 0, KEY_READ, &hKeyHandle) == ERROR_SUCCESS) {
        DWORD valueType;
        DWORD valueSize;

        // First query to get the required buffer size
        if (RegQueryValueExA(hKeyHandle, valName.c_str(), NULL, &valueType, NULL, &valueSize) == ERROR_SUCCESS) {
            if (valueType == REG_SZ) {
                // Allocate buffer for the string data
                char* tempBuffer = new char[valueSize];

                // Second query to actually retrieve the string data
                if (RegQueryValueExA(hKeyHandle, valName.c_str(), NULL, &valueType, 
                                     reinterpret_cast<LPBYTE>(tempBuffer), &valueSize) == ERROR_SUCCESS) {
                    resultValue = std::string(tempBuffer);
                }

                delete[] tempBuffer;
            }
            // Additional type handling can be added here as needed
        }

        RegCloseKey(hKeyHandle);
    }

    return resultValue;
}

// Unit tests using Google Test framework
TEST(RegistryFetchTest, ValidStringValueCheck) {
    // Retrieve value from registry path "Software\\MyApp" with name "Build"
    std::string actualValue = fetchRegistryString("Software\\MyApp", "Build");
    EXPECT_EQ("3.14159", actualValue.substr(0, 7));
}

TEST(RegistryFetchTest, FallbackBehavior) {
    // Test behavior when key or value doesn't exist
    std::string missingValue = fetchRegistryString("NonExistent\\Path", "MissingKey");
    EXPECT_TRUE(missingValue.empty());
}

