template <typename T, size_t N>
class array_view {
private:
    T* buffer;
    size_t length;
public:
    array_view(T* buffer, size_t length) : buffer(buffer), length(length) {}

    // Assignment operator: copy elements from another view
    array_view& operator=(const array_view& src) {
        for (size_t idx = 0; idx < length; ++idx) {
            buffer[idx] = src.buffer[idx];
        }
        return *this;
    }

    // Addition operator: create a new view with element-wise sum
    array_view operator+(const array_view& rhs) const {
        array_view temp(*this);
        for (size_t idx = 0; idx < length; ++idx) {
            temp.buffer[idx] += rhs.buffer[idx];
        }
        return temp;
    }
};

int main() {
    // Demonstration of array_view usage
    std::vector<double> data = {1.5, 2.5, 3.5, 4.5, 5.5, 6.5};
    array_view<double, 4> view1(&data[0], 4);   // First four elements
    array_view<double, 4> view2(&data[2], 4);   // Elements starting at index 2

    view2 = view1 + view2;  // Add and assign

    // Print the updated data vector
    for (size_t i = 0; i < data.size(); ++i) {
        std::cout << data[i] << " ";
    }
    std::cout << std::endl;
    return 0;
}

