// Map 2D coordinates (eta, phi) to 3D indices for barrel data storage
std::vector<int> coordinateMapper(int row, int col) {
    std::vector<int> result(3);
    result[0] = col / 8;         // Module index in phi direction
    result[1] = row / 8;         // Module index in eta direction
    result[2] = (col % 8) * 8 + (row % 8);  // Fine position within module
    return result;
}

int main() {
    // Predefined arrays for electromagnetic and hadronic calorimeter data
    std::vector<int> emCaloData(72 * 56);   // Electromagnetic calorimeter data
    std::vector<int> hadCaloData(72 * 56);  // Hadronic calorimeter data

    // 3D array structure: [phi_module][eta_module][position]
    std::vector<std::vector<std::vector<int>>> detectorData(
        9, 
        std::vector<std::vector<int>>(7, std::vector<int>(64))
    );

    // Populate detector data using mapping function
    for (int colIndex = 0; colIndex < 72; colIndex++) {
        for (int rowIndex = 0; rowIndex < 56; rowIndex++) {
            std::vector<int> locIndices = coordinateMapper(rowIndex, colIndex);

            // Assign EM calorimeter value
            detectorData[locIndices[0]][locIndices[1]][locIndices[2]] = 
                emCaloData[colIndex * 56 + rowIndex];

            // Assign hadronic calorimeter value (offset by 32)
            detectorData[locIndices[0]][locIndices[1]][locIndices[2] + 32] = 
                hadCaloData[colIndex * 56 + rowIndex];
        }
    }

    return 0;
}

