// Function to compute the maximum weight after connecting ropes with given conditions
int highestWeightAfterRopeConnection(int weights[], int count, int initial) {
    std::sort(weights, weights + count); // Sort the rope weights in ascending order

    int derived[count]; // Array to hold transformed weights
    for (int index = count - 1; index >= 0; index--) {
        derived[index] = weights[index] * initial; // Multiply current weight by initial value
        initial++; // Increment multiplier for next iteration
    }

    std::sort(derived, derived + count); // Sort derived values in ascending order
    int maximum = derived[count - 1]; // The largest value is at the end of sorted array
    return maximum;
}

int main() {
    int weights[] = {4, 3, 2, 6};
    int count = 4;
    int initial = 1;

    std::cout << highestWeightAfterRopeConnection(weights, count, initial) << std::endl;
    return 0;
}

