class ct_RndStore {
private:
    std::mutex mtx_Lock;
    int val_Data;
public:
    // Constructor to initialize val_Data with a random number
    ct_RndStore() {
        std::random_device rng_Source;
        std::mt19937 rng_Generator(rng_Source());
        std::uniform_int_distribution<int> dist_Range(1, 100);
        val_Data = dist_Range(rng_Generator);
    }
    // Method to swap random number data between two ct_RndStore instances
    void Exchange(ct_RndStore &ref_Other) {
        mtx_Lock.lock();
        ref_Other.mtx_Lock.lock();
        std::swap(val_Data, ref_Other.val_Data);
        ref_Other.mtx_Lock.unlock();
        mtx_Lock.unlock();
    }
};

