using feature_volume = int***; // Assuming feature_volume is a pointer to a 3D matrix of features

int compute_total_ops(const std::vector<filter_config>& kernels, const feature_volume data, int begin_idx, int finish_idx) {
    unsigned count = finish_idx - begin_idx + 1;
    assert(finish_idx >= begin_idx);
    assert(count <= kernels.size());

    int kernel_h = kernels[0].dims.height;
    int kernel_w = kernels[0].dims.width;
    int kernel_d = kernels[0].dims.depth;

    // Calculate the total number of operations based on the dimensions of the kernels and the length of the range
    int total_ops = count * kernel_h * kernel_w * kernel_d;
    return total_ops;
}

