enum class SeverityLevel { TRACE, NOTICE, ALERT, CRITICAL, PANIC };

class LoggingSystem {
public:
    LoggingSystem() : minSeverity(SeverityLevel::NOTICE) {}

    void setMinimumSeverity(SeverityLevel level) {
        minSeverity = level;
    }

    void enableConsoleLogging() {
        targets.push_back(&std::cout);
    }

    void enableFileLogging(const std::string& filepath) {
        std::ofstream* stream = new std::ofstream(filepath);
        targets.push_back(stream);
    }

    void write(SeverityLevel severity, const std::string& text) {
        if (severity >= minSeverity) {
            std::lock_guard<std::mutex> guard(mtx);
            for (auto target : targets) {
                *target << getTimestamp() << " [" << severityToString(severity) << "] " << text << std::endl;
            }
        }
    }

    ~LoggingSystem() {
        for (auto target : targets) {
            if (target != &std::cout) {
                std::ofstream* fileStream = static_cast<std::ofstream*>(target);
                fileStream->close();
                delete fileStream;
            }
        }
    }

private:
    SeverityLevel minSeverity;
    std::vector<std::ostream*> targets;
    std::mutex mtx;

    std::string getTimestamp() {
        std::time_t currentTime = std::time(nullptr);
        char timeBuffer[64];
        std::strftime(timeBuffer, sizeof(timeBuffer), "%Y-%m-%d %H:%M:%S", std::localtime(&currentTime));
        return std::string(timeBuffer);
    }

    std::string severityToString(SeverityLevel level) {
        switch (level) {
            case SeverityLevel::TRACE:   return "TRACE";
            case SeverityLevel::NOTICE:  return "NOTICE";
            case SeverityLevel::ALERT:   return "ALERT";
            case SeverityLevel::CRITICAL:return "CRITICAL";
            case SeverityLevel::PANIC:   return "PANIC";
            default:                     return "UNKNOWN";
        }
    }
};

int main() {
    LoggingSystem logger;
    logger.enableConsoleLogging();
    logger.enableFileLogging("application.log");
    logger.setMinimumSeverity(SeverityLevel::TRACE);

    logger.write(SeverityLevel::NOTICE,  "Application started successfully");
    logger.write(SeverityLevel::ALERT,   "Memory usage exceeded threshold");
    logger.write(SeverityLevel::CRITICAL,"Database connection failed");
    logger.write(SeverityLevel::TRACE,   "Entering function processRequest");

    return 0;
}

