// Function to query the count of value-contiguous segments in range [start, end]
int get_segment_count(int start, int end) {
    if (start > end) return 0;
    cout << "1 " << start << " " << end << endl;
    int result;
    cin >> result;
    return result;
}

// Function to exchange elements at positions pos1 and pos2
void swap_positions(int pos1, int pos2) {
    if (pos1 == pos2) return;
    cout << "2 " << pos1 << " " << pos2 << endl;
    int temp;
    cin >> temp;
}

int main() {
    // Speed up I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int array_size, range1, range2;
    if (!(cin >> array_size >> range1 >> range2)) return 0;

    // chain_length tracks how long the current contiguous value sequence is
    int chain_length = 1;

    while (chain_length < array_size) {
        // Determine if the element at position chain_length has a value-adjacent neighbor 
        // in the unprocessed portion of the array (positions chain_length+1 to array_size)
        int total_segments = get_segment_count(chain_length, array_size);
        int rest_segments = get_segment_count(chain_length + 1, array_size);

        if (total_segments <= rest_segments) {
            // Found a value-adjacent element in the remaining part
            int left_bound = chain_length + 1;
            int right_bound = array_size;

            // Binary search to locate the exact position of the adjacent element
            while (left_bound < right_bound) {
                int middle = left_bound + (right_bound - left_bound) / 2;
                int seg_left_part = get_segment_count(chain_length, middle);
                int seg_right_part = get_segment_count(chain_length + 1, middle);

                if (seg_left_part <= seg_right_part) {
                    right_bound = middle;  // Adjacent element is in left half
                } else {
                    left_bound = middle + 1;  // Adjacent element is in right half
                }
            }

            // Move the found element next in the chain
            swap_positions(chain_length + 1, left_bound);
            chain_length++;
        } else {
            // No adjacent element found - current end is a boundary (value 1 or array_size)
            // Reverse the current chain so the other end becomes accessible
            for (int idx = 1; idx <= chain_length / 2; ++idx) {
                swap_positions(idx, chain_length - idx + 1);
            }
            // Continue processing with updated chain orientation
        }
    }

    // Output the resulting permutation
    cout << "3";
    for (int i = 1; i <= array_size; ++i) {
        cout << " " << i;
    }
    cout << endl;

    return 0;
}

#include <vector>

class Solution {
public:
    // Find the pivot index in the array where left sum equals right sum
    int findMiddleIndex(std::vector<int>& values) {
        int size = values.size();
        int prefixSum = 0;
        int grandTotal = 0;

        // Calculate the total sum of all elements
        for(int element : values) {
            grandTotal += element;
        }

        // Check each position for the pivot condition
        for(int index = 0; index < size; index++) {
            // Left sum should equal right sum (total - left - current element)
            if(prefixSum == grandTotal - prefixSum - values[index]) {
                return index;
            }
            prefixSum += values[index];
        }

        return -1;
    }
};

