class Solution {
public:
    // Find the minimum cost triplet starting with first element
    int findMinimumExpense(std::vector<int>& values) {
        int length = values.size();
        int bestValue = INT_MAX;

        for(int idx = 1; idx < length - 1; idx++) {
            for(int kdx = idx + 1; kdx < length; kdx++) {
                int currentTotal = values[0] + values[idx] + values[kdx];
                if(currentTotal < bestValue) {
                    bestValue = currentTotal;
                }
            }
        }

        return bestValue;
    }
};

