#include <sol/sol.hpp>
#include <string>
#include <iostream>

// Demonstrates accessing data from Lua tables using sol3
int main() {
    std::cout << "=== table access ===" << std::endl;
    sol::state lua_vm;

    // Create a Lua array-like table
    lua_vm.script(R"(arrayTable = {"first", "second"})");

    // Create a nested Lua table with key-value pairs
    lua_vm.script(R"(
        complexTable = {
            ["inner"] = {
                ["id"] = "ID_001",
                ["status"] = "active",
            },
            ["label"] = "complexTable",
        }
    )");

    /* Compact retrieval approach */
    // Extract values directly from arrayTable
    /*std::cout << (std::string)lua_vm["arrayTable"][1] << " "
         << (std::string)lua_vm["arrayTable"][2] << '\n';*/

    // Retrieve nested values step-by-step
    auto outer_table = lua_vm.get<sol::table>("complexTable");
    auto inner_table = outer_table.get<sol::table>("inner");

    // Alternative: direct chaining via operator[]
    // sol::table outer_table = lua_vm["complexTable"];
    // sol::table inner_table = outer_table["inner"];

    std::string status_value = lua_vm["complexTable"]["inner"]["status"];
    std::cout << "inner table: id : "
              << inner_table.get<std::string>("id")
              << ", status: " << status_value << '\n';

    std::cout << "label of outer table: " 
              << outer_table.get<std::string>("label") << '\n';

    std::string label_str = outer_table["label"];
    std::cout << "label of outer table: " << label_str << '\n';

    /* Explicit long-form retrieval */
    // Using get<> for arrayTable elements
    std::cout << lua_vm.get<sol::table>("arrayTable").get<std::string>(
         1) << " "
              << lua_vm.get<ol::table>("arrayTable").get<std::string>(
                      2)
              << '\n';

    // Nested access using chained get<>
    std::cout << "inner table: id : "
              << inner_table.get<std::string>("id")
              << ", status: "
              << lua_vm.get<sol::table>("complexTable")
                      .get<sol::table>("inner")
                      .get<std::string>("status")
              << '\n';

    std::cout << "label of outer table: " 
              << outer_table.get<std::string>("label") << '\n';

    std::cout << std::endl;
    return 0;
}

