namespace {
class OcamlGCMetadataPrinter : public GCMetadataPrinter {
public:
  void beginAssembly(Module &M, GCModuleInfo &Info, AsmPrinter &AP) override;
  void finishAssembly(Module &M, GCModuleInfo &Info, AsmPrinter &AP) override;
};
} // end anonymous namespace

static GCMetadataPrinterRegistry::Add<OcamlGCMetadataPrinter>
    Z("ocaml", "ocaml 3.10-compatible collector");

void llvm::linkOcamlGCPrinter() {}

static void EmitCamlGlobal(const Module &M, AsmPrinter &AP, const char *Label) {
  const std::string &ModId = M.getModuleIdentifier();
  std::string SymbolName;
  SymbolName += "caml";
  size_t FirstLetterPos = SymbolName.size();
  SymbolName.append(ModId.begin(), llvm::find(ModId, '.'));
  SymbolName += "__";
  SymbolName += Label;
  // Capitalize the first letter of the module name.
  SymbolName[FirstLetterPos] = toupper(SymbolName[FirstLetterPos]);
  SmallString<128> TempBuffer;
  Mangler::getNameWithPrefix(TempBuffer, SymbolName, M.getDataLayout());
  MCSymbol *Sym = AP.OutContext.getOrCreateSymbol(TempBuffer);
  AP.OutStreamer->emitSymbolAttribute(Sym, MCSA_Global);
  AP.OutStreamer->emitLabel(Sym);
}

void OcamlGCMetadataPrinter::beginAssembly(Module &M, GCModuleInfo &Info,
                                           AsmPrinter &AP) {
  AP.OutStreamer->switchSection(AP.getObjFileLowering().getTextSection());
  EmitCamlGlobal(M, AP, "code_begin");
  AP.OutStreamer->switchSection(AP.getObjFileLowering().getDataSection());
  EmitCamlGlobal(M, AP, "data_begin");
}

/// emitAssembly - Print the frametable. The ocaml frametable format is thus:
///
///   extern "C" struct align(sizeof(intptr_t)) {
///     uint16_t NumDescriptors;
///     struct align(sizeof(intptr_t)) {
///       void *ReturnAddress;
///       uint16_t FrameSize;
///       uint16_t NumLiveOffsets;
///       uint16_t LiveOffsets[NumLiveOffsets];
///     } Descriptors[NumDescriptors];
///   } caml${module}__frametable;
///
/// Note that this precludes programs from stack frames larger than 64K
/// (FrameSize and LiveOffsets would overflow). FrameTablePrinter will abort if
/// either condition is detected in a function which uses the GC.
///
void OcamlGCMetadataPrinter::finishAssembly(Module &M, GCModuleInfo &Info,
                                            AsmPrinter &AP) {
  unsigned PtrSize = M.getDataLayout().getPointerSize();
  AP.OutStreamer->switchSection(AP.getObjFileLowering().getTextSection());
  EmitCamlGlobal(M, AP, "code_end");
  AP.OutStreamer->switchSection(AP.getObjFileLowering().getDataSection());
  EmitCamlGlobal(M, AP, "data_end");
  // FIXME: Why does ocaml emit this??
  AP.OutStreamer->emitIntValue(0, PtrSize);
  AP.OutStreamer->switchSection(AP.getObjFileLowering().getDataSection());
  EmitCamlGlobal(M, AP, "frametable");
  int DescCount = 0;
  for (std::unique_ptr<GCFunctionInfo> &FuncInfo :
       llvm::make_range(Info.funcinfo_begin(), Info.funcinfo_end())) {
    if (FuncInfo->getStrategy().getName() != getStrategy().getName())
      // this function is managed by some other GC
      continue;
    DescCount += FuncInfo->size();
  }
  if (DescCount >= 1 << 16) {
    // Very rude!
    report_fatal_error(" Too much descriptor for ocaml GC");
  }
  AP.emitInt16(DescCount);
  AP.emitAlignment(PtrSize == 4 ? Align(4) : Align(8));
  for (std::unique_ptr<GCFunctionInfo> &FuncInfo :
       llvm::make_range(Info.funcinfo_begin(), Info.funcinfo_end())) {
    if (FuncInfo->getStrategy().getName() != getStrategy().getName())
      // this function is managed by some other GC
      continue;
    uint64_t FrameSize = FuncInfo->getFrameSize();
    if (FrameSize >= 1 << 16) {
      // Very rude!
      report_fatal_error("Function '" + FuncInfo->getFunction().getName() +
                         "' is too large for the ocaml GC! "
                         "Frame size " +
                         Twine(FrameSize) +
                         ">= 65536.\n"
                         "(" +
                         Twine(reinterpret_cast<uintptr_t>(FuncInfo.get())) + ")");
    }
    AP.OutStreamer->AddComment("live roots for " +
                               Twine(FuncInfo->getFunction().getName()));
    AP.OutStreamer->addBlankLine();
    for (GCFunctionInfo::iterator It = FuncInfo->begin(), EndIt = FuncInfo->end();
         It != EndIt; ++It) {
      size_t LiveCount = FuncInfo->live_size(It);
      if (LiveCount >= 1 << 16) {
        // Very rude!
        report_fatal_error("Function '" + FuncInfo->getFunction().getName() +
                           "' is too large for the ocaml GC! "
                           "Live root count " +
                           Twine(LiveCount) + " >= 65536.");
      }
      AP.OutStreamer->emitSymbolValue(It->Label, PtrSize);
      AP.emitInt16(FrameSize);
      AP.emitInt16(LiveCount);
      for (GCFunctionInfo::live_iterator K = FuncInfo->live_begin(It),
                                         KE = FuncInfo->live_end(It);
           K != KE; ++K) {
        if (K->StackOffset >= 1 << 16) {
          // Very rude!
          report_fatal_error(
              "GC root stack offset is outside of fixed stack frame and out "
              "of range for ocaml GC!");
        }
        AP.emitInt16(K->StackOffset);
      }
      AP.emitAlignment(PtrSize == 4 ? Align(4) : Align(8));
    }
  }
}

