using qubit_engine::QuantumRegister;

// Helper function to compare complex numbers within a tolerance
bool is_similar(std::complex<double> x, std::complex<double> y,
                double eps = 1e-5) {
  return std::abs(x - y) < eps;
}

int main(int argc, char **args) {
  MPI_Init(&argc, &args);

  int my_rank;
  MPI_Comm_rank(MPI_COMM_WORLD, &my_rank);

  int total_ranks;
  MPI_Comm_size(MPI_COMM_WORLD, &total_ranks);

  if (total_ranks != 2) {
    if (my_rank == 0) {
      std::cerr << "Error: This test requires exactly 2 MPI processes."
                << std::endl;
    }
    MPI_Finalize();
    return 1;
  }

  // Setup: 4 qubits, each rank holds half the amplitude vector (8 elements)
  // Rank 0 handles global indices [0..7] (MSB of qubit 3 = 0)
  // Rank 1 handles global indices [8..15] (MSB of qubit 3 = 1)
  size_t num_qb = 4;
  QuantumRegister state_reg(num_qb);

  // Initialize in |0000⟩: amplitude 1.0 at index 0 on rank 0, rest zero
  // Step 1: Apply Hadamard to qubit 3 (most significant)
  // Result: (|0000⟩ + |1000⟩)/√2
  // → Rank 0 index 0: 1/√2
  // → Rank 1 index 0 (global 8): 1/√2
  if (my_rank == 0)
    std::cout << "Executing H on qubit 3..." << std::endl;

  state_reg.applyHadamard(3);
  auto amplitudes = state_reg.getStateVector();
  double one_over_root2 = 1.0 / std::sqrt(2.0);

  if (my_rank == 0) {
    assert(is_similar(amplitudes[0], one_over_root2));
  } else {
    assert(is_similar(amplitudes[0], one_over_root2)); // global index 8 = |1000⟩
  }

  // Step 2: Apply CNOT with control=3 (global), target=0 (local)
  // |1000⟩ → |1001⟩, so:
  //   Rank 1 local index 0 (global 8 = |1000⟩) → amplitude 0
  //   Rank 1 local index 1 (global 9 = |1001⟩) → amplitude 1/√2
  // Rank 0 remains unchanged since control qubit 3 is 0 for its indices
  if (my_rank == 0)
    std::cout << "Executing CNOT(3, 0)..." << std::endl;

  state_reg.applyCNOT(3, 0);
  amplitudes = state_reg.getStateVector();

  if (my_rank == 0) {
    // Still |0000⟩ component: amplitude should be 1/√2
    if (is_similar(amplitudes[0], one_over_root2)) {
      std::cout << "[Rank 0] |0000⟩ component confirmed." << std::endl;
    } else {
      std::cerr << "[Rank 0] ERROR: |0000⟩ amplitude mismatch." << std::endl;
      MPI_Finalize();
      return 1;
    }
  } else {
    // Now |1001⟩: local index 1 should hold 1/√2, local index 0 should be 0
    if (is_similar(amplitudes[0], 0.0) && is_similar(amplitudes[1], one_over_root2)) {
      std::cout << "[Rank 1] |1001⟩ component confirmed." << std::endl;
    } else {
      std::cerr << "[Rank 1] ERROR: |1001⟩ amplitude mismatch." << std::endl;
      MPI_Finalize();
      return 1;
    }
  }

  MPI_Finalize();
  return 0;
}

