#include "llvm/Transforms/Utils/UnifyFunctionExitNodes.h"
#include "llvm/IR/BasicBlock.h"
#include "llvm/IR/Function.h"
#include "llvm/IR/Instructions.h"
#include "llvm/IR/Type.h"
#include "llvm/Transforms/Utils.h"

using namespace llvm;

namespace {
bool mergeUnreachableBlocks(Function &F) {
  std::vector<BasicBlock *> UnreachableList;
  for (BasicBlock &BB : F)
    if (isa<UnreachableInst>(BB.getTerminator()))
      UnreachableList.push_back(&BB);

  if (UnreachableList.size() <= 1)
    return false;

  BasicBlock *MergedBlock =
      BasicBlock::Create(F.getContext(), "MergedUnreachable", &F);
  new UnreachableInst(F.getContext(), MergedBlock);

  for (BasicBlock *BB : UnreachableList) {
    BB->back().eraseFromParent(); // Remove original terminator
    BranchInst::Create(MergedBlock, BB);
  }
  return true;
}

bool mergeReturnBlocks(Function &F) {
  std::vector<BasicBlock *> ReturnList;
  for (BasicBlock &BB : F)
    if (isa<ReturnInst>(BB.getTerminator()))
      ReturnList.push_back(&BB);

  if (ReturnList.size() <= 1)
    return false;

  BasicBlock *NewReturnBlock = BasicBlock::Create(F.getContext(),
                                                  "MergedReturn", &F);
  PHINode *PN = nullptr;

  if (F.getReturnType()->isVoidTy()) {
    ReturnInst::Create(F.getContext(), nullptr, NewReturnBlock);
  } else {
    PN = PHINode::Create(F.getReturnType(), ReturnList.size(),
                         "MergedValue");
    PN->insertInto(NewReturnBlock, NewReturnBlock->end());
    ReturnInst::Create(F.getContext(), PN, NewReturnBlock);
  }

  for (BasicBlock *BB : ReturnList) {
    if (PN)
      PN->addIncoming(BB->getTerminator()->getOperand(0), BB);

    BB->back().eraseFromParent(); // Remove return instruction
    BranchInst::Create(NewReturnBlock, BB);
  }
  return true;
}
} // namespace

PreservedAnalyses UnifyFunctionExitNodesPass::run(Function &F,
                                                  FunctionAnalysisManager &AM) {
  bool Modified = false;
  Modified |= mergeUnreachableBlocks(F);
  Modified |= mergeReturnBlocks(F);
  return Modified ? PreservedAnalyses() : PreservedAnalyses::all();
}

export module Karm.Core:base.panic;
import :base.base;
import :base.cstr;

namespace Karm {

export enum class PanicType {
    DEBUG,
    FATAL,
};

using PanicCallback = void (*)(PanicType type, char const* text, usize size);
static PanicCallback panicCallback = nullptr;

export void setPanicCallback(PanicCallback callback) {
    panicCallback = callback;
}

void _trigger(PanicType type, char const* text, usize size) {
    if (panicCallback)
        panicCallback(type, text, size);
    else
        // No handler registered - terminate execution
        __builtin_trap();
}

export void debug(char const* text, usize size) {
    _trigger(PanicType::DEBUG, text, size);
}

export void debug(char const* text) {
    debug(text, cstrLen(text));
}

export [[noreturn]] void fatal(char const* text, usize size) {
    _trigger(PanicType::FATAL, text, size);
    __builtin_unreachable();
}

export [[noreturn]] void fatal(char const* text) {
    fatal(text, cstrLen(text));
}

export [[noreturn]] void unimplemented() {
    fatal("unimplemented", 13);
}

export [[noreturn]] void shouldNotReach() {
    fatal("should not reach", 16);
}

export void breakPoint() {
#ifdef __ck_debug__
#    ifdef __clang__
    __builtin_debugtrap();
#    elif defined(__GNUC__)
    __builtin_trap(); // TODO: use __builtin_debugtrap() when available
#    elif defined(_MSC_VER)
    __debugbreak();
#    else
#        error "Unsupported compiler"
#    endif
#endif
}

} // namespace Karm

