class Solution {
public:
    int countEmployeesMeetingGoal(std::vector<int>& workHours, int goal) {
        int result = 0;
        for (int hours : workHours) {
            if (hours >= goal) {
                result++;
            }
        }
        return result;
    }
};

#include "rslcpp/rslcpp.hpp"
#include <limits>
#include <rslcpp_exceptions/exceptions.hpp>

namespace rslcpp
{
exit_code_t run_simulation(int argc, char ** argv, Job::SharedPtr simulation_job)
{
  // Retrieve the time delay backend instance
  time_delay::CallbackBackend & time_backend = time_delay::CallbackBackend::getInstance();

  // Configure RCLCPP initialization options
  rclcpp::InitOptions init_opts;

  // Initialize the ROS2 context
  rclcpp::init(argc, argv, init_opts);

  // Acquire all nodes from the job
  auto node_list = simulation_job->create_and_get_nodes();

  // Validate that each node is configured to use simulated time
  for (auto & node : node_list) {
    if (!node->get_parameter("use_sim_time").as_bool()) {
      throw exceptions::NodeNotUsingSimTime(node->get_fully_qualified_name());
    }
  }

  // Setup executor with global context
  auto default_context = rclcpp::contexts::get_global_default_context();
  rclcpp::ExecutorOptions exec_opts;
  exec_opts.context = default_context;

  rclcpp::experimental::executors::EventsExecutor executor{
    std::make_unique<rclcpp::experimental::executors::SimpleEventsQueue>(), false,
    exec_opts};

  // Register all nodes with the executor
  for (auto & node : node_list) {
    executor.add_node(node);
  }

  // Initialize simulation clock
  auto sim_clock = simulation_job->get_initial_time();

  // Main simulation loop
  while (!simulation_job->get_finished() && rclcpp::ok(default_context)) {
    // Update time delay backend with current simulation time
    time_backend.set_time(sim_clock.nanoseconds());

    // Synchronize all node clocks to current simulation time
    for (auto & node : node_list) {
      rslcpp::set_clock(sim_clock, node->get_clock());
    }

    // Process any ready delayed callbacks
    time_backend.execute_ready_delayed_callables();

    // Execute all pending callbacks with a very long timeout (effectively until all are done)
    executor.spin_all(
      std::chrono::hours(
        200 * 365 * 24));  // ~200 years ensures all callbacks execute before timeout

#ifdef RSLCPP__CUSTOM__RCLCPP
    // Get next timer deadline if available
    std::chrono::nanoseconds next_timer_event = executor.get_time_until_next_timer();
#else
    // Fallback: assume 1ms delay if custom rclcpp not compiled
    std::chrono::nanoseconds next_timer_event = std::chrono::milliseconds(1);
#endif

    // Terminate simulation if no more timers scheduled
    if (next_timer_event == std::chrono::nanoseconds::max()) {
      break;
    }

    // Determine earliest event between timers and delayed callbacks
    rslcpp::time_delay::Duration next_delayed_event =
      time_backend.get_time_until_next_delayed_callable();

    // Select minimum of the two durations for advancing simulation
    rclcpp::Duration delta_time =
      (next_delayed_event < next_timer_event.count())
        ? std::chrono::nanoseconds(next_delayed_event)
        : next_timer_event;

    // Advance simulation time
    sim_clock += delta_time;
  }

  // Finalize and return exit code
  auto result_code = simulation_job->get_exit_code();
  rclcpp::shutdown();
  return result_code;
}
}  // namespace rslcpp

#include <iostream>
#include <asio.hpp>
#include <boost/bind.hpp>

class timer_printer
{
public:
  timer_printer(asio::io_context& context)
    : interval_timer_(context, asio::chrono::seconds(1)),
      counter_(0)
  {
    interval_timer_.async_wait(boost::bind(&timer_printer::display_count, this));
  }

  ~timer_printer()
  {
    std::cout << "Final count is " << counter_ << std::endl;
  }

  void display_count()
  {
    if (counter_ < 5)
    {
      std::cout << counter_ << std::endl;
      ++counter_;
      interval_timer_.expires_at(interval_timer_.expiry() + asio::chrono::seconds(1));
      interval_timer_.async_wait(boost::bind(&timer_printer::display_count, this));
    }
  }

private:
  asio::steady_timer interval_timer_;
  int counter_;
};

int main()
{
  asio::io_context execution_context;
  timer_printer printer_instance(execution_context);
  execution_context.run();
  return 0;
}

