// Helper functions to convert boolean values to natural numbers with precedence handling
unsigned int BoolNatTernaryPrecedence::class_(const bool b) {
  if (b) {
    return (1 + 0);
  } else {
    return 0;
  }
}

// Extended conversion: true maps to 2, false maps to 3
unsigned int BoolNatTernaryPrecedence::class_0(const bool b) {
  if (b) {
    return ((1 + 0) + 1);
  } else {
    return (((1 + 0) + 1) + 1);
  }
}

#include "holder_vector.h"
#include <library/cpp/testing/unittest/registar.h>

Y_UNIT_TEST_SUITE(THolderVectorTest) {
    Y_UNIT_TEST(TestCreateEmpty) {
        THolderVector<int> collection;
        UNIT_ASSERT_EQUAL(collection.Size(), 0);
        UNIT_ASSERT(!collection);
    }

    Y_UNIT_TEST(TestCreateNonEmpty) {
        THolderVector<int> collection(5);
        UNIT_ASSERT_EQUAL(collection.Size(), 5);
        UNIT_ASSERT(collection);
        for (size_t index = 0; index < collection.Size(); ++index) {
            UNIT_ASSERT_EQUAL(collection[index], (int*)nullptr);
        }
    }

    Y_UNIT_TEST(TestResetValue) {
        THolderVector<int> collection;
        collection.PushBack(new int(10));
        collection.PushBack(new int(20));
        UNIT_ASSERT_VALUES_EQUAL(*collection[0], 10);
        UNIT_ASSERT_VALUES_EQUAL(*collection[1], 20);
        collection.Reset(0, MakeHolder<int>(30));
        collection.Reset(1, MakeHolder<int>(40));
        UNIT_ASSERT_VALUES_EQUAL(*collection[0], 30);
        UNIT_ASSERT_VALUES_EQUAL(*collection[1], 40);
    }

    Y_UNIT_TEST(TestResetNoValue) {
        THolderVector<int> collection;
        collection.Resize(1);
        UNIT_ASSERT_EQUAL(collection[0], (int*)nullptr);
        collection.Reset(0, MakeHolder<int>(99));
        UNIT_ASSERT_UNEQUAL(collection[0], (int*)nullptr);
        UNIT_ASSERT_VALUES_EQUAL(*collection[0], 99);
    }

    Y_UNIT_TEST(TestResetSmartPtr) {
        THolderVector<int> collection;
        collection.Resize(2);
        THolder<int> smartPtr(new int(7));
        collection.Reset(0, std::move(smartPtr));
        UNIT_ASSERT_VALUES_EQUAL(*collection[0], 7);
        UNIT_ASSERT(!smartPtr);
    }

    Y_UNIT_TEST(TestSwap) {
        THolderVector<int> vecA;
        vecA.PushBack(new int(100));
        THolderVector<int> vecB;
        vecA.Swap(vecB);
        UNIT_ASSERT(vecA.empty() && vecB.size() == 1 && *vecB.front() == 100);
    }

    Y_UNIT_TEST(TestUniquePtr) {
        THolderVector<TString> container;
        std::unique_ptr<TString> text(new TString("world"));
        container.PushBack(std::move(text));
        UNIT_ASSERT(container.Size() == 1);
        UNIT_ASSERT(text.get() == nullptr);
    }
} // Y_UNIT_TEST_SUITE(THolderVectorTest)

