int main() {
    // Initialize a JSON object with various data types
    json data =
    {
        {"number", 1}, 
        {"string", "foo"}, 
        {"array", {1, 2}}
    };

    // Access elements using JSON pointers (read-only)
    std::cout << data["/number"_json_pointer] << '\n';
    std::cout << data["/string"_json_pointer] << '\n';
    std::cout << data["/array"_json_pointer] << '\n';
    std::cout << data["/array/1"_json_pointer] << '\n';

    // Modify existing values
    data["/string"_json_pointer] = "bar";
    std::cout << data["string"] << '\n';

    // Add new key-value pair
    data["/boolean"_json_pointer] = true;
    std::cout << data << '\n';

    // Update array element at index 1
    data["/array/1"_json_pointer] = 21;

    // Extend array by adding element at non-existing index
    data["/array/4"_json_pointer] = 44;
    std::cout << data["array"] << '\n';

    // Append to array using "-" pointer
    data["/array/-"_json_pointer] = 55;
    std::cout << data["array"] << '\n';
}

