// Verify header file self-containment
#include "asio/coroutine.hpp"
#include "unit_test.hpp"

// Required after all other includes
#include "asio/yield.hpp"

//------------------------------------------------------------------------------
// Coroutine finishes execution using yield break
void finish_with_yield_break(asio::coroutine& state)
{
  reenter (state)
  {
    yield return;
    yield break;
  }
}

void test_yield_break()
{
  asio::coroutine state;
  ASIO_CHECK(!state.is_complete());
  finish_with_yield_break(state);
  ASIO_CHECK(!state.is_complete());
  finish_with_yield_break(state);
  ASIO_CHECK(state.is_complete());
}
//------------------------------------------------------------------------------
// Coroutine finishes via explicit return
void finish_with_return(asio::coroutine& state)
{
  reenter (state)
  {
    return;
  }
}

void test_return_completion()
{
  asio::coroutine state;
  finish_with_return(state);
  ASIO_CHECK(state.is_complete());
}
//------------------------------------------------------------------------------
// Coroutine finishes by throwing an exception
void finish_by_exception(asio::coroutine& state)
{
  reenter (state)
  {
    throw 42;
  }
}

void test_exception_completion()
{
  asio::coroutine state;
  try { finish_by_exception(state); } catch (...) {}
  ASIO_CHECK(state.is_complete());
}
//------------------------------------------------------------------------------
// Coroutine finishes when control reaches the end of the block
void finish_by_fallthrough(asio::coroutine& state)
{
  reenter (state)
  {
    // Empty block - coroutine completes immediately
  }
}

