// Use __int128 for intermediate products to avoid overflow.
// This is a GCC/Clang extension, standard in competitive programming environments.
using int128 = __int128_t;

// The modulus, read from input.
long long mod;
// Calculates bits(x) = ceil(log2(x+1)).
// For a positive integer x, this is the number of bits in its binary representation.
inline int count_bits(long long val) {
    if (val == 0) {
        return 0;
    }
    // For a 64-bit non-zero integer, the number of bits is 64 - (number of leading zeros).
    // __builtin_clzll is a GCC/Clang intrinsic for "count leading zeros".
    return 64 - __builtin_clzll(val);
}
// Function to simulate the device's computation and calculate the total time.
// This function must correctly model the timing behavior described in the problem.
long long estimate_time(long long base_val, long long exponent) {
    long long elapsed = 0;
    int128 remainder = 1;
    int128 current_base = base_val;
    for (int bit_pos = 0; bit_pos < 60; ++bit_pos) {
        if ((exponent >> bit_pos) & 1) {
            elapsed += (long long)(count_bits((long long)remainder) + 1) * (count_bits((long long)current_base) + 1);
            remainder = remainder * current_base % mod;
        }
        elapsed += (long long)(count_bits((long long)current_base) + 1) * (count_bits((long long)current_base) + 1);
        current_base = current_base * current_base % mod;
    }
    return elapsed;
}
int main() {
    // Fast I/O is crucial for interactive problems.
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);
    // Read the public modulus n.
    std::cin >> mod;
    // From the problem description, d is chosen coprime with m = (p-1)(q-1).
    // Since p and q are primes > 2, p-1 and q-1 are even.
    // Thus m is divisible by 4.
    // For d to be coprime with m, d must be odd.
    // This implies the 0-th bit of d is always 1. We start with this knowledge.
    long long current_guess = 1;
    // Initialize a high-quality random number generator.
    std::mt19937_64 prng(std::chrono::steady_clock::now().time_since_epoch().count());
    std::uniform_int_distribution<long long> range(2, mod - 1);
    // We need to determine 59 bits (from 1 to 59).
    // With a 30000 query limit, we can afford a good number of samples for each bit.
    // Let's use 400 samples per bit, for a total of 59 * 400 = 23600 queries.
    int trials_per_bit = 400;
    // Determine bits one by one, from k=1 to k=59.
    for (int position = 1; position < 60; ++position) {
        long double accumulated_score = 0.0L;

        // At step k, current_guess holds our best guess for d mod 2^k.
        // We form two hypotheses for d mod 2^(k+1).
        long long guess_zero = current_guess;              // Hypothesis: position-th bit is 0.
        long long guess_one = current_guess | (1LL << position); // Hypothesis: position-th bit is 1.
        for (int trial = 0; trial < trials_per_bit; ++trial) {
            // Choose a random base 'a'.
            long long base = range(prng);

            // Query the device and get the execution time.
            std::cout << "? " << base << std::endl;
            long long measured_time;
            std::cin >> measured_time;
            // Calculate the expected time for both hypotheses, using only the bits known so far.
            long long predicted_zero = estimate_time(base, guess_zero);
            long long predicted_one = estimate_time(base, guess_one);

            // Calculate the squared error for both hypotheses.
            int128 error0 = measured_time - predicted_zero;
            int128 error1 = measured_time - predicted_one;

            // Accumulate the difference of squared errors.
            // If d_k=0 is correct, observed_time should be closer to predicted_zero, making error0^2 < error1^2.
            // If d_k=1 is correct, observed_time should be closer to predicted_one, making error0^2 > error1^2.
            accumulated_score += (long double)error0 * error0 - (long double)error1 * error1;
        }

        // If the sum of score differences is positive, it's statistically more likely that d_k=1.
        if (accumulated_score > 0) {
            current_guess = guess_one;
        }
    }
    // Output the final determined value of d.
    std::cout << "! " << current_guess << std::endl;
    return 0;
}

