// Test basic rate limiting functionality with a single concurrent request limit
TEST(RequestLimiterTest, Basic) {
  // Configure the maximum allowed concurrent requests to 1
  FLAGS_max_concurrent_requests = 1;
  RateLimiter limiter;

  // Initially no active requests, so no throttling should occur
  EXPECT_EQ(limiter.is_limited(), false);

  // After one request is counted, the limit is reached and throttling activates
  EXPECT_EQ(limiter.is_limited(), true);

  // Simulate completion of one request to reduce active count
  limiter.decrease_one_request();

  // With zero active requests, throttling is no longer in effect
  EXPECT_EQ(limiter.is_limited(), false);
}
