FTakeRecorderStateProvider::FTakeRecorderStateProvider()
{
	UTakeRecorder::OnRecordingInitialized().AddRaw(this, &FTakeRecorderStateProvider::HandleTakeRecorderInit);
}

void FTakeRecorderStateProvider::HandleTakeRecorderInit(UTakeRecorder* RecorderInstance)
{
	if (RecorderInstance)
	{
		// When recording begins, notify monitors with the current timecode as the start boundary for critical state
		RecorderInstance->OnRecordingStarted().AddRaw(this, &FTakeRecorderStateProvider::HandleTakeRecorderStart);
		// When recording ends or is aborted, send a reliable message with the final timecode to mark the end boundary
		RecorderInstance->OnRecordingCancelled().AddRaw(this, &FTakeRecorderStateProvider::HandleTakeRecorderEnd);
		RecorderInstance->OnRecordingFinished().AddRaw(this, &FTakeRecorderStateProvider::HandleTakeRecorderEnd);
	}

	CurrentState = EStageCriticalStateEvent::Exit;
}

void FTakeRecorderStateProvider::HandleTakeRecorderStart(UTakeRecorder* RecorderInstance)
{
	if (CurrentState == EStageCriticalStateEvent::Exit)
	{
		TakeName = RecorderInstance->GetSequence()->GetFName();
		CurrentState = EStageCriticalStateEvent::Enter;
		IStageDataProvider::SendMessage<FCriticalStateProviderMessage>(EStageMessageFlags::Reliable, CurrentState, TakeName);
	}
}

void FTakeRecorderStateProvider::HandleTakeRecorderEnd(UTakeRecorder* RecorderInstance)
{
	if (CurrentState == EStageCriticalStateEvent::Enter)
	{
		CurrentState = EStageCriticalStateEvent::Exit;
		IStageDataProvider::SendMessage<FCriticalStateProviderMessage>(EStageMessageFlags::Reliable, CurrentState, TakeName);
	}
}
