};

void showHelpMessage() {
    std::cout << "Command line options:" << std::endl
              << std::endl;
    std::cout << "infiniccl-test --<device_type>" << std::endl
              << std::endl;
    std::cout << "  --<device_type>" << std::endl;
    std::cout << "    Choose the device type: --(nvidia|cambricon|ascend|metax|moore|iluvatar|qy|kunlun|hygon|ali)." << std::endl
              << std::endl;
    std::cout << "The test suite will execute on all accessible devices of the selected type."
              << " Control visible device IDs using environment variables like CUDA_VISIBLE_DEVICES.";
    exit(-1);
}

#define HANDLE_DEVICE_OPTION(OPTION, ENUM_VALUE) \
    if (input_arg == OPTION) {                   \
        options.target_device = ENUM_VALUE;      \
    }

CommandLineOptions parseInputArguments(int argc, char *argv[]) {
    if (argc != 2) {
        showHelpMessage();
    }

    std::string arg_value = argv[1];
    if (arg_value == "--help" || arg_value == "-h") {
        showHelpMessage();
    }

    CommandLineOptions options{};
    try {
        std::string input_arg = arg_value;
        // clang-format off
        HANDLE_DEVICE_OPTION("--nvidia", INFINI_DEVICE_NVIDIA)
        else HANDLE_DEVICE_OPTION("--cambricon", INFINI_DEVICE_CAMBRICON)
        else HANDLE_DEVICE_OPTION("--ascend", INFINI_DEVICE_ASCEND)
        else HANDLE_DEVICE_OPTION("--metax", INFINI_DEVICE_METAX)
        else HANDLE_DEVICE_OPTION("--moore", INFINI_DEVICE_MOORE)
        else HANDLE_DEVICE_OPTION("--iluvatar", INFINI_DEVICE_ILUVATAR)
        else HANDLE_DEVICE_OPTION("--qy", INFINI_DEVICE_QY)
        else HANDLE_DEVICE_OPTION("--kunlun", INFINI_DEVICE_KUNLUN)
        else HANDLE_DEVICE_OPTION("--hygon", INFINI_DEVICE_HYGON)
        else HANDLE_DEVICE_OPTION("--ali", INFINI_DEVICE_ALI)
        else {
            showHelpMessage();
        }
        // clang-format on
    } catch (...) {
        showHelpMessage();
    }
    return options;
}

int main(int argc, char *argv[]) {
    CommandLineOptions options = parseInputArguments(argc, argv);
    int device_count = 0;

    infinirtInit();

    if (infinirtGetDeviceCount(options.target_device, &device_count) != INFINI_STATUS_SUCCESS) {
        std::cerr << "Error: Unable to retrieve device count." << std::endl;
        return -1;
    }

    if (device_count == 0) {
        std::cout << "No compatible devices detected. Skipping tests." << std::endl;
        return 0;
    } else {
        std::cout << "Detected " << device_count << " devices. Proceeding with tests..." << std::endl;
    }

    int errors = 0;
    errors += testAllReduce(options.target_device, device_count);

    return errors;
}

