#include <pthread.h>
#include "libcgo.h"

// Retrieve the stack bounds for the current thread
void
x_cgo_getstackbound(uintptr bounds[2])
{
	pthread_attr_t attributes;
	void *stack_addr;
	size_t stack_size;

	// Initialize pthread attributes
	pthread_attr_init(&attributes);

#if defined(__GLIBC__) || defined(__BIONIC__) || (defined(__sun) && !defined(__illumos__))
	// Use GNU extension to get current thread attributes
	pthread_getattr_np(pthread_self(), &attributes);
	pthread_attr_getstack(&attributes, &stack_addr, &stack_size);
#elif defined(__illumos__)
	// Illumos-specific function to retrieve thread attributes
	pthread_attr_get_np(pthread_self(), &attributes);
	pthread_attr_getstack(&attributes, &stack_addr, &stack_size);
#else
	// Fallback: no way to determine exact stack bounds
	stack_addr = 0;
	stack_size = 0;
#endif

	// Clean up attributes object
	pthread_attr_destroy(&attributes);

	// Synchronize with TSAN to avoid false positives on stack reuse
	_cgo_tsan_acquire();
	bounds[0] = (uintptr)stack_addr;
	bounds[1] = (uintptr)stack_addr + stack_size;
	_cgo_tsan_release();
}

#include "ReduceGlobalVarInitializers.h"
#include "llvm/IR/Constants.h"
#include "llvm/IR/GlobalValue.h"
using namespace llvm;

/// Eliminates initial values for global variables that are not part of the target chunks
static void stripGVInitializers(Oracle &O, ReducerWorkItem &WorkItem) {
  // Clear initializers for globals outside the selected chunks
  for (auto &Global : WorkItem.getModule().globals()) {
    if (Global.hasInitializer() && !O.shouldKeep()) {
      Global.setInitializer(nullptr);
      Global.setLinkage(GlobalValue::LinkageTypes::ExternalLinkage);
      Global.setComdat(nullptr);
    }
  }
}

void llvm::reduceGlobalsInitializersDeltaPass(TestRunner &Test) {
  runDeltaPass(Test, stripGVInitializers, "Stripping GV Initializers");
}

