// Structure to hold memory pool usage data
struct memPoolStats
{
    std::uint64_t currentReserved;
    std::uint64_t peakReserved;
    std::uint64_t currentUsed;
    std::uint64_t peakUsed;
};

// Retrieve current and peak memory usage metrics from the pool
void fetchMemoryStats(hipMemPool_t pool, memPoolStats *stats)
{
    HIP_ERROR_CHECK(hipMemPoolGetAttribute(pool, hipMemPoolAttrReservedMemCurrent, &stats->currentReserved));
    HIP_ERROR_CHECK(hipMemPoolGetAttribute(pool, hipMemPoolAttrReservedMemHigh, &stats->peakReserved));
    HIP_ERROR_CHECK(hipMemPoolGetAttribute(pool, hipMemPoolAttrUsedMemCurrent, &stats->currentUsed));
    HIP_ERROR_CHECK(hipMemPoolGetAttribute(pool, hipMemPoolAttrUsedMemHigh, &stats->peakUsed));
}

// Reset high-watermark counters to their current values
void resetPeakCounters(hipMemPool_t pool)
{
    std::uint64_t zero = 0;
    HIP_ERROR_CHECK(hipMemPoolSetAttribute(pool, hipMemPoolAttrReservedMemHigh, &zero));
    HIP_ERROR_CHECK(hipMemPoolSetAttribute(pool, hipMemPoolAttrUsedMemHigh, &zero));
}

int main()
{
    hipMemPool_t pool;
    hipDevice_t devId = 0; // Device identifier

    // Set active device
    HIP_ERROR_CHECK(hipSetDevice(devId));

    // Obtain default memory pool for the device
    HIP_ERROR_CHECK(hipDeviceGetDefaultMemPool(&pool, devId));

    // Allocate a test block of memory (e.g., 2 MB)
    std::size_t blockSize = 2 * 1024 * 1024;
    void* buffer;
    HIP_ERROR_CHECK(hipMalloc(&buffer, blockSize));

    // Deallocate the memory block
    HIP_ERROR_CHECK(hipFree(buffer));

    // Trim the pool to a smaller size (e.g., 768 KB)
    std::size_t targetSize = 768 * 1024;
    HIP_ERROR_CHECK(hipMemPoolTrimTo(pool, targetSize));

    // Collect statistics before resetting counters
    memPoolStats beforeReset;
    fetchMemoryStats(pool, &beforeReset);

    std::cout << "Before resetting counters:" << std::endl;
    std::cout << "Reserved Memory (current): " << beforeReset.currentReserved << " bytes" << std::endl;
    std::cout << "Reserved Memory (peak):    " << beforeReset.peakReserved << " bytes" << std::endl;
    std::cout << "Used Memory (current):     " << beforeReset.currentUsed << " bytes" << std::endl;
    std::cout << "Used Memory (peak):        " << beforeReset.peakUsed << " bytes" << std::endl;

    // Reset high-watermark counters
    resetPeakCounters(pool);

    // Collect statistics after resetting counters
    memPoolStats afterReset;
    fetchMemoryStats(pool, &afterReset);

    std::cout << "After resetting counters:" << std::endl;
    std::cout << "Reserved Memory (current): " << afterReset.currentReserved << " bytes" << std::endl;
    std::cout << "Reserved Memory (peak):    " << afterReset.peakReserved << " bytes" << std::endl;
    std::cout << "Used Memory (current):     " << afterReset.currentUsed << " bytes" << std::endl;
    std::cout << "Used Memory (peak):        " << afterReset.peakUsed << " bytes" << std::endl;

    return EXIT_SUCCESS;
}

