#include "RHIBufferTests.h"

// Copies data from the given vertex buffer to CPU memory and validates it using the provided callback
bool FRHIBufferTests::VerifyBufferContents(const TCHAR* TestName, FRHICommandListImmediate& RHICmdList, FRHIVertexBuffer* Buffer, TFunctionRef<bool(void* Ptr, uint32 NumBytes)> VerifyCallback)
{
	bool bSuccess;
	{
		uint32 ByteCount = Buffer->GetSize();
		FStagingBufferRHIRef StagingBuf = RHICreateStagingBuffer();
		RHICmdList.CopyToStagingBuffer(Buffer, StagingBuf, 0, ByteCount);
		// @todo - readback API is inconsistent across RHIs
		RHICmdList.SubmitCommandsAndFlushGPU();
		RHICmdList.BlockUntilGPUIdle();
		void* DataPtr = RHILockStagingBuffer(StagingBuf, 0, ByteCount);
		bSuccess = VerifyCallback(DataPtr, ByteCount);
		RHIUnlockStagingBuffer(StagingBuf);
	}
	// Immediate flush to clean up staging buffer / other resources
	RHICmdList.ImmediateFlush(EImmediateFlushType::FlushRHIThreadFlushResourcesFlushDeferredDeletes);
	if (!bSuccess)
	{
		UE_LOG(LogRHIUnitTestCommandlet, Error, TEXT("Test failed. \"%s\""), TestName);
	}
	else
	{
		UE_LOG(LogRHIUnitTestCommandlet, Display, TEXT("Test passed. \"%s\""), TestName);
	}
	return bSuccess;
}

// Copies data from the given structured buffer to CPU memory and validates it using the provided callback
bool FRHIBufferTests::VerifyBufferContents(const TCHAR* TestName, FRHICommandListImmediate& RHICmdList, FRHIStructuredBuffer* Buffer, TFunctionRef<bool(void* Ptr, uint32 NumBytes)> VerifyCallback)
{
	bool bSuccess;
	{
		uint32 ByteCount = Buffer->GetSize();
		RHICmdList.ImmediateFlush(EImmediateFlushType::FlushRHIThreadFlushResourcesFlushDeferredDeletes);
		void* DataPtr = RHICmdList.LockStructuredBuffer(Buffer, 0, ByteCount, EResourceLockMode::RLM_ReadOnly);
		bSuccess = VerifyCallback(DataPtr, ByteCount);
		RHICmdList.UnlockStructuredBuffer(Buffer);
	}
	// Immediate flush to clean up resources
	RHICmdList.ImmediateFlush(EImmediateFlushType::FlushRHIThreadFlushResourcesFlushDeferredDeletes);
	if (!bSuccess)
	{
		UE_LOG(LogRHIUnitTestCommandlet, Error, TEXT("Test failed. \"%s\""), TestName);
	}
	else
	{
		UE_LOG(LogRHIUnitTestCommandlet, Display, TEXT("Test passed. \"%s\""), TestName);
	}
	return bSuccess;
}

