#include <iostream>
#include <vector>
#include <utility>
#include <numeric>

int n, m;
std::vector<int> towers[60];
std::vector<std::pair<int, int>> operations;

void transfer_disk(int source, int dest) {
    if (source == dest || towers[source].empty()) {
        return;
    }
    int disk = towers[source].back();
    towers[source].pop_back();
    towers[dest].push_back(disk);
    operations.push_back({source, dest});
}

void shift_all(int source, int dest) {
    while (!towers[source].empty()) {
        transfer_disk(source, dest);
    }
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);
    std::cin >> n >> m;
    for (int idx = 1; idx <= n; ++idx) {
        towers[idx].resize(m);
        for (int pos = 0; pos < m; ++pos) {
            std::cin >> towers[idx][pos];
        }
    }

    // Strategy: Arrange colors sequentially. For color i, gather all balls of color i to tower i.
    // Towers 1 through i-1 are already correctly arranged.
    for (int target = 1; target <= n; ++target) {
        // First, move all balls from unsorted towers (target to n) to the auxiliary tower (n+1).
        for (int src = target; src <= n; ++src) {
            shift_all(src, n + 1);
        }

        // Now, redistribute balls from the auxiliary tower (n+1).
        // Balls of the current target color go to tower target.
        // Balls of other colors k > target go to their respective towers (as temporary storage).
        while (!towers[n + 1].empty()) {
            int ball_value = towers[n + 1].back();
            if (ball_value == target) {
                transfer_disk(n + 1, target);
            } else {
                transfer_disk(n + 1, ball_value);
            }
        }

        // At this stage, tower target is fully sorted and complete.
        // Remaining balls reside on their intended destination towers, prepared for the next phase.
    }

    std::cout << operations.size() << "\n";
    for (const auto& op : operations) {
        std::cout << op.first << " " << op.second << "\n";
    }

    return 0;
}

