using asio::ip::tcp;

// Connection handler class that manages a single client session
class connection_handler : public std::enable_shared_from_this<connection_handler>
{
public:
  explicit connection_handler(tcp::socket socket)
    : client_socket_(std::move(socket)),
      timeout_timer_(client_socket_.get_io_context()),
      work_strand_(client_socket_.get_io_context())
  {
  }

  void start()
  {
    auto self(shared_from_this());

    // Coroutine for handling data transfer with timeout
    asio::spawn(work_strand_,
        [this, self](asio::yield_context yield)
        {
          try
          {
            char buffer[128];
            for (;;)
            {
              timeout_timer_.expires_from_now(std::chrono::seconds(10));
              std::size_t bytes_read = client_socket_.async_read_some(asio::buffer(buffer), yield);
              asio::async_write(client_socket_, asio::buffer(buffer, bytes_read), yield);
            }
          }
          catch (std::exception& err)
          {
            client_socket_.close();
            timeout_timer_.cancel();
          }
        });

    // Coroutine for managing the timeout mechanism
    asio::spawn(work_strand_,
        [this, self](asio::yield_context yield)
        {
          while (client_socket_.is_open())
          {
            asio::error_code ec_ignore;
            timeout_timer_.async_wait(yield[ec_ignore]);
            if (timeout_timer_.expires_from_now() <= std::chrono::seconds(0))
              client_socket_.close();
          }
        });
  }

private:
  tcp::socket client_socket_;
  asio::steady_timer timeout_timer_;
  asio::io_context::strand work_strand_;
};

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 2)
    {
      std::cerr << "Usage: echo_server <port>\n";
      return 1;
    }

    asio::io_context service_context;

    asio::spawn(service_context,
        [&](asio::yield_context yield)
        {
          tcp::acceptor listener(service_context,
            tcp::endpoint(tcp::v4(), std::atoi(argv[1])));

          for (;;)
          {
            asio::error_code accept_error;
            tcp::socket new_connection(service_context);
            listener.async_accept(new_connection, yield[accept_error]);

            if (!accept_error)
            {
              std::make_shared<connection_handler>(std::move(new_connection))->start();
            }
          }
        });

    service_context.run();
  }
  catch (std::exception& ex)
  {
    std::cerr << "Error occurred: " << ex.what() << "\n";
  }

  return 0;
}

