#include <vector>
using namespace std;

// Bubble sort implementation to sort colors (0s, 1s, 2s)
class Solution {
public:
    void sortColors(vector<int>& colors) {
        int size = colors.size();
        int swapTemp;
        for(int i = 0; i < size; i++) {
            for(int j = 0; j < size - i - 1; j++) {
                if(colors[j] > colors[j+1]) {
                    swapTemp = colors[j];
                    colors[j] = colors[j+1];
                    colors[j+1] = swapTemp;
                }
            }
        }
    }
};

