std::atomic<bool> termination_flag(false);

void handleTerminationSignal(int sig) {
    spdlog::info("Received termination signal: {}", sig);
    termination_flag = true;
}

void startServer() {
    std::string listen_address("0.0.0.0:50052");
    QubitEngineServiceImpl engine_service;
    grpc::ServerBuilder builder;

    builder.AddListeningPort(listen_address, grpc::InsecureServerCredentials());
    builder.RegisterService(&engine_service);

    // Optional reflection plugin — commented out for production builds
    // grpc::reflection::InitProtoReflectionServerBuilderPlugin();

    auto server_ptr = builder.BuildAndStart();
    spdlog::set_pattern("[%Y-%m-%d %H:%M:%S.%f] [%^%l%$] [thr %t] %v");
    spdlog::set_level(spdlog::level::debug);

    spdlog::info("QubitEngine (C++) bound to {}", listen_address);
    spdlog::info("QubitEngine v2 (Debug) - VisualizeCircuit active");

    // Launch Prometheus metrics endpoint
    QuantumMetrics::Instance().Start();

    // Set up signal handlers
    std::signal(SIGINT, handleTerminationSignal);
    std::signal(SIGTERM, handleTerminationSignal);

    // Main wait loop
    while (!termination_flag) {
        std::this_thread::sleep_for(std::chrono::milliseconds(750));
    }

    spdlog::info("Initiating graceful shutdown of gRPC server...");
    server_ptr->Shutdown();
}

