int main(int argc, char **argv) {
#ifdef MPI_ENABLED
    MPI_Init(&argc, &argv);
    int my_rank;
    MPI_Comm_rank(MPI_COMM_WORLD, &my_rank);
    int total_ranks;
    MPI_Comm_size(MPI_COMM_WORLD, &total_ranks);

    if (my_rank == 0) {
        spdlog::info("MPI initialized; cluster size = {}", total_ranks);
        startServer();
    } else {
        // Non-root ranks operate as distributed workers
        // Decoupled from gRPC: poll Redis directly for job dispatch
        try {
            sw::redis::Redis redis_conn("tcp://localhost:6379");
            spdlog::info("Worker rank {} connected to Redis.", my_rank);
            while (!termination_flag) {
                // Non-blocking probe for incoming MPI messages
                int pending = 0;
                MPI_Status req_status;
                MPI_Iprobe(MPI_ANY_SOURCE, MPI_ANY_TAG, MPI_COMM_WORLD, &pending, &req_status);
                if (pending) {
                    // Handle incoming message here when needed
                }
                // Blocking pop from job queue with timeout
                auto task = redis_conn.bzpopmax("queue:jobs", 1);
                if (task) {
                    spdlog::info("Worker {} dequeued job ID: {}", my_rank, std::get<1>(*task));
                    // executeJob(std::get<1>(*task)); // Integrate execution logic
                }
            }
        } catch (const sw::redis::Error &ex) {
            spdlog::error("Redis exception: {}", ex.what());
        }
    }
    MPI_Finalize();
#else
    // Standalone mode: run single-node server
    startServer();
#endif
    return 0;
}

#include <fstream>
#include <iostream>

struct Record {
    int id;
    char fullName[64];
    double score;

    // Method to display the record details
    void display() const {
        std::cout << "ID: " << id
            << " | Full Name: " << fullName
            << " | Score: " << score << std::endl;
    }
};

// Writes a record to the specified file in append mode
void writeRecord(const char* filepath, const Record& r) {
    std::ofstream file(filepath, std::ios::app);
    if (!file) return;

    // Use tab as delimiter to safely handle names with spaces
    file << r.id << "\t" << r.fullName << "\t" << r.score << "\n";
    file.close();
}

// Reads and displays all records from the file
void readAndDisplayRecords(const char* filepath) {
    std::ifstream input(filepath);
    if (!input) {
        std::cerr << "Failed to open file for reading." << std::endl;
        return;
    }

    Record buffer;
    std::cout << "--- RECORDS ---" << std::endl;

    while (input >> buffer.id) {
        // Skip the tab character after the ID
        input.ignore();

        // Read the name up to the next tab
        input.getline(buffer.fullName, 64, '\t');

        // Read the numeric score
        input >> buffer.score;

        // Discard the rest of the line to prepare for next iteration
        input.ignore(1000, '\n');

        buffer.display();
    }

    input.close();
}

int main() {
    const char* database = "records.dat";

    Record entry1 = { 1001, "Alexei Petrov", 5.75 };
    Record entry2 = { 2002, "Elena Georgieva", 6.00 };

    // Persist records to disk
    writeRecord(database, entry1);
    writeRecord(database, entry2);

    // Retrieve and show stored records
    readAndDisplayRecords(database);

    return 0;
}

#include "server.hpp"
#include "request.hpp"
#include "reply.hpp"

namespace http {
namespace server4 {

// Constructor for the server class
server::server(asio::io_context& ctx,
    const std::string& host, const std::string& port_str,
    boost::function<void(const request&, reply&)> handler_func)
  : request_handler_(handler_func)
{
  tcp::resolver resolver(ctx);
  asio::ip::tcp::endpoint endpoint =
    *resolver.resolve(host, port_str).begin();
  acceptor_.reset(new tcp::acceptor(ctx, endpoint));
}

// Enable the pseudo-keywords reenter, yield and fork.
#include <asio/yield.hpp>

void server::operator()(asio::error_code ec, std::size_t bytes_transferred)
{
  // Centralized error handling: check once at the top
  if (!ec)
  {
    reenter (this)
    {
      // Main loop to accept incoming connections
      do
      {
        // Prepare a new socket for the next connection
        socket_.reset(new tcp::socket(acceptor_->get_executor().context()));

        // Asynchronously wait for a new connection; coroutine yields control here
        yield acceptor_->async_accept(*socket_, *this);

        // Fork a new coroutine instance to handle this specific connection
        fork server(*this)();

        // Parent continues accepting; child proceeds to process the connection
      } while (is_parent());

      // Initialize buffers and request object for reading client data
      buffer_.reset(new boost::array<char, 16384>);  // Increased buffer size
      request_.reset(new request);

      // Loop until full request is parsed or invalid input detected
      do
      {
        // Read data from socket asynchronously
        yield socket_->async_read_some(asio::buffer(*buffer_), *this);

        // Parse incoming data
        boost::tie(valid_request_, boost::tuples::ignore)
          = request_parser_.parse(*request_,
              buffer_->data(), buffer_->data() + bytes_transferred);

        // Continue reading if parsing is inconclusive
      } while (boost::indeterminate(valid_request_));

      // Prepare reply object
      reply_.reset(new reply);

      if (valid_request_)
      {
        // Process valid request using user-provided handler
        request_handler_(*request_, *reply_);
      }
      else
      {
        // Send standard bad request response for invalid input
        *reply_ = reply::stock_reply(reply::bad_request);
      }

      // Send reply back to client
      yield asio::async_write(*socket_, reply_->to_buffers(), *this);

      // Gracefully close the connection
      socket_->shutdown(tcp::socket::shutdown_both, ec);
    }
  }
  // On error: coroutine exits, all shared_ptr references drop, resources auto-destruct
}

