#if LINEAR_MEMORY_BOUNDS_CHECKS
uint8_t *MemoryHelper::extensionRequest(uint64_t const requiredMinMemSize, uint32_t const baseDataSz,
                                        uint8_t *const origLinMemBase) VB_NOEXCEPT {
  // Early exit if requested size exceeds 32-bit address space
  if ((requiredMinMemSize + baseDataSz) > UINT32_MAX) {
    return nullptr;
  }

  uint32_t const reqMinLinMemSize_32{static_cast<uint32_t>(requiredMinMemSize)};
  Runtime &runtime{*readFromPtr<Runtime *>(pSubI(origLinMemBase, Basedata::FromEnd::runtimePtrOffset))};
  ExtendableMemory &memManager{runtime.jobMemory_};

  uint32_t const wasmMemPages{readFromPtr<uint32_t>(pSubI(origLinMemBase, Basedata::FromEnd::linMemWasmSize))};
  uint32_t const currentAllocSize{readFromPtr<uint32_t>(pSubI(origLinMemBase, Basedata::FromEnd::actualLinMemByteSize))};

  uint32_t const minTotalReqSize{baseDataSz + reqMinLinMemSize_32};
  // Align up to next even number
  uint32_t const alignedMinTotalSize{(minTotalReqSize + 1U) & ~1_U32};

  if (reqMinLinMemSize_32 <= currentAllocSize) {
    // Already sufficient memory allocated
    return memManager.data();
  } else if (reqMinLinMemSize_32 > (wasmMemPages * WasmConstants::wasmPageSize)) {
    // Requested size exceeds Wasm-defined limit → trap signal
    return numToP<uint8_t *>(~static_cast<uintptr_t>(0));
  } else if (memManager.size() >= alignedMinTotalSize) {
    // Existing allocation suffices; zero-initialize new region and update metadata
    size_t const bytesToZero = static_cast<size_t>(reqMinLinMemSize_32) - static_cast<size_t>(currentAllocSize);
    static_cast<void>(std::memset(pAddI(origLinMemBase, currentAllocSize), 0x00, bytesToZero));

    writeToPtr<uint32_t>(pSubI(origLinMemBase, Basedata::FromEnd::actualLinMemByteSize), reqMinLinMemSize_32);
    return memManager.data(); // No reallocation needed
  } else {
    // Need to grow memory via extension request
    if (!memManager.hasExtensionRequest()) {
      return nullptr; // Cannot extend without callback
    }

    memManager.extensionRequest(alignedMinTotalSize);

    if ((memManager.data() != nullptr) && (memManager.size() >= alignedMinTotalSize)) {
      uint8_t *const newBase{pAddI(memManager.data(), baseDataSz)};
      size_t const bytesToZeroNew = static_cast<size_t>(reqMinLinMemSize_32) - static_cast<size_t>(currentAllocSize);
      static_cast<void>(std::memset(pAddI(newBase, currentAllocSize), 0x00, bytesToZeroNew));

      writeToPtr<uint32_t>(pSubI(newBase, Basedata::FromEnd::actualLinMemByteSize), reqMinLinMemSize_32);
      return memManager.data();
    } else {
      // Extension failed or insufficient capacity
      return nullptr;
    }
  }
}
#else
bool MemoryHelper::notifyOfMemoryGrowth(uint8_t *const linMemBase, uint32_t const newMemSizeInPages) VB_NOEXCEPT {
  Runtime const &runtime{*readFromPtr<Runtime *>(pSubI(linMemBase, Basedata::FromEnd::runtimePtrOffset))};
  return runtime.extendMemory(newMemSizeInPages);
}
#endif

