// Evaluate bitvector literal expressions 
void evaluate_bitvector_literals(SMTParser::ParserPtr& parser) {
    std::vector<std::string> test_cases = {
        "#b1010",                     // 4-bit binary representation
        "#x1A",                       // hexadecimal notation (26 in decimal)
        "(_ bv42 8)",                 // represent 42 as an 8-bit bitvector
        "(_ bv255 8)"                 // represent 255 as an 8-bit bitvector
    };

    std::cout << "=== Evaluating Bitvector Literals ===" << std::endl;
    for (const auto& input : test_cases) {
        std::cout << "Input: " << input << std::endl;
        std::shared_ptr<SMTParser::DAGNode> output = parser->mkExpr(input);
        assert(output && !output->isErr());
        std::cout << "  Output: " << parser->toString(output) << std::endl;
        std::cout << std::endl;
    }
}

// Test logical operations on bitvectors
void evaluate_bv_logical_ops(SMTParser::ParserPtr& parser) {
    std::vector<std::string> test_cases = {
        "(bvnot #b1010)",
        "(bvand #b1010 #b1100)",
        "(bvor #b1010 #b1100)",
        "(bvxor #b1010 #b1100)",
        "(bvnand #b1010 #b1100)",
        "(bvnor #b1010 #b1100)",
        "(bvxnor #b1010 #b1100)"
    };

    std::cout << "=== Testing Bitvector Logical Operations ===" << std::endl;
    for (const auto& input : test_cases) {
        std::cout << "Input: " << input << std::endl;
        std::shared_ptr<SMTParser::DAGNode> output = parser->mkExpr(input);
        assert(output && !output->isErr());
        std::cout << "  Output: " << parser->toString(output) << std::endl;
        std::cout << std::endl;
    }
}

// Test arithmetic operations on bitvectors
void evaluate_bv_arithmetic_ops(SMTParser::ParserPtr& parser) {
    std::vector<std::string> test_cases = {
        "(bvneg #b0101)",
        "(bvadd #b0101 #b0011)",
        "(bvsub #b1010 #b0011)",
        "(bvmul #b0101 #b0011)",
        "(bvudiv #b1010 #b0011)",
        "(bvurem #b1010 #b0011)",
        "(bvshl #b0101 #b0011)",
        "(bvlshr #b1010 #b0001)",
        "(bvashr #b1010 #b0001)"
    };

    std::cout << "=== Testing Bitvector Arithmetic Operations ===" << std::endl;
    for (const auto& input : test_cases) {
        std::cout << "Input: " << input << std::endl;
        std::shared_ptr<SMTParser::DAGNode> output = parser->mkExpr(input);
        assert(output && !output->isErr());
        std::cout << "  Output: " << parser->toString(output) << std::endl;
        std::cout << std::endl;
    }
}

// Test comparison operations on bitvectors
void evaluate_bv_comparison_ops(SMTParser::ParserPtr& parser) {
    std::vector<std::string> test_cases = {
        "(bvult #b0101 #b1010)",     // unsigned less than
        "(bvule #b0101 #b0101)",     // unsigned less than or equal
        "(bvugt #b1010 #b0101)",     // unsigned greater than
        "(bvuge #b0101 #b0101)",     // unsigned greater than or equal
        "(bvslt #b0101 #b1010)",     // signed less than
        "(bvsle #b0101 #b0101)",     // signed less than or equal
        "(bvsgt #b0000 #b1111)",     // signed greater than
        "(bvsge #b0101 #b0101)"      // signed greater than or equal
    };

    std::cout << "=== Testing Bitvector Comparison Operations ===" << std::endl;
    for (const auto& input : test_cases) {
        std::cout << "Input: " << input << std::endl;
        std::shared_ptr<SMTParser::DAGNode> output = parser->mkExpr(input);
        assert(output && (output->isTrue() || output->isFalse()));
        std::cout << "  Output: " << parser->toString(output) << std::endl;
        std::cout << std::endl;
    }
}

int main() {
    std::cout << "======= Bitvector Operations Validation =======" << std::endl;

    SMTParser::ParserPtr parser = SMTParser::newParser();

    evaluate_bitvector_literals(parser);
    evaluate_bv_logical_ops(parser);
    evaluate_bv_arithmetic_ops(parser);
    evaluate_bv_comparison_ops(parser);

    return 0;
}

