namespace duckdb {

StdioServerTransport::StdioServerTransport() : is_connected(false) {
}

StdioServerTransport::~StdioServerTransport() {
    Close();
}

bool StdioServerTransport::Open() {
    std::lock_guard<std::mutex> guard(io_mutex);
    if (is_connected) {
        return true;
    }
    is_connected = true;
    return true;
}

void StdioServerTransport::Close() {
    std::lock_guard<std::mutex> guard(io_mutex);
    is_connected = false;
}

bool StdioServerTransport::IsOpen() const {
    return is_connected;
}

void StdioServerTransport::Transmit(const MCPMessage &msg) {
    if (!IsOpen()) {
        MCP_LOG_ERROR("stdio", "Transmit invoked while not connected");
        throw IOException("Connection not established");
    }
    std::lock_guard<std::mutex> guard(io_mutex);
    try {
        std::string json_payload = msg.ToJSON();
        MCP_LOG_DEBUG("stdio", "Outgoing message: %s", json_payload.substr(0, 100).c_str());
        // Output directly to stdout and force immediate flush
        std::cout << json_payload << std::endl;
        std::cout.flush();
        MCP_LOG_DEBUG("stdio", "Message transmitted and flushed successfully");
    } catch (const std::exception &err) {
        MCP_LOG_ERROR("stdio", "Transmission failed: %s", err.what());
        throw IOException("Message transmission error: " + std::string(err.what()));
    }
}

MCPMessage StdioServerTransport::Listen() {
    if (!IsOpen()) {
        MCP_LOG_ERROR("stdio", "Listen invoked while not connected");
        throw IOException("Connection not established");
    }
    std::lock_guard<std::mutex> guard(io_mutex);
    try {
        MCP_LOG_DEBUG("stdio", "Awaiting input from stdin...");
        std::string input_line;
        if (!std::getline(std::cin, input_line)) {
            MCP_LOG_DEBUG("stdio", "End-of-file or read error on stdin");
            throw IOException("Input stream terminated");
        }
        MCP_LOG_DEBUG("stdio", "Received line (%zu bytes): %s", input_line.size(), input_line.substr(0, 100).c_str());
        if (input_line.empty()) {
            MCP_LOG_WARN("stdio", "Empty line received");
            throw IOException("Empty message received");
        }
        return MCPMessage::FromJSON(input_line);
    } catch (const IOException &) {
        throw;
    } catch (const std::exception &err) {
        MCP_LOG_ERROR("stdio", "Failed to parse incoming message: %s", err.what());
        throw IOException("Message parsing failure: " + std::string(err.what()));
    }
}

MCPMessage StdioServerTransport::Exchange(const MCPMessage &msg) {
    // In server mode, bidirectional exchange is not applicable
    throw NotImplementedException("Exchange operation is unsupported in server mode");
}

bool StdioServerTransport::CheckHealth() {
    return IsOpen();
}

std::string StdioServerTransport::DescribeConnection() const {
    return "stdio server transport (stdin/stdout)";
}

} // namespace duckdb

