#include "WifiTypeConfigurator.h"

std::string WifiTypeConfigurator::configure(TerminalTypeEnum& terminalMode) {
    switch (terminalMode)
    {
    case TerminalTypeEnum::WiFiClient:
        #if defined(DEVICE_CARDPUTER)
            // Initialize cardputer WiFi configuration
            setupCardputerWifi(); // blocks execution until a valid network is found and connected
        #elif defined(DEVICE_STICKS3)
            // Initialize StickS3 WiFi configuration
            setupStickWifi(); // verifies credentials previously stored in flash
        #elif defined(DEVICE_TEMBEDS3) || defined(DEVICE_TEMBEDS3CC1101)
            // Initialize T-Embed S3 WiFi configuration
            setupTembedWifi(view); // halts program flow until successful connection to a known network
        #elif defined(DEVICE_TDISPLAYS3)
            // Initialize T-Display S3 WiFi configuration
            setupTdisplayWifi(view); // waits indefinitely for user-selected network connection
        #else
            // Default ESP32 WiFi configuration
            setupS3Wifi(); // validates saved authentication data
        #endif
        return std::string(WiFi.localIP().toString().c_str());
    case TerminalTypeEnum::WiFiAp: {
        return "";
    }
    default:
        break;
    }
    return "";
}

