#include "llvm/Support/circular_raw_ostream.h"
#include <algorithm>
using namespace llvm;

void circular_raw_ostream::write_impl(const char *data, size_t length) {
  if (Capacity == 0) {
    Output->write(data, length);
    return;
  }

  // Fill the circular buffer, wrapping around when needed
  while (length > 0) {
    size_t chunk =
      std::min(length, size_t(Capacity - (Position - Storage)));
    memcpy(Position, data, chunk);
    length -= chunk;
    Position += chunk;

    if (Position == Storage + Capacity) {
      // Wrap around to beginning of buffer
      Position = Storage;
      MarkedFull = true;
    }
  }
}

void circular_raw_ostream::flushBufferWithBanner() {
  if (Capacity != 0) {
    // Output the banner followed by buffered content
    Output->write(Header, std::strlen(Header));
    flushBuffer();
  }
}

#include <vector>
#include <algorithm>
using namespace std;

// Find the maximum absolute sum of any subarray
class Solution {
public:
    int maxAbsoluteSum(vector<int>& arr) {
        int len = arr.size();
        int minVal = arr[0];
        int maxVal = 0;
        int currPos = 0;
        int currNeg = 0;

        // Calculate maximum subarray sum using Kadane's algorithm
        for(int idx = 0; idx < len; idx++) {
            currPos = currPos + arr[idx];
            maxVal = max(currPos, maxVal);
            if(currPos < 0) {
                currPos = 0;
            }
        }

        // Calculate minimum subarray sum
        for(int idx = 0; idx < len; idx++) {
            currNeg = currNeg + arr[idx];
            minVal = min(currNeg, minVal);
            if(currNeg > 0) {
                currNeg = 0;
            }
        }

        // Return the maximum of maximum sum and absolute value of minimum sum
        int result = max(maxVal, abs(minVal));
        return result; 
    }
};

