namespace arch {
    [[gnu::weak]] void disable_interrupts() {
        asm volatile("cli");
    }

    [[gnu::weak]] void enable_interrupts() {
        asm volatile("sti");
    }

    [[gnu::weak]] void wait_for_interrupt() {
        asm volatile("hlt");
    }

    [[gnu::weak]] void hcf() {
        disable_interrupts();
        while (true) {
            wait_for_interrupt();
        }
    }

    [[gnu::weak]] void pause() {
        asm volatile("pause");
    }

    [[gnu::weak]] void tlb_flush(std::uintptr_t addr, std::uintptr_t size) {
        if (size / PAGE_SIZE > 256 || size == 0) {
            std::uint64_t cr3_reg = 0;
            asm volatile("mov %%cr3, %0" : "=r"(cr3_reg) : : "memory");
            asm volatile("mov %0, %%cr3" : : "r"(cr3_reg) : "memory");
        } else {
            for (std::uintptr_t offset = 0; offset < size; offset += PAGE_SIZE) {
                asm volatile("invlpg (%0)" : : "b"(addr + offset) : "memory");
            }
        }
    }

    [[gnu::weak]] const char* name() {
        return "x86_64";
    }

    [[gnu::weak]] int level_paging() {
        return bootloader::bootloader->is_5_level_paging() ? 5 : 4;
    }

    [[gnu::weak]] void init(int stage) {
        switch(stage) {
        case ARCH_INIT_EARLY:
            x86_64::init_cpu_data();
            drivers::hpet::init();
            drivers::tsc::init();
            x86_64::gdt::init();
            x86_64::idt::init();
            x86_64::lapic::init(1500);
            drivers::ioapic::init();
            return;
        case ARCH_INIT_COMMON:
            return;
        }
    }

    [[gnu::weak]] void panic(char* message) {
        x86_64::panic::print_ascii_art();
        klibc::printf("Panic with message \"%s\"\r\n", message);
    }

    [[gnu::weak]] int register_handler(int irq_num, int handler_type, std::uint64_t flags, void (*handler)(void* data), void* data) {
        return x86_64::irq::create(irq_num, handler_type, handler, data, flags);
    }
}

