// Constructs an InputStreamReader that utilizes the default character encoding.
// Parameters:
// input - An InputStream object
InputStreamReader::InputStreamReader(InputStream *input) : stream( new DataInputStream( input ) )
{
}

// Releases the stream and deallocates any system resources tied to it.
// After closing, calls to read(), ready(), mark(), reset(), or skip() will throw an IOException.
// Closing an already closed stream has no additional effect.
void InputStreamReader::close()
{
	stream->close();
}

// Reads one character from the stream.
// Returns:
// The character read as an integer, or -1 if the end of the stream is reached
int InputStreamReader::read()
{
	return stream->readUTFChar();
}

// Reads characters into a specified region of an array.
// Parameters:
// buffer - Target array for storing characters
// startIndex - Starting index in the array where characters are stored
// maxChars - Upper limit on how many characters to read
// Returns:
// Number of characters successfully read, or -1 if end-of-stream is encountered
int InputStreamReader::read(wchar_t buffer[], unsigned int startIndex, unsigned int maxChars)
{
	unsigned int numRead = 0;
	for( unsigned int idx = startIndex; idx < startIndex + maxChars; idx++ )
	{
		wchar_t tempChar = (wchar_t)stream->readUTFChar();
		if( tempChar != -1 )
		{
			buffer[idx] = tempChar;
			numRead++;
		}
		// TODO 4J Stu - Exception handling may be needed here? If so, return -1
		else break;
	}
	return numRead;
}

