#include <ocs2_switched_model_interface/constraint/EndEffectorVelocityConstraint.h>

int main(int argc, char** args) {
  using EEVelConstraint = switched_model::EndEffectorVelocityConstraint<3, 2>;

  // Configure the constraint parameters
  switched_model::EndEffectorVelocityConstraintSettings params;
  EEVelConstraint eeVelConstr(params);

  // Prepare evaluation point (t, x, u, p)
  EEVelConstraint::scalar_t t;
  EEVelConstraint::state_vector_t x;
  EEVelConstraint::input_vector_t u;
  t = 0.0;
  x.setZero();
  u.setConstant(2.0);
  params.desiredEndEffectorVelocity.setConstant(-0.5);

  // Compute constraint value and derivatives
  auto values = eeVelConstr.getValue(t, x, u);
  auto approx = eeVelConstr.getLinearApproximation(t, x, u);

  std::cout << "Constraint residuals" << std::endl;
  for (const auto& val : values) {
    std::cout << val << std::endl;
  }

  std::cout << "Jacobian w.r.t. state" << std::endl;
  for (const auto& jacState : approx.derivativeState) {
    std::cout << jacState.transpose() << std::endl;
  }

  std::cout << "Jacobian w.r.t. input" << std::endl;
  for (const auto& jacInput : approx.derivativeInput) {
    std::cout << jacInput.transpose() << std::endl;
  }

  return 0;
}

#include <vector>
#include <stack>

class Solution {
public:
    std::vector<int> dailyTemperatures(std::vector<int>& temperatures) {
        std::stack<int> indices;
        int size = temperatures.size();
        std::vector<int> result(size, 0);

        // Start from the last day
        indices.push(size - 1);

        for (int day = size - 2; day >= 0; --day) {
            // Pop indices of days with temperature <= current day's temperature
            while (!indices.empty() && temperatures[indices.top()] <= temperatures[day]) {
                indices.pop();
            }

            // If no warmer day found in the future
            if (indices.empty()) {
                result[day] = 0;
            } else {
                // Days until warmer temperature
                result[day] = indices.top() - day;
            }

            // Push current day index onto stack
            indices.push(day);
        }

        return result;
    }
};

