#include <iostream>
#include <vector>
#include <cmath>
#include <numeric>
#include <random>
#include <chrono>

// Modulus used in the cryptographic computation
long long modulus_value;

// Performs modular multiplication using __int128 to avoid overflow
long long mod_multiply(long long x, long long y, long long mod) {
    return static_cast<long long>((static_cast<__int128>(x) * y) % mod);
}

// Calculates the number of bits required to represent a non-negative integer
// Returns 0 for input 0, otherwise floor(log2(x)) + 1
int bit_count(long long value) {
    if (value == 0) return 0;
    return 64 - __builtin_clzll(value);
}

// Queries the device with a given value and retrieves the response time
long long query_device(long long input_value) {
    std::cout << "? " << input_value << std::endl;
    long long response_time;
    std::cin >> response_time;
    return response_time;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    // Read the public modulus from input
    std::cin >> modulus_value;

    // Variable to store the secret exponent being recovered
    long long secret_exponent = 0;

    // Initialize random number generator with current time as seed
    std::mt19937_64 prng(std::chrono::steady_clock::now().time_since_epoch().count());

    // Recover each bit of the secret exponent from LSB to MSB (0 to 59)
    for (int position = 0; position < 60; ++position) {
        long double evidence_score = 0.0;

        // Number of samples to collect per bit decision
        int sample_count = 40;

        for (int sample_index = 0; sample_index < sample_count; ++sample_index) {
            // Generate random base value in valid range [2, modulus-1]
            long long base_value = std::uniform_int_distribution<long long>(2, modulus_value - 1)(prng);

            // Query device with base value to get total execution time
            long long observed_time = query_device(base_value);

            // Precompute powers: base^(2^i) mod modulus for i=0..59
            std::vector<long long> power_sequence(60);
            std::vector<int> power_bit_counts(60);

            power_sequence[0] = base_value;
            for (int exp_index = 1; exp_index < 60; ++exp_index) {
                power_sequence[exp_index] = mod_multiply(power_sequence[exp_index - 1], power_sequence[exp_index - 1], modulus_value);
            }

            // Compute bit counts for each precomputed power
            for (int idx = 0; idx < 60; ++idx) {
                power_bit_counts[idx] = bit_count(power_sequence[idx]) + 1;
            }

            // Calculate constant part C(base) independent of secret exponent
            long long constant_cost = 0;
            for (int idx = 0; idx < 60; ++idx) {
                constant_cost += static_cast<long long>(power_bit_counts[idx]) * power_bit_counts[idx];
            }

            // Process already-determined lower bits of secret exponent
            long long known_bits = secret_exponent;
            long long running_product = 1;
            long long known_cost = 0;

            for (int idx = 0; idx < position; ++idx) {
                if ((known_bits >> idx) & 1) {
                    known_cost += static_cast<long long>(bit_count(running_product) + 1) * power_bit_counts[idx];
                    running_product = mod_multiply(running_product, power_sequence[idx], modulus_value);
                }
            }

            long long remainder_time = observed_time - constant_cost - known_cost;

            // Cost contribution if current bit is 1
            long long current_bit_cost = static_cast<long long>(bit_count(running_product) + 1) * power_bit_counts[position];

            // Statistical test: compare remainder time against half the cost
            evidence_score += remainder_time - static_cast<long double>(current_bit_cost) / 2.0;
        }

        // Update secret exponent based on accumulated evidence
        if (evidence_score > 0) {
            secret_exponent |= (1LL << position);
        }
    }

    // Output the recovered secret exponent
    std::cout << "! " << secret_exponent << std::endl;
    return 0;
}

#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    // Speed up input/output operations
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int participants, rounds;
    // Read number of participants and number of wager rounds
    if (cin >> participants >> rounds) {
        // Initialize expert weights to 1.0 each
        vector<double> weights(participants, 1.0);

        // Decay factor for incorrect predictions
        double decay = 0.8; 
        for (int round = 0; round < rounds; ++round) {
            string predictions;
            cin >> predictions;

            // Compute weighted votes for each option
            double vote0 = 0.0;
            double vote1 = 0.0;
            for (int idx = 0; idx < participants; ++idx) {
                if (predictions[idx] == '0') {
                    vote0 += weights[idx];
                } else {
                    vote1 += weights[idx];
                }
            }

            // Decide prediction based on majority weighted vote
            char prediction = (vote1 > vote0) ? '1' : '0';
            cout << prediction << '\n'; // Output prediction

            // Get actual result
            char result;
            cin >> result;

            // Apply penalty to incorrectly predicted experts
            double highestWeight = 0.0;
            for (int idx = 0; idx < participants; ++idx) {
                if (predictions[idx] != result) {
                    weights[idx] *= decay;
                }
                if (weights[idx] > highestWeight) {
                    highestWeight = weights[idx];
                }
            }

            // Prevent underflow by rescaling if needed
            if (highestWeight < 1e-150) {
                for (int idx = 0; idx < participants; ++idx) {
                    weights[idx] *= 1e150;
                }
            }
        }
    }
    return 0;
}

