    Astroid::Astroid() {
        // Initialize position above the visible screen area (Y = -100).
        // X coordinate is randomized to allow spawning slightly off-screen.
        position = Pointf(RandomFloat(-200, 1920 + 200), -100);
        // Assign random horizontal drift and vertical fall speed.
