        velocity = Pointf(RandomFloat(-150, 150), RandomFloat(500, 1200));
        // Select a random visual variant (sprite type) for this asteroid.
        // The renderer uses this value (modulo total types) to choose the image.
        astroidType = rand();
        // Set up an independent animation for this asteroid.
        anim.SetAnimation(
            Assets::Astroid::Get(astroidType % Assets::Astroid::GetTypeCount()).GetImage() // source image
                .CreateAnimation() // instantiate animation from the image
        );
    }
    void Astroid::DoFrame(unsigned delta) {
        // Update position using standard time-based motion formula.
        position += velocity * delta / 1000.0;
        // Ensure asteroids aren't immediately marked as off-screen upon creation.
        // preCheckTime delays the first off-screen check to avoid premature removal.
        if (preCheckTime > delta) {
            preCheckTime -= delta;
        } else {
            preCheckTime = 0;
        }
    }
}

