#include <vector>
#include <iostream>

class Solution {
public:
    long long cumulativeSum[18] = {1};

    // Compute the exponential sum for a given value x
    long long computeExpSum(unsigned x) {
        if (x == 0) return 0;
        int exponent = (30 - __builtin_clz(x | 1)) / 2;
        unsigned remainder = x - (1U << (2 * exponent));
        return cumulativeSum[exponent] + remainder * (static_cast<long long>(exponent) + 1LL);
    }

    long long minOperations(std::vector<std::vector<int>>& queries) {
        // Precompute the cumulative sums
        for (int idx = 1; idx < 18; idx++) {
            cumulativeSum[idx] = 1LL + cumulativeSum[idx - 1] + 3LL * static_cast<long long>(idx) * (1LL << (2 * (idx - 1)));
        }

        long long totalOperations = 0;
        for (auto& query : queries) {
            int leftBound = query[0] - 1;
            int rightBound = query[1];
            totalOperations += (computeExpSum(rightBound) - computeExpSum(leftBound) + 1LL) / 2LL;
        }

        return totalOperations;
    }
};

