// Constructs a Value instance with the given type and unindexed flag
Value::Value(ValueType type, bool enable_unindexed)
  : _value_type(type), _value(enable_unindexed) {
  // Store the unindexed status in the boolean part of _value
  if (enable_unindexed &&
      (_value_type != ValueType::Array && _value_type != ValueType::Object)) {
    throw Exception(Exception::kInvalidValueType, "Compound type required");
  }
}

bool Value::isUnindexed() const {
  if (_value_type != ValueType::Array && _value_type != ValueType::Object) {
    throw Exception(Exception::kInvalidValueType, "Compound type required");
  }
  return _value;
}

