struct data_container {
    int value = 45;
    double compute_value() {
        return 36.7;
    }
};

int main(int, char*[]) {
    std::cout << "=== functions (all) ===" << std::endl;
    sol::state vm;
    vm.open_libraries(sol::lib::base);

    // put an instance of "data_container" into vm
    // (we'll go into more detail about this later
    // just know here that it works and is
    // put into vm as a userdata
    vm.set("dc", data_container());

    // binds a plain function
    vm["a1"] = display_message;
    vm.set_function("a2", &alternate_action);

    // binds just the member function
    vm["m1"] = &data_container::compute_value;

    // binds the class to the type
    vm.set_function(
         "m2", &data_container::compute_value, data_container {});

    // binds just the member variable as a function
    vm["v1"] = &data_container::value;

    // binds class with member variable as function
    vm.set_function(
         "v2", &data_container::value, data_container {});

    vm.script(R"(
    a1() -- display message!
    a2() -- alternate action!

    -- need class instance if you don't bind it with the function
    print(m1(dc)) -- 36.7
    -- does not need class instance: was bound to vm with one 
    print(m2()) -- 36.7

    -- need class instance if you 
    -- don't bind it with the function
    print(v1(dc)) -- 45
    -- does not need class instance: 
    -- it was bound with one 
    print(v2()) -- 45
    -- can set, still 
    -- requires instance
    v1(dc, 189)
    -- can set, does not need 
    -- class instance: was bound with one 
    v2(203)
    print(v1(dc)) -- 189
    print(v2()) -- 203
    )");

    std::cout << std::endl;
    return 0;
}

