#include "../backend/src/QuantumRegister.hpp"
#include <benchmark/benchmark.h>
#include <iostream>

// Benchmark for Hadamard Gate application to evaluate memory bandwidth
static void BM_HadamardOperation(benchmark::State &state) {
  int qubit_count = state.range(0);

  // Initialize quantum register outside the timing loop to exclude allocation overhead
  // Note: 28 qubits require 2^28 * 16 bytes ≈ 4 GB of RAM
  try {
    QuantumRegister reg(qubit_count);

    for (auto _ : state) {
      // Perform the memory-bound operation
      reg.applyHadamard(0);

      // Prevent compiler optimizations and ensure memory operations are preserved
      benchmark::DoNotOptimize(reg.getStateVector().data());
      benchmark::ClobberMemory();
    }

    // Compute memory throughput metrics for reporting
    // Each Hadamard operation processes:
    // - Reads: one full state vector (2^N * 16 bytes)
    // - Writes: same state vector updated in-place with stride-based access
    // Total data moved ≈ 2 × size_of_state_vector
    // State vector size = 2^N × 16 bytes (complex<double> per amplitude)
    double total_bytes = static_cast<double>(1ULL << qubit_count) * 16.0 * 2.0;
    state.SetBytesProcessed(static_cast<int64_t>(state.iterations()) *
                            static_cast<int64_t>(total_bytes));

  } catch (const std::exception &ex) {
    state.SkipWithError("Insufficient memory or allocation failure");
  }
}

// Register benchmarks for different system sizes:
// 20 qubits → 16 MB, 25 qubits → 512 MB, 28 qubits → 4 GB
BENCHMARK(BM_HadamardOperation)
    ->Arg(20)
    ->Arg(25)
    ->Arg(28)
    ->Unit(benchmark::kMillisecond);

BENCHMARK_MAIN();

