#include <iostream>
using namespace std;

int main() {
    int currentDistance;
    cin >> currentDistance;
    int previousColor = -1;  // color of the edge we arrived from, -1 initially

    while (currentDistance > 0) {
        // try the two colors that are not the one we came from
        for (int color = 0; color < 3; ++color) {
            if (color == previousColor) continue;

            // move along color 'color'
            cout << "move " << color << endl;
            int resultAfterMove;
            cin >> resultAfterMove;

            if (resultAfterMove == 1) {
                // reached the exit
                return 0;
            }

            // query the new distance
            cout << "query" << endl;
            int updatedDistance;
            cin >> updatedDistance;

            if (updatedDistance < currentDistance) {
                // this move decreased the distance
                currentDistance = updatedDistance;
                previousColor = color;  // remember the edge we used
                break;                  // proceed to the next step
            } else {
                // this move increased the distance, move back
                cout << "move " << color << endl;
                cin >> resultAfterMove;

                if (resultAfterMove == 1) {
                    // reached the exit while moving back (unlikely but handled)
                    return 0;
                }
                // after moving back we are at the original node, distance unchanged
            }
        }
    }

    // If currentDistance becomes 0, we are already at the exit.
    return 0;
}

