    ROCPROFILER_REGISTER_COMPUTE_VERSION_2(ROCDECODE_RUNTIME_API_TABLE_MAJOR_VERSION,    \
                                           ROCDECODE_RUNTIME_API_TABLE_STEP_VERSION)

