#include <vector>
#include <string>
#include <unordered_map>

class Solution {
public:
    std::vector<std::string> removeAnagrams(std::vector<std::string>& inputWords) {
        std::vector<std::unordered_map<char, int>> charCounts(inputWords.size());

        // Build frequency maps for each word
        for (int index = 0; index < inputWords.size(); index++) {
            for (char character : inputWords[index]) {
                charCounts[index][character]++;
            }
        }

        std::vector<std::string> result;
        result.push_back(inputWords[0]);

        // Compare adjacent frequency maps to filter out anagrams
        for (int position = 1; position < inputWords.size(); position++) {
            if (charCounts[position] != charCounts[position - 1]) {
                result.push_back(inputWords[position]);
            }
        }

        return result;
    }
};

