class Solution {
public:
    // Increment the number represented by digits array by one
    vector<int> plusOne(vector<int>& numDigits) {
        int size = numDigits.size();
        int carryOver = 1;
        vector<int> result(size, 0);

        for (int index = size - 1; index >= 0; --index) {
            int currentSum = numDigits[index];
            currentSum = currentSum + carryOver;
            carryOver = currentSum / 10;

            currentSum = currentSum % 10;
            result[index] = currentSum;

            if (carryOver == 1 && index == 0) {
                result.insert(result.begin(), carryOver);
            }
        }
        return result;
    }
};

