Y_UNIT_TEST_SUITE(TCompactStrSpnTestSuite) {
    Y_UNIT_TEST(TestFindFirstOfFunctionality) {
        const TString testString("some text!");
        UNIT_ASSERT_EQUAL(TCompactStrSpn("mos").FindFirstOf(testString.begin(), testString.end()), testString.begin());
        UNIT_ASSERT_EQUAL(TCompactStrSpn("mos").FindFirstOf(testString.c_str()), testString.begin());
        UNIT_ASSERT_EQUAL(TCompactStrSpn("xt").FindFirstOf(testString.begin(), testString.end()), testString.begin() + 5);
        UNIT_ASSERT_EQUAL(TCompactStrSpn("xt").FindFirstOf(testString.c_str()), testString.begin() + 5);
        UNIT_ASSERT_EQUAL(TCompactStrSpn(".?!").FindFirstOf(testString.begin(), testString.end()), testString.end() - 1);
        UNIT_ASSERT_EQUAL(TCompactStrSpn(".?!").FindFirstOf(testString.c_str()), testString.end() - 1);
        UNIT_ASSERT_EQUAL(TCompactStrSpn("abc").FindFirstOf(testString.begin(), testString.end()), testString.end());
        UNIT_ASSERT_EQUAL(TCompactStrSpn("abc").FindFirstOf(testString.c_str()), testString.end());

        // Must be const. If not, non-const begin() will clone the shared empty string
        // and the next assertion will possibly use invalidated end iterator.
        const TString emptyString;
        UNIT_ASSERT_EQUAL(TCompactStrSpn("abc").FindFirstOf(emptyString.begin(), emptyString.end()), emptyString.end());
        UNIT_ASSERT_EQUAL(TCompactStrSpn("abc").FindFirstOf(emptyString.c_str()), emptyString.end());
    }

    Y_UNIT_TEST(TestFindFirstNotOfFunctionality) {
        const TString testString("abacabaxyz");
        UNIT_ASSERT_EQUAL(TCompactStrSpn("123").FindFirstNotOf(testString.begin(), testString.end()), testString.begin());
        UNIT_ASSERT_EQUAL(TCompactStrSpn("123").FindFirstNotOf(testString.c_str()), testString.begin());
        UNIT_ASSERT_EQUAL(TCompactStrSpn("abc").FindFirstNotOf(testString.begin(), testString.end()), testString.begin() + 7);
        UNIT_ASSERT_EQUAL(TCompactStrSpn("abc").FindFirstNotOf(testString.c_str()), testString.begin() + 7);
        UNIT_ASSERT_EQUAL(TCompactStrSpn("abcxy").FindFirstNotOf(testString.begin(), testString.end()), testString.end() - 1);
        UNIT_ASSERT_EQUAL(TCompactStrSpn("abcxy").FindFirstNotOf(testString.c_str()), testString.end() - 1);
        UNIT_ASSERT_EQUAL(TCompactStrSpn("abcxyz").FindFirstNotOf(testString.begin(), testString.end()), testString.end());
        UNIT_ASSERT_EQUAL(TCompactStrSpn("abcxyz").FindFirstNotOf(testString.c_str()), testString.end());

        const TString emptyString;
        UNIT_ASSERT_EQUAL(TCompactStrSpn("abc").FindFirstNotOf(emptyString.begin(), emptyString.end()), emptyString.end());
        UNIT_ASSERT_EQUAL(TCompactStrSpn("abc").FindFirstNotOf(emptyString.c_str()), emptyString.end());
    }

    Y_UNIT_TEST(TestReverseFindFirstOfFunctionality) {
        TStringBuf testString("some text");
        UNIT_ASSERT_EQUAL(TCompactStrSpn("xt").FindFirstOf(testString.rbegin(), testString.rend()), testString.rbegin());
        UNIT_ASSERT_EQUAL(TCompactStrSpn("mos").FindFirstOf(testString.rbegin(), testString.rend()), testString.rend() - 3);
        UNIT_ASSERT_EQUAL(TCompactStrSpn("s").FindFirstOf(testString.rbegin(), testString.rend()), testString.rend() - 1);
        UNIT_ASSERT_EQUAL(TCompactStrSpn("abc").FindFirstOf(testString.rbegin(), testString.rend()), testString.rend());

        TStringBuf emptyBuffer;
        UNIT_ASSERT_EQUAL(TCompactStrSpn("abc").FindFirstOf(emptyBuffer.rbegin(), emptyBuffer.rend()), emptyBuffer.rend());
    }

    Y_UNIT_TEST(TestReverseFindFirstNotOfFunctionality) {
        TStringBuf testString("_abacabaxyz");
        UNIT_ASSERT_EQUAL(TCompactStrSpn("abc").FindFirstNotOf(testString.rbegin(), testString.rend()), testString.rbegin());
        UNIT_ASSERT_EQUAL(TCompactStrSpn("xyz").FindFirstNotOf(testString.rbegin(), testString.rend()), testString.rbegin() + 3);
        UNIT_ASSERT_EQUAL(TCompactStrSpn("abcxyz").FindFirstNotOf(testString.rbegin(), testString.rend()), testString.rend() - 1);
        UNIT_ASSERT_EQUAL(TCompactStrSpn("abcxyz_").FindFirstNotOf(testString.rbegin(), testString.rend()), testString.rend());

        TStringBuf emptyBuffer;
        UNIT_ASSERT_EQUAL(TCompactStrSpn("abc").FindFirstNotOf(emptyBuffer.rbegin(), emptyBuffer.rend()), emptyBuffer.rend());
    }
} // Y_UNIT_TEST_SUITE(TCompactStrSpnTestSuite)

