using namespace aeronet;

/// Example showing how to configure TLS session tickets for resumption.
///
/// Session tickets support TLS session resumption without requiring the server
/// to maintain session state, enabling faster reconnects (0-RTT).
///
/// Verify resumption using OpenSSL client:
///   # Initial connection (full handshake)
///   openssl s_client -connect localhost:9443 -sess_out ticket.pem
///
///   # Subsequent connection (resumed - check for "Reused, TLSv1.3")
///   openssl s_client -connect localhost:9443 -sess_in ticket.pem
int main(int argc, char** argv) {
  if (argc < 3 || argc > 5) {
    std::cerr << "Usage: " << argv[0] << " <certificate.pem> <private.key> [port] [--fixed-key]\n\n";
    std::cerr << "Arguments:\n";
    std::cerr << "  --fixed-key   Use a fixed session ticket encryption key instead of rotating automatically\n";
    return EXIT_FAILURE;
  }

  std::string certFile = argv[1];
  std::string keyFile = argv[2];
  uint16_t listenPort = 9443;
  bool useFixedKey = false;

  for (int idx = 3; idx < argc; ++idx) {
    std::string token = argv[idx];
    if (token == "--fixed-key") {
      useFixedKey = true;
    } else {
      listenPort = static_cast<uint16_t>(std::stoi(token));
    }
  }

  SignalHandler::Enable();

  try {
    HttpServerConfig config;
    config.withPort(listenPort).withTlsCertKey(certFile, keyFile);

    if (useFixedKey) {
      // Fixed key mode: load a predetermined key for encrypting session tickets.
      // Useful in multi-server setups where servers must share the ability to decrypt tickets.
      //
      // In real deployments, retrieve this from a secure secrets system.
      // The key must be exactly 48 bytes: 16B name + 16B AES key + 16B HMAC key.
      TLSConfig::SessionTicketKey fixedKey;
      // For demonstration only — use cryptographically secure randomness in production
      for (auto& byte : fixedKey) {
        byte = static_cast<std::byte>(std::rand() % 256);  // NOLINT - demo only
      }
      config.tls.withTlsSessionTicketKey(std::move(fixedKey));  // Activate tickets and set key
      std::cout << "Session tickets active with fixed key (rotation turned off)\n";
    } else {
      // Auto-rotation mode (preferred for single-server environments).
      // Keys are generated automatically and rotated periodically.
      config.tls.withTlsSessionTickets(true)
          .withTlsSessionTicketLifetime(std::chrono::hours{3})
          .withTlsSessionTicketMaxKeys(5);
      std::cout << "Session tickets active with automatic key rotation\n";
      std::cout << "  Key validity period: 3 hours\n";
      std::cout << "  Maximum keys retained: 5\n";
    }

    Router handler;
    handler.setDefault([](const HttpRequest& request) {
      HttpResponse response(256U, http::StatusCodeOK);
      response.bodyAppend("Welcome from aeronet with TLS session ticket support!\n");
      response.bodyAppend("Request path: ");
      response.bodyAppend(request.path());
      response.bodyAppend("\nTLS version: ");
      response.bodyAppend(request.tlsVersion());
      response.bodyAppend("\nCipher suite: ");
      response.bodyAppend(request.tlsCipher());
      response.bodyAppend("\n");
      return response;
    });

    SingleHttpServer server(std::move(config), std::move(handler));

    std::cout << "Listening on port " << listenPort << "\n";
    std::cout << "\nSession resumption test commands:\n";
    std::cout << "  openssl s_client -connect localhost:" << listenPort << " -sess_out ticket.pem\n";
    std::cout << "  openssl s_client -connect localhost:" << listenPort << " -sess_in ticket.pem\n";
    std::cout << "  (Look for 'Reused, TLSv1.3' in output)\n\n";

    server.run();

    const auto metrics = server.stats();
    std::cout << "\nServer metrics:\n";
    std::cout << "  Requests handled: " << metrics.totalRequestsServed << '\n';
    std::cout << "  TLS handshakes completed: " << metrics.tlsHandshakesSucceeded << '\n';
  } catch (const std::exception& err) {
    std::cerr << "Exception occurred: " << err.what() << '\n';
    return EXIT_FAILURE;
  }
}

