#include <iostream>
#include <fstream>  // for file input/output operations
#include "program.hpp"

int main(void) {
    char input_file_name[MAX_FILE_NAME];

    // Prompt user to enter the file name
    std::cout << "Enter file name: ";
    std::cin.getline(input_file_name, MAX_FILE_NAME);

    std::ifstream input_stream(input_file_name);
    if (!input_stream.is_open()) {
        std::cout << "Invalid file name!\n";
        return -1;
    }

    // Open output file (creates or overwrites)
    std::ofstream output_stream("Result.txt");
    if (!output_stream.is_open()) {
        std::cout << "Could not create Result file!";
        input_stream.close();
        return -1;
    }

    // Process each program in the input file
    while (input_stream) {
        program_context current_program;
        int status = read_program(current_program, input_stream);

        if (status == 1) {  // parsing succeeded
            output_stream << current_program.program_name << '\n';
            for (int index = 0; index < ALPHABET_SIZE; ++index) {
                if (current_program.defined[index]) {
                    output_stream 
                        << static_cast<char>('a' + index)
                        << '='
                        << current_program.values[index] << '\n';
                }
            }
        } else if (status == 0) {  // parsing failed
            output_stream << current_program.program_name << ' ' << FAIL_MESSAGE << '\n';
        }

        clear_context(current_program);
    }

    input_stream.close();
    output_stream.close();
    return 0;
}

