namespace Detail {
  // Fixed ACPI Description Table (FADT) structure definition
  struct FADT final : public SDT {
    UInt32 FirmwareControl;
    UInt32 DSDTAddress;
    // field used in ACPI 1.0; no longer in use, maintained for compatibility only
    UInt8 SystemReserved;
    UInt8 PowerManagementProfile;
    UInt16 SCIInterruptNumber;
    UInt32 SMICmdPortAddress;
    UInt8 AcpiEnableCommand;
    UInt8 AcpiDisableCommand;
    UInt8 S4BIOSRequest;
    UInt8 PStateControlRegister;
    UInt32 PM1aEventStatusBlock;
    UInt32 PM1bEventStatusBlock;
    UInt32 PM1aControlBlockAddr;
    UInt32 PM1bControlBlockAddr;
    UInt32 PM2ControlBlockAddr;
    UInt32 PMTimerBlockAddr;
    UInt32 GPE0BlockAddress;
    UInt32 GPE1BlockAddress;
    UInt8 PM1EventLengthField;
    UInt8 PM1ControlLengthField;
    UInt8 PM2ControlLengthField;
    UInt8 PMTimerLengthField;
    UInt8 GPE0BlockLength;
    UInt8 GPE1BlockLength;
    UInt8 GPE1BaseRegister;
    UInt8 CStateControlReg;
    UInt16 MaxC2LatencyValue;
    UInt16 MaxC3LatencyValue;
    UInt16 CacheFlushSize;
    UInt16 CacheFlushStride;
    UInt8 DutyCycleOffset;
    UInt8 DutyCycleBitWidth;
    UInt8 DayAlarmClock;
    UInt8 MonthAlarmClock;
    UInt8 CenturyRegister;
    // reserved in ACPI 1.0; utilized starting from ACPI 2.0+
    UInt16 BootArchitectureFlags;
    UInt8 PlatformReserved;
    UInt32 FeatureFlags;
    // 12-byte register location structure; see ACPI specification for details
    ACPI_ADDRESS ResetControlRegister;
    UInt8 ResetCommandValue;
    UInt8 ReservedSpace[3];
    // 64-bit address fields - present in ACPI 2.0 and later versions
    UInt64 ExtendedFirmwareControl;
    UInt64 ExtendedDSDTAddress;
    ACPI_ADDRESS ExtendedPM1aEventBlock;
    ACPI_ADDRESS ExtendedPM1bEventBlock;
    ACPI_ADDRESS ExtendedPM1aControlBlock;
    ACPI_ADDRESS ExtendedPM1bControlBlock;
    ACPI_ADDRESS ExtendedPM2ControlBlock;
    ACPI_ADDRESS ExtendedPMTimerBlock;
    ACPI_ADDRESS ExtendedGPE0Block;
    ACPI_ADDRESS ExtendedGPE1Block;
  };
}  // namespace Detail

