/// @brief Perform system reboot using ACPI methods or fallback triple fault mechanism.
/// @return This function does not return as it triggers a system restart.
Void ACPIFactoryInterface::Reboot() {
  asm volatile(
      ".intel_syntax noprefix; "
      "reboot_hardware:; "
      "cli; "
      "poll_kbd_status:; "
      "in al,0x64; "
      "and al,2; "
      "jnz poll_kbd_status; "
      "mov al,0xD1; "
      "out 0x64,al; "
      "poll_output_buffer:; "
      "in al,0x64; "
      "and al,2; "
      "jnz poll_output_buffer; "
      "mov al,0xFE; "
      "out 0x60,al; "
      "xor rax,rax; "
      "lidt [rax]; "
      "infinite_loop:; "
      "jmp infinite_loop; "
      ".att_syntax; ");
}
}  // namespace Kernel

