namespace engine::store::pythonBase {
//-----------------------------------------------------------------
/// @details
///		Generate static, immutable configuration identifiers
///	@param[out]	configKey
///		Outputs the distinct configuration identifier for this endpoint
//-----------------------------------------------------------------
Error IPythonEndpointBase::getConfigSubKey(Text &configKey) noexcept {
    // Terminate the python endpoint processing
    const auto pythonHandler = localfcn()->Error {
        // If the underlying driver lacks this method, return default (empty)
        if (!py::hasattr(m_pyEndpoint, "getConfigSubKey")) return {};
        // Execute the method call
        auto resultKey = m_pyEndpoint.attr("getConfigSubKey")();
        // If no value returned, delegate to base implementation
        if (resultKey.is_none()) return Parent::getConfigSubKey(configKey);
        // Convert to string type
        configKey = py::cast<std::string>(resultKey);
        return {};
    };
    // Invoke Python handler
    return callPython(pythonHandler);
}
//-----------------------------------------------------------------
/// @details
///		Verify the integrity of the service setup. Typically, this
///		should not produce hard failures; instead, any issues should
///		be logged as warnings or errors in the diagnostics output.
///		A non-zero return code will be incorporated into the error
///		report by the configuration manager automatically
///	@param[in]	syntaxOnlyCheck
///		If true, only syntactic validation is performed
//-----------------------------------------------------------------
Error IPythonEndpointBase::validateConfig(bool syntaxOnlyCheck) noexcept {
    // Delegate to parent first
    if (auto status = Parent::validateConfig(syntaxOnlyCheck)) return status;
    // Wrap Python execution context
    const auto pythonHandler = localfcn()->Error {
        // If available, invoke derived implementation — raises on failure
        if (py::hasattr(m_pyEndpoint, "validateConfig"))
            m_pyEndpoint.attr("validateConfig")(syntaxOnlyCheck);
        return {};
    };
    // Execute Python logic
    return callPython(pythonHandler);
}
//-----------------------------------------------------------------
/// @details
///		Retrieve the ordered set of pipe stack filters
///	@param[out]	filterList
///		Aggregated list of filter specifications required by endpoint
//-----------------------------------------------------------------
Error IPythonEndpointBase::getPipeFilters(IPipeFilters &filterList) noexcept {
    Error status;
    // Python-side filter retrieval
    const auto pythonHandler = localfcn()->Error {
        if (py::hasattr(m_pyEndpoint, "getPipeFilters")) {
            // Fetch filters from Python endpoint
            pybind11::object rawResult = m_pyEndpoint.attr("getPipeFilters")();
            // Only process if it's a list
            if (!py::isinstance<py::list>(rawResult)) return {};
            // Extract list object
            py::list pyFilterList = rawResult.cast<py::list>();
            // Iterate over each item
            for (auto &entry : pyFilterList) {
                if (py::isinstance<py::str>(entry)) {
                    // String entries → Text objects
                    filterList.emplace_back(Text(py::cast<std::string>(entry)));
                } else if (py::isinstance<py::dict>(entry)) {
                    // Dictionary entries → JSON values via converter
                    json::Value jsonSpec =
                        engine::python::pyjson::dictToJson(entry);
                    filterList.emplace_back(
                        jsonSpec);  // Append copy to filter list
                } else {
                    throw APERR(Ec::InvalidParam,
                                "getPipeFilters entry must be str or dict");
                }
            }
        }
        return {};
    };
    status = callPython(pythonHandler);
    if (checkCallParent(status)) return Parent::getPipeFilters(filterList);
    return status;
}
}  // namespace engine::store::pythonBase

