namespace RC {
#ifdef RC_LOGGING
    std::ofstream log_stream;
    void close_log_file() { log_stream.close(); }
#endif

    void initialize_logging() {
#ifdef RC_LOGGING
        std::error_code err;
        std::filesystem::create_directories(ReCraftCore::GetRootDir(), err);

        const std::string root_dir = ReCraftCore::GetRootDir();
        const std::string log_path = root_dir + "/log.txt";
        const std::string backup_path = root_dir + "/log.last.txt";

        if (std::filesystem::exists(log_path)) {
            if (std::filesystem::exists(backup_path)) {
                std::filesystem::remove(backup_path, err);
            }
            std::filesystem::rename(log_path, backup_path, err);
        }

        log_stream.open(log_path);
#endif
    }

    void finalize_logging() {
#ifdef RC_LOGGING
        close_log_file();
#endif
    }

    void save_crash_info(const std::string& message) {
        std::ofstream crash_file(ReCraftCore::GetRootDir() + "/crash.txt");
        if (crash_file.is_open()) {
            crash_file << message;
            crash_file.close();
        }
#ifdef RC_LOGGING
        close_log_file();
#endif
    }

    void write_to_log(const std::string& text) {
#ifdef RC_LOGGING
        if (log_stream.is_open()) {
            log_stream << text << std::endl;
        }
#endif
    }

    void display_crash_screen(const std::string& error_msg) {
        gfxInitDefault();
        consoleInit(GFX_TOP, nullptr);

        std::cout << "ReCraft - " GIT_BRANCH " - " GIT_COMMIT " Error Handler\n\n";
        std::cout << error_msg << std::endl;
        std::cout << "\nPress Start to exit...\n";

        while (aptMainLoop) {
            hidScanInput();
            if (hidKeysDown() & KEY_START) {
                break;
            }
            gspWaitForVBlank();
            gfxSwapBuffers();
        }
    }
} // namespace RC

