std::string LogicalAggregatePrintInfo::toString() const {
    std::string output = "";
    output += "Grouping By: ";
    output += binder::ExpressionUtil::toString(groupingKeys);
    output += ", Aggregate Functions: ";
    output += binder::ExpressionUtil::toString(aggFunctions);
    return output;
}

void LogicalAggregate::computeFactorizedSchema() {
    resetSchema();
    auto groupIdx = schema->createGroup();
    addAllExpressionsToGroupAndScope(groupIdx);
}

void LogicalAggregate::computeFlatSchema() {
    resetSchema();
    schema->createGroup();
    addAllExpressionsToGroupAndScope(0 /* groupIndex */);
}

f_group_pos_set LogicalAggregate::getGroupsPosToFlatten() {
    auto [nonFlatGroup, flattenedGroups] =
        FlattenAllButOne::getGroupsPosToFlatten(getAllGroupingKeys(), *children[0]->getSchema());

    // Flatten distinct aggregates if they originate from a different group than the non-flat key group
    // Standard aggregates can be handled while unflattened, but distinct aggregates are placed in
    // separate AggregateHashTable instances and face the same input constraints as aggregate groups
    if (nonFlatGroup != INVALID_F_GROUP_POS) {
        for (const auto& aggExpr : aggFunctions) {
            auto funcExpr = aggExpr->constPtrCast<binder::AggregateFunctionExpression>();
            auto analyzer = GroupDependencyAnalyzer(false /* gatherDependentExprs */,
                *children[0]->getSchema());
            analyzer.visit(aggExpr);
            for (const auto& grp : analyzer.getRequiredFlatGroups()) {
                flattenedGroups.insert(grp);
            }
            if (funcExpr->isDistinct()) {
                for (const auto& grp : analyzer.getDependentGroups()) {
                    if (grp != nonFlatGroup) {
                        flattenedGroups.insert(grp);
                    }
                }
            }
        }
    }
    return flattenedGroups;
}

std::string LogicalAggregate::getExpressionsForPrinting() const {
    std::string result = "Group By [";
    for (auto& expr : groupingKeys) {
        result += expr->toString() + ", ";
    }
    for (auto& expr : dependentKeys) {
        result += expr->toString() + ", ";
    }
    result += "], Aggregates [";
    for (auto& expr : aggFunctions) {
        result += expr->toString() + ", ";
    }
    result += "]";
    return result;
}

void LogicalAggregate::addAllExpressionsToGroupAndScope(f_group_pos groupIdx) {
    for (auto& expr : groupingKeys) {
        schema->insertToGroupAndScopeMayRepeat(expr, groupIdx);
    }
    for (auto& expr : dependentKeys) {
        schema->insertToGroupAndScopeMayRepeat(expr, groupIdx);
    }
    for (auto& expr : aggFunctions) {
        schema->insertToGroupAndScopeMayRepeat(expr, groupIdx);
    }
}

