void SimpleAdBlocker::interceptRequest(QWebEngineUrlRequestInfo &info)
{
    if (!m_active) return;

    QUrl requestUrl = info.requestUrl();
    QString urlString = requestUrl.toString();
    QString domain = requestUrl.host();

    for (const QString &blockedDomain : m_blockedDomains) {
        if (domain.contains(blockedDomain) || urlString.contains(blockedDomain)) {
            info.block(true);
            return;
        }
    }
}

#include "stdafx.h"
#include "Buffer.h"

Buffer::Buffer(unsigned int capacity) : m_capacity(capacity), m_position(0), m_limit(capacity), hasBackingArray(false)
{
}

// Resets this buffer. The position is set to zero, the limit is set to the capacity, and the mark is discarded.
// This method does not actually erase the data in the buffer, but it is named as if it did because it will most often
// be used in situations in which that might as well be the case.
//
// Returns:
// This buffer
Buffer* Buffer::reset()
{
	m_position = 0;
	m_limit = m_capacity;
	return this;
}

// Configures this buffer's limit. If the position exceeds the new limit then it is adjusted to match.
// If the mark exists and is greater than the new limit then it is removed.
// Parameters:
// newLimit - The new limit value; must be non-negative and no larger than this buffer's capacity
// Returns:
// This buffer
Buffer* Buffer::setMaxLimit(unsigned int newLimit)
{
	assert(newLimit <= m_capacity);
	m_limit = newLimit;
	if (m_position > newLimit)
		m_position = newLimit;
	return this;
}

unsigned int Buffer::getMaxLimit()
{
	return m_limit;
}

// Adjusts this buffer's position. If the mark is defined and exceeds the new position then it is cleared.
// Parameters:
// newPos - The new position value; must be non-negative and no larger than the current limit
// Returns:
// This buffer
Buffer* Buffer::setPos(unsigned int newPos)
{
	assert(newPos <= m_limit);
	m_position = newPos;
	return this;
}

// Retrieves this buffer's current position.
// Returns:
// The position of this buffer
unsigned int Buffer::getPos()
{
	return m_position;
}

// Computes the number of elements between the current position and the limit.
// Returns:
// The number of elements remaining in this buffer
unsigned int Buffer::getRemaining()
{
	return m_limit - m_position;
}

