// Test suite for demangling functionality
TEST(common, demangling)
{
    // This test verifies the cxx_demangle function behavior:
    // - Correctly demangles valid mangled names
    // - Returns original string when demangling fails
    using pair_type = std::pair<std::string_view, std::string_view>;

    for(auto [input_mangled, expected_demangled] :
        {pair_type{"_ZN11rocprofiler8internal18correlation_config22get_unique_internal_idEv",
                   "rocprofiler::internal::correlation_config::get_unique_internal_id()"},
         pair_type{"_ZN11rocprofiler8internal18get_active_configsEv",
                   "rocprofiler::internal::get_active_configs()"},
         pair_type{"_ZN11rocprofiler8internal22get_registered_configsEv",
                   "rocprofiler::internal::get_registered_configs()"},
         pair_type{
             "_ZZN11rocprofiler8internal18correlation_config22get_unique_internal_idEvE2_v",
             "rocprofiler::internal::correlation_config::get_unique_internal_id()::_v"},
         pair_type{"_ZZN11rocprofiler8internal18get_active_configsEvE2_v",
                   "rocprofiler::internal::get_active_configs()::_v"},
         pair_type{"_ZZN11rocprofiler8internal22get_registered_configsEvE2_v",
                   "rocprofiler::internal::get_registered_configs()::_v"}})
    {
        // Check that demangling produces expected result
        EXPECT_EQ(rocprofiler::common::cxx_demangle(input_mangled), expected_demangled)
            << "demangling failed for '" << input_mangled << "'";

        // Verify that malformed mangled strings are returned unchanged
        auto invalid_mangled = std::string{"_Z"} + std::string{input_mangled};
        EXPECT_EQ(rocprofiler::common::cxx_demangle(invalid_mangled), invalid_mangled)
            << "unexpected success demangling '" << invalid_mangled << "'";
    }
}

// Test suite for name truncation functionality
TEST(common, truncate)
{
    // This test verifies that truncate_name correctly extracts function names
    // from complex template instantiations

    auto mangled_input = std::string_view{"_ZSt16__do_uninit_copyIPKSt4pairINSt7__cxx1112basic_"
                                    "stringIcSt11char_traitsIcESaIcEEES6_EPS7_ET0_T_SC_SB_"};

    auto full_demangled = std::string_view{
        "std::pair<std::__cxx11::basic_string<char, std::char_traits<char>, std::allocator<char> "
        ">, std::__cxx11::basic_string<char, std::char_traits<char>, std::allocator<char> > >* "
        "std::__do_uninit_copy<std::pair<std::__cxx11::basic_string<char, std::char_traits<char>, "
        "std::allocator<char> >, std::__cxx11::basic_string<char, std::char_traits<char>, "
        "std::allocator<char> > > const*, std::pair<std::__cxx11::basic_string<char, "
        "std::char_traits<char>, std::allocator<char> >, std::__cxx11::basic_string<char, "
        "std::char_traits<char>, std::allocator<char> > "
        ">*>(std::pair<std::__cxx11::basic_string<char, std::char_traits<char>, "
        "std::allocator<char> >, std::__cxx11::basic_string<char, std::char_traits<char>, "
        "std::allocator<char> > > const*, std::pair<std::__cxx11::basic_string<char, "
        "std::char_traits<char>, std::allocator<char> >, std::__cxx11::basic_string<char, "
        "std::char_traits<char>, std::allocator<char> > > const*, "
        "std::pair<std::__cxx11::basic_string<char, std::char_traits<char>, std::allocator<char> "
        ">, std::__cxx11::basic_string<char, std::char_traits<char>, std::allocator<char> > >*)"};

    // Verify full demangling matches expected output
    EXPECT_EQ(rocprofiler::common::cxx_demangle(mangled_input), full_demangled);

    // Verify truncation extracts correct function name
    EXPECT_EQ(rocprofiler::common::truncate_name(full_demangled),
              std::string_view{"__do_uninit_copy"});

    // Verify truncation works on demangled result directly
    EXPECT_EQ(rocprofiler::common::truncate_name(rocprofiler::common::cxx_demangle(mangled_input)),
              std::string_view{"__do_uninit_copy"});
}

#include <cstdlib>
#include <iostream>
#include <boost/bind.hpp>
#include "asio.hpp"
#include "asio/ssl.hpp"

enum { buffer_size = 2048 };

class secure_client
{
public:
  secure_client(asio::io_context& service,
      asio::ssl::context& ssl_context,
      asio::ip::tcp::resolver::results_type server_endpoints)
    : ssl_socket_(service, ssl_context)
  {
    ssl_socket_.set_verify_mode(asio::ssl::verify_peer);
    ssl_socket_.set_verify_callback(
        boost::bind(&secure_client::check_certificate, this, _1, _2));
    asio::async_connect(ssl_socket_.lowest_layer(), server_endpoints,
        boost::bind(&secure_client::on_connection, this,
          asio::placeholders::error));
  }

  bool check_certificate(bool is_valid,
      asio::ssl::verify_context& ctx)
  {
    // This callback can be used to validate the peer's certificate.
    // For instance, RFC 2818 outlines the procedure for HTTPS.
    // Refer to OpenSSL documentation for further details.
    // The function is invoked once per certificate in the chain,
    // beginning with the root CA.
    // Here we simply display the certificate's subject name.
    char cert_subject[512];
    X509* cert = X509_STORE_CTX_get_current_cert(ctx.native_handle());
    X509_NAME_oneline(X509_get_subject_name(cert), cert_subject, 512);
    std::cout << "Certificate subject: " << cert_subject << "\n";
    return is_valid;
  }

  void on_connection(const asio::error_code& err)
  {
    if (!err)
    {
      ssl_socket_.async_handshake(asio::ssl::stream_base::client,
          boost::bind(&secure_client::on_handshake_complete, this,
            asio::placeholders::error));
    }
    else
    {
      std::cerr << "Connection error: " << err.message() << "\n";
    }
  }

  void on_handshake_complete(const asio::error_code& err)
  {
    if (!err)
    {
      std::cout << "Enter your message: ";
      std::cin.getline(user_input_, buffer_size - 1);
      size_t msg_length = strlen(user_input_);
      asio::async_write(ssl_socket_,
          asio::buffer(user_input_, msg_length),
          boost::bind(&secure_client::on_send_complete, this,
            asio::placeholders::error,
            asio::placeholders::bytes_transferred));
    }
    else
    {
      std::cerr << "SSL handshake failed: " << err.message() << "\n";
    }
  }

  void on_send_complete(const asio::error_code& err,
      size_t bytes_sent)
  {
    if (!err)
    {
      asio::async_read(ssl_socket_,
          asio::buffer(response_buffer_, bytes_sent),
          boost::bind(&secure_client::on_receive_complete, this,
            asio::placeholders::error,
            asio::placeholders::bytes_transferred));
    }
    else
    {
      std::cerr << "Transmission failed: " << err.message() << "\n";
    }
  }

  void on_receive_complete(const asio::error_code& err,
      size_t bytes_received)
  {
    if (!err)
    {
      std::cout << "Server response: ";
      std::cout.write(response_buffer_, bytes_received);
      std::cout << "\n";
    }
    else
    {
      std::cerr << "Reception error: " << err.message() << "\n";
    }
  }

private:
  asio::ssl::stream<asio::ip::tcp::socket> ssl_socket_;
  char user_input_[buffer_size];
  char response_buffer_[buffer_size];
};

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 3)
    {
      std::cerr << "Usage: secure_client <hostname> <port>\n";
      return 1;
    }

    asio::io_context io_service;
    asio::ip::tcp::resolver resolver(io_service);
    auto endpoints = resolver.resolve(argv[1], argv[2]);

    asio::ssl::context ssl_ctx(asio::ssl::context::sslv23);
    ssl_ctx.load_verify_file("ca.pem");

    secure_client client_instance(io_service, ssl_ctx, endpoints);
    io_service.run();
  }
  catch (const std::exception& ex)
  {
    std::cerr << "Runtime error: " << ex.what() << "\n";
  }

  return 0;
}

#include "jemalloc/internal/jemalloc_preamble.h"
#include "jemalloc/internal/jemalloc_internal_includes.h"
#include "jemalloc/internal/prof_stats.h"

bool opt_prof_stats = true;
malloc_mutex_t prof_stats_lock;
static prof_stats_t live_stats[PROF_SC_NSIZES];
static prof_stats_t accum_stats[PROF_SC_NSIZES];

static void
prof_stats_acquire(tsd_t *tsd, szind_t index) {
    assert(opt_prof && opt_prof_stats);
    assert(index < SC_NSIZES);
    malloc_mutex_lock(tsd_tsdn(tsd), &prof_stats_lock);
}

static void
prof_stats_release(tsd_t *tsd) {
    malloc_mutex_unlock(tsd_tsdn(tsd), &prof_stats_lock);
}

void
prof_stats_add(tsd_t *tsd, szind_t index, size_t size) {
    cassert(config_prof);
    prof_stats_acquire(tsd, index);
    live_stats[index].req_sum += size;
    live_stats[index].count++;
    accum_stats[index].req_sum += size;
    accum_stats[index].count++;
    prof_stats_release(tsd);
}

void
prof_stats_subtract(tsd_t *tsd, szind_t index, size_t size) {
    cassert(config_prof);
    prof_stats_acquire(tsd, index);
    live_stats[index].req_sum -= size;
    live_stats[index].count--;
    prof_stats_release(tsd);
}

void
prof_stats_fetch_live(tsd_t *tsd, szind_t index, prof_stats_t *result) {
    cassert(config_prof);
    prof_stats_acquire(tsd, index);
    memcpy(result, &live_stats[index], sizeof(prof_stats_t));
    prof_stats_release(tsd);
}

void
prof_stats_fetch_accum(tsd_t *tsd, szind_t index, prof_stats_t *result) {
    cassert(config_prof);
    prof_stats_acquire(tsd, index);
    memcpy(result, &accum_stats[index], sizeof(prof_stats_t));
    prof_stats_release(tsd);
}

#include "EventTimer.hpp"
#include <algorithm>
#include <limits>
#include <iostream>
#include "debug.hpp"
//#include "cpu.hpp"

// EventTimer destructor
EventTimer::~EventTimer() = default;

// Update the next event cycle to the earliest scheduled event
inline void EventTimer::updateNextEventCycle() {
    // Set next_event_cycle to the smallest trigger time, or max if no events exist
    next_event_cycle = events.empty() ? std::numeric_limits<uint64_t>::max() : events.front().triggerCycles;
}

// Schedule a new event or update an existing one
void EventTimer::scheduleEvent(uint64_t triggerCycles, void (*callback)(uint64_t, void*), uint64_t instanceID, void* userData) {
    if (DEBUG(DEBUG_EVENT_TIMER)) std::cout << "scheduleEvent: " << triggerCycles << " InstanceID: " << instanceID << std::endl;

    // Skip scheduling if the event is in the past relative to the clock
    if (clock && triggerCycles < clock->get_cycles()) {
        std::cout << "scheduleEvent: Event in the past, skipping" << std::endl;
        return;
    }

    // Search for an existing event with the same instance ID
    auto existingEvent = std::find_if(events.begin(), events.end(), 
        [instanceID](const Event& evt) { return evt.instanceID == instanceID; });

    if (existingEvent != events.end()) {
        // Update the existing event's properties
        existingEvent->triggerCycles = triggerCycles;
        existingEvent->triggerCallback = callback;
        existingEvent->userData = userData;

        // Restore heap property after modification
        std::make_heap(events.begin(), events.end(), [](const Event& a, const Event& b) {
            return a.triggerCycles > b.triggerCycles;
        });
    } else {
        // Insert a new event into the queue
        Event newEvent{triggerCycles, callback, instanceID, userData};
        events.push_back(newEvent);
        std::push_heap(events.begin(), events.end(), [](const Event& a, const Event& b) {
            return a.triggerCycles > b.triggerCycles; // Min-heap based on earliest trigger time
        });
    }

    // Refresh the cached next event cycle
    updateNextEventCycle();
}

// Trigger all events that are due by the specified cycle count
void EventTimer::processEvents(uint64_t currentCycles) {
    /* std::cout << "processEvents: " << currentCycles << "Front: " << events.front().triggerCycles << std::endl;
    if (!events.empty()) {
        std::cout << "Events on queue: " << events.size() << std::endl;
    } */

    while (!events.empty() && events.front().triggerCycles <= currentCycles) {
        Event event = events.front();
        std::pop_heap(events.begin(), events.end(), [](const Event& a, const Event& b) {
            return a.triggerCycles > b.triggerCycles;
        });
        events.pop_back();

        if (DEBUG(DEBUG_EVENT_TIMER)) std::cout << "Processing event: " << event.triggerCycles << " InstanceID: " << event.instanceID << std::endl;

        // Execute the registered callback if present
        if (event.triggerCallback) {
            event.triggerCallback(event.instanceID, event.userData);
        }
    }

    updateNextEventCycle();
}

// Remove all events associated with a given instance ID
void EventTimer::cancelEvents(uint64_t instanceID) {
    auto newEnd = std::remove_if(events.begin(), events.end(),
        [instanceID](const Event& evt) { return evt.instanceID == instanceID; });

    if (newEnd != events.end()) {
        events.erase(newEnd, events.end());
        // Re-establish heap ordering after removals
        std::make_heap(events.begin(), events.end(), [](const Event& a, const Event& b) {
            return a.triggerCycles > b.triggerCycles;
        });
    }

    updateNextEventCycle();
}

// Determine whether any events are pending
bool EventTimer::hasPendingEvents() const {
    return !events.empty();
}

// Retrieve the cycle count of the earliest scheduled event
uint64_t EventTimer::getNextEventCycle() const {
    return next_event_cycle;
}

