        Operator firstOperator(7, &v);
        firstOperator.display();
    } // firstOperator's destructor is called here
    // the Vehicle still lives independently of the Operator whose destructor was called
    Operator secondOperator(12, &v); // another operator starts using that same vehicle
    secondOperator.display();
}

