  // Boolean is a valid value
  Value* To_Value::operator()(Boolean* boolVal)
  {
    return boolVal;
  }

  // Number is a valid value
  Value* To_Value::operator()(Number* num)
  {
    return num;
  }

  // Color is a valid value
  Value* To_Value::operator()(Color_RGBA* color)
  {
    return color;
  }

  // Color is a valid value
  Value* To_Value::operator()(Color_HSLA* color)
  {
    return color;
  }

  // String_Constant is a valid value
  Value* To_Value::operator()(String_Constant* str)
  {
    return str;
  }

  // String_Quoted is a valid value
  Value* To_Value::operator()(String_Quoted* str)
  {
    return str;
  }

  // List is a valid value
  Value* To_Value::operator()(List* lst)
  {
    List_Obj newLst = SASS_MEMORY_NEW(List,
                                   lst->pstate(),
                                   lst->length(),
                                   lst->separator(),
                                   lst->is_arglist(),
                                   lst->is_bracketed());
    for (size_t idx = 0, len = lst->length(); idx < len; ++idx) {
      newLst->append((*lst)[idx]->perform(this));
    }
    return newLst.detach();
  }

  // Map is a valid value
  Value* To_Value::operator()(Map* mp)
  {
    return mp;
  }

  // Null is a valid value
  Value* To_Value::operator()(Null* nullVal)
  {
    return nullVal;
  }

  // Function is a valid value
  Value* To_Value::operator()(Function* func)
  {
    return func;
  }

  // Argument returns its value
  Value* To_Value::operator()(Argument* arg)
  {
    if (!arg->name().empty()) return nullptr;
    return arg->value()->perform(this);
  }

  // SelectorList is converted to a string
  Value* To_Value::operator()(SelectorList* selList)
  {
    return SASS_MEMORY_NEW(String_Quoted,
                           selList->pstate(),
                           selList->to_string(ctx.c_options));
  }

