  Value* To_Value::operator()(Binary_Expression* binExpr)
  {
    return SASS_MEMORY_NEW(String_Quoted,
                           binExpr->pstate(),
                           binExpr->to_string(ctx.c_options));
  }
};

#define SOL_ALL_SAFETIES_ON 1
#include <sol/sol.hpp>

int main(int argc, char* argv[]) {
    sol::state lua_vm;
    lua_vm.script("function calculate(a, b) return (a + b) * 2 end");

    sol::reference func_handle = lua_vm["calculate"];

    // This could be inside a lua_CFunction binding,
    // or part of an integration with an existing system,
    // perhaps using a custom lua_load invocation,
    // or working with state_view's load(lua_Reader, ...) mechanism...
    // Below demonstrates stack manipulation techniques:
    lua_State* L = lua_vm.lua_state();

    // Set up an error handler:
    // stack_aligned_stack_handler,
    // as its name indicates,
    // expects the handler to be placed on the stack
    sol::stack_reference error_handler(L,
         -sol::stack::push(
              L, sol::default_traceback_error_handler));

    // Push the function onto the stack
    func_handle.push();
    sol::stack_aligned_stack_handler_function callable(
         L, -1, error_handler);

    // Push arguments manually using the raw C API
    lua_pushinteger(L, 7); // first argument
    lua_pushinteger(L, 8); // second argument

    // Execute the function with 2 arguments
    int output = callable(sol::stack_count(2));
    // The call removes the function and arguments from the stack,
    // leaving only the result; however, we must clean up the error handler ourselves
    error_handler.pop();

    // Verify correctness and stack balance
    SOL_ASSERT(output == 30);
    SOL_ASSERT(
         lua.stack_top() == 0); // ensure stack is empty after execution

    return 0;
}

