#include "ByteArrayInputStream.h"
#include <cstddef>
#include "util/console/ArrayWithLength.h"
#include "win/extraX64.h"

ByteArrayInputStream::ByteArrayInputStream(
    byteArray    buffer,
    unsigned int startOffset,
    unsigned int maxLength
)
: currentPos(startOffset),
  totalBytes(std::min(startOffset + maxLength, buffer.length)),
  markPosition(startOffset) {
    this->buffer = buffer;
}

// Creates a ByteArrayInputStream so that it uses buffer as its internal storage.
// The provided buffer is not duplicated. Initially, currentPos is set to 0 and
// totalBytes is assigned the full length of the buffer.
// Parameters: buffer - the data source array.
ByteArrayInputStream::ByteArrayInputStream(byteArray buffer)
: currentPos(0),
  totalBytes(buffer.length),
  markPosition(0) {
    this->buffer = buffer;
}

// Reads the next byte from the stream. Returns the byte value (0-255) as an int,
// or -1 if no more bytes remain. This operation does not block.
// Returns: the next byte or -1 on EOF.
int ByteArrayInputStream::read() {
    if (currentPos >= totalBytes) return -1;
    else return buffer.data[currentPos++];
}

// Reads multiple bytes into the provided buffer b. Returns the number of bytes
// actually read, or -1 if none are available. Delegates to read(b, 0, b.length).
// Parameters: b - destination array for the input data.
// Returns: number of bytes read, or -1 if end-of-stream reached.
int ByteArrayInputStream::read(byteArray b) { return read(b, 0, b.length); }

// Reads up to length bytes into array b starting at index offset. If currentPos
// equals totalBytes, returns -1. Otherwise, reads min(length, totalBytes - currentPos)
// bytes using XMemCpy. Updates currentPos and returns the count of bytes copied.
// Parameters:
//   b        - destination array
//   offset   - starting index in b
//   length   - maximum number of bytes to read
// Returns: actual number of bytes read, or -1 if no data remains.
int ByteArrayInputStream::read(
    byteArray    b,
    unsigned int offset,
    unsigned int length
) {
    if (currentPos == totalBytes) return -1;
    int bytesRead = std::min(length, totalBytes - currentPos);
    XMemCpy(&b[offset], &buffer.data[currentPos], bytesRead);
    // std::copy( buffer.data+currentPos, buffer.data+currentPos+bytesRead, b.data + offset );
    currentPos += bytesRead;
    return bytesRead;
}

// No-op implementation: closing a ByteArrayInputStream has no effect.
// All methods remain usable after calling close().
void ByteArrayInputStream::close() { return; }

// Skips up to n bytes forward in the stream. Actual skipped amount k is the
// smaller of n and (totalBytes - currentPos). Updates currentPos and returns k.
// Overrides: skip in base InputStream class.
// Parameters: n - desired number of bytes to skip.
// Returns: actual number of bytes skipped.
std::int64_t ByteArrayInputStream::skip(std::int64_t n) {
    int newPos = currentPos + n;
    if (newPos > totalBytes) newPos = totalBytes;
    int skipped = newPos - currentPos;
    currentPos   = newPos;
    return skipped;
}

ByteArrayInputStream::~ByteArrayInputStream() {
    if (buffer.data != NULL) delete[] buffer.data;
}

