using namespace llvm;

/// Parses a comma-separated string into individual feature strings.
void SubtargetFeatures::Split(std::vector<std::string> &V, StringRef S) {
  SmallVector<StringRef, 3> Parts;
  S.split(Parts, ',', -1, false /* KeepEmpty */);
  V.reserve(Parts.size());
  for (StringRef Part : Parts)
    V.emplace_back(Part.str());
}

void SubtargetFeatures::AddFeature(StringRef FeatureStr, bool Enable) {
  // Skip empty feature strings.
  if (!FeatureStr.empty()) {
    // Normalize to lowercase and ensure proper flag prefix.
    std::string Normalized = FeatureStr.lower();
    if (hasFlag(FeatureStr))
      Features.push_back(Normalized);
    else
      Features.push_back((Enable ? "+" : "-") + Normalized);
  }
}

void SubtargetFeatures::addFeaturesVector(
    const ArrayRef<std::string> AdditionalFeatures) {
  Features.insert(Features.end(), AdditionalFeatures.begin(), AdditionalFeatures.end());
}

SubtargetFeatures::SubtargetFeatures(StringRef Initial) {
  // Initialize features by splitting the input string.
  Split(Features, Initial);
}

std::string SubtargetFeatures::getString() const {
  return join(Features.begin(), Features.end(), ",");
}

void SubtargetFeatures::print(raw_ostream &OS) const {
  for (const auto &Feature : Features)
    OS << Feature << " ";
  OS << "\n";
}

#if !defined(NDEBUG) || defined(LLVM_ENABLE_DUMP)
LLVM_DUMP_METHOD void SubtargetFeatures::dump() const {
  print(dbgs());
}
#endif

void SubtargetFeatures::getDefaultSubtargetFeatures(const Triple& TargetTriple) {
  // TODO: Improve this mechanism — encoding subtarget info directly in IR would be cleaner.
  if (TargetTriple.getVendor() == Triple::Apple) {
    switch (TargetTriple.getArch()) {
      case Triple::ppc:
        // e.g., powerpc-apple-*
        AddFeature("altivec");
        break;
      case Triple::ppc64:
        // e.g., powerpc64-apple-*
        AddFeature("64bit");
        AddFeature("altivec");
        break;
      default:
        break;
    }
  }
}

