#include "JavaMath.h"
#include "Random.h"

// Pseudorandom number generator instance
Random Math::rand = Random();

// Generates a double in the range [0.0, 1.0)
// Uses an internal pseudorandom-number generator that is created on first use
// Thread-safe implementation for concurrent access
double Math::random() { 
    return Math::rand.nextDouble(); 
}

// Rounds a double value to the nearest long integer
// Implementation follows: (long)Math.floor(a + 0.5d)
// Handles special cases: NaN → 0, overflow/underflow → Long.MIN/MAX_VALUE
std::int64_t Math::round(double d) { 
    return static_cast<std::int64_t>(floor(d + 0.5)); 
}

// Integer maximum function
int Math::_max(int a, int b) { 
    return (a > b) ? a : b; 
}

// Integer minimum function
int Math::_min(int a, int b) { 
    return (a < b) ? a : b; 
}

// Float maximum function
float Math::_max(float a, float b) { 
    return (a > b) ? a : b; 
}

// Float minimum function
float Math::_min(float a, float b) { 
    return (a < b) ? a : b; 
}

// Wraps an angle in degrees to the range [-180, 180)
float Math::wrapDegrees(float input) {
    while (input >= 360.0f) {
        input -= 360.0f;
    }
    if (input >= 180.0f) {
        input -= 360.0f;
    } else if (input < -180.0f) {
        input += 360.0f;
    }
    return input;
}

// Wraps an angle in degrees to the range [-180, 180) (double version)
double Math::wrapDegrees(double input) {
    while (input >= 360.0) {
        input -= 360.0;
    }
    if (input >= 180.0) {
        input -= 360.0;
    } else if (input < -180.0) {
        input += 360.0;
    }
    return input;
}

