namespace Karm::Aio {

export template <typename T>
struct AdapterWrapper : Reader, Writer {
    T& _wrapped;

    AdapterWrapper(T& wrapped)
        : _wrapped(wrapped) {}

    Async::Task<usize> writeAsync(Bytes buffer, Async::CancellationToken) override {
        if constexpr (Io::Writable<T>) {
            co_return _wrapped.write(buffer);
        } else {
            co_return Ok(buffer.len());
        }
    }

    Async::Task<usize> readAsync(MutBytes buffer, Async::CancellationToken) override {
        if constexpr (Io::Readable<T>) {
            co_return _wrapped.read(buffer);
        } else {
            co_return Ok(0);
        }
    }
};

export template <typename T>
AdapterWrapper<T> createAdapter(T& item) {
    return {item};
}

