// Apply Wi-Fi power state: disable or enable connection
void applyWifiPower(bool isActive)
{
  if (!isActive) {
    WiFi.setAutoReconnect(false);
    WiFi.disconnect(true, true);
    WiFi.mode(WIFI_OFF);
    return;
  }

  // Activate Wi-Fi in station mode
  WiFi.mode(WIFI_STA);
  WiFi.setAutoReconnect(true);

  String storedSsid, storedPass;
  if (wifiStoreLoad(storedSsid, storedPass)) {
    WiFi.begin(storedSsid.c_str(), storedPass.c_str());
  } else {
    // No credentials found => prevent automatic reconnection
    WiFi.setAutoReconnect(false);
    WiFi.disconnect(true, true);
  }
}

// Reset Wi-Fi settings by clearing saved credentials
void wifiResetSettings()
{
  Preferences prefs;
  prefs.begin("rh_wifi", false);
  prefs.putString("ssid", "");
  prefs.putString("pass", "");
  prefs.end();

  // Terminate current connection
  WiFi.disconnect(true, true);
  delay(50);
}

