#include <asio/use_future.hpp>
#include <iostream>

using asio::post;
using asio::thread_pool;
using asio::use_future;

// Modified active object pattern implementation
class bank_account
{
  int current_balance_ = 0;
  mutable thread_pool executor_{1};
public:
  void credit(int value)
  {
    post(executor_,
      use_future([=]
        {
          current_balance_ += value;
        })).get();
  }
  void debit(int value)
  {
    post(executor_,
      use_future([=]
        {
          if (current_balance_ >= value)
            current_balance_ -= value;
        })).get();
  }
  int get_balance() const
  {
    return post(executor_,
      use_future([=]
        {
          return current_balance_;
        })).get();
  }
};

int main()
{
  bank_account account;
  account.credit(25);
  account.debit(15);
  std::cout << "balance = " << account.get_balance() << "\n";
}

