namespace lbug {
namespace function {

// Compute absolute value with overflow protection for signed integers
template<typename INPUT_TYPE>
static inline bool ComputeAbsWithOverflow(INPUT_TYPE value, INPUT_TYPE& output) {
    if (value == NumericLimits<INPUT_TYPE>::minimum()) {
        return false;
    }
    output = std::abs(value);
    return true;
}

struct AbsOperation {
    template<typename T>
    static inline bool apply(T& input_value, T& output_result);
};

// Specializations for fixed-width integer types
template<>
bool inline AbsOperation::apply(int8_t& input_value, int8_t& output_result) {
    return ComputeAbsWithOverflow<int8_t>(input_value, output_result);
}

template<>
bool inline AbsOperation::apply(int16_t& input_value, int16_t& output_result) {
    return ComputeAbsWithOverflow<int16_t>(input_value, output_result);
}

template<>
bool inline AbsOperation::apply(int32_t& input_value, int32_t& output_result) {
    return ComputeAbsWithOverflow<int32_t>(input_value, output_result);
}

template<>
bool AbsOperation::apply(int64_t& input_value, int64_t& output_result) {
    return ComputeAbsWithOverflow<int64_t>(input_value, output_result);
}

// Public interface for INT8
template<>
void Abs::operation(int8_t& input_value, int8_t& output_result) {
    if (!AbsOperation::apply(input_value, output_result)) {
        throw common::OverflowException{
            std::format("Cannot compute absolute value of {} in INT8 range.",
                common::TypeUtils::toString(input_value))};
    }
}

// Public interface for INT16
template<>
void Abs::operation(int16_t& input_value, int16_t& output_result) {
    if (!AbsOperation::apply(input_value, output_result)) {
        throw common::OverflowException{
            std::format("Cannot compute absolute value of {} in INT16 range.",
                common::TypeUtils::toString(input_value))};
    }
}

// Public interface for INT32
template<>
void Abs::operation(int32_t& input_value, int32_t& output_result) {
    if (!AbsOperation::apply(input_value, output_result)) {
        throw common::OverflowException{
            std::format("Cannot compute absolute value of {} in INT32 range.",
                common::TypeUtils::toString(input_value))};
    }
}

// Public interface for INT64
template<>
void Abs::operation(int64_t& input_value, int64_t& output_result) {
    if (!AbsOperation::apply(input_value, output_result)) {
        throw common::OverflowException{
            std::format("Cannot compute absolute value of {} in INT64 range.",
                common::TypeUtils::toString(input_value))};
    }
}

// Public interface for int128_t (no overflow possible)
template<>
void Abs::operation(common::int128_t& input_value, common::int128_t& output_result) {
    output_result = (input_value < 0) ? -input_value : input_value;
}

