#include "../core/clauses/bk-clauses.hpp"
#include <CLI/CLI.hpp>
#include <iostream>
#include <map>
#include <string>
#include <vector>

int main(int argc, char **argv) {
    // Using CLI11 for command-line parsing with subcommands (verbs)
    CLI::App program{"beekeeperman"};

    std::string selected_verb;
    std::map<std::string, std::string> parsed_options;
    std::vector<std::string> positional_args;

    // Dynamically register each verb from the registry
    for (const auto &[name, info] : clauses_registry) {
        // Create a subcommand for this verb
        CLI::App *subcmd = program.add_subcommand(name, info.description);

        // Set callback to capture which verb was invoked
        subcmd->callback([&]() {
            selected_verb = name;
        });

        // Register all allowed options for this verb
        for (const auto &opt : info.allowed_options) {
            std::string spec = "--" + opt.long_name;
            if (!opt.short_name.empty()) {
                spec += ",-" + opt.short_name;
            }

            if (opt.requires_value) {
                subcmd->add_option(
                    spec,
                    parsed_options[opt.long_name]
                )->required(false);
            } else {
                subcmd->add_flag(
                    spec,
                    [&](std::size_t) {
                        parsed_options[opt.long_name] = "true";
                    }
                );
            }
        }

        // Add positional arguments (subjects)
        subcmd->add_option(
            "args",
            positional_args,
            "Target subjects for this clause"
        );
    }

    // Parse command line arguments
    try {
        program.require_subcommand(1);
        program.parse(argc, argv);
    } catch (const CLI::ParseError &err) {
        return program.exit(err);
    }

    // Execute the handler associated with the selected verb
    command_streams result = clauses_registry.at(selected_verb).handler(parsed_options, positional_args);

    // Output results: stderr first, then stdout, and finally return exit code
    if (!result.stderr_str.empty()) {
        std::cerr << result.stderr_str << std::endl;
    }
    if (!result.stdout_str.empty()) {
        std::cout << result.stdout_str << std::endl;
    }
    return result.errcode;
}

