#define SOL_ALL_SAFETIES_ON 1
#include <sol/sol.hpp>
#include <memory>
#include <iostream>

struct sacred {
private:
    sacred() : value() {
    }
    sacred(int val) : value(val) {
    }
    ~sacred() {
    }
public:
    struct destroyer {
        void operator()(sacred* ptr) const {
            cleanup(*ptr);
        }
    };
    const int value;
    static std::unique_ptr<sacred, destroyer> instantiate() {
        std::cout << "instantiating 'sacred' unique_ptr directly and "
                     "letting sol/Lua manage it"
                  << std::endl;
        return std::unique_ptr<sacred, destroyer>(new sacred(50));
    }
    static void setup(sacred& raw_memory) {
        std::cout << "setting up 'sacred' userdata at "
                  << static_cast<void*>(&raw_memory)
                  << std::endl;
        new (&raw_memory) sacred();
    }
    static void cleanup(sacred& lua_managed_memory) {
        std::cout << "cleaning up 'sacred' userdata at "
                  << static_cast<void*>(&lua_managed_memory)
                  << std::endl;
        lua_managed_memory.~sacred();
    }
};

int main() {
    std::cout << "=== usertype_initializers ===" << std::endl;
    { // scope block to ensure destruction order
        sol::state vm;
        vm.open_libraries();
        vm.new_usertype<sacred>("sacred",
             "new",
             sol::initializers(&sacred::setup),
             "instantiate",
             sol::factories(&sacred::instantiate),
             sol::meta_function::garbage_collect,
             sol::destructor(&sacred::cleanup),
             "value",
             &sacred::value);
        vm.script(R"(
s1 = sacred.instantiate()
s2 = sacred.new()
print('s1.value is ' .. s1.value)
print('s2.value is ' .. s2.value)
)");
        sacred& s1 = vm["s1"];
        sacred& s2 = vm["s2"];
        SOL_ASSERT(s1.value == 50);
        SOL_ASSERT(s2.value == 0);
    }
    std::cout << std::endl;
}

#include "sample-string.h"
#include <gtest/gtest.h>

// Verifies the behavior of the default constructor
TEST(MyString, DefaultConstructor) {
  const MyString str;
  // Checks that str.c_string() returns nullptr.
  //
  // <ImplementationNotes>
  //
  // Using NULL instead of
  //
  //   static_cast<const char *>(NULL)
  //
  // would cause a warning in gcc 3.4, because EXPECT_EQ must deduce the types
  // of its operands to format them on failure. As NULL is typically #defined
  // as 0, the compiler treats it as an int, but gcc warns that NULL should be
  // used only as a pointer.
  //
  // This stems from C++'s historical ambiguity between zero and null pointers,
  // which remains unresolved.
  //
  // </ImplementationNotes>
  EXPECT_STREQ(nullptr, str.c_string());
  EXPECT_EQ(0u, str.Length());
}

const char kTestPhrase[] = "Hello, world!";

// Tests the constructor that takes a C-style string
TEST(MyString, ConstructorFromCString) {
  const MyString str(kTestPhrase);
  EXPECT_EQ(0, strcmp(str.c_string(), kTestPhrase));
  EXPECT_EQ(sizeof(kTestPhrase)/sizeof(kTestPhrase[0]) - 1,
            str.Length());
}

// Tests the copy constructor
TEST(MyString, CopyConstructor) {
  const MyString original(kTestPhrase);
  const MyString copy(original);
  EXPECT_EQ(0, strcmp(copy.c_string(), kTestPhrase));
}

// Tests the Set() method
TEST(MyString, Set) {
  MyString str;
  str.Set(kTestPhrase);
  EXPECT_EQ(0, strcmp(str.c_string(), kTestPhrase));

  // Verify Set works when the input pointer aliases the current internal buffer
  str.Set(str.c_string());
  EXPECT_EQ(0, strcmp(str.c_string(), kTestPhrase));

  // Test setting the string to nullptr
  str.Set(nullptr);
  EXPECT_STREQ(nullptr, str.c_string());
}

#include "PPCXCOFFStreamer.h"
