// Template union for managing stream and buffer data
template <class StreamT, class BufferT>
union io_stream_data {
  constexpr io_stream_data() {}
  constexpr ~io_stream_data() {}
  struct {
    // Stream object must be first due to references in <iostream>
    StreamT stream_obj;
    BufferT buffer_obj;
    mbstate_t mb_state;
  };

  void initialize(FILE* stdstream) {
    mb_state = {};
    std::construct_at(&buffer_obj, stdstream, &mb_state);
    std::construct_at(&stream_obj, &buffer_obj);
  }
};

