// Initialize TLS for locales before creating standard streams
static void ensure_locale_tls_setup() {
#if defined(_LIBCPP_MSVCRT_LIKE)
  static bool initialized = []() {
    auto loc = __locale::__newlocale(_LIBCPP_ALL_MASK, "C", 0);
    {
      __locale::__locale_guard g(loc); // ensures locale TLS initialization
      ((void)g);
    }
    __locale::__freelocale(loc);
    return true;
  }();
  ((void)initialized);
#endif
}

class StreamInitializer {
public:
  StreamInitializer();
  ~StreamInitializer();
};

StreamInitializer::StreamInitializer() {
  ensure_locale_tls_setup();
  cin.initialize(stdin);
  cout.initialize(stdout);
  cerr.initialize(stderr);
  clog.initialize(stderr);
  cin.stream_obj.tie(&cout.stream_obj);
  std::unitbuf(cerr.stream_obj);
  cerr.stream_obj.tie(&cout.stream_obj);

#if _LIBCPP_HAS_WIDE_CHARACTERS
  wcin.initialize(stdin);
  wcout.initialize(stdout);
  wcerr.initialize(stderr);
  wclog.initialize(stderr);
  wcin.stream_obj.tie(&wcout.stream_obj);
  std::unitbuf(wcerr.stream_obj);
  wcerr.stream_obj.tie(&wcout.stream_obj);
#endif
}

StreamInitializer::~StreamInitializer() {
  cout.stream_obj.flush();
  clog.stream_obj.flush();
#if _LIBCPP_HAS_WIDE_CHARACTERS
  wcout.stream_obj.flush();
  wclog.stream_obj.flush();
#endif
}

ios_base::Init::Init() {
  static StreamInitializer init_streams; // gets initialized once
}

