#include "llvm/Analysis/SyntheticCountsUtils.h"
#include "llvm/ADT/DenseSet.h"
#include "llvm/ADT/SCCIterator.h"
#include "llvm/Analysis/CallGraph.h"
#include "llvm/IR/ModuleSummaryIndex.h"

using namespace llvm;

// Propagate profile counts starting from a strongly connected component (SCC)
template <typename CallGraphType>
void SyntheticCountsUtils<CallGraphType>::propagateFromSCC(
    const SccTy &component, 
    GetProfCountTy getProfileCount, 
    AddCountTy accumulateCount) {

  DenseSet<NodeRef> nodesInComponent;
  SmallVector<std::pair<NodeRef, EdgeRef>, 8> internalEdges, externalEdges;

  // Identify all nodes belonging to this SCC
  for (const auto &node : component)
    nodesInComponent.insert(node);

  // Classify outgoing edges: those staying within the SCC vs. those leaving it
  for (const auto &node : nodesInComponent) {
    for (auto &edge : children_edges<CallGraphType>(node)) {
      NodeRef dest = CGT::edge_dest(edge);
      if (nodesInComponent.count(dest))
        internalEdges.emplace_back(node, edge);
      else
        externalEdges.emplace_back(node, edge);
    }
  }

  // Compute cumulative count contributions *within* the SCC in two phases:
  // Phase 1: Aggregate incoming contributions per node from intra-SCC edges
  // Phase 2: Apply aggregated updates — avoids dependency on traversal order
  DenseMap<NodeRef, Scaled64> deltaCounts;
  for (const auto &edge : internalEdges) {
    auto profOpt = getProfileCount(edge.first, edge.second);
    if (!profOpt)
      continue;
    NodeRef callee = CGT::edge_dest(edge.second);
    deltaCounts[callee] += *profOpt;
  }

  // Apply computed deltas to each node in the SCC
  for (const auto &item : deltaCounts)
    accumulateCount(item.first, item.second);

  // Finally, propagate counts along edges leading outside the SCC
  for (const auto &edge : externalEdges) {
    auto profOpt = getProfileCount(edge.first, edge.second);
    if (!profOpt)
      continue;
    NodeRef callee = CGT::edge_dest(edge.second);
    accumulateCount(callee, *profOpt);
  }
}

/// Distribute synthetic entry counts across the call graph \p CG.
///
/// Traverses SCCs in top-down order (reverse of bottom-up SCC iterator),
/// applying intra-SCC propagation first, then inter-SCC propagation.
/// Requires \p GraphTraits specialization for \p CallGraphType.
template <typename CallGraphType>
void SyntheticCountsUtils<CallGraphType>::propagate(
    const CallGraphType &graph,
    GetProfCountTy getProfileCount,
    AddCountTy accumulateCount) {

  std::vector<SccTy> sccList;
  // Gather all SCCs via reverse post-order collection
  for (auto iter = scc_begin(graph); !iter.isAtEnd(); ++iter)
    sccList.push_back(*iter);

  // Process SCCs from roots toward leaves (i.e., reverse bottom-up order)
  for (auto &scc : reverse(sccList))
    propagateFromSCC(scc, getProfileCount, accumulateCount);
}

// Explicit template instantiations
template class llvm::SyntheticCountsUtils<const CallGraph *>;
template class llvm::SyntheticCountsUtils<ModuleSummaryIndex *>;

#include <iostream>
#include <istream>
#include <ostream>
#include <string>
#include <asio/ip/tcp.hpp>
using asio::ip::tcp;

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 3)
    {
      std::cout << "Usage: http_client <server> <path>\n";
      std::cout << "Example:\n";
      std::cout << "  http_client www.boost.org /LICENSE_1_0.txt\n";
      return 1;
    }

    tcp::iostream connection_stream;
    // Set timeout for the entire operation to 60 seconds
    connection_stream.expires_after(std::chrono::seconds(60));

    // Connect to the specified server and service
    connection_stream.connect(argv[1], "http");

    if (!connection_stream)
    {
      std::cout << "Connection failed: " << connection_stream.error().message() << "\n";
      return 1;
    }

    // Build and send HTTP GET request
    connection_stream << "GET " << argv[2] << " HTTP/1.0\r\n";
    connection_stream << "Host: " << argv[1] << "\r\n";
    connection_stream << "Accept: */*\r\n";
    connection_stream << "Connection: close\r\n\r\n";

    // Read and validate HTTP response version
    std::string version_string;
    connection_stream >> version_string;

    unsigned int response_code;
    connection_stream >> response_code;

    std::string response_text;
    std::getline(connection_stream, response_text);

    // Verify response format and status
    if (!connection_stream || version_string.substr(0, 5) != "HTTP/")
    {
      std::cout << "Malformed HTTP response received\n";
      return 1;
    }

    if (response_code != 200)
    {
      std::cout << "HTTP error: " << response_code << " returned\n";
      return 1;
    }

    // Output headers until blank line is reached
    std::string header_line;
    while (std::getline(connection_stream, header_line) && header_line != "\r")
      std::cout << header_line << "\n";

    std::cout << "\n";

    // Output remaining body content directly from stream buffer
    std::cout << connection_stream.rdbuf();
  }
  catch (std::exception& ex)
  {
    std::cout << "Runtime error: " << ex.what() << "\n";
  }

  return 0;
}

