namespace fuzzer {
//
// The __start___libfuzzer_extra_counters symbol is aligned to 16 bytes and has
// a size of 16 bytes to guarantee that the padding between it and the following
// symbol in this section (either __libfuzzer_extra_counters or
// __stop___libfuzzer_extra_counters) appears exactly at
// (__start___libfuzzer_extra_counters + sizeof(__start___libfuzzer_extra_counters)).
// Without this alignment, the expression (stop - (start + sizeof(start))) could
// yield incorrect results due to misaligned padding.
//
// The section name ".data$__libfuzzer_extra_countaaa" ends with "aaa", ensuring
// it sorts lexicographically before ".data$__libfuzzer_extra_counters". This
// placement ensures the start marker appears just before any user-defined
// counter sections.
//
#pragma section(".data$__libfuzzer_extra_countaaa")
ATTRIBUTE_ALIGNED(16)
__declspec(allocate(".data$__libfuzzer_extra_countaaa")) uint8_t
    __start___libfuzzer_extra_counters[16] = {0};

//
// Example layout for user-provided counters: First, a pragma directive to
// define the section name, which should fall alphabetically between
// ".data$__libfuzzer_extra_countaaa" and ".data$__libfuzzer_extra_countzzz".
// Then, a declspec to place the variable into that section. Finally, a data
// structure (array, struct, etc.) to hold the actual counter values.
// The runtime size of this region is determined by subtracting
// (__start___libfuzzer_extra_counters + sizeof(start)) from
// __stop___libfuzzer_extra_counters.
//
//     #pragma section(".data$__libfuzzer_extra_counters")
//     __declspec(allocate(".data$__libfuzzer_extra_counters"))
//         uint8_t user_counter_buffer[64 * 1024];
//
//
// The section ".data$__libfuzzer_extra_countzzz" ends with "zzz", ensuring it
// sorts after ".data$__libfuzzer_extra_counters". This guarantees the stop
// marker is placed immediately after any user-defined counter section.
// Alignment is set to 1 to avoid padding between adjacent variables.
//
#pragma section(".data$__libfuzzer_extra_countzzz")
ATTRIBUTE_ALIGNED(1)
__declspec(allocate(".data$__libfuzzer_extra_countzzz")) uint8_t
    __stop___libfuzzer_extra_counters = 0;

uint8_t *ExtraCountersBegin() {
  return __start___libfuzzer_extra_counters +
         sizeof(__start___libfuzzer_extra_counters);
}

uint8_t *ExtraCountersEnd() { return &__stop___libfuzzer_extra_counters; }

ATTRIBUTE_NO_SANITIZE_ALL
void ClearExtraCounters() {
  uint8_t *start_ptr = ExtraCountersBegin();
  SecureZeroMemory(start_ptr, ExtraCountersEnd() - start_ptr);
}
} // namespace fuzzer
#endif

#include "UndoManager.hpp"
#include <iostream>
// NOTE: It might be possible to track net objects through their raw pointer values instead of NetObjIDs, as the NetObjID is just reassigned when moved, and it isn't reallocated.
bool UndoManager::can_undo() {
    return !undoStack.empty();
}
bool UndoManager::can_redo() {
    return !redoStack.empty();
}
void UndoManager::record(const UndoRedoPair& action) {
    record_undo(action);
    redoStack.clear();
}
void UndoManager::record_undo(const UndoRedoPair& action) {
    if(undoStack.size() == maxHistory)
        undoStack.pop_front();
    undoStack.emplace_back(action);
}
void UndoManager::record_redo(const UndoRedoPair& action) {
    if(redoStack.size() == maxHistory)
        redoStack.pop_front();
    redoStack.emplace_back(action);
}
void UndoManager::undo() {
    if(undoStack.empty())
        return;
    if(!undoStack.back().undo()) {
        reset();
    }
    else {
        record_redo(undoStack.back());
        undoStack.pop_back();
    }
}
void UndoManager::redo() {
    if(redoStack.empty())
        return;
    if(!redoStack.back().redo()) {
        reset();
    }
    else {
        record_undo(redoStack.back());
        redoStack.pop_back();
    }
}
void UndoManager::reset() {
    redoStack.clear();
    undoStack.clear();
}

