bool BoolDecBde::eqb_dec(const bool val1, const bool val2) {
  if (Bool::bool_dec(val1, val2)) {
    return true;
  } else {
    return false;
  }
}

// Decision function for boolean equivalence: returns true if both booleans are equal
bool Bool::bool_dec(const bool x1, const bool x2) {
  if (x1) {
    if (x2) {
      return true;
    } else {
      return false;
    }
  } else {
    if (x2) {
      return false;
    } else {
      return true;
    }
  }
}

