namespace tpa {

// Entry point for performing pointer analysis on a semi-sparse program.
//
// The process is divided into two main stages:
//
// Stage 1: Global Setup
// Leverages GlobalPointerAnalysis to inspect the module and identify global 
// variables and functions. Builds an initial Environment (Env) and Store that 
// reflect the effects of global initializers.
//
// Stage 2: Iterative Data-Flow Computation
// Initializes GlobalState (immutable context), then configures the DataFlowAnalysis 
// engine with appropriate components:
// - GlobalState: Provides shared context (program structure, type info, managers)
// - Memo: Caches intermediate results to avoid recomputation
// - TransferFunction: Computes effect of each program statement
// - SemiSparsePropagator: Controls how the analysis traverses control-flow graph
//
// Execution continues until no further changes occur (fixpoint).
void SemiSparsePointerAnalysis::runOnProgram(const SemiSparseProgram &ssProg) {
  LOG_INFO("Stage 1: Processing global pointers and initializers...");
  auto storeBuffer = Store();

  // Analyze globals and obtain initial environment and store.
  std::tie(env, storeBuffer) =
      GlobalPointerAnalysis(ptrManager, memManager, ssProg.getTypeMap())
          .runOnModule(ssProg.getModule());

  LOG_INFO("Global pointer analysis finished");
  LOG_INFO("Stage 2: Executing data-flow computation...");

  // Prepare global state object used by transfer functions.
  // Note: 'env' is passed by reference and gets updated during analysis.
  auto analysisContext = GlobalState(ptrManager, memManager, ssProg, extTable, env);

  // Set up the generic data-flow engine with our specific configuration.
  auto dfaEngine = util::DataFlowAnalysis<GlobalState, Memo, TransferFunction,
                                          SemiSparsePropagator>(analysisContext, memo);

  // Start fixpoint iteration from initial store derived from global initialization.
  dfaEngine.runOnInitialState<Initializer>(std::move(storeBuffer));
  LOG_INFO("Data-flow computation completed");
}

// Required implementation for CRTP base class method getPtsSetImpl.
// Retrieves precomputed points-to set from the final environment.
PtsSet SemiSparsePointerAnalysis::getPtsSetImpl(const Pointer *ptr) const {
  return env.lookup(ptr);
}

