namespace unravel
{
selection_action_t::selection_action_t(editing_manager* mgr,
                                       const std::vector<entt::meta_any>& prev_sel,
                                       const std::vector<entt::meta_any>& curr_sel, bool is_select)
    : manager(mgr), old_selection(prev_sel), new_selection(curr_sel), is_select(is_select)
{
    name = is_select ? "Select" : "Unselect";
    undoable = true;
}

void selection_action_t::do_action()
{
    if (!manager)
    {
        return;
    }
    // Apply the current selection state using the internal method
    manager->restore_selection_impl(new_selection);
}

void selection_action_t::undo_action()
{
    if (!manager)
    {
        return;
    }
    // Revert to the previous selection state using the internal method
    manager->restore_selection_impl(old_selection);
}

auto selection_action_t::is_mergeable(const editing_action_t& prior) const -> bool
{
    const auto& selection_action = static_cast<const selection_action_t&>(prior);
    if(selection_action.is_select != is_select)
    {
        return false;
    }
    // For consecutive selection operations (e.g., area-based picking), merge if:
    // The current action's old_selection aligns with the prior action's new_selection
    // indicating continuity from where the earlier operation ended

    // Handle cases involving empty selections
    if(old_selection.empty() && selection_action.new_selection.empty())
    {
        return true;
    }
    if(old_selection.size() != selection_action.new_selection.size())
    {
        return false;
    }
    // Verify that old_selection corresponds to prior new_selection (order-agnostic comparison)
    // This accommodates scenarios where entities are selected in varying sequences
    for(const auto& curr_old_item : old_selection)
    {
        bool match_found = false;
        for(const auto& prev_new_item : selection_action.new_selection)
        {
            if(curr_old_item == prev_new_item)
            {
                match_found = true;
                break;
            }
        }
        if(!match_found)
        {
            return false;
        }
    }
    return true;
}

void selection_action_t::merge_with(const editing_action_t& prior)
{
    // Upon merging, retain the old_selection from the earlier action
    // and preserve the new_selection from the current action (representing the most recent state)
    const auto& selection_action = static_cast<const selection_action_t&>(prior);
    old_selection = selection_action.old_selection;
    // new_selection remains unchanged (it reflects the latest condition)
}

auto selection_action_t::is_valid() const -> bool
{
    return manager != nullptr;
}
