#include "ConstrainedMeshSmoothers.h"
#include "MatrixSolver.h"
#include "ConstrainedPoissonSolver.h"

bool FBiHarmonicMeshSmoother::ComputeSmoothedMeshPositions(TArray<FVector3d>& OutPositions)
{
    UpdateSolverConstraints();

    // Construct the right-hand side vector for the biharmonic system
    FSOAPositions RHSVector(InternalVertexCount);

    if (InternalVertexCount != VertexCount) // boundary vertices present
    {
        for (int32 axis = 0; axis < 3; ++axis)
        {
            RHSVector.Array(axis) = BoundaryOperator * BoundaryPositions.Array(axis);
        }
    }
    else
    {
        RHSVector.ZeroInitialize();
    }

    // Prepare storage for solution
    FSOAPositions SolutionVec(InternalVertexCount);

    // Solve the constrained optimization problem
    bool bSolvedSuccessfully = ConstrainedSolver->Solve(RHSVector, SolutionVec);

    // Apply post-fix constraints if any
    UpdateWithPostFixConstraints(SolutionVec);

    // Prepare output buffer
    const int32 MaxVertexIndex = VtxLinearization.ToId().Num();
    OutPositions.Reset(MaxVertexIndex);
    OutPositions.SetNumUninitialized(MaxVertexIndex);

    // Populate internal vertex positions from solution
    CopyInternalPositions(SolutionVec, OutPositions);

    // Fill in boundary vertex positions
    CopyBoundaryPositions(OutPositions);

    return bSolvedSuccessfully;
}

bool FCGBiHarmonicMeshSmoother::ComputeSmoothedMeshPositions(TArray<FVector3d>& OutPositions)
{
    UpdateSolverConstraints();

    // Build source term for CG-based smoothing
    FSOAPositions RHSVector(InternalVertexCount);

    if (InternalVertexCount != VertexCount) // boundary nodes exist
    {
        for (int32 dim = 0; dim < 3; ++dim)
        {
            RHSVector.Array(dim) = BoundaryOperator * BoundaryPositions.Array(dim);
        }
    }
    else
    {
        RHSVector.SetZero(InternalVertexCount);
    }

    // Allocate space for computed solution
    FSOAPositions SolutionVec(InternalVertexCount);

    // Perform constrained solve
    bool bSolvedSuccessfully = ConstrainedSolver->Solve(RHSVector, SolutionVec);

    // Enforce additional positional constraints
    UpdateWithPostFixConstraints(SolutionVec);

    // Resize output array to accommodate all vertices
    const int32 MaxVertexIndex = VtxLinearization.ToId().Num();
    OutPositions.Empty(MaxVertexIndex);
    OutPositions.AddUninitialized(MaxVertexIndex);

    // Transfer internal vertex data into final layout
    CopyInternalPositions(SolutionVec, OutPositions);

    // Restore boundary vertex values
    CopyBoundaryPositions(OutPositions);

    return bSolvedSuccessfully;
}

