#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>

/**
 * @brief Sends a query to the judge and returns the response.
 * 
 * @param sliceIdx The slice number to toggle.
 * @return int The number of distinct mineral kinds in the device.
 */
int sendQuery(int sliceIdx) {
    std::cout << "? " << sliceIdx << std::endl;
    int result;
    std::cin >> result;
    if (result == -1) exit(0); // Exit if judge reports an error
    return result;
}

/**
 * @brief Announces a found pair to the judge.
 * 
 * @param firstSlice The first slice in the pair.
 * @param secondSlice The second slice in the pair.
 */
void reportPair(int firstSlice, int secondSlice) {
    std::cout << "! " << firstSlice << " " << secondSlice << std::endl;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::cin >> n;

    std::vector<bool> isPaired(2 * n + 1, false);
    std::vector<int> unmatchedSlices;
    int currentKindCount = 0;

    for (int idx = 1; idx <= 2 * n; ++idx) {
        if (isPaired[idx]) {
            continue;
        }

        int newKindCount = sendQuery(idx);

        if (newKindCount > currentKindCount) {
            // This is a "starter" slice of a new kind.
            unmatchedSlices.push_back(idx);
            currentKindCount = newKindCount;
        } else { 
            // This is a "finisher" slice. Its pair is in unmatchedSlices.
            int targetKindCount = newKindCount;

            // Linearly scan unmatchedSlices to find the pair.
            // Scanning from the end is often a good heuristic.
            for (int pos = unmatchedSlices.size() - 1; pos >= 0; --pos) {
                int candidate = unmatchedSlices[pos];
                int testResult = sendQuery(candidate);

                if (testResult == targetKindCount) {
                    // Found the pair: (idx, candidate).
                    // Removing candidate did not change the number of kinds, because idx has the same kind.
                    reportPair(idx, candidate);
                    isPaired[idx] = true;
                    isPaired[candidate] = true;

                    unmatchedSlices.erase(unmatchedSlices.begin() + pos);
                    currentKindCount = testResult;
                    break;
                } else {
                    // Not a pair. Put candidate back into the device to restore the state for the next check.
                    sendQuery(candidate);
                }
            }
        }
    }

    return 0;
}

#include "ReduceFunctionBodies.h"
