    }
#endif

    // Allocate and format the complete message for crash reporting or logging
    // Memory is intentionally leaked as program termination follows immediately
#if defined(_LIBCXXABI_USE_CRASHREPORTER_CLIENT)
    char* msg_buffer;
    va_list ap;
    va_start(ap, fmt);
    vasprintf(&msg_buffer, fmt, ap);
    va_end(ap);
    CRSetCrashLogMessage(msg_buffer);
#elif defined(__BIONIC__)
    char* log_buffer;
    va_list arglist;
    va_start(arglist, fmt);
    vasprintf(&log_buffer, fmt, arglist);
    va_end(arglist);

    // Ensure the message appears in tombstone logs
    android_set_abort_message(log_buffer);

    // Also send to system log
    openlog("libc++abi", 0, 0);
    syslog(LOG_CRIT, "%s", log_buffer);
    closelog();
#endif // __BIONIC__
    abort();
}

#include <iostream>
#include <vector>
#include <utility>
#include <algorithm>

// Global variables for board size and state
int SIZE;
// Using 1-based indexing for convenience to match problem statement.
// Global arrays are zero-initialized, which works perfectly for 'unvisited'.
int grid[667][667]; 
// Knight's move offsets (8 directions, ordered clockwise)
const int dx[] = {-2, -1, 1, 2, 2, 1, -1, -2};
const int dy[] = {1, 2, 2, 1, -1, -2, -2, -1};
// Check if a square (x, y) is on the board and unvisited.
// Inlining can give a minor performance boost.
inline bool inBounds(int x, int y) {
    return x >= 1 && x <= SIZE && y >= 1 && y <= SIZE && grid[x][y] == 0;
}
// Calculate the number of available moves from a square (Warnsdorff's rule).
// This is the 'degree' of the vertex in the graph of unvisited squares.
int countOptions(int x, int y) {
    int cnt = 0;
    for (int k = 0; k < 8; ++k) {
        if (inBounds(x + dx[k], y + dy[k])) {
            cnt++;
        }
    }
    return cnt;
}

int main() {
    // Use fast I/O
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);
    int begin_x, begin_y;
    std::cin >> SIZE >> begin_x >> begin_y;
    // `route` will store the sequence of visited squares.
    std::vector<std::pair<int, int>> route;

    // Set the starting position.
    int cur_x = begin_x;
    int cur_y = begin_y;
    // Mark the starting square as visited (step 1).
    grid[cur_x][cur_y] = 1;
    route.push_back({cur_x, cur_y});
    // Generate the rest of the path, up to SIZE*SIZE-1 more moves.
    for (int step = 2; step <= SIZE * SIZE; ++step) {
        int next_x = -1;
        int next_y = -1;
        // Max possible degree is 8, so 9 is a safe initial value for min_options.
        int min_options = 9;
        // Apply Warnsdorff's rule: find the next move that has the minimum number of onward moves.
        for (int k = 0; k < 8; ++k) {
            int nx = cur_x + dx[k];
            int ny = cur_y + dy[k];
            if (inBounds(nx, ny)) {
                int options = countOptions(nx, ny);
                if (options < min_options) {
                    min_options = options;
                    next_x = nx;
                    next_y = ny;
                }
            }
        }
        // If next_x is -1, it means we are stuck and cannot make any more moves.
        if (next_x == -1) {
            break; 
        }
        // Make the chosen move.
        cur_x = next_x;
        cur_y = next_y;
        grid[cur_x][cur_y] = step;
        route.push_back({cur_x, cur_y});
    }
    // Output the length of the route found.
    std::cout << route.size() << "\n";
    // Output the coordinates of each square in the route.
    for (const auto& pt : route) {
        std::cout << pt.first << " " << pt.second << "\n";
    }
    return 0;
}

