using namespace stepit;

int main(int argc, char **argv) {
  if (argc != 2) {
    std::cerr << "Usage: " << argv[0] << " <data_file>" << std::endl;
    return 1;
  }
  try {
    NpzReader npz(argv[1]);
    std::size_t max_key_width       = 4;
    std::size_t max_dims_width      = 5;
    std::vector<std::string> keys   = npz.keys();
    std::vector<std::string> dims_strs;
    std::vector<std::string> type_strs;

    for (const auto &key : keys) {
      max_key_width = std::max(max_key_width, key.length());
      dims_strs.push_back(fmt::format("({})", fmt::join(npz[key].shape, ", ")));
      max_dims_width = std::max(max_dims_width, dims_strs.back().length());
      type_strs.push_back(npz[key].dtype);
    }

    max_key_width += 2;
    max_dims_width += 2;

    std::cout << fmt::format("{:<{}}{:<{}}{}\n", "Key", max_key_width, "Dims", max_dims_width, "Type")
              << std::string(max_key_width + max_dims_width + 15, '-') << std::endl;

    for (std::size_t idx{}; idx < keys.size(); ++idx) {
      std::cout << fmt::format("{:<{}}{:<{}}{}", keys[idx], max_key_width, dims_strs[idx], max_dims_width, type_strs[idx])
                << std::endl;
    }
  } catch (const std::exception &err) {
    std::cerr << kRed << "ERROR: " << kClear << err.what() << std::endl;
    return 1;
  }
  return 0;
}

