#include <vector>
using namespace std;

class Solution {
public:
    // Generate Pascal's Triangle with specified number of rows
    vector<vector<int>> generate(int numRows) {
        vector<vector<int>> triangle;
        triangle.push_back({1});

        for(int rowIndex = 1; rowIndex < numRows; rowIndex++) {
            vector<int> row;
            row.push_back(1);

            for(int colIndex = 1; colIndex < triangle.back().size(); colIndex++) {
                row.push_back(triangle.back()[colIndex] + triangle.back()[colIndex - 1]);
            }

            row.push_back(1);
            triangle.push_back(row);
        }

        return triangle;
    }
};

