namespace http {
namespace server3 {

server::server(const std::string& host, const std::string& port_str,
    const std::string& doc_directory, std::size_t num_threads)
  : thread_pool_size_(num_threads),
    signals_(io_context_),
    acceptor_(io_context_),
    new_connection_(),
    request_handler_(doc_directory)
{
  // Register signal handlers for graceful shutdown
  // Asio allows multiple registrations for the same signal
  signals_.add(SIGINT);
  signals_.add(SIGTERM);
#if defined(SIGQUIT)
  signals_.add(SIGQUIT);
#endif // defined(SIGQUIT)

  signals_.async_wait(boost::bind(&server::handle_stop, this));

  // Configure and bind the acceptor
  asio::ip::tcp::resolver resolver(io_context_);
  asio::ip::tcp::endpoint endpoint =
    *resolver.resolve(host, port_str).begin();

  acceptor_.open(endpoint.protocol());
  acceptor_.set_option(asio::ip::tcp::acceptor::reuse_address(true));
  acceptor_.bind(endpoint);
  acceptor_.listen();

  start_accept();
}

void server::run()
{
  // Create a thread pool to process I/O operations
  std::vector<boost::shared_ptr<asio::thread> > worker_threads;
  for (std::size_t i = 0; i < thread_pool_size_; ++i)
  {
    boost::shared_ptr<asio::thread> thread(new asio::thread(
          boost::bind(&asio::io_context::run, &io_context_)));
    worker_threads.push_back(thread);
  }

  // Wait for all threads to complete
  for (std::size_t i = 0; i < worker_threads.size(); ++i)
    worker_threads[i]->join();
}

void server::start_accept()
{
  new_connection_.reset(new connection(io_context_, request_handler_));
  acceptor_.async_accept(new_connection_->socket(),
      boost::bind(&server::handle_accept, this,
        asio::placeholders::error));
}

void server::handle_accept(const asio::error_code& ec)
{
  if (!ec)
  {
    new_connection_->start();
  }
  start_accept();
}

void server::handle_stop()
{
  io_context_.stop();
}

