#include <iostream>

// Function to query a range and obtain the response
int query(int left, int right) {
    std::cout << "? " << left << " " << right << std::endl;
    int answer;
    std::cin >> answer;
    return answer;
}

void process() {
    int size;
    std::cin >> size;

    // Step 1: Locate reference element (position of 'size-1')
    // and decide whether 'size' lies left or right of it.
    int ref = query(1, size);
    int low, high;
    bool ref_on_left;

    if (ref < size && query(ref, size) == ref) {
        // 'size' is located in [ref+1, size], so reference is on the left side
        low = ref + 1;
        high = size;
        ref_on_left = true;
    } else {
        // 'size' is located in [1, ref-1], so reference is on the right side
        low = 1;
        high = ref - 1;
        ref_on_left = false;
    }

    // Step 2: Perform binary search to pinpoint exact position of 'size'
    while (low < high) {
        int mid = low + (high - low) / 2;

        if (ref_on_left) {
            // Reference is left of current segment. Check if 'size' is in [low, mid]
            // Query [ref, mid] includes 'size' iff target position is within [low, mid]
            if (query(ref, mid) == ref) {
                high = mid;
            } else {
                low = mid + 1;
            }
        } else {
            // Reference is right of current segment. Check if 'size' is in [mid+1, high]
            // Query [mid+1, ref] includes 'size' iff target position is within [mid+1, high]
            if (query(mid + 1, ref) == ref) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
    }

    std::cout << "! " << low << std::endl;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int test_cases;
    std::cin >> test_cases;

    while (test_cases--) {
        process();
    }

    return 0;
}

