#include <iostream>
#include <vector>
#include <algorithm>
#include <random>
using namespace std;

// Problem constraint: n * m <= 100000
// By enforcing rows <= columns, we ensure rows <= sqrt(100000) ≈ 316
// Using a slightly larger bound for safety
const int MAX_ROWS = 350;

// track[i][j] = true if rows i and j have been paired in any previous column
bool track[MAX_ROWS][MAX_ROWS];

// conflict_count[i] = number of rows that row i has already been paired with
int conflict_count[MAX_ROWS];

struct Coordinate {
    int row_idx;
    int col_idx;
};

int main() {
    // Speed up I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int input_rows, input_cols;
    if (!(cin >> input_rows >> input_cols)) return 0;

    bool dimensions_swapped = false;
    int rows = input_rows;
    int cols = input_cols;

    // Ensure rows <= cols to optimize the greedy selection process
    if (rows > cols) {
        swap(rows, cols);
        dimensions_swapped = true;
    }

    // Initialize RNG with fixed seed for deterministic behavior
    mt19937 engine(42);

    // Create list of row indices [0, 1, ..., rows-1]
    vector<int> row_list(rows);
    for (int i = 0; i < rows; ++i) {
        row_list[i] = i;
    }

    vector<Coordinate> solution;

    // Process each column
    for (int current_col = 0; current_col < cols; ++current_col) {
        // Randomize row order to avoid bias
        shuffle(row_list.begin(), row_list.end(), engine);

        // Sort rows by conflict count (ascending) — prefer less constrained rows
        stable_sort(row_list.begin(), row_list.end(), [&](int r1, int r2) {
            return conflict_count[r1] < conflict_count[r2];
        });

        vector<int> selected_rows_for_this_column;

        // Greedy selection: pick rows that don't conflict with already-selected ones
        for (int candidate_row : row_list) {
            bool can_use = true;
            for (int used_row : selected_rows_for_this_column) {
                if (track[candidate_row][used_row]) {
                    can_use = false;
                    break;
                }
            }
            if (can_use) {
                selected_rows_for_this_column.push_back(candidate_row);
            }
        }

        // Record chosen points and update constraints
        for (size_t i = 0; i < selected_rows_for_this_column.size(); ++i) {
            int r1 = selected_rows_for_this_column[i];
            solution.push_back({r1 + 1, current_col + 1});

            for (size_t j = i + 1; j < selected_rows_for_this_column.size(); ++j) {
                int r2 = selected_rows_for_this_column[j];
                track[r1][r2] = true;
                track[r2][r1] = true;
                conflict_count[r1]++;
                conflict_count[r2]++;
            }
        }
    }

    // Output total number of points
    cout << solution.size() << "\n";

    // Output coordinates
    for (const auto& coord : solution) {
        if (dimensions_swapped) {
            cout << coord.col_idx << " " << coord.row_idx << "\n";
        } else {
            cout << coord.row_idx << " " << coord.col_idx << "\n";
        }
    }

    return 0;
}

