	Date RetrieveDate(const std::string& statIdentifier)
	{
		Date outputDate{};
		TransformMPX(statIdentifier);
		STATS::STAT_GET_DATE(Joaat(statIdentifier), &outputDate, SCR_SIZEOF(Date), -1);
		return outputDate;
	}

	const char* RetrieveString(const std::string& statIdentifier)
	{
		TransformMPX(statIdentifier);
		return STATS::STAT_GET_STRING(Joaat(statIdentifier), -1); // The native is null-safe
	}

	void AssignPackedBool(int slotIndex, bool flag)
	{
		STATS::SET_PACKED_STAT_BOOL_CODE(slotIndex, flag, -1);
	}

	void AssignPackedInt(int slotIndex, int number)
	{
		STATS::SET_PACKED_STAT_INT_CODE(slotIndex, number, -1);
	}

	bool FetchPackedBool(int slotIndex)
	{
		return STATS::GET_PACKED_STAT_BOOL_CODE(slotIndex, -1);
	}

	int FetchPackedInt(int slotIndex)
	{
		return STATS::GET_PACKED_STAT_INT_CODE(slotIndex, -1);
	}
}

