namespace {
// Singleton to initialize MLIR environment once
class MLIRInitializer {
public:
    static MLIRInitializer& get() {
        static MLIRInitializer instance;
        return instance;
    }
    mlir::DialectRegistry& get_registry() { return registry_; }

private:
    MLIRInitializer() {
        // Initialize all standard MLIR dialects
        mlir::registerAllDialects(registry_);
        // Register all built-in passes
        mlir::registerAllPasses();
        // Setup SDFG-specific components
        ::sdfg::codegen::register_default_dispatchers();
        ::sdfg::serializer::register_default_serializers();
    }
    mlir::DialectRegistry registry_;
};

// Wrapper class for handling MLIR modules and conversion pipeline
class PyMLIRModule {
public:
    explicit PyMLIRModule(const std::string& input_text) {
        auto& init = MLIRInitializer::get();
        context_ = std::make_unique<mlir::MLIRContext>(init.get_registry());
        context_->loadAllAvailableDialects();
        module_ = mlir::parseSourceString<mlir::ModuleOp>(input_text, context_.get());
        if (!module_) {
            throw std::runtime_error("Error parsing MLIR source");
        }
    }

    std::string dump() {
        std::string output;
        llvm::raw_string_ostream stream(output);
        module_->print(stream);
        return output;
    }

    void apply_transforms() {
        mlir::PassManager manager(context_.get());
        manager.addPass(mlir::createLinalgSpecializeGenericOpsPass());
        if (mlir::failed(manager.run(*module_))) {
            throw std::runtime_error("Transformation pipeline failed");
        }
    }

    std::string export_sdfg() {
        std::string buffer;
        llvm::raw_string_ostream stream(buffer);
        if (mlir::failed(mlir::sdfg::translateToSDFG(module_->getOperation(), stream))) {
            throw std::runtime_error("SDFG translation failed");
        }
        return buffer;
    }

    mlir::Operation* get_root() { return module_->getOperation(); }

private:
    std::unique_ptr<mlir::MLIRContext> context_;
    mlir::OwningOpRef<mlir::ModuleOp> module_;
};
} // anonymous namespace

PYBIND11_MODULE(_sdfg_mlir, module) {
    module.doc() = "Python bindings for MLIR-to-SDFG compilation pipeline";

    py::class_<PyMLIRModule>(module, "MLIRModule")
        .def(py::init<const std::string&>(), 
             py::arg("source"), 
             "Construct an MLIR module from textual representation")
        .def("dump", &PyMLIRModule::dump, 
             "Return the string representation of the MLIR module")
        .def("apply_transforms", &PyMLIRModule::apply_transforms, 
             "Apply Linalg specialization transformations")
        .def("export_sdfg", &PyMLIRModule::export_sdfg, 
             "Convert the module to serialized SDFG format");
}

