static void glewPrintExtensionInfo (const char* extensionName, GLboolean status1, GLboolean status2, GLboolean status3)
{
  unsigned int index;
  fprintf(logFile, "\n%s:", extensionName);
  for (index=0; index<62-strlen(extensionName); index++) fprintf(logFile, " ");
  fprintf(logFile, "%s ", status1 ? "OK" : "MISSING");

  if (status1 != status2)
    fprintf(logFile, "[%s] ", status2 ? "OK" : "MISSING");

  if (status1 != status3)
    fprintf(logFile, "[%s]\n", status3 ? "OK" : "MISSING");
  else
    fprintf(logFile, "\n");

  for (index=0; index<strlen(extensionName)+1; index++) fprintf(logFile, "-");
  fprintf(logFile, "\n");
  fflush(logFile);
}

static void glewLogFunctionInfo (const char* functionName, GLint isUndefined)
{
  unsigned int index;
  fprintf(logFile, "  %s:", functionName);
  for (index=0; index<60-strlen(functionName); index++) fprintf(logFile, " ");
  fprintf(logFile, "%s\n", isUndefined ? "MISSING" : "OK");
  fflush(logFile);
}

