/*----------------------------------------------------------------------------------------------------------------------
|	Duplicates the content of 'text' into the exception message and stores the current parsing location: line number,
|	column number, and file position.
*/
NxsException::NxsException(
  const NxsString &text,	/* the error description to present to the user */
  file_pos pos_in,			/* the file position at error occurrence */
  long line_num,			/* the current line index in the file */
  long col_num)				/* the current column index in the file */
	{
	pos		= pos_in;
	line	= line_num;
	col		= col_num;
	msg		= text;
	}
/*----------------------------------------------------------------------------------------------------------------------
|	Constructs a NxsException instance using the provided error description, extracting location data from the token.
*/
NxsException::NxsException(
  const NxsString &description,	/* descriptive message of the error */
  const NxsToken &token)		/* NxsToken holding the last parsed token (triggering the exception) */
	{
	msg		= description; 
	pos		= token.GetFilePosition();
	line	= token.GetFileLine();
	col		= token.GetFileColumn();
  	}

