namespace roboplan {

using namespace nanobind::literals;

void bind_optimal_ik_module(nanobind::module_& mod) {
  // Bind base Task class
  nanobind::class_<Task>(mod, "Task", "Abstract base class for IK tasks.")
      .def_ro("alpha", &Task::gain, "Task gain for low-pass filtering.")
      .def_ro("w_cost", &Task::weight, "Weight matrix for cost normalization.")
      .def_ro("mu_damp", &Task::lm_damping, "Levenberg-Marquardt damping.")
      .def_ro("n_vars", &Task::num_variables, "Number of optimization variables.");

  // FrameTaskOptions binding
  nanobind::class_<FrameTaskOptions>(mod, "FrameTaskOptions", "Parameters for FrameTask.")
      .def(nanobind::init<double, double, double, double>(), "pos_weight"_a = 1.0,
           "ori_weight"_a = 1.0, "tau_gain"_a = 1.0, "damp_param"_a = 0.0)
      .def_rw("pos_weight", &FrameTaskOptions::position_cost, "Position cost weight.")
      .def_rw("ori_weight", &FrameTaskOptions::orientation_cost, "Orientation cost weight.")
      .def_rw("tau_gain", &FrameTaskOptions::task_gain, "Task gain for low-pass filtering.")
      .def_rw("damp_param", &FrameTaskOptions::lm_damping, "Levenberg-Marquardt damping.");

  // FrameTask binding
  nanobind::class_<FrameTask, Task>(mod, "FrameTask",
                                    "Task to reach a target pose for a specified frame.")
      .def(nanobind::init<const CartesianConfiguration&, int, const FrameTaskOptions&>(),
           "pose_desired"_a, "n_dof"_a, "cfg"_a = FrameTaskOptions{})
      .def_ro("link_name", &FrameTask::frame_name, "Name of the frame to control.")
      .def_ro("link_idx", &FrameTask::frame_id,
              "Index of the frame in the scene's Pinocchio model.")
      .def_ro("goal_pose", &FrameTask::target_pose, "Target pose for the frame.")
      .def("setGoalTransform", &FrameTask::setTargetFrameTransform,
           "Sets the target transform for this frame task.");

  // ConfigurationTaskOptions binding
  nanobind::class_<ConfigurationTaskOptions>(mod, "ConfigurationTaskOptions",
                                             "Parameters for ConfigurationTask.")
      .def(nanobind::init<double, double>(), "eta"_a = 1.0, "eps"_a = 0.0)
      .def_rw("eta", &ConfigurationTaskOptions::task_gain,
              "Task gain for low-pass filtering.")
      .def_rw("eps", &ConfigurationTaskOptions::lm_damping, "Levenberg-Marquardt damping.");

  // ConfigurationTask binding
  nanobind::class_<ConfigurationTask, Task>(mod, "ConfigurationTask",
                                            "Task to reach a target joint configuration.")
      .def(nanobind::init<const Eigen::VectorXd&, const Eigen::VectorXd&,
                          const ConfigurationTaskOptions&>(),
           "q_ref"_a, "jnt_weights"_a, "opts"_a = ConfigurationTaskOptions{})
      .def_rw("q_ref", &ConfigurationTask::target_q, "Target joint configuration.")
      .def_rw("jnt_weights", &ConfigurationTask::joint_weights,
              "Weights for each joint in the configuration task.");

  // Constraints base class
  nanobind::class_<Constraints>(mod, "Constraints", "Abstract base class for IK constraints.");

  // PositionLimit constraint
  nanobind::class_<PositionLimit, Constraints>(mod, "PositionLimit",
                                               "Constraint to enforce joint position limits.")
      .def(nanobind::init<int, double>(), "n_dof"_a, "rho"_a = 1.0)
      .def_rw("rho_pos", &PositionLimit::config_limit_gain,
              "Gain for position limit enforcement.");

  // VelocityLimit constraint
  nanobind::class_<VelocityLimit, Constraints>(mod, "VelocityLimit",
                                               "Constraint to enforce joint velocity limits.")
      .def(nanobind::init<int, double, const Eigen::VectorXd&>(), "n_dof"_a, "h"_a,
           "v_max_vec"_a)
      .def_rw("h", &VelocityLimit::dt, "Time step for velocity calculation.")
      .def_rw("v_max_vec", &VelocityLimit::v_max, "Maximum joint velocities.");

  // Oink solver binding
  nanobind::class_<Oink>(mod, "Oink", "Optimal Inverse Kinematics solver.")
      .def(nanobind::init<int>(), "n_dof"_a)
      .def(
          "compute_joint_velocity",
          [](Oink& self, const std::vector<std::shared_ptr<Task>>& task_list,
             const std::vector<std::shared_ptr<Constraints>>& constraint_list,
             const std::shared_ptr<Scene>& world_scene, nanobind::DRef<Eigen::VectorXd> dq_out,
             double reg_strength) {
            auto solution = self.solveIk(task_list, constraint_list, *world_scene, dq_out, reg_strength);
            if (!solution.has_value()) {
              throw std::runtime_error("IK solve failed: " + solution.error());
            }
          },
          "tasks"_a, "constraints"_a, "scene"_a, "delta_q"_a, "reg_factor"_a = 1e-12,
          "Solve inverse kinematics for given tasks and constraints.\n\n"
          "Solves a QP optimization problem to compute the joint velocity that minimizes\n"
          "weighted task errors while satisfying all constraints. The result is written\n"
          "directly into the provided delta_q buffer.\n\n"
          "Args:\n"
          "    tasks: List of weighted tasks to optimize for.\n"
          "    constraints: List of constraints to satisfy.\n"
          "    scene: Scene containing robot model and state.\n"
          "    delta_q: Pre-allocated numpy array for output (size = num_variables).\n"
          "             Must be a contiguous float64 array. Modified in-place.\n"
          "    reg_factor: Tikhonov regularization weight for the QP Hessian.\n"
          "                Higher values improve numerical stability but may reduce\n"
          "                task tracking accuracy. Default: 1e-12.\n\n"
          "Raises:\n"
          "    RuntimeError: If the QP solver fails to find a solution.\n\n"
          "Example:\n"
          "    delta_q = np.zeros(oink.num_variables)\n"
          "    oink.compute_joint_velocity(tasks, constraints, scene, delta_q)");
}

