#define DEBUG_TYPE "valuesymtab"

// Class destructor
ValueSymbolTable::~ValueSymbolTable() {
#ifndef NDEBUG // Only perform cleanup checks in debug builds...
  for (const auto &entry : vmap)
    dbgs() << "Value still present in symbol table! Type = '"
           << *entry.getValue()->getType() << "' Name = '" << entry.getKeyData()
           << "'\n";
  assert(vmap.empty() && "Some values remain in the symbol table!");
#endif
}

ValueName *ValueSymbolTable::makeUniqueName(Value *val,
                                            SmallString<256> &buffer) {
  unsigned prefixLen = buffer.size();
  while (true) {
    // Truncate to original prefix length and append next unique suffix.
    buffer.resize(prefixLen);
    raw_svector_ostream OS(buffer);

    if (auto *GV = dyn_cast<GlobalValue>(val)) {
      const Module *mod = GV->getParent();
      if (mod) {
        Triple target(mod->getTargetTriple());
        // Append dot separator on most targets, but avoid it on NVPTX due to PTX syntax restrictions.
        if (!target.isNVPTX())
          OS << ".";
      }
    }

    OS << ++LastUnique;

    // Attempt insertion with new suffix.
    auto [iter, success] = vmap.insert(std::make_pair(buffer.str(), val));
    if (success)
      return &*iter;
  }
}

// Reinsert a value into the symbol table, renaming if necessary.
void ValueSymbolTable::reinsertValue(Value *val) {
  assert(val->hasName() && "Cannot insert a nameless Value into the symbol table");

  // Try inserting directly first.
  if (vmap.insert(val->getValueName())) {
    // Insertion succeeded; nothing more to do.
    return;
  }

  // Conflict detected: rename the value.
  SmallString<256> candidateName(val->getName().begin(), val->getName().end());

  // Free old name to allow reuse of memory.
  MallocAllocator allocator;
  val->getValueName()->Destroy(allocator);

  ValueName *newName = makeUniqueName(val, candidateName);
  val->setValueName(newName);
}

void ValueSymbolTable::removeValueName(ValueName *name) {
  // Remove the entry from internal map.
  vmap.remove(name);
}

/// createValueName - Attempts to create and insert a named entry into the symbol table.
/// If the requested name is already taken, auto-renames and returns the new name.
ValueName *ValueSymbolTable::createValueName(StringRef name, Value *val) {
  // Enforce maximum name size limit if configured.
  if (MaxNameSize > -1 && name.size() > static_cast<unsigned>(MaxNameSize))
    name = name.substr(0, std::max(1u, static_cast<unsigned>(MaxNameSize)));

  // Common case: no conflict, insert directly.
  auto [iter, inserted] = vmap.insert(std::make_pair(name, val));
  if (inserted)
    return &*iter;

  // Conflict occurred: generate a unique variant.
  SmallString<256> base(name.begin(), name.end());
  return makeUniqueName(val, base);
}

#if !defined(NDEBUG) || defined(LLVM_ENABLE_DUMP)
// dump - print out the contents of the symbol table for debugging.
LLVM_DUMP_METHOD void ValueSymbolTable::dump() const {
  for (const auto &item : *this) {
    item.getValue()->dump();
  }
}
#endif

