namespace common {

std::string ExceptionMessage::duplicatePKException(const std::string& pkValue) {
    return std::format("Duplicate primary key value {} detected, breaching the uniqueness "
                       "requirement for primary key columns.",
        pkValue);
}

std::string ExceptionMessage::nonExistentPKException(const std::string& pkValue) {
    return std::format("Primary key value {} could not be located.", pkValue);
}

std::string ExceptionMessage::invalidPKType(const std::string& dataType) {
    return std::format("Unsupported primary key column type {}. Primary keys must be either STRING "
                       "or a numeric data type.",
        dataType);
}

std::string ExceptionMessage::nullPKException() {
    return "Encountered NULL value, violating the NOT NULL constraint on the primary key column.";
}

std::string ExceptionMessage::overLargeStringPKValueException(uint64_t size) {
    return std::format("The maximum allowed length for primary key strings is 262144 bytes. The "
                       "provided string exceeded this limit with a length of {}.",
        size);
}

std::string ExceptionMessage::overLargeStringValueException(uint64_t size) {
    return std::format(
        "The maximum allowed length for strings is 262144 bytes. The provided string had a length "
        "of {}.",
        size);
}

std::string ExceptionMessage::violateDeleteNodeWithConnectedEdgesConstraint(
    const std::string& tableName, const std::string& nodeOffset, const std::string& edgeDirection) {
    return std::format(
        "Node(nodeOffset: {}) cannot be deleted because it has connected edges in table {} in the "
        "{} direction. Please remove the associated edges first or use DETACH DELETE.",
        nodeOffset, tableName, edgeDirection);
}

std::string ExceptionMessage::violateRelMultiplicityConstraint(const std::string& tableName,
    const std::string& nodeOffset, const std::string& edgeDirection) {
    return std::format("Node(nodeOffset: {}) has multiple neighbors in table {} in the {} "
                       "direction, contravening the relationship multiplicity rule.",
        nodeOffset, tableName, edgeDirection);
}

std::string ExceptionMessage::variableNotInScope(const std::string& varName) {
    return std::format("Variable {} is undefined in the current scope.", varName);
}

std::string ExceptionMessage::listFunctionIncompatibleChildrenType(const std::string& funcName,
    const std::string& leftType, const std::string& rightType) {
    return std::string("Unable to bind function " + funcName + " due to incompatible parameter "
                       "types: " + leftType + " and " + rightType + ".");
}

std::string ExceptionMessage::invalidSkipLimitParam(const std::string& expressionName,
    const std::string& clauseType) {
    return std::format("Expression {} cannot be interpreted as a valid {} value.", expressionName,
        clauseType);
}

} // namespace common
} // namespace lbug

