#include <iostream>
#include <vector>
#include <cmath>
#include <sm/vec>
#include <sm/vvec>
#include <sm/grid>
#include <sm/hexgrid>
#include <mplot/loadpng.h>
#include <mplot/Visual.h>
#include <mplot/VisualDataModel.h>
#include <mplot/GridVisual.h>
#include <mplot/HexGridVisual.h>

int main() {
    // Create visualization window with custom dimensions and title
    mplot::Visual viewer(1400, 1300, "Demonstration: Grid-based Image Resampling");

    // Set camera position for scene view
    viewer.setSceneTrans(sm::vec<float, 3>({-2.60691f, 1.39885f, -11.1f}));

    // Define grid resolution parameters
    unsigned int reductionFactor = 2U;
    sm::vec<float, 2> baseSpacing = { 0.02f, 0.02f };
    sm::vec<float, 2> coarserSpacing = baseSpacing * reductionFactor;

    // Construct original grid (g1) — top-left to bottom-right indexing matches PNG loading convention
    sm::grid originalGrid(256U, 64U, baseSpacing);
    std::cout << "Original grid extents (xmin,xmax,ymin,ymax): " << originalGrid.extents() << std::endl;

    // Construct resampled (coarser) grid (g2)
    sm::grid resampledGrid(256U / reductionFactor, 64U / reductionFactor, coarserSpacing);
    std::cout << "Resampled grid extents (xmin,xmax,ymin,ymax): " << resampledGrid.extents() << std::endl;

    // Load input image
    std::string imagePath = "../examples/bike256_64.png";
    sm::vvec<float> pixelBuffer; // stores image data in BLTR order
    sm::vec<unsigned int, 2> imageDimensions = mplot::loadpng(imagePath, pixelBuffer);
    std::cout << "Loaded image dimensions: " << imageDimensions << std::endl;

    // Validate image width
    if (imageDimensions[0] != 256U) {
        std::cerr << "Error: Unexpected image width.\n";
        return -1;
    }

    // Resample onto coarser grid
    sm::vec<float, 2> scaleFactors = {1.0f, 1.0f};
    sm::vec<float, 2> translationOffset = {0.0f, 0.0f};
    sm::vvec<float> resampledData = resampledGrid.resample_image(
        pixelBuffer, imageDimensions[0], scaleFactors, translationOffset);

    // Also resample onto hexagonal grid
    sm::vec<float, 2> g2_spacing = resampledGrid.get_dx();
    sm::hexgrid hexGrid(g2_spacing[0], resampledGrid.width() * 2.0f, 0.0f);
    hexGrid.setRectangularBoundary(resampledGrid.width(), resampledGrid.height());

    // Hexgrid-specific scaling to match visual extent
    sm::vec<float, 2> hexScale = { static_cast<float>(resampledGrid.width()), 
                                   static_cast<float>(resampledGrid.width()) };
    sm::vvec<float> hexResampledData = hexGrid.resampleImage(
        pixelBuffer, imageDimensions[0], hexScale, translationOffset);

    // Visualize original image on regular grid
    auto originalGV = std::make_unique<mplot::GridVisual<float>>(&originalGrid, sm::vec<float>({0, 0, 0}));
    viewer.bindmodel(originalGV);
    originalGV->gridVisMode = mplot::GridVisMode::RectInterp;
    originalGV->setScalarData(&pixelBuffer);
    originalGV->cm.setType(mplot::ColourMapType::GreyscaleInv);
    originalGV->zScale.null_scaling();
    originalGV->addLabel("Original", {0, -0.2, 0}, mplot::TextFeatures(0.1f));
    originalGV->finalize();
    viewer.addVisualModel(originalGV);

    // Visualize resampled image on coarser grid
    auto resampledGV = std::make_unique<mplot::GridVisual<float>>(
        &resampledGrid, sm::vec<float>{0.0f, -2.0f, 0.0f});
    viewer.bindmodel(resampledGV);
    resampledGV->gridVisMode = mplot::GridVisMode::RectInterp;
    resampledGV->setScalarData(&resampledData);
    resampledGV->cm.setType(mplot::ColourMapType::GreyscaleInv);
    resampledGV->zScale.null_scaling();
    resampledGV->addLabel("Resampled to Coarser Grid", {0, -0.2, 0}, mplot::TextFeatures(0.1f));
    resampledGV->finalize();
    viewer.addVisualModel(resampledGV);

    // Visualize hexgrid-resampled image
    auto hexGV = std::make_unique<mplot::HexGridVisual<float>>(
        &hexGrid, sm::vec<float>{static_cast<float>(resampledGrid.width()) / 2.0f,
                                  static_cast<float>(resampledGrid.height()) / 2.0f - 4.0f,
                                  0.0f});
    viewer.bindmodel(hexGV);
    hexGV->setScalarData(&hexResampledData);
    hexGV->cm.setType(mplot::ColourMapType::GreyscaleInv);
    hexGV->zScale.null_scaling();
    hexGV->addLabel("Resampled to Hex Grid", 
                    {-static_cast<float>(resampledGrid.width()) / 2.0f, 
                     -0.2f - static_cast<float>(resampledGrid.height()) / 2.0f, 
                     0}, 
                    mplot::TextFeatures(0.1f));
    hexGV->finalize();
    viewer.addVisualModel(hexGV);

    // Keep window open until user interaction
    viewer.keepOpen();
    return 0;
}

#include "llvm/IR/DiagnosticHandler.h"
#include "llvm/Support/CommandLine.h"
#include "llvm/Support/Regex.h"

using namespace llvm;

namespace {
/// Regular expression pattern used to filter passes for diagnostic emission
struct PassFilterConfig {
  std::shared_ptr<Regex> FilterPattern;

  void assign(const std::string &Input) {
    if (!Input.empty()) {
      FilterPattern = std::make_shared<Regex>(Input);
      std::string ErrorMsg;
      if (!FilterPattern->isValid(ErrorMsg))
        report_fatal_error(Twine("Invalid regex '") + Input +
                               "' in -pass-filter: " + ErrorMsg,
                           false);
    }
  }
};

static PassFilterConfig PassedFilterLoc;
static PassFilterConfig MissedFilterLoc;
static PassFilterConfig AnalysisFilterLoc;

// Command line option for optimization remarks
static cl::opt<PassFilterConfig, true, cl::parser<std::string>> PassFilter(
    "pass-filter", cl::value_desc("regex"),
    cl::desc("Activate optimization diagnostics from passes matching this regex"),
    cl::Hidden, cl::location(PassedFilterLoc), cl::ValueRequired);

// Command line option for missed optimization diagnostics
static cl::opt<PassFilterConfig, true, cl::parser<std::string>> PassFilterMissed(
    "pass-filter-missed", cl::value_desc("regex"),
    cl::desc("Activate missed optimization diagnostics from passes matching this regex"),
    cl::Hidden, cl::location(MissedFilterLoc), cl::ValueRequired);

// Command line option for analysis diagnostics
static cl::opt<PassFilterConfig, true, cl::parser<std::string>>
    PassFilterAnalysis(
        "pass-filter-analysis", cl::value_desc("regex"),
        cl::desc("Activate analysis diagnostics from passes matching this regex"),
        cl::Hidden, cl::location(AnalysisFilterLoc), cl::ValueRequired);
}

bool DiagnosticHandler::isAnalysisDiagnosticEnabled(StringRef PassName) const {
  return (AnalysisFilterLoc.FilterPattern &&
          AnalysisFilterLoc.FilterPattern->match(PassName));
}

bool DiagnosticHandler::isMissedOptDiagnosticEnabled(StringRef PassName) const {
  return (MissedFilterLoc.FilterPattern &&
          MissedFilterLoc.FilterPattern->match(PassName));
}

bool DiagnosticHandler::isPassedOptDiagnosticEnabled(StringRef PassName) const {
  return (PassedFilterLoc.FilterPattern &&
          PassedFilterLoc.FilterPattern->match(PassName));
}

bool DiagnosticHandler::hasAnyDiagnosticEnabled() const {
  return (PassedFilterLoc.FilterPattern || MissedFilterLoc.FilterPattern ||
          AnalysisFilterLoc.FilterPattern);
}

#include "Alias/TPA/PointerAnalysis/Engine/GlobalState.h"
#include "Alias/TPA/PointerAnalysis/Engine/TransferFunction.h"
#include "Alias/TPA/PointerAnalysis/Program/CFG/CFG.h"

namespace tpa {

void TransferFunction::processEntryNode(const ProgramPoint &entryPoint,
                                        EvalResult &result) {
    assert(localState != nullptr);
    propagateTopLevelSuccessors(entryPoint, result);
    propagateMemoryLevelSuccessors(entryPoint, *localState, result);

    // To ensure the analysis does not terminate prematurely before newly 
    // introduced return edges are considered, we unconditionally enqueue 
    // the exit node upon entering a function.
    //
    // Note: This unconditional enqueue is deliberate. The SemiSparsePropagator
    // maintains a memoization cache (Memo) and will only re-evaluate the exit 
    // node if the store state at that point has been updated. Thus, although 
    // the exit node is enqueued on each entry visit, redundant computations 
    // are avoided through memo-table lookups, preserving correctness and 
    // termination of the fixpoint computation.

    auto &controlFlowGraph = entryPoint.getCFGNode()->getCFG();
    if (!controlFlowGraph.hasNoReturn()) {
        result.addTopLevelProgramPoint(
            ProgramPoint(entryPoint.getContext(), controlFlowGraph.getExitNode()));
    }
}

} // namespace tpa

#define SOL_ALL_SAFETIES_ON 1
#include <sol/sol.hpp>
#include <vector>
#include <iostream>

int main(int, char**) {
    std::cout << "=== containers ===" << std::endl;
    sol::state lua_env;
    lua_env.open_libraries();
    lua_env.script(R"(
function display_container (data)
    print("container has:")
    for i=1,#data do
        val = data[i]
        print("\t", i, val)
    end
    print()
end
    )");

    sol::function display_func = lua_env["display_container"];

    // Initialize a global variable with a vector of 5 integers
    lua_env["my_data"] = std::vector<int> { 3, 6, 9, 12, 15 };

    // Display initial contents
    display_func(lua_env["my_data"]);

    // Modify the vector from C++
    std::vector<int>& vec_ref = lua_env["my_data"];
    vec_ref.push_back(18);

    // Display updated contents (now 6 elements)
    display_func(lua_env["my_data"]);

    lua_env.script(R"(
my_data:add(42)
    )");

    // Display after adding another element (7 total)
    display_func(lua_env["my_data"]);

    lua_env.script(R"(
my_data:clear()
    )");

    // Now empty
    display_func(lua_env["my_data"]);

    std::cout << std::endl;
    return 0;
}

#include <hip/hip_runtime.h>
#include <cstddef>
#include <cstdlib>
#include <iostream>

int main()
{
    // Initialize the HIP runtime environment
    if (auto result = hipInit(0); result != hipSuccess)
    {
        std::cerr << "Error: HIP runtime initialization failed." << std::endl;
        return EXIT_FAILURE;
    }

    // Retrieve the per-thread default stream
    hipStream_t worker_stream = hipStreamPerThread;

    // Allocate device memory using the stream
    void* device_memory;
    std::size_t buffer_size = 1024;

    if (auto err = hipMalloc(&device_memory, buffer_size); err != hipSuccess)
    {
        std::cerr << "Memory allocation on device failed." << std::endl;
        return EXIT_FAILURE;
    }

    // Asynchronously initialize the allocated memory to zero
    if (auto status = hipMemsetAsync(device_memory, 0, buffer_size, worker_stream); status != hipSuccess)
    {
        std::cerr << "Memory initialization operation failed." << std::endl;
        return EXIT_FAILURE;
    }

    // Wait for all operations in the stream to complete
    if (auto sync_result = hipStreamSynchronize(worker_stream); sync_result != hipSuccess)
    {
        std::cerr << "Stream synchronization failed." << std::endl;
        return EXIT_FAILURE;
    }

    // Release the device memory
    if(auto free_err = hipFree(device_memory); free_err != hipSuccess)
    {
        std::cerr << "Device memory deallocation failed." << std::endl;
        return EXIT_FAILURE;
    }

    std::cout << "All operations completed successfully with per-thread default stream." << std::endl;
    return EXIT_SUCCESS;
}

