namespace CTRPF = CTRPluginFramework;
using namespace Core;

// Timeout duration set to 5000 milliseconds
static Core::Timer asyncExecutionTimeout(CTRPF::Milliseconds(5000));

// Resets the async execution timer
void Core::AsyncRestartClock() {
    asyncExecutionTimeout.Restart();
}

// Checks if async coroutine exceeded allowed execution time
void Core::_TimeoutAsyncHook(lua_State *L, lua_Debug *ar) {
    if (asyncExecutionTimeout.Expired())
        luaL_error(L, "Async coroutine exceeded execution time (5000 ms)");
}

// ----------------------------------------------------------------------------
//$Async
//@@AsyncTask
// ----------------------------------------------------------------------------

/*
- Creates and returns a new task based on the provided function that can be linked to game events
## func: function
## return: AsyncTask
### Async.create
*/
static int l_Async_create(lua_State *L)
{
    /* Only stores a reference to the function. The actual coroutine is created
       when needed, enabling multiple invocations of the same task */
    luaL_checktype(L, 1, LUA_TFUNCTION);
    lua_newtable(L);
    lua_pushvalue(L, 1); // retain function reference
    lua_setfield(L, -2, "_taskF");
    luaC_setmetatable(L, "AsyncTask");
    return 1;
}

/*
- Enqueues the given function to run concurrently with the game until completion
## func: function
### Async.run
*/
static int l_Async_run(lua_State *L)
{
    luaL_checktype(L, 1, LUA_TFUNCTION);
    lua_State *coroutine = lua_newthread(L);
    lua_pushvalue(L, 1);
    lua_xmove(L, coroutine, 1);
    lua_sethook(coroutine, Core::_TimeoutAsyncHook, LUA_MASKCOUNT, 100);
    Scheduler::getInstance().AddTask(L, -1);
    lua_pop(L, 1); // Remove coroutine from stack
    return 0;
}

/*
- Suspends the current task for the specified duration (in seconds), then resumes.
  Always returns true upon resumption.
## seconds: number?
## return: boolean
### Async.wait
*/
static int l_Async_wait(lua_State *L) {
    if (!Scheduler::getInstance().IsValidTask(L)) {
        return luaL_error(L, "use an async task to execute this function");
    }
    int argCount = lua_gettop(L);
    if (argCount > 0) {
        if (lua_isnumber(L, 1)) {
            float duration = lua_tonumber(L, 1);
            if (duration < 0)
                return luaL_error(L, "bad time value");
            else
                return Scheduler::getInstance().CreateWait(L, UniqueAlloc::alloc<AsyncWaitHandler>(duration));
        } else {
            return luaL_error(L, "bad #1 argument type (expected number)");
        }
    } else {
        // Perform a single-frame wait; still requires AsyncWaitHandler for proper return behavior
        return Scheduler::getInstance().CreateWait(L, UniqueAlloc::alloc<AsyncWaitHandler>(0));
    }
}

// ----------------------------------------------------------------------------
static inline void RegisterAsyncTaskMetatable(lua_State *L)
{
    luaL_newmetatable(L, "AsyncTask");
    lua_newtable(L);
    lua_setfield(L, -2, "__index");
    lua_pushcfunction(L, luaC_invalid_newindex);
    lua_setfield(L, -2, "__newindex");
    lua_pushstring(L, "AsyncTask");
    lua_setfield(L, -2, "__name");
    lua_pop(L, 1);
}

bool Core::RegisterAsyncModule(lua_State *L)
{
    RegisterAsyncTaskMetatable(L);
    lua_newtable(L);
    lua_pushcfunction(L, l_Async_run);
    lua_setfield(L, -2, "run");
    lua_pushcfunction(L, l_Async_create);
    lua_setfield(L, -2, "create");
    lua_pushcfunction(L, l_Async_wait);
    lua_setfield(L, -2, "wait");
    lua_setglobal(L, "Async");
    return true;
}

