            TString("a b  \033[1;2;3;4;5m\nc d").Quote()
        );
        UNIT_ASSERT_STRINGS_EQUAL(
            NLastGetopt::Wrap(5, "a b       \033[1;2;3;4;5m  c d").Quote(),
            TString("a b\n\033[1;2;3;4;5m  c d").Quote()
        );
    }

    Y_UNIT_TEST(TestTextInfo) {
        size_t lineLength;
        bool containsParagraphs;

        NLastGetopt::Wrap(5, "a b c d e", "", &lineLength, &containsParagraphs);
        UNIT_ASSERT_VALUES_EQUAL(lineLength, 3);
        UNIT_ASSERT_VALUES_EQUAL(containsParagraphs, false);

        NLastGetopt::Wrap(5, "a b c\n\nd e f h", "", &lineLength, &containsParagraphs);
        UNIT_ASSERT_VALUES_EQUAL(lineLength, 1);
        UNIT_ASSERT_VALUES_EQUAL(containsParagraphs, true);

        NLastGetopt::Wrap(5, "a b c\n\n", "", &lineLength, &containsParagraphs);
        UNIT_ASSERT_VALUES_EQUAL(lineLength, 0);
