{
	if (hitResult->entityTarget != NULL)
	{
		DamageSource *source = DamageSource::thrown(shared_from_this(), owner);
		hitResult->entityTarget->takeDamage(source, 0);
		delete source;
	}

	for (int index = 0; index < 32; index++)
	{
		world->spawnParticle(eParticleType_ender, x, y + random->nextDouble() * 2, z, random->nextGaussian(), 0, random->nextGaussian());
