using asio::post;
using asio::thread_pool;

// Modified active object implementation for bank account operations
class financial_account
{
  int current_balance_ = 0;
  mutable thread_pool worker_pool_{1};
public:
  void credit(int value)
  {
    post(worker_pool_, [=]
      {
        current_balance_ += value;
      });
  }
  void debit(int value)
  {
    post(worker_pool_, [=]
      {
        if (current_balance_ >= value)
          current_balance_ -= value;
      });
  }
  void show_status() const
  {
    post(worker_pool_, [=]
      {
        std::cout << "account balance = " << current_balance_ << "\n";
      });
  }
  ~financial_account()
  {
    worker_pool_.join();
  }
};

int main()
{
  financial_account user_account;
  user_account.credit(20);
  user_account.debit(10);
  user_account.show_status();
}

