// Function to perform a query operation via interactive communication.
int execute_query(int left, int right) {
    std::cout << "1 " << left << " " << right << std::endl;
    int result;
    std::cin >> result;
    return result;
}

// Function to output the final answer in required format.
void print_result(const std::vector<int>& solution) {
    std::cout << "3";
    for (size_t idx = 1; idx < solution.size(); ++idx) {
        std::cout << " " << solution[idx];
    }
    std::cout << std::endl;
}

int main() {
    // Fast I/O setup
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n, range1, range2;
    std::cin >> n >> range1 >> range2;

    // `index_map[k]` stores the original index of the element currently at position `k`.
    // Initially, position `k` holds the element that started at index `k`.
    std::vector<int> index_map(n + 1);
    std::iota(index_map.begin(), index_map.end(), 0);

    // Strategy: Build a chain of consecutive-value elements step by step.
    // After iteration `i`, positions `1..i` contain a chain of `i` value-adjacent elements.
    // For each `i`, find an element from remaining positions (`i+1..n`) that is value-adjacent to `p[i]`.
    for (int step = 1; step < n; ++step) {
        // Current pivot is at position `step`. Look for its neighbor among remaining positions.
        for (int candidate = step + 1; candidate <= n; ++candidate) {
            // Move candidate element to position `step+1` for testing
            execute_swap(step + 1, candidate);
            std::swap(index_map[step + 1], index_map[candidate]);

            // Query on interval `[step, step+1]` tells us if adjacent values exist
            // Returns 3 if p[step] and p[step+1] have consecutive values, else 2
            if (execute_query(step, step + 1) == 3) {
                // Found a valid neighbor - keep it at position `step+1`
                break;
            }

            // Not a neighbor - restore previous state
            execute_swap(step + 1, candidate);
            std::swap(index_map[step + 1], index_map[candidate]);
        }
    }

    // Now positions 1..n form a chain of consecutive integers
    // The sequence must be either increasing (1,2,...,n) or decreasing (n,n-1,...,1)
    std::vector<int> final_answer(n + 1);
    for (int pos = 1; pos <= n; ++pos) {
        final_answer[index_map[pos]] = pos;
    }

    // Problem constraints ensure only two possible solutions exist (complementary permutations)
    print_result(final_answer);
    return 0;
}

#include <format>
#include <sm/vvec>
#include <mplot/Visual.h>
#include <mplot/GraphVisual.h>

int main()
{
    // Initialize a mplot::Visual 'scene environment' with custom dimensions and title
    mplot::Visual scene(1280, 960, "Generated using mplot::GraphVisual");

    // Instantiate a GraphVisual object (as unique_ptr) positioned at origin (0,0,0)
    auto graph = std::make_unique<mplot::GraphVisual<double>>(sm::vec<float>{0.0f, 0.0f, 0.0f});

    // Required initialization: associate parent context and bind internal callbacks
    scene.bindmodel(graph);

    // Prepare x-axis data using vvec (vector-like container with vectorized operations)
    sm::vvec<double> x_coords;
    x_coords.linspace(0, 10, 11);  // 11 points from 0 to 10 inclusive

    // Define y-axis values manually
    sm::vvec<double> y_values = {5, 8, 2, 9, 1, 2, 4, 5, 8, 3, 1};

    // Configure line-style dataset with crimson color
    mplot::DatasetStyle line_style(mplot::stylepolicy::lines);
    line_style.linecolour = mplot::colour::crimson;

    // Set fixed y-axis range for the plot
    graph->setlimits_y(0, 10);

    // Assign data to the graph
    graph->setdata(x_coords, y_values, line_style);

    // Create horizontal reference line style at y=7
    mplot::DatasetStyle horz_line_style(mplot::stylepolicy::lines);
    horz_line_style.linecolour = mplot::colour::grey68;
    horz_line_style.linewidth = line_style.linewidth * 0.6f;

    // Detect crossing points of the curve with y=7 and draw vertical markers
    sm::vvec<double> cross_points = graph->add_y_crossing_lines(
        x_coords, y_values, 7, line_style, horz_line_style);

    // Format annotation string for crossing points
    size_t count = cross_points.size();
    std::stringstream annotation_stream;
    if (count > 0) {
        for (size_t idx = 0; idx < count; ++idx) {
            annotation_stream << std::format(
                "{}{}{:.2f}",
                ((idx == 0 || idx == count - 1) ? "" : ", "),
                (idx == count - 1 ? " and " : ""),
                cross_points[idx]
            );
        }
    } else {
        annotation_stream << "[no intersections]";
    }

    // Add descriptive label at bottom-left corner
    graph->addLabel(
        std::format("y=7 at x = {:s}", annotation_stream.str()),
        {0.05f, 0.05f, 0.0f},
        mplot::TextFeatures(0.03f)
    );

    // Finalize rendering setup (compute OpenGL geometry)
    graph->finalize();

    // Transfer ownership of graph model to the visual scene
    scene.addVisualModel(graph);

    // Display window and wait for user exit (Ctrl-q)
    scene.keepOpen();

    // Automatic cleanup via RAII when scene destructor runs
    return 0;
}

