using namespace std;

// Custom comparator to sort pairs by their second value
bool sortBySecond(pair<int, int> x, pair<int, int> y) {
    return x.second < y.second;
}

int main() {
    vector<pair<int, int>> data = {{5, 2}, {8, 1}, {4, 3}}; // vector of integer pairs
    sort(data.begin(), data.end()); // sort using default comparison (by first element)

    cout << "Sorted by first component: ";
    for (auto iter = data.begin(); iter != data.end(); ++iter) {
        cout << "(" << iter->first << ", " << iter->second << ") ";
    }
    cout << endl;

    sort(data.begin(), data.end(), sortBySecond); // sort using custom comparator (by second element)
    cout << "Sorted by second component: ";
    for (auto iter = data.begin(); iter != data.end(); ++iter) {
        cout << "(" << iter->first << ", " << iter->second << ") ";
    }
    cout << endl;

    return 0;
}

#include "BufferedOutputStream.h"
#include "util/console/ArrayWithLength.h"
#include "win/extraX64.h"

// Constructs a buffered output stream that wraps the given output stream,
// using a buffer of the specified size.
// Parameters:
//   out  - the underlying output stream to write to
//   size - the size of the internal buffer
BufferedOutputStream::BufferedOutputStream(OutputStream* out, int size) {
    baseStream = out;
    buffer     = byteArray(size);
    bufferSize = 0;
}

BufferedOutputStream::~BufferedOutputStream() { delete buffer.data; }

// Flushes any pending data in the internal buffer to the underlying stream.
void BufferedOutputStream::flush() {
    baseStream->write(buffer, 0, bufferSize);
    bufferSize = 0;
}

// Closes the stream, ensuring all buffered data is written before closing.
void BufferedOutputStream::close() {
    flush();
    baseStream->close();
}

// Writes a specified number of bytes from an array to the stream.
// If the amount of data exceeds the buffer capacity, it bypasses buffering
// and writes directly to the underlying stream.
//
// Parameters:
//   b      - source byte array
//   offset - starting index in the array
//   length - number of bytes to write
void BufferedOutputStream::write(
    byteArray    b,
    unsigned int offset,
    unsigned int length
) {
    // If the write request is larger than or equal to buffer size,
    // flush current buffer and write directly
    if (length >= buffer.length) {
        flush();
        baseStream->write(b, offset, length);
    } else {
        // Otherwise, write byte-by-byte through the single-byte write method
        for (unsigned int idx = 0; idx < length; idx++) {
            write(b[offset + idx]);
        }
    }
}

// Convenience method: writes an entire byte array to the stream.
void BufferedOutputStream::write(byteArray b) { 
    write(b, 0, b.length); 
}

// Writes a single byte to the buffer.
// When the buffer becomes full, it automatically flushes.
void BufferedOutputStream::write(unsigned int b) {
    buffer[bufferSize++] = (byte)b;
    if (bufferSize == buffer.length) {
        flush();
    }
}

