// Returns: the position of the least significant set bit in 'value',
// or zero if 'value' is zero. Bit positions start at one from the LSB.
COMPILER_RT_ABI int __ffssi2(si_int value) {
  if (value == 0) {
    return 0;
  }
  return __builtin_ctz(value) + 1;
}

