// Simulate sol::nested and sol::as_table_t behavior for demonstration
namespace sol {
    template <typename T>
    struct as_table_t {
        T value_;
        as_table_t(const T& v) : value_(v) {}
        const T& value() const { return value_; }
    };

    template <typename T>
    struct nested {
        T value_;
        nested(const T& v) : value_(v) {}
        const T& value() const { return value_; }
    };
}

void demo(
     sol::nested<std::map<std::string, std::vector<std::string>>>
          src) {
	std::cout << "demo, sol::nested<...>" << std::endl;
	const auto& listmap = src.value();
	for (const auto& kvp : listmap) {
		const std::vector<std::string>& strings = kvp.second;
		std::cout << "\t" << kvp.first << " = ";
		for (const auto& s : strings) {
			std::cout << "'" << s << "'"
			          << " ";
		}
		std::cout << std::endl;
	}
	std::cout << std::endl;
}

void demo_explicit(sol::as_table_t<std::map<std::string,
          sol::as_table_t<std::vector<std::string>>>>
          src) {
	std::cout << "demo, explicit sol::as_table_t<...>"
	          << std::endl;
	const auto& listmap = src.value();
	for (const auto& kvp : listmap) {
		const std::vector<std::string>& strings
		     = kvp.second.value();
		std::cout << "\t" << kvp.first << " = ";
		for (const auto& s : strings) {
			std::cout << "'" << s << "'"
			          << " ";
		}
		std::cout << std::endl;
	}
	std::cout << std::endl;
}

int main(int, char**) {
	std::cout << "=== containers retrieved from lua tables ==="
	          << std::endl;

	// Simulate the Lua table structure in C++
	std::map<std::string, std::vector<std::string>> test_map;
	test_map["key1"] = {"hello", "there", "world"};
	test_map["key2"] = {"bark", "borf", "woof"};

	sol::nested<std::map<std::string, std::vector<std::string>>> nested_wrapper(test_map);
	demo(nested_wrapper);

	sol::as_table_t<std::map<std::string, sol::as_table_t<std::vector<std::string>>>> explicit_wrapper(test_map);
	demo_explicit(explicit_wrapper);

	std::cout << std::endl;
	return 0;
}

#include <vector>
using namespace std;

class Solution {
public:
    void rotate(vector<int>& nums, int k) {
        int size = nums.size();
        vector<int> rotated;

        // Adjust k if it's larger than array size
        if (k > size) {
            k = k % size;
        }

        // Add elements from the end first (right part)
        if (k > 0) {
            rotated.push_back(nums[size - k]);
        }

        // Continue adding remaining right part elements
        for (int j = size - k + 1; j < size; j++) {
            rotated.push_back(nums[j]);
        }

        // Add the left part elements
        for (int j = 0; j < size - k; j++) {
            rotated.push_back(nums[j]);
        }

        // Update original array with rotated version
        nums = rotated;
    }
};

