namespace faiss {

InvertedListsIOHook::InvertedListsIOHook(
        const std::string& identifier,
        const std::string& type_name)
        : key(identifier), classname(type_name) {}

namespace {
/// Custom vector that owns and cleans up its InvertedListsIOHook elements
struct CallbackRegistry : std::vector<InvertedListsIOHook*> {
    CallbackRegistry() {
#ifndef _WIN32
        push_back(new OnDiskInvertedListsIOHook());
#endif
        push_back(new BlockInvertedListsIOHook());
    }
    ~CallbackRegistry() {
        for (auto item : *this) {
            delete item;
        }
    }
};
static CallbackRegistry inverted_lists_io_callbacks;
} // namespace

InvertedListsIOHook* InvertedListsIOHook::lookup(int code) {
    for (const auto& hook : inverted_lists_io_callbacks) {
        if (code == fourcc(hook->key)) {
            return hook;
        }
    }
    FAISS_THROW_FMT(
            "read_InvertedLists: could not load ArrayInvertedLists as "
            "%08x (\"%s\")",
            code,
            fourcc_inv_printable(code).c_str());
}

InvertedListsIOHook* InvertedListsIOHook::lookup_by_type(
        const std::string& type_name) {
    for (const auto& hook : inverted_lists_io_callbacks) {
        if (hook->classname == type_name) {
            return hook;
        }
    }
    FAISS_THROW_FMT(
            "read_InvertedLists: could not find class type %s",
            type_name.c_str());
}

void InvertedListsIOHook::register_hook(InvertedListsIOHook* cb) {
    inverted_lists_io_callbacks.push_back(cb);
}

void InvertedListsIOHook::list_hooks() {
    printf("registered %zd InvertedListsIOHooks:\n",
           inverted_lists_io_callbacks.size());
    for (const auto& hook : inverted_lists_io_callbacks) {
        printf("%08x %s %s\n",
               fourcc(hook->key.c_str()),
               hook->key.c_str(),
               hook->classname.c_str());
    }
}

InvertedLists* InvertedListsIOHook::read_ArrayInvertedLists(
        IOReader*,
        int,
        size_t,
        size_t,
        const std::vector<size_t>&) const {
    FAISS_THROW_FMT("read to array not implemented for %s", classname.c_str());
}

} // namespace faiss

#include <iostream>
#include <string>
#include <vector>

// Global variables for the state machine logic
// n: number of passages in each chamber (renamed from m)
int n;
// count: counter for passages taken from the currently active chamber (renamed from k)
int count = 0;

void process() {
    // Read the number of passages per chamber
    std::cin >> n;
    std::string current_state;

    // Continue processing until treasure is found
    while (std::cin >> current_state && current_state != "treasure") {
        if (current_state == "center") {
            // New unvisited chamber encountered
            // Initialize exploration by marking as 'left' and taking reference passage
            // Output: "0 left 0" means:
            //   d=0: stone placed at reference passage
            //   s=left: mark chamber as being explored
            //   p=0: take the reference passage itself
            count = 1;
            std::cout << "0 left 0" << std::endl;
        } else if (current_state == "left") {
            // Chamber currently under exploration
            // count indicates how many passages have been taken so far

            if (count < n - 1) {
                // Not yet at the last passage in this chamber
                // Move to next passage clockwise, keep exploration status
                // Output: "1 left 1" means:
                //   d=1: move stone one position clockwise
                //   s=left: continue marking as in-progress
                //   p=1: take the next passage clockwise
                std::cout << "1 left 1" << std::endl;
            } else {
                // Last passage to explore in this chamber
                // After this, chamber will be fully explored
                // Output: "1 right 1" means:
                //   d=1: move stone to final passage
                //   s=right: mark as fully completed
                //   p=1: take the final passage
                std::cout << "1 right 1" << std::endl;
            }
            // Update passage count after taking a new passage
            count++;
        } else if (current_state == "right") {
            // Fully explored chamber - just pass through
            // Take the marked passage without changing state
            // Output: "0 right 0" means:
            //   d=0: no stone movement
            //   s=right: maintain completed status
            //   p=0: take the reference (marked) passage
            std::cout << "0 right 0" << std::endl;
        }
    }
}

int main() {
    // Optimize I/O performance
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);
    process();
    return 0;
}

