#include <asio.hpp>
#include <boost/bind.hpp>
#include <istream>
#include <iostream>
#include <ostream>
#include "icmp_header.hpp"
#include "ipv4_header.hpp"

using asio::ip::icmp;
using asio::steady_timer;

namespace chrono = asio::chrono;

class network_pinger
{
public:
  network_pinger(asio::io_context& context, const char* target_host)
    : host_resolver_(context), icmp_socket_(context, icmp::v4()),
      timeout_timer_(context), current_seq_(0), reply_count_(0)
  {
    target_endpoint_ = *host_resolver_.resolve(icmp::v4(), target_host, "").begin();
    initiate_transmission();
    prepare_for_response();
  }

private:
  void initiate_transmission()
  {
    std::string payload_data("Message from Asio network diagnostic tool.");

    // Construct ICMP echo request packet
    icmp_header request_packet;
    request_packet.type(icmp_header::echo_request);
    request_packet.code(0);
    request_packet.identifier(fetch_process_id());
    request_packet.sequence_number(++current_seq_);
    calculate_checksum(request_packet, payload_data.begin(), payload_data.end());

    // Prepare transmission buffer
    asio::streambuf transmission_buffer;
    std::ostream output_stream(&transmission_buffer);
    output_stream << request_packet << payload_data;

    // Send packet and set timeout
    last_send_time_ = steady_timer::clock_type::now();
    icmp_socket_.send_to(transmission_buffer.data(), target_endpoint_);

    // Configure timeout for response
    reply_count_ = 0;
    timeout_timer_.expires_at(last_send_time_ + chrono::seconds(7));
    timeout_timer_.async_wait(boost::bind(&network_pinger::on_timeout, this));
  }

  void on_timeout()
  {
    if (reply_count_ == 0)
      std::cout << "No response received within timeout period" << std::endl;

    // Enforce minimum delay between requests
    timeout_timer_.expires_at(last_send_time_ + chrono::seconds(2));
    timeout_timer_.async_wait(boost::bind(&network_pinger::initiate_transmission, this));
  }

  void prepare_for_response()
  {
    // Clear any buffered data
    response_buffer_.consume(response_buffer_.size());

    // Set up asynchronous receive operation
    icmp_socket_.async_receive(response_buffer_.prepare(131072),
        boost::bind(&network_pinger::process_response, this, _2));
  }

  void process_response(std::size_t bytes_received)
  {
    // Commit received bytes to buffer
    response_buffer_.commit(bytes_received);

    // Parse incoming packet
    std::istream packet_stream(&response_buffer_);
    ipv4_header ip_header;
    icmp_header icmp_header;
    packet_stream >> ip_header >> icmp_header;

    // Validate response matches our expectations
    if (packet_stream && icmp_header.type() == icmp_header::echo_reply
          && icmp_header.identifier() == fetch_process_id()
          && icmp_header.sequence_number() == current_seq_)
    {
      // First successful reply cancels timeout
      if (reply_count_++ == 0)
        timeout_timer_.cancel();

      // Output statistics
      chrono::steady_clock::time_point current_time = chrono::steady_clock::now();
      chrono::steady_clock::duration round_trip = current_time - last_send_time_;
      std::cout << bytes_received - ip_header.header_length()
        << " octets from " << ip_header.source_address()
        << ": icmp_seq=" << icmp_header.sequence_number()
        << ", ttl=" << ip_header.time_to_live()
        << ", latency="
        << chrono::duration_cast<chrono::milliseconds>(round_trip).count()
        << " ms" << std::endl;
    }

    prepare_for_response();
  }

  static unsigned short fetch_process_id()
  {
#if defined(ASIO_WINDOWS)
    return static_cast<unsigned short>(::GetCurrentProcessId());
#else
    return static_cast<unsigned short>(::getpid());
#endif
  }

  icmp::resolver host_resolver_;
  icmp::endpoint target_endpoint_;
  icmp::socket icmp_socket_;
  steady_timer timeout_timer_;
  unsigned short current_seq_;
  chrono::steady_clock::time_point last_send_time_;
  asio::streambuf response_buffer_;
  std::size_t reply_count_;
};

int main(int argument_count, char* arguments[])
{
  try
  {
    if (argument_count != 2)
    {
      std::cerr << "Usage: ping <hostname>" << std::endl;
#if !defined(ASIO_WINDOWS)
      std::cerr << "(This program may require elevated privileges)" << std::endl;
#endif
      return 1;
    }

    asio::io_context service_context;
    network_pinger pinger_instance(service_context, arguments[1]);
    service_context.run();
  }
  catch (std::exception& exception_object)
  {
    std::cerr << "Error encountered: " << exception_object.what() << std::endl;
  }
}

