int main() {
    // Optimize input/output operations for competitive programming.
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    // Set grid size constants based on problem constraints.
    const int rows = 20;
    const int cols = 20;

    // Output the grid dimensions.
    std::cout << rows << " " << cols << '\n';

    // Initialize grid with obstacles ('0').
    std::vector<std::string> maze(rows, std::string(cols, '0'));

    // Specify center point for cross shape (slightly off-center is acceptable).
    const int mid_row = 10;
    const int mid_col = 10;

    // Draw vertical line of the cross.
    for (int r = 0; r < rows; ++r) {
        maze[r][mid_col] = '1';
    }

    // Draw horizontal line of the cross.
    for (int c = 0; c < cols; ++c) {
        maze[mid_row][c] = '1';
    }

    // Display the resulting pattern.
    for (int r = 0; r < rows; ++r) {
        std::cout << maze[r] << '\n';
    }

    return 0;
}

