// tag::decl[]
bool is_short_timeout(pugi::xml_node element)
{
    return element.attribute("Timeout").as_int() < 20;
}

struct has_remote_permission
{
    bool operator()(pugi::xml_attribute attribute) const
    {
        return std::strcmp(attribute.name(), "AllowRemote") == 0;
    }

    bool operator()(pugi::xml_node node) const
    {
        return node.attribute("AllowRemote").as_bool();
    }
};
// end::decl[]

int main()
{
    pugi::xml_document document;
    if (!document.load_file("xgconsole.xml")) return -1;

    pugi::xml_node section = document.child("Profile").child("Tools");

    // tag::find[]
    // Locate direct child using predicate
    std::cout << section.find_child(has_remote_permission()).attribute("Filename").value() << std::endl;

    // Locate any descendant using predicate (depth-first search)
    std::cout << document.find_node(has_remote_permission()).attribute("Filename").value() << std::endl;

    // Locate attribute using predicate
    std::cout << section.last_child().find_attribute(has_remote_permission()).value() << std::endl;

    // Using function pointer instead of functor
    std::cout << section.find_child(is_short_timeout).attribute("Filename").value() << std::endl;
    // end::find[]
}

