EnumSwitchColorFlip::Outer::color
EnumSwitchColorFlip::Outer::invert(const EnumSwitchColorFlip::Outer::color input) {
  return [&](void) {
    switch (input) {
    case color::Green: {
      return color::Yellow;
    }
    case color::Yellow: {
      return color::Green;
    }
    }
  }();
}

unsigned int
EnumSwitchColorFlip::Outer::value(const EnumSwitchColorFlip::Outer::color input) {
  return [&](void) {
    switch (input) {
    case color::Green: {
      return (10 + 5);
    }
    case color::Yellow: {
      return ((10 + 5) + 5);
    }
    }
  }();
}

