#include <unitree/robot/go2/video/video_client.hpp>
#include <iostream>
#include <fstream>
#include <ctime>

int main() {
    // Initialize the communication channel
    unitree::robot::ChannelFactory::Instance()->Init(0);
    unitree::robot::go2::VideoClient video_capture;

    // Configure request timeout to 1.0 seconds
    video_capture.SetTimeout(1.0f);
    video_capture.Init();

    // Capture and save images periodically
    std::vector<uint8_t> frame_data;
    int status_code;

    while (true) {
        status_code = video_capture.GetImageSample(frame_data);

        if (status_code == 0) {
            time_t current_time;
            struct tm *time_struct;
            char timestamp[80];

            time(&current_time);
            time_struct = localtime(&current_time);
            strftime(timestamp, sizeof(timestamp), "%Y%m%d%H%M%S.jpg", time_struct);

            std::string filename(timestamp);
            std::ofstream output_file(filename, std::ios::binary);

            if (output_file.is_open()) {
                output_file.write(reinterpret_cast<const char*>(frame_data.data()), frame_data.size());
                output_file.close();
                std::cout << "Frame captured and saved as " << filename << std::endl;
            } else {
                std::cerr << "Error: Unable to create file " << filename << std::endl;
            }
        }

        sleep(3);
    }

    return 0;
}

#include <engLib/eng.h>
namespace engine::task::actionTransform {
//-----------------------------------------------------------------
/// @details
///		Initialization routine for a transformation task
//-----------------------------------------------------------------
Error Task::beginTask() noexcept {
    // Acquire the destination endpoint first, as configuration parameters
    // for opening the source endpoint rely on the destination settings
    if (!(m_destinationEndpoint = IServiceEndpoint::getTargetEndpoint(
              {.jobConfig = jobConfig(),
               .taskConfig = taskConfig(),
               .serviceConfig = taskConfig()["destination"],
               .openMode = OPEN_MODE::TRANSFORM})))
        return m_destinationEndpoint.ccode();

    // Determine the appropriate mode for opening the source endpoint
    OPEN_MODE sourceOpenMode{};
    if (m_destinationEndpoint->config.taskConfig.lookup<bool>("requiresPolicies") ||
        m_destinationEndpoint->config.taskConfig.lookup<bool>("requiresContext") ||
        m_destinationEndpoint->config.taskConfig.lookup<bool>("requiresText")) {
        sourceOpenMode =
            m_destinationEndpoint->config.taskConfig.lookup<bool>("requiresData")
                ? OPEN_MODE::SOURCE_INDEX
                : OPEN_MODE::INDEX;
    } else {
        sourceOpenMode = OPEN_MODE::SOURCE;
    }

    // Acquire the source endpoint
    if (!(m_sourceEndpoint = IServiceEndpoint::getSourceEndpoint(
              {.jobConfig = jobConfig(),
               .taskConfig = taskConfig(),
               .serviceConfig = taskConfig()["source"],
               .openMode = sourceOpenMode})))
        return m_sourceEndpoint.ccode();

    // Execute base class initialization
    return Parent::beginTask();
}
//-----------------------------------------------------------------
///	@details
///		Processes an incoming line to generate and queue an entry
/// @param[in] inputLine
///		The raw input line in JSON format
/// @param[in] ancestorUrl
///		The parent URL context
//-----------------------------------------------------------------
ErrorOr<Entry> Task::processLine(TextView inputLine, const Url &ancestorUrl) noexcept {
    // Handle lines starting with 'A' followed by JSON content
    auto entry = Parent::processLine("A"_tv, inputLine, ancestorUrl);
    if (entry.hasCcode()) return entry;

    // Transform action requires classification; update flags accordingly
    entry.value().flags(entry.value().flags() | Entry::FLAGS::INDEX |
                        Entry::FLAGS::CLASSIFY | Entry::FLAGS::OCR);
    return entry;
}
//-----------------------------------------------------------------
/// @details
///		Applies transformation logic to an entry and sends it to the target
/// @param[in] itemEntry
///		The entry to be transformed
//-----------------------------------------------------------------
Error Task::processItem(Entry &itemEntry) noexcept {
    // Apply base transformation logic
    if (auto ccode = Parent::processItem(itemEntry)) return ccode;

    // The Transform action may invoke Classification with wantsText enabled,
    // which includes full text content in classification results. This can
    // significantly increase disk or network usage since output batches are
    // not further processed. Therefore, classifications are stripped here.
    itemEntry.classifications.reset();

    // Handle success/failure states
    if (itemEntry.objectFailed()) {
        // Check if object was skipped
        if (itemEntry.completionCode() == Ec::Skipped) {
            // Record as completed without writing output
            MONITOR(addCompleted, 1, itemEntry.size());
        } else {
            // Record as failed
            MONITOR(addFailed, 1, itemEntry.size());
            // Log error details
            if (auto ccode = Parent::writeError(itemEntry, itemEntry.completionCode()))
                return ccode;
        }
    } else {
        // Record successful completion
        MONITOR(addCompleted, 1, itemEntry.size());
        // Write transformed result
        if (auto ccode = Parent::writeResult('A', itemEntry)) return ccode;
    }

    // Task complete
    return {};
}
}  // namespace engine::task::actionTransform

