namespace YimMenu::Features
{
	class RemoveAllObjects : public Command
	{
		using Command::Command;
		virtual void OnCall() override
		{
			for (auto item : Pools::GetObjects())
			{
				if (item)
					item.Remove();
			}
		}
	};

	class RemoveAllCameras : public Command
	{
		using Command::Command;
		virtual void OnCall() override
		{
			for (auto entity : Pools::GetObjects())
			{
				if (entity && entity.As<Object>().IsCamera())
					entity.Remove();
			}
		}
	};

	class RemoveAllPeds : public Command
	{
		using Command::Command;
		virtual void OnCall() override
		{
			for (auto unit : Pools::GetPeds())
			{
				if (!unit.IsPlayer())
					unit.Remove();
			}
		}
	};

	class RemoveAllVehicles : public Command
	{
		using Command::Command;
		virtual void OnCall() override
		{
			for (auto vehicle : Pools::GetVehicles())
			{
				vehicle.Remove();
			}
		}
	};

	static RemoveAllCameras _RemoveAllCameras("remcams", "Remove All Cameras", "Removes all cameras");
	static RemoveAllObjects _RemoveAllObjects{"remobjs", "Remove All Objects", "Removes all objects in the game world, including mission critical objects"};
	static RemoveAllPeds _RemoveAllPeds{"rempeds", "Remove All Peds", "Removes all peds in the game world, including mission critical peds"};
	static RemoveAllVehicles _RemoveAllVehicles{"remvehs", "Remove All Vehicles", "Removes all vehicles in the game world, including mission critical vehicles"};
}

