#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    // Optimize I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int black, white, height_top, height_bot;
    if (cin >> black >> white >> height_top >> height_bot) {
        // We construct the grid by splitting it into a top part (Black background)
        // and a bottom part (White background).
        // The top part will contain white-1 white islands.
        // The bottom part will contain black-1 black islands.
        // The interface between top (Black) and bottom (White) ensures the backgrounds 
        // are single connected components.

        // Calculate the minimum width required to fit the islands in one row.
        // Pattern for islands: @ . @ . @ (Islands at odd positions)
        // Length needed: 2 * islands + 1.
        int needed_top = (white == 1) ? 1 : (2 * (white - 1) + 1);
        int needed_bot = (black == 1) ? 1 : (2 * (black - 1) + 1);
        int cols = max(needed_top, needed_bot);

        vector<string> canvas;

        // Construct Top Part (Black background, White islands)
        if (white > 1) {
            // Row 1: Contains islands separated by background color
            string line = "";
            for (int idx = 0; idx < white - 1; ++idx) {
                line += "@.";
            }
            line += "@";
            // Pad the rest of the row with background color
            while ((int)line.length() < cols) line += "@";
            canvas.push_back(line);

            // Row 2: "Spine" row, fully background color to connect all background pieces
            canvas.push_back(string(cols, '@'));
        } else {
            // If only 1 white component needed, it is provided by the bottom part's background.
            // We just need the black background here.
            canvas.push_back(string(cols, '@'));
        }

        // Construct Bottom Part (White background, Black islands)
        if (black > 1) {
            // Row 3: "Spine" row, fully background color
            canvas.push_back(string(cols, '.'));

            // Row 4: Contains islands
            string line = "";
            for (int idx = 0; idx < black - 1; ++idx) {
                line += ".@";
            }
            line += ".";
            while ((int)line.length() < cols) line += ".";
            canvas.push_back(line);
        } else {
            // If only 1 black component needed, it is provided by the top part's background.
            // We just need the white background here.
            canvas.push_back(string(cols, '.'));
        }

        // Output results
        cout << canvas.size() << " " << cols << "\n";
        for (const string& s : canvas) {
            cout << s << "\n";
        }
    }
    return 0;
}

#include <shmem.h>
#include <stdio.h>

int main(void)
{
    // 1. Initialize the SHMEM environment
    shmem_init();

    // 2. Acquire essential runtime information
    int rank = shmem_my_pe();   // current processing element identifier
    int size = shmem_n_pes();   // total number of processing elements

    // Basic greeting from each PE
    printf("Greetings from PE %d among %d\n", rank, size);

    // -------------------------------------------------------------------------
    // Enhanced interaction: point-to-point data exchange
    // -------------------------------------------------------------------------

    // Allocate a single integer in symmetric memory accessible by all PEs
    int* shared_data = (int*) shmem_malloc(sizeof(int));

    // Each PE sets its local copy to its own rank
    *shared_data = rank;

    // Synchronize all PEs to ensure initialization is complete
    shmem_barrier_all();

    // Determine which PE will be our communication partner (cyclically next)
    int target_pe = (rank + 1) % size;
    int buffer;

    // Perform blocking get operation to fetch data from target PE
    shmem_int_get(&buffer, shared_data, 1, target_pe);

    printf("PE %d obtained value %d from PE %d\n", rank, buffer, target_pe);

    // Ensure all remote memory operations are completed before proceeding
    shmem_quiet();

    // -------------------------------------------------------------------------
    // Resource cleanup
    // -------------------------------------------------------------------------
    shmem_free(shared_data);

    // Terminate SHMEM environment properly
    shmem_finalize();

    return 0;
}

