void execute_operation(int a, int b) {
    if (a <= 0 || b <= 0 || a + b >= size) {
        return;
    }
    operations.push_back({a, b});

    std::vector<int> part1, part2, part3;
    part1.assign(arr.begin(), arr.begin() + a);
    part2.assign(arr.begin() + a, arr.begin() + size - b);
    part3.assign(arr.begin() + size - b, arr.end());

    arr.clear();
    arr.insert(arr.end(), part3.begin(), part3.end());
    arr.insert(arr.end(), part2.begin(), part2.end());
    arr.insert(arr.end(), part1.begin(), part1.end());

    for (int idx = 0; idx < size; ++idx) {
        pos[arr[idx]] = idx + 1;
    }
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::cin >> size;
    arr.resize(size);
    pos.resize(size + 1);

    for (int i = 0; i < size; ++i) {
        std::cin >> arr[i];
        pos[arr[i]] = i + 1;
    }

    if (size == 3) {
        // For size=3, reverse the array if lexicographically smaller
        std::vector<int> reversed_arr = arr;
        std::reverse(reversed_arr.begin(), reversed_arr.end());
        if (reversed_arr < arr) {
            execute_operation(1, 1);
        }
    } else {
        // For size >= 4, sort the array completely
        for (int target = 1; target <= size; ++target) {
            int current_pos = pos[target];
            if (current_pos == target) {
                continue;
            }

            // Bring element to position 1 using two operations
            if (current_pos > 1) {
                execute_operation(current_pos - 1, 1);
                execute_operation(size - 1, 1);
            }

            // Move element from position 1 to its correct position
            if (target > 1) {
                execute_operation(1, size - target);
                execute_operation(target, 1);
            }
        }
    }

    std::cout << operations.size() << "\n";
    for (const auto& op : operations) {
        std::cout << op.first << " " << op.second << "\n";
    }

    return 0;
}

