#include "PipelineExecutor.h"
#include "Processor.h"
#include "PipelineV2.h"
#include "PipelineBuffer.h"

using namespace db;

PipelineExecutor::PipelineExecutor(PipelineV2* pipeline,
                                   ExecutionContext* ctxt)
    : _pipeline(pipeline),
      _ctxt(ctxt)
{
}

PipelineExecutor::~PipelineExecutor() {
}

void PipelineExecutor::init() {
    // Initialize the execution stack with all source processors
    auto& workList = _activeStack;
    for (Processor* src : _pipeline->sources()) {
        workList.push(src);
    }
}

void PipelineExecutor::execute() {
    init();
    while (!_activeStack.empty()) {
        runOneCycle();
    }
}

void PipelineExecutor::runOneCycle() {
    auto& pendingStack = _activeStack;
    auto& readyQueue = _updateQueue;

    // Locate the first executable processor in the pending stack
    // Processors that cannot execute yet are removed to prevent unbounded growth.
    // They will be reactivated later through the propagation mechanism via the ready queue.
    //
    // No processor is lost: eventually, only source processors remain at the bottom.
    {
        while (!pendingStack.empty()) {
            Processor* proc = pendingStack.top();
            pendingStack.pop();
            if (proc->canExecute()) {
                readyQueue.push(proc);
                break;
            }
        }
    }

    // Process all ready processors in this cycle
    while (!readyQueue.empty()) {
        Processor* current = readyQueue.front();
        readyQueue.pop();

        if (!current->isPrepared()) {
            current->prepare(_ctxt);
        }

        if (current->isFinished()) {
            current->reset();
        }

        current->execute();

        // If still not finished, push back onto the pending stack for future cycles
        if (!current->isFinished()) {
            pendingStack.push(current);
        }

        current->setScheduled(false);

        // Enqueue dependent successors if they become executable
        for (PipelineOutputPort* outPort : current->outputs()) {
            PipelineInputPort* input = outPort->getConnectedPort();
            if (input) {
                Processor* successor = input->getProcessor();
                if (!successor->isScheduled() && successor->canExecute()) {
                    readyQueue.push(successor);
                    successor->setScheduled(true);
                }
            }
        }
    }
}

