#include <vector>
#include <algorithm>
#include <climits>

class Solution {
public:
    int minOperations(std::vector<int>& arr) {
        int size = arr.size();
        int ones = std::count(arr.begin(), arr.end(), 1); // Count existing 1s

        // If there's at least one 1, we just need to convert the rest
        if (ones != 0) {
            return size - ones;
        }

        int minOps = INT_MAX; // Initialize with a large value

        // Check all possible subarrays to find the shortest one with GCD = 1
        for (int start = 0; start < size; start++) {
            int currentGcd = arr[start];
            for (int end = start + 1; end < size; end++) {
                currentGcd = __gcd(currentGcd, arr[end]);

                if (currentGcd == 1) {
                    // Operations needed: (end - start) to create a 1, then (size - 1) to propagate it
                    minOps = std::min(minOps, end - start + (size - 1));
                    break;
                }
            }
        }

        return (minOps == INT_MAX) ? -1 : minOps;
    }
};

#include <vector>
#include <numeric>

class Solution {
public:
    long long maxPower(std::vector<int>& cityStations, int radius, int extraStations) {
        long long low = 0;
        // Maximum possible answer when all stations are evenly distributed with extra stations
        long long high = std::accumulate(cityStations.begin(), cityStations.end(), 0LL) + extraStations;
        long long result = 0;

        while (low <= high) {
            long long midValue = (low + high) / 2;
            if (canAchieve(cityStations, radius, midValue, extraStations)) {
                result = midValue; // Current value is feasible, try for higher
                low = midValue + 1; // Explore upper half for better solution
            } else {
                high = midValue - 1; // Reduce required power level
            }
        }
        return result;
    }

    bool canAchieve(std::vector<int>& cityStations, int radius, long long requiredPower, int availableStations) {
        int n = cityStations.size();
        // Calculate initial window power for first city
        long long currentWindowPower = std::accumulate(cityStations.begin(), cityStations.begin() + radius, 0LL);
        std::vector<long long> stationAdditions(n, 0);

        for (int index = 0; index < n; index++) {
            if (index + radius < n) {
                // Expand window to include right boundary
                currentWindowPower += cityStations[index + radius];
            }

            if (currentWindowPower < requiredPower) {
                long long deficit = requiredPower - currentWindowPower;
                if (deficit > availableStations) {
                    // Not enough stations to cover the deficit
                    return false;
                }
                // Place additional stations at the farthest position in range
                stationAdditions[std::min(n - 1, index + radius)] += deficit;
                currentWindowPower = requiredPower;
                availableStations -= deficit;
            }

            if (index - radius >= 0) {
                // Remove contribution from left side of window
                currentWindowPower -= cityStations[index - radius] + stationAdditions[index - radius];
            }
        }
        return true;
    }
};

