#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    // Design a "Snake" layout on a 25x25 grid
    // This forms an extended path (similar to Hamiltonian path) across empty cells
    // The path spans roughly 300 positions
    // Random movements (U, D, L, R) simulate a 1D random walk along this path
    // Perpendicular moves (e.g., vertical in horizontal rows) are obstructed by walls,
    // halving the number of effective steps
    // With 60,000 total steps, about 30,000 are effective
    // Expected range for 30,000 steps is ~300
    // Since our path length (~300) is comparable to the expected range,
    // many test runs may not fully traverse the path, preventing synchronization
    int rows = 25;
    int cols = 25;

    // Output dimensions
    cout << rows << " " << cols << endl;

    // Initialize grid with walls ('#')
    vector<string> layout(rows, string(cols, '#'));

    // Build the snake pattern
    for (int r = 0; r < rows; ++r) {
        if (r % 2 == 0) {
            // Even rows (0, 2, ..., 24) are fully open corridors
            for (int c = 0; c < cols; ++c) {
                layout[r][c] = '.';
            }
        } else {
            // Odd rows have one opening to link adjacent even rows
            // Alternating connection points create a winding route
            // Row 1 links at right side (column 24)
            // Row 3 links at left side (column 0)
            // Pattern continues alternately
            if (r % 4 == 1) {
                // Connect at right end
                layout[r][cols - 1] = '.';
            } else {
                // Connect at left end
                layout[r][0] = '.';
            }
        }
    }

    // Display the constructed map
    for (int i = 0; i < rows; ++i) {
        cout << layout[i] << endl;
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <stack>
using namespace std;

// LeetCode 210: Course Schedule II - Modified Version
// This function determines the order in which courses can be completed given their prerequisites.
// We use DFS-based topological sorting to detect cycles and produce a valid course sequence.
class CourseScheduler {
public:
    // Helper function to detect cycles in the directed graph
    bool hasCycle(int node, vector<bool>& visited, vector<bool>& inRecursion, const vector<vector<int>>& adjList) {
        visited[node] = true;
        inRecursion[node] = true;

        // Traverse all edges to find neighbors of the current node
        for (int idx = 0; idx < adjList.size(); idx++) {
            int target = adjList[idx][0];
            int source = adjList[idx][1];

            // If this edge originates from the current node
            if (source == node) {
                if (!visited[target]) {
                    if (hasCycle(target, visited, inRecursion, adjList)) {
                        return true; // Cycle found in recursive call
                    }
                } else if (inRecursion[target]) {
                    return true; // Back edge indicates cycle
                }
            }
        }

        inRecursion[node] = false; // Remove node from recursion stack
        return false;
    }

    // Helper function to perform topological sort using DFS
    void topoSort(int node, vector<bool>& visited, stack<int>& orderStack, const vector<vector<int>>& adjList) {
        visited[node] = true;

        // Visit all unvisited neighbors
        for (int idx = 0; idx < adjList.size(); idx++) {
            int neighbor = adjList[idx][0];
            int src = adjList[idx][1];
            if (src == node && !visited[neighbor]) {
                topoSort(neighbor, visited, orderStack, adjList);
            }
        }

        orderStack.push(node); // Push node after processing all dependencies
    }

    vector<int> getOrder(int totalCourses, vector<vector<int>>& prereqList) {
        vector<bool> visited(totalCourses, false);
        vector<bool> inRecursion(totalCourses, false);

        // Check for cycles before proceeding with topological sort
        for (int course = 0; course < totalCourses; course++) {
            if (!visited[course]) {
                if (hasCycle(course, visited, inRecursion, prereqList)) {
                    return {}; // Cycle detected - impossible to complete all courses
                }
            }
        }

        // Reset visited array for topological sort
        fill(visited.begin(), visited.end(), false);
        stack<int> orderStack;
        vector<int> finalOrder;

        // Perform DFS-based topological sort on each unvisited node
        for (int course = 0; course < totalCourses; course++) {
            if (!visited[course]) {
                topoSort(course, visited, orderStack, prereqList);
            }
        }

        // Build result by popping from stack (reverses post-order to get topological order)
        while (!orderStack.empty()) {
            finalOrder.push_back(orderStack.top());
            orderStack.pop();
        }

        return finalOrder;
    }
};

#include <RegexPayloadProcessorHTTP.h>
#include <spdlog/spdlog.h>

void RegexPayloadProcessorHTTP::Process(http::request<http::string_body> const& request, tcp::socket& socket) {
    http::response<http::string_body> response;
    response.version(request.version());
    response.keep_alive(request.keep_alive());
    response.result(http::status::ok);
    response.set(http::field::content_type, "application/json; charset=UTF-8");
    response.set(http::field::vary, "Origin");

    for (const auto& [pattern, handler] : m_resMap) {
        if (std::regex_search(request.body(), pattern.m_rx)) {
            response.body() = handler->dump();
            response.prepare_payload();
            http::write(socket, response);
            return;
        }
    }

    spdlog::error("Regex processor {} failed to find any valid response for the packet, dropping the packet.\nPacket contents: {}", GetRoute(), request.body());
}

