  DecompositorClient client(grpc::CreateChannel(
      "localhost:50051", grpc::InsecureChannelCredentials()));

  int number_to_process = 42;
  std::string result = client.ProcessInteger(number_to_process);

  std::cout << "Response from server: " << result << std::endl;
  return 0;
}

