// Define a structure to hold pointer-to-member function metadata
struct PTMF {
    long this_delta;   // adjustment to the this pointer
    long vtbl_offset;  // offset within the virtual table (-1 indicates non-virtual)
    union {
        void* func_addr;     // address of non-virtual function
        long ventry_offset;  // index into virtual table for virtual function
    } func_data;
};

// Null PTMF constant initialization
const PTMF null_ptmf = { 0, 0, 0 };

/* clang-format off */
asm void check_ptmf(register PTMF* ptmf_ptr) {
  nofralloc
  lwz r5, PTMF.this_delta(ptmf_ptr)
  lwz r6, PTMF.vtbl_offset(ptmf_ptr)
  lwz r7, PTMF.func_data(ptmf_ptr)
  li r3, 1
  cmpwi cr0, r5, 0
  cmpwi cr6, r6, 0
  cmpwi cr7, r7, 0
  bnelr cr0
  bnelr cr6
  bnelr cr7
  li r3, 0
  blr
}

asm void call_ptmf(...) {
  nofralloc
  lwz r0, PTMF.this_delta(r12)
  lwz r11, PTMF.vtbl_offset(r12)
  lwz r12, PTMF.func_data(r12)
  add r3, r3, r0
  cmpwi r11, 0
  blt @label_1
  lwzx r12, r3, r12
  lwzx r12, r12, r11
@label_1 
  mtctr r12
  bctr
}
