#include <iostream>
#include <fstream>
#include <string>
#include <vector>

int main(int argc, char* argv[]) {
    std::string directoryPath = "";
    bool process_ok = true;
    std::cout << "Initiating diagnostic read for .ans files in " << directoryPath << std::endl;

    for (int index = 1; index <= 10; ++index) {
        std::string filePath = directoryPath + std::to_string(index) + ".ans";
        std::cout << "\n--- Processing file: " << filePath << " ---" << std::endl;

        std::ifstream inputStream(filePath);
        if (!inputStream.is_open()) {
            std::cerr << "  [ERROR] Unable to open the file. It may not exist." << std::endl;
            process_ok = false;
            continue;
        }

        // Verify if the file is empty
        if (inputStream.peek() == std::ifstream::traits_type::eof()) {
            std::cerr << "  [ERROR] File has no content." << std::endl;
            process_ok = false;
            inputStream.close();
            continue;
        }

        std::vector<std::pair<int, int>> dataPairs;
        int row, col;
        while (inputStream >> row >> col) {
            dataPairs.emplace_back(row, col);
        }

        // Determine why the reading loop ended
        if (inputStream.eof()) {
            // Expected case: reached end of file naturally
            if (dataPairs.empty()) {
                std::cerr << "  [WARNING] File accessible but contained no valid integer pairs." << std::endl;
            } else {
                std::cout << "  [SUCCESS] Parsed " << dataPairs.size() << " integer pairs successfully." << std::endl;
            }
        } else if (inputStream.fail()) {
            // Error case: parsing stopped due to invalid input
            std::cerr << "  [ERROR] Parsing failed. File likely contains non-integer or malformed data." << std::endl;
            process_ok = false;
        }

        inputStream.close();
    }

    std::cout << "\n--- Final Report ---" << std::endl;
    if (process_ok) {
        std::cout << "All analyzed .ans files were processed without issues." << std::endl;
    } else {
        std::cout << "Some .ans files encountered problems during processing. Check the details above." << std::endl;
    }

    return 0;
}

