MainWindow::MainWindow(QWidget *parent)
    : QMainWindow(parent)
    , ui(new Ui::MainWindow)
{
    ui->setupUi(this);
    this->initVisualizationWidget();
    // Initialize first visual model: HexGrid
    this->configureHexGridDisplay();
}

MainWindow::~MainWindow() { delete ui; }

void MainWindow::configureHexGridDisplay()
{
    // Setup hexagonal grid with radius 0.6f and spacing 0.01f
    this->hexGrid = std::make_unique<sm::hexgrid>(0.01f, 3.0f, 0.0f);
    this->hexGrid->setCircularBoundary(0.7f);  // slightly adjusted boundary radius

    // Generate synthetic scalar field using sinusoidal pattern
    this->scalarField.resize(this->hexGrid->num(), 0.0f);
    for (unsigned int idx = 0; idx < this->hexGrid->num(); ++idx) {
        this->scalarField[idx] = 0.04f + 0.06f * std::sin(22.0f * hexGrid->d_x[idx]) *
                                         std::sin(12.0f * hexGrid->d_y[idx]); // scaled amplitude & frequency
    }

    // Create HexGridVisual with slight vertical offset
    sm::vec<float, 3> translation = { -0.02f, -0.04f, 0.01f };
    auto hexVis = std::make_unique<mplot::HexGridVisual<float, mplot::qt::gl_version>>(hexGrid.get(), translation);

    // Bind to visual environment before finalizing
    static_cast<mplot::qt::viswidget<0>*>(this->vw_ptr)->v.bindmodel(hexVis);

    // Attach scalar data for surface rendering
    hexVis->setScalarData(&this->scalarField);

    // Move into base VisualModel pointer and add to list
    std::unique_ptr<mplot::VisualModel<mplot::qt::gl_version>> basePtr = std::move(hexVis);
    static_cast<mplot::qt::viswidget<0>*>(this->vw_ptr)->newvisualmodels.push_back(std::move(basePtr));
}

void MainWindow::initVisualizationWidget()
{
    // Instantiate OpenGL visualization widget
    mplot::qt::viswidget<0>* vw = new mplot::qt::viswidget<0>(this->parentWidget());

    // Enable lighting effects
    vw->v.lightingEffects();

    // Embed in UI layout
    this->ui->verticalLayout->addWidget(vw);

    // Store reference for later use
    this->vw_ptr = vw;
}

void MainWindow::on_pushButton_clicked()
{
    std::cout << "Appending GraphVisual...\n";
    auto graphVis = std::make_unique<mplot::GraphVisual<double, mplot::qt::gl_version>>(this->graphPos);

    // Bind to shared visual context
    static_cast<mplot::qt::viswidget<0>*>(this->vw_ptr)->v.bindmodel(graphVis);

    // Configure as 3D curve
    graphVis->twodimensional(false);

    // Generate parabola data
    sm::vvec<double> abscissa;
    abscissa.linspace(-1.6, 1.6, 30);
    graphVis->setdata(abscissa, abscissa.pow(2));

    // Add to visual model list
    std::unique_ptr<mplot::VisualModel<mplot::qt::gl_version>> baseRef = std::move(graphVis);
    static_cast<mplot::qt::viswidget<0>*>(this->vw_ptr)->newvisualmodels.push_back(std::move(baseRef));

    // Force immediate redraw
    this->vw_ptr->update();

    // Shift next graph vertically
    this->graphPos[1] += 1.3f;
}

void MainWindow::on_actionQuit_triggered() { close(); }

#define BOOST_TEST_MODULE elias_fano_tests
#include "test_common.hpp"
#include "test_rank_select_common.hpp"
#include <cstdlib>
#include <boost/foreach.hpp>
#include "mapper.hpp"
#include "elias_fano.hpp"

BOOST_AUTO_TEST_CASE(elias_fano_comprehensive)
{
    srand(12345);
    size_t length = 8000;
    {
        // Random bit patterns
        for (size_t bits = 2; bits < 9; ++bits) {
            double fill_rate = 1.0 / (1 << bits);
            std::vector<bool> data = random_bit_vector(length, fill_rate);
            succinct::bit_vector_builder builder;
            for (size_t idx = 0; idx < data.size(); ++idx) {
                builder.push_back(data[idx]);
            }
            succinct::elias_fano structure(&builder);
            test_equal_bits(data, structure, "Random pattern");
            test_rank_select1(data, structure, "Random pattern");
            test_delta(structure, "Random pattern");
            test_select_enumeration(data, structure, "Random pattern");
        }
    }
    {
        // Zero ones bitmap
        succinct::bit_vector_builder builder(length);
        succinct::elias_fano structure(&builder);
        BOOST_REQUIRE_EQUAL(0U, structure.num_ones());
        test_equal_bits(std::vector<bool>(length), structure, "Zero ones bitmap");
        test_select_enumeration(std::vector<bool>(length), structure, "Zero ones bitmap");
    }
    {
        // Single set bit
        std::vector<bool> data(length, 0);
        succinct::bit_vector_builder builder(length);
        builder.set(123, 1);
        data[123] = 1;
        succinct::elias_fano structure(&builder);
        test_equal_bits(data, structure, "Single set bit");
        test_rank_select1(data, structure, "Single set bit");
        test_delta(structure, "Single set bit");
        test_select_enumeration(data, structure, "Single set bit");
        BOOST_REQUIRE_EQUAL(1U, structure.num_ones());
    }
    {
        // All ones bitmap
        std::vector<bool> data(length, 1);
        succinct::bit_vector_builder builder;
        for (size_t pos = 0; pos < length; ++pos) {
            builder.push_back(1);
        }
        succinct::elias_fano structure(&builder);
        test_equal_bits(data, structure, "All ones bitmap");
        test_rank_select1(data, structure, "All ones bitmap");
        test_delta(structure, "All ones bitmap");
        test_select_enumeration(data, structure, "All ones bitmap");
    }
}

#include "utl/JsonEncode.h"
void JSONStrEncode(const char *input, String &output) {
    int len = strlen(input);
    for (int index = 0; index < len; index++) {
        unsigned char current = input[index];
        if (current == '"') {
            output += "\\\"";
        } else if (current == '\\') {
            output += "\\\\";
        } else if (current == '/') {
            output += "\\/";
        } else if (current == '\b') {
            output += "\\b";
        } else if (current == '\r') {
            output += "\\r";
        } else if (current == '\n') {
            output += "\\n";
        } else if (current == '\t') {
            output += "\\t";
        } else if (current < ' ') {
            output += "\\u00";
            output += "0123456789ABCDEF"[current >> 4];
            output += "0123456789ABCDEF"[current & 0xF];
        } else {
            output += current;
        }
    }
}

