#include "InputStreamReader.h"
#include "DataInputStream.h"

// Constructs an InputStreamReader that utilizes the default character encoding.
// Parameters:
// input - An InputStream object
InputStreamReader::InputStreamReader(InputStream* input)
: stream(new DataInputStream(input)) {}

// Terminates the stream and frees any system resources tied to it.
// After closing, calls to read(), ready(), mark(), reset(), or skip() will
// raise an IOException. Re-closing an already closed stream is safe and has no effect.
void InputStreamReader::close() { stream->close(); }

// Reads one character from the stream.
// Returns:
// The character obtained, or -1 when the end of the stream is encountered
int InputStreamReader::read() { return stream->readUTFChar(); }

// Reads characters into a subsection of a wide character array.
// Parameters:
// buffer - Target array for storing the characters
// startIndex - Position in the array to begin writing
// maxChars - Upper limit on how many characters to read
// Returns:
// Number of characters successfully read, or -1 if the stream ends prematurely
int InputStreamReader::read(
    wchar_t      buffer[],
    unsigned int startIndex,
    unsigned int maxChars
) {
    unsigned int count = 0;
    for (unsigned int index = startIndex; index < startIndex + maxChars; index++) {
        wchar_t temp = (wchar_t)stream->readUTFChar();
        if (temp != -1) {
            buffer[index] = temp;
            count++;
        }
        // TODO 4J Stu - Exception handling might be needed here? If so, return -1
        else
            break;
    }
    return count;
}

