using namespace llvm;

namespace tpa
{
namespace
{
// Determines whether a CFG node belongs to the top-level category.
// Top-level nodes (Alloc, Copy, Offset) influence only top-level pointer variables (Env).
// They neither read from nor write to the memory Store.
bool isTopLevelNode(const CFGNode* node)
{
	return node->isAllocNode() || node->isCopyNode() || node->isOffsetNode();
}
} // namespace

// Updates the memoization structure and returns true if the stored state was modified.
// If the state at this program point has changed, the point is inserted into the worklist
// to propagate the updated information to its successors.
bool SemiSparsePropagator::enqueueIfMemoChange(const ProgramPoint& pp, const Store& store)
{
	if (memo.update(pp, store))
	{
		workList.enqueue(pp);
		return true;
	}
	else
		return false;
}

// Handles flow for top-level nodes (Alloc, Copy, Offset).
// Since these nodes do not alter the Store, we unconditionally enqueue
// the successor program point. Env modifications occur in-place globally
// (handled by TransferFunction/GlobalState).
void SemiSparsePropagator::propagateTopLevel(const EvalSuccessor& evalSucc)
{
	// Top-level successors: no store merging, just enqueue
	workList.enqueue(evalSucc.getProgramPoint());
	//errs() << "\tENQ(T) " << evalSucc.getProgramPoint() << "\n";
}

// Handles flow for memory-level nodes (Load, Store, Call, Ret).
// These nodes interact with the Store. We must verify whether the outgoing Store
// differs from previously observed states at the successor point.
void SemiSparsePropagator::propagateMemLevel(const EvalSuccessor& evalSucc)
{
	// Mem-level successors: store merging, enqueue if memo updated
	const auto *node = evalSucc.getProgramPoint().getCFGNode();
	assert(!isTopLevelNode(node));
	assert(evalSucc.getStore() != nullptr);

	// Determine if the store state has changed at this program point.
	// If so, update the memo table and insert into worklist.
	bool enqueued = enqueueIfMemoChange(evalSucc.getProgramPoint(), *evalSucc.getStore());
	//if (enqueued)
	//	errs() << "\tENQ(M) " << evalSucc.getProgramPoint() << "\n";
}

// Primary propagation entry point.
// Traverses all successors generated by evaluating the transfer function
// and routes each to the appropriate propagation handler.
void SemiSparsePropagator::propagate(const EvalResult& evalResult)
{
	for (auto const& evalSucc : evalResult)
	{
		if (evalSucc.isTopLevel())
			propagateTopLevel(evalSucc);
		else
			propagateMemLevel(evalSucc);
	}
}
} // namespace tpa

