#define ROCP_REG_VERSION                                                                 \
    ROCPROFILER_REGISTER_COMPUTE_VERSION_3(                                              \
        HSA_VERSION_MAJOR, HSA_VERSION_MINOR, HSA_VERSION_PATCH)

ROCPROFILER_REGISTER_DEFINE_IMPORT(hsa, ROCP_REG_VERSION)

#ifndef ROCP_REG_FILE_NAME
#    define ROCP_REG_FILE_NAME                                                           \
        ::std::string{ __FILE__ }                                                        \
            .substr(::std::string_view{ __FILE__ }.find_last_of('/') + 1)                \
            .c_str()
#endif

namespace hsa
{
namespace
{
auto&
get_hsa_api_table_instance()
{
    static auto _api_table = std::atomic<HsaApiTable*>{ nullptr };
    return _api_table;
}

void
init_profiler_impl()
{
    static auto _base_api_table = HsaApiTable{};
    initialize_hsa_api_table(&_base_api_table);

    // establish initial table before any recursive calls
    get_hsa_api_table_instance().exchange(&_base_api_table);

    // prepare modified copy for profiler instrumentation
    static auto _instrumented_api_table = HsaApiTable{};
    copy_hsa_api_table(&_instrumented_api_table, &_base_api_table);

    void* _profiler_table_ptr = static_cast<void*>(&_instrumented_api_table);

    rocprofiler_register_library_indentifier_t lib_identifier{};
    auto registration_result =
        rocprofiler_register_library_api_table("hsa",
                                               &ROCPROFILER_REGISTER_IMPORT_FUNC(hsa),
                                               ROCP_REG_VERSION,
                                               &_profiler_table_ptr,
                                               1,
                                               &lib_identifier);

    if(registration_result == 0)
    {
        printf("[%s] hsa identifier %lu\n", ROCP_REG_FILE_NAME, lib_identifier.handle);

        auto* _current_table = &_base_api_table;
        if(!get_hsa_api_table_instance().compare_exchange_strong(_current_table,
                                                                &_instrumented_api_table))
        {
            std::cerr
                << "init_profiler_impl expected the API table to be the internal "
                   "implementation but it differs. unexpected condition occurred.\n";
            abort();
        }
    }
    else if(registration_result != ROCP_REG_NO_TOOLS)
    {
        std::cerr << "HSA library failed to register with rocprofiler-register: "
                  << rocprofiler_register_error_string(registration_result) << "\n";
        exit(EXIT_FAILURE);
    }
}

void
init_profiler()
{
    // optimization: minimal overhead after initialization via atomic check
    // handles concurrent registration attempts properly
    static auto _is_initialized = std::atomic<bool>{ false };
    if(!_is_initialized.load(std::memory_order_acquire))
    {
        using lock_type      = std::recursive_mutex;
        using guard_type     = std::unique_lock<lock_type>;
        static auto _init_flag  = std::once_flag{};
        static auto _sync_mutex = lock_type{};

        guard_type _lk{ _sync_mutex, std::defer_lock };

        // prevent deadlock when same thread re-enters during registration
        if(_lk.owns_lock()) return;

        _lk.lock();

        std::call_once(_init_flag, init_profiler_impl);

        _is_initialized.exchange(true, std::memory_order_release);
    }
}
}  // namespace

HsaApiTable*
fetch_hsa_api_table()
{
    init_profiler();
    return get_hsa_api_table_instance().load(std::memory_order_relaxed);
}

void
initialize_hsa_runtime()
{
    printf("[%s] %s\n", ROCP_REG_FILE_NAME, __FUNCTION__);
}
}  // namespace hsa

extern "C" {
void
hsa_init(void)
{
    hsa::fetch_hsa_api_table()->hsa_init_fn();
}
}

