#include "ReduceFunctions.h"
#include "Delta.h"
#include "Utils.h"
#include "llvm/ADT/STLExtras.h"
#include "llvm/Transforms/Utils/ModuleUtils.h"
#include <iterator>
using namespace llvm;

// Eliminates functions that are not part of the selected test chunks
static void filterUnusedFunctions(Oracle &O, ReducerWorkItem &WorkItem) {
  Module &Program = WorkItem.getModule();

  // Collect functions to be removed based on criteria
  SmallPtrSet<Constant *, 8> FunctionsToErase;
  for (Function &Func : Program.functions()) {
    // Skip intrinsics unless they're unused or have no meaningful body
    if ((!Func.isIntrinsic() || Func.use_empty()) && 
        !hasAliasOrBlockAddressUse(Func) &&
        !O.shouldKeep()) {
      FunctionsToErase.insert(&Func);
    }
  }

  // Remove from used lists first
  removeFromUsedLists(Program, [&FunctionsToErase](Constant *C) {
    return FunctionsToErase.count(C);
  });

  // Clear function bodies in batch before deletion
  for (Constant *F : FunctionsToErase)
    F->dropAllReferences();

  // Final cleanup: replace remaining uses and erase functions
  for (Constant *F : FunctionsToErase) {
    // Substitute remaining uses with default value
    F->replaceAllUsesWith(getDefaultValue(F->getType()));

    // Erase the function from the module
    cast<Function>(F)->eraseFromParent();
  }
}

void llvm::reduceFunctionsDeltaPass(TestRunner &Test) {
  runDeltaPass(Test, filterUnusedFunctions, "Filtering Functions");
}

#include "Alias/TPA/Context/Context.h"
#include "Alias/TPA/Context/ProgramPoint.h"
using namespace llvm;
namespace context {

// Adds a new context frame to the top of the current context stack.
// This overload accepts a ProgramPoint, and internally extracts the context and instruction.
const Context *Context::pushContext(const ProgramPoint &pp) {
  return pushContext(pp.getContext(), pp.getInstruction());
}

// Adds a new context frame.
// Parameters:
//   callerCtx - The calling function's context (current context).
//   callInst - The call instruction representing the call site.
// Returns: A pointer to the unique interned Context object representing the updated state.
const Context *Context::pushContext(const Context *callerCtx,
                                    const Instruction *callInst) {
  // Construct a temporary context object
  auto updatedCtx = Context(callInst, callerCtx);
  // Insert into the set. 'itr' will point to either the existing or newly inserted element.
  auto itr = ctxSet.insert(updatedCtx).first;
  return &(*itr);
}

// Removes the topmost context frame.
// Returns the preceding context (i.e., the caller's context).
const Context *Context::popContext(const Context *ctx) {
  assert(ctx->depth != 0 && "Attempting to pop from an empty context");
  return ctx->callerContext;
}

// Accesses the single Global Context instance.
// Used for global variables and the initial analysis entry point.
const Context *Context::getGlobalContext() {
  auto itr = ctxSet.insert(Context()).first;
  return &(*itr);
}

// Utility to obtain all contexts created so far.
// Helpful for diagnostics or reporting purposes.
std::vector<const Context *> Context::getAllContexts() {
  std::vector<const Context *> result;
  result.reserve(ctxSet.size());
  for (auto const &ctx : ctxSet)
    result.push_back(&ctx);
  return result;
}
} // namespace context

#include <vector>
#include <algorithm>

class Solution {
public:
    int findContentChildren(std::vector<int>& g, std::vector<int>& s) {
        int sizeG = g.size();
        int sizeS = s.size();

        std::sort(g.begin(), g.end());
        std::sort(s.begin(), s.end());

        int indexG = 0;
        int indexS = 0;
        int satisfiedCount = 0;

        while (indexG < sizeG && indexS < sizeS) {
            if (g[indexG] <= s[indexS]) {
                satisfiedCount++;
                indexG++;
                indexS++;
            } else {
                indexS++;
            }
        }

        return satisfiedCount;      
    }
};

