    // Normalize line endings in the input string according to the specified type
    std::string NormalizeLineEndings(const std::string &input, LineEnding format) {
        if(format == LineEnding::Mixed) return input;

        std::string output;
        output.reserve(input.size());

        for(auto iter = input.begin(); iter != input.end(); ++iter) {
            if(*iter == '\x0d') {
                // Check for following LF
                ++iter;
                if(iter != input.end()) {
                    // If not LF, backtrack to reprocess next char
                    if(*iter != '\x0a') --iter; 
                }

                // Append appropriate line ending based on target format
                if((int)format & (int)LineEnding::CR)
                    output.push_back('\x0d');
                if((int)format & (int)LineEnding::LF)
                    output.push_back('\x0a');
            }
            else if(*iter >= '\x0a' && *iter <= '\x0c') {
                // Handle standalone LF, VT, or FF characters
                if((int)format & (int)LineEnding::CR)
                    output.push_back('\x0d');
                if((int)format & (int)LineEnding::LF)
                    output.push_back('\x0a');
            }
            else {
                output.push_back(*iter);
            }
        }
        return output;
    }

}

#include "comms/torchcomms/ncclx/TorchWorkNCCLX.hpp"

namespace torch::comms {

// Perform cleanup of completed or failed work items in the queue
TorchWorkNCCLX::WorkStatus TorchWorkNCCLXQueue::garbageCollectLocked() {
  TorchWorkNCCLX::WorkStatus prev_status =
      TorchWorkNCCLX::WorkStatus::COMPLETED;

  // Iterate through all stream queues and remove finished work items
  auto iter = stream_work_queues_.begin();
  while (iter != stream_work_queues_.end()) {
    auto& pending_queue = iter->second;

    while (!pending_queue.empty()) {
      // Examine the earliest work item in the current queue
      auto task = pending_queue.front();

      // Query the current status of the work item
      TorchWorkNCCLX::WorkStatus current_state = task->checkStatus();
      prev_status = current_state;

      if (current_state == TorchWorkNCCLX::WorkStatus::COMPLETED) {
        // Remove completed work from the queue
        pending_queue.pop();
      } else if (
          current_state == TorchWorkNCCLX::WorkStatus::TIMEDOUT ||
          current_state == TorchWorkNCCLX::WorkStatus::ERROR) {
        // Propagate terminal error states immediately
        return current_state;
      } else {
        // Work still in progress or not started — stop processing this queue
        break;
      }
    }

    // Remove empty stream queues to avoid unnecessary memory usage
    if (pending_queue.empty()) {
      iter = stream_work_queues_.erase(iter);
    } else {
      ++iter;
    }
  }

  return prev_status;
}

// Thread-safe wrapper for garbage collection using mutex protection
TorchWorkNCCLX::WorkStatus TorchWorkNCCLXQueue::garbageCollect() {
  std::lock_guard<std::mutex> guard(queue_mutex_);
  return garbageCollectLocked();
}

// Finalize all pending work and clean up resources
TorchWorkNCCLX::WorkStatus TorchWorkNCCLXQueue::finalize() {
  // Defensive locking even though timeout thread may already be joined
  std::lock_guard<std::mutex> guard(queue_mutex_);

  // Default to COMPLETED if no work exists
  TorchWorkNCCLX::WorkStatus result = TorchWorkNCCLX::WorkStatus::COMPLETED;

  while (!stream_work_queues_.empty()) {
    result = garbageCollectLocked();
    if (result == TorchWorkNCCLX::WorkStatus::ERROR ||
        result == TorchWorkNCCLX::WorkStatus::TIMEDOUT ||
        result == TorchWorkNCCLX::WorkStatus::COMPLETED) {
      break;
    }
  }

  // Ensure all remaining work references are released to prevent leaks
  stream_work_queues_.clear();
  return result;
}

// Add new work item to the appropriate stream's queue
void TorchWorkNCCLXQueue::enqueueWork(
    c10::intrusive_ptr<TorchWorkNCCLX> task,
    cudaStream_t stream_id) {
  std::lock_guard<std::mutex> guard(queue_mutex_);
  stream_work_queues_[stream_id].push(std::move(task));
}

