#include <iostream>

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    // Phase 1: Initialization.
    // Input string is represented as sSt.
    // Convert S to Q and preserve t in backup using alphabet {A, B, C}.
    std::cout << "S=Q#" << std::endl;
    std::cout << "#a=a#A" << std::endl;
    std::cout << "#b=b#B" << std::endl;
    std::cout << "#c=c#C" << std::endl;
    // Now the string becomes `s Q t # t_ABC`.

    // Insert marker `L` at start of s.
    std::cout << "a=La" << std::endl;
    std::cout << "b=Lb" << std::endl;
    std::cout << "c=Lc" << std::endl;
    std::cout << "L=E" << std::endl;
    // String now is `E s Q t # t_ABC`. E acts as sliding pointer.

    // Phase 2: Main matching loop.
    // Transition E to match state J.
    std::cout << "E=J" << std::endl;

    // Matching transitions:
    std::cout << "JaQa=J" << std::endl;
    std::cout << "JbQb=J" << std::endl;
    std::cout << "JcQc=J" << std::endl;

    // Match success when all of t consumed:
    std::cout << "JQ#=(return)1" << std::endl;

    // Mismatch rules:
    std::cout << "JaQb=W" << std::endl;
    std::cout << "JaQc=W" << std::endl;
    std::cout << "JbQa=W" << std::endl;
    std::cout << "JbQc=W" << std::endl;
    std::cout << "JcQa=W" << std::endl;
    std::cout << "JcQb=W" << std::endl;

    // Mismatch recovery:
    // W cleans up partial match and restores t, then advances E.
    std::cout << "aW=Wa" << std::endl;
    std::cout << "bW=Wb" << std::endl;
    std::cout << "cW=Wc" << std::endl;
    std::cout << "JW=WJ" << std::endl; // Move W past original J position.

    // When W reaches front of remaining s:
    // `prefix W J rest...` -> advance logical position of E.
    std::cout << "WJ=E" << std::endl;

    // Restore t when E moves forward:
    std::cout << "EaQ=EaU" << std::endl;
    std::cout << "EbQ=EbU" << std::endl;
    std::cout << "EcQ=EcU" << std::endl;
    std::cout << "E#=E_U" << std::endl; // Handle empty t case

    // U (restore) phase:
    std::cout << "Ua=U" << std::endl;
    std::cout << "Ub=U" << std::endl;
    std::cout << "Uc=U" << std::endl;
    std::cout << "U#=V" << std::endl;

    // V copies from backup alphabet {A,B,C}:
    std::cout << "VA=aV" << std::endl;
    std::cout << "VB=bV" << std::endl;
    std::cout << "VC=cV" << std::endl;

    // Finalize restoration:
    std::cout << "aV=aQ" << std::endl;
    std::cout << "bV=bQ" << std::endl;
    std::cout << "cV=cQ" << std::endl;
    std::cout << "V=Q" << std::endl;

    // Termination when E scans entire s:
    std::cout << "EQ=(return)0" << std::endl;

    return 0;
}

