// Memoization map to store previously queried matrix values
std::map<std::pair<int, int>, long long> cache;
long long matrix_size;

// Function to query a cell (r, c) and store the result in cache
long long fetch_value(int row, int col) {
    if (cache.count({row, col})) {
        return cache[{row, col}];
    }

    std::cout << "QUERY " << row << " " << col << std::endl;
    long long value;
    std::cin >> value;

    // Handle input failure (e.g., judge error or unexpected termination)
    if (std::cin.fail()) {
        exit(0);
    }

    // Store result in cache before returning
    return cache[{row, col}] = value;
}

// Count how many elements in the matrix are <= target_value
// Uses staircase traversal pattern, making at most 2*matrix_size queries
long long count_less_equal(long long target_value) {
    long long total = 0;
    int column = matrix_size;

    for (int row = 1; row <= matrix_size; ++row) {
        // Move left while current value is greater than target
        while (column > 0 && fetch_value(row, column) > target_value) {
            column--;
        }
        total += column;
    }

    return total;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    long long k_position;
    std::cin >> matrix_size >> k_position;

    long long low, high;
    if (matrix_size > 0) {
        // Set initial search bounds using corner values
        low = fetch_value(1, 1);
        high = fetch_value(matrix_size, matrix_size);
    } else {
        // Handle edge case where matrix_size is zero
        std::cout << "DONE " << 0 << std::endl;
        return 0;
    }

    long long result = high;

    // Binary search for the k-th smallest element
    while (low <= high) {
        long long mid = low + (high - low) / 2;

        if (count_less_equal(mid) >= k_position) {
            result = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }

    std::cout << "DONE " << result << std::endl;
    return 0;
}

