                break;
            } else {
                // Moved away from exit (child node), so backtrack
                cout << "move " << color << endl;
                cin >> response;

                if (response == 1) {
                    // Exit reached during backtracking
                    return 0;
                }
                // Continue with next color option
            }
        }
    }

    return 0;
}

