// Function to execute a move command and get the response from the system
int perform_move(int color) {
    std::cout << "move " << color << std::endl;
    int response;
    std::cin >> response;
    return response;
}

// Function to request the current distance to the target
int request_distance() {
    std::cout << "query" << std::endl;
    int distance;
    std::cin >> distance;
    return distance;
}

int main() {
    // Optimize I/O for competitive programming scenarios
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int starting_depth;
    std::cin >> starting_depth;
    int remaining_distance = starting_depth;

    // If already at the destination, exit immediately
    if (remaining_distance == 0) {
        return 0;
    }

    int incoming_color;

    // --- Initial exploration phase ---
    // With no prior knowledge, test colors 0 and 1 first
    // If both go deeper, then color 2 must be the upward direction
    int upward_direction = -1;
    for (int trial_color = 0; trial_color < 2; ++trial_color) {
        if (perform_move(trial_color) == 1) {
            return 0;
        }
        int new_dist = request_distance();
        if (new_dist < remaining_distance) {
            upward_direction = trial_color;
            break;
        }
        perform_move(trial_color); // Return to original position
    }

    if (upward_direction == -1) {
        upward_direction = 2;
        if (perform_move(upward_direction) == 1) {
            return 0;
        }
    }

    remaining_distance--;
    incoming_color = upward_direction;

    // --- Main navigation loop ---
    // Now we know the incoming edge color, which points downward.
    // We only need to test the remaining two possible directions.
    while (remaining_distance > 0) {
        // Compute the two alternative colors using modular arithmetic
        int alt_color_1 = (incoming_color + 1) % 3;
        int alt_color_2 = (incoming_color + 2) % 3;

        // Try the first alternative
        if (perform_move(alt_color_1) == 1) {
            return 0;
        }
        int updated_dist = request_distance();

        if (updated_dist < remaining_distance) {
            // First alternative leads upward
            upward_direction = alt_color_1;
        } else {
            // First alternative goes deeper; revert and try second
            perform_move(alt_color_1);
            upward_direction = alt_color_2;
            if (perform_move(upward_direction) == 1) {
                return 0;
            }
        }

        remaining_distance--;
        incoming_color = upward_direction;
    }

    return 0;
}

