#include <vector>
#include <algorithm>

class Solution {
public:
    // Find the maximum profit achievable from a single buy-sell transaction
    int maxProfit(std::vector<int>& stockPrices) {
        int size = stockPrices.size();
        int bestProfit = 0;
        int minPriceSoFar = stockPrices[0];

        for (int day = 0; day < size; day++) {
            minPriceSoFar = std::min(stockPrices[day], minPriceSoFar);
            int currentProfit = stockPrices[day] - minPriceSoFar;
            bestProfit = std::max(bestProfit, currentProfit);
        }

        return bestProfit;
    }
};

