    options.AddLongOption("threads", "Number of worker threads (default: number of CPUs)")
        .RequiredArgument("N")
        .DefaultValue("0")
        .StoreResult(&threadCount);

    NLastGetopt::TOptsParseResult(&options, argc, argv);

    const int cpuCount = GetOnlineCpuCount();
    const int activeThreads = (threadCount > 0) ? threadCount : cpuCount;

    std::vector<std::thread> pool;
    pool.reserve(activeThreads);

    for (int idx = 0; idx < activeThreads; ++idx) {
        int assignedCpu = idx % cpuCount;
        int workerIdx = idx % static_cast<int>(Workers.size());
        pool.emplace_back([assignedCpu, workerIdx]() {
            SetCpuAffinity(assignedCpu);
            Workers[workerIdx]();
        });
    }

    sleep(runTime);
    gKeepRunning.store(false, std::memory_order_relaxed);

    for (auto& t : pool) {
        t.join();
    }

    return 0;
}

