    PathUndoRedoer undoManager;
    QCOMPARE(undoManager.undoPathAvailable(), false);
    undoManager("step1");
    QCOMPARE(undoManager.undoPathAvailable(), false);
    QCOMPARE(undoManager.undoStack.size(), 1); // "step1", "step2"
    QCOMPARE(undoManager.undoStack.top(), "step1");
    undoManager("step2");
    QCOMPARE(undoManager.undoPathAvailable(), true);
    QCOMPARE(undoManager.undoStack.size(), 2); // "step1", "step2"
    QCOMPARE(undoManager.undoStack.top(), "step2");
    QCOMPARE(undoManager.redoPathAvailable(), false);
    QCOMPARE(undoManager.redoStack.isEmpty(), true);
    QCOMPARE(undoManager.onRedoPath(), ""); // cannot redo, try redo, nothing happens
    QCOMPARE(undoManager.undoPathAvailable(), true);
    QCOMPARE(undoManager.undoStack.size(), 2); // "step1", "step2"
    QCOMPARE(undoManager.undoStack.top(), "step2");
    QCOMPARE(undoManager.redoPathAvailable(), false);
    QCOMPARE(undoManager.redoStack.isEmpty(), true);
    QCOMPARE(undoManager.onUndoPath(), "step1");
    QCOMPARE(undoManager.undoPathAvailable(), false);
    QCOMPARE(undoManager.undoStack.size(), 1); // "step1"
    QCOMPARE(undoManager.undoStack.top(), "step1");
    QCOMPARE(undoManager.redoPathAvailable(), true);
    QCOMPARE(undoManager.redoStack.size(), 1); // "step2"
    QCOMPARE(undoManager.redoStack.top(), "step2");
    undoManager.onRedoPath();
    QCOMPARE(undoManager.undoPathAvailable(), true);
    QCOMPARE(undoManager.undoStack.size(), 2); // "step1", "step2"
    QCOMPARE(undoManager.undoStack.top(), "step2");
    QCOMPARE(undoManager.redoPathAvailable(), false);
    QCOMPARE(undoManager.redoStack.isEmpty(), true); // ""
    undoManager("step3");
    QCOMPARE(undoManager.undoPathAvailable(), true);
    QCOMPARE(undoManager.undoStack.size(), 3); // "step1", "step2", "step3"
    QCOMPARE(undoManager.undoStack.top(), "step3");
    QCOMPARE(undoManager.redoPathAvailable(), false);
    QCOMPARE(undoManager.redoStack.isEmpty(), true); // ""
    undoManager("step4");
    QCOMPARE(undoManager.undoPathAvailable(), true);
    QCOMPARE(undoManager.undoStack.size(), 4); // "step1", "step2", "step3", "step4"
    QCOMPARE(undoManager.undoStack.top(), "step4");
    QCOMPARE(undoManager.redoPathAvailable(), false);
    QCOMPARE(undoManager.redoStack.isEmpty(), true); // ""
    QCOMPARE(undoManager.onUndoPath(), "step3");
    QCOMPARE(undoManager.undoPathAvailable(), true);
    QCOMPARE(undoManager.undoStack.size(), 3); // "step1", "step2", "step3"
    QCOMPARE(undoManager.undoStack.top(), "step3");
    QCOMPARE(undoManager.redoPathAvailable(), true);
    QCOMPARE(undoManager.redoStack.size(), 1); // "step4"
    QCOMPARE(undoManager.redoStack.top(), "step4");
    QCOMPARE(undoManager.onUndoPath(), "step2");
    QCOMPARE(undoManager.undoPathAvailable(), true);
    QCOMPARE(undoManager.undoStack.size(), 2); // "step1", "step2"
    QCOMPARE(undoManager.undoStack.top(), "step2");
    QCOMPARE(undoManager.redoPathAvailable(), true);
    QCOMPARE(undoManager.redoStack.size(), 2); // "step4", "step3"
    QCOMPARE(undoManager.redoStack.top(), "step3");
    QCOMPARE(undoManager.onUndoPath(), "step1");
    QCOMPARE(undoManager.undoPathAvailable(), false);
    QCOMPARE(undoManager.undoStack.size(), 1); // "step1"
    QCOMPARE(undoManager.undoStack.top(), "step1");
    QCOMPARE(undoManager.redoPathAvailable(), true);
    QCOMPARE(undoManager.redoStack.size(), 3); // "step4", "step3", "step2"
    QCOMPARE(undoManager.redoStack.top(), "step2");
    QCOMPARE(undoManager.onUndoPath(), ""); // cannot undo, try undo, nothing happens
