// Constructs a new byte array output stream with an initial buffer capacity of 32 bytes
ByteArrayOutputStream::ByteArrayOutputStream() {
    dataOffset = 0;
    buffer     = byteArray(32);
}

// Constructs a new byte array output stream with the specified initial capacity
ByteArrayOutputStream::ByteArrayOutputStream(unsigned int initialCapacity) {
    dataOffset = 0;
    buffer     = byteArray(initialCapacity);
}

ByteArrayOutputStream::~ByteArrayOutputStream() {
    if (buffer.data != nullptr) delete[] buffer.data;
}

// Writes a single byte to the stream
void ByteArrayOutputStream::write(unsigned int value) {
    // Expand buffer if needed
    if (dataOffset + 1 >= buffer.length) buffer.resize(buffer.length * 2);
    buffer[dataOffset] = static_cast<byte>(value);
    dataOffset++;
}

// Writes all bytes from the given array to the stream
void ByteArrayOutputStream::write(byteArray source) { 
    write(source, 0, source.length); 
}

// Writes a subsequence of bytes from the given array to the stream
void ByteArrayOutputStream::write(
    byteArray    source,
    unsigned int startIndex,
    unsigned int countToWrite
) {
    assert(source.length >= startIndex + countToWrite);

    // Ensure sufficient buffer space
    if (dataOffset + countToWrite >= buffer.length)
        buffer.resize(std::max(dataOffset + countToWrite + 1, buffer.length * 2));

    XMemCpy(&buffer[dataOffset], &source[startIndex], countToWrite);
    dataOffset += countToWrite;
}

// No-op: closing this stream has no effect
void ByteArrayOutputStream::close() {}

// Returns a copy of the current contents of the stream as a new byte array
byteArray ByteArrayOutputStream::toByteArray() {
    byteArray result(dataOffset);
    memcpy(result.data, buffer.data, dataOffset);
    return result;
}

