// Generate a formatted legend string for the logistic function parameters
std::string generate_legend_label (double slope, double shift)
{
    namespace uc = mplot::unicode;
    std::stringstream slope_txt;
    if (slope != 1.0) { slope_txt << slope; }

    std::stringstream paren_txt;
    std::stringstream offset_txt;
    if (shift != 0.0) {
        paren_txt << "(";
        if (shift > 0.0) {
            offset_txt << " - " << shift << ")";
        } else {
            offset_txt << " + " << -shift << ")";
        }
    }

    std::stringstream equation;
    equation << "k=" << slope << ", x" << uc::toUtf8(uc::subs0) << "=" << shift;
    equation << ": f(x) = 1 / [1 + exp (-" << slope_txt.str() << paren_txt.str() << "x" << offset_txt.str() << ")]";
    return equation.str();
}

int main()
{
    // Initialize an mplot::Visual window with specified dimensions and title
    mplot::Visual scene(1280, 960, "Sigmoidal Curves");

    // Create a GraphVisual object with spatial offset (-0.3f, -0.3f, 0.0f)
    auto graph_view = std::make_unique<mplot::GraphVisual<double>> (sm::vec<float>({-0.3f,-0.3f,0.0f}));
    scene.bindmodel(graph_view);

    // Prepare x-axis data using vvec (vectorized vector with math operations)
    sm::vvec<double> abscissa;
    abscissa.linspace(-80, 40, 250);

    // Add multiple logistic curves to the plot
    graph_view->setdata(abscissa, abscissa.logistic(0.15, -8), generate_legend_label(0.15, -8));

    // Use in-place modification for one curve
    sm::vvec<double> transformed = abscissa;
    transformed.logistic_inplace(0.3, -4);
    graph_view->setdata(abscissa, transformed, generate_legend_label(0.3, -4));

    graph_view->setdata(abscissa, abscissa.logistic(0.6, 0), generate_legend_label(0.6, 0));
    graph_view->setdata(abscissa, abscissa.logistic(1.2, 6), generate_legend_label(1.2, 6));
    graph_view->setdata(abscissa, abscissa.logistic(2.5, 12), generate_legend_label(2.5, 12));

    // Finalize graph model construction
    graph_view->finalize();

    // Transfer ownership of the graph model to the visual scene
    scene.addVisualModel(graph_view);

    // Keep window open until user exits (Ctrl-q)
    scene.keepOpen();
    return 0;
}

