#include <iostream>
#include <vector>
#include <string>
#include <numeric>
#include <algorithm>

// Function to output a query for the current candidate set S
void send_query(const std::vector<int>& candidates) {
    std::cout << "? " << candidates.size();
    for (int val : candidates) {
        std::cout << " " << val;
    }
    std::cout << std::endl;
}

// Function to output a guessed value
void output_guess(int guess_value) {
    std::cout << "! " << guess_value << std::endl;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int total_numbers;
    std::cin >> total_numbers;

    // Set A: possible values if last response was true
    // Set B: possible values if last response was false
    std::vector<int> set_a(total_numbers);
    std::iota(set_a.begin(), set_a.end(), 1);
    std::vector<int> set_b;

    // Reduce candidate sets until only 2 or fewer remain
    while (set_a.size() + set_b.size() > 2) {
        size_t half_a = set_a.size() / 2;
        size_t half_b = set_b.size() / 2;

        std::vector<int> query_set;

        // Build query set from first halves of both sets
        if (half_a > 0) {
            query_set.insert(query_set.end(), set_a.begin(), set_a.begin() + half_a);
        }
        if (half_b > 0) {
            query_set.insert(query_set.end(), set_b.begin(), set_b.begin() + half_b);
        }

        send_query(query_set);

        std::string answer;
        std::cin >> answer;

        // Split original sets into halves
        std::vector<int> set_a_first(set_a.begin(), set_a.begin() + half_a);
        std::vector<int> set_a_second(set_a.begin() + half_a, set_a.end());
        std::vector<int> set_b_first(set_b.begin(), set_b.begin() + half_b);
        std::vector<int> set_b_second(set_b.begin() + half_b, set_b.end());

        std::vector<int> new_set_a, new_set_b;

        if (answer == "YES") {
            // Update sets for YES response
            new_set_a.reserve(set_a_first.size() + set_b_first.size());
            new_set_a.insert(new_set_a.end(), set_a_first.begin(), set_a_first.end());
            new_set_a.insert(new_set_a.end(), set_b_first.begin(), set_b_first.end());
            new_set_b = set_a_second;
        } else { // NO case
            new_set_a.reserve(set_a_second.size() + set_b_second.size());
            new_set_a.insert(new_set_a.end(), set_a_second.begin(), set_a_second.end());
            new_set_a.insert(new_set_a.end(), set_b_second.begin(), set_b_second.end());
            new_set_b = set_a_first;
        }

        set_a = std::move(new_set_a);
        set_b = std::move(new_set_b);
    }

    // Final phase: check remaining candidates
    std::vector<int> remaining_candidates;
    remaining_candidates.insert(remaining_candidates.end(), set_a.begin(), set_a.end());
    remaining_candidates.insert(remaining_candidates.end(), set_b.begin(), set_b.end());

    for (int num : remaining_candidates) {
        output_guess(num);
        std::string feedback;
        std::cin >> feedback;
        if (feedback == ":)") {
            return 0;
        }
    }

    return 0;
}

