using namespace llvm;

#define DEBUG_TYPE "elim-avail-extern"

cl::opt<bool> ConvertToLocal(
    "avail-extern-to-local", cl::Hidden,
    cl::desc("Convert available_externally into locals, renaming them "
             "to avoid link-time clashes."));

STATISTIC(NumRemovals, "Number of functions removed");
STATISTIC(NumConversions, "Number of functions converted");
STATISTIC(NumVariables, "Number of global variables removed");

void deleteFunction(Function &F) {
  F.deleteBody();
  ++NumRemovals;
}

/// Create a local copy of the function, rename it to avoid conflicts, and
/// redirect direct call sites to use the new local version. Only direct calls
/// are redirected; indirect uses (e.g., taking the address) remain bound to
/// the original declaration.
///
/// Note: Metadata such as Value Profiling ("VP") MD_prof is not updated to
/// reflect the new GUID, assuming that consumers of this metadata reside
/// earlier in the pipeline (e.g., ICP).
static void convertToLocalCopy(Module &M, Function &F) {
  assert(F.hasAvailableExternallyLinkage());
  assert(!F.isDeclaration());

  // If no call uses exist, simply delete the function body
  if (F.uses().end() == llvm::find_if(F.uses(), [&](Use &U) {
        return isa<CallBase>(U.getUser());
      })) {
    deleteFunction(F);
    return;
  }

  std::string OrigName = F.getName().str();
  std::string UniqueSuffix = getUniqueModuleId(&M);
  std::string NewName = OrigName + ".__uniq" + UniqueSuffix;

  F.setName(NewName);

  if (auto *SP = F.getSubprogram())
    SP->replaceLinkageName(MDString::get(F.getContext(), NewName));

  F.setLinkage(GlobalValue::InternalLinkage);

  // Create an external declaration for the original name to handle non-call uses
  Function *Decl = Function::Create(
      F.getFunctionType(), GlobalValue::ExternalLinkage,
      F.getAddressSpace(), OrigName, F.getParent());

  F.replaceUsesWithIf(Decl, [&](Use &U) {
    return !isa<CallBase>(U.getUser());
  });

  ++NumConversions;
}

static bool eliminateAvailableExternally(Module &M) {
  bool Changed = false;

  // Process available_externally global variables
  for (GlobalVariable &GV : M.globals()) {
    if (!GV.hasAvailableExternallyLinkage())
      continue;

    if (GV.hasInitializer()) {
      Constant *Init = GV.getInitializer();
      GV.setInitializer(nullptr);
      if (isSafeToDestroyConstant(Init))
        Init->destroyConstant();
    }

    GV.removeDeadConstantUsers();
    GV.setLinkage(GlobalValue::ExternalLinkage);
    ++NumVariables;
    Changed = true;
  }

  // Process available_externally functions
  for (Function &F : llvm::make_early_inc_range(M)) {
    if (F.isDeclaration() || !F.hasAvailableExternallyLinkage())
      continue;

    if (ConvertToLocal)
      convertToLocalCopy(M, F);
    else
      deleteFunction(F);

    F.removeDeadConstantUsers();
    Changed = true;
  }

  return Changed;
}

PreservedAnalyses
EliminateAvailableExternallyPass::run(Module &M, ModuleAnalysisManager &) {
  if (!eliminateAvailableExternally(M))
    return PreservedAnalyses::all();

  return PreservedAnalyses::none();
}

#include <madvoro/Voronoi3D.hpp>
#include <iostream>
#include <vector>

int main(int argc, char *argv[])
{
    // Define the bounding box for the Voronoi diagram
    MadVoro::Vector3D bottomLeft(-10.0, -10.0, -10.0);
    MadVoro::Vector3D topRight(10.0, 10.0, 10.0);

    // Initialize the 3D Voronoi diagram with the specified bounds
    MadVoro::Voronoi3D voronoiDiagram(bottomLeft, topRight);

    // Input point set (sites) for the Voronoi diagram
    std::vector<MadVoro::Vector3D> sites {
        { -0.115, 4.484, 0.688 },
        { -6.121, 6.335, -9.093 },
        { -5.529, -7.464, 2.459 },
        { -3.448, -7.794, -6.939 },
        { -3.231, 8.213, -7.829 },
        { 5.204, 9.943, 6.175 },
        { -7.018, 7.155, -0.226 },
        { 0.567, 2.263, -0.962 },
        { 9.998, -3.030, 7.772 },
        { 3.811, 6.672, -8.231 },
        { 4.252, -8.460, -2.693 },
        { 5.184, 0.449, -1.665 },
        { -3.333, 3.909, 5.544 },
        { 3.495, -0.703, 5.494 },
        { -4.844, 4.808, -4.166 },
        { 3.016, -0.006, -1.534 },
        { -3.990, -1.579, 0.691 },
        { 6.928, 1.059, 6.088 },
        { 9.439, -6.873, 5.741 },
        { 6.238, -6.793, -4.822 }
    };

    // Retrieve and verify the bounding box after initialization
    std::pair<MadVoro::Vector3D, MadVoro::Vector3D> domainBounds = voronoiDiagram.GetBoxCoordinates();

    // Construct the Voronoi diagram using the provided points
    voronoiDiagram.Build(sites);

    // Output basic information about the diagram
    std::cout << "Lower-left corner: " << domainBounds.first 
              << ", Upper-right corner: " << domainBounds.second << std::endl;
    std::cout << "Total number of sites (cells): " << voronoiDiagram.GetPointNo() << std::endl;

    // Analyze a specific cell (index 3)
    size_t targetSiteIndex = 3;
    const MadVoro::face_vec &cellFaces = voronoiDiagram.GetCellFaces(targetSiteIndex);

    std::cout << "Site #" << targetSiteIndex 
              << " at position " << voronoiDiagram.GetMeshPoint(targetSiteIndex)
              << " has " << cellFaces.size() << " faces" << std::endl;
    std::cout << "Hence, it has " << cellFaces.size() << " neighboring cells" << std::endl;

    // Get all face vertex coordinates
    std::vector<MadVoro::Vector3D> allFaceVertices = voronoiDiagram.GetFacePoints();

    std::cout << "Detailed face information:" << std::endl;
    for (const size_t &faceID : cellFaces) {
        // Compute center of mass for this face
        MadVoro::Vector3D faceCentroid = voronoiDiagram.FaceCM(faceID);

        // Get adjacent sites (neighbors) sharing this face
        const std::pair<size_t, size_t> adjacentSites = voronoiDiagram.GetFaceNeighbors(faceID);

        // Identify the neighbor site (excluding the current site)
        size_t neighborSite = (adjacentSites.first == targetSiteIndex) 
                              ? adjacentSites.second 
                              : adjacentSites.first;

        std::cout << "Face " << faceID 
                  << ": neighbor is site #" << neighborSite 
                  << " at " << voronoiDiagram.GetMeshPoint(neighborSite) << std::endl;

        // Print vertices of this face
        std::cout << "  Face vertices: ";
        for (const size_t &vertexID : voronoiDiagram.GetPointsInFace(faceID)) {
            std::cout << allFaceVertices[vertexID] << ", ";
        }
        std::cout << "\b\b" << std::endl;
    }

    return 0;
}

