#include <algorithm>
#include <climits>

class Solution {
public:
    long long minimumRemoval(std::vector<int>& beans) {
        // Sort the beans array in non-decreasing order
        std::sort(beans.begin(), beans.end());

        // Calculate the total sum of all beans
        long long overallSum = 0;
        for (int bean : beans) {
            overallSum += bean;
        }

        // Initialize answer with maximum possible value
        long long minRemovals = LLONG_MAX;
        int size = beans.size();

        // For each possible target value (beans[i])
        for (int index = 0; index < size; index++) {
            // Calculate beans that would remain if we keep beans[index] 
            // for all positions from index to end
            long long remainingBeans = 1LL * beans[index] * (size - index);

            // Removals needed = total beans - beans that remain
            long long removals = overallSum - remainingBeans;

            // Update minimum removals
            minRemovals = std::min(minRemovals, removals);
        }

        return minRemovals;
    }
};

#include <vector>

class Solution {
public:
    // Find the pivot index where sum of elements to the left equals sum to the right
    int pivotIndex(std::vector<int>& values) {
        int size = values.size();
        int overallSum = 0;
        int prefixSum = 0;

        // Calculate the total sum of all elements
        for(int element : values) {
            overallSum += element;
        }

        // Check each position for pivot condition
        for(int index = 0; index < size; index++) {
            if(prefixSum == overallSum - prefixSum - values[index]) {
                return index;
            }
            prefixSum += values[index];
        }

        return -1;
    }
};

