#include <iostream>
#include <vector>
#include <numeric>
#include <list>

// Process each test case to determine the two pens with ink
void processTest() {
    int size;
    std::cin >> size;
    std::list<int> options;
    for (int idx = 0; idx < size; ++idx) {
        options.push_back(idx);
    }
    while (options.size() > 2) {
        // Retrieve three candidates from the beginning of the list
        int first = options.front(); options.pop_front();
        int second = options.front(); options.pop_front();
        int third = options.front(); options.pop_front();

        // Test the first two candidates
        std::cout << "0 " << first << std::endl;
        int result1;
        std::cin >> result1;
        std::cout << "0 " << second << std::endl;
        int result2;
        std::cin >> result2;

        // Determine which candidates proceed based on test outcomes
        if (result1 == 1 && result2 == 1) {
            // Both first and second have ink; keep them, discard third
            options.push_back(first);
            options.push_back(second);
        } else if (result1 == 1 && result2 == 0) {
            // Only first has ink; keep first and third
            options.push_back(first);
            options.push_back(third);
        } else if (result1 == 0 && result2 == 1) {
            // Only second has ink; keep second and third
            options.push_back(second);
            options.push_back(third);
        } else { // result1 == 0 && result2 == 0
            // Neither first nor second has ink; only third survives
            options.push_back(third);
        }
    }

    // Extract the final two remaining candidates
    int lastOption1 = options.front(); options.pop_front();
    int lastOption2 = options.front(); options.pop_front();

    // Report the final pair
    std::cout << "1 " << lastOption1 << " " << lastOption2 << std::endl;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    int testCaseCount;
    std::cin >> testCaseCount;
    while (testCaseCount--) {
        processTest();
    }

    return 0;
}

