#include <iostream>
#include <vector>
#include <numeric>
#include <random>
#include <algorithm>

// Function to send a query for a specific slice
int performQuery(int value) {
    std::cout << "? " << value << std::endl;
    int result;
    std::cin >> result;
    if (result == -1) {
        exit(0); // Terminate if judge signals error
    }
    return result;
}

// Function to output the final answer pair
void reportAnswer(int first, int second) {
    std::cout << "! " << first << " " << second << std::endl;
}

// Recursive function to solve the pairing problem
void process(std::vector<int>& items) {
    if (items.empty()) {
        return;
    }

    // Base case: two items left — directly report them as a pair
    if (items.size() == 2) {
        reportAnswer(items[0], items[1]);
        return;
    }

    // Select pivot as last element (pre-shuffled ensures randomness)
    int pivot = items.back();
    items.pop_back();

    // Query the pivot to initialize device state
    performQuery(pivot);

    std::vector<int> sameGroup;
    sameGroup.push_back(pivot);
    std::vector<int> diffGroup;

    int distinctCount = 1; // Only pivot is in device initially

    // Partition remaining items based on whether they match pivot's group
    for (int item : items) {
        int newDistinctCount = performQuery(item);

        if (newDistinctCount == distinctCount) {
            // No increase in distinct count → item belongs to same group as pivot
            sameGroup.push_back(item);
        } else {
            // Distinct count increased → item belongs to different group
            diffGroup.push_back(item);
            distinctCount = newDistinctCount;
        }
    }

    // Clear device by toggling all elements in sameGroup back out
    for (int item : sameGroup) {
        performQuery(item);
    }

    // Recursively process both groups
    process(sameGroup);
    process(diffGroup);
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::cin >> n;
    if (n == 0) {
        return 0;
    }

    // Initialize vector with values 1 to 2*n
    std::vector<int> allItems(2 * n);
    std::iota(allItems.begin(), allItems.end(), 1);

    // Shuffle to randomize pivot selection and avoid worst-case behavior
    std::random_device rd;
    std::mt19937 rng(rd());
    std::shuffle(allItems.begin(), allItems.end(), rng);

    process(allItems);
    return 0;
}

