// Function to display the size of a binary file
void demoFileSize() {
    // Open the file in binary mode for precise byte measurement
    std::ifstream inputFile("image.png", std::ios::binary);
    if (!inputFile) return;

    // Position the get pointer at the end of the file
    // (offset 0 from the end)
    inputFile.seekg(0, std::ios::end);

    // Retrieve the current position of the get pointer
    // (which now represents the total file size in bytes)
    std::streampos fileSize = inputFile.tellg();
    std::cout << "File size: " << fileSize << " bytes" << std::endl;

    // Reset the get pointer to the beginning for potential subsequent reads
    inputFile.seekg(0, std::ios::beg);
}

