// A reference-counted non-modifiable buffer class.
class shared_const_buffer
{
public:
  // Construct from a std::string.
  explicit shared_const_buffer(const std::string& input_data)
    : data_(new std::vector<char>(input_data.begin(), input_data.end())),
      buffer_(asio::buffer(*data_))
  {
  }

  // Implement the ConstBufferSequence requirements.
  typedef asio::const_buffer value_type;
  typedef const asio::const_buffer* const_iterator;
  const asio::const_buffer* begin() const { return &buffer_; }
  const asio::const_buffer* end() const { return &buffer_ + 1; }

private:
  std::shared_ptr<std::vector<char>> data_;
  asio::const_buffer buffer_;
};

class connection_handler
  : public std::enable_shared_from_this<connection_handler>
{
public:
  connection_handler(tcp::socket client_socket)
    : socket_(std::move(client_socket))
  {
  }

  void initiate()
  {
    perform_write();
  }

private:
  void perform_write()
  {
    std::time_t current_time = std::time(0);
    shared_const_buffer time_buffer(std::ctime(&current_time));
    auto self(shared_from_this());

    asio::async_write(socket_, time_buffer,
        [this, self](std::error_code err, std::size_t /*bytes_transferred*/)
        {
          // No action needed after write
        });
  }

  // The socket used to communicate with the client.
  tcp::socket socket_;
};

class server_instance
{
public:
  server_instance(asio::io_context& service, short listening_port)
    : acceptor_(service, tcp::endpoint(tcp::v4(), listening_port))
  {
    start_accepting();
  }

private:
  void start_accepting()
  {
    acceptor_.async_accept(
        [this](std::error_code error, tcp::socket new_socket)
        {
          if (!error)
          {
            std::make_shared<connection_handler>(std::move(new_socket))->initiate();
          }
          start_accepting();
        });
  }

  tcp::acceptor acceptor_;
};

