LogToFile::LogToFile(std::string const& filename, int flags)
    :
    Logger::Listener(flags),
    mFileName(filename)
{
    std::ofstream logStream(filename);
    if (logStream)
    {
        // This clears the file contents from any previous runs.
        logStream.close();
    }
    else
    {
        // The file cannot be opened.  Use an empty string for Report to know
        // not to attempt opening the file for append.
        mFileName = "";
    }
}

void LogToFile::Report(std::string const& message)
{
    if (!mFileName.empty())
    {
        // Open for append.
        std::ofstream logStream(mFileName,
            std::ios_base::out | std::ios_base::app);
        if (logStream)
        {
            logStream << message.c_str();
            logStream.close();
        }
        else
        {
            // The file cannot be opened.  Set the filename to empty so that
            // future calls to Report do not attempt to open the file again.
            mFileName = "";
        }
    }
}

