// Weak symbol implementation for __cxa_thread_atexit_impl
// This provides compatibility with older glibc versions that lack the 2.18 export.
// The function is marked weak to allow newer libc implementations to override it.
// In our engine application, thread-local storage cleanup on thread exit isn't 
// strictly necessary since the engine typically terminates when threads end.
[[gnu::weak]] int __cxa_thread_atexit_impl(destructor_func dtor, void *data,
                                           void *dso_handle) {
    return 0;
}

// Implementation of getrandom syscall wrapper
// Introduced in glibc 2.25 (not 2.2 as mentioned in comment), this function
// provides secure random number generation without requiring /dev/urandom access.
// Falls back to direct syscall when glibc doesn't provide it.
ssize_t getrandom(void *buf, size_t len, unsigned int opts) {
    return syscall(SYS_getrandom, buf, len, opts);
}
}

#include "FiberPool.hpp"
