void jointStateCallback(sensor_msgs::JointStateConstPtr msg) {
  if (lastJointState.position == msg->position) {
    return;
  }
  lastJointState.position = msg->position;
  Eigen::VectorXd configuration(9);
  configuration(0) = configuration(1) = configuration(2) = 0.0;
  for (size_t i = 3; i < 9; ++i) {
    configuration(i) = lastJointState.position[i - 3];
  }
  visualizationInterface->publishDistances(configuration);
}

