bool FCrashDebugHelperWindows::ProduceMinidumpDiagnosticReport(const FString& DumpFilePath)
{
    FWindowsPlatformStackWalkExt StackWalker(CrashData);
    const bool bInitialized = StackWalker.InitializeStackWalking();
    bool bSuccess = false;

    if (bInitialized && StackWalker.OpenDumpFile(DumpFilePath))
    {
        if (CrashData.SourceRevision != FCrashInfo::INVALID_CHANGELIST)
        {
            // Retrieve build version and module paths
            FCrashModuleInfo ExeVersionInfo;
            StackWalker.GetExeFileVersionAndModuleList(ExeVersionInfo);

            // Initialize symbol handling
            StackWalker.InitializeSymbols();

            // Configure symbol search paths using loaded modules
            StackWalker.SetSymbolPathsFromModules();

            // Gather detailed module information
            StackWalker.RetrieveModuleDetails();

            // Collect system context data
            StackWalker.AcquireSystemInformation();

            // Extract thread state details
            StackWalker.CollectThreadDetails();

            // Acquire exception context
            StackWalker.GatherExceptionDetails();

            // Generate callstacks for all threads
            StackWalker.BuildCallstacks();

            // Include source file context at crash site
            AppendSourceToReport();

            // Mark success
            bSuccess = true;
        }
        else
        {
            UE_LOG(LogCrashDebugHelper, Warning, TEXT("Invalid source revision identifier"));
        }
    }
    else
    {
        UE_LOG(LogCrashDebugHelper, Warning, TEXT("Unable to open crash dump: %s"), *DumpFilePath);
    }

    return bSuccess;
}

