/// @brief Launches a new kernel-level task from a given function entry point.
/// @note This initializes a fresh stack context; any local state from the caller's stack frame is lost.
/// @param entry_point the starting address of the new task.
/// @param task_id the unique Kernel ID assigned to the new task.
/// @return TRUE if the task was successfully created, FALSE otherwise.
BOOL rtl_create_kernel_task(HAL::StackFramePtr entry_point, const KID task_id) {
  if (!task_id || entry_point == nullptr) return FALSE;
  return KernelTaskHelper::Add(entry_point, task_id);
}

/***********************************************************************************/
/// @brief Creates and schedules a new user-space process.
/// @note The provided function becomes the main entry for the new process.
/// @param entry_func the function pointer serving as the process entry point.
/// @param name the human-readable name of the process.
/// @return the ProcessID assigned to the new process, or kSchedInvalidPID on failure.
/***********************************************************************************/
ProcessID rtl_create_user_process(rtl_start_kind entry_func, const Char* name) {
  if (!name || *name == '\0') return kSchedInvalidPID;
  return UserProcessScheduler::The().Spawn(name, reinterpret_cast<VoidPtr>(entry_func), nullptr);
}

