// Process one test scenario
void handle_case() {
    int count;
    std::cin >> count;
    std::set<std::string> collected;

    // Try each starting character from 'a' to 'z'
    for (char ch = 'a'; ch <= 'z'; ++ch) {
        if (collected.size() == count) {
            break;
        }

        std::string base(1, ch);
        int request_size = 1;

        // Exponential search for words with current prefix
        while (true) {
            if (collected.size() == count) {
                break;
            }

            std::cout << "ask " << base << " " << request_size << std::endl;
            int received_count;
            std::cin >> received_count;

            for (int idx = 0; idx < received_count; ++idx) {
                std::string item;
                std::cin >> item;
                collected.insert(item);
            }

            // If fewer items returned than requested, no more words for this prefix
            if (received_count < request_size) {
                break;
            }

            // Safety check: if we asked for 'count' and got 'count', we're done for this prefix
            if (request_size == count) {
                break;
            }

            // Double the request size for next iteration
            request_size *= 2;
            if (request_size > count) {
                request_size = count;
            }
        }
    }

    // Print final result
    std::cout << "result";
    for (const auto& str : collected) {
        std::cout << " " << str;
    }
    std::cout << std::endl;
}

int main() {
    // Optimize I/O operations
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int test_cases;
    std::cin >> test_cases;

    while (test_cases--) {
        handle_case();
    }

    return 0;
}

