#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// Structure to represent a swap operation between two positions
struct Operation {
    int r1, c1, r2, c2;
};

int main() {
    // Speed up I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int size = 30;
    vector<vector<int>> pyramid(size);

    // Input reading: populate the pyramid structure
    for (int row = 0; row < size; ++row) {
        pyramid[row].resize(row + 1);
        for (int col = 0; col <= row; ++col) {
            cin >> pyramid[row][col];
        }
    }

    vector<Operation> swaps;

    // Bottom-up heapification strategy:
    // Start from the second-last row and move upward.
    // For each element, perform sift-down to maintain max-heap property.
    // Since lower levels are already processed, we only need to fix violations locally.

    for (int level = size - 2; level >= 0; --level) {
        for (int index = 0; index <= level; ++index) {
            int current_row = level;
            int current_col = index;

            // Sift down the current element until heap property is satisfied
            while (current_row < size - 1) {
                int value = pyramid[current_row][current_col];
                int left_child = pyramid[current_row + 1][current_col];
                int right_child = pyramid[current_row + 1][current_col + 1];

                // If current node is greater than or equal to both children, stop
                if (value >= left_child && value >= right_child) {
                    break;
                }

                // Determine which child to swap with (prefer left if equal)
                int target_row = current_row + 1;
                int target_col;

                if (left_child > right_child) {
                    target_col = current_col;
                } else {
                    target_col = current_col + 1;
                }

                // Record this swap
                swaps.push_back({current_row, current_col, target_row, target_col});

                // Perform the actual swap in the pyramid
                swap(pyramid[current_row][current_col], pyramid[target_row][target_col]);

                // Update position to continue sifting down
                current_row = target_row;
                current_col = target_col;
            }
        }
    }

    // Output results: number of swaps followed by each swap's coordinates
    cout << swaps.size() << "\n";
    for (const auto& op : swaps) {
        cout << op.r1 << " " << op.c1 << " " << op.r2 << " " << op.c2 << "\n";
    }

    return 0;
}

