#include <vector>
#include <cmath>

class Solution {
public:
    std::vector<int> findDisappearedNumbers(std::vector<int>& nums) {
        int size = nums.size();

        // Mark indices corresponding to present numbers as negative
        for (int idx = 0; idx < size; idx++) {
            int position = std::abs(nums[idx]) - 1;
            if (nums[position] > 0) {
                nums[position] = -nums[position];
            }
        }

        // Collect indices that remain positive (missing numbers)
        std::vector<int> result;
        for (int j = 0; j < size; j++) {
            if (nums[j] > 0) {
                result.push_back(j + 1);
            }
        }

        return result;
    }
};

#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>

int size;
std::vector<std::vector<int>> parity_table;

// Returns 0 for invalid ranges (l >= r) since such ranges contain no inversions.
// Used to avoid boundary checks in get_rel function.
int range_query(int left, int right) {
    if (left >= right) {
        return 0;
    }
    return parity_table[left][right];
}

// Computes whether p[i] > p[j] (mod 2) for i < j using four range queries.
// Based on inclusion-exclusion principle applied to inversion counts.
int compare_parity(int pos_i, int pos_j) {
    return range_query(pos_i, pos_j) ^ 
           range_query(pos_i + 1, pos_j) ^ 
           range_query(pos_i, pos_j - 1) ^ 
           range_query(pos_i + 1, pos_j - 1);
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::cin >> size;
    if (size == 1) {
        std::cout << "1 1\n";
        return 0;
    }

    // Precompute all pairwise subarray inversion parities
    parity_table.assign(size + 2, std::vector<int>(size + 2, 0));
    for (int left = 1; left <= size; ++left) {
        for (int right = left + 1; right <= size; ++right) {
            std::cout << "0 " << left << " " << right << "\n";
            std::cin >> parity_table[left][right];
        }
    }

    std::vector<int> positions(size);
    std::iota(positions.begin(), positions.end(), 1);

    // Sort positions according to underlying permutation values
    // Comparator uses parity comparisons to determine relative ordering
    std::stable_sort(positions.begin(), positions.end(), [&](int idx_a, int idx_b) {
        if (idx_a == idx_b) return false;

        if (idx_a < idx_b) {
            // p[idx_a] < p[idx_b] when there's no inversion (parity == 0)
            return compare_parity(idx_a, idx_b) == 0;
        } else { // idx_a > idx_b
            // p[idx_a] < p[idx_b] when p[idx_b] > p[idx_a] (parity == 1)
            return compare_parity(idx_b, idx_a) == 1;
        }
    });

    // Build result permutation: position -> value mapping
    std::vector<int> perm(size + 1);
    for (int rank = 0; rank < size; ++rank) {
        perm[positions[rank]] = rank + 1;
    }

    // Output final permutation
    std::cout << "1 ";
    for (int i = 1; i <= size; ++i) {
        std::cout << perm[i] << (i == size ? "" : " ");
    }
    std::cout << "\n";
    return 0;
}

