namespace engine::monitor {
namespace {
//---------------------------------------------------------------------
// Flag to control whether the final MONCCODE(exit...) is displayed
// This can be disabled when needed (e.g., for Python launcher compatibility)
//---------------------------------------------------------------------
bool g_displayExitCode = true;
}  // namespace

//-------------------------------------------------------------------------
// Monitor configuration option: specifies the factory name for custom monitors.
// Two primary built-in types are supported:
//		--monitor=Console	- outputs human-readable information
//		--monitor=App		- outputs structured data optimized for automated parsing
//-------------------------------------------------------------------------
application::Opt MonitorMode{"--monitor", "Console"};

//-------------------------------------------------------------------------
/// @brief Enables or disables display of the final exit code
/// @param[in] enableFlag - if true, show exit code; if false, suppress it
/// @return The updated setting after modification
//-------------------------------------------------------------------------
bool setDisplayExitCode(bool enableFlag) noexcept {
    // Allow disabling this feature for integration with external launchers
    g_displayExitCode = enableFlag;
    // Return the new current state
    return g_displayExitCode;
}

//-------------------------------------------------------------------------
/// @brief Retrieves the current setting for displaying the exit code
/// @return true if exit code will be shown, false otherwise
//-------------------------------------------------------------------------
bool getDisplayExitCode() noexcept { return g_displayExitCode; }

//-------------------------------------------------------------------------
/// @brief Initializes the selected monitor type based on configuration
//-------------------------------------------------------------------------
Error initialize() noexcept {
    // Register available monitor factories
    if (auto err = Factory::registerFactory(Console::Factory, App::Factory,
                                            TestConsole::Factory))
        return err;

    auto mode = MonitorMode.val();
    auto instance = Factory::make<Monitor>(_location, mode);
    if (!instance) return instance.ccode();

    config::monitor() = _mv(*instance);

    // Set up crash dump notification callback
    dev::crashDumpCreatedCallback() = [](const file::Path &dumpPath) noexcept {
        if (config::monitor()) MONITOR(onCrashDumpCreated, _location, dumpPath);
    };

    // Start the monitor subsystem
    MONITOR(startMonitor);
    return {};
}

//-------------------------------------------------------------------------
/// @brief Shuts down and cleans up monitor resources
//-------------------------------------------------------------------------
void shutdown() noexcept {
    // Stop the active monitor if present
    if (config::monitor()) MONITOR(stopMonitor);

    // Unregister factories to prevent accidental re-initialization
    Factory::deregisterFactory(Console::Factory, App::Factory,
                               TestConsole::Factory);

    // Clear the monitor reference
    config::monitor() = {};
}
}  // namespace engine::monitor

#include <iostream>
#include <unordered_map>
#include <queue>
using namespace std;

class Solution {
public:
    int firstUniqueChar(string input) {
        unordered_map<char, int> frequencyMap;
        queue<int> indexQueue;

        // Track character frequencies and preserve first occurrence indices
        for (int pos = 0; pos < input.length(); pos++) {
            char currentChar = input[pos];

            if (frequencyMap.find(currentChar) == frequencyMap.end()) {
                frequencyMap[currentChar] = 1;
                indexQueue.push(pos);
            } else {
                frequencyMap[currentChar]++;
            }

            // Clean up non-unique characters from the front of the queue
            while (!indexQueue.empty() && frequencyMap[input[indexQueue.front()]] > 1) {
                indexQueue.pop();
            }
        }

        return indexQueue.empty() ? -1 : indexQueue.front();
    }
