inline auto
insert_impl(ContainerT& _container, int, Args&&... _args)
    -> decltype(_container.push_back(std::forward<Args>(_args)...))
{
    return _container.push_back(std::forward<Args>(_args)...);
}

template <typename ContainerT, typename... Args>
inline auto
insert_impl(ContainerT& _container, long, Args&&... _args)
    -> decltype(_container.insert(std::forward<Args>(_args)...))
{
    return _container.insert(std::forward<Args>(_args)...);
}

template <typename ContainerT, typename... Args>
inline auto
insert(ContainerT& _container, Args&&... _args)
{
    return insert_impl(_container, 0, std::forward<Args>(_args)...);
}

template <typename ContainerT, typename SizeT>
inline auto
allocate_impl(ContainerT& _container, int, SizeT _size) -> decltype(_container.reserve(_size), bool())
{
    _container.reserve(_size);
    return true;
}

template <typename ContainerT, typename SizeT>
inline auto
allocate_impl(ContainerT&, long, SizeT)
{
    return false;
}

template <typename ContainerT, typename SizeT>
inline auto
allocate(ContainerT& _container, SizeT _size)
{
    return allocate_impl(_container, 0, _size);
}
