template <typename ContainerT>
ContainerT
split_string(const std::string& input, std::string_view separators)
{
    ContainerT output{};
    size_t     start_pos = 0;   // index of the start of a substring
    size_t     sep_pos   = 0;   // index of the next separator

    if(allocate(output, 0))
    {
        size_t max_count = 0;
        for(char c : input)
        {
            for(char sep : separators)
            {
                if(c == sep) ++max_count;
            }
        }
        allocate(output, max_count + 1);
    }

    while(start_pos < input.length() && sep_pos < input.length())
    {
        // locate first non-separator character starting from sep_pos
        start_pos = input.find_first_not_of(separators, sep_pos);
        if(start_pos == std::string::npos) break;

        // find next separator after start_pos
        sep_pos = input.find_first_of(separators, start_pos);

        std::string segment{};
        segment = input.substr(start_pos, sep_pos - start_pos);

        if(!segment.empty()) insert(output, segment);
    }

    return output;
}

template std::vector<std::string>
split_string(const std::string&, std::string_view);
template std::set<std::string>
split_string(const std::string&, std::string_view);
