#include <vector>
#include <algorithm>

class Solution {
public:
    std::vector<int> replaceNonCoprimes(std::vector<int>& nums) {
        std::vector<int> stack;

        // Process each number in the input array
        for (int num : nums) {
            stack.push_back(num);  // Add current number to the working stack

            // While we have at least two numbers and they share a common factor > 1
            while (stack.size() >= 2) {
                int last = stack.back();
                int prev = stack[stack.size() - 2];
                int g = std::gcd(last, prev);

                if (g <= 1) break;  // They are coprime, stop processing

                // Remove the two non-coprime numbers
                stack.pop_back();
                stack.pop_back();

                // Replace them with their LCM
                long long lcm = (long long)last * prev / g;
                stack.push_back((int)lcm);
            }
        }

        return stack;
    }
};

