#include <vector>
using namespace std;

// Generate all possible subset sums recursively
void calculateSubsetTotals(vector<int>& elements, int position, int size, int currentSum, vector<int>& results) {
    // Base case: when we've processed all elements
    if (position == size) {
        results.push_back(currentSum);
        return;
    }

    // Include current element in the sum and proceed
    calculateSubsetTotals(elements, position + 1, size, currentSum + elements[position], results);
    // Exclude current element from the sum and proceed
    calculateSubsetTotals(elements, position + 1, size, currentSum, results);
}

vector<int> subsetSums(vector<int>& inputArray) {
    vector<int> output;
    calculateSubsetTotals(inputArray, 0, inputArray.size(), 0, output);
    return output;
}

