void U4MLManager::ConfigureAsServer(FRPCServer& NetworkServer)
{
	UE_LOG(LogUE4ML, Log, TEXT("\tsetting up server mode"));
	AddCommonFunctions(NetworkServer);
#if WITH_RPCLIB
	NetworkServer.bind("enable_manual_world_tick", [this](bool bActivate) {
		SetManualWorldTickEnabled(bActivate);
	});
	Librarian.AddRPCFunctionDescription(TEXT("enable_manual_world_tick"), TEXT("(), Controls whether the world runs in real time or is manually advanced via \'step\' or \'request_world_tick\' calls. Defaults to \'real time\'."));

	NetworkServer.bind("request_world_tick", [this](int32 NumTicks, bool bBlockUntilComplete) {
		if (bTickWorldManually == false)
		{
			return;
		}
		StepsRequested = NumTicks;
		while (bBlockUntilComplete && StepsRequested > 0)
		{
			FPlatformProcess::Sleep(0.f);
		}
		return;
	});

	Librarian.AddRPCFunctionDescription(TEXT("request_world_tick"), TEXT("(int NumTicks, bool bBlockUntilComplete), Triggers NumTicks world updates. Only effective if \'enable_manual_world_tick(true)\' was previously invoked. If bBlockUntilComplete is true, the function waits until all ticks are completed."));

	NetworkServer.bind("close_session", [this]() { U4MLManager::Get().SetSession(nullptr); });
	Librarian.AddRPCFunctionDescription(TEXT("close_session"), TEXT("(), Terminates the active session (including all associated agents)."));
#endif // WITH_RPCLIB

	if (Session)
	{
		Session->ConfigureAsServer();
	}
	OnAddServerFunctions.Broadcast(NetworkServer);
}

