namespace NLastGetopt {
    TString GenerateCompletionInfo(TStringBuf progName, TStringBuf optionFlag) {
        TString description = (
            "This command produces a shell script that implements tab-completion functionality and outputs it to `stdout`, "
            "enabling users to save the result into a file as needed. "
            "The location for storing this file varies depending on your shell environment and operating system."
            "\n"
            "\n"
            "\n"
            "{B}BASH (Linux){R}:"
            "\n"
            "\n"
            "System-wide completions reside in `/etc/bash_completion.d/`. "
            "User-specific completions go into `~/.local/share/bash-completion/completions`. "
            "Thus, redirect the output of this tool to one of these locations:"
            "\n"
            "\n"
            "    $ mkdir -p ~/.local/share/bash-completion/completions"
            "\n"
            "    $ {command} {flag} bash >"
            "\n"
            "          ~/.local/share/bash-completion/completions/{command}"
            "\n"
            "\n"
            "Please restart your shell session for modifications to become effective."
            "\n"
            "\n"
            "\n"
            "{B}BASH (macOS){R}:"
            "\n"
            "\n"
            "Ensure you have installed `bash-completion` (or `bash-completion@2` if using a newer bash version via Homebrew). "
            "Completion files should be placed in `/usr/local/etc/bash_completion.d`: "
            "\n"
            "\n"
            "    $ mkdir -p $(brew --prefix)/etc/bash_completion.d"
            "\n"
            "    $ {command} {flag} bash >"
            "\n"
            "          $(brew --prefix)/etc/bash_completion.d/{command}"
            "\n"
            "\n"
            "Alternatively, you can include the script directly by sourcing it in your `~/.bash_profile`."
            "\n"
            "\n"
            "Don't forget to reload your shell configuration after making changes."
            "\n"
            "\n"
            "\n"
            "{B}ZSH{R}:"
            "\n"
            "\n"
            "Zsh searches for completion scripts in directories specified by the `$fpath` array. "
            "It's advisable to store them under `~/.zfunc`: "
            "\n"
            "\n"
            "    $ mkdir -m755 -p ~/.zfunc"
            "\n"
            "    $ {command} {flag} zsh > ~/.zfunc/_{command}"
            "\n"
            "\n"
            "Add these lines at the end of your `.zshrc`, just before invoking `compinit`: "
            "\n"
            "\n"
            "    fpath+=(~/.zfunc)"
            "\n"
            "\n"
            "Restart your terminal or source your `.zshrc` to apply updates.");

        SubstGlobal(description, "{command}", progName);
        SubstGlobal(description, "{flag}", optionFlag);
        SubstGlobal(description, "{B}", NColorizer::StdErr().LightDefault());
        SubstGlobal(description, "{R}", NColorizer::StdErr().Reset());
        return description;
    }

    NComp::ICompleterPtr SupportedShellsCompleter() {
        return NComp::Choice({{"bash"}, {"zsh"}});
    }

    TOpt BuildCompletionOption(const TOpts* options, TString programName, TString longName) {
        return TOpt()
            .AddLongName(longName)
            .Help("produce shell completion script for bash or zsh")
            .CompletionHelp("generate shell completion script")
            .OptionalArgument("shell-type")
            .CompletionArgHelp("target shell syntax")
            .IfPresentDisableCompletion()
            .Completer(SupportedShellsCompleter())
            .Handler1T<TString>([options, programName, longName](TStringBuf shellType) {
                if (shellType.empty()) {
                    Cerr << Wrap(80, GenerateCompletionInfo(programName, "--" + longName)) << Endl;
                } else if (shellType == "bash") {
                    TBashCompletionGenerator(options).Generate(programName, Cout);
                } else if (shellType == "zsh") {
                    TZshCompletionGenerator(options).Generate(programName, Cout);
                } else {
                    Cerr << "Unsupported shell: " << TString{shellType}.Quote() << Endl;
                    exit(1);
                }
                exit(0);
            });
    }

    class TCompletionMode : public TMainClassArgs {
    public:
        TCompletionMode(const TModChooser* modeSelector, TString appName, TString modLabel)
            : AppName_(std::move(appName))
            , ModeSelector_(modeSelector)
            , ModLabel_(std::move(modLabel))
        {
        }

    protected:
        void RegisterOptions(NLastGetopt::TOpts& opts) override {
            TMainClassArgs::RegisterOptions(opts);
            opts.SetTitle("Create shell completion scripts for bash or zsh");
            opts.AddSection("Details", GenerateCompletionInfo(AppName_, ModLabel_));
            opts.SetFreeArgsNum(1);
            opts.GetFreeArgSpec(0)
                .Title("<shell-syntax>")
                .Help("target shell for completion (bash or zsh)")
                .CompletionArgHelp("shell syntax for completion script")
                .Completer(SupportedShellsCompleter());
        }

        int DoRun(NLastGetopt::TOptsParseResult&& parsedArgs) override {
            auto arg = parsedArgs.GetFreeArgs()[0];
            arg.to_lower();
            if (arg == "bash") {
                TBashCompletionGenerator(ModeSelector_).Generate(AppName_, Cout);
            } else if (arg == "zsh") {
                TZshCompletionGenerator(ModeSelector_).Generate(AppName_, Cout);
            } else {
                Cerr << "Unknown shell: " << arg.Quote() << Endl;
                parsedArgs.PrintUsage();
                return 1;
            }
            return 0;
        }

    private:
        TString AppName_;
        const TModChooser* ModeSelector_;
        TString ModLabel_;
    };

    THolder<TMainClassArgs> CreateCompletionModule(const TModChooser* modeSelector, TString appName, TString modLabel) {
        return MakeHolder<TCompletionMode>(modeSelector, std::move(appName), std::move(modLabel));
    }
}

#include <iostream>

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    // This C++ program outputs an A=B system specification for substring matching.
    // The Tid parameter is disregarded as per problem requirements.
    // The generated A=B system simulates a brute-force substring search:
    // For each possible starting index in string `s`, it verifies whether `t` matches.
    //
    // Internal representation:
    // s_processed P s_rem Z t
    // P: Outer loop pointer, indicating the current starting position in `s`.
    //
    // s_processed a C s_matched s_unmatched Z t
    // C: Active comparison marker; `a` is the first character being compared.
    // s_matched: Characters from `s` already confirmed to match prefix of `t`, marked A,B,C.
    //
    // D,E,F: Transport markers for characters a,b,c from `t`.
    // Y: Mismatch recovery state.
    // A,B,C: Matched characters in `s` corresponding to a,b,c in `t`.
    // Z: Main delimiter (replaces initial 'S').
    //
    // Complexity: O(|s|*|t|*|s|), but may pass due to test constraints or lenient limits.
    // Rule count remains under 100; string length grows by ≤1 per step (≤2L+10).
    // Initialization: place P and Z markers; P will be positioned at start.
    std::cout << "S=PZ" << std::endl;

    // Success/failure states
    std::cout << "AZ=(return)1" << std::endl;  // Match found
    std::cout << "PZ=(return)0" << std::endl;  // All positions checked, no match

    // Mismatch recovery (Y state) - high priority rules
    std::cout << "AY=Ya" << std::endl;
    std::cout << "BY=Yb" << std::endl;
    std::cout << "CY=Yc" << std::endl;
    std::cout << "aY=Ya" << std::endl;
    std::cout << "bY=Yb" << std::endl;
    std::cout << "cY=Yc" << std::endl;
    std::cout << "CY=P" << std::endl;  // Reset to outer loop when Y reaches C

    // Successful match detection
    std::cout << "CZ=AZ" << std::endl;  // When C reaches Z, entire pattern matched

    // Load next character from t using carriers
    std::cout << "Za=ZDa" << std::endl;
    std::cout << "Zb=ZEb" << std::endl;
    std::cout << "Zc=ZFc" << std::endl;

    // Carrier movement through regular characters
    std::cout << "aD=Da" << std::endl;
    std::cout << "bD=Db" << std::endl;
    std::cout << "cD=Dc" << std::endl;
    std::cout << "aE=Ea" << std::endl;
    std::cout << "bE=Eb" << std::endl;
    std::cout << "cE=Ec" << std::endl;
    std::cout << "aF=Fa" << std::endl;
    std::cout << "bF=Fb" << std::endl;
    std::cout << "cF=Fc" << std::endl;

    // Carrier movement through already matched characters
    std::cout << "AD=DA" << std::endl;
    std::cout << "BD=DB" << std::endl;
    std::cout << "CD=DC" << std::endl;
    std::cout << "AE=EA" << std::endl;
    std::cout << "BE=EB" << std::endl;
    std::cout << "CE=EC" << std::endl;
    std::cout << "AF=FA" << std::endl;
    std::cout << "BF=FB" << std::endl;
    std::cout << "CF=FC" << std::endl;

    // Character comparison at current position
    std::cout << "CaD=CA" << std::endl;
    std::cout << "CbE=CB" << std::endl;
    std::cout << "CcF=CC" << std::endl;

    // Mismatch handling
    std::cout << "CaE=Y" << std::endl;
    std::cout << "CaF=Y" << std::endl;
    std::cout << "CbD=Y" << std::endl;
    std::cout << "CbF=Y" << std::endl;
    std::cout << "CcD=Y" << std::endl;
    std::cout << "CcE=Y" << std::endl;

    // Outer loop advancement
    std::cout << "Pa=aC" << std::endl;
    std::cout << "Pb=bC" << std::endl;
    std::cout << "Pc=cC" << std::endl;
    std::cout << "aP=Pa" << std::endl;
    std::cout << "bP=Pb" << std::endl;
    std::cout << "cP=Pc" << std::endl;

    return 0;
}

#include <iostream>
#include <algorithm>
#include <cmath>

class Solution {
public:
    // Compute greatest common divisor using binary method
    static int GCD(unsigned a, unsigned b) {
        const int tzA = countr_zero(a);
        const int tzB = countr_zero(b);
        const int commonTrailingZeros = std::min(tzA, tzB);
        a >>= tzA;
        b >>= tzB;

        while (b != 0) {
            unsigned remainder = a % b;
            a = b;
            b = remainder;
        }
        return a << commonTrailingZeros;
    }

    // Count the number of Pythagorean triples with hypotenuse <= n
    static int countTriples(int limit) {
        int result = 0;
        int sqrtLimit = static_cast<int>(std::sqrt(limit));

        for (int m = 2; m <= sqrtLimit; ++m) {
            for (int n = 1 + (m & 1); n < m; n += 2) {
                if (GCD(m, n) != 1) continue;

                int hypotenuse = m * m + n * n;
                if (hypotenuse > limit) break;

                int multiplierMax = limit / hypotenuse;
                // Each primitive triple generates two ordered variants and their multiples
                result += 2 * multiplierMax;
            }
        }
        return result;
    }
};

#include "EntityIDRebaser.h"
#include "BioAssert.h"

using namespace db;

EntityIDRebaser::EntityIDRebaser() = default;
EntityIDRebaser::~EntityIDRebaser() = default;
EntityIDRebaser::EntityIDRebaser(const EntityIDRebaser& other) = default;
EntityIDRebaser& EntityIDRebaser::operator=(const EntityIDRebaser& other) = default;
EntityIDRebaser::EntityIDRebaser(EntityIDRebaser&& other) noexcept = default;
EntityIDRebaser& EntityIDRebaser::operator=(EntityIDRebaser&& other) noexcept = default;

// When a @ref Change creates local commits, it assigns NodeIDs based on its own
// view of the next available ID at the time it was forked. This local perspective
// may become outdated if other changes submit to main in the meantime.
// For example:
// @code
// CREATE (n:LOCALNODE) <- Created in this Change
// COMMIT             <- LOCALNODE assigned ID 7
// CREATE (n @ 7)-[r:LINK]->(m:ANOTHER) <- Edge referencing node 7
// @endcode
// Between the branch creation and submission, another change might have created
// nodes on main, causing ID 7 to already exist there. To prevent incorrect edge
// connections, we must adjust any IDs that were allocated after the branch point.
//
// The adjustment logic compares:
// 1. The nextNodeID value recorded when the Change was created (_branchTimeNextNodeID)
// 2. The current nextNodeID on main (_newNextNodeID)
// Any IDs >= _branchTimeNextNodeID need shifting forward by the difference.

NodeID EntityIDRebaser::rebaseNodeID(NodeID original) const {
    bioassert(_branchTimeNextNodeID <= _newNextNodeID, "invalid _branchTimeNextNodeID");
    return original >= _branchTimeNextNodeID 
           ? original + _newNextNodeID - _branchTimeNextNodeID 
           : original;
}

EdgeID EntityIDRebaser::rebaseEdgeID(EdgeID original) const {
    bioassert(_branchTimeNextEdgeID <= _newNextEdgeID, "invalid _branchTimeNextEdgeID");
    return original >= _branchTimeNextEdgeID 
           ? original + _newNextEdgeID - _branchTimeNextEdgeID 
           : original;
}

