#include <asio/dispatch.hpp>
#include <asio/execution_context.hpp>
#include <condition_variable>
#include <iostream>
#include <memory>
#include <mutex>
#include <queue>

using asio::dispatch;
using asio::execution_context;

class task_scheduler : public execution_context
{
public:
  // A class that satisfies the Executor requirements.
  class executor_type
  {
  public:
    executor_type(task_scheduler& ctx, int level) noexcept
      : context_(ctx), priority_level_(level)
    {
    }

    task_scheduler& context() const noexcept
    {
      return context_;
    }

    void on_work_started() const noexcept
    {
      // This executor doesn't count work. Instead, the scheduler simply runs
      // until explicitly stopped.
    }

    void on_work_finished() const noexcept
    {
      // This executor doesn't count work. Instead, the scheduler simply runs
      // until explicitly stopped.
    }

    template <class Func, class Alloc>
    void dispatch(Func&& f, const Alloc& a) const
    {
      submit(std::forward<Func>(f), a);
    }

    template <class Func, class Alloc>
    void post(Func f, const Alloc& a) const
    {
      auto p(std::allocate_shared<task_item<Func>>(
            typename std::allocator_traits<
              Alloc>::template rebind_alloc<char>(a),
            priority_level_, std::move(f)));
      std::lock_guard<std::mutex> guard(context_.mutex_);
      context_.task_queue_.push(p);
      context_.notify_.notify_one();
    }

    template <class Func, class Alloc>
    void defer(Func&& f, const Alloc& a) const
    {
      post(std::forward<Func>(f), a);
    }

    friend bool operator==(const executor_type& a,
        const executor_type& b) noexcept
    {
      return &a.context_ == &b.context_;
    }

    friend bool operator!=(const executor_type& a,
        const executor_type& b) noexcept
    {
      return &a.context_ != &b.context_;
    }

  private:
    task_scheduler& context_;
    int priority_level_;
  };

  executor_type get_executor(int level = 0) noexcept
  {
    return executor_type(*const_cast<task_scheduler*>(this), level);
  }

  void run()
  {
    std::unique_lock<std::mutex> lock(mutex_);
    for (;;)
    {
      notify_.wait(lock, [&]{ return shutdown_ || !task_queue_.empty(); });
      if (shutdown_)
        return;
      auto p(task_queue_.top());
      task_queue_.pop();
      lock.unlock();
      p->run_(p);
      lock.lock();
    }
  }

  void stop()
  {
    std::lock_guard<std::mutex> lock(mutex_);
    shutdown_ = true;
    notify_.notify_all();
  }

private:
  struct base_task
  {
    int priority_;
    void (*run_)(std::shared_ptr<base_task>&);
  };

  template <class Func>
  struct task_item : base_task
  {
    task_item(int pri, Func f) : function_(std::move(f))
    {
      priority_ = pri;
      run_ = [](std::shared_ptr<base_task>& p)
      {
        Func tmp(std::move(static_cast<task_item*>(p.get())->function_));
        p.reset();
        tmp();
      };
    }
    Func function_;
  };

  struct task_comparator
  {
    bool operator()(
        const std::shared_ptr<base_task>& a,
        const std::shared_ptr<base_task>& b)
    {
      return a->priority_ < b->priority_;
    }
  };

  std::mutex mutex_;
  std::condition_variable notify_;
  std::priority_queue<
    std::shared_ptr<base_task>,
    std::vector<std::shared_ptr<base_task>>,
    task_comparator> task_queue_;
  bool shutdown_ = false;
};

int main()
{
  task_scheduler sched;
  auto low_priority = sched.get_executor(0);
  auto medium_priority = sched.get_executor(1);
  auto high_priority = sched.get_executor(2);

  dispatch(low_priority, []{ std::cout << "A\n"; });
  dispatch(low_priority, []{ std::cout << "AA\n"; });
  dispatch(medium_priority, []{ std::cout << "B\n"; });
  dispatch(medium_priority, []{ std::cout << "BB\n"; });
  dispatch(high_priority, []{ std::cout << "C\n"; });
  dispatch(high_priority, []{ std::cout << "CC\n"; });
  dispatch(high_priority, []{ std::cout << "CCC\n"; });
  dispatch(sched.get_executor(-1), [&]{ sched.stop(); });

  sched.run();
}

