// Verify that a newly created manager starts in disconnected state
void test_network_manager_initial_state() {
    NetworkManager netMgr;
    TEST_ASSERT_FALSE(netMgr.isConnected());
    TEST_ASSERT_EQUAL_STRING("", netMgr.getSSID().c_str());
}

// Test AP mode: calling begin() without stored credentials should trigger START_AP,
// and handleClient() should execute the command, transitioning to AP_MODE.
void test_network_manager_ap_mode_operation() {
    NetworkManager netMgr;
    netMgr.begin();          // queues START_AP (no saved credentials available)
    netMgr.handleClient();   // processes START_AP -> internal state becomes AP_MODE
    TEST_ASSERT_FALSE(netMgr.isConnected());
    TEST_ASSERT_TRUE(netMgr.getIPAddress().startsWith("192.168.4."));
    TEST_ASSERT_TRUE(netMgr.getSSID().startsWith("ESP32_"));
}

// Confirm that saveCredentials stores the SSID and schedules connection attempt
void test_network_manager_credentials_storage() {
    NetworkManager netMgr;
    netMgr.saveCredentials("MyNetwork", "SecurePass");
    // saveCredentials enqueues CONNECT; process it to apply credentials
    netMgr.handleClient();  // CONNECT -> connect() -> state = CONNECTING
    // getSSID() returns stored SSID when not in AP mode
    TEST_ASSERT_EQUAL_STRING("MyNetwork", netMgr.getSSID().c_str());
    TEST_ASSERT_FALSE(netMgr.isConnected());  // mock WiFi never actually connects
}

// Ensure begin() + handleClient() sequence doesn't crash and yields valid IP string
void test_network_manager_begin_safety() {
    NetworkManager netMgr;
    netMgr.begin();
    netMgr.handleClient();
    String ipAddr = netMgr.getIPAddress();
    TEST_ASSERT_TRUE(ipAddr.length() > 0);
}

int runUnityTests() {
    UNITY_BEGIN();
    RUN_TEST(test_network_manager_initial_state);
    RUN_TEST(test_network_manager_ap_mode_operation);
    RUN_TEST(test_network_manager_credentials_storage);
    RUN_TEST(test_network_manager_begin_safety);
    return UNITY_END();
}

