    // tag::node[]
    pugi::xml_node element = doc.child("element");
    // modify node name
    std::cout << element.set_name("renamed");
    std::cout << ", updated element name: " << element.name() << std::endl;

    // modify comment text
    std::cout << doc.last_child().set_value("irrelevant comment");
    std::cout << ", updated comment text: " << doc.last_child().value() << std::endl;

    // we cannot change value of the element or name of the comment
    std::cout << element.set_value("0") << ", " << doc.last_child().set_name("invalid") << std::endl;
    // end::node[]

    // tag::attr[]
    pugi::xml_attribute attribute = element.attribute("id");
    // modify attribute name/value
    std::cout << attribute.set_name("identifier") << ", " << attribute.set_value("789");
    std::cout << ", new attribute: " << attribute.name() << "=" << attribute.value() << std::endl;

    // we can use numbers or booleans
