namespace Karm {

// FNV-1a 64-bit hash implementation per RFC draft-eastlake-fnv-21
export constexpr u64 fnv64(u8 const* buffer, usize size) {
    u64 result = 0xcbf29ce484222325;
    for (usize index = 0; index < size; index++) {
        result ^= buffer[index];
        result *= 0x100000001b3;
    }
    return result;
}

template <typename T>
struct Hasher;

export template <typename T>
constexpr u64 computeHash(T const& value) {
    if constexpr (
        requires(T const val) {
            { val.hash() } -> Meta::Same<u64>;
        }
    ) {
        return value.hash();
    } else {
        return Hasher<T>::hash(value);
    }
}

export template <Meta::Boolean T>
struct Hasher<T> {
    static constexpr u64 hash(T const& value) {
        return fnv64(reinterpret_cast<u8 const*>(&value), sizeof(value));
    }
};

export template <Meta::Integer T>
struct Hasher<T> {
    static constexpr u64 hash(T const& value) {
        return fnv64(reinterpret_cast<u8 const*>(&value), sizeof(value));
    }
};

export template <Meta::Float T>
struct Hasher<T> {
    static constexpr u64 hash(T const& value) {
        return fnv64(reinterpret_cast<u8 const*>(&value), sizeof(value));
    }
};

export template <Meta::Enum T>
struct Hasher<T> {
    static constexpr u64 hash(T const& value) {
        return fnv64(reinterpret_cast<u8 const*>(&value), sizeof(value));
    }
};

export template <>
struct Hasher<None> {
    static constexpr u64 hash(None const&) {
        return Karm::computeHash(0x0ULL);
    }
};

} // namespace Karm

