using namespace std;
using namespace std::chrono;

// Global flag to signal termination of worker threads
atomic<bool> shutdownRequested(false);

// Forward declaration for Scheduler structure
struct Scheduler;

// Coroutine task wrapper
struct WorkItem {
    struct promise_type {
        Scheduler* ownerScheduler;
        WorkItem get_return_object() {
            return WorkItem{ std::coroutine_handle<promise_type>::from_promise(*this) };
        }
        std::suspend_always initial_suspend() { return {}; }

        struct completion_awaiter {
            bool await_ready() noexcept { return false; }
            void await_suspend(std::coroutine_handle<>) noexcept {}
            void await_resume() noexcept {}
        };

        completion_awaiter final_suspend() noexcept { return {}; }
        void unhandled_exception() {}
        void return_void() {}
    };

    std::coroutine_handle<promise_type> coroutineHandle;

    WorkItem(std::coroutine_handle<promise_type> h) : coroutineHandle(h) {}

    ~WorkItem() {
        if (coroutineHandle) {
            coroutineHandle.destroy();
        }
    }

    void activate(Scheduler& sched);
};

// Scheduler managing timed coroutine execution
struct Scheduler {
    using ScheduledTask = pair<steady_clock::time_point, std::coroutine_handle<>>;
    priority_queue<ScheduledTask, vector<ScheduledTask>, greater<>> taskQueue;

    void enqueue(std::coroutine_handle<> handle) {
        taskQueue.emplace(steady_clock::now(), handle);
    }

    void enqueue_at(std::coroutine_handle<> handle, steady_clock::time_point targetTime) {
        taskQueue.emplace(targetTime, handle);
    }

    void execute() {
        while (!shutdownRequested.load()) {
            if (!taskQueue.empty()) {
                auto [scheduledTime, task] = taskQueue.top();

                if (steady_clock::now() >= scheduledTime) {
                    taskQueue.pop();
                    if (!task.done()) {
                        task.resume();
                    }
                } else {
                    auto waitDuration = scheduledTime - steady_clock::now();
                    if (waitDuration > milliseconds(1)) {
                        this_thread::sleep_for(milliseconds(1));
                    } else {
                        this_thread::yield();
                    }
                }
            } else {
                this_thread::yield();
            }
        }
    }
};

void WorkItem::activate(Scheduler& sched) {
    coroutineHandle.promise().ownerScheduler = &sched;
    sched.enqueue(coroutineHandle);
}

// Awaitable type for asynchronous sleep/delay
struct DelayAwaiter {
    Scheduler& schedulerRef;
    steady_clock::time_point wakeUpTime;

    DelayAwaiter(Scheduler& sched, microseconds duration)
        : schedulerRef(sched), wakeUpTime(steady_clock::now() + duration) {}

    bool await_ready() {
        return steady_clock::now() >= wakeUpTime;
    }

    void await_suspend(std::coroutine_handle<> h) {
        schedulerRef.enqueue_at(h, wakeUpTime);
    }

    void await_resume() {}
};

// Coroutine simulating transaction processing logic
WorkItem processTransactionCoroutine(Scheduler& sched, int& throughputCounter) {
    while (!shutdownRequested.load()) {
        throughputCounter++;
        co_await DelayAwaiter(sched, microseconds(15));
    }
}

// Worker thread function executing two coroutines concurrently
void workerFunction(int workerId, int& localCounter) {
    Scheduler sched;
    WorkItem item1 = processTransactionCoroutine(sched, localCounter);
    WorkItem item2 = processTransactionCoroutine(sched, localCounter);

    item1.activate(sched);
    item2.activate(sched);

    sched.execute();
}

int main(int argc, char* argv[]) {
    int numberOfThreads = 4;
    vector<thread> threadPool;
    vector<int> perThreadCounts(numberOfThreads, 0); // Local counters per thread

    // Launch worker threads
    for (int idx = 0; idx < numberOfThreads; ++idx) {
        threadPool.emplace_back(workerFunction, idx, ref(perThreadCounts[idx]));
    }

    // Run for specified duration
    int testDuration = 10;
    this_thread::sleep_for(seconds(testDuration));

    // Signal shutdown and wait for workers
    shutdownRequested.store(true);

    for (auto& t : threadPool) {
        t.join();
    }

    // Aggregate results
    int aggregateThroughput = 0;
    for (int i = 0; i < numberOfThreads; ++i) {
        aggregateThroughput += perThreadCounts[i];
    }

    // Display throughput metric
    cout << "Throughput: " << aggregateThroughput / testDuration << " txn/sec" << endl;

    return 0;
}

#include "llvm/Transforms/Utils/SSAUpdaterBulk.h"
#include "llvm/Analysis/IteratedDominanceFrontier.h"
#include "llvm/IR/BasicBlock.h"
#include "llvm/IR/Dominators.h"
#include "llvm/IR/IRBuilder.h"
#include "llvm/IR/Instructions.h"
#include "llvm/IR/Use.h"
#include "llvm/IR/Value.h"

using namespace llvm;

#define DEBUG_TYPE "ssaupdaterbulk"

/// Helper function to determine the block where a value should be defined for a given user.
/// For PHI nodes, returns the corresponding predecessor block; otherwise, returns the parent block of the instruction.
static BasicBlock *getUserBB(Use *U) {
  auto *UserInst = cast<Instruction>(U->getUser());
  if (auto *PHI = dyn_cast<PHINode>(UserInst))
    return PHI->getIncomingBlock(*U);
  else
    return UserInst->getParent();
}

/// Registers a new variable with the SSA rewriter. Must be called before AddAvailableValue or AddUse.
unsigned SSAUpdaterBulk::AddVariable(StringRef VarName, Type *VarType) {
  unsigned VarID = Rewrites.size();
  LLVM_DEBUG(dbgs() << "SSAUpdater: Var=" << VarID << ": initialized with Ty = "
                    << *VarType << ", Name = " << VarName << "\n");
  RewriteInfo Info(VarName, VarType);
  Rewrites.push_back(Info);
  return VarID;
}

/// Marks that a rewritten value is available in a specific block.
void SSAUpdaterBulk::AddAvailableValue(unsigned VarID, BasicBlock *BB, Value *Val) {
  assert(VarID < Rewrites.size() && "Variable not found!");
  LLVM_DEBUG(dbgs() << "SSAUpdater: Var=" << VarID
                    << ": added new available value " << *Val << " in "
                    << BB->getName() << "\n");
  Rewrites[VarID].Defines[BB] = Val;
}

/// Records a use site for a symbolic value. This use will be updated during RewriteAllUses.
void SSAUpdaterBulk::AddUse(unsigned VarID, Use *U) {
  assert(VarID < Rewrites.size() && "Variable not found!");
  LLVM_DEBUG(dbgs() << "SSAUpdater: Var=" << VarID << ": added a use " << *U->get()
                    << " in " << getUserBB(U)->getName() << "\n");
  Rewrites[VarID].Uses.push_back(U);
}

// Computes the value at a given block BB by either retrieving it directly or recursively
// traversing up the dominator tree.
Value *SSAUpdaterBulk::computeValueAt(BasicBlock *BB, RewriteInfo &R, DominatorTree *DT) {
  if (!R.Defines.count(BB)) {
    if (DT->isReachableFromEntry(BB) && !PredCache.get(BB).empty()) {
      BasicBlock *ImmediateDom = DT->getNode(BB)->getIDom()->getBlock();
      Value *V = computeValueAt(ImmediateDom, R, DT);
      R.Defines[BB] = V;
    } else {
      R.Defines[BB] = UndefValue::get(R.Ty);
    }
  }
  return R.Defines[BB];
}

/// Given sets of UsingBlocks and DefBlocks, computes the set of LiveInBlocks.
/// This identifies the region where the value is live — essentially a subgraph bounded by definitions and uses.
static void
ComputeLiveInBlocks(const SmallPtrSetImpl<BasicBlock *> &UsingBlocks,
                    const SmallPtrSetImpl<BasicBlock *> &DefBlocks,
                    SmallPtrSetImpl<BasicBlock *> &LiveInBlocks,
                    PredIteratorCache &PredCache) {
  // Initialize worklist with all blocks where the value is used.
  SmallVector<BasicBlock *, 64> Worklist(UsingBlocks.begin(), UsingBlocks.end());

  // Propagate liveness backwards through predecessors until fixed point.
  while (!Worklist.empty()) {
    BasicBlock *BB = Worklist.pop_back_val();

    // Skip if already processed.
    if (!LiveInBlocks.insert(BB).second)
      continue;

    // Examine predecessors: add them to the worklist unless they define the value.
    for (BasicBlock *Pred : PredCache.get(BB)) {
      if (DefBlocks.contains(Pred))
        continue;
      Worklist.push_back(Pred);
    }
  }
}

/// Performs all necessary updates: inserts PHI nodes, fills in their arguments, and replaces uses.
void SSAUpdaterBulk::RewriteAllUses(DominatorTree *DT,
                                    SmallVectorImpl<PHINode *> *InsertedPHIs) {
  for (auto &R : Rewrites) {
    // Determine where PHI nodes are needed using IDF calculation.
    ForwardIDFCalculator IDF(*DT);
    LLVM_DEBUG(dbgs() << "SSAUpdater: rewriting " << R.Uses.size() << " use(s)\n");

    // Collect defining and using blocks.
    SmallPtrSet<BasicBlock *, 2> DefBlocks;
    for (auto &Def : R.Defines)
      DefBlocks.insert(Def.first);

    IDF.setDefiningBlocks(DefBlocks);

    SmallPtrSet<BasicBlock *, 2> UsingBlocks;
    for (Use *U : R.Uses)
      UsingBlocks.insert(getUserBB(U));

    // Compute live-in blocks and IDF.
    SmallVector<BasicBlock *, 32> IDFBlocks;
    SmallPtrSet<BasicBlock *, 32> LiveInBlocks;
    ComputeLiveInBlocks(UsingBlocks, DefBlocks, LiveInBlocks, PredCache);
    IDF.resetLiveInBlocks();
    IDF.setLiveInBlocks(LiveInBlocks);
    IDF.calculate(IDFBlocks);

    // Insert PHI nodes at IDF blocks.
    SmallVector<PHINode *, 4> NewPHIs;
    for (auto *BB : IDFBlocks) {
      IRBuilder<> Builder(BB, BB->begin());
      PHINode *PN = Builder.CreatePHI(R.Ty, 0, R.Name);
      R.Defines[BB] = PN;
      NewPHIs.push_back(PN);
      if (InsertedPHIs)
        InsertedPHIs->push_back(PN);
    }

    // Populate PHI node operands.
    for (auto *PN : NewPHIs) {
      BasicBlock *PhiBB = PN->getParent();
      for (BasicBlock *Pred : PredCache.get(PhiBB))
        PN->addIncoming(computeValueAt(Pred, R, DT), Pred);
    }

    // Replace actual uses with computed values.
    SmallPtrSet<Use *, 4> HandledUses;
    for (Use *U : R.Uses) {
      if (!HandledUses.insert(U).second)
        continue;

      Value *NewVal = computeValueAt(getUserBB(U), R, DT);
      Value *OldVal = U->get();
      assert(OldVal && "Invalid use!");

      // Notify value handles about replacement.
      if (OldVal != NewVal && OldVal->hasValueHandle())
        ValueHandleBase::ValueIsRAUWd(OldVal, NewVal);

      LLVM_DEBUG(dbgs() << "SSAUpdater: replacing " << *OldVal << " with " << *NewVal << "\n");
      U->set(NewVal);
    }
  }
}

