// Normalizes an angle in degrees to the range [-180, 180)
float Math::wrapDegrees(float angle) 
{
	while(angle >= 360.0f) angle -= 360.0f;
	if (angle >= 180.0f) angle -= 360.0f;
	if (angle < -180.0f) angle += 360.0f;
	return angle;
}

// Normalizes an angle in degrees to the range [-180, 180) for double precision
double Math::wrapDegrees(double angle) 
{
	while(angle >= 360.0) angle -= 360.0;
	if (angle >= 180.0) angle -= 360.0;
	if (angle < -180.0) angle += 360.0;
	return angle;
}

