#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    // Speed up I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int size;
    if (!(cin >> size)) return 0;

    // Array with 1-based indexing
    vector<int> arr(size + 1);
    for (int idx = 1; idx <= size; ++idx) {
        cin >> arr[idx];
    }

    // Fixed pivot value: 3
    // This yields reversal lengths of 2 and 4, enabling moves of distance 1 and 3.
    cout << 3 << "\n";
    vector<pair<int, int>> operations;

    // Lambda to record and apply a reversal operation
    auto apply_reverse = [&](int left, int right) {
        operations.emplace_back(left, right);
        reverse(arr.begin() + left, arr.begin() + right + 1);
    };

    // Greedy sorting: place smallest/largest remaining elements in correct positions
    int leftBound = 1, rightBound = size;
    while (leftBound < rightBound) {
        int posMin = -1, posMax = -1;

        // Locate current positions of values 'leftBound' and 'rightBound'
        for (int i = 1; i <= size; ++i) {
            if (arr[i] == leftBound) posMin = i;
            if (arr[i] == rightBound) posMax = i;
        }

        // Compute distances to target positions
        int distToStart = posMin - leftBound;
        int distToEnd = rightBound - posMax;

        // Choose the more efficient move based on approximate cost (distance / 3)
        if (distToStart <= distToEnd) {
            // Move element with value 'leftBound' to position 'leftBound'
            int currentPos = posMin;
            while (currentPos > leftBound) {
                if (currentPos - 3 >= leftBound) {
                    // Perform length-4 reversal (jump by 3 positions)
                    apply_reverse(currentPos - 3, currentPos);
                    currentPos -= 3;
                } else {
                    // Perform length-2 reversal (jump by 1 position)
                    apply_reverse(currentPos - 1, currentPos);
                    currentPos -= 1;
                }
            }
            leftBound++;
        } else {
            // Move element with value 'rightBound' to position 'rightBound'
            int currentPos = posMax;
            while (currentPos < rightBound) {
                if (currentPos + 3 <= rightBound) {
                    // Perform length-4 reversal (jump by 3 positions)
                    apply_reverse(currentPos, currentPos + 3);
                    currentPos += 3;
                } else {
                    // Perform length-2 reversal (jump by 1 position)
                    apply_reverse(currentPos, currentPos + 1);
                    currentPos += 1;
                }
            }
            rightBound--;
        }
    }

    // Output number of operations followed by each operation
    cout << operations.size() << "\n";
    for (const auto& op : operations) {
        cout << op.first << " " << op.second << "\n";
    }

    return 0;
}

