#include <assert.h>
#include <math.h>
#include <mpi.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Generates an array filled with random values between 0 and 1
float*
generate_random_values(int count)
{
    float* values = (float*) malloc(sizeof(float) * count);
    assert(values != NULL);
    for(int idx = 0; idx < count; idx++)
    {
        values[idx] = (rand() / (float) RAND_MAX);
    }
    return values;
}

int
main(int argc, char** argv)
{
    if(argc != 2)
    {
        fprintf(stderr, "Usage: std_dev num_elements_per_process\n");
        exit(1);
    }

    int elements_per_process = atoi(argv[1]);

    MPI_Init(NULL, NULL);

    int process_rank;
    MPI_Comm_rank(MPI_COMM_WORLD, &process_rank);

    int total_processes;
    MPI_Comm_size(MPI_COMM_WORLD, &total_processes);

    // Initialize random seed based on process rank to ensure different sequences
    srand(time(NULL) * process_rank);

    float* random_data = NULL;
    random_data = generate_random_values(elements_per_process);

    // Compute local sum of elements
    float partial_sum = 0.0f;
    for(int j = 0; j < elements_per_process; j++)
    {
        partial_sum += random_data[j];
    }

    // Aggregate all local sums to compute global sum
    float total_sum;
    MPI_Allreduce(&partial_sum, &total_sum, 1, MPI_FLOAT, MPI_SUM, MPI_COMM_WORLD);

    float average = total_sum / (elements_per_process * total_processes);

    // Compute local sum of squared deviations from the mean
    float partial_sq_dev = 0.0f;
    for(int k = 0; k < elements_per_process; k++)
    {
        float diff = random_data[k] - average;
        partial_sq_dev += diff * diff;
    }

    // Gather all local squared deviations at root process
    float total_sq_dev;
    MPI_Reduce(&partial_sq_dev, &total_sq_dev, 1, MPI_FLOAT, MPI_SUM, 0, MPI_COMM_WORLD);

    // Calculate standard deviation only on root process
    if(process_rank == 0)
    {
        float variance = total_sq_dev / (elements_per_process * total_processes);
        float standard_deviation = sqrt(variance);
        printf("Average - %f, Standard deviation = %f\n", average, standard_deviation);
    }

    // Cleanup resources
    free(random_data);
    MPI_Barrier(MPI_COMM_WORLD);
    MPI_Finalize();
}

#include "ReduceGlobalVars.h"
#include "Utils.h"
#include "llvm/IR/Constants.h"
#include "llvm/Transforms/Utils/ModuleUtils.h"
using namespace llvm;

static bool shouldAlwaysRetain(const GlobalVariable &GV) {
  return GV.getName() == "llvm.used" || GV.getName() == "llvm.compiler.used";
}

/// Eliminates all GVs that are not part of the specified chunks.
static void pruneGVsFromModule(Oracle &O, ReducerWorkItem &WorkItem) {
  Module &Program = WorkItem.getModule();

  // Collect GVs that belong to the target chunks
  std::vector<Constant *> DesiredGVs;
  for (auto &GV : Program.globals()) {
    if (shouldAlwaysRetain(GV) || O.shouldKeep())
      DesiredGVs.push_back(&GV);
  }

  // Build a set from the vector to avoid repeated rebalancing costs
  DenseSet<Constant *> KeepList(DesiredGVs.begin(), DesiredGVs.end());

  // Identify globals to remove
  DenseSet<Constant *> RemoveList;
  for (auto &GV : Program.globals()) {
    if (!KeepList.count(&GV))
      RemoveList.insert(&GV);
  }

  // Clean up references in llvm.used / llvm.compiler.used lists
  removeFromUsedLists(Program,
                      [&RemoveList](Constant *C) { return RemoveList.count(C); });

  // Replace uses and erase removed globals
  for (auto *GV : RemoveList) {
    GV->replaceAllUsesWith(getDefaultValue(GV->getType()));
    cast<GlobalVariable>(GV)->eraseFromParent();
  }
}

void llvm::reduceGlobalsDeltaPass(TestRunner &Test) {
  runDeltaPass(Test, pruneGVsFromModule, "Eliminating GlobalVariables");
}

