#include <grpc++/grpc++.h>
#include "bzl/examples/grpc/proto/test_service.grpc.pb.h"

using grpc::Server;
using grpc::ServerBuilder;
using grpc::ServerContext;
using grpc::Status;
using test_service_package::IntRequest;
using test_service_package::IntReply;
using test_service_package::Decompositor;

using namespace std::chrono_literals;

namespace 
{
  std::unique_ptr<Server> gMainServer;
  auto gServerTimeout = 15s;
}

// Logic and data behind the server's behavior.
class DecompositionServiceImpl final : public Decompositor::Service 
{

  Status Decompose(ServerContext* context, 
                   const IntRequest* request,
                   IntReply* reply) override {
    int target_value = request->value();
    std::vector<int> parts;

    while (target_value != 0)
    {
      std::random_device seed_generator;
      std::mt19937 random_engine(seed_generator());
      std::uniform_int_distribution<> distribution(1, target_value);
      int current_part = distribution(random_engine);
      parts.push_back(current_part);
      target_value -= current_part;
    }

    std::string result_string;
    for(auto part : parts)
    {
      result_string += std::to_string(part) + " + ";
    }

    result_string.pop_back(); // Remove last space
    result_string.pop_back(); // Remove last '+'

    result_string += " = ";

    reply->set_message(result_string + std::to_string(request->value()));

    return Status::OK;
  }
};

void StartServer() {
  std::string listen_address("0.0.0.0:50052");
  DecompositionServiceImpl service;
  ServerBuilder builder;
  // Listen on the given address without any authentication mechanism.
  builder.AddListeningPort(listen_address, grpc::InsecureServerCredentials());
  // Register "service" as the instance through which we'll communicate with
  // clients. In this case it corresponds to an *synchronous* service.
  builder.RegisterService(&service);
  // Finally assemble the server.
  gMainServer = builder.BuildAndStart();
  std::cout << "Server started on " << listen_address << std::endl;
  // Wait for the server to shutdown. Note that some other thread must be
  // responsible for shutting down the server for this call to ever return.
  gMainServer->Wait();
}

void shutdown_server_after_timeout()
{
  std::this_thread::sleep_for(gServerTimeout);
  std::cout << "Initiating server shutdown after " << gServerTimeout.count() << " seconds" << std::endl;
  gMainServer->Shutdown(); 
}

int main(int argc, char** argv) {

  std::thread worker_thread(shutdown_server_after_timeout);
  StartServer();
  worker_thread.join();
  return 0;
}

