#include <asio/ts/executor.hpp>
#include <asio/thread_pool.hpp>
#include <iostream>
#include <string>

using asio::bind_executor;
using asio::dispatch;
using asio::make_work_guard;
using asio::post;
using asio::thread_pool;

// Asynchronously reads one line from an input stream and passes it to the handler
template <typename CompletionToken>
void async_readline(std::istream& input_stream, CompletionToken token)
{
  // Create a work guard for the handler's executor to prevent premature pool termination
  auto guard = make_work_guard(token);

  // Schedule the actual reading operation to run asynchronously
  post([input_stream, guard, token=std::move(token)]() mutable
      {
        std::string buffer;
        std::getline(input_stream, buffer);

        // Ensure the handler is invoked through the associated executor
        dispatch(guard.get_executor(),
            [buffer=std::move(buffer), token=std::move(token)]() mutable
            {
              token(std::move(buffer));
            });
      });
}

int main()
{
  thread_pool worker_pool;
  std::cout << "Please enter a line: ";

  async_readline(std::cin,
      bind_executor(worker_pool, [](std::string data)
        {
          std::cout << "Received: " << data << "\n";
        }));

  worker_pool.join();
}

