#include <string>
#include <sstream>
#include <sm/vvec>
#include <sm/bootstrap>
#include <sm/random>
#include <sm/histo>
#include <mplot/Visual.h>
#include <mplot/GraphVisual.h>
#include <sm/config>

int main()
{
    int exitCode = -1;
    // Perform bootstrap estimation of standard error for the sample mean
    sm::config settings ("../examples/bootstrap.json");

    // Generate data from a normal distribution (mean, sigma)
    double param_mean_1 = settings.get<double>("dist1_mean", 5.0);
    double param_sigma_1 = settings.get<double>("dist1_sigma", 2.0);
    size_t sampleSize_1 = settings.get<size_t>("dist1_n", 1000);
    sm::rand_normal<double, std::mt19937_64> generator1(param_mean_1, param_sigma_1);
    sm::vvec<double> dataset1;
    dataset1.set_from(generator1.get(sampleSize_1));

    // Display basic statistics
    std::cout << "Standard deviation: " << dataset1.std() << std::endl;
    std::cout << "Std dev / sqrt(n): "
              << (dataset1.std() / std::sqrt(dataset1.size())) << std::endl;

    // Bootstrap estimation of standard error
    size_t resampleCount = settings.get<size_t>("num_resamples", 1024);
    double bootSE = sm::bootstrap::error_of_mean<double>(dataset1, resampleCount);
    std::cout << "Bootstrap standard error of mean: " << bootSE << std::endl;

    // Visualization setup
    mplot::Visual window(1400, 768, "Bootstrap Analysis");
    sm::histo<double, float> histogram1(dataset1, 100);
    auto graphView1 = std::make_unique<mplot::GraphVisual<float>>(sm::vec<float>({-2, 0, 0}));
    window.bindmodel(graphView1);
    graphView1->setdata(histogram1);
    graphView1->xlabel = "Value";
    graphView1->ylabel = "Proportion";

    {
        std::string meanLabel = "Mean: ";
        meanLabel += std::to_string(dataset1.mean());
        graphView1->addLabel(meanLabel, sm::vec<float>({1.1, 0.66, 0}), mplot::TextFeatures(0.05f));

        std::string sdLabel = "StdDev: ";
        sdLabel += std::to_string(dataset1.std());
        graphView1->addLabel(sdLabel, sm::vec<float>({1.1, 0.58, 0}), mplot::TextFeatures(0.05f));

        std::string semLabel = "SEM = SD/";
        semLabel += mplot::unicode::toUtf8(mplot::unicode::sqrt);
        semLabel += std::to_string(dataset1.size()) + " = ";
        semLabel += std::to_string(dataset1.std() / std::sqrt(dataset1.size()));
        graphView1->addLabel(semLabel, sm::vec<float>({1.1, 0.5, 0}), mplot::TextFeatures(0.05f));

        std::string bsLabel = "Boot. SE: ";
        bsLabel += std::to_string(bootSE);
        graphView1->addLabel(bsLabel, sm::vec<float>({1.1, 0.42, 0}), mplot::TextFeatures(0.05f));
    }

    // Second dataset generation and analysis
    double param_mean_2 = settings.get<double>("dist2_mean", 5.0);
    double param_sigma_2 = settings.get<double>("dist2_sigma", 2.0);
    size_t sampleSize_2 = settings.get<size_t>("dist2_n", 1000);
    sm::rand_normal<double, std::mt19937_64> generator2(param_mean_2, param_sigma_2);
    sm::vvec<double> dataset2;
    dataset2.set_from(generator2.get(sampleSize_2));

    double bootSE2 = sm::bootstrap::error_of_mean<double>(dataset2, resampleCount);
    std::cout << "Second dataset bootstrap SE: " << bootSE2 << std::endl;

    sm::vec<double, 2> aslResult = sm::bootstrap::ttest_equalityofmeans<double>(dataset1, dataset2, resampleCount);
    std::cout << "Achieved significance level: " << aslResult[0] 
              << " (min possible: " << aslResult[1] << ")\n";

    sm::histo<double, float> histogram2(dataset2, 100);
    auto graphView2 = std::make_unique<mplot::GraphVisual<float>>(sm::vec<float>({0, 0, 0}));
    window.bindmodel(graphView2);
    graphView2->setdata(histogram1);
    graphView2->setdata(histogram2);
    graphView2->xlabel = "Value";
    graphView2->ylabel = "Proportion";

    {
        std::string meanLabel2 = "Mean: ";
        meanLabel2 += std::to_string(dataset2.mean());
        graphView2->addLabel(meanLabel2, sm::vec<float>({1.1, 0.66, 0}), mplot::TextFeatures(0.05f));

        std::string sdLabel2 = "StdDev2: ";
        sdLabel2 += std::to_string(dataset2.std());
        graphView2->addLabel(sdLabel2, sm::vec<float>({1.1, 0.58, 0}), mplot::TextFeatures(0.05f));

        std::string semLabel2 = "SEM2 = SD2/";
        semLabel2 += mplot::unicode::toUtf8(mplot::unicode::sqrt);
        semLabel2 += std::to_string(dataset2.size()) + " = ";
        semLabel2 += std::to_string(dataset2.std() / std::sqrt(dataset1.size()));
        graphView2->addLabel(semLabel2, sm::vec<float>({1.1, 0.5, 0}), mplot::TextFeatures(0.05f));

        std::string bsLabel2 = "Boot. SE2: ";
        bsLabel2 += std::to_string(bootSE2);
        graphView2->addLabel(bsLabel2, sm::vec<float>({1.1, 0.42, 0}), mplot::TextFeatures(0.05f));

        graphView2->addLabel("ASL: " + aslResult.str(), 
                             sm::vec<float>({1.1, 0.34, 0}), mplot::TextFeatures(0.05f));

        // Significance decision label
        double alphaLevel = settings.get<double>("chosen_significance_level", 0.01);
        std::stringstream decisionStream;
        if (aslResult[0] < aslResult[1]) {
            decisionStream << "Reject null hypothesis at α=" << alphaLevel << ".\n"
                           << "Probability of same mean < min ASL.\n"
                           << "Min measurable ASL with " << resampleCount << " resamples: " << aslResult[1];
        } else if (aslResult[0] < alphaLevel) {
            decisionStream << "Reject null hypothesis at α=" << alphaLevel << ".\n"
                           << "Probability of same mean: " << aslResult[0];
        } else {
            decisionStream << "Fail to reject null hypothesis.\n"
                           << "α=" << alphaLevel << ", ASL=" << aslResult[0];
        }
        graphView2->addLabel(decisionStream.str(), 
                             sm::vec<float>({0.0, -0.27, 0}), mplot::TextFeatures(0.05f));
    }

    graphView1->finalize();
    graphView2->finalize();
    window.addVisualModel(graphView1);
    window.addVisualModel(graphView2);
    window.keepOpen();
    return exitCode;
}

#include <vector>
