using namespace std;

// Definition for a binary tree node.
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode() : val(0), left(nullptr), right(nullptr) {}
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
    TreeNode(int x, TreeNode *l, TreeNode *r) : val(x), left(l), right(r) {}
};

class Validator {
public:
    void collectInorder(TreeNode* node, vector<int>& result) {
        if (!node) return;
        collectInorder(node->left, result);
        result.push_back(node->val);
        collectInorder(node->right, result);
    }

    bool checkValidBST(TreeNode* root) {
        vector<int> sequence;
        collectInorder(root, sequence);

        // Verify the sequence is strictly increasing
        for (int idx = 1; idx < sequence.size(); ++idx) {
            if (sequence[idx] <= sequence[idx - 1]) {
                return false;
            }
        }
        return true;
    }
};

#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <tuple>

// Stores the generated edges in the form (source, intermediate, target)
std::vector<std::tuple<int, int, int>> generated_edges;

/**
 * @brief Constructs edges for a specific jump size.
 *
 * For a given jump distance `dist`, this function creates an edge from `start`
 * to `start + dist` for all valid starting positions. The edge is justified by
 * the existing path: `start -> start + first_part -> start + dist`, where
 * `first_part` and `second_part = dist - first_part` are pre-existing jumps.
 *
 * @param dist Size of the jump to be created.
 * @param max_vertex Maximum vertex index in the graph.
 * @param first_part Length of the first segment in the decomposition.
 * @param second_part Length of the second segment in the decomposition.
 */
void construct_jump(int dist, int max_vertex, int first_part, int second_part) {
    if (dist > max_vertex) return;
    for (int start = 0; start <= max_vertex - dist; ++start) {
        generated_edges.emplace_back(start, start + first_part, start + dist);
    }
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::cin >> n;

    // Handle trivial cases
    if (n <= 1) {
        std::cout << 0 << '\n';
        return 0;
    }

    // Determine optimal parameter k to minimize total edges
    // Approximate formula: minimize (2k + n/k^2), solution near k = n^(1/3)
    int k_param = 1;
    if (n > 0) {
        k_param = static_cast<int>(std::round(std::pow(n, 1.0 / 3.0)));
    }
    if (k_param <= 1 && n > 1) {
        k_param = 2; // Ensure k is at least 2 for correctness
    }

    // Step 1: Build small jumps [2, k-1] using previous jumps
    for (int jump_len = 2; jump_len < k_param; ++jump_len) {
        construct_jump(jump_len, n, jump_len - 1, 1);
    }

    // Step 2: Build multiples of k: {k, 2k, ..., (k-1)k}
    if (k_param <= n) {
        construct_jump(k_param, n, k_param - 1, 1);
    }
    for (int multiplier = 2; multiplier < k_param; ++multiplier) {
        construct_jump(multiplier * k_param, n, (multiplier - 1) * k_param, k_param);
    }

    // Step 3: Build multiples of k^2: {k^2, 2k^2, ..., A*k^2} where A = floor(n/k^2)
    int square_k = k_param * k_param;
    if (square_k <= n) {
        construct_jump(square_k, n, (k_param - 1) * k_param, k_param);
    }
    int max_multiplier = n / square_k;
    for (int mult = 2; mult <= max_multiplier; ++mult) {
        construct_jump(mult * square_k, n, (mult - 1) * square_k, square_k);
    }

    // Output results
    std::cout << generated_edges.size() << '\n';
    for (const auto& edge : generated_edges) {
        std::cout << std::get<0>(edge) << " "
                  << std::get<1>(edge) << " "
                  << std::get<2>(edge) << '\n';
    }

    return 0;
}

