#include "json.h"
#include "wrapper.h"
#include <library/cpp/json/json_value.h>
using namespace NJson;

void NLua::PushJsonValue(TLuaStateHolder* ctx, const TJsonValue& value) {
    // Each recursive invocation will explicitly push only one item onto the stack,
    // delegating stack space reservation to deeper calls.
    // For instance, for an object {"key": "val"}, the initial call allocates room for create_table,
    // then PushJsonValue is invoked for the string value, which in turn reserves space for that string.
    // Therefore, a single ensure_stack call at the beginning suffices.
    ctx->ensure_stack(1);

    switch (value.GetType()) {
        case JSON_UNDEFINED:
            ythrow yexception() << "cannot push undefined json value";
        case JSON_NULL:
            ctx->push_nil();
            break;
        case JSON_BOOLEAN:
            ctx->push_bool(value.GetBoolean());
            break;
        case JSON_INTEGER:
            ctx->push_number(value.GetInteger());
            break;
        case JSON_UINTEGER:
            ctx->push_number(value.GetUInteger());
            break;
        case JSON_DOUBLE:
            ctx->push_number(value.GetDouble());
            break;
        case JSON_STRING:
            ctx->push_string(value.GetString());
            break;
        case JSON_MAP: {
            ctx->create_table();
            int pos = 1; // Lua uses 1-based indexing for arrays
            for (const auto& entry : value.GetMap()) {
                PushJsonValue(ctx, entry.second); // Recursive call handles its own stack needs
                ctx->set_field(-2, entry.first.data());
            }
            break;
        }
        case JSON_ARRAY: {
            ctx->create_table();
            int idx = 1; // Lua tables are 1-indexed by convention
            for (const auto& item : value.GetArray()) {
                PushJsonValue(ctx, item); // Recursive call manages its own stack requirements
                ctx->rawseti(-2, idx++);
            }
            break;
        }
        default:
            ythrow yexception() << "Unexpected json value type";
    }
}

#include <mplot/Visual.h>
#include <mplot/GraphVisual.h>
#include <sm/vvec>

int main()
{
    // Initialize a mplot::Visual window with specified dimensions and title
    mplot::Visual scene(1024, 768, "Generated using mplot::GraphVisual");

    // Instantiate a GraphVisual object for double-precision data, positioned at origin
    auto graph = std::make_unique<mplot::GraphVisual<double>>(sm::vec<float>({0.0f, 0.0f, 0.0f}));

    // Essential initialization step: associate the model with the visual scene
    scene.bindmodel(graph);

    // Prepare x-axis data using sm::vvec (a vector-like container with mathematical operations)
    sm::vvec<double> abscissa;

    // Generate evenly spaced points from -0.5 to 0.8, totaling 14 samples
    abscissa.linspace(-0.5, 0.8, 14);

    // Define the function y = x^3 and assign it to the graph
    graph->setdata(abscissa, abscissa.pow(3));

    // Finalize graph setup: compute OpenGL vertex data for rendering
    graph->finalize();

    // Transfer ownership of the graph model to the visual scene
    scene.addVisualModel(graph);

    // Display the visualization and wait for user to exit (Ctrl-q)
    scene.keepOpen();

    // Automatic cleanup occurs when 'scene' goes out of scope, releasing the graph resource
    return 0;
}

