namespace engine::store::filter::filesys::filesys {
//-----------------------------------------------------------------
// Register the filesys protocol config with the Url system. This
// enables usage of Url::toPath(...), Url::toUrl(...), etc. Note that
// we only supply the osPath since the service manager will
// register generic toPath, toUrl and capabilities
//-----------------------------------------------------------------
static url::UrlConfig urlConfig{
    {//------------------------------------------------------------
     /// @details
     ///	Specify the protocol identifier
     //------------------------------------------------------------
     .protocol = Type,
     //-------------------------------------------------------------
     /// @details
     ///		This function transforms a path (with prefix stripped) into an absolute
     ///		path compatible with the underlying operating system.
     ///
     ///		Under Linux:
     ///			input: ("usr", "dir", "file.txt")
     ///			output: /usr/dir/file
     ///
     ///		Under Windows:
     ///			input: ("C:", "dir", "file.txt")
     ///			output: //./C:/dir/file.txt
     ///
     ///	@param[in] sourceUrl
     ///		The URL object to convert
     ///	@param[out] destinationPath
     ///		Receives the OS-compatible string representation of the path
     ///	@returns
     ///		Error code indicating success or failure
     //------------------------------------------------------------
     .osPath = [](const Url &sourceUrl, Text &destinationPath) -> Error {
         // Extract the internal path representation
         Path intermediatePath;
         if (auto errorCode = urlConfig.toPath(sourceUrl, intermediatePath)) return errorCode;
#ifdef ROCKETRIDE_PLAT_WIN
         // On Windows, delegate directly to platform-specific conversion
         destinationPath = intermediatePath.plat();
#else
         // On Linux/Unix systems, ensure absolute paths start with "/"
         // Since URLs like filesys://FileSystem/dir/file.txt yield relative paths internally,
         // prepend "/" when missing
         if (!intermediatePath.isAbsolute()) {
             destinationPath = "/" + intermediatePath.plat();
         } else {
             destinationPath = intermediatePath.plat();
         }
#endif
         return {};
     }}};
}  // namespace engine::store::filter::filesys::filesys

