void process() {
    // First query: 100000 words of length 1
    std::cout << "? 100000";
    for (int idx = 0; idx < 100000; ++idx) {
        std::cout << " 1";
    }
    std::cout << std::endl;

    long long response1;
    std::cin >> response1;

    if (response1 == -1) { // Handle error condition
        return;
    }

    if (response1 == 1) {
        std::cout << "! 100000" << std::endl;
        return;
    }

    // Compute the possible range [min_len, max_len] based on response1
    long long min_len = (100000LL + response1 - 1) / response1;
    long long max_len = (100000LL - 1) / (response1 - 1);

    if (min_len == max_len) {
        std::cout << "! " << min_len << std::endl;
        return;
    }

    // Second query: construct article to determine exact word count
    long long range_size = max_len - min_len + 1;
    long long n2 = 2 * (range_size - 1);

    std::cout << "? " << n2;
    for (long long k = 1; k < range_size; ++k) {
        std::cout << " " << min_len << " " << k;
    }
    std::cout << std::endl;

    long long response2;
    std::cin >> response2;

    if (response2 == -1) { // Handle error condition
        return;
    }

    // Derive final answer from second response
    long long result = 2 * max_len - min_len - response2;
    std::cout << "! " << result << std::endl;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int test_cases;
    std::cin >> test_cases;

    while (test_cases--) {
        process();
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <tuple>

// Stores the generated edges as tuples (source, intermediate, destination)
std::vector<std::tuple<int, int, int>> generated_edges;

// Tracks whether an edge already exists to prevent duplicates
bool edge_exists[4100][4100] = {false};

// Adds an edge from u to v via intermediate node c if it's not already present
void insert_new_edge(int u, int c, int v) {
    if (u >= v) return;
    if (!edge_exists[u][v]) {
        generated_edges.emplace_back(u, c, v);
        edge_exists[u][v] = true;
    }
}

// Recursively constructs required connections between nodes in range [l, r]
void construct_connections(int l, int r) {
    // Base case: no further splitting needed for adjacent nodes
    if (r - l <= 1) {
        return;
    }

    // Split the current segment into two halves
    int mid = l + (r - l) / 2;

    // Process left and right halves recursively
    construct_connections(l, mid);
    construct_connections(mid, r);

    // Connect nodes from left half to the midpoint
    int left_mid = l + (mid - l) / 2;
    for (int i = l; i < mid; ++i) {
        insert_new_edge(i, left_mid, mid);
    }

    // Connect the midpoint to nodes in the right half
    int right_mid = mid + (r - mid) / 2;
    for (int j = mid + 1; j <= r; ++j) {
        insert_new_edge(mid, right_mid, j);
    }
}

int main() {
    // Optimize I/O performance
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::cin >> n;

    if (n > 0) {
        // Initialize direct edges between consecutive nodes: i -> i+1
        for (int i = 0; i < n; ++i) {
            edge_exists[i][i + 1] = true;
        }

        // Build additional necessary edges
        construct_connections(0, n);
    }

    // Output number of new edges and their details
    std::cout << generated_edges.size() << "\n";
    for (const auto& e : generated_edges) {
        std::cout << std::get<0>(e) << " " << std::get<1>(e) << " " << std::get<2>(e) << "\n";
    }

    return 0;
}

