// Implements a file output stream for writing data to a file
FileOutputStream::FileOutputStream(const File &file) : m_fileHandle( INVALID_HANDLE_VALUE )
{
	if( file.exists() && file.isDirectory())
	{
		// TODO 4J Stu - FileNotFoundException
		return;
	}
#ifdef _DURANGO
	m_fileHandle = CreateFile(
		file.getPath().c_str(), // file name
		GENERIC_WRITE,          // access mode
		0,                      // share mode
		NULL,                   // security attributes (unused)
		OPEN_ALWAYS,            // creation disposition
		FILE_ATTRIBUTE_NORMAL,  // file attributes
		NULL                    // template file (unsupported)
		);
#elif defined(__linux__)
	std::wstring filePath = file.getPath();
	char* pathBuffer = new char[filePath.size() + 1];
	std::wcstombs(pathBuffer, filePath.c_str(), filePath.size() + 1);
	m_fileHandle = open(pathBuffer, O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR);
	delete[] pathBuffer;
#else
	m_fileHandle = CreateFile(
		wstringtofilename(file.getPath()), // file name
		GENERIC_WRITE,                     // access mode
		0,                                 // share mode
		NULL,                              // security attributes (unused)
		OPEN_ALWAYS,                       // creation disposition
		FILE_ATTRIBUTE_NORMAL,             // file attributes
		NULL                               // template file (unsupported)
		);
#endif
	if( m_fileHandle == INVALID_HANDLE_VALUE )
	{
		// TODO 4J Stu - Any form of error/exception handling
		DWORD lastError = GetLastError();
	}
}

FileOutputStream::~FileOutputStream()
{
	if( m_fileHandle != INVALID_HANDLE_VALUE )
		::close( m_fileHandle );
}

// Writes a single byte to the file
void FileOutputStream::write(unsigned int b)
{	
	byte value = static_cast<byte>(b);
#if defined(_WIN32)
	BOOL success = WriteFile(
		m_fileHandle,              // handle to file
		&value,                    // data buffer
		1,                         // number of bytes to write
		&bytesWritten,             // number of bytes written
		NULL                       // overlapped I/O (not used)
		);
#else // LINUX
	int fd = static_cast<int>(m_fileHandle);
	ssize_t result = ::write(fd, &value, 1);
	int success = (result == 1) ? 1 : 0;
#endif // _WIN32
	if( success == 0 )
	{
		// TODO 4J Stu - Some kind of error handling
	}
}

// Writes an entire byte array to the file
void FileOutputStream::write(byteArray b)
{
#if defined(_WIN32)
	BOOL success = WriteFile(
		m_fileHandle,              // handle to file
		b.data,                    // data buffer
		b.length,                  // number of bytes to write
		&bytesWritten,             // number of bytes written
		NULL                       // overlapped I/O (not used)
		);
#else // Linux
	int fd = static_cast<int>(m_fileHandle);
	ssize_t result = ::write(fd, b.data, b.length);
	int success = (result == static_cast<ssize_t>(b.length)) ? 1 : 0;
#endif // _WIN32
	if( success == 0 )
	{
		// TODO 4J Stu - Some kind of error handling
	}
}

// Writes a subarray of the given byte array to the file
void FileOutputStream::write(byteArray b, unsigned int offset, unsigned int length)
{
	// Ensure we don't write beyond array bounds
	assert( length <= ( b.length - offset ) );
#if defined(_WIN32)
	DWORD localBytesWritten;
	BOOL success = WriteFile(
		m_fileHandle,              // handle to file
		&b[offset],                // data buffer
		length,                    // number of bytes to write
		&localBytesWritten,        // number of bytes written
		NULL                       // overlapped I/O (not used)
		);
#else
	int fd = static_cast<int>(m_fileHandle);
	ssize_t result = ::write(fd, static_cast<const void*>(&b[offset]), length);
	int success = (result == static_cast<ssize_t>(length)) ? 1 : 0;
#endif // _WIN32
	if( success == 0 )
	{
		// TODO 4J Stu - Some kind of error handling
	}
}

// Closes the file stream and releases associated resources
void FileOutputStream::close()
{
#ifdef _WIN32
	BOOL success = CloseHandle( m_fileHandle );
#else // __linux__
	int success = ::close( m_fileHandle );
#endif // _WIN32
	if( success == 0 )
	{
		// TODO 4J Stu - Some kind of error handling
	}
	// Prevent double-close in destructor
	m_fileHandle = INVALID_HANDLE_VALUE;
}

#include <vector>
#include <set>
#include <algorithm>

class Solution {
    std::multiset<long long> leftSet, rightSet;
public:
    long long minimumCost(std::vector<int>& nums, int k, int dist) {
        int size = nums.size();
        int targetK = k - 1;
        long long currentSum = nums[0];

        // Initialize with first window elements
        for (int idx = 1; idx <= dist + 1; idx++) {
            currentSum += nums[idx];
            leftSet.insert(nums[idx]);
        }

        // Balance sets to have exactly targetK elements in leftSet
        while (leftSet.size() > static_cast<size_t>(targetK)) {
            currentSum -= *leftSet.rbegin();
            rightSet.insert(*leftSet.rbegin());
            leftSet.erase(leftSet.find(*leftSet.rbegin()));
        }

        long long result = currentSum;

        // Slide the window
        for (int idx = dist + 2; idx < size; idx++) {
            // Remove element going out of window
            if (leftSet.find(nums[idx - dist - 1]) != leftSet.end()) {
                currentSum -= nums[idx - dist - 1];
                leftSet.erase(leftSet.find(nums[idx - dist - 1]));
            } else {
                rightSet.erase(rightSet.find(nums[idx - dist - 1]));
            }

            // Add new element
            if (nums[idx] < *leftSet.rbegin()) {
                currentSum += nums[idx];
                leftSet.insert(nums[idx]);
            } else {
                rightSet.insert(nums[idx]);
            }

            // Rebalance leftSet to have exactly targetK elements
            while (leftSet.size() < static_cast<size_t>(targetK)) {
                currentSum += *rightSet.begin();
                leftSet.insert(*rightSet.begin());
                rightSet.erase(rightSet.find(*rightSet.begin()));
            }

            while (leftSet.size() > static_cast<size_t>(targetK)) {
                currentSum -= *leftSet.rbegin();
                rightSet.insert(*leftSet.rbegin());
                leftSet.erase(leftSet.find(*leftSet.rbegin()));
            }

            result = std::min(result, currentSum);
        }

        return result;
    }
};

