// A class for consuming buffer sequences in a streaming fashion
template<bool IsMutable>
class buffer_consumer
{
public:
    /** The type of buffer returned by the consumer
    */
    using buffer_type = std::conditional_t<
        IsMutable, mutable_buffer, const_buffer>;

    /** Destructor
    */
    virtual ~buffer_consumer() = default;

    /** Check if there are no more buffers available
        @return `true` if no buffers remain, `false` otherwise.
    */
    virtual bool is_empty() const noexcept = 0;

    /** Retrieve the next batch of buffers
        @param out A pointer to an array where buffers will be stored
        @param max_count The maximum number of buffers to store in `out`
        @return The actual number of buffers copied into `out`
    */
    virtual std::size_t get_next(
        buffer_type* out, std::size_t max_count) = 0;
};

/** Adapter that wraps a BufferSequence as a consumer
    This class converts any valid BufferSequence into a consumer interface.
*/
template<class BufferSequence>
class buffer_consumer_adapter : public buffer_consumer<
    is_mutable_buffer_sequence_v<BufferSequence>>
{
    BufferSequence seq_;
    decltype(begin(seq_)) current_;
    decltype(end(seq_)) finish_;
public:
    template<class T>
    buffer_consumer_adapter(T&& t)
        : seq_(std::forward<T>(t))
        , current_(begin(seq_))
        , finish_(end(seq_))
    {
    }

    bool is_empty() const noexcept override
    {
        return current_ == finish_;
    }

    std::size_t get_next(typename
        buffer_consumer_adapter::buffer_type* out, std::size_t max_count) override
    {
        std::size_t count = 0;
        while(current_ != finish_ && max_count--)
        {
            *out++ = typename buffer_consumer_adapter::buffer_type(*current_++);
            ++count;
        }
        return count;
    }
};

