#include <array>
#include <future>
#include <iostream>
#include <thread>
#include <asio/io_context.hpp>
#include <asio/ip/udp.hpp>
#include <asio/use_future.hpp>

using asio::ip::udp;

void fetch_time(asio::io_context& ctx, const char* server_name)
{
  try
    {
      udp::resolver r(ctx);
      std::future<udp::resolver::results_type> result =
        r.async_resolve(udp::v4(), server_name, "daytime",
                        asio::use_future);

      udp::socket sock(ctx, udp::v4());
      std::array<char, 1> request = {{ 0 }};
      std::future<std::size_t> bytes_sent =
        sock.async_send_to(asio::buffer(request),
                           *result.get().begin(),
                           asio::use_future);

      // Perform other tasks while send is in progress
      bytes_sent.get(); // Wait for send to finish

      std::array<char, 256> response;
      udp::endpoint remote_endpoint;
      std::future<std::size_t> bytes_received =
        sock.async_receive_from(asio::buffer(response),
                                remote_endpoint,
                                asio::use_future);

      // Do additional work here before blocking on receive
      std::size_t received = bytes_received.get(); // Block until data arrives
      std::cout.write(response.data(), received);
    }
  catch (const std::system_error& err)
    {
      std::cerr << err.what() << '\n';
    }
}

int main(int argc, char* argv[])
{
  try
    {
      if (argc != 2)
        {
          std::cerr << "Usage: daytime_client <server>" << std::endl;
          return 1;
        }

      asio::io_context context;
      auto guard = asio::make_work_guard(context);
      std::thread worker([&context](){ context.run(); });

      fetch_time(context, argv[1]);

      context.stop();
      worker.join();
    }
  catch (const std::exception& ex)
    {
      std::cerr << ex.what() << '\n';
    }

  return 0;
}

