using namespace std;

// Approximate LCS using greedy skip-cost heuristic
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    string str1, str2;
    if (!(cin >> str1 >> str2)) return 0;

    int len1 = (int)str1.size();
    int len2 = (int)str2.size();

    // Precompute positions for each character in both strings
    vector<int> charPos1[128];
    vector<int> charPos2[128];

    for (int idx = 0; idx < len1; ++idx) {
        unsigned char ch = static_cast<unsigned char>(str1[idx]);
        charPos1[ch].push_back(idx);
    }

    for (int idx = 0; idx < len2; ++idx) {
        unsigned char ch = static_cast<unsigned char>(str2[idx]);
        charPos2[ch].push_back(idx);
    }

    // Track current position in each character's position list
    vector<int> posPtr1(128, 0);
    vector<int> posPtr2(128, 0);

    string lcsStr;
    lcsStr.reserve(min(len1, len2));

    int i1 = 0, i2 = 0;
    const int BIG_NUM = 2000000000;

    while (i1 < len1 && i2 < len2) {
        unsigned char c1 = static_cast<unsigned char>(str1[i1]);
        unsigned char c2 = static_cast<unsigned char>(str2[i2]);

        if (c1 == c2) {
            lcsStr += static_cast<char>(c1);
            ++i1;
            ++i2;
        } else {
            // Find next occurrence of c1 in str2 starting from i2
            int nextMatchInStr2 = -1;
            while (posPtr2[c1] < (int)charPos2[c1].size() && charPos2[c1][posPtr2[c1]] < i2) {
                ++posPtr2[c1];
            }
            if (posPtr2[c1] < (int)charPos2[c1].size()) {
                nextMatchInStr2 = charPos2[c1][posPtr2[c1]];
            }

            // Find next occurrence of c2 in str1 starting from i1
            int nextMatchInStr1 = -1;
            while (posPtr1[c2] < (int)charPos1[c2].size() && charPos1[c2][posPtr1[c2]] < i1) {
                ++posPtr1[c2];
            }
            if (posPtr1[c2] < (int)charPos1[c2].size()) {
                nextMatchInStr1 = charPos1[c2][posPtr1[c2]];
            }

            int cost1 = (nextMatchInStr2 == -1) ? BIG_NUM : (nextMatchInStr2 - i2);
            int cost2 = (nextMatchInStr1 == -1) ? BIG_NUM : (nextMatchInStr1 - i1);

            if (cost1 == BIG_NUM && cost2 == BIG_NUM) {
                // No matching characters ahead in either string
                ++i1;
                ++i2;
            } else if (cost1 <= cost2) {
                // Prefer matching c1 from str1 with its next occurrence in str2
                lcsStr += static_cast<char>(c1);
                ++i1;
                i2 = nextMatchInStr2 + 1;
            } else {
                // Prefer matching c2 from str2 with its next occurrence in str1
                lcsStr += static_cast<char>(c2);
                i1 = nextMatchInStr1 + 1;
                ++i2;
            }
        }
    }

    cout << lcsStr << '\n';
    return 0;
}

