#include "ELD/PluginAPI/OutputSectionIteratorPlugin.h"
#include "ELD/PluginAPI/PluginVersion.h"

class InsertNewRule : public eld::plugin::OutputSectionIteratorPlugin {
public:
  InsertNewRule() : eld::plugin::OutputSectionIteratorPlugin("InsertNewRule") {}

  // Initialization logic - not required for this plugin
  void Init(std::string config) override {}

  // Process each output section during linking
  void processOutputSection(eld::plugin::OutputSection section) override {
    // Only operate during CreatingSections phase
    if (Linker->getState() != eld::plugin::LinkerWrapper::State::CreatingSections)
      return;

    std::string name = section.getName();
    if (name == "data_section") {
      m_Data = section;
    } else if (name == "text_section") {
      m_Text = section;
    } else if (name == "rodata_section") {
      m_Rodata = section;
    }
  }

  // Execute the main plugin logic after processing all sections
  eld::plugin::Plugin::Status Run(bool trace) override {
    if (Linker->getState() != eld::plugin::LinkerWrapper::State::CreatingSections)
      return eld::plugin::Plugin::Status::SUCCESS;

    auto lastRule = m_Data.getLinkerScriptRules().back();

    // Create a new rule with descriptive annotation
    eld::plugin::LinkerScriptRule newRule = Linker->createLinkerScriptRule(
        m_Data, /*Annotation=*/"Transfer text and rodata chunks to data");

    // Add the new rule after the last existing rule in data_section
    Linker->insertAfterRule(m_Data, lastRule, newRule);

    // Move chunks from text and rodata sections to the new rule
    moveChunks(m_Text, newRule);
    moveChunks(m_Rodata, newRule);

    return eld::plugin::Plugin::Status::SUCCESS;
  }

  // Cleanup resources when plugin is destroyed
  void Destroy() override {}

  uint32_t GetLastError() override { return 0; }
  std::string GetLastErrorAsString() override { return "Success"; }
  std::string GetName() override { return "InsertNewRule"; }

private:
  // Helper function to move chunks between rules
  void moveChunks(eld::plugin::LinkerScriptRule sourceRule,
                  eld::plugin::LinkerScriptRule targetRule) {
    for (eld::plugin::Chunk chunk : sourceRule.getChunks()) {
      // Ensure chunk ownership is properly transferred
      Linker->addChunk(targetRule, chunk);
      Linker->removeChunk(sourceRule, chunk);
    }
  }

  // Overload to handle moving chunks from entire output sections
  void moveChunks(eld::plugin::OutputSection sourceSection,
                  eld::plugin::LinkerScriptRule targetRule) {
    for (eld::plugin::LinkerScriptRule rule : sourceSection.getLinkerScriptRules())
      moveChunks(rule, targetRule);
  }

private:
  eld::plugin::OutputSection m_Data = eld::plugin::OutputSection(nullptr);
  eld::plugin::OutputSection m_Text = eld::plugin::OutputSection(nullptr);
  eld::plugin::OutputSection m_Rodata = eld::plugin::OutputSection(nullptr);
};

