// Constructs an InputStreamReader that uses the default charset.
// Parameters:
// input - An InputStream pointer
InputStreamReader::InputStreamReader(InputStream *input) : stream( new DataInputStream( input ) )
{
}

// Closes the stream and frees any system resources tied to it.
// After closing, calls like read(), ready(), mark(), reset(), or skip() will throw an IOException.
// Closing an already closed stream has no effect.
void InputStreamReader::close()
{
    stream->close();
}

// Reads a single wide character.
// Returns:
// The character read, or -1 if end-of-stream is reached
int InputStreamReader::read()
{
    return stream->readUTFChar();
}

// Reads characters into a subarray of the given buffer.
// Parameters:
// buffer - Target array to store the characters
// startIndex - Starting index in the array where characters are placed
// maxChars - Upper limit on number of characters to read
// Returns:
// Number of characters actually read, or -1 if end-of-stream occurs
int InputStreamReader::read(wchar_t buffer[], unsigned int startIndex, unsigned int maxChars)
{
    unsigned int numRead = 0;
    for( unsigned int idx = startIndex; idx < startIndex + maxChars; idx++ )
    {
        wchar_t ch = (wchar_t)stream->readUTFChar();
        if( ch != -1 )
        {
            buffer[idx] = ch;
            numRead++;
        }
        else
        {
            break;
        }
    }
    return numRead;
}

