// Construct a Qt-based mplot application using widget rendering
int main(int argc, char** argv) {
    QApplication application(argc, argv);

    // Instantiate the visualization widget; OpenGL version is determined by template parameter
    // Index 0 indicates the first widget instance
    mplot::qt::viswidget<0> display_widget;

    // Displaying the widget triggers initialization of the OpenGL context via initializeGL()
    // Alternatively, one could configure the buildmodels callback (as demonstrated in app2)
    display_widget.show();

    // Create a GraphVisual object to represent data; specify spatial offset (0,0,0)
    auto graph_visual = std::make_unique<mplot::GraphVisual<double, mplot::qt::gl_version>>(
        sm::vec<float>({0.0f, 0.0f, 0.0f})
    );

    // Required setup: associate parent and bind internal callbacks
    display_widget.v.bindmodel(graph_visual);

    // Enable three-dimensional rendering
    graph_visual->twodimensional(false);

    // Prepare x-axis data using vvec (vector with vectorized operations)
    sm::vvec<double> x_values;

    // Generate evenly spaced points: start=-0.5, end=0.8, count=14
    x_values.linspace(-0.5, 0.8, 14);

    // Configure plot: y = x^3
    graph_visual->setdata(x_values, x_values.pow(3));

    // Finalize model construction: compute vertex data for OpenGL rendering
    graph_visual->finalize();

    // Transfer ownership of the visual model to the scene
    display_widget.v.addVisualModel(graph_visual);

    return application.exec();
}

#include <iostream>
#include <queue>
using namespace std;

int main() {
    // Create a max heap (default behavior)
    priority_queue<int> maxPQ;

    // Insert elements into the max heap
    maxPQ.push(10);
    maxPQ.push(20);
    maxPQ.push(30);
    maxPQ.push(40);
    maxPQ.emplace(50);

    // Extract and print elements in descending order
    while (!maxPQ.empty()) {
        cout << maxPQ.top() << " ";
        maxPQ.pop();
    }
    cout << endl;

    // Check properties after emptying the queue
    cout << "Max heap size after removal: " << maxPQ.size() << endl;
    cout << "Is max heap empty? " << (maxPQ.empty() ? "Yes" : "No") << endl;

    // Create a min heap using greater comparator
    priority_queue<int, vector<int>, greater<int>> minPQ;

    // Insert elements into the min heap
    minPQ.push(100);
    minPQ.push(200);
    minPQ.push(300);
    minPQ.push(400);
    minPQ.emplace(500);
    minPQ.emplace(600);

    // Extract and print elements in ascending order
    while (!minPQ.empty()) {
        cout << minPQ.top() << " ";
        minPQ.pop();
    }
    cout << endl;

    // Check properties after emptying the min heap
    cout << "Min heap size after removal: " << minPQ.size() << endl;
    cout << "Is min heap empty? " << (minPQ.empty() ? "Yes" : "No") << endl;

    return 0;
}

