#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

// Converts a character from the set {'A'-'Z', '0'-'9'} to an integer in [0, 35]
inline int char_to_index(char ch) {
    if (ch >= 'A' && ch <= 'Z') {
        return ch - 'A';
    }
    return ch - '0' + 26;
}

// Computes a common subsequence by greedily matching characters from string 'x' within string 'y'
// Time complexity: O(|x| + |y|)
std::string greedy_match(const std::string& x, const std::string& y) {
    // Build position lists for each character in 'y'
    // positions[k] holds all indices where the k-th alphabet character appears in 'y'
    std::vector<std::vector<int>> positions(36);
    for (int idx = 0; idx < y.size(); ++idx) {
        positions[char_to_index(y[idx])].push_back(idx);
    }

    std::string result;
    // Pre-allocate space: maximum possible LCS length is min(|x|, |y|)
    result.reserve(std::min(x.size(), y.size()));

    int last_index_y = -1;
    // Pointers tracking current position in each character's list
    std::vector<int> pointers(36, 0);

    for (char ch : x) {
        int char_id = char_to_index(ch);

        // Advance pointer until we find a position > last_index_y or exhaust the list
        while (pointers[char_id] < positions[char_id].size() && 
               positions[char_id][pointers[char_id]] <= last_index_y) {
            pointers[char_id]++;
        }

        // If valid position exists, include character and update state
        if (pointers[char_id] < positions[char_id].size()) {
            result.push_back(ch);
            last_index_y = positions[char_id][pointers[char_id]];
            pointers[char_id]++; // advance for next occurrence
        }
    }
    return result;
}

int main() {
    // Optimize I/O for speed with large inputs
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::string input1, input2;
    std::cin >> input1 >> input2;

    // Generate two candidate subsequences by running greedy in both directions
    std::string candidate1 = greedy_match(input1, input2);
    std::string candidate2 = greedy_match(input2, input1);

    // Output the longer of the two candidates
    if (candidate1.length() >= candidate2.length()) {
        std::cout << candidate1 << '\n';
    } else {
        std::cout << candidate2 << '\n';
    }

    return 0;
}

