namespace NGTest::NInternal {
    namespace {
        void FormatActual(const std::exception& ex, const TBackTrace* trace, TStringBuilder& buffer) {
            buffer << "an exception of type " << TypeName(ex) << " "
                   << "with message " << TString(ex.what()).Quote() << ".";
            if (trace) {
                buffer << "\n   Trace: ";
                for (auto& segment : StringSplitter(trace->PrintToString()).Split('\n')) {
                    buffer << "          " << segment.Token() << "\n";
                }
            }
        }

        void FormatActual(TStringBuilder& buffer) {
            buffer << "  Actual: it throws ";
            auto excPtr = std::current_exception();
            if (excPtr) {
                try {
                    std::rethrow_exception(excPtr);
                } catch (const yexception& ex) {
                    FormatActual(ex, ex.BackTrace(), buffer);
                    return;
                } catch (const std::exception& ex) {
                    FormatActual(ex, nullptr, buffer);
                    return;
                } catch (...) {
                    buffer << "an unknown exception.";
                    return;
                }
            }
            buffer << "nothing.";
        }

        void FormatExpected(const char* expr, const char* kind, const TString& substr, TStringBuilder& buffer) {
            buffer << "Expected: ";
            if (TStringBuf(expr).size() > 80) {
                buffer << "statement";
            } else {
                buffer << expr;
            }
            buffer << " throws an exception of type " << kind;
            if (!substr.empty()) {
                buffer << " with message containing " << substr.Quote();
            }
            buffer << ".";
        }
    }

    TString FormatErrorWrongException(const char* expr, const char* kind) {
        return FormatErrorWrongException(expr, kind, "");
    }

    TString FormatErrorWrongException(const char* expr, const char* kind, TString substr) {
        TStringBuilder buffer;
        FormatExpected(expr, kind, substr, buffer);
        buffer << "\n";
        FormatActual(buffer);
        return buffer;
    }

    TString FormatErrorUnexpectedException(const char* expr) {
        TStringBuilder buffer;
        buffer << "Expected: ";
        if (TStringBuf(expr).size() > 80) {
            buffer << "statement";
        } else {
            buffer << expr;
        }
        buffer << " doesn't throw an exception.\n  ";
        FormatActual(buffer);
        return buffer;
    }

    bool ExceptionMessageContains(const std::exception& ex, TString substr) {
        return TStringBuf(ex.what()).Contains(substr);
    }
}

#include <iostream>
#include <asio.hpp>
#include <boost/bind.hpp>

class timer_printer
{
public:
  timer_printer(asio::io_context& context)
    : work_strand_(context),
      first_timer_(context, asio::chrono::seconds(1)),
      second_timer_(context, asio::chrono::seconds(1)),
      counter_(0)
  {
    first_timer_.async_wait(asio::bind_executor(work_strand_,
          boost::bind(&timer_printer::show_first, this)));
    second_timer_.async_wait(asio::bind_executor(work_strand_,
          boost::bind(&timer_printer::show_second, this)));
  }

  ~timer_printer()
  {
    std::cout << "Final count is " << counter_ << std::endl;
  }

  void show_first()
  {
    if (counter_ < 10)
    {
      std::cout << "Timer 1: " << counter_ << std::endl;
      ++counter_;
      first_timer_.expires_at(first_timer_.expiry() + asio::chrono::seconds(1));
      first_timer_.async_wait(asio::bind_executor(work_strand_,
            boost::bind(&timer_printer::show_first, this)));
    }
  }

  void show_second()
  {
    if (counter_ < 10)
    {
      std::cout << "Timer 2: " << counter_ << std::endl;
      ++counter_;
      second_timer_.expires_at(second_timer_.expiry() + asio::chrono::seconds(1));
      second_timer_.async_wait(asio::bind_executor(work_strand_,
            boost::bind(&timer_printer::show_second, this)));
    }
  }

private:
  asio::io_context::strand work_strand_;
  asio::steady_timer first_timer_;
  asio::steady_timer second_timer_;
  int counter_;
};

int main()
{
  asio::io_context service;
  timer_printer instance(service);
  asio::thread worker_thread(boost::bind(&asio::io_context::run, &service));
  service.run();
  worker_thread.join();
  return 0;
}

