#include <vector>
#include <string>

class Solution {
public:
    void buildParentheses(int openLeft, int closeLeft, std::string current, std::vector<std::string> &results) {
        if (closeLeft == 0) {
            results.push_back(current);
        }
        if (closeLeft > openLeft) {
            buildParentheses(openLeft, closeLeft - 1, current + ')', results);
        }
        if (openLeft > 0) {
            buildParentheses(openLeft - 1, closeLeft, current + '(', results);
        }
    }

    std::vector<std::string> generateParenthesis(int n) {
        int openCount = n;
        int closeCount = n;
        std::string initialString = "";
        std::vector<std::string> combinations;

        buildParentheses(openCount, closeCount, initialString, combinations);
        return combinations;
    }
};

