#include <vector>
using namespace std;

// Leetcode 1352: Product of Last K Numbers (Type II Clone)
class ProductOfNumbers {
private:
    vector<int> prefixProducts;  // Renamed from 'ans' to 'prefixProducts'
public:
    ProductOfNumbers() {
        prefixProducts.push_back(1);  // Initialize with 1 for product calculations
    }

    void add(int value) {  // Renamed parameter 'num' to 'value'
        if (value == 0) {
            prefixProducts.clear();   // Clear on zero to handle division by zero later
            prefixProducts.push_back(1);  // Reset with 1 as neutral element
        } else {
            prefixProducts.push_back(prefixProducts.back() * value);
        }
    }

    int getProduct(int k) {  // Renamed parameter 'k' remains same, but logic slightly reordered
        if (k >= prefixProducts.size()) return 0;
        // Compute product using prefix products: total_product / prefix_before_k_elements
        return prefixProducts.back() / prefixProducts[prefixProducts.size() - k - 1];
    }
};
// Time Complexity:
// - add: O(1)
// - getProduct: O(1) (constant time division)
// Space Complexity: O(n) where n is the number of elements added (due to the vector storing products)
// Note: The vector `prefixProducts` stores the prefix products, enabling efficient retrieval of the product

