// Global variables for graph representation and DSATUR-related data
int vertex_count, edge_count;
std::vector<std::vector<bool>> adjacency_matrix;
std::vector<int> clique_assignment;  // Stores the color (clique ID) for each vertex
std::vector<int> complement_degrees;
std::vector<int> saturation_levels;
std::vector<std::vector<bool>> observed_colors;

// Reads graph data from standard input
void load_graph_data() {
    std::cin >> vertex_count >> edge_count;
    adjacency_matrix.assign(vertex_count + 1, std::vector<bool>(vertex_count + 1, false));

    for (int idx = 0; idx < edge_count; ++idx) {
        int src, dst;
        std::cin >> src >> dst;
        adjacency_matrix[src][dst] = adjacency_matrix[dst][src] = true;
    }
}

// Implements DSATUR algorithm on the complement graph to solve Clique Cover
void compute_clique_cover() {
    // Step 1: Compute degrees in the complement graph
    complement_degrees.assign(vertex_count + 1, 0);
    for (int i = 1; i <= vertex_count; ++i) {
        for (int j = i + 1; j <= vertex_count; ++j) {
            if (!adjacency_matrix[i][j]) {
                complement_degrees[i]++;
                complement_degrees[j]++;
            }
        }
    }

    // Initialize DSATUR structures
    clique_assignment.assign(vertex_count + 1, 0);          // 0 means unassigned
    saturation_levels.assign(vertex_count + 1, 0);
    observed_colors.assign(vertex_count + 1, std::vector<bool>(vertex_count + 2, false));

    // Main DSATUR loop: assign one vertex per iteration
    for (int step = 0; step < vertex_count; ++step) {
        // Select next vertex: highest saturation degree, tie-break by complement degree
        int candidate_vertex = -1;
        for (int v = 1; v <= vertex_count; ++v) {
            if (clique_assignment[v] == 0) {  // Only consider unassigned vertices
                if (candidate_vertex == -1) {
                    candidate_vertex = v;
                } else {
                    if (saturation_levels[v] > saturation_levels[candidate_vertex]) {
                        candidate_vertex = v;
                    } else if (saturation_levels[v] == saturation_levels[candidate_vertex] &&
                               complement_degrees[v] > complement_degrees[candidate_vertex]) {
                        candidate_vertex = v;
                    }
                }
            }
        }

        int selected_vertex = candidate_vertex;

        // Determine smallest available color not used by neighbors in complement graph
        std::vector<bool> neighbor_color_flags(vertex_count + 2, false);
        for (int neighbor = 1; neighbor <= vertex_count; ++neighbor) {
            if (selected_vertex != neighbor && 
                !adjacency_matrix[selected_vertex][neighbor] && 
                clique_assignment[neighbor] != 0) {
                neighbor_color_flags[clique_assignment[neighbor]] = true;
            }
        }

        int chosen_color = 1;
        while (neighbor_color_flags[chosen_color]) {
            ++chosen_color;
        }
        clique_assignment[selected_vertex] = chosen_color;

        // Update saturation levels of unassigned neighbors in complement graph
        for (int neighbor = 1; neighbor <= vertex_count; ++neighbor) {
            if (selected_vertex != neighbor && 
                !adjacency_matrix[selected_vertex][neighbor] && 
                clique_assignment[neighbor] == 0) {
                if (!observed_colors[neighbor][chosen_color]) {
                    observed_colors[neighbor][chosen_color] = true;
                    saturation_levels[neighbor]++;
                }
            }
        }
    }
}

int main() {
    optimize_io();
    load_graph_data();
    compute_clique_cover();

    for (int i = 1; i <= vertex_count; ++i) {
        std::cout << clique_assignment[i] << "\n";
    }

    return 0;
}

