namespace {
template <typename Container>
void runBenchmark(std::string_view label) {
    Container first;
    Container second;
    ankerl::nanobench::Rng randomGen(456);
    ankerl::nanobench::Bench timer;

    for (size_t iteration = 0; iteration < 10000; ++iteration) {
        first[randomGen()];
        second[randomGen()];
    }

    timer.run(fmt::format("exchange {}", label), [&] {
        std::swap(first, second);
    });

    ankerl::nanobench::doNotOptimizeAway(&first);
    ankerl::nanobench::doNotOptimizeAway(&second);
}
} // namespace

