#include <lapack.hh>
#include <vector>

namespace py = pybind11;

/**
 * @brief Compute eigenvalues and eigenvectors for a symmetric dense matrix using LAPACK's syev.
 *
 * @param input_matrix Input square matrix (NumPy array).
 * @return A tuple with the computed eigenvalues and eigenvectors.
 */
py::tuple symmetric_eigensolver(const py::array_t<double>& input_matrix) {
  // Check that input is a 2D array
  if (input_matrix.ndim() != 2) {
    throw std::invalid_argument("Input must be a 2-dimensional array.");
  }

  auto dims = input_matrix.shape();
  if (dims[0] != dims[1]) {
    throw std::invalid_argument("Input matrix must be square.");
  }

  int size = dims[0];

  // Convert NumPy array to Eigen matrix
  Eigen::MatrixXd A = Eigen::Map<const Eigen::MatrixXd>(input_matrix.data(), size, size);
  Eigen::VectorXd eigen_vals(size);

  // Call LAPACK routine to compute eigenvalues and eigenvectors
  int result = lapack::syev(lapack::Job::Vec, lapack::Uplo::Lower, size, A.data(), size, eigen_vals.data());

  if (result != 0) {
    throw std::runtime_error("LAPACK syev computation failed.");
  }

  return py::make_tuple(eigen_vals, A);
}

/**
 * @brief Expose the symmetric eigensolver to Python via pybind11.
 *
 */
void expose_eigensolver(py::module& module) {
  module.def("solve_symmetric_eigen", &symmetric_eigensolver,
        R"(
            Compute eigenvalues and eigenvectors of a real symmetric matrix using LAPACK's syev.

            Parameters
            ----------
            input_matrix : numpy.ndarray
                Real symmetric matrix of shape (n, n).

            Returns
            -------
            tuple of (numpy.ndarray, numpy.ndarray)
                - ``eigenvalues``: 1-D array of length n containing eigenvalues in ascending order
                - ``eigenvectors``: 2-D array of shape (n, n), where column i is the eigenvector corresponding to eigenvalue i

            Raises
            ------
            ValueError
                If the input is not a square matrix.
            RuntimeError
                If the eigenvalue computation does not converge.
        )",
        py::arg("input_matrix"));
}

