	if (!DisplayClusterNetworkDataConversion::BinaryPacketToBinaryEvent(InRequest, InternalEvent))
	{
		UE_LOG(LogDisplayClusterNetwork, Error, TEXT("%s - failed to convert net packet to binary event"), *GetName());
		return typename IDisplayClusterSessionPacketHandler<FDisplayClusterPacketBinary, false>::ReturnType();
	}

	// Re-emit the event internally for cluster-wide replication
	UE_LOG(LogDisplayClusterNetwork, Verbose, TEXT("%s - forwarding cluster event for internal propagation..."), *GetName());
	EmitClusterEventBinary(InternalEvent);

	return typename IDisplayClusterSessionPacketHandler<FDisplayClusterPacketBinary, false>::ReturnType();
}

