using asio::ip::tcp;

class echo_session
  : public std::enable_shared_from_this<echo_session>
{
public:
  echo_session(tcp::socket sock)
    : socket_(std::move(sock))
  {
  }

  void begin()
  {
    perform_read();
  }

private:
  void perform_read()
  {
    auto self(shared_from_this());
    socket_.async_read_some(asio::buffer(buffer_, buffer_size),
        [this, self](std::error_code err, std::size_t bytes_transferred)
        {
          if (!err)
          {
            perform_write(bytes_transferred);
          }
        });
  }

  void perform_write(std::size_t len)
  {
    auto self(shared_from_this());
    asio::async_write(socket_, asio::buffer(buffer_, len),
        [this, self](std::error_code err, std::size_t /*bytes_written*/)
        {
          if (!err)
          {
            perform_read();
          }
        });
  }

  tcp::socket socket_;
  static constexpr std::size_t buffer_size = 1024;
  char buffer_[buffer_size];
};

class echo_server
{
public:
  echo_server(asio::io_context& ctx, unsigned short port_num)
    : acceptor_(ctx, tcp::endpoint(tcp::v4(), port_num)),
      socket_(ctx)
  {
    start_accepting();
  }

private:
  void start_accepting()
  {
    acceptor_.async_accept(socket_,
        [this](std::error_code ec)
        {
          if (!ec)
          {
            std::make_shared<echo_session>(std::move(socket_))->begin();
          }
          start_accepting();
        });
  }

  tcp::acceptor acceptor_;
  tcp::socket socket_;
};

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 2)
    {
      std::cerr << "Usage: async_echo_server <port>\n";
      return 1;
    }

    asio::io_context context;
    echo_server server_instance(context, static_cast<unsigned short>(std::atoi(argv[1])));
    context.run();
  }
  catch (const std::exception& ex)
  {
    std::cerr << "Error occurred: " << ex.what() << "\n";
  }

  return 0;
}

