namespace {
/// NVPTXAssignValidGlobalNames - Assigns valid PTX identifiers to local globals and functions
class NVPTXAssignValidGlobalNames : public ModulePass {
public:
  static char ID;
  NVPTXAssignValidGlobalNames() : ModulePass(ID) {}
  bool runOnModule(Module &M) override;

  /// Sanitize the global name by replacing invalid characters for PTX
  std::string sanitizeName(StringRef originalName);
};
}

char NVPTXAssignValidGlobalNames::ID = 0;

namespace llvm {
void initializeNVPTXAssignValidGlobalNamesPass(PassRegistry &);
}

INITIALIZE_PASS(NVPTXAssignValidGlobalNames, "nvptx-assign-valid-global-names",
                "Assign valid PTX names to globals", false, false)

bool NVPTXAssignValidGlobalNames::runOnModule(Module &M) {
  // Process all global variables with local linkage
  for (GlobalVariable &GV : M.globals()) {
    if (GV.hasLocalLinkage()) {
      GV.setName(sanitizeName(GV.getName()));
    }
  }

  // Process all functions with local linkage
  for (Function &func : M.functions()) {
    if (func.hasLocalLinkage()) {
      func.setName(sanitizeName(func.getName()));
    }
  }

  return true;
}

std::string NVPTXAssignValidGlobalNames::sanitizeName(StringRef originalName) {
  std::string sanitized;
  raw_string_ostream stream(sanitized);

  for (char ch : originalName) {
    if (ch == '.' || ch == '@' || ch == '<' || ch == '>') {
      stream << "_$_";
    } else {
      stream << ch;
    }
  }

  return stream.str();
}

ModulePass *llvm::createNVPTXAssignValidGlobalNamesPass() {
  return new NVPTXAssignValidGlobalNames();
}

#include <iostream>
#include <vector>
#include <string>

// This program constructs a 20x20 grid map for the "Kangaroos" challenge.
// The layout features a "double-sided comb" pattern, forming a tree structure.
// It aims to hinder agents from clustering under random motion by creating
// distinct movement zones: horizontal paths along the spine and vertical paths
// along the teeth. Movement between zones is constrained to intersection points,
// making coordinated gathering unlikely with stochastic inputs. Dead-ends further
// limit agent mobility and prevent easy convergence.
void generateMap() {
    int rows = 20;
    int cols = 20;
    std::cout << rows << " " << cols << std::endl;
    std::vector<std::string> grid(rows, std::string(cols, '0'));

    // Position the central horizontal spine on row index 9 for a 20-row grid
    int spine_row = rows / 2 - 1;
    for (int col = 0; col < cols; ++col) {
        grid[spine_row][col] = '1';
    }

    // Add vertical teeth at even column indices to avoid adjacency and preserve tree properties
    for (int col = 0; col < cols; ++col) {
        if (col % 2 == 0) {
            // Extend upper teeth from top edge down to the spine
            for (int row = 0; row < spine_row; ++row) {
                grid[row][col] = '1';
            }
            // Extend lower teeth from below the spine to bottom edge
            for (int row = spine_row + 1; row < rows; ++row) {
                grid[row][col] = '1';
            }
        }
    }

    // Output the final grid configuration
    for (int row = 0; row < rows; ++row) {
        std::cout << grid[row] << std::endl;
    }
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);
    generateMap();
    return 0;
}

