#include <fstream>
#include <vector>
#include <string>
#include <stdexcept>

std::vector<std::string> read2BitFile(const std::string& fileName) {
    std::ifstream file(fileName, std::ios::binary);
    if (!file) {
        throw std::runtime_error("Failed to open file: " + fileName);
    }

    // Read number of sequences
    int seqCount;
    file.read(reinterpret_cast<char*>(&seqCount), sizeof(seqCount));

    std::vector<std::string> names;
    names.reserve(seqCount);

    // Read sequence names
    for (int i = 0; i < seqCount; ++i) {
        int nameLen;
        file.read(reinterpret_cast<char*>(&nameLen), sizeof(nameLen));
        std::string name(nameLen, '\0');
        file.read(&name[0], nameLen);
        names.push_back(std::move(name));
    }

    std::vector<std::string> decodedSeqs;
    decodedSeqs.reserve(seqCount);

    // Decode each sequence
    for (const auto& name : names) {
        int seqLen;
        file.read(reinterpret_cast<char*>(&seqLen), sizeof(seqLen));

        std::string encoded(seqLen, '\0');
        file.read(&encoded[0], seqLen);

        // Decode using bit manipulation instead of bitset
        std::string decoded;
        decoded.reserve(seqLen * 2); // Each byte represents 2 bases

        for (unsigned char byte : encoded) {
            // Extract two 2-bit groups from the byte
            unsigned char base1 = (byte >> 6) & 0x03;
            unsigned char base2 = byte & 0x03;

            // Map to nucleotides using lookup
            const char* nucleotides = "ACGT";
            decoded += nucleotides[base1];
            decoded += nucleotides[base2];
        }

        decodedSeqs.push_back(std::move(decoded));
    }

    return decodedSeqs;
}

#include <iostream>
#include <string>
#include <unordered_set>

// Template class representing a hierarchical path structure
template <typename PathRegistry>
class FilePath {
public:
    FilePath() = default;

    // Constructor creates a child path under a parent with given name
    FilePath(const FilePath& ancestor, const std::string& segment) 
        : ancestor_(&ancestor), segment_(segment) {}

    // Check if this path segment is unique among siblings
    bool isDistinct() const {
        if (ancestor_ == nullptr) {
            return true;  // Root node has no siblings, thus distinct
        }
        const auto& registry = ancestor_->getRegistry();
        return registry.find(segment_) == registry.end();
    }

    // Print the full path from root to current node
    void display() const {
        if (ancestor_ != nullptr) {
            ancestor_->display();
            std::cout << "/" << segment_;
        } else {
            std::cout << "/" << segment_;
        }
    }

private:
    const FilePath* ancestor_ = nullptr;
    std::string segment_;

    // Access the registry of sibling paths
    const PathRegistry& getRegistry() const {
        return PathRegistry::access();
    }
};

// Registry template managing shared state for path uniqueness
template <typename T>
class SharedPathRegistry {
public:
    static const SharedPathRegistry& access() {
        static SharedPathRegistry singleton;
        return singleton;
    }

    std::unordered_set<std::string> registeredPaths;

private:
    SharedPathRegistry() = default;
};

int main() {
    using FilePath = FilePath<SharedPathRegistry<std::string>>;

    // Create path hierarchy
    FilePath base;
    FilePath leaf1 { base, "folderA" };
    FilePath leaf2 { base, "folderB" };
    FilePath duplicate { base, "folderA" };  // Same name as leaf1
    FilePath nested { leaf2, "subfolder" };

    // Display paths
    leaf1.display();   // Output: /folderA
    std::cout << std::endl;

    leaf2.display();   // Output: /folderB
    std::cout << std::endl;

    duplicate.display(); // Output: /folderA
    std::cout << std::endl;

    nested.display();  // Output: /folderB/subfolder
    std::cout << std::endl;

    // Report uniqueness status
    std::cout << "leaf1 distinct: " << (leaf1.isDistinct() ? "true" : "false") << std::endl;   // true
    std::cout << "leaf2 distinct: " << (leaf2.isDistinct() ? "true" : "false") << std::endl;   // true
    std::cout << "duplicate distinct: " << (duplicate.isDistinct() ? "true" : "false") << std::endl; // false
    std::cout << "nested distinct: " << (nested.isDistinct() ? "true" : "false") << std::endl;  // true

    return 0;
}

#include <mcpputil/mcpputil/pointer_utils.hpp>
#include <unordered_set>
#include <iostream>

// Custom memory tracking allocator that monitors allocations and deallocations
class MemoryTracker {
public:
    void* requestMemory(size_t bytes) {
        void* addr = mcpputil::pointer_utils::allocate(bytes);
        tracked_blocks.insert(addr);
        cumulative_usage += bytes;
        return addr;
    }

    void releaseMemory(void* addr, size_t bytes) {
        auto iter = tracked_blocks.find(addr);
        if (iter != tracked_blocks.end()) {
            mcpputil::pointer_utils::deallocate(addr, bytes);
            tracked_blocks.erase(iter);
            cumulative_usage -= bytes;
        }
    }

    ~MemoryTracker() {
        for (void* block : tracked_blocks) {
            std::cerr << "Unreleased memory block at: " << block << std::endl;
            // Note: In real usage, you'd need to track sizes per allocation
            mcpputil::pointer_utils::deallocate(block, /* unknown size */ 0);
        }
    }

    size_t currentUsage() const {
        return cumulative_usage;
    }

private:
    std::unordered_set<void*> tracked_blocks;
    size_t cumulative_usage = 0;
};

int main() {
    MemoryTracker tracker;

    // Acquire memory blocks
    void* blockA = tracker.requestMemory(100);
    void* blockB = tracker.requestMemory(200);

    // Release first block intentionally
    tracker.releaseMemory(blockA, 100);

    // Second block remains allocated to simulate a leak scenario

    // Report current memory usage
    std::cout << "Current memory usage: " << tracker.currentUsage() << " bytes" << std::endl;

    // Destructor will report remaining leaked memory
    return 0;
}

