// Abstract command interface
class Command {
public:
    virtual ~Command() = default;
    virtual void perform() = 0;
    virtual void revert() = 0;
    virtual void reapply() = 0;
};

// Concrete implementation for full selection operation
class FullSelectionCommand : public Command {
private:
    std::vector<Item> currentItems;       // Holds the items involved in the operation
    std::vector<Item> priorState;         // Stores the state before the last change

public:
    explicit FullSelectionCommand(const std::vector<Item>& items) 
        : currentItems(items) {}

    void perform() override {
        // Capture previous state before modifying
        priorState = currentItems;
        // Replace with complete set of available items
        currentItems = fetchAllItems();
        std::cout << "Complete selection applied" << std::endl;
    }

    void revert() override {
        // Restore to previously saved state
        currentItems = priorState;
        std::cout << "Selection reverted" << std::endl;
    }

    void reapply() override {
        // Re-execute the original action
        perform();
    }

private:
    std::vector<Item> fetchAllItems() {
        // Retrieve all possible items from the application context
        // Implementation details omitted
        return std::vector<Item>();
    }
};

