#include <iostream>
#include <string>
#include <cctype>

// Count how many times a word appears in a text (case-insensitive)
int countWordOccurrences(const std::string& text, const std::string& word) {
    // Create lowercase versions of both strings for comparison
    std::string lowerText = text;
    std::string lowerWord = word;

    // Convert each character to lowercase manually
    for (size_t i = 0; i < lowerText.length(); ++i) {
        lowerText[i] = std::tolower(static_cast<unsigned char>(lowerText[i]));
    }
    for (size_t i = 0; i < lowerWord.length(); ++i) {
        lowerWord[i] = std::tolower(static_cast<unsigned char>(lowerWord[i]));
    }

    int occurrences = 0;
    size_t index = 0;

    // Search for the word repeatedly in the text
    while ((index = lowerText.find(lowerWord, index)) != std::string::npos) {
        occurrences++;
        index += lowerWord.length();
    }

    return occurrences;
}

int main() {
    std::string passage = "This is a sample text. This text contains the word 'this' multiple times. This is a simple example.";
    std::string target = "this";

    int result = countWordOccurrences(passage, target);
    std::cout << "Number of occurrences of the word '" << target << "': " << result << std::endl;

    return 0;
