// Perform Caesar cipher decryption (shift backward by key)
char applyCaesarShift(char ch, int shiftAmount) {
    if (!std::isalpha(ch)) {
        return ch;
    }

    char base = std::islower(ch) ? 'a' : 'A';
    // Shift backward by 'shiftAmount' positions with wrap-around
    int offset = (ch - base - shiftAmount + 26) % 26;
    return static_cast<char>(base + offset);
}

int main() {
    std::string message;
    int shiftValue;

    std::cout << "Enter a line of text:\n";
    std::getline(std::cin, message);

    std::cout << "Enter an integer to shift the text (1-25):\n";
    std::cin >> shiftValue;

    // Validate input range for shift value
    while (shiftValue < 1 || shiftValue > 25) {
        std::cout << "Invalid shift value. Please enter an integer between 1 and 25:\n";
        std::cin >> shiftValue;
    }

    std::string result;
    for (size_t i = 0; i < message.length(); ++i) {
        result += applyCaesarShift(message[i], shiftValue);
    }

    std::cout << "Encrypted text: " << result << std::endl;
    return 0;
}

