// Using a distinct type alias for class identifiers
using class_identifier = int;

class inheritance_graph {
public:
    inheritance_graph();
    ~inheritance_graph();

    // Perform a safe downcast between types
    std::pair<void*, bool> perform_cast(
        void* obj_ptr, 
        class_identifier source_type_id, 
        class_identifier target_type_id, 
        class_identifier actual_type_id, 
        void const* actual_object_ptr) const;
};

std::pair<void*, bool> inheritance_graph::perform_cast(
    void* obj_ptr, 
    class_identifier source_type_id, 
    class_identifier target_type_id, 
    class_identifier actual_type_id, 
    void const* actual_object_ptr) const {

    // Check if the dynamic type matches the source type
    if (actual_type_id == source_type_id) {
        // Attempt to cast the pointer to void*
        void* converted_ptr = dynamic_cast<void*>(obj_ptr);

        // Verify the cast succeeded and target type matches
        if (converted_ptr != nullptr && actual_type_id == target_type_id) {
            return std::make_pair(converted_ptr, true);  // Cast successful
        }
    }

    // Return failure result
    return std::make_pair(nullptr, false);  // Cast unsuccessful
}

