// Function to compute molecular mass of a compound
double ComputeMolecularMass(std::istream& input) {
  // Map containing atomic masses for common elements
  std::map<std::string, double> elementMasses = {
    {"H", 1.008}, {"C", 12.011}, {"O", 15.999}, {"N", 14.007}
    // Additional elements can be added here
  };

  double cumulativeMass = 0.0;
  char currentElement;
  int quantity;

  // Parse the chemical formula from the input stream
  while (input >> currentElement >> quantity) {
    std::string symbol(1, currentElement);

    auto it = elementMasses.find(symbol);
    if (it != elementMasses.end()) {
      cumulativeMass += it->second * quantity;
    } else {
      std::cerr << "Error: Unknown element " << symbol << std::endl;
      return -1.0;  // Indicates an error due to unknown element
    }
  }

  return cumulativeMass;
}

int main() {
  // Demonstration usage
  std::string formula = "H2O";
  std::istringstream inputStream(formula);
  double result = ComputeMolecularMass(inputStream);
  std::cout << "Molecular weight of " << formula << " is " << result << std::endl;
  return 0;
}

