#include <vector>
#include <unordered_set>

bool canFormTreePair(std::vector<int> treePositions, int targetDistance) {
    std::unordered_set<int> seen;

    for (int pos : treePositions) {
        // Check if there exists a position such that current_pos - previous_pos = targetDistance
        // or current_pos - previous_pos = -targetDistance (which means previous_pos - current_pos = targetDistance)
        if (seen.find(pos - targetDistance) != seen.end() || 
            seen.find(pos + targetDistance) != seen.end()) {
            return true;
        }
        seen.insert(pos);
    }

    return false;
}

