class RandomNumberGenerator {
private:
    mt19937 engine;  // Mersenne Twister pseudo-random generator
    uniform_int_distribution<int> rangeDist;
public:
    RandomNumberGenerator(int lowerBound, int upperBound) 
        : engine(system_clock::now().time_since_epoch().count()), 
          rangeDist(lowerBound, upperBound) {}

    int produce() {
        return rangeDist(engine);
    }

    void adjustBounds(int newLower, int newUpper) {
        rangeDist = uniform_int_distribution<int>(newLower, newUpper);
    }
};

int main() {
