    for (int count = 0; count < 10; ++count) {
        cout << randGen.produce() << " ";  // Generate and print 10 random numbers within the specified range
    }
    cout << endl;

    randGen.adjustBounds(50, 150);  // Change the range to [50, 150]

    for (int count = 0; count < 10; ++count) {
        cout << randGen.produce() << " ";  // Generate and print 10 random numbers within the new range
