namespace Rider {
    namespace Faiz {
        // Alternative implementation of disjunction using parameter pack expansion
        namespace detail {
            template <bool... Values>
            struct disjunction_helper : std::false_type {};

            template <bool First, bool... Rest>
            struct disjunction_helper<First, Rest...> 
                : std::integral_constant<bool, First || disjunction_helper<Rest...>::value> {};
        }

        // Main disjunction meta-function that works with type traits
        template <typename... Ts>
        struct disjunction : detail::disjunction_helper<Ts::value...> {};

        // Macro for compile-time assertions
        #define VERIFY_STATIC(expr) static_assert(expr, "Compile-time verification failed")

        // Type aliases for testing
        using flag_true = std::true_type;
        using flag_false = std::false_type;

        // Verification tests for the disjunction implementation
        VERIFY_STATIC(disjunction<flag_true, flag_false>::value);
        VERIFY_STATIC(disjunction<flag_false, flag_true, flag_false>::value);
        VERIFY_STATIC(!disjunction<flag_false, flag_false, flag_false>::value);
    }
