#include <vector>
#include <algorithm>

// Helper function to find all unique combinations that sum to target
void exploreCombinations(std::vector<std::vector<int>>& results, 
                        std::vector<int>& currentPath, 
                        const std::vector<int>& sortedNums, 
                        int remainingSum, 
                        int index) {
    // Base case: if remaining sum is negative, no valid combination
    if (remainingSum < 0) {
        return;
    }

    // Base case: if remaining sum is zero, found a valid combination
    if (remainingSum == 0) {
        results.push_back(currentPath);
        return;
    }

    // Try each candidate starting from current index
    for (int pos = index; pos < sortedNums.size(); ++pos) {
        // Skip duplicates to avoid repeated combinations
        if (pos > index && sortedNums[pos] == sortedNums[pos - 1]) {
            continue;
        }

        // Include current number in combination
        currentPath.push_back(sortedNums[pos]);

        // Recursively search with updated parameters
        exploreCombinations(results, currentPath, sortedNums, 
                          remainingSum - sortedNums[pos], pos + 1);

        // Backtrack: remove last added number
        currentPath.pop_back();
    }
}

// Main function to find combinations that sum to target
std::vector<std::vector<int>> findUniqueCombinations(std::vector<int> nums, int target) {
    // Sort numbers to handle duplicates properly
    std::sort(nums.begin(), nums.end());

    std::vector<std::vector<int>> allSolutions;
    std::vector<int> currentCombination;

    // Start recursive exploration
    exploreCombinations(allSolutions, currentCombination, nums, target, 0);

    return allSolutions;
}

