    enum class EBayerCode {
        BG, // GigE Vision Bayer code
        GB, // GigE Vision Bayer code
        RG, // GigE Vision Bayer code
        GR  // GigE Vision Bayer code
    };

    int bayerCodeGray(EBayerCode code) {
        switch (code) {
            // OpenCV uses a different indexing than GigE Vision
            // Adjust mapping accordingly
            case EBayerCode::BG: return CV_BAYER_RG2GRAY; // Maps to OpenCV's BG -> RG pattern
            case EBayerCode::GB: return CV_BAYER_GR2GRAY; // Maps to OpenCV's GB -> GR pattern
            case EBayerCode::RG: return CV_BAYER_BG2GRAY; // Maps to OpenCV's RG -> BG pattern
            case EBayerCode::GR: return CV_BAYER_GB2GRAY; // Maps to OpenCV's GR -> GB pattern
