using namespace std;

class WordCounter {
private:
    map<string, int> wordCounts;

    string normalize(const string& input) {
        string result;
        for (char c : input) {
            if (!ispunct(static_cast<unsigned char>(c))) {
                result += static_cast<char>(tolower(static_cast<unsigned char>(c)));
            }
        }
        return result;
    }

public:
    WordCounter(const string& filename) {
        ifstream inputFile(filename);
        if (inputFile.is_open()) {
            string token;
            while (inputFile >> token) {
                string cleaned = normalize(token);
                if (!cleaned.empty()) {
                    wordCounts[cleaned]++;
                }
            }
            inputFile.close();
        } else {
            cerr << "Error: Cannot open file " << filename << endl;
        }
    }

    int count(const string& target) const {
        string normalizedTarget = normalize(target);
        auto it = wordCounts.find(normalizedTarget);
        if (it != wordCounts.end()) {
            return it->second;
        }
        return 0;
    }
};

int main() {
    WordCounter wc("input.txt");
    cout << "Occurrences of 'the': " << wc.count("the") << endl;
    cout << "Occurrences of 'fox': " << wc.count("fox") << endl;
    return 0;
}

