// Custom namespace for mathematical utilities
namespace math_utils {
    // Computes the factorial of a non-negative integer using iterative approach
    int compute_factorial(int value) {
        if (value <= 1) {
            return 1;
        }

        int accumulator = 1;
        int counter = 2;
        while (counter <= value) {
            accumulator *= counter;
            ++counter;
        }
        return accumulator;
    }
}

// Main function demonstrating usage of the custom namespace and computation
int main() {
    using namespace math_utils;  // Import the custom namespace

    int input_number;
    std::cout << "Enter a number to calculate its factorial: ";
    std::cin >> input_number;

    int result = compute_factorial(input_number);  // Invoke the factorial function from custom namespace
    std::cout << "Factorial of " << input_number << " is: " << result << std::endl;

    return 0;
}

