#include <vector>

void ParticleEmitter::updateParticles(float deltaTime)
{
    // Process each particle using index-based loop
    for (size_t i = 0; i < particles.size(); )
    {
        // Update particle position using velocity and time step
        particles[i].positionX += particles[i].velocityX * deltaTime;
        particles[i].positionY += particles[i].velocityY * deltaTime;

        // Decrease particle's remaining life
        particles[i].remainingLife -= deltaTime;

        // Check if particle has expired
        if (particles[i].remainingLife <= 0.0f)
        {
            // Remove expired particle by swapping with last element and popping
            particles[i] = std::move(particles.back());
            particles.pop_back();
        }
        else
        {
            // Move to next particle only if current wasn't removed
            ++i;
        }
    }
}

