// Compute the median value of a vector of integers
double findMedian(std::vector<int>& nums) {
    // Sort the vector in ascending order using std::sort
    std::sort(nums.begin(), nums.end());

    size_t count = nums.size();

    // Handle even and odd cases separately
    if (count % 2 == 0) {
        // For even-sized vectors, average the two central elements
        int mid1 = nums[count / 2 - 1];
        int mid2 = nums[count / 2];
        return (static_cast<double>(mid1) + static_cast<double>(mid2)) / 2.0;
    } else {
        // For odd-sized vectors, return the middle element directly
        return static_cast<double>(nums[count / 2]);
    }
}

