    processing_queue.emplace(src_x, src_y);

    // Mark starting position as water-filled
    water_grid[src_x][src_y] = Filled;

    // Define movement offsets for 4-directional spread
    const std::vector<std::pair<int, int>> moves = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    // Process all reachable tiles
    while (!processing_queue.empty()) {
        const auto [cur_x, cur_y] = processing_queue.front();
        processing_queue.pop();

        // Examine each adjacent tile
        for (const auto& offset : moves) {
            const int adj_x = cur_x + offset.first;
            const int adj_y = cur_y + offset.second;

            // Verify adjacency is within bounds and not already filled
            if (adj_x >= 0 && adj_x < static_cast<int>(grid.size()) &&
                adj_y >= 0 && adj_y < static_cast<int>(grid[0].size()) &&
                water_grid[adj_x][adj_y] != Filled) {

