// Custom type trait to strip variadic arguments from member function pointers
template <typename T>
struct strip_variadic_args;

// Specialization for non-static const volatile member functions with variadic parameters
template <typename Result, typename ClassType, typename... Args>
struct strip_variadic_args<Result(ClassType::*)(Args..., ...) const volatile> {
    using type = Result(ClassType::*)(Args...);
};

// Compile-time assertion helper macro
#define COMPILE_TIME_CHECK(condition) static_assert(condition, #condition)

int main() {
    // Define various member function pointer types with different cv-qualifiers and ref-qualifiers
    using va_f   = void(BOOST_CLBL_TRTS_DEFAULT_VARARGS_CC foo::*)(int&, int&&...) const;
    using va_l   = void(BOOST_CLBL_TRTS_DEFAULT_VARARGS_CC foo::*)(int&, int&&...) &;
    using va_r   = void(BOOST_CLBL_TRTS_DEFAULT_VARARGS_CC foo::*)(int&, int&&...) &&;
    using va_c   = void(BOOST_CLBL_TRTS_DEFAULT_VARARGS_CC foo::*)(int&, int&&...) const;
    using va_cl  = void(BOOST_CLBL_TRTS_DEFAULT_VARARGS_CC foo::*)(int&, int&&...) const &;
    using va_cr  = void(BOOST_CLBL_TRTS_DEFAULT_VARARGS_CC foo::*)(int&, int&&...) const &&;

    // Verify that stripping variadic args yields expected signatures
    COMPILE_TIME_CHECK(std::is_same<va_f, typename strip_variadic_args<va_f>::type>::value);
    COMPILE_TIME_CHECK(std::is_same<va_l, typename strip_variadic_args<va_l>::type>::value);
    COMPILE_TIME_CHECK(std::is_same<va_r, typename strip_variadic_args<va_r>::type>::value);
    COMPILE_TIME_CHECK(std::is_same<va_c, typename strip_variadic_args<va_c>::type>::value);
    COMPILE_TIME_CHECK(std::is_same<va_cl, typename strip_variadic_args<va_cl>::type>::value);
