};

// Define a simple color class
class Color {
public:
    int red, green, blue;
    Color(int r, int g, int b) : red(r), green(g), blue(b) {}
};

// Define an abstract base class for animators
class AnimationController {
public:
    virtual void advance() = 0;
};

// Define a position animator class
class PositionController : public AnimationController {
private:
    Vector2D currentPos;
public:
    PositionController(float startX, float startY) : currentPos(startX, startY) {}

    void advance() override {
        // Simulate movement by incrementing coordinates
        currentPos.x += 1.0f;
        currentPos.y += 0.5f;
    }

    Vector2D getPosition() const {
        return currentPos;
    }
};

// Define a color animator class
class ColorController : public AnimationController {
private:
    Color currentTone;
public:
    ColorController(int r, int g, int b) : currentTone(r, g, b) {}

    void advance() override {
        // Cycle through RGB values with different increments
        currentTone.red   = (currentTone.red   + 1) % 256;
        currentTone.green = (currentTone.green + 2) % 256;
        currentTone.blue  = (currentTone.blue  + 3) % 256;
    }

    Color getTone() const {
        return currentTone;
    }
};

int main() {
    // Initialize animation controllers
    PositionController posCtrl(100.0f, 100.0f);
    ColorController colCtrl(255, 0, 0);

    // Run animation loop
    int frameCount = 0;
    while (frameCount < 10) {
        posCtrl.advance();
        colCtrl.advance();

        // Get updated state
        Vector2D pos = posCtrl.getPosition();
        Color tone = colCtrl.getTone();

        // Output rendering command
        std::cout << "Drawing circle at (" << pos.x << ", " << pos.y 
                  << ") with color (" << tone.red << ", " 
                  << tone.green << ", " << tone.blue << ")" << std::endl;

        frameCount++;
    }

    return 0;
