class FenceController {
public:
    void AddFence(int id) {
        std::unique_lock<std::mutex> guard(_lock);
        _ids.push_back(id);
        _status.push_back(false);
    }

    void SetFence(int id) {
        std::unique_lock<std::mutex> guard(_lock);
        auto iter = std::find(_ids.begin(), _ids.end(), id);
        if (iter != _ids.end()) {
            size_t pos = std::distance(_ids.begin(), iter);
            _status[pos] = true;
            _cond.notify_all();
        }
    }

    void AwaitFence(int id) {
        std::unique_lock<std::mutex> guard(_lock);
        auto iter = std::find(_ids.begin(), _ids.end(), id);
        if (iter != _ids.end()) {
            size_t idx = std::distance(_ids.begin(), iter);
            _cond.wait(guard, [this, idx]() { return _status[idx]; });
        }
    }

private:
    std::vector<int> _ids;
    std::vector<bool> _status;
    mutable std::mutex _lock;
    std::condition_variable _cond;
};

int main() {
    FenceController controller;

    // Register fences
    controller.AddFence(1);
    controller.AddFence(2);
    controller.AddFence(3);

    // Signal each fence from separate threads
    std::thread worker1([&controller] { controller.SetFence(1); });
    std::thread worker2([&controller] { controller.SetFence(2); });
    std::thread worker3([&controller] { controller.SetFence(3); });

    worker1.join();
    worker2.join();
    worker3.join();

    // Wait for all fences to be set
    controller.AwaitFence(1);
    controller.AwaitFence(2);
    controller.AwaitFence(3);

    std::cout << "All fences have been signaled." << std::endl;
    return 0;
}

