// Compute the Total Ion Current (TIC) by summing all intensity values in the chromatogram
double computeTotalIonCurrent(const OpenMS::MSChromatogram& chromatogram) {
    double tic = 0.0;
    const auto& floatArrays = chromatogram.getFloatDataArrays();

    for (size_t i = 0; i < floatArrays.size(); ++i) {
        const auto& currentArray = floatArrays[i];
        for (size_t j = 0; j < currentArray.size(); ++j) {
            tic += currentArray[j];
        }
    }

    return tic;
}

