// Fisher-Yates shuffle implementation using a different RNG setup
template <typename T>
void fisherYatesShuffle(std::vector<T>& arr) {
    // Use a fixed seed for reproducibility in testing, or keep random_device
    std::random_device rd;
    std::mt19937_64 engine(rd());

    // Start from the last element and move backwards
    for (size_t idx = arr.size(); idx > 1; --idx) {
        // Generate random index in [0, idx-1]
        std::uniform_int_distribution<size_t> dist(0, idx - 1);
        size_t swapIdx = dist(engine);

        // Swap elements at positions idx-1 and swapIdx
        std::swap(arr[idx - 1], arr[swapIdx]);
    }
}

int main() {
    std::vector<int> data = {1, 2, 3, 4, 5};
    fisherYatesShuffle(data);

    for (const auto& value : data) {
        std::cout << value << " ";
    }
    std::cout << std::endl;

    return 0;
}

