// Enum to represent different logging levels
enum class SeverityLevel { 
    INFORMATION, 
    WARN, 
    SEVERE, 
    TRACE 
};

// Custom logger class for handling messages and assertions
class LogHandler {
public:
    // Log an informational message
    void info(const std::string& msg) {
        record(SeverityLevel::INFORMATION, msg);
    }

    // Log a warning message
    void warn(const std::string& msg) {
        record(SeverityLevel::WARN, msg);
    }

    // Log an error message
    void err(const std::string& msg) {
        record(SeverityLevel::SEVERE, msg);
    }

    // Log a debug/trace message
    void trace(const std::string& msg) {
        record(SeverityLevel::TRACE, msg);
    }

    // Check condition and log error if false
    void verify(bool check, const std::string& desc) {
        if (!check) {
            err("Verification failed: " + desc);
            haltExecution();
        }
    }

    // Redirect output stream
    void setOutput(std::ostream& stream) {
        targetStream = &stream;
    }

private:
    std::ostream* targetStream = &std::cout;

    // Internal method to format and write log messages
    void record(SeverityLevel level, const std::string& message) {
        std::string tag;
        switch (level) {
            case SeverityLevel::INFORMATION:
                tag = "INFO";
                break;
            case SeverityLevel::WARN:
                tag = "WARNING";
                break;
            case SeverityLevel::SEVERE:
                tag = "ERROR";
                break;
            case SeverityLevel::TRACE:
                tag = "DEBUG";
                break;
        }
        (*targetStream) << "[" << tag << "] " << message << '\n';
    }

    // Terminate program with exception
    void haltExecution() {
        throw std::runtime_error("Execution stopped due to failed assertion");
    }
};

int main() {
    LogHandler handler;
    handler.err("An error occurred");
    handler.trace("Debugging information");
    handler.setOutput(std::cerr);
    handler.warn("This is a warning");
    handler.verify(2 + 2 == 5, "Math is broken");
    handler.info("This message should not be logged");
    return 0;
}

