#include <utility>

std::pair<std::string, std::string> processText(const std::vector<std::pair<int, std::string>>& commands) {
  std::string target_text, search_text;
  auto iter = commands.begin();

  while (iter != commands.end()) {
    int action_code = (*iter).first;
    const std::string& text_content = (*iter).second;

    if (action_code == 1) {
      if (!target_text.empty()) {
        target_text.append(" ");
      }
      target_text.append(text_content);
    } else if (action_code == 2) {
      if (!search_text.empty()) {
        search_text.append(" ");
      }
      search_text.append(text_content);
    } else if (action_code == 3) {
      target_text.erase();
    } else if (action_code == 4) {
      search_text.erase();
    }

    ++iter;
  }

  return std::make_pair(target_text, search_text);
}

