class FunctionRegistry {
private:
    std::unordered_map<std::string, std::function<void()>> registryMap;
public:
    void addFunction(const std::string& funcName, const std::function<void()>& funcPtr) {
        if (registryMap.count(funcName) > 0) {
            throw std::invalid_argument("A function named '" + funcName + "' is already registered");
        }
        registryMap[funcName] = funcPtr;
    }

    template<typename... Args>
    void callFunction(const std::string& funcName, Args&&... params) {
        auto it = registryMap.find(funcName);
        if (it == registryMap.end()) {
            throw std::invalid_argument("No function named '" + funcName + "' found in registry");
        }
        it->second(std::forward<Args>(params)...);
    }
};

