class FileChangeNotifier {
private:
    bool m_bActive;
    FileWatcher* m_pFileWatcher;
    float m_fTimeUntilNextAllowedRecompile;
    float m_fFileChangeSpamTimeRemaining;

public:
    FileChangeNotifier(bool active, FileWatcher* fileWatcher, float timeUntilNextAllowedRecompile, float fileChangeSpamTimeRemaining)
        : m_bActive(active), m_pFileWatcher(fileWatcher), 
          m_fTimeUntilNextAllowedRecompile(timeUntilNextAllowedRecompile), 
          m_fFileChangeSpamTimeRemaining(fileChangeSpamTimeRemaining) {}

    void Update(float deltaTime) {
        if (m_bActive) {
            m_pFileWatcher->update();

            // Decrement timers, ensuring they don't go below zero
            if (m_fTimeUntilNextAllowedRecompile > 0.0f) {
                m_fTimeUntilNextAllowedRecompile -= deltaTime;
                if (m_fTimeUntilNextAllowedRecompile < 0.0f) {
                    m_fTimeUntilNextAllowedRecompile = 0.0f;
                }
            }

            if (m_fFileChangeSpamTimeRemaining > 0.0f) {
                m_fFileChangeSpamTimeRemaining -= deltaTime;
                if (m_fFileChangeSpamTimeRemaining < 0.0f) {
                    m_fFileChangeSpamTimeRemaining = 0.0f;
                }
            }
        }
    }
};

