// Function to add a demand branch with performance curve validation
void addDemandBranch(model::Model& model, model::PlantLoop& plantLoop, model::CurveBiquadratic& demandCurve) {
    // Construct a demand component associated with the given model
    model::DemandComponent createdComponent(model);
    // Assign the biquadratic performance characteristic to the component
    createdComponent.setPerformanceCurve(demandCurve);

    // Integrate the newly formed component into the plant loop's demand side
    plantLoop.addDemandComponent(createdComponent);

    // Confirm integration by checking all existing demand components on the loop
    std::vector<model::DemandComponent> availableComponents = plantLoop.demandComponents();
    bool found = false;

    for (const auto& item : availableComponents) {
        if (item == createdComponent) {
            found = true;
            break;
        }
    }

    // Ensure the component was successfully registered
    if (!found) {
        throw std::runtime_error("Failed to add demand component to plant loop");
    }
}

