// Function to verify JSON structure integrity by re-parsing serialized data
bool checkJsonIntegrity(const Json::Value& root) {
    // Serialize the JSON value to string
    Json::StreamWriterBuilder builder;
    std::string jsonText = Json::writeString(builder, root);

    // Prepare for parsing back
    Json::CharReaderBuilder charReaderBuilder;
    std::istringstream inputStream(jsonText);
    Json::Value verifiedRoot;
    std::string errorMsg;

    // Attempt to parse the serialized string
    bool parseOk = Json::parseFromStream(charReaderBuilder, inputStream, &verifiedRoot, &errorMsg);

    if (parseOk) {
        return true;  // Parsing succeeded, JSON is structurally valid
    } else {
        std::cerr << "JSON validation failed: " << errorMsg << std::endl;
        return false; // Parsing failed, JSON is invalid
    }
}

