#include <type_traits>

enum class CachePolicy : bool { 
    needs_caching = true, 
    no_caching = false 
};

template <typename ResultType, bool IsConstCorrect, CachePolicy Policy, typename Callable>
struct TaskWrapper {
public:
    ResultType run() {
        return stored_callable_();
    }
private:
    Callable stored_callable_;
};

template <typename Callable>
constexpr auto build_TaskWrapper() {
    using Result = std::invoke_result_t<Callable>;
    return TaskWrapper<Result, true, CachePolicy::no_caching, Callable>();
}

template <typename T, 
          std::enable_if_t<std::is_class_v<T>, T&> value_ref, 
          typename Callable>
constexpr auto build_TaskWrapper(Callable&& callable) {
    constexpr bool is_const_type = std::is_const_v<T>;
    return TaskWrapper<T, is_const_type, CachePolicy::no_caching, Callable>(
        std::forward<Callable>(callable)
    );
}

