    }

    // Verify conversion of 5 miles
    SECTION("5 miles to kilometers")
    {
        REQUIRE(mileToKilometer(5.0) == Approx(8.04672).epsilon(1e-9));
    }

    // Verify conversion of 10 miles
    SECTION("10 miles to kilometers")
    {
        REQUIRE(mileToKilometer(10.0) == Approx(16.09344).epsilon(1e-9));
    }
}

