// Check if a string represents a valid single character literal
bool isValidCharLiteral(const std::string& text) {
    // Must be exactly 3 characters: quote, char, quote
    if (text.length() != 3) {
        return false;
    }

    // Verify opening and closing quotes
    if (text.front() != '\'' || text.back() != '\'') {
        return false;
    }

    // Extract the character between quotes
    char innerChar = text[1];

    // Check for printable ASCII range excluding single quote
    if (innerChar >= 32 && innerChar <= 126 && innerChar != '\'') {
        return true;
    }

    return false;
}

int main() {
    std::cout << std::boolalpha;

    // Test cases
    std::cout << isValidCharLiteral("'x'") << std::endl;  // Output: true
    std::cout << isValidCharLiteral("'abc'") << std::endl; // Output: false

    return 0;
}

#include <algorithm>

long long totalProblemsToSolve(long long n, long long k, long long d) {
    // Calculate minimum days needed to complete k problems when solving d problems per day
    long long minDays = k / d;
    if (k % d != 0) {
        minDays += 1;  // Add extra day if there's remainder
    }

    // Total problems = number of topics × days needed
    long long problemsFromTopics = n * minDays;

    // The answer is the maximum between problems from topics and the required k problems
    return (problemsFromTopics > k) ? problemsFromTopics : k;
}

