// Type definitions for 64-bit unsigned integers
typedef unsigned long long U64;
using BitBoard = U64;

// Generate a 64-bit random value by combining multiple rand() calls
BitBoard generateRandom64() {
    U64 part1 = static_cast<U64>(std::rand());
    U64 part2 = static_cast<U64>(std::rand()) << 15;
    U64 part3 = static_cast<U64>(std::rand()) << 30;
    U64 part4 = static_cast<U64>(std::rand()) << 45;
    U64 part5 = static_cast<U64>(std::rand() & 0xF) << 60;

    return part1 | part2 | part3 | part4 | part5;
}

// Create a 64-bit bitboard with limited set bits using bitwise AND of three random values
BitBoard generateSparseRandom() {
    BitBoard a = generateRandom64();
    BitBoard b = generateRandom64();
    BitBoard c = generateRandom64();
    return a & b & c;
}

int main() {
    // Demonstrate the sparse random bitboard generator
    BitBoard sample = generateSparseRandom();
    std::cout << "Sparse random bitboard: " << sample << std::endl;
    return 0;
}

#include <vector>

class CFill {
private:
    std::vector<std::vector<int>> grid;
    int height;
    int width;

    void floodFillRecursive(int row, int col, int targetColor, int replacementColor) {
        // Check boundary conditions and color match
        if (row < 0 || row >= height || col < 0 || col >= width || grid[row][col] != targetColor) {
            return;
        }

        // Update current cell's color
        grid[row][col] = replacementColor;

        // Recursively process adjacent cells (up, down, left, right)
        floodFillRecursive(row + 1, col, targetColor, replacementColor);
        floodFillRecursive(row - 1, col, targetColor, replacementColor);
        floodFillRecursive(row, col + 1, targetColor, replacementColor);
        floodFillRecursive(row, col - 1, targetColor, replacementColor);
    }

public:
    CFill() : height(10), width(10), grid(std::vector<std::vector<int>>(10, std::vector<int>(10, 0))) {
        // Initialize the grid with default dimensions and zero values
    }

    void performFloodFill(int startX, int startY, int newColorValue) {
        // Validate input coordinates
        if (startX < 0 || startX >= height || startY < 0 || startY >= width) {
            return;
        }

        int originalColor = grid[startX][startY];

        // Avoid unnecessary work if colors are identical
        if (originalColor == newColorValue) {
            return;
        }

        floodFillRecursive(startX, startY, originalColor, newColorValue);
    }
};

