#include <vector>
#include <algorithm>

std::vector<int> processQueries(std::vector<Query>& queries, std::vector<int>& nums) {
    std::vector<int> result;

    for (const auto& query : queries) {
        // Extract the subarray from index l to r (inclusive)
        int left = query.l;
        int right = query.r;
        std::vector<int> temp;

        // Manually copy elements instead of using vector constructor
        for (int idx = left; idx <= right; ++idx) {
            temp.push_back(nums[idx]);
        }

        // Sort the temporary array
        std::sort(temp.begin(), temp.end());

        // Add the k-th smallest element (1-indexed) to result
        result.push_back(temp[query.k - 1]);
    }

    return result;
}

