namespace eosio {
  class [[eosio::contract("wlist.token")]] token : public contract {
  public:
    using contract::contract;

    // Structure representing an account with owner and balance
    struct [[eosio::table]] user_account {
      name owner;
      uint64_t balance;
      uint64_t primary_key() const { return owner.value; }
    };

    // Multi-index table type for accounts
    typedef multi_index<"accounts"_n, user_account> account_table;

    // Constructor
    token(name receiver, name code, datastream<const char *> ds)
        : contract(receiver, code, ds) {}

    // Transfer tokens from one account to another
    [[eosio::action]]
    void transfer(name sender, name recipient, uint64_t amount) {
      require_auth(sender);

      account_table sender_accounts(get_self(), sender.value);
      auto sender_iter = sender_accounts.find(sender.value);
      eosio_assert(sender_iter != sender_accounts.end(), "Sender account not found");
      eosio_assert(sender_iter->balance >= amount, "Not enough balance");

      account_table recipient_accounts(get_self(), recipient.value);
      auto recipient_iter = recipient_accounts.find(recipient.value);

      if (recipient_iter == recipient_accounts.end()) {
        recipient_accounts.emplace(sender, [&](auto &acc) {
          acc.owner = recipient;
          acc.balance = amount;
        });
      } else {
        recipient_accounts.modify(recipient_iter, same_payer, [&](auto &acc) {
          acc.balance += amount;
        });
      }

      sender_accounts.modify(sender_iter, same_payer, [&](auto &acc) {
        acc.balance -= amount;
      });
    }

    // Retrieve the balance of a given account
    [[eosio::action]]
    uint64_t get_balance(name account_owner) {
      account_table accounts(get_self(), account_owner.value);
      auto iter = accounts.find(account_owner.value);
      eosio_assert(iter != accounts.end(), "Account does not exist");
      return iter->balance;
    }
  };
}  // namespace eosio

