void applyGraphOptimization(Operation* operation, Tensor* sourceTensor, Tensor* targetTensor) {
    // Construct new nodes and intermediate tensors for the optimization pass
    Operation* quant_node = new Operation("quantize_output");
    Operation* scale_op = new Operation("scale_multiply");
    Operation* clamp_node = new Operation("clamp_max");
    Tensor* scale_factor = new Tensor("scale");
    Tensor* dequantized_input = new Tensor("dequant_in");

    // Rename the quantization node and wire it to the downstream max operation
    quant_node->name(std::string(targetTensor->name()->string_view()) + "/quantize");
    quant_node->input().connect(clamp_node->output());

    // Wire up the scaling operation with its operands
    scale_op->input_b().connect(scale_factor->output());
    scale_op->input_a().connect(dequantized_input->output());

    // Configure the clamp node to use both the scaled and original inputs
    clamp_node->input_b().connect(scale_op->output());
    clamp_node->input_a().connect(dequantized_input->output());

    // Establish connections between tensors and operations at graph boundaries
    bind_input_tensor(&dequantized_input->input(), sourceTensor);
    bind_output_tensor(targetTensor, &quant_node->output());
}

