// Compute the minimal energy configuration for a given loop structure
int computeLoopEnergy(int start_pos, int end_pos, CTStructure* structure, EnergyData* params) {
    int min_energy = INT_MAX;  // Start with maximum possible value as baseline

    // First contribution: loop-specific energy with stacking and penalty terms
    int loop_contribution = erg4(start_pos, end_pos, end_pos - 1, 2, structure, params, 
                                  lfce[end_pos - 1]) + 
                            penalty(start_pos, end_pos, structure, params) +
                            wmb.f(start_pos + 1, end_pos - 2) + 
                            params->eparam[5] + params->eparam[6] + params->eparam[10];

    if (loop_contribution < min_energy) {
        min_energy = loop_contribution;
    }

    // Second contribution: stacking interactions and non-pairing contributions
    int stacking_energy = params->tstkm[structure->numseq[start_pos]][structure->numseq[end_pos]]
                                [structure->numseq[start_pos + 1]][structure->numseq[end_pos - 1]];
    int non_pairing_term = checknp(lfce[start_pos + 1], lfce[end_pos - 1]);

    int combined_contribution = stacking_energy + non_pairing_term;

    if (combined_contribution < min_energy) {
        min_energy = combined_contribution;
    }

    return min_energy;  // Return the lowest energy found
}

