// Helper struct to deduce the function pointer signature from various callable types
template <typename T>
struct callable_signature;

// Specialization for raw function pointers
template <typename R, typename... P>
struct callable_signature<R(*)(P...)> {
    using type = R(*)(P...);
};

// Specialization for std::function objects
template <typename R, typename... P>
struct callable_signature<std::function<R(P...)>> {
    using type = R(*)(P...);
};

// Generic case: handles lambdas and other callables with operator()
template <typename C>
struct callable_signature<C> {
    using type = typename callable_signature<
        decltype(&std::remove_reference_t<C>::operator())
    >::type;
};

// Extracts the function pointer from a callable using decay and capture-less lambda conversion
template <typename F>
auto extract_function_pointer(F&& f) -> typename callable_signature<std::decay_t<F>>::type {
    return +f;  // Unary plus triggers implicit conversion of captureless lambda to function pointer
}

int main() {
    // Create a simple addition lambda (captureless)
    auto add_lambda = [](int a, int b) { return a + b; };

    // Convert it to a function pointer
    auto fn_ptr = extract_function_pointer(add_lambda);

    // Use the function pointer
    std::cout << fn_ptr(10, 20) << std::endl;  // Output: 30

    return 0;
}

