// Generate a random value from a normal distribution with mean 0 and std dev 1
double sampleNormal(std::mt19937& rng) {
    std::normal_distribution<double> normDist(0.0, 1.0);
    return normDist(rng);
}

int main() {
    // Initialize simulation parameters
    double velocity = 0.0;       // Starting velocity
    double position = 0.0;       // Starting position
    double velStdDev = 0.1;      // Standard deviation for velocity noise
    double posStdDev = 0.2;      // Standard deviation for position noise
    int totalSteps = 100;        // Number of simulation steps
    std::mt19937 generator;      // Mersenne Twister random number generator

    // Container for storing current state data
    std::map<std::string, double> currentState;

    int stepIndex = 0;           // Step counter for indexing
    double currentTime = 0.0;    // Simulation time tracker

    // Perform simulation over the specified number of steps
    for (int step = 0; step < totalSteps; ++step) {
        // Apply stochastic updates using Euler-Maruyama approximation
        velocity += velStdDev * sampleNormal(generator);
        position += posStdDev * sampleNormal(generator);

        // Populate current state data
        currentState["Index"] = static_cast<double>(stepIndex++);
        currentState["Time"] = currentTime;
        currentState["Velocity"] = velocity;
        currentState["Position"] = position;
        currentState["PosNoiseStd"] = posStdDev;
        currentState["VelNoiseStd"] = velStdDev;

        // Output all current state variables
        for (const auto& [key, value] : currentState) {
            std::cout << key << ": " << value << std::endl;
        }

        // Advance simulation time
        currentTime += 1.0;

        // Reset container for next iteration
        currentState.clear();
    }

    return 0;
}

