#include <filesystem>

namespace fs = std::filesystem;

// Search for the 'resources' directory by traversing upward from the given path
fs::path DirectoryUtils::searchResourceDirectory(const fs::path& workingDirectory) {
    // Begin search at the provided working directory
    fs::path searchPath = workingDirectory;

    // Continue searching while there are parent directories to check
    while (!searchPath.empty()) {
        // Construct potential resource directory path
        fs::path candidatePath = searchPath / "resources";

        // Check if this path exists and is a directory
        if (fs::exists(candidatePath) && fs::is_directory(candidatePath)) {
            return candidatePath;
        }

        // Move up one level in the directory tree
        searchPath = searchPath.has_parent_path() ? searchPath.parent_path() : fs::path();
    }

    // Return empty path if no resources directory was found
    return fs::path();
}

