// Parallel image processing using OpenMP with alternative loop structure
void demo_parallel() {
    #pragma omp parallel
    {
        // Get current thread information
        int current_thread = omp_get_thread_num();
        int total_threads = omp_get_num_threads();

        // Compute work distribution for this thread
        int base_chunk = image_data_size / total_threads;
        int remainder = image_data_size % total_threads;

        // Distribute extra elements to earlier threads
        int offset = (current_thread < remainder) ? current_thread : remainder;
        int my_chunk_size = base_chunk + ((current_thread < remainder) ? 1 : 0);

        int begin_pos = current_thread * base_chunk + offset;
        int finish_pos = begin_pos + my_chunk_size;

        // Process assigned portion of image data
        for (int idx = begin_pos; idx < finish_pos; ++idx) {
            process_image_data(image_data[idx]);
        }
    }
}

