// Custom transition class that inherits from guarded_action_transition
template <typename EventType, typename GuardFunc, typename ActionFunc>
class CustomTransition : public skizzay::fsm::guarded_action_transition<EventType> {
public:
    CustomTransition(EventType evt, GuardFunc guard_fn, ActionFunc action_fn)
        : skizzay::fsm::guarded_action_transition<EventType>(evt), 
          guard_fn_(guard_fn), 
          action_fn_(action_fn) {}

    bool check_guard() const override {
        return guard_fn_();
    }

    void perform_action() const override {
        action_fn_();
    }

private:
    GuardFunc guard_fn_;
    ActionFunc action_fn_;
};

// Define states and events for the finite state machine
enum class MachineState { INITIAL, FINAL };
enum class SystemEvent { ACTIVATE };

int main() {
    // Define guard condition and action as lambdas
    auto guard_check = []() -> bool { return true; };
    auto do_action = []() { std::cout << "Action executed successfully" << std::endl; };

    // Instantiate the custom transition
    CustomTransition<SystemEvent, decltype(guard_check), decltype(do_action)> 
        my_transition(SystemEvent::ACTIVATE, guard_check, do_action);

    // Set up the FSM with initial state
    skizzay::fsm::finite_state_machine<MachineState, SystemEvent> machine(MachineState::INITIAL);

    // Add the transition to the FSM
    machine.add_transition(MachineState::INITIAL, SystemEvent::ACTIVATE, MachineState::FINAL, my_transition);

    // Process the event to trigger the transition
    machine.process_event(SystemEvent::ACTIVATE);

    return 0;
}

