#include <cmath>

class ZComplex {
private:
    double realPart;
    double imagPart;
public:
    ZComplex(double r, double i) : realPart(r), imagPart(i) {}

    ZComplex add(const ZComplex& other) const {
        return ZComplex(realPart + other.realPart, imagPart + other.imagPart);
    }

    ZComplex subtract(const ZComplex& other) const {
        return ZComplex(realPart - other.realPart, imagPart - other.imagPart);
    }

    ZComplex multiply(const ZComplex& other) const {
        return ZComplex(
            realPart * other.realPart - imagPart * other.imagPart,
            realPart * other.imagPart + imagPart * other.realPart
        );
    }

    ZComplex divide(const ZComplex& other) const {
        double normSquared = other.realPart * other.realPart + other.imagPart * other.imagPart;
        return ZComplex(
            (realPart * other.realPart + imagPart * other.imagPart) / normSquared,
            (imagPart * other.realPart - realPart * other.imagPart) / normSquared
        );
    }

    ZComplex power(int exponent) const {
        double magnitude = std::sqrt(realPart * realPart + imagPart * imagPart);
        double angle = std::atan2(imagPart, realPart);
        double resultMagnitude = std::pow(magnitude, exponent);
        return ZComplex(
            resultMagnitude * std::cos(exponent * angle),
            resultMagnitude * std::sin(exponent * angle)
        );
    }
};

