class TripleReflectedCount {
private:
    std::vector<int> data;
public:
    TripleReflectedCount(const std::vector<int>& input) : data(input) {}

    int countValue(int target) {
        // Count occurrences in original order
        int forwardCount = 0;
        for (int item : data) {
            if (item == target) forwardCount++;
        }

        // Count occurrences in reverse order (same as forward since it's the same elements)
        int backwardCount = 0;
        for (auto it = data.rbegin(); it != data.rend(); ++it) {
            if (*it == target) backwardCount++;
        }

        // Return total: original count + 3 times reversed count
        return forwardCount + 3 * backwardCount;
    }
};

int main() {
    std::vector<int> sampleData = {1, 2, 3, 0, 4, 0, 3, 2, 1};
    TripleReflectedCount counter(sampleData);
    int searchValue = 0;
    int result = counter.countValue(searchValue);
    std::cout << "Frequency of " << searchValue << " in the mirrored list: " << result << std::endl;
    return 0;
}

#include "../include/cpp_lane_line_detection.h"
#include <vector>

int main(int argc, char * argv[])
{
    // Process each input image provided as command-line argument
    for (int imgIndex = 1; imgIndex < argc; ++imgIndex) {
        // Load the current image from disk
        cv::Mat sourceImage = cv::imread(argv[imgIndex]);

        // Convert to grayscale and apply smoothing
        cv::Mat grayscale, smoothed, edges;
        cv::cvtColor(sourceImage, grayscale, cv::COLOR_BGR2GRAY);
        cv::GaussianBlur(grayscale, smoothed, cv::Size(5, 5), 0);
        cv::Canny(smoothed, edges, 50, 150);

        // Define and apply a trapezoidal region of interest
        cv::Mat roiMask = cv::Mat::zeros(edges.size(), edges.type());
        cv::Point vertices[4] = {
            cv::Point(100, edges.rows),
            cv::Point(450, 300),
            cv::Point(550, 300),
            cv::Point(edges.cols - 100, edges.rows)
        };
        cv::fillConvexPoly(roiMask, vertices, 4, cv::Scalar(255));
        cv::bitwise_and(edges, roiMask, edges);

        // Detect line segments using probabilistic Hough transform
        std::vector<cv::Vec4i> detectedSegments;
        cv::HoughLinesP(edges, detectedSegments, 1.0, CV_PI / 180.0, 50, 50.0, 10.0);

        // Overlay detected lane lines on the original image
        for (const auto& segment : detectedSegments) {
            cv::line(sourceImage,
                     cv::Point(segment[0], segment[1]),
                     cv::Point(segment[2], segment[3]),
                     cv::Scalar(0, 0, 255),
                     3,
                     cv::LINE_AA);
        }

        // Show the result with overlaid lane markings
        cv::imshow("Lane Detection Result", sourceImage);
        cv::waitKey(0);
    }

    return 0;
}

#include <iostream>

// Custom smart pointer implementation with shared ownership semantics
template <typename T>
class SmartPointer {
private:
    T* dataPtr;
    unsigned long* countPtr;

public:
    // Initialize with raw pointer
    explicit SmartPointer(T* p) : dataPtr(p), countPtr(new unsigned long(1)) {}

    // Copy constructor: shares ownership and increments reference count
    SmartPointer(const SmartPointer& other) : dataPtr(other.dataPtr), countPtr(other.countPtr) {
        ++(*countPtr);
    }

    // Assignment operator: handles self-assignment, decrements old ref count, increments new one
    SmartPointer& operator=(const SmartPointer& other) {
        if (this != &other) {
            // Release current resource if no longer referenced
            if (--(*countPtr) == 0) {
                delete dataPtr;
                delete countPtr;
            }
            // Take over ownership of other's resources
            dataPtr = other.dataPtr;
            countPtr = other.countPtr;
            ++(*countPtr);
        }
        return *this;
    }

    // Destructor: releases resource when last reference is gone
    ~SmartPointer() {
        if (--(*countPtr) == 0) {
            delete dataPtr;
            delete countPtr;
        }
    }

    // Access the underlying pointer
    T* access() const {
        return dataPtr;
    }

    // Query how many SmartPointers share ownership
    unsigned long references() const {
        return *countPtr;
    }
};

int main() {
    // First SmartPointer instance managing an integer
    SmartPointer<int> sp1(new int(42));

    // Second SmartPointer sharing ownership with first
    SmartPointer<int> sp2 = sp1;

    // Output current reference count
    std::cout << "Reference count: " << sp1.references() << std::endl;

    // Third SmartPointer managing a different integer
    SmartPointer<int> sp3(new int(100));

    // Reassign sp2 to share ownership with sp3
    sp2 = sp3;

    // Output updated reference count for sp3
    std::cout << "Reference count: " << sp3.references() << std::endl;

    return 0;
}

