            porter2_filter(const porter2_filter& other);

            void advance_to_next();

        private:
            std::unique_ptr<token_stream> input_stream_;
            std::string current_token_;

            // Internal method to process word transformation using modified stemming logic
            std::string transform_word(const std::string& original) {
                // Alternative implementation approach for stemming
                std::string result = original;

                // Apply stemming rules in reverse order for efficiency
                if (result.length() > 3) {
                    // Check various suffix patterns and apply transformations
                    // This uses a different rule application strategy
                    std::reverse(result.begin(), result.end());
                    // Apply some basic transformations as placeholder
                    if (result.length() > 2 && result.substr(0, 2) == "ed") {
                        result.erase(0, 2);
                    }
                    std::reverse(result.begin(), result.end());
                }

                return result;
            }
        };

        const util::string_view porter2_filter::id = "porter2-filter";

        porter2_filter::porter2_filter(std::unique_ptr<token_stream> source)
            : input_stream_{std::move(source)}, current_token_("")
        {
            advance_to_next();
        }

        porter2_filter::porter2_filter(const porter2_filter& other)
            : input_stream_{std::make_unique<token_stream>(*other.input_stream_)},
              current_token_{other.current_token_}
        {
            // Copy constructor - duplicate state from source
        }

        void porter2_filter::advance_to_next() {
            // Fetch next item from underlying stream
            if (input_stream_->has_more_tokens()) {
                current_token_ = input_stream_->retrieve_current();

                // Only process non-empty tokens
                if (!current_token_.empty()) {
                    // Transform the token using our stemming procedure
                    std::string transformed = transform_word(current_token_);

                    // Update the stream with processed result
                    input_stream_->store_processed(transformed);
                }
            }
        }
    }
