};

// Class for enumeration properties
class CEnumProp : public CBaseProp {
public:
    int GetVal(void* pData) {
        // Implementation to retrieve the value of the enumeration property
        return *static_cast<int*>(pData);
    }
};

// Class for flags properties
class CFlagsProp : public CBaseProp {
public:
    int GetVal(void* pData) {
        // Implementation to retrieve the value of the flags property
        return *static_cast<int*>(pData);
    }
};

// Class for string properties
class CStringProp : public CBaseProp {
public:
    std::string GetVal(void* pData) {
        // Implementation to retrieve the value of the string property
        return *static_cast<std::string*>(pData);
    }
};

// Property serializer class
class PropSerializer {
public:
    void WriteProperty(EPropType propKind, CBaseProp* pProp, std::ostream& rOut) {
        switch (propKind) {
            case EPropType::Enum: {
                CEnumProp* pEnum = dynamic_cast<CEnumProp*>(pProp);
                if (pEnum) {
                    rOut << pEnum->GetVal(nullptr);
                }
                break;
            }
            case EPropType::Flags: {
                CFlagsProp* pFlags = dynamic_cast<CFlagsProp*>(pProp);
                if (pFlags) {
                    rOut << pFlags->GetVal(nullptr);
                }
                break;
            }
            case EPropType::String: {
                CStringProp* pStr = dynamic_cast<CStringProp*>(pProp);
                if (pStr) {
                    rOut << pStr->GetVal(nullptr);
                }
                break;
            }
        }
    }
};

