    // Create and serialize a flags property
    CFlagsProp flagsProp;
    int flagsVal = 123;
    serializer.WriteProperty(EPropType::Flags, &flagsProp, std::cout);

    // Create and serialize a string property
    CStringProp stringProp;
    std::string stringVal = "Hello, World!";
    serializer.WriteProperty(EPropType::String, &stringProp, std::cout);

    return 0;
}

