// Compute derived components using state derivatives and acceleration values
std::vector<double> computeStateComponents(const DVec<double>& stateDerivatives, 
                                           const DVec<double>& bodyVelocities, 
                                           const DVec<double>& accelerations) {
    // Isolate translational and rotational parts from the state derivative vector
    DVec<double> translationalPart = stateDerivatives.segment(0, 6);
    DVec<double> angularPart = stateDerivatives.segment(6, 12);

    // Prepare container for computed results
    std::vector<double> resultComponents;

    // Iterate through the first six elements to compute pairwise products
    for (int idx = 0; idx < 6; ++idx) {
        resultComponents.push_back(translationalPart[idx] * angularPart[idx]);
    }

    return resultComponents;
}

