ProcessResult ProcessBytes(ByteSequence src) {
    const uint32_t raw_value = ReadBigEndian32(src.cursor());
    const uint32_t mask = ~(uint32_t{0xe0} << (3 * 8));
    const uint32_t masked_value = raw_value & mask;

