public:
    Output(Node* node, int index, Tensor* tensor) : m_node(node), m_index(index), m_tensor(tensor) {}

    // Add an input to the vector of inputs that use this output.
    void add_input(Input* input) {
        // Check if input already exists by iterating through the vector
        bool found = false;
        for (size_t i = 0; i < m_inputs.size(); ++i) {
            if (m_inputs[i] == input) {
                found = true;
                break;
            }
        }
        if (!found) {
            m_inputs.push_back(input);
        }
    }

    void remove_input(Input* input) {
        // Find and remove the input using manual iteration
        for (size_t i = 0; i < m_inputs.size(); ++i) {
            if (m_inputs[i] == input) {
                m_inputs.erase(m_inputs.begin() + i);
                break;
            }
        }
    }

    // Method to get the number of inputs (added to make code compile)
    size_t get_num_inputs() const {
        return m_inputs.size();
    }

private:
    Node* m_node;
    int m_index;
    Tensor* m_tensor;
    std::vector<Input*> m_inputs;
};

