// Function to decode storage information from the buffer
DeviceStorageDetails decodeStorageDetails(const BinaryBuffer& stream) {
    DeviceStorageDetails details;

    details.fileSystemKind = stream.extractUint16();
    details.permissionLevel = stream.extractUint16();

    // Convert bytes to megabytes by right-shifting 20 bits (divide by 2^20)
    details.totalCapacityMB = stream.extractUint64() >> 20;
