class CustomString {
private:
    char* data;
public:
    // Default constructor - initializes empty string
    CustomString() : data(new char[1]) {
        data[0] = '\0';
    }

    // Constructor from C-string
    CustomString(const char* input) : data(new char[strlen(input) + 1]) {
        strcpy(data, input);
    }

    // Destructor - releases allocated memory
    ~CustomString() {
        delete[] data;
    }

    // Returns the length of stored string
    size_t getSize() const {
        return strlen(data);
    }

    // Concatenates another CustomString to this one
    void add(const CustomString& additional) {
        size_t currentLen = getSize();
        size_t extraLen = additional.getSize();
        char* buffer = new char[currentLen + extraLen + 1];

        strcpy(buffer, data);
        strcat(buffer, additional.data);

        delete[] data;
        data = buffer;
    }

    // Provides access to underlying C-string
    const char* toString() const {
        return data;
    }
};

int main() {
    CustomString first;      // Empty string via default constructor
    CustomString second("Hello");   // Initialize with "Hello"
    CustomString third(" World");   // Initialize with " World"

    std::cout << "Initial string: " << first.toString() << std::endl;

    first.add(second);         // Append "Hello"
    std::cout << "After adding 'Hello': " << first.toString() << std::endl;

    first.add(third);          // Append " World"
    std::cout << "After adding ' World': " << first.toString() << std::endl;

