class DelegateManager
{
public:
    // Store a no-argument callable action
    void SetAction(ActionFunc&& action)
    {
        m_Action = std::forward<ActionFunc>(action);
    }

    // Store a delegate with signature int(int, bool)
    void SetDelegate(GenericDelegate<int, int, bool> delegate)
    {
        m_Delegate = std::move(delegate);
    }

    // Execute the stored action if it's valid
    void RunAction()
    {
        if (m_Action)
        {
            m_Action();
        }
    }

    // Execute the stored delegate with provided arguments
    int RunDelegate(int value, bool flag)
    {
        if (m_Delegate)
        {
            return m_Delegate(value, flag);
        }
        return -1; // Alternative default return value
    }

private:
    ActionFunc m_Action;
    GenericDelegate<int, int, bool> m_Delegate;
};

