// Determine the highest supported SIMD instruction set version
int maxSupportedSIMDVersion(const std::array<uint32_t, 4>& regs) {
    int highestVersion = 0;

    // Extract SSE4.2 support level from the first register
    int sseLevel = regs[0] & 0x0F;
    highestVersion = std::max(highestVersion, sseLevel);

    // Check for AVX support (bit 28 of the fourth register)
    int avxSupport = (regs[3] >> 28) & 1;
    highestVersion = std::max(highestVersion, avxSupport);

    return highestVersion;
}

