class Ball {
public:
    Ball(Ogre::Entity* ballMesh, Ogre::SceneManager* sceneManager);
    void update(float timeStep);
    void addImpulse(Ogre::Vector2 impulse);
    void checkBoundaryCollision(int windowWidth, int windowHeight);
private:
    Ogre::SceneNode* ballNode;
    Ogre::Vector2 currentVelocity;
    Ogre::Vector2 currentPosition;
};

Ball::Ball(Ogre::Entity* ballMesh, Ogre::SceneManager* sceneManager) {
    // Initialize the ball in the scene
    ballNode = sceneManager->getRootSceneNode()->createChildSceneNode();
    ballNode->setPosition(0.0f, 20.0f, 0.0f); // Centered horizontally, elevated vertically
    ballNode->setScale(0.1f, 0.1f, 0.1f);
    ballNode->attachObject(ballMesh);

    // Initialize motion state
    currentVelocity = Ogre::Vector2::ZERO;
    currentPosition = Ogre::Vector2::ZERO;
}

void Ball::update(float timeStep) {
    // Advance position using velocity and elapsed time
    currentPosition += currentVelocity * timeStep;
    ballNode->setPosition(currentPosition.x, 20.0f, currentPosition.y);
}

void Ball::addImpulse(Ogre::Vector2 impulse) {
    // Apply an instantaneous change to velocity (impulse)
    currentVelocity += impulse;
}

void Ball::checkBoundaryCollision(int windowWidth, int windowHeight) {
    // Check horizontal boundaries
    if (currentPosition.x <= 0.0f || currentPosition.x >= static_cast<float>(windowWidth)) {
        currentVelocity.x = -currentVelocity.x;
    }

    // Check vertical boundaries
    if (currentPosition.y <= 0.0f || currentPosition.y >= static_cast<float>(windowHeight)) {
        currentVelocity.y = -currentVelocity.y;
    }
}

