#include <queue>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <functional>

class WorkerPool {
public:
    WorkerPool(size_t thread_count) : active_(true), active_tasks_(0) {
        for (size_t i = 0; i < thread_count; ++i) {
            workers_.emplace_back([this] { runWorker(); });
        }
    }

    void submitTask() {
        std::unique_lock<std::mutex> lock(queue_mutex_);
        if (active_) {
            auto job = tasks_.front();
            tasks_.pop();
            lock.unlock();
            ++active_tasks_;
            job(); // Execute the submitted task
            lock.lock();
            --active_tasks_;
            condition_.notify_one();
        }
    }

    void shutdown() {
        {
            std::lock_guard<std::mutex> lock(queue_mutex_);
            active_ = false;
        }
        condition_.notify_all();
        for (auto& worker : workers_) {
            worker.join();
        }
    }

private:
    using Job = std::function<void()>;
    std::queue<Job> tasks_;
    std::vector<std::thread> workers_;
    std::mutex queue_mutex_;
    std::condition_variable condition_;
    bool active_;
    size_t active_tasks_;

    void runWorker() {
        while (true) {
            std::unique_lock<std::mutex> lock(queue_mutex_);
            condition_.wait(lock, [this] { return !active_ || !tasks_.empty(); });
            if (!active_ && tasks_.empty()) {
                break;
            }
            submitTask();
        }
    }
};

