#include <functional>

// Approximate the definite integral using the trapezoidal method
double trapezoidalIntegral(std::function<double(double)> f, double a, double b, int N) {
    double stepSize = (b - a) / static_cast<double>(N);  // Length of each subinterval

    // Start with the average of endpoint values
    double accumulatedSum = 0.5 * (f(a) + f(b));

    // Iterate through interior points
    int pointIndex = 1;
    double currentX = a + stepSize;

    while (pointIndex < N) {
        accumulatedSum += f(currentX);  // Add function value at interior point
        currentX += stepSize;           // Move to next x position
        pointIndex++;                   // Increment counter
    }

    return stepSize * accumulatedSum;  // Multiply by width to get final integral approximation
}

