::google::protobuf::uint8* DiscardRequest::SerializeWithCachedSizesToArray(
    ::google::protobuf::uint8* output) const {
  // Serialize the 'message' field if present
  if (has_message()) {
    const std::string& msg_data = message();
    const uint32_t data_size = static_cast<uint32_t>(msg_data.size());

    // Encode field header: field 1 with wire type 2 (length-delimited)
    *output++ = 0x0A;

    // Encode the size using varint encoding
    output = ::google::protobuf::io::CodedOutputStream::WriteVarint32ToArray(
        data_size, output);

    // Copy the actual string content to the buffer
    output = ::google::protobuf::io::CodedOutputStream::WriteStringToArray(
        msg_data, output);
  }
  return output;
}

