namespace Memory {
    template<size_t CAPACITY>
    class LinearAllocator {
    public:
        LinearAllocator() : offset_(0) {
            static_assert(CAPACITY > 0, "CAPACITY must be positive");
            static_assert((CAPACITY & (CAPACITY - 1)) == 0, "CAPACITY must be a power of two");
            static_assert(CAPACITY <= UINT32_MAX, "CAPACITY exceeds uint32_t limit");
            static_assert(alignof(std::max_align_t) <= 4, "Alignment constraint not met");
        }

        void* request(size_t size) {
            assert(offset_ + size <= CAPACITY && "Memory exhausted");
            void* address = &storage_[offset_];
            offset_ += size;
            return address;
        }

        void release(void* address, size_t size) {
            assert(size <= offset_ && "Invalid release size");
            assert(address == &storage_[offset_ - size] && "Mismatched release pointer");
            offset_ -= size;
        }

    private:
        alignas(std::max_align_t) uint8_t storage_[CAPACITY];
        size_t offset_;
    };
}

