// Template class for managing a contiguous array of plain old data (POD) elements
template<typename T, typename index_type>
class memory_array {
private:
    T* elements;       // Pointer to the underlying storage
    index_type length; // Number of elements currently stored

public:
    // Constructor: initialize with external data and specified size
    explicit memory_array(const T* source, const index_type count) {
        length = count;
        elements = new T[length];
        for (index_type idx = 0; idx < length; ++idx) {
            elements[idx] = source[idx];
        }
    }

    // Constructor: construct from an expression proxy (simplified interface)
    template<typename Expr>
    explicit memory_array(const Expr& expr) {
        length = expr.size();
        elements = new T[length];
        for (index_type idx = 0; idx < length; ++idx) {
            elements[idx] = expr.at(idx);
        }
    }

    // Non-const subscript operator: allows modification
    T& operator[] (const index_type pos) {
        return elements[pos];
    }

    // Const subscript operator: read-only access
    T operator[] (const index_type pos) const {
        return elements[pos];
    }

    // Non-const function call operator: alternative access syntax
    T& operator() (const index_type pos) {
        return elements[pos];
    }

    // Const function call operator: read-only alternative access
    T operator() (const index_type pos) const {
        return elements[pos];
    }

    // Resize the internal buffer to hold new_count elements
    void resize(const index_type new_count) {
        T* temp = new T[new_count];
        index_type copy_limit = (new_count < length) ? new_count : length;
        for (index_type i = 0; i < copy_limit; ++i) {
            temp[i] = elements[i];
        }
        delete[] elements;
        elements = temp;
        length = new_count;
    }

    // Release resources and reset state
    void clear() {
        delete[] elements;
        elements = nullptr;
        length = 0;
    }

    // Destructor: ensure proper cleanup
    ~memory_array() {
        delete[] elements;
    }
};

int main() {
    // Demonstration of the memory_array class
    int initial_data[] = {10, 20, 30, 40, 50};
    memory_array<int, std::size_t> arr(initial_data, 5);

    std::cout << arr[2] << std::endl;   // Output: 30

    arr.resize(3);
    // Accessing beyond new size is undefined behavior
    std::cout << arr[4] << std::endl;   // Output: Undefined/Garbage

    arr.clear();
    return 0;
}

