// Custom namespace to mimic fc::raw::unpack behavior
namespace custom {
    template <typename T>
    T deserialize(const char* buffer) {
        // Interpret the first sizeof(T) bytes as a little-endian integer
        T value = 0;
        for (size_t i = 0; i < sizeof(T); ++i) {
            value |= static_cast<unsigned char>(buffer[i]) << (8 * i);
        }
        return value;
    }
}

std::chrono::time_point<std::chrono::system_clock> convertFromRawTime(const char* rawData) {
    using namespace std::chrono;

    // Deserialize seconds from raw data
    int64_t secs = custom::deserialize<int64_t>(rawData);

    // Construct time_point from seconds duration
    system_clock::duration dur(secs);
    return time_point<system_clock>(dur);
}

