template <typename T, fcppt::math::size_type R, fcppt::math::size_type C>
bool compare_matrices(
    fcppt::math::matrix::object<T, R, C> const &lhs,
    fcppt::math::matrix::object<T, R, C> const &rhs,
    fcppt::math::matrix::object<T, R, C> const &expected)
{
    auto const computed = fcppt::math::matrix::binary_map(
        lhs,
        rhs,
        [](T const &a, T const &b) { return a + b; });

    return fcppt::math::matrix::comparison(computed, expected);
}

