// Type alias for log identifiers
using LogIdentifier = int;

// Type alias for key-value log entries
using LogEntries = std::vector<std::pair<std::string, std::string>>;

// Abstract base class for logging functionality
class LogProcessor {
public:
    virtual void record(LogIdentifier identifier, LogEntries entries) = 0;
};

// Concrete implementation of the logger
class DetailedLogger : public LogProcessor {
private:
    std::unordered_map<LogIdentifier, LogEntries> storage;
public:
    void record(LogIdentifier identifier, LogEntries entries) override {
        storage[identifier] = std::move(entries);
    }

    // Access stored entries by log identifier
    LogEntries fetchEntries(LogIdentifier identifier) const {
        auto it = storage.find(identifier);
        if (it != storage.end()) {
            return it->second;
        }
        return {};
    }
};

int main() {
    // Instantiate the logger
    DetailedLogger detailedLogger;

    // Record some key-value pairs under log ID 1
    detailedLogger.record(1, {{"key1", "value1"}, {"key2", "value2"}});

    // Retrieve and display the stored entries
    LogEntries retrieved = detailedLogger.fetchEntries(1);
    for (const auto& entry : retrieved) {
        std::cout << entry.first << ": " << entry.second << '\n';
    }

    return 0;
}

