class TxIn {
 private:
  struct OutPoint {
    // Implementation details of OutPoint
  };
  OutPoint prevOut;
  std::vector<uint8_t> scriptSig;
  uint32_t sequence;

 public:
  // Method to serialize the TxIn object into a byte stream
  std::vector<uint8_t> serialize() {
    std::vector<uint8_t> resultBuffer;

    // Convert OutPoint to bytes and append to buffer
    const uint8_t* outPointStart = reinterpret_cast<const uint8_t*>(&prevOut);
    const uint8_t* outPointEnd = outPointStart + sizeof(OutPoint);
    resultBuffer.insert(resultBuffer.end(), outPointStart, outPointEnd);

    // Append scriptSig content to the buffer
    resultBuffer.insert(resultBuffer.end(), scriptSig.begin(), scriptSig.end());

    // Handle sequence number conversion (endianness)
    uint32_t sequenceNetworkOrder = htobe32(sequence);  // Host to big-endian conversion
    const uint8_t* seqBytesBegin = reinterpret_cast<const uint8_t*>(&sequenceNetworkOrder);
    const uint8_t* seqBytesEnd = seqBytesBegin + SEQUENCE_SIZE;
    resultBuffer.insert(resultBuffer.end(), seqBytesBegin, seqBytesEnd);

    return resultBuffer;
  }
};

