// Function to distribute tasks among workers using modified round-robin approach
void assignTasks(const std::vector<Task>& taskList) {
    int totalTasks = taskList.size();
    int unassigned = totalTasks;

    // Distribute base portion of tasks evenly
    for (int workerId = 0; workerId < workerCount; ++workerId) {
        int startIdx = workerId * (totalTasks / workerCount);
        int endIdx = (workerId + 1) * (totalTasks / workerCount);

        // Assign tasks in the calculated range
        for (int idx = startIdx; idx < endIdx && idx < totalTasks; ++idx) {
            // Simulate task assignment: taskList[idx] assigned to workerId
            // For example: workers[workerId].addTask(taskList[idx]);
            unassigned--;
        }
    }

    // Distribute leftover tasks one-by-one to remaining workers
    int leftover = totalTasks % workerCount;
    for (int i = 0; i < leftover; ++i) {
        // Assign extra tasks to first 'leftover' workers in round-robin fashion
        // For example: workers[i].addTask(taskList[totalTasks - leftover + i]);
        unassigned--;
    }
}

