#include <fcppt/math/vector/object.hpp>
#include <fcppt/math/vector/static.hpp>

template <typename T, typename S1, typename S2>
fcppt::math::vector::static_<T, 3> cross(
    fcppt::math::vector::object<T, 3, S1> const &lhs,
    fcppt::math::vector::object<T, 3, S2> const &rhs)
{
  // Compute each component of the cross product
  T x_component = lhs[1] * rhs[2] - lhs[2] * rhs[1];
  T y_component = lhs[2] * rhs[0] - lhs[0] * rhs[2];
  T z_component = lhs[0] * rhs[1] - lhs[1] * rhs[0];

  // Return the result as a static vector
  return fcppt::math::vector::static_<T, 3>(x_component, y_component, z_component);
}

#include <iostream>
#include <cstring>

// Hash table implementation using separate chaining for collision resolution
class HashMap {
private:
    struct Entry {
        void* key;
        void* value;
        Entry* next;  // Chain for handling collisions
    };

    Entry** buckets;     // Dynamic array of bucket pointers
    size_t capacity;     // Current number of buckets
    size_t count;        // Number of stored entries
    double maxLoad;      // Load factor threshold before resizing

    // Simple hash function for pointer addresses
    size_t computeIndex(void* ptr, size_t size) {
        // Convert pointer to integer and apply hash mixing
        uintptr_t addr = reinterpret_cast<uintptr_t>(ptr);
        size_t hash = addr ^ (addr >> 7) ^ (addr >> 14);
        return hash % capacity;
    }

    // Insert new entry at the front of the chain at given index
    void prependEntry(size_t idx, void* k, void* v) {
        Entry* newNode = new Entry();
        newNode->key = k;
        newNode->value = v;
        newNode->next = buckets[idx];
        buckets[idx] = newNode;
    }

    // Double the table size and rehash all existing entries
    void expandBuckets() {
        size_t oldCap = capacity;
        capacity *= 2;

        Entry** oldBuckets = buckets;
        buckets = new Entry*[capacity]();
        std::memset(buckets, 0, sizeof(Entry*) * capacity);

        // Reinsert all entries into new buckets
        for (size_t i = 0; i < oldCap; ++i) {
            Entry* current = oldBuckets[i];
            while (current != nullptr) {
                size_t newIndex = computeIndex(current->key, 0);
                prependEntry(newIndex, current->key, current->value);

                Entry* temp = current;
                current = current->next;
                delete temp;
            }
        }

        delete[] oldBuckets;
    }

public:
    HashMap(size_t initialCapacity, double loadLimit) 
        : capacity(initialCapacity), count(0), maxLoad(loadLimit) {
        buckets = new Entry*[capacity];
        std::memset(buckets, 0, sizeof(Entry*) * capacity);
    }

    ~HashMap() {
        // Clean up all allocated memory
        for (size_t i = 0; i < capacity; ++i) {
            Entry* current = buckets[i];
            while (current != nullptr) {
                Entry* next = current->next;
                delete current;
                current = next;
            }
        }
        delete[] buckets;
    }

    // Add or update a key-value pair
    void put(void* key, void* value) {
        // Check if we need to resize before insertion
        if (static_cast<double>(count) / capacity > maxLoad) {
            expandBuckets();
        }

        size_t idx = computeIndex(key, 0);

        // Search for existing key in chain
        Entry* probe = buckets[idx];
        while (probe != nullptr) {
            if (probe->key == key) {  // Same key address
                probe->value = value; // Update value
                return;
            }
            probe = probe->next;
        }

        // Key not found - insert new entry
        prependEntry(idx, key, value);
        ++count;
    }

    // Get value associated with key, or nullptr if not found
    void* get(void* key) {
        size_t idx = computeIndex(key, 0);
        Entry* cursor = buckets[idx];

        while (cursor != nullptr) {
            if (cursor->key == key) {
                return cursor->value;
            }
            cursor = cursor->next;
        }

        return nullptr;
    }

    // Remove entry by key, return true if found and removed
    bool erase(void* key) {
        size_t idx = computeIndex(key, 0);
        Entry* prev = nullptr;
        Entry* cursor = buckets[idx];

        while (cursor != nullptr) {
            if (cursor->key == key) {
                if (prev == nullptr) {
                    buckets[idx] = cursor->next;
                } else {
                    prev->next = cursor->next;
                }
                delete cursor;
                --count;
                return true;
            }
            prev = cursor;
            cursor = cursor->next;
        }

        return false;
    }
};

int main() {
    // Demonstration of HashMap usage
    HashMap map(64, 0.8);  // Start with 64 buckets, resize at 80% load

    int key1 = 10, val1 = 100;
    int key2 = 20, val2 = 200;

    map.put(&key1, &val1);
    map.put(&key2, &val2);

