// Base class for all resources
class Resource {
public:
    virtual ~Resource() {}
    // Core resource lifecycle methods
    virtual void Initialize() = 0;
    virtual void Release() = 0;
};

// Manager class to handle resource registration and lifecycle
class ResourceManager {
private:
    std::map<std::string, Resource*> resourceTable;
    GraphicsContext* pGraphicsSystem;
    FileSystem* pStorageSystem;

public:
    ResourceManager(GraphicsContext* graphicsSystem, FileSystem* storageSystem)
        : pGraphicsSystem(graphicsSystem), pStorageSystem(storageSystem) {}

    // Add a new resource to the registry
    void AddToRegistry(const std::string& identifier, Resource* resource) {
        resourceTable[identifier] = resource;
    }

    // Initialize a registered resource
    void InitializeResource(const std::string& identifier) {
        if (!pGraphicsSystem || !pStorageSystem) {
            std::cerr << "Required systems not available for initialization" << std::endl;
            return;
        }

        auto iter = resourceTable.find(identifier);
        if (iter != resourceTable.end()) {
            iter->second->Initialize();
        } else {
            std::cerr << "Unknown resource: '" << identifier << "'" << std::endl;
        }
    }

    // Deinitialize a registered resource
    void DeinitializeResource(const std::string& identifier) {
        auto iter = resourceTable.find(identifier);
        if (iter != resourceTable.end()) {
            iter->second->Release();
        } else {
            std::cerr << "Unknown resource: '" << identifier << "'" << std::endl;
        }
    }

    // Retrieve a resource by name
    Resource* FindResource(const std::string& identifier) {
        auto iter = resourceTable.find(identifier);
        if (iter != resourceTable.end()) {
            return iter->second;
        } else {
            std::cerr << "Resource lookup failed: '" << identifier << "' not found" << std::endl;
            return nullptr;
        }
    }
};

