#include <type_traits>

template<typename...>
struct list {};

// Comparison metafunction: returns true if sizeof(T) <= sizeof(U)
template<typename T, typename U>
struct compare_size : std::integral_constant<bool, sizeof(T) <= sizeof(U)> {};

// Helper for merging two type lists
template<typename L1, typename L2, typename Acc, typename Cmp>
struct merge_helper;

// Base cases: when one list is empty, append the other to accumulator
template<typename... xs, typename Acc, typename Cmp>
struct merge_helper<list<xs...>, list<>, Acc, Cmp> {
    using type = Acc;
};

template<typename... ys, typename Acc, typename Cmp>
struct merge_helper<list<>, list<ys...>, Acc, Cmp> {
    using type = Acc;
};

// Recursive case: compare first elements and prepend smaller one to accumulator
template<typename x, typename... xt, typename y, typename... yt, typename... acc, typename Cmp>
struct merge_helper<list<x, xt...>, list<y, yt...>, list<acc...>, Cmp> {
    using result = typename std::conditional<
        Cmp::template apply<x, y>::value,
        typename merge_helper<list<xt...>, list<y, yt...>, list<acc..., x>, Cmp>::type,
        typename merge_helper<list<x, xt...>, list<yt...>, list<acc..., y>, Cmp>::type
    >::type;

    using type = result;
};

int main() {
    // Merge two sorted type lists: [1,3,5] and [2,4,6]
    using merged_list = typename merge_helper<
        list<int, int, int>,    // representing [1,3,5] as types
        list<int, int, int>,    // representing [2,4,6] as types
        list<>,                 // empty accumulator
        compare_size            // comparison function
    >::type;

    return 0;
}

