using namespace eosio;

class [[eosio::contract]] MyToken : public contract {
public:
  using contract::contract;

  // Create a new token with given issuer and max supply
  [[eosio::action]]
  void create(name issuer, asset maximum_supply) {
    require_auth(_self);

    symbol_code sym_code = maximum_supply.symbol.code();
    check(maximum_supply.symbol.is_valid(), "invalid symbol name");
    check(maximum_supply.amount > 0, "max-supply must be positive");
    check(maximum_supply.is_valid(), "invalid supply");

    stats_table statstable(_self, sym_code.raw());
    auto existing = statstable.find(sym_code.raw());
    check(existing == statstable.end(), "token with symbol already exists");

    statstable.emplace(_self, [&](auto& s) {
      s.supply = asset{0, maximum_supply.symbol};
      s.max_supply = maximum_supply;
      s.issuer = issuer;
    });
  }

  // Issue additional tokens to a recipient
  [[eosio::action]]
  void issue(name to, asset quantity, std::string memo) {
    symbol_code sym_code = quantity.symbol.code();
    check(quantity.symbol.is_valid(), "invalid symbol name");
    check(memo.length() <= 256u, "memo exceeds 256 bytes");

    stats_table statstable(_self, sym_code.raw());
    auto it = statstable.find(sym_code.raw());
    check(it != statstable.end(), "token with symbol does not exist");

    const auto& token_stats = *it;
    require_auth(token_stats.issuer);

    check(quantity.amount > 0, "must issue positive quantity");
    check(quantity.is_valid(), "invalid quantity");
    check(quantity.symbol == token_stats.supply.symbol, "symbol mismatch");

    asset remaining = token_stats.max_supply - token_stats.supply;
    check(quantity.amount <= remaining.amount, "insufficient remaining supply");

    statstable.modify(token_stats, same_payer, [&](auto& s) {
      s.supply += quantity;
    });

    // Update issuer balance first
    update_account_balance(token_stats.issuer, quantity, token_stats.issuer);

    // If recipient differs from issuer, trigger transfer
    if (to != token_stats.issuer) {
      send_inline_transfer(token_stats.issuer, to, quantity, memo);
    }
  }

  // Transfer tokens between accounts
  [[eosio::action]]
  void transfer(name from, name to, asset quantity, std::string memo) {
    check(from != to, "cannot transfer to self");
    require_auth(from);
    check(is_account(to), "destination account does not exist");

    symbol_code sym_code = quantity.symbol.code();
    stats_table statstable(_self, sym_code.raw());
    const auto& token_stats = statstable.get(sym_code.raw());

    require_recipient(from);
    require_recipient(to);

    check(quantity.amount > 0, "transfer amount must be positive");
    check(quantity.is_valid(), "invalid quantity");
    check(memo.length() <= 256u, "memo too long");

    deduct_from(from, quantity);
    credit_to(to, quantity, from);
  }

  // Query account balance for the caller
  [[eosio::action]]
  void balance(name account) {
    require_auth(account);
    accounts_table accountstable(_self, account.value);
    const auto& entry = accountstable.get(account.value, "no balance found");
    print("Balance: ", entry.balance);
  }

private:
  struct [[eosio::table]] account_record {
    asset balance;
    uint64_t primary_key() const { return balance.symbol.code().raw(); }
  };

  struct [[eosio::table]] token_statistics {
    asset supply;
    asset max_supply;
    name issuer;
    uint64_t primary_key() const { return supply.symbol.code().raw(); }
  };

  typedef multi_index<"accounts"_n, account_record> accounts_table;
  typedef multi_index<"stat"_n, token_statistics> stats_table;

  // Helper: Deduct balance from an account
  void deduct_from(name owner, asset amount) {
    accounts_table from_acnts(_self, owner.value);
    auto iter = from_acnts.find(amount.symbol.code().raw());
    check(iter != from_acnts.end(), "balance object missing");

    const auto& current = *iter;
    check(current.balance.amount >= amount.amount, "insufficient funds");

    if (current.balance.amount == amount.amount) {
      from_acnts.erase(iter);
    } else {
      from_acnts.modify(current, owner, [&](auto& rec) {
        rec.balance -= amount;
      });
    }
  }

  // Helper: Add balance to an account
  void credit_to(name owner, asset amount, name payer) {
    accounts_table to_acnts(_self, owner.value);
    auto iter = to_acnts.find(amount.symbol.code().raw());

    if (iter == to_acnts.end()) {
      to_acnts.emplace(payer, [&](auto& rec) {
        rec.balance = amount;
      });
    } else {
      to_acnts.modify(*iter, payer, [&](auto& rec) {
        rec.balance += amount;
      });
    }
  }

  // Internal alias for add_balance
  void update_account_balance(name owner, asset amount, name ram_payer) {
    credit_to(owner, amount, ram_payer);
  }

  // Inline action sender for transfers
  void send_inline_transfer(name from, name to, asset qty, std::string note) {
    SEND_INLINE_ACTION(*this, transfer, {from, "active"_n}, {from, to, qty, note});
  }
};

