// Process a module from the input stream
// Returns 0 for success, non-zero for failure
int ProcessModule(char pointerSize, const char* start, const char* limit) {
    // Validate input pointers
    if (start == nullptr || limit == nullptr || start > limit) {
        std::cerr << "Invalid buffer pointers provided" << std::endl;
        return 1;
    }

    // Ensure there's at least one byte available for size
    if (start + 1 > limit) {
        std::cerr << "Not enough data to determine module length" << std::endl;
        return 1;
    }

    // Extract module length from first byte
    unsigned char lengthByte = static_cast<unsigned char>(*start);
    int moduleLength = lengthByte;

    // Verify module fits within buffer bounds
    if (start + moduleLength + 1 > limit) {
        std::cerr << "Module exceeds buffer boundaries or data is incomplete" << std::endl;
        return 1;
    }

    // Simulate module processing by outputting its content
    std::cout << "Handling module: ";
    for (int idx = 0; idx < moduleLength; ++idx) {
        std::cout << *(start + idx + 1);  // Display module payload
    }
    std::cout << std::endl;

    // Advance pointer past current module (size byte + payload)
    const char* nextPosition = start + moduleLength + 1;
    // Note: In real implementation, we'd update caller's pointer via reference/pointer

    return 0;  // Indicate successful processing
}

int main() {
    const char* testData = "5Hello7World";
    const char* cursor = testData;
    const char* boundary = testData + 12;  // Total length including null terminator

    while (cursor < boundary && *cursor != '\0') {
        // Get current byte as size indicator
        char sizeIndicator = *cursor;

        // Process the module starting after the size byte
        int status = ProcessModule(sizeIndicator, cursor + 1, boundary);
        if (status != 0) {
            std::cerr << "Failed to process module correctly" << std::endl;
            return 1;
        }

        // Move cursor forward by module size + 1 (for size byte)
        cursor += sizeIndicator + 2;  // +1 for size byte, +moduleLength for payload
    }

    return 0;
}

