// Abstract base class for input/output operations
class io_handler {
public:
  virtual bool perform_read() = 0;
  virtual bool perform_write() = 0;
  virtual void assign_filename(const std::string& path) = 0;
  virtual ~io_handler() = default;
};

// Singleton factory pattern for dynamic IO object creation
class io_manager {
public:
  static io_manager& get_instance() {
    static io_manager instance;
    return instance;
  }

  using creator_function = io_handler* (*)();

  bool register_io_type(const std::string& name, creator_function func) {
    return creators_.insert({name, func}).second;
  }

  io_handler* instantiate(const std::string& kind, const std::string& filepath) {
    auto found = creators_.find(kind);
    if (found != creators_.end()) {
      io_handler* handler = found->second();
      handler->assign_filename(filepath);
      return handler;
    }
    return nullptr;
  }

private:
  io_manager() = default;
  std::unordered_map<std::string, creator_function> creators_;
};

