enum class Orientation { Horizontal, Vertical };

class GridReader {
private:
    std::vector<std::vector<char>> data;

public:
    GridReader(const std::vector<std::vector<char>>& initialData) : data(initialData) {}

    std::string extract(int startRow, int startCol, Orientation dir, int count) {
        std::string result;

        if (dir == Orientation::Horizontal) {
            for (int offset = 0; offset < count; ++offset) {
                result += data[startRow][startCol + offset];
            }
        } else if (dir == Orientation::Vertical) {
            for (int offset = 0; offset < count; ++offset) {
                result += data[startRow + offset][startCol];
            }
        }

        return result;
    }
};

int main() {
    std::vector<std::vector<char>> initialGrid = {
        {'H', 'e', 'l', 'l', 'o', ' ', 'W', 'o', 'r', 'l', 'd', '!'},
        {'V', 'e', 'r', 'y', ' ', 'N', 'i', 'c', 'e', ' ', 'T', 'o', ' ', 'M', 'e', 'e', 't', ' ', 'Y', 'o', 'u'},
        {'I', ' ', 'D', 'o', 'm', 'i', 'n', 'a', 't', 'e', ' ', 'T', 'h', 'i', 's', ' ', 'G', 'a', 'm', 'e'}
    };

    GridReader reader(initialGrid);

    std::string word1 = reader.extract(1, 8, Orientation::Horizontal, 4);  // "Nice"
    std::string word2 = reader.extract(1, 0, Orientation::Horizontal, 4);  // "Very"
    std::string word3 = reader.extract(0, 6, Orientation::Vertical, 6);    // "World!"
    std::string word4 = reader.extract(0, 13, Orientation::Vertical, 10);  // "I Dominate"

    std::cout << "Word 1: " << word1 << std::endl;
    std::cout << "Word 2: " << word2 << std::endl;
    std::cout << "Word 3: " << word3 << std::endl;
    std::cout << "Word 4: " << word4 << std::endl;

    return 0;
}

