// Serialize a string using cereal's binary archive
std::string serializeData(const std::string& data) {
#if defined ENABLE_BOOST_IOSTREAMS && !defined DISABLE_BOOST_IOSTREAMS
    // Alternative implementation using Boost.IOStreams
    std::string result;
    boost::iostreams::back_insert_device<std::string> device(result);
    boost::iostreams::stream<boost::iostreams::back_insert_device<std::string>> stream(device);
    {
        cereal::BinaryOutputArchive archive(stream);
        archive(data);
    }
    stream.flush();
    return result;
#else
    // Fallback to standard C++ stringstream-based serialization
    std::ostringstream buffer;
    {
        cereal::BinaryOutputArchive archive(buffer);
        archive(data);
    }
    return buffer.str();
#endif
}

