// Custom memory manager class for tracking allocations
class MemoryManager {
private:
    std::map<void*, size_t> allocatedBlocks; // Stores pointer-to-size mappings

public:
    // Allocate raw memory and record its size
    void* requestMemory(size_t bytes) {
        void* address = new char[bytes];
        allocatedBlocks[address] = bytes;
        return address;
    }

    // Release previously allocated memory block
    void releaseMemory(void* address) {
        auto it = allocatedBlocks.find(address);
        if (it != allocatedBlocks.end()) {
            delete[] static_cast<char*>(address);
            allocatedBlocks.erase(it);
        }
    }

    // Template method to allocate single object
    template<typename T>
    T* createInstance() {
        return new T();
    }

    // Template method to destroy single object
    template<typename T>
    void destroyInstance(T* obj) {
        delete obj;
    }

    // Cleanup all remaining tracked allocations on destruction
    ~MemoryManager() {
        for (const auto& block : allocatedBlocks) {
            delete[] static_cast<char*>(block.first);
        }
        allocatedBlocks.clear();
    }
};

int main() {
    MemoryManager memHandler;

    // Request memory for a class_A instance
    class_A* instanceA = static_cast<class_A*>(memHandler.requestMemory(sizeof(class_A)));

    // Create a standalone class_A pointer
    class_A* ptrToA = memHandler.createInstance<class_A>();

    // Request memory for a struct_S instance
    struct_S* instanceS = static_cast<struct_S*>(memHandler.requestMemory(sizeof(struct_S)));

    // Create a standalone struct_S pointer
    struct_S* ptrToS = memHandler.createInstance<struct_S>();

    // Clean up all allocated resources
    memHandler.releaseMemory(instanceA);
    memHandler.destroyInstance(ptrToA);
    memHandler.releaseMemory(instanceS);
    memHandler.destroyInstance(ptrToS);

    return 0;
}

