#include <set>

class Solution {
public:
    int smallestRepunitDivByK(int K) {
        // Early termination: numbers with only digit 1 are never divisible by 2 or 5
        if (K % 2 == 0 || K % 5 == 0) {
            return -1;
        }

        int currentRemainder = 0;
        int digitsCount = 0;

        // Continue until we find remainder 0 or exceed K digits (pigeonhole principle)
        while (digitsCount < K) {
            digitsCount++;
            currentRemainder = (currentRemainder * 10 + 1) % K;

            if (currentRemainder == 0) {
                return digitsCount;
            }
        }

        return -1;
    }
};

#include <vector>

// Function to render lights into camera constant buffers
void RenderLights(const std::vector<LightData>& lights, std::vector<CameraConstantBuffer>& cameraBuffers)
{
    // Iterate through each light using index-based loop for clarity
    for (size_t idx = 0; idx < lights.size(); ++idx)
    {
        const LightData& currentLight = lights[idx];

        if (currentLight.m_lightType == ELightType::Directional)
        {
            // For directional lights, only one view-projection matrix is needed
            CameraConstantBuffer buffer;
            buffer.m_viewProjection = currentLight.m_viewProjection;
            cameraBuffers.push_back(buffer);
        }
        else if (currentLight.m_lightType == ELightType::Point)
        {
            // Point lights require rendering in 6 directions (cubemap faces)
            const int faceCount = 6;
            Vector3 origin = currentLight.m_position;

            // Define the six primary directions for point light cubemap sampling
            Vector3 directions[faceCount] = {
                Vector3(1.0f, 0.0f, 0.0f),   // +X
                Vector3(-1.0f, 0.0f, 0.0f),  // -X
                Vector3(0.0f, 1.0f, 0.0f),   // +Y
                Vector3(0.0f, -1.0f, 0.0f),  // -Y
                Vector3(0.0f, 0.0f, 1.0f),   // +Z
                Vector3(0.0f, 0.0f, -1.0f)   // -Z
            };

            Vector3 upAxis(0.0f, 1.0f, 0.0f);  // Fixed up vector for all views

            // Generate view-projection matrices for each cubemap face
            for (int faceIdx = 0; faceIdx < faceCount; ++faceIdx)
            {
                CameraConstantBuffer buffer;

                // Compute view matrix: look from light position toward direction
                Vector3 target = origin + directions[faceIdx];
                Matrix view = CreateLookAtMatrix(origin, target, upAxis);

                // Compute projection matrix with 90-degree FOV for cubemap face
                Matrix proj = CreatePerspectiveMatrix(90.0f, 1.0f, 0.1f, 100.0f);

                buffer.m_viewProjection = view * proj;
                cameraBuffers.push_back(buffer);
            }
        }
    }
}

