// Function to validate and modify attribute definitions
void processAttributeDefinitions(smtk::attribute::DefinitionPtr targetDef, smtk::attribute::DefinitionPtr sourceDef) {
    // Ensure both definitions are valid (non-null)
    if (targetDef && sourceDef) {
        // Attempt to retrieve the "Expression String" item from targetDef
        smtk::attribute::StringItemDefinitionPtr exprItem = targetDef->itemDefinition("Expression String");

        // If not found, create and add it
        if (!exprItem) {
            exprItem = smtk::attribute::StringItemDefinition::New("Expression String");
            targetDef->addItemDefinition(exprItem);
        }

        // Look for "Base String" in sourceDef
        smtk::attribute::StringItemDefinitionPtr baseItem = sourceDef->itemDefinition("Base String");

        // If found, remove it from sourceDef
        if (baseItem) {
            sourceDef->removeItemDefinition(baseItem);
        }
    }
}

