namespace intern {
    // Helper to perform recursive transformation and reduction
    template <typename T, std::size_t N, std::size_t I>
    struct TransformReduceImpl {
        static constexpr auto apply(const std::array<T, N>& a,
                                   const std::array<T, N>& b,
                                   auto&& op_transform,
                                   auto&& op_reduce) {
            return op_reduce(op_transform(a[I], b[I]),
                           TransformReduceImpl<T, N, I - 1>::apply(a, b, op_transform, op_reduce));
        }
    };

    // Base case: when index reaches 0
    template <typename T, std::size_t N>
    struct TransformReduceImpl<T, N, 0> {
        static constexpr auto apply(const std::array<T, N>& a,
                                   const std::array<T, N>& b,
                                   auto&& op_transform,
                                   auto&& op_reduce) {
            return op_reduce(op_transform(a[0], b[0]), T{});
        }
    };
} // namespace intern

// Public interface for compile-time array transform-reduce operation
template <typename T, std::size_t N, typename Transformer, typename Reducer>
constexpr auto transform_reduce(const std::array<T, N>& lhs,
                                const std::array<T, N>& rhs,
                                Transformer&& transformer,
                                Reducer&& reducer) 
    -> decltype(std::forward<Transformer>(transformer)(lhs[0], rhs[0])) {
    static_assert(N > 0, "Array size must be at least 1");

    return intern::TransformReduceImpl<T, N, N - 1>::apply(
        lhs, rhs, 
        std::forward<Transformer>(transformer),
        std::forward<Reducer>(reducer)
    );
}

