// Helper class to manage identifiers with thread-safe operations
class IdentifierManager {
private:
    std::mutex* pMutex;
    std::string identifier;

public:
    IdentifierManager(std::mutex* mtx) : pMutex(mtx), identifier("") {}

    void addIdentifier(const std::string& id) {
        std::lock_guard<std::mutex> lock(*pMutex);
        identifier = id;
    }

    void removeIdentifier(const std::string&) {
        std::lock_guard<std::mutex> lock(*pMutex);
        identifier.clear();
    }

    bool isIdentifierExists(const std::string&) const {
        std::lock_guard<std::mutex> lock(*pMutex);
        return !identifier.empty();
    }
};

int main() {
    std::mutex mtx;
    IdentifierManager manager(&mtx);

    // Launch three threads to perform concurrent operations
    std::thread t1([&manager]() {
        manager.addIdentifier("ID1");
    });

    std::thread t2([&manager]() {
        manager.removeIdentifier("ID1");
    });

    std::thread t3([&manager]() {
        bool exists = manager.isIdentifierExists("ID1");
        std::cout << "ID1 exists: " << std::boolalpha << exists << std::endl;
    });

    // Ensure all threads complete before exiting
    t1.join();
    t2.join();
    t3.join();

    return 0;
}

