#include <boost/safe_float/convenience.hpp>
#include <boost/safe_float/policy/check_addition_overflow.hpp>
#include <boost/safe_float/policy/check_addition_underflow.hpp>
#include <boost/safe_float/policy/check_addition_inexact.hpp>
#include <boost/safe_float/policy/check_addition_invalid_result.hpp>

// Wrapper for safe floating-point operations
template <typename FloatingPointType>
class FloatingPointGuard {
public:
    using SafeType = boost::safe_float::safe_float<FloatingPointType>;

    explicit FloatingPointGuard(FloatingPointType val) : stored_value_(val) {}

    // Perform addition with specified policies
    template<typename... Policies>
    SafeType perform_operation(const SafeType& operand, Policies&&... policies) {
        return boost::safe_float::add(stored_value_, operand, std::forward<Policies>(policies)...);
    }

    // Display error status information
    void display_diagnostics(const SafeType& result) const {
        const auto& err = result.error();
        std::cout << "Overflow detected: " << err.overflow() << std::endl;
        std::cout << "Underflow detected: " << err.underflow() << std::endl;
        std::cout << "Inexact result: " << err.inexact() << std::endl;
        std::cout << "Invalid operation: " << err.invalid_result() << std::endl;
    }

private:
    SafeType stored_value_;
};

int main() {
    // Initialize safe floating-point values
    FloatingPointGuard<float> guard_a(1.0f);
    FloatingPointGuard<float> guard_b(2.0f);

    // First operation: check overflow and inexact conditions
    auto calculation_1 = guard_a.perform_operation(
        guard_b.stored_value_,
        boost::safe_float::policy::check_addition_overflow{},
        boost::safe_float::policy::check_addition_inexact{}
    );
    guard_a.display_diagnostics(calculation_1);

    // Second operation: check underflow and invalid result conditions
    auto calculation_2 = guard_a.perform_operation(
        guard_b.stored_value_,
        boost::safe_float::policy::check_addition_underflow{},
        boost::safe_float::policy::check_addition_invalid_result{}
    );
    guard_a.display_diagnostics(calculation_2);

    return 0;
}

