class CustomNetworkInterface : public NetworkInterface {
private:
    std::string m_identifier;
    std::string m_type;
    connection_state m_state;
    data_rate m_rate;
    transmission_mode m_mode;

public:
    CustomNetworkInterface(const std::string& id, const std::string& kind, 
                           connection_state state, data_rate rate, transmission_mode mode)
        : m_identifier(id), m_type(kind), m_state(state), m_rate(rate), m_mode(mode) {}

    std::string identifier() const override { return m_identifier; }
    std::string type_name() const override { return m_type; }
    connection_state state() const override { return m_state; }
    data_rate rate() const override { return m_rate; }
    transmission_mode mode() const override { return m_mode; }

