            case data_rate::giga:
                std::cout << "1 Gbps";
                break;
            case data_rate::ten_gig:
                std::cout << "10 Gbps";
                break;
        }
        std::cout << std::endl;
        std::cout << "Mode: " << (m_mode == transmission_mode::simplex ? "half" : "full") << std::endl;
