// Convert FILETIME to 64-bit unsigned integer
ULONGLONG convertFileTimeToULL(const FILETIME& ft) {
    ULONGLONG high = static_cast<ULONGLONG>(ft.dwHighDateTime);
    ULONGLONG low = static_cast<ULONGLONG>(ft.dwLowDateTime);
    return (high << 32) | low;
}

// Global map to store system performance metrics
std::map<std::string, double> systemMetrics;

// Function to compute CPU utilization and populate the metrics map
void updateCPUStatistics(const FILETIME& currentIdle, const FILETIME& currentKernel,
                         const FILETIME& currentUser, const FILETIME& prevIdle,
                         const FILETIME& prevKernel, const FILETIME& prevUser) {
    systemMetrics.clear(); // Reset the metrics container

    // Compute time deltas
    ULONGLONG idleDelta = convertFileTimeToULL(currentIdle) - convertFileTimeToULL(prevIdle);
    ULONGLONG kernelDelta = convertFileTimeToULL(currentKernel) - convertFileTimeToULL(prevKernel);
    ULONGLONG userDelta = convertFileTimeToULL(currentUser) - convertFileTimeToULL(prevUser);

    // Calculate total active time and total time
    ULONGLONG activeTime = kernelDelta + userDelta;
    ULONGLONG totalTime = activeTime + idleDelta;

    // Avoid division by zero
    double cpuPercentage = 0.0;
    if (totalTime > 0) {
        cpuPercentage = 100.0 * static_cast<double>(activeTime) / static_cast<double>(totalTime);
    }

    // Store result in the global map
    systemMetrics["CPU Usage"] = cpuPercentage;
}

