    if (!client) {
        return false; // client pointer is null
    }
    if (!payloadCount) {
        return false; // payloadCount pointer is null
    }

    // Interpret the input buffer as a structured parameter block
    pg_param_decode_params* params = reinterpret_cast<pg_param_decode_params*>(pData);

    // Extract values from the parameter structure into output arguments
    *client = params->client;
    *payloadCount = params->payloadCount;

    // Allocate memory for payloads and copy them
    *payloads = new ia_binary_data[params->payloadCount];
    for (int i = 0; i < params->payloadCount; ++i) {
        (*payloads)[i] = params->payloads[i];
    }

    // Update internal stats handle reference in the decoded structure
    params->clientStatsHandle = statsHandle;

    return true;
}

