// Helper function to determine direction between two points (8-connected)
int DetermineDirection(const PointType& fromPoint, const PointType& toPoint)
{
  // Compute displacement components
  double dx = toPoint[0] - fromPoint[0];
  double dy = toPoint[1] - fromPoint[1];

  // Normalize to integer grid directions for 8-connectivity
  int idX = (dx > 0) ? 1 : ((dx < 0) ? -1 : 0);
  int idY = (dy > 0) ? 1 : ((dy < 0) ? -1 : 0);

  // Map (idX, idY) to standard 8-direction code:
  // 0: (1,0), 1: (1,1), 2: (0,1), 3: (-1,1), 
  // 4: (-1,0), 5: (-1,-1), 6: (0,-1), 7: (1,-1)
  if (idX == 0 && idY == 0) return -1; // No movement

  // Use lookup table or direct mapping
  static const int dirMap[3][3] = {
    {5, 6, 7},   // idX = -1
    {4, -1, 0},  // idX =  0
    {3, 2, 1}    // idX = +1
  };

  return dirMap[idX + 1][idY + 1];
}

template <typename TInputPath, typename TOutputChainCodePath>
void PathToChainCodePathFilter<TInputPath, TOutputChainCodePath>::GenerateData()
{
  if (nullptr == this->GetInput())
  {
    itkExceptionMacro("Input path is null");
    return;
  }

  auto* inputPath = this->GetInput();
  auto* outputChainCodePath = this->GetOutput();

  // Early exit if insufficient points
  const size_t pointCount = inputPath->GetNumberOfPoints();
  if (pointCount < 2)
  {
    return; // Nothing to encode
  }

  // Process consecutive point pairs using index-based iteration
  for (size_t idx = 0; idx < pointCount - 1; ++idx)
  {
    PointType startPoint = inputPath->GetPoint(idx);
    PointType endPoint   = inputPath->GetPoint(idx + 1);

    int encodedDir = DetermineDirection(startPoint, endPoint);
    if (encodedDir >= 0)
    {
      outputChainCodePath->AppendDirection(encodedDir);
    }
  }
}

