#define INCLUDE_BA_LOG_DETAIL_EXCEPTION_TRANSLATOR_HPP
#include <exception>
#include <functional>
#include <unordered_map>

class ExceptionTranslator {
public:
    template <typename Callable>
    void handle(Callable&& action) {
        try {
            std::forward<Callable>(action)();
        } catch (const std::exception& e) {
            auto key = typeid(e).name();
            auto iter = translationTable.find(key);
            if (iter != translationTable.end()) {
                throw iter->second();
            } else {
                throw;
            }
        }
    }

    template <typename Source, typename Target>
    void registerMapping() {
        translationTable[typeid(Source).name()] = []() -> std::exception {
            return Target{};
        };
    }

private:
    std::unordered_map<std::string, std::function<std::exception()>> translationTable;
};

#define CATCH_AND_TRANSLATE(translator, codeBlock) \
    translator.handle([&]() { codeBlock; })

