// Helper to find the index of a type T in a sequence seq<Ts...>
template<typename T, template <typename...> class seq, typename... Ts>
struct TypeIndex;

// Base case: empty sequence - type not found
template<typename T, template <typename...> class seq>
struct TypeIndex<T, seq<>> : std::integral_constant<std::size_t, std::numeric_limits<std::size_t>::max()> {};

// Recursive case: check first element
template<typename T, template <typename...> class seq, typename First, typename... Rest>
struct TypeIndex<T, seq<First, Rest...>> {
    static constexpr std::size_t value = 
        std::is_same_v<T, First> ? 0 : 
        (TypeIndex<T, seq<Rest...>>::value == std::numeric_limits<std::size_t>::max() 
         ? std::numeric_limits<std::size_t>::max() 
         : TypeIndex<T, seq<Rest...>>::value + 1);
};

// Alias for convenience
template<typename T, template <typename...> class seq, typename... Ts>
using TypeIndex_t = typename TypeIndex<T, seq<Ts...>>::value_type;

// Check if type T is contained in the sequence seq<Ts...>
template<typename T, template <typename...> class seq, typename... Ts>
struct Contains : std::bool_constant<!std::is_same_v<TypeIndex<T, seq<Ts...>>, 
                                                      std::integral_constant<std::size_t, std::numeric_limits<std::size_t>::max()>>> {};

