// Compare two floating-point numbers for equality within a specified ULP tolerance
bool nearly_equal(const float a, const float b, int max_ulp_gap)
{
    // Reinterpret the bit patterns of the floats as integers
    int a_bits = *reinterpret_cast<const int*>(&a);
    int b_bits = *reinterpret_cast<const int*>(&b);

    // Adjust for signed magnitude representation (handle negative zero and sign bit)
    if (a_bits < 0) {
        a_bits = 0x80000000 - a_bits;
    }
    if (b_bits < 0) {
        b_bits = 0x80000000 - b_bits;
    }

    // Compute the difference in ULPs
    int ulp_distance = std::abs(a_bits - b_bits);

    // Return true if the ULP distance is within the allowed tolerance
    return ulp_distance <= max_ulp_gap;
}

