// Simulate a class method that lists directory contents with error handling
TInt64 CliTask::command_lsahci(TInt ac, char **av) {
  // Validate argument count: must have exactly one argument after command name
  if (ac != 2) {
    Error("lsahci expects exactly one argument");
    return -1;
  }

  // Extract the directory path from the command-line arguments
  std::string targetPath = av[1];

  // Check if the path exists and is a directory
  if (!std::filesystem::exists(targetPath)) {
    Error("Directory does not exist");
    return -1;
  }

  if (!std::filesystem::is_directory(targetPath)) {
    Error("Specified path is not a directory");
    return -1;
  }

  // Output header for directory listing
  mWindow->WriteFormatted("Contents of directory '%s':\n", targetPath.c_str());

  // Iterate through directory entries using an explicit iterator instead of range-based loop
  std::filesystem::directory_iterator iter(targetPath);
  std::filesystem::directory_iterator endIter;

  while (iter != endIter) {
    const auto& item = *iter;
    mWindow->WriteFormatted("%s\n", item.path().filename().string().c_str());
    ++iter;
  }

  return 0;  // Indicate successful completion
}

