#include <thread>
#include <iostream>
#include <gtest/gtest.h>

class OrderedPrinter {
public:
    OrderedPrinter() : nextExpected(1) {}

    void executeFirst() {
        printValue(1);
    }

    void executeSecond() {
        printValue(2);
    }

    void executeThird() {
        printValue(3);
    }

private:
    int nextExpected;
    std::mutex mtx;
    std::condition_variable condVar;

    void printValue(int val) {
        std::unique_lock<std::mutex> guard(mtx);
        condVar.wait(guard, [this, val] { return nextExpected == val; });

        std::cout << val;
        nextExpected++;

        condVar.notify_all();
    }
};

TEST(OrderedPrinterTest, SequentialOutput) {
    OrderedPrinter printer;

    std::thread worker1(&OrderedPrinter::executeFirst, &printer);
    std::thread worker2(&OrderedPrinter::executeSecond, &printer);
    std::thread worker3(&OrderedPrinter::executeThird, &printer);

    worker1.join();
    worker2.join();
    worker3.join();

    std::string captured = testing::internal::GetCapturedStdout();
    ASSERT_EQ(captured, "123");
}

int main(int argc, char** argv) {
    testing::InitGoogleTest(&argc, argv);
    return RUN_ALL_TESTS();
}

#include <iostream>
#include <thread>
#include <vector>
#include <functional>
#include <mutex>
#include <condition_variable>

class TaskExecutor {
public:
    TaskExecutor() : completedCount(0) {}

    void addTask(const std::function<void()>& task) {
        std::unique_lock<std::mutex> lock(taskMutex);
        pendingTasks.push_back(task);
    }

    void runAll() {
        std::vector<std::thread> workerThreads;

        // Capture current size to avoid issues with dynamic changes
        size_t taskCount = pendingTasks.size();

        for (size_t index = 0; index < taskCount; ++index) {
            workerThreads.emplace_back([this, index] {
                // Lock only when accessing shared resources
                {
                    std::unique_lock<std::mutex> lock(taskMutex);
                    if (index < pendingTasks.size()) {
                        pendingTasks[index]();
                    }
                }

                // Update counter safely after task execution
                {
                    std::unique_lock<std::mutex> lock(resultMutex);
                    ++completedCount;
                }

                // Notify any waiting threads
                resultCV.notify_one();
            });
        }

        // Wait for all threads to complete
        for (auto& thread : workerThreads) {
            thread.join();
        }
    }

    int getCompletedCount() const {
        return completedCount;
    }

private:
    std::vector<std::function<void()>> pendingTasks;
    mutable std::mutex taskMutex;
    mutable std::mutex resultMutex;
    std::condition_variable resultCV;
    int completedCount;
};

int main() {
    TaskExecutor executor;

    // Add tasks to be executed
    executor.addTask([] { std::cout << "First task completed" << std::endl; });
    executor.addTask([] { std::cout << "Second task completed" << std::endl; });
    executor.addTask([] { std::cout << "Third task completed" << std::endl; });

    // Execute all scheduled tasks
    executor.runAll();

    // Display the total number of completed tasks
    std::cout << "Number of finished tasks: " << executor.getCompletedCount() << std::endl;

    return 0;
}

#include <QObject>
#include <QThread>
#include <QVector>
#include <complex>
#include <fftw3.h>

class FFTProcessor : public QObject {
    Q_OBJECT
public:
    explicit FFTProcessor(int size) : m_size(size) {
        m_inputData.resize(size);
        m_outputData.resize(size);
        // Setup FFTW plan with specified length and flags
        m_plan = fftw_plan_dft_1d(size, 
                                  reinterpret_cast<fftw_complex*>(m_inputData.data()),
                                  reinterpret_cast<fftw_complex*>(m_outputData.data()), 
                                  FFTW_FORWARD, FFTW_MEASURE);
    }

    ~FFTProcessor() {
        if (m_plan) {
            fftw_destroy_plan(m_plan);
        }
    }

public slots:
    void handleSignal(const QVector<double>& signal) {
        // Transfer incoming data to internal buffer
        std::copy(signal.begin(), signal.end(), m_inputData.begin());

        // Prepare worker thread for computation
        m_workerThread = new QThread();
        moveToThread(m_workerThread);

        // Connect signals for proper lifecycle management
        connect(m_workerThread, &QThread::started, this, &FFTProcessor::executeTransform);
        connect(this, &FFTProcessor::processingDone, m_workerThread, &QThread::quit);
        connect(this, &FFTProcessor::processingDone, this, &FFTProcessor::cleanup);
        connect(m_workerThread, &QThread::finished, m_workerThread, &QThread::deleteLater);

        // Start the processing thread
        m_workerThread->start();
    }

signals:
    void processingDone(const QVector<std::complex<double>>& output);

private:
    int m_size;
    QVector<double> m_inputData;
    QVector<std::complex<double>> m_outputData;
    fftw_plan m_plan = nullptr;
    QThread* m_workerThread = nullptr;

    void executeTransform() {
        // Run actual FFT computation
        fftw_execute(m_plan);

        // Convert raw FFTW output to Qt-compatible format
        QVector<std::complex<double>> convertedOutput(m_size);
        for (int idx = 0; idx < m_size; ++idx) {
            convertedOutput[idx] = std::complex<double>(
                m_outputData[idx].real(), 
                m_outputData[idx].imag()
            );
        }

        // Notify completion with result
        emit processingDone(convertedOutput);
    }

    void cleanup() {
        deleteLater();
    }
};

