#include <iostream>
#include <stack>
using namespace std;

class MinStack {
private:
    stack<int> dataStack;
    stack<int> minTracker;
public:
    void insert(int value) {
        // Push the new value onto the main stack
        dataStack.push(value);

        // Update the minimum tracking stack if needed
        if (minTracker.empty() || value <= minTracker.top()) {
            minTracker.push(value);
        }
    }

    void remove() {
        // Remove from the main stack
        if (!dataStack.empty()) {
            // If the top element is the current minimum, also remove from min tracker
            if (dataStack.top() == minTracker.top()) {
                minTracker.pop();
            }
            dataStack.pop();
        }
    }

    int peek() {
        return dataStack.top();
    }

    bool isEmpty() {
        return dataStack.empty();
    }

    int findMin() {
        return minTracker.top();
    }
};

