#include <iostream>
#include <vector>
#include <queue>
using namespace std;

const int MAX_NODES = 1005; // Maximum number of vertices

int adjMatrix[MAX_NODES][MAX_NODES]; // Adjacency matrix for the graph
int inDegree[MAX_NODES];             // In-degree count for each vertex
int numVertices;                     // Total number of vertices in the graph

// Perform topological sort using Kahn's algorithm
int performTopologicalSort() {
    vector<int> topoOrder; // Resulting topological sequence
    queue<int> zeroQueue;  // Queue for vertices with zero in-degree

    // Initialize: enqueue all vertices with zero in-degree
    for (int i = 0; i < numVertices; ++i) {
        if (inDegree[i] == 0) {
            zeroQueue.push(i);
        }
    }

    // Process vertices in BFS manner
    while (!zeroQueue.empty()) {
        int current = zeroQueue.front();
        zeroQueue.pop();
        topoOrder.push_back(current);

        // Check all possible neighbors
        for (int neighbor = 0; neighbor < numVertices; ++neighbor) {
            if (adjMatrix[current][neighbor] != 0) {
                inDegree[neighbor]--; // Remove edge effect

                if (inDegree[neighbor] == 0) {
                    zeroQueue.push(neighbor);
                }
            }
        }
    }

    // If not all vertices are included, there's a cycle
    if (topoOrder.size() != static_cast<size_t>(numVertices)) {
        return -1;
    } else {
        return static_cast<int>(topoOrder.size());
    }
}

int main() {
    // Input graph and in-degrees would be read here
    // ...

    int result = performTopologicalSort();

    if (result == -1) {
        cout << "Impossible\n";
    } else {
        cout << result << '\n';
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

const int MAX_SIZE = 100005;
vector<pair<int, int>> intervals[MAX_SIZE];
int left_vals[MAX_SIZE], right_vals[MAX_SIZE], fenwick_tree[MAX_SIZE];

// Sort intervals by their first element (left endpoint)
void organizeIntervals(vector<pair<int, int>>& data) {
    sort(data.begin(), data.end());
}

// Query maximum value in Fenwick tree up to index x
int queryMax(int idx) {
    int result = 0;
    while (idx > 0) {
        result = max(result, fenwick_tree[idx]);
        idx -= idx & -idx;
    }
    return result;
}

// Update Fenwick tree at position idx with value
void updateTree(int idx, int value) {
    while (idx < MAX_SIZE) {
        fenwick_tree[idx] = max(fenwick_tree[idx], value);
        idx += idx & -idx;
    }
}

int main() {
    // Example input processing: populate intervals with sample data
    // In practice, this would read from standard input
    vector<pair<int, int>> temp = {{1, 3}, {2, 5}, {4, 6}};
    for (auto& p : temp) {
        intervals[p.first].push_back(p);
    }

    // Process each interval using coordinate compression concept
    int max_value = 0;
    for (int i = 1; i < MAX_SIZE; ++i) {
        if (!intervals[i].empty()) {
            organizeIntervals(intervals[i]);
            for (auto& interval : intervals[i]) {
                int l = interval.first;
                int r = interval.second;
                int current = queryMax(l) + 1;
                max_value = max(max_value, current);
                updateTree(r, current);
            }
        }
    }

    cout << max_value << '\n';
    return 0;
}

