// Compute HPCP (Harmonic Pitch Class Profile) from frequencies and magnitudes
std::vector<double> computeHPCP(const std::vector<double>& freqs, const std::vector<double>& mags) {
    std::vector<double> result(12, 0.0);  // Create HPCP vector initialized to zero

    for (size_t idx = 0; idx < freqs.size(); ++idx) {
        double freq = freqs[idx];
        double mag = mags[idx];

        // Compute pitch class using A4=440Hz reference and rounding
        double semitoneOffset = 12.0 * std::log2(freq / 440.0);
        int pcIndex = static_cast<int>(semitoneOffset + 0.5) % 12;
        if (pcIndex < 0) pcIndex += 12;  // Handle negative indices

        result[pcIndex] += mag;
    }

    return result;
}

