// Helper function to extract comparison key from element
static inline int GetSortKey(const _E& elem) {
    // Extract the numeric value used for sorting from the element
    // Assumes _E contains a public member 'value'
    return elem.value;
}

// Lexicographical less-than comparison for two elements
static inline bool IsLessThan(const _E& first, const _E& second) {
    return GetSortKey(first) < GetSortKey(second);
}

// Compare two arrays of elements lexicographically
static inline int CompareArrays(const _E* arr1, const _E* arr2, std::size_t count) {
    for (std::size_t idx = 0; idx < count; ++idx) {
        if (IsLessThan(arr1[idx], arr2[idx])) {
            return -1;  // First array is lexicographically smaller
        } else if (IsLessThan(arr2[idx], arr1[idx])) {
            return 1;   // First array is lexicographically larger
        }
    }
    return 0;  // Arrays are equal in all positions
}

