// Perform element-wise multiplication with broadcasting support
Eigen::MatrixXd performElementwiseProduct(const Eigen::MatrixXd& matrix1, const Eigen::MatrixXd& matrix2) {
    // Check if matrices have identical dimensions
    if (matrix1.rows() == matrix2.rows() && matrix1.cols() == matrix2.cols()) {
        return matrix1.cwiseProduct(matrix2);
    }

    // Check if first matrix is a row vector that can be broadcast to second matrix
    if (matrix1.rows() == 1 && matrix1.cols() == matrix2.cols()) {
        Eigen::RowVectorXd rowVec = matrix1.row(0);
        return matrix2.array().rowwise() * rowVec.array();
    }

    // Check if second matrix is a row vector that can be broadcast to first matrix
    if (matrix2.rows() == 1 && matrix1.cols() == matrix2.cols()) {
        Eigen::RowVectorXd rowVec = matrix2.row(0);
        return matrix1.array().rowwise() * rowVec.array();
    }

    // Throw exception for incompatible dimensions
    throw std::invalid_argument("Matrix dimensions are incompatible for element-wise multiplication");
}

