int main() {
    std::ifstream file_stream("input.txt");
    if (!file_stream) {
        std::cerr << "Input file not found" << std::endl;
        return 1;
    }

    std::vector<int> numbers;
    std::string current_line;

    while (std::getline(file_stream, current_line)) {
        size_t pos = 0;
        std::string token;

        while ((pos = current_line.find(' ')) != std::string::npos || 
               (pos = current_line.find('\t')) != std::string::npos || 
               !current_line.empty()) {

            // Extract number part before delimiter or end of string
            size_t end_pos = current_line.find_first_of(" \t", pos);
            if (end_pos == std::string::npos) {
                token = current_line.substr(pos);
                current_line.clear();
            } else {
                token = current_line.substr(pos, end_pos - pos);
                current_line.erase(0, end_pos + 1);
            }

            if (token.empty()) continue;

            char* end_ptr = nullptr;
            long val = std::strtol(token.c_str(), &end_ptr, 10);

            if (*end_ptr != '\0' || token.empty()) {
                std::cerr << "Invalid input format" << std::endl;
                return 1;
            }

            numbers.push_back(static_cast<int>(val));
        }
    }

    file_stream.close();

    std::ofstream result_file("output.txt");
    if (!result_file) {
        std::cerr << "Failed to open output file" << std::endl;
        return 1;
    }

    for (size_t i = 0; i < numbers.size(); ++i) {
        int squared = numbers[i] * numbers[i];
        result_file << squared << "\n";
    }

    result_file.close();
    return 0;
}

