class Complex {
private:
    double realPart;
    double imagPart;

public:
    // Constructor with initialization list
    Complex(double r, double i) : realPart(r), imagPart(i) {}

    // Accessor methods
    double getReal() const { return realPart; }
    double getImag() const { return imagPart; }

    // Overloaded addition operator
    Complex operator+(const Complex& rhs) const {
        return Complex(realPart + rhs.realPart, imagPart + rhs.imagPart);
    }

    // Overloaded subtraction operator
    Complex operator-(const Complex& rhs) const {
        return Complex(realPart - rhs.realPart, imagPart - rhs.imagPart);
    }

    // Overloaded multiplication operator
    Complex operator*(const Complex& rhs) const {
        double newReal = realPart * rhs.realPart - imagPart * rhs.imagPart;
        double newImag = realPart * rhs.imagPart + imagPart * rhs.realPart;
        return Complex(newReal, newImag);
    }

    // Compute complex conjugate
    Complex conjugate() const {
        return Complex(realPart, -imagPart);
    }
};

