#include <vector>

template <typename T>
class binary_indexed_tree {
  std::vector<T> dat;
  static constexpr T NEUTRAL = T{};
  T combine(T left, T right) const { return left + right; }

public:
  binary_indexed_tree(size_t size) : dat(size + 1, NEUTRAL) {}

  binary_indexed_tree(size_t size, T value) : dat(size + 1, NEUTRAL) {
    for (size_t position = 0; position < size; ++position) {
      modify(position, value);
    }
  }

  void modify(int index, T value) {
    int position = index + 1;
    for (; position < dat.size(); position += position & -position) {
      dat[position] = combine(dat[position], value);
    }
  }

  T prefix_sum(int index) const {
    T result = NEUTRAL;
    for (int position = index + 1; position > 0; position -= position & -position) {
      result = combine(result, dat[position]);
    }
    return result;
  }
};

