// Generate OpenGL texture setup code for a 3D texture
std::string createOpenGL3DTextureConfiguration(int wrapMode, int minFilterMode, int magFilterMode, int format, int dimension) {
    std::stringstream shaderCode;

    // Set texture wrapping parameters for the R coordinate
    shaderCode << "glTexParameteri(GL_TEXTURE_3D, GL_TEXTURE_WRAP_R, " << wrapMode << ");\n";

    // Configure minification filter
    shaderCode << "glTexParameteri(GL_TEXTURE_3D, GL_TEXTURE_MIN_FILTER, " << minFilterMode << ");\n";

    // Configure magnification filter
    shaderCode << "glTexParameteri(GL_TEXTURE_3D, GL_TEXTURE_MAG_FILTER, " << magFilterMode << ");\n";

    // Define 3D texture storage with 7 mipmap levels
    shaderCode << "glTexStorage3D(GL_TEXTURE_3D, 7, " << format << ", " << dimension << ", " << dimension << ", " << dimension << ");\n";

    return shaderCode.str();
}

