// Custom binary tree implementation with implicit conversion to unsigned int
class BinarySearchTree {
private:
    struct TreeNode {
        int data;
        TreeNode* leftChild;
        TreeNode* rightChild;

        TreeNode(int val) : data(val), leftChild(nullptr), rightChild(nullptr) {}
    };

    TreeNode* rootNode;

    // Recursive helper to build tree from array representation
    TreeNode* buildTreeFromVector(const std::vector<int>& elements, int position) {
        if (position < static_cast<int>(elements.size())) {
            TreeNode* current = new TreeNode(elements[position]);
            current->leftChild = buildTreeFromVector(elements, 2 * position + 1);
            current->rightChild = buildTreeFromVector(elements, 2 * position + 2);
            return current;
        }
        return nullptr;
    }

public:
    // Public interface to initialize the tree structure
    void initializeTree(const std::vector<int>& inputValues) {
        rootNode = buildTreeFromVector(inputValues, 0);
    }

    // Conversion operator to extract root node's value as unsigned integer
    operator unsigned int() const {
        return static_cast<unsigned int>(rootNode->data);
    }
};

int main() {
    BinarySearchTree bst;
    bst.initializeTree({1, 2, 3, 4, 5, 6, 7});
    unsigned int rootData = bst; // Automatic type conversion occurs here
    std::cout << "Root element: " << rootData << std::endl;
    return 0;
}

