#include <iostream>
#include <cmath>

class ComplexNumber {
private:
    double realPart;
    double imaginaryPart;

public:
    // Default constructor
    ComplexNumber() : realPart(0.0), imaginaryPart(0.0) {}

    // Parameterized constructor
    ComplexNumber(double r, double i) : realPart(r), imaginaryPart(i) {}

    // Overloaded addition operator
    ComplexNumber add(const ComplexNumber& other) const {
        return ComplexNumber(realPart + other.realPart, imaginaryPart + other.imaginaryPart);
    }

    // Overloaded subtraction operator
    ComplexNumber subtract(const ComplexNumber& other) const {
        return ComplexNumber(realPart - other.realPart, imaginaryPart - other.imaginaryPart);
    }

    // Overloaded multiplication operator
    ComplexNumber multiply(const ComplexNumber& other) const {
        double newReal = realPart * other.realPart - imaginaryPart * other.imaginaryPart;
        double newImag = realPart * other.imaginaryPart + imaginaryPart * other.realPart;
        return ComplexNumber(newReal, newImag);
    }

    // Overloaded division operator
    ComplexNumber divide(const ComplexNumber& other) const {
        double denom = other.realPart * other.realPart + other.imaginaryPart * other.imaginaryPart;
        if (denom == 0.0) {
            return ComplexNumber(0.0, 0.0); // Avoid division by zero
        }
        double newReal = (realPart * other.realPart + imaginaryPart * other.imaginaryPart) / denom;
        double newImag = (imaginaryPart * other.realPart - realPart * other.imaginaryPart) / denom;
        return ComplexNumber(newReal, newImag);
    }

    // Friend function for output stream
    friend std::ostream& operator<<(std::ostream& os, const ComplexNumber& num) {
        char sign = num.imaginaryPart >= 0 ? '+' : '-';
        os << num.realPart << " " << sign << " " << std::abs(num.imaginaryPart) << "i";
        return os;
    }

    // Method to compute magnitude
    double getMagnitude() const {
        return std::sqrt(realPart * realPart + imaginaryPart * imaginaryPart);
    }
};

int main() {
    ComplexNumber z1;
    ComplexNumber z2(8.0, 0.0);
    ComplexNumber z3(0.0, -4.0);
    ComplexNumber z4(29.99, 88.44);

    std::cout << "Complex number z1: " << z1 << std::endl;
    std::cout << "Complex number z2: " << z2 << std::endl;
    std::cout << "Complex number z3: " << z3 << std::endl;
    std::cout << "Complex number z4: " << z4 << std::endl;

    ComplexNumber sumResult = z2.add(z3);
    ComplexNumber diffResult = z2.subtract(z3);
    ComplexNumber prodResult = z2.multiply(z3);
    ComplexNumber quotResult = z2.divide(z3);

    std::cout << "Sum of z2 and z3: " << sumResult << std::endl;
    std::cout << "Difference of z2 and z3: " << diffResult << std::endl;
    std::cout << "Product of z2 and z3: " << prodResult << std::endl;
    std::cout << "Quotient of z2 and z3: " << quotResult << std::endl;
    std::cout << "Magnitude of z2: " << z2.getMagnitude() << std::endl;

