#include <vector>
#include <string>
using namespace std;

class Solution {
private:
    void explore(vector<string>& results, const string& digits, int goal, string& currentExpression, 
                 long long prevOperand, long long currentVal, int index) {
        // Base case: reached end of the digit string
        if (index == digits.length()) {
            if (currentVal == goal) {
                results.push_back(currentExpression);
            }
            return;
        }

        // Try all possible numbers starting from current position
        for (int j = index; j < digits.length(); ++j) {
            // Skip numbers with leading zeros (except single '0')
            if (j != index && digits[index] == '0') {
                break;
            }

            string numberStr = digits.substr(index, j - index + 1);
            long long number = stoll(numberStr);

            if (index == 0) {
                // First number in expression - no operator before it
                currentExpression += numberStr;
                explore(results, digits, goal, currentExpression, number, number, j + 1);
                // Backtrack: remove added characters
                currentExpression.erase(currentExpression.length() - numberStr.length());
            } else {
                // Try addition
                currentExpression += "+" + numberStr;
                explore(results, digits, goal, currentExpression, number, currentVal + number, j + 1);
                currentExpression.erase(currentExpression.length() - (numberStr.length() + 1));

                // Try subtraction
                currentExpression += "-" + numberStr;
                explore(results, digits, goal, currentExpression, -number, currentVal - number, j + 1);
                currentExpression.erase(currentExpression.length() - (numberStr.length() + 1));

                // Try multiplication
                currentExpression += "*" + numberStr;
                // Adjust for precedence: subtract previous operand and add (prev * curr)
                long long newCurrent = currentVal - prevOperand + (prevOperand * number);
                explore(results, digits, goal, currentExpression, prevOperand * number, newCurrent, j + 1);
                currentExpression.erase(currentExpression.length() - (numberStr.length() + 1));
            }
        }
    }

public:
    vector<string> addOperators(string num, int target) {
        vector<string> solutions;
        string expression;

        // Start with each possible first number
        for (int i = 0; i < num.length(); ++i) {
            // Skip numbers with leading zeros (except single '0')
            if (i != 0 && num[0] == '0') {
                break;
            }

            string firstNumStr = num.substr(0, i + 1);
            long long firstNum = stoll(firstNumStr);

            expression = firstNumStr;
            explore(solutions, num, target, expression, firstNum, firstNum, i + 1);
        }

        return solutions;
    }
};

