#include <climits>

class Graph {
private:
    struct Node {
        std::vector<std::pair<Node*, int>> edges;
    };
    std::vector<Node*> nodes;

public:
    void insert_node() {
        nodes.push_back(new Node());
    }

    void connect(Node* source, Node* destination, int cost) {
        source->edges.emplace_back(destination, cost);
    }

    int minimum_cost(Node* start, Node* end) {
        // Implementation of Dijkstra's algorithm for shortest path
        std::vector<int> distances(nodes.size(), INT_MAX);
        distances[start - &nodes[0]] = 0;
        std::vector<bool> processed(nodes.size(), false);

        for (size_t count = 0; count < nodes.size(); ++count) {
            int min_index = -1;
            for (size_t idx = 0; idx < nodes.size(); ++idx) {
                if (!processed[idx] && (min_index == -1 || distances[idx] < distances[min_index])) {
                    min_index = idx;
                }
            }

            if (min_index == -1) break;

            processed[min_index] = true;
            Node* current = nodes[min_index];

            for (const auto& edge : current->edges) {
                Node* neighbor = edge.first;
                int weight = edge.second;
                int neighbor_index = neighbor - &nodes[0];

                if (!processed[neighbor_index] && 
                    distances[min_index] != INT_MAX && 
                    distances[min_index] + weight < distances[neighbor_index]) {
                    distances[neighbor_index] = distances[min_index] + weight;
                }
            }
        }

        return distances[end - &nodes[0]];
    }
};

int main() {
    Graph network;
    network.insert_node(); // First node
    network.insert_node(); // Second node

    // Create directed connection with weight
    network.connect(network.nodes[0], network.nodes[1], 5);

    // Output the minimum cost path
    std::cout << "Minimum weight from first to second node: " 
              << network.minimum_cost(network.nodes[0], network.nodes[1]) << std::endl;

    return 0;
}

