#include <vector>
#include <stack>

// Helper function to perform DFS-based topological sorting
void Graph::performTopoSort(int vertex, std::vector<bool>& isVisited, std::stack<int>& resultStack) {
    // Mark the current vertex as visited
    isVisited[vertex] = true;

    // Traverse all adjacent vertices
    for (int neighbor : adj[vertex]) {
        if (!isVisited[neighbor]) {
            performTopoSort(neighbor, isVisited, resultStack);
        }
    }

    // Add current vertex to the stack after visiting all descendants
    resultStack.push(vertex);
}

std::vector<int> Graph::topologicalSort() {
    std::stack<int> tempStack;
    std::vector<bool> visited(V, false);  // Initialize all vertices as unvisited

    // Process each unvisited vertex
    for (int i = 0; i < V; ++i) {
        if (!visited[i]) {
            performTopoSort(i, visited, tempStack);
        }
    }

    // Build the final topological order from the stack
    std::vector<int> topoOrder;
    while (!tempStack.empty()) {
        topoOrder.push_back(tempStack.top());
        tempStack.pop();
    }

    return topoOrder;
}

