// Enum to represent various statistics counters
enum class StatsCounter {
    error_msgs_sent__,
    unexpected_rx_msgs__,
    secure_tx_msgs__,
    total_stats__  // Total count of tracked statistics
};

class OutstationStats {
public:
    // Retrieve the current value of a specific statistic
    int fetchStat(StatsCounter stat) {
        switch (stat) {
            case StatsCounter::error_msgs_sent__:
                return errCount;
            case StatsCounter::unexpected_rx_msgs__:
                return unexpCount;
            case StatsCounter::secure_tx_msgs__:
                return secCount;
            case StatsCounter::total_stats__:
                return static_cast<int>(StatsCounter::total_stats__);
        }
        return -1; // Fallback for invalid cases
    }

    // Check if there's an APDU ready to be processed
    bool checkAPDU() {
        return pendingAPDU;
    }

private:
    int errCount = 0;
    int unexpCount = 0;
    int secCount = 0;
    bool pendingAPDU = false;
};

// Unit test function for OutstationStats
void validateOutstationStats() {
    OutstationStats stats;

    // Verify initial values of all statistics
    assert(stats.fetchStat(StatsCounter::error_msgs_sent__) == 0);
    assert(stats.fetchStat(StatsCounter::unexpected_rx_msgs__) == 0);
    assert(stats.fetchStat(StatsCounter::secure_tx_msgs__) == 0);
    assert(stats.fetchStat(StatsCounter::total_stats__) == 3);  // Confirm correct count

    // Verify no pending APDU initially
    assert(!stats.checkAPDU());
}

int main() {
    validateOutstationStats();
    std::cout << "All validation checks passed successfully." << std::endl;
    return 0;
}

