void memcpy(void* dest, const void* src, std::int64_t size);

template <typename T>
inline void copy(T* dest, const T* src, std::int64_t count) {
    // Validate input parameters for safety
    if (count < 0) {
        throw std::invalid_argument("Copy count cannot be negative");
    }

    constexpr auto type_size = static_cast<std::int64_t>(sizeof(T));
    if (type_size == 0) {
        throw std::runtime_error("Invalid type size for copy operation");
    }

    // Compute total bytes and check for overflow
    std::int64_t total_bytes = type_size * count;
    if (total_bytes < 0 || total_bytes / type_size != count) {
        throw std::overflow_error("Buffer overflow detected during memory copy");
    }

    // Perform the actual copy
    ONEDAL_ASSERT_MUL_OVERFLOW(std::int64_t, type_size, count);
    memcpy(dest, src, total_bytes);
}

