// Compute the average of scores after removing the lowest and highest values
int calculateAverage(std::vector<int> scores) {
    // Handle cases with insufficient data points
    if (scores.size() <= 2) {
        return 0;
    }

    // Sort the scores in ascending order
    std::sort(scores.begin(), scores.end());

    // Manually compute the sum of middle elements (excluding min and max)
    int total = 0;
    for (size_t i = 1; i < scores.size() - 1; ++i) {
        total += scores[i];
    }

    // Compute average using integer division with rounding
    int count = static_cast<int>(scores.size()) - 2;
    double avg = static_cast<double>(total) / count;
    int result = static_cast<int>(std::round(avg));

    return result;
}

