#include <cmath>

// Define a small constant to prevent division by zero
const float MIN_DIVISOR = 0.0001f;

// Calculate the sphere thickness at a given point after transformation
float calculateSphereThickness(const float transformMatrix[16], const float pointCoords[3], float thicknessParam) {
    // Isolate the translation part from the transformation matrix and add point coordinates
    const float dx = transformMatrix[12] + pointCoords[0];
    const float dy = transformMatrix[13] + pointCoords[1];
    const float dz = transformMatrix[14] + pointCoords[2];

    // Compute squared distance with minimum divisor for numerical stability
    const float distanceSquared = dx * dx + dy * dy + dz * dz;

    // Return thickness scaled by inverse squared distance
    return thicknessParam / (distanceSquared + MIN_DIVISOR);
}

#include <vector>
#include <stdexcept>

std::vector<double> computeEdgeScores(const Graph& G, 
                                      const std::vector<double>& attr0, 
                                      const std::vector<double>& attr1, 
                                      const std::vector<bool>& mask) {
    // Verify that edge IDs have been properly assigned
    if (!G.hasEdgeIds()) {
        throw std::runtime_error("edge indexing required - invoke indexEdges before scoring");
    }

    // Prepare result container with appropriate size
    std::vector<double> result;
    result.reserve(G.upperEdgeIdBound());

    // Initialize all scores to zero first
    result.assign(G.upperEdgeIdBound(), 0.0);

    // Process each edge to determine its score
    for (edgeid i = 0; i < static_cast<edgeid>(result.size()); ++i) {
        // Select the appropriate attribute value based on the mask condition
        result[i] = mask[i] ? attr1[i] : attr0[i];
    }

    return result;
}

