// Forward declarations
class File;
class Directory;

// Visitor interface for traversing file system elements
class PathVisitor {
public:
    virtual ~PathVisitor() = default;
    virtual void handleFile(const File& file) = 0;
    virtual void handleDirectory(const Directory& directory) = 0;
};

// Base class representing a file
class File {
private:
    std::string name;
public:
    explicit File(const std::string& n = "unnamed_file") : name(n) {}

    const std::string& getName() const {
        return name;
    }

    void accept(PathVisitor* visitor) const {
        visitor->handleFile(*this);
    }
};

// Class representing a directory containing files and subdirectories
class Directory {
private:
    std::vector<File> files;
    std::vector<Directory> subDirectories;
    std::string dirName;
public:
    explicit Directory(const std::string& name = "unnamed_dir") : dirName(name) {}

    const std::string& getName() const {
        return dirName;
    }

    void accept(PathVisitor* visitor) const {
        visitor->handleDirectory(*this);

        // Process all files in this directory
        for (const auto& file : files) {
            file.accept(visitor);
        }

        // Recursively process all subdirectories
        for (const auto& subdir : subDirectories) {
            subdir.accept(visitor);
        }
    }

    void appendFile(const File& file) {
        files.push_back(file);
    }

    void appendSubdirectory(const Directory& directory) {
        subDirectories.push_back(directory);
    }
};

// Concrete visitor that lists all files and directories
class ListVisitor : public PathVisitor {
public:
    void handleFile(const File& file) override {
        std::cout << "File: " << file.getName() << std::endl;
    }

    void handleDirectory(const Directory& directory) override {
        std::cout << "Directory: " << directory.getName() << std::endl;
    }
};

// Concrete visitor that searches for a specific file or directory by name
class SearchVisitor : public PathVisitor {
private:
    std::string searchTerm;
    bool matchFound = false;

public:
    explicit SearchVisitor(const std::string& name) : searchTerm(name) {}

    void handleFile(const File& file) override {
        if (file.getName() == searchTerm) {
            std::cout << "File found: " << searchTerm << std::endl;
            matchFound = true;
        }
    }

    void handleDirectory(const Directory& directory) override {
        if (directory.getName() == searchTerm) {
            std::cout << "Directory found: " << searchTerm << std::endl;
            matchFound = true;
        }
    }

    bool wasSuccessful() const {
        return matchFound;
    }
};

int main() {
    // Create the file system structure
    Directory root("root");
    File textFile("document.txt"), imageFile("photo.jpg");
    Directory configDir("config");

    // Build the hierarchy
    root.appendFile(textFile);
    root.appendFile(imageFile);
    root.appendSubdirectory(configDir);

    // Use the list visitor to display contents
    ListVisitor lister;
    root.accept(&lister);

    // Use the search visitor to find an item
    SearchVisitor finder("photo.jpg");
    root.accept(&finder);

    if (!finder.wasSuccessful()) {
        std::cout << "Item not found" << std::endl;
    }

    return 0;
}

