// Weight-balanced binary search tree implementation
template <typename T>
class BalancedBST {
private:
  struct TreeNode {
    T data;
    int subtreeSize;
    TreeNode* leftChild;
    TreeNode* rightChild;

    TreeNode(T val) 
      : data(val), subtreeSize(1), leftChild(nullptr), rightChild(nullptr) {}
  };

  TreeNode* rootPtr;

  // Helper to get current subtree size
  int getSize(TreeNode* node) const {
    return node ? node->subtreeSize : 0;
  }

  // Update subtree size based on children
  void updateSize(TreeNode* node) {
    if (node) {
      node->subtreeSize = getSize(node->leftChild) + getSize(node->rightChild) + 1;
    }
  }

  // In-order traversal to collect elements
  void traverseInOrder(TreeNode* node, std::vector<T>& storage) const {
    if (!node) return;
    traverseInOrder(node->leftChild, storage);
    storage.push_back(node->data);
    traverseInOrder(node->rightChild, storage);
  }

  // Build balanced BST from sorted array
  TreeNode* constructBalanced(const std::vector<T>& sortedData, int left, int right) {
    if (left >= right) return nullptr;

    int center = (left + right) / 2;
    TreeNode* newNode = new TreeNode(sortedData[center]);
    newNode->leftChild = constructBalanced(sortedData, left, center);
    newNode->rightChild = constructBalanced(sortedData, center + 1, right);
    updateSize(newNode);
    return newNode;
  }

  // Rebuild tree when balance factor is violated
  void restoreBalance(TreeNode*& node) {
    if (!node) return;

    int leftSubtree = getSize(node->leftChild);
    int rightSubtree = getSize(node->rightChild);

    // Check if balance factor exceeds threshold (3:1 ratio)
    if (leftSubtree > 3 * rightSubtree || rightSubtree > 3 * leftSubtree) {
      std::vector<T> collectedValues;
      traverseInOrder(node, collectedValues);
      delete node;
      node = constructBalanced(collectedValues, 0, collectedValues.size());
    } else {
      updateSize(node);
    }
  }

  // Insert value into tree
  void insertValue(TreeNode*& node, const T& newValue) {
    if (!node) {
      node = new TreeNode(newValue);
    } else if (newValue < node->data) {
      insertValue(node->leftChild, newValue);
    } else {
      insertValue(node->rightChild, newValue);
    }
    restoreBalance(node);
  }

  // Find minimum value node in subtree
  TreeNode* locateMinimum(TreeNode* node) {
    while (node && node->leftChild) {
      node = node->leftChild;
    }
    return node;
  }

  // Delete value from tree
  void eraseValue(TreeNode*& node, const T& targetValue) {
    if (!node) return;

    if (targetValue < node->data) {
      eraseValue(node->leftChild, targetValue);
    } else if (targetValue > node->data) {
      eraseValue(node->rightChild, targetValue);
    } else {
      // Node found - handle deletion cases
      if (!node->leftChild) {
        TreeNode* temp = node->rightChild;
        delete node;
        node = temp;
      } else if (!node->rightChild) {
        TreeNode* temp = node->leftChild;
        delete node;
        node = temp;
      } else {
        // Two children case - find inorder successor
        TreeNode* successor = locateMinimum(node->rightChild);
        node->data = successor->data;
        eraseValue(node->rightChild, successor->data);
      }
    }
    restoreBalance(node);
  }

  // Calculate sum of values within range [minBound, maxBound]
  T rangeSumQuery(TreeNode* node, const T& minBound, const T& maxBound) const {
    if (!node) return T();

    if (node->data < minBound) {
      return rangeSumQuery(node->rightChild, minBound, maxBound);
    } else if (node->data > maxBound) {
      return rangeSumQuery(node->leftChild, minBound, maxBound);
    } else {
      return node->data + 
             rangeSumQuery(node->leftChild, minBound, node->data) +
             rangeSumQuery(node->rightChild, node->data, maxBound);
    }
  }

public:
  BalancedBST() : rootPtr(nullptr) {}

  ~BalancedBST() {
    clearTree(rootPtr);
  }

  void insert(const T& value) {
    insertValue(rootPtr, value);
  }

  void remove(const T& value) {
    eraseValue(rootPtr, value);
  }

  int countElements() const {
    return getSize(rootPtr);
  }

  T calculateRangeSum(const T& lower, const T& upper) const {
    return rangeSumQuery(rootPtr, lower, upper);
  }

private:
  void clearTree(TreeNode* node) {
    if (!node) return;
    clearTree(node->leftChild);
    clearTree(node->rightChild);
    delete node;
  }
};

int main() {
  BalancedBST<int> bst;

  // Insert sample values
  bst.insert(5);
  bst.insert(3);
  bst.insert(7);
  bst.insert(2);
  bst.insert(4);
  bst.insert(6);
  bst.insert(8);

  std::cout << "Total nodes in tree: " << bst.countElements() << std::endl;
  std::cout << "Sum in range [3, 7]: " << bst.calculateRangeSum(3, 7) << std::endl;

  // Remove a node and check results
  bst.remove(5);
  std::cout << "Nodes after removing 5: " << bst.countElements() << std::endl;

  return 0;
}

