void updateSentMessages(const std::string& reply, int messageCount, ClientConnection& clientRef, Server* serverPtr) {
    int adjustedCount = messageCount;

    // Check if reply lacks trailing CRLF and adjust count accordingly
    if (reply.empty() || reply.back() != '\n' || 
        (reply.length() > 1 && reply[reply.length() - 2] != '\r')) {
        adjustedCount--;
    }

    clientRef.sentmsgs += adjustedCount;

    // Update server's tracking if socket descriptor is valid
    if (clientRef.sock > 0 && serverPtr != nullptr) {
        serverPtr->fds[clientRef.sock].sentmsgs += adjustedCount;
    }
}

