// Generate assembly jump instruction based on condition type
void Asm_x64::build_jmp(LtacNode *node) {
    auto jmp = static_cast<LtacJmp *>(node);

    // Map operator types to their corresponding assembly jump codes
    const char* jump_codes[] = {
        "\tjmp ",   // None - unconditional jump
        "\tje ",    // Equal - jump if equal
        "\tjne ",   // NotEqual - jump if not equal
        "\tjg ",    // Greater - jump if greater
        "\tjl ",    // Less - jump if less
        "\tjge ",   // GreaterEq - jump if greater or equal
        "\tjle "    // LessEq - jump if less or equal
    };

    // Determine index based on operator value and output corresponding code
    int op_index = static_cast<int>(jmp->op);
    if (op_index >= 0 && op_index < 7) {
        writer << jump_codes[op_index];
    }
}

