#include <vector>
#include <tuple>

std::tuple<int, int, int> getHighestResolutionMode(const std::vector<std::tuple<int, int, int>>& videoModes) {
    // Start with the first available mode as our candidate
    auto bestMode = videoModes.front();

    // Iterate through all modes to find the optimal one
    for (size_t idx = 1; idx < videoModes.size(); ++idx) {
        const auto& currentMode = videoModes[idx];

        // Extract dimensions for easier comparison
        int currWidth = std::get<0>(currentMode);
        int currHeight = std::get<1>(currentMode);
        int currRefresh = std::get<2>(currentMode);

        int bestWidth = std::get<0>(bestMode);
        int bestHeight = std::get<1>(bestMode);
        int bestRefresh = std::get<2>(bestMode);

        // Determine if current mode is better than the best found so far
        bool shouldUpdate = false;

        // Priority: width > height > refresh rate
        if (currWidth > bestWidth) {
            shouldUpdate = true;
        } else if (currWidth == bestWidth) {
            if (currHeight > bestHeight) {
                shouldUpdate = true;
            } else if (currHeight == bestHeight) {
                if (currRefresh > bestRefresh) {
                    shouldUpdate = true;
                }
            }
        }

        if (shouldUpdate) {
            bestMode = currentMode;
        }
    }

    return bestMode;
}

