#include <opencv2/opencv.hpp>
#include <cstring>

void SMExtractRGBI(IplImage* inputImage, CvMat* &R, CvMat* &G, CvMat* &B, CvMat* &I)
{
    // Convert input image to OpenCV Mat
    cv::Mat inputMat(inputImage);

    // Split the input image into its BGR components (OpenCV default order)
    std::vector<cv::Mat> bgrChannels;
    cv::split(inputMat, bgrChannels);

    // Convert channels to floating point format
    cv::Mat B_float, G_float, R_float;
    bgrChannels[0].convertTo(B_float, CV_32F);
    bgrChannels[1].convertTo(G_float, CV_32F);
    bgrChannels[2].convertTo(R_float, CV_32F);

    // Calculate intensity (I) as the average of RGB channels
    cv::Mat I_float = (R_float + G_float + B_float) * (1.0f / 3.0f);

    // Allocate memory for output matrices
    R = cvCreateMat(inputImage->height, inputImage->width, CV_32FC1);
    G = cvCreateMat(inputImage->height, inputImage->width, CV_32FC1);
    B = cvCreateMat(inputImage->height, inputImage->width, CV_32FC1);
    I = cvCreateMat(inputImage->height, inputImage->width, CV_32FC1);

    // Copy data from OpenCV Mat to CvMat using proper size calculation
    size_t bytesCount = inputMat.total() * sizeof(float);
    std::memcpy(R->data.fl, R_float.data, bytesCount);
    std::memcpy(G->data.fl, G_float.data, bytesCount);
    std::memcpy(B->data.fl, B_float.data, bytesCount);
    std::memcpy(I->data.fl, I_float.data, bytesCount);
}

