// Inventory management system with item tracking
class Warehouse {
private:
    std::map<int, std::pair<std::string, std::pair<int, double>>> stock; // Stores items by ID: name -> (quantity, price)
public:
    void addProduct(int productId, const std::string& productName, int count, double unitCost) {
        auto it = stock.find(productId);
        if (it != stock.end()) {
            it->second.first += count; // Increase existing item's quantity
        } else {
            stock[productId] = std::make_pair(productName, std::make_pair(count, unitCost));
        }
    }

    void subtractProduct(int productId, int amount) {
        auto it = stock.find(productId);
        if (it != stock.end()) {
            if (it->second.first <= amount) {
                stock.erase(it); // Remove item completely if insufficient stock
            } else {
                it->second.first -= amount; // Decrease quantity
            }
        }
    }

    void showStock() {
        std::cout << "Current Stock:\n";
        for (const auto& entry : stock) {
            std::cout << "ID: " << entry.first 
                      << ", Product: " << entry.second.first 
                      << ", Units: " << entry.second.second.first 
                      << ", Cost: $" << entry.second.second.second << "\n";
        }
    }
};

int main() {
    Warehouse warehouse;
    warehouse.addProduct(1, "Shirt", 50, 25.99);
    warehouse.addProduct(2, "Pants", 30, 39.99);
    warehouse.addProduct(1, "Shirt", 20, 25.99); // Add more shirts to existing stock
    warehouse.showStock();
    warehouse.subtractProduct(1, 30); // Sell 30 shirts
    warehouse.showStock();
    return 0;
}

