// Extract parts of a SQL-like query string
void extractQueryInfo(const std::string& sql) {
    std::string colList, tblName, whereClause;
    std::istringstream stream(sql);
    std::string token1, token2, token3;

    // Read tokens in order: SELECT, columns, FROM, table, WHERE, conditions
    stream >> token1 >> colList >> token2 >> tblName >> token3 >> whereClause;

    // Clean up trailing comma from column list if present
    if (!colList.empty() && colList.back() == ',') {
        colList.pop_back();
    }

    // Output parsed components
    std::cout << "Table: " << tblName << std::endl;
    std::cout << "Columns:" << std::endl;

    // Split and print each column individually
    std::istringstream colStream(colList);
    std::string col;
    while (std::getline(colStream, col, ',')) {
        std::cout << col << std::endl;
    }

    std::cout << "Conditions: " << whereClause << std::endl;
}

int main() {
    std::string input = "SELECT doctor_id FROM visits WHERE LENGTH(patient_name) > 11";
    extractQueryInfo(input);
    return 0;
}

