template<typename SrcPort, typename DstPort>
class Path {
    std::vector<std::pair<SrcPort, DstPort>> _path;
public:
    // Check if the path contains any repeated connections
    bool hasCycle() const {
        std::set<std::pair<SrcPort, DstPort>> visited;

        for (size_t idx = 0; idx < _path.size(); ++idx) {
            const auto& connection = _path[idx];

            if (visited.find(connection) != visited.end()) {
                return true;  // Duplicate entry indicates a cycle
            }

            visited.insert(connection);
        }

        return false;  // All entries are unique, no cycle detected
    }
};

