// Helper function to get size of OpenGL data types
int getTypeSize(int type) {
    switch (type) {
        case GL_FLOAT:
            return sizeof(GLfloat);
        case GL_INT:
            return sizeof(GLint);
        // Additional cases can be added for other types as needed
        default:
            throw std::invalid_argument("Unsupported data type");
    }
}

class VertexArray {
public:
    VertexArray(ag::span<VertexAttribute> attributes) {
        // Compute total byte stride by summing up individual attribute sizes
        int totalStride = 0;
        for (const auto& attr : attributes) {
            totalStride += attr.size * getTypeSize(attr.type);
        }

        // Create and bind the vertex array object
        glGenVertexArrays(1, &mVertexArrayID);
        glBindVertexArray(mVertexArrayID);

        // Setup each vertex attribute with correct offset and stride
        int currentOffset = 0;
        for (size_t index = 0; index < attributes.size(); ++index) {
            const auto& attr = attributes[index];
            glEnableVertexAttribArray(static_cast<GLuint>(index));
            glVertexAttribPointer(
                static_cast<GLuint>(index),
                attr.size,
                attr.type,
                GL_FALSE,
                totalStride,
                reinterpret_cast<void*>(currentOffset)
            );
            currentOffset += attr.size * getTypeSize(attr.type);
        }

        // Clean up binding state
        glBindVertexArray(0);
    }

private:
    GLuint mVertexArrayID;
};

