int main(int argc, char* argv[]) {
    if (argc != 3) {
        std::cerr << "Usage: ./proxy <path> <number>\n";
        return 1;
    }

    unsigned int nodeCount;
    if (sscanf(argv[2], "%u", &nodeCount) != 1 || nodeCount == 0) {
        std::cerr << "Invalid number format\n";
        return 1;
    }

    LocalNode** nodes = new LocalNode*[nodeCount];

    // Create communication pipe between parent and children
    int parentToChildPipe[2];
    if (pipe(parentToChildPipe) == -1) {
        perror("Failed to create pipe");
        return 1;
    }

    // Open input file
    int inputFile = open(argv[1], O_RDONLY);
    if (inputFile == -1) {
        perror("Failed to open file");
        return 1;
    }

    for (unsigned int i = 0; i < nodeCount; ++i) {
        int childToParentPipe[2];
        if (pipe(childToParentPipe) == -1) {
            perror("Failed to create pipe");
            return 1;
        }

        pid_t childPid = fork();
        if (childPid == -1) {
            perror("Fork failed");
            return 1;
        }

        if (childPid == 0) {  // Child process
            close(parentToChildPipe[1]);   // Close write end in child
            close(childToParentPipe[0]);   // Close read end in child

            // Read data from parent
            char dataBuffer[512];
            ssize_t bytesRead = read(parentToChildPipe[0], dataBuffer, sizeof(dataBuffer));

            if (bytesRead < 0) {
                perror("Child read error");
                _exit(1);
            }

            // Simulate processing (placeholder logic)
            // Process the received data independently

            close(parentToChildPipe[0]);
            _exit(0);
        } else {  // Parent process
            close(parentToChildPipe[0]);   // Close read end in parent
            close(childToParentPipe[1]);   // Close write end in parent

            // Read chunk from file
            char fileBuffer[512];
            ssize_t fileBytes = read(inputFile, fileBuffer, sizeof(fileBuffer));

            if (fileBytes < 0) {
                perror("File read error");
                return 1;
            }

            // Send data to child via pipe
            if (fileBytes > 0) {
                ssize_t written = write(parentToChildPipe[1], fileBuffer, fileBytes);
                if (written < 0) {
                    perror("Pipe write error");
                    return 1;
                }
            }

            close(parentToChildPipe[1]);   // Signal EOF to child
        }
    }

    close(inputFile);  // Close file descriptor in parent

    // Wait for all child processes to finish
    for (unsigned int j = 0; j < nodeCount; ++j) {
        wait(nullptr);
    }

    delete[] nodes;  // Clean up allocated memory
    return 0;
}

#include <unordered_set>

bool isInstanceIdUsable(int instance, std::unordered_set<int>* seen_instance_ids, bool* usable) {
  // Determine if the instance ID has been encountered before
  auto it = seen_instance_ids->find(instance);
  if (it != seen_instance_ids->end()) {
    // Instance ID was previously recorded, so it's not available
    *usable = false;
  } else {
    // New instance ID - record it and confirm availability
    seen_instance_ids->insert(instance);
    *usable = true;
  }
  return *usable;
}

