class StockSpanner {
    stack<int> prices;      // stores the stock prices
    stack<int> spans;       // stores the corresponding spans
public:
    StockSpanner() {

    }

    int next(int currentPrice) {
        int spanCount = 1;

        // While there are previous prices that are <= current price
        while (!prices.empty() && prices.top() <= currentPrice) {
            spanCount += spans.top();
            prices.pop();
            spans.pop();
        }

        prices.push(currentPrice);
        spans.push(spanCount);

        return spanCount;
    }
};

