#include <vulkan/vulkan.hpp>
#include <map>
#include <algorithm>

// Reorganize Vulkan image memory barriers by grouping them per image and sorting by subresource range
std::vector<vk::ImageMemoryBarrier> organizeImageMemoryBarriers(
    const std::vector<vk::ImageMemoryBarrier>& preBarriersInput,
    const std::vector<vk::ImageMemoryBarrier>& postBarriersInput) {

  std::map<vk::Image, std::vector<vk::ImageMemoryBarrier>> groupedBarriers;

  // Collect all barriers and group by image object
  for (const auto& barrier : preBarriersInput) {
    groupedBarriers[barrier.image].push_back(barrier);
  }
  for (const auto& barrier : postBarriersInput) {
    groupedBarriers[barrier.image].push_back(barrier);
  }

  std::vector<vk::ImageMemoryBarrier> result;

  // Process each image's barriers separately
  for (const auto& [imageHandle, barriers] : groupedBarriers) {
    std::vector<vk::ImageMemoryBarrier> writeBarriers;
    std::vector<vk::ImageMemoryBarrier> readBarriers;

    // Separate barriers based on access mask
    for (const auto& b : barriers) {
      if ((b.srcAccessMask & vk::AccessFlagBits::eMemoryWrite) != vk::AccessFlags{}) {
        writeBarriers.push_back(b);
      } else {
        readBarriers.push_back(b);
      }
    }

    // Sort write barriers by mip level then array layer
    std::sort(writeBarriers.begin(), writeBarriers.end(),
              [](const vk::ImageMemoryBarrier& a, const vk::ImageMemoryBarrier& b) {
                return std::tie(a.subresourceRange.baseMipLevel, a.subresourceRange.baseArrayLayer) <
                       std::tie(b.subresourceRange.baseMipLevel, b.subresourceRange.baseArrayLayer);
              });

    // Sort read barriers similarly
    std::sort(readBarriers.begin(), readBarriers.end(),
              [](const vk::ImageMemoryBarrier& a, const vk::ImageMemoryBarrier& b) {
                return std::tie(a.subresourceRange.baseMipLevel, a.subresourceRange.baseArrayLayer) <
                       std::tie(b.subresourceRange.baseMipLevel, b.subresourceRange.baseArrayLayer);
              });

    // Append in order: write barriers first, then read barriers
    result.insert(result.end(), writeBarriers.begin(), writeBarriers.end());
    result.insert(result.end(), readBarriers.begin(), readBarriers.end());
  }

  return result;
}

#include <iostream>

// Custom smart pointer implementation for demonstration
template<typename T>
class CustomSharedPtr {
private:
    T* ptr;
    int* refCount;

public:
    // Constructor
    explicit CustomSharedPtr(T* p) : ptr(p), refCount(new int(1)) {}

    // Copy constructor
    CustomSharedPtr(const CustomSharedPtr& other) : ptr(other.ptr), refCount(other.refCount) {
        if (refCount) {
            (*refCount)++;
        }
    }

    // Destructor
    ~CustomSharedPtr() {
        if (refCount) {
            (*refCount)--;
            if (*refCount == 0) {
                delete ptr;
                delete refCount;
            }
        }
    }

    // Dereference operator
    T& operator*() const { return *ptr; }

    // Member access operator
    T* operator->() const { return ptr; }

    // Assignment operator
    CustomSharedPtr& operator=(const CustomSharedPtr& other) {
        if (this != &other) {
            if (refCount) {
                (*refCount)--;
                if (*refCount == 0) {
                    delete ptr;
                    delete refCount;
                }
            }
            ptr = other.ptr;
            refCount = other.refCount;
            if (refCount) {
                (*refCount)++;
            }
        }
        return *this;
    }
};

int main() {
    // Create first shared pointer
    CustomSharedPtr<int> firstPtr(new int(5));

    // Create second shared pointer via copy - shares ownership
    CustomSharedPtr<int> secondPtr = firstPtr;

    // Print values through both pointers
    std::cout << *firstPtr << std::endl;   // Output: 5
    std::cout << *secondPtr << std::endl;  // Output: 5

    // Modify value through first pointer
    *firstPtr = 10;

    // Both pointers reflect the change since they share the same object
    std::cout << *firstPtr << std::endl;   // Output: 10
    std::cout << *secondPtr << std::endl;  // Output: 10

    return 0;  // Both destructors called, memory properly released
}

