    std::vector<std::vector<char>> levelMap;  // Renamed from mazeGrid to levelMap
    int playerCol, playerRow;  // Renamed coordinates: x->col, y->row for clarity

public:
    MazeGame() : levelMap(10, std::vector<char>(10, ' ')), 
                 playerCol(1), playerRow(1) {
        // Initialize the maze layout and starting position
        levelMap[3][3] = '#';  // Obstacle symbol changed from 'X' to '#'
        levelMap[8][8] = '$';  // Goal symbol changed from 'G' to '$'
    }

    void OnUserCreate() override {
        // Render initial state of the maze and player
        for (int r = 0; r < levelMap.size(); ++r) {
            for (int c = 0; c < levelMap[r].size(); ++c) {
                Draw(c, r, levelMap[r][c]);
            }
        }
        Draw(playerCol, playerRow, '@');  // Player symbol changed from 'P' to '@'
    }

    void OnUserUpdate(float fElapsedTime) override {
        // Handle directional input with updated boundary checks and obstacle detection
        if (GetKey(olc::Key::UP).bPressed && playerRow > 0 && levelMap[playerRow - 1][playerCol] != '#') {
            playerRow--;
        } else if (GetKey(olc::Key::DOWN).bPressed && playerRow < levelMap.size() - 1 && levelMap[playerRow + 1][playerCol] != '#') {
            playerRow++;
        } else if (GetKey(olc::Key::LEFT).bPressed && playerCol > 0 && levelMap[playerRow][playerCol - 1] != '#') {
            playerCol--;
        } else if (GetKey(olc::Key::RIGHT).bPressed && playerCol < levelMap[0].size() - 1 && levelMap[playerRow][playerCol + 1] != '#') {
            playerCol++;
        }

        // Check win condition using new goal symbol
        if (levelMap[playerRow][playerCol] == '$') {
            DrawString(20, 25, "Victory!", olc::WHITE);
            return;
        }

        // Check lose condition using new obstacle symbol
        if (levelMap[playerRow][playerCol] == '#') {
            DrawString(20, 25, "Defeat!", olc::WHITE);
            return;
        }

        // Redraw entire game state after movement
        for (int r = 0; r < levelMap.size(); ++r) {
            for (int c = 0; c < levelMap[r].size(); ++c) {
                Draw(c, r, levelMap[r][c]);
            }
        }
        Draw(playerCol, playerRow, '@');
    }
};

