#include <cstddef>

void calculateTimeDerivative(const Scalar& lapse,
                             const Tensor& extrinsic_curvature,
                             Tensor& dt_spatial_metric,
                             const Vector& shift,
                             const Tensor& deriv_spatial_metric,
                             const Tensor& spatial_metric,
                             const Tensor& deriv_shift) {
  // Determine the spatial dimension from the spatial metric
  const size_t dim = spatial_metric.dimension();

  // Iterate through all components of the symmetric tensor
  for (size_t i_idx = 0; i_idx < dim; ++i_idx) {
    for (size_t j_idx = 0; j_idx < dim; ++j_idx) {
      // Start with the main contribution from the lapse and extrinsic curvature
      double result = -2.0 * lapse * extrinsic_curvature.get(i_idx, j_idx);

      // Add contributions from the shift and spatial derivatives
      for (size_t k_idx = 0; k_idx < dim; ++k_idx) {
        result += shift.get(k_idx) * deriv_spatial_metric.get(k_idx, i_idx, j_idx);
        result += spatial_metric.get(k_idx, i_idx) * deriv_shift.get(j_idx, k_idx);
        result += spatial_metric.get(k_idx, j_idx) * deriv_shift.get(i_idx, k_idx);
      }

      // Store the computed result in the output tensor
      dt_spatial_metric.get(i_idx, j_idx) = result;
    }
  }
}

