#include <iostream>
#include <thread>
#include <atomic>
#include <vector>
#include <functional>

// A simplified thread pool-like manager using standard C++11 features
class TaskExecutor {
public:
    explicit TaskExecutor(size_t threadCount) : m_active(true), m_taskIndex(0) {
        // Create worker threads
        for (size_t i = 0; i < threadCount; ++i) {
            m_workers.emplace_back([this] {
                while (true) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(m_mutex);
                        m_condition.wait(lock, [this] {
                            return !m_tasks.empty() || !m_active.load();
                        });

                        if (!m_active.load() && m_tasks.empty()) {
                            break;
                        }

                        task = std::move(m_tasks.front());
                        m_tasks.pop();
                    }

                    if (task) {
                        task();
                    }
                }
            });
        }
    }

    void enqueueTask(const std::function<void()>& task) {
        {
            std::lock_guard<std::mutex> lock(m_mutex);
            m_tasks.push(task);
        }
        m_condition.notify_one();
    }

    void shutdown() {
        m_active.store(false);
        m_condition.notify_all();

        for (auto& worker : m_workers) {
            if (worker.joinable()) {
                worker.join();
            }
        }
    }

private:
    std::vector<std::thread> m_workers;
    std::queue<std::function<void()>> m_tasks;
    std::mutex m_mutex;
    std::condition_variable m_condition;
    std::atomic<bool> m_active;
    std::atomic<size_t> m_taskIndex;
};

// Example usage
int main() {
    TaskExecutor executor(4);  // Create an executor with 4 worker threads

    // Enqueue tasks to be executed by the worker threads
    for (int i = 0; i < 10; ++i) {
        int taskId = i;
        executor.enqueueTask([taskId]() {
            std::cout << "Task " << taskId 
                      << " executed by thread " 
                      << std::this_thread::get_id() << std::endl;
        });
    }

    // Gracefully shut down all workers
    executor.shutdown();

    return 0;
}

