class Curl {
private:
    CURL* curlHandle;
    std::string responseBuffer;

    // Callback function to write received data into the buffer
    static size_t writeCallback(char* ptr, size_t size, size_t nmemb, void* userdata) {
        if (ptr && userdata) {
            Curl* instance = static_cast<Curl*>(userdata);
            instance->responseBuffer.append(ptr, size * nmemb);
        }
        return size * nmemb;
    }

public:
    Curl() {
        curl_global_init(CURL_GLOBAL_DEFAULT);
        curlHandle = curl_easy_init();
        if (curlHandle) {
            // Set up the write callback to capture response
            curl_easy_setopt(curlHandle, CURLOPT_WRITEFUNCTION, &Curl::writeCallback);
            curl_easy_setopt(curlHandle, CURLOPT_WRITEDATA, this);
        }
    }

    ~Curl() {
        if (curlHandle) {
            curl_easy_cleanup(curlHandle);
        }
        curl_global_cleanup();
    }

    bool perform(const std::string& url) {
        if (!curlHandle) return false;

        // Reset buffer before new request
        responseBuffer.clear();

        // Set URL and perform request
        curl_easy_setopt(curlHandle, CURLOPT_URL, url.c_str());
        CURLcode res = curl_easy_perform(curlHandle);
        return (res == CURLE_OK);
    }

    void print() const {
        std::cout << responseBuffer << std::endl;
    }

    void getString(std::string& str) const {
        str = responseBuffer;
    }
};

#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>

class TaskManager {
public:
    TaskManager() : active(true) {}

    void beginProcessing() {
        workerThread = std::thread([this] { this->process(); });
    }

    void enqueueTask(void (*func)()) {
        std::lock_guard<std::mutex> guard(queueMutex);
        taskQueue.push(func);
        conditionVariable.notify_one();
    }

    void process() {
        while (active) {
            std::unique_lock<std::mutex> lock(queueMutex);
            conditionVariable.wait(lock, [this] { 
                return !taskQueue.empty() || !active; 
            });

            if (!taskQueue.empty()) {
                auto currentTask = taskQueue.front();
                taskQueue.pop();
                lock.unlock();  // Unlock before executing to avoid blocking other threads

                currentTask();  // Execute the task outside the critical section
            }
        }
    }

    ~TaskManager() {
        active = false;
        conditionVariable.notify_one();  // Wake up the worker thread for shutdown
        if (workerThread.joinable()) {
            workerThread.join();
        }
    }

private:
    std::queue<void (*)()> taskQueue;
    std::mutex queueMutex;
    std::condition_variable conditionVariable;
    std::thread workerThread;
    bool active;
};

void taskOne() {
    std::cout << "taskOne(): execution" << std::endl;
}

void taskTwo() {
    std::cout << "taskTwo(): execution" << std::endl;
