// Render graphics content based on drawing style
void RenderGraphics(int style, Image& img, Font* fnt, 
                   const IRectangle& region, const IRectangle& content,
                   const std::string& txt, const IPoint& pos, Color color) {
    // Determine what to render based on style flags
    bool shouldRenderImage = (style & (GDS_IMAGE | GDS_IMAGETEXT)) != 0;
    bool shouldRenderText = (style & (GDS_TEXT | GDS_IMAGETEXT)) != 0;

    // Render image component if needed
    if (shouldRenderImage) {
        img.Render();
    }

    // Render text component if needed
    if (shouldRenderText) {
        // Calculate effective drawing rectangle by combining regions
        IRectangle effectiveRect = region;
        effectiveRect += content;

        // Compute final text position
        int finalX = effectiveRect.X + pos.X;
        int finalY = effectiveRect.Y + pos.Y;

        fnt->Render(txt, finalX, finalY, color);
    }
}

