#include <iostream>
#include <vector>

struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

bool isValidBST(TreeNode* root) {
    std::vector<int> inorderValues;

    // Perform in-order traversal to collect all values
    TreeNode* current = root;
    std::vector<TreeNode*> stack;

    while (current != nullptr || !stack.empty()) {
        // Go to the leftmost node
        while (current != nullptr) {
            stack.push_back(current);
            current = current->left;
        }

        // Process current node
        current = stack.back();
        stack.pop_back();
        inorderValues.push_back(current->val);

        // Go to right subtree
        current = current->right;
    }

    // Check if the in-order traversal is strictly increasing
    for (size_t i = 1; i < inorderValues.size(); ++i) {
        if (inorderValues[i] <= inorderValues[i - 1]) {
            return false;
        }
    }

    return true;
}

