class Bullet {
private:
    // Member variables
    float pos_y;     // Vertical position of the bullet
    float speed_val; // Movement speed
    bool active;     // Tracks whether the bullet is currently active

public:
    // Constructor initializes member variables
    Bullet(float y = 0.0f, float spd = 1.0f) 
        : pos_y(y), speed_val(spd), active(true) {}

    // Methods to control bullet behavior
    void ascend();   // Move upward
    void descend();  // Move downward
    bool isActive() const;  // Check if bullet is active
    void activate(); // Reactivate bullet
    void deactivate(); // Deactivate bullet
};

// Implementation of Bullet class methods
void Bullet::activate() {
    active = true;
}

void Bullet::deactivate() {
    active = false;
}

bool Bullet::isActive() const {
    return active;
}

void Bullet::ascend() {
    // Move up only if within bounds and bullet is active
    if (pos_y < 150.0f && active) {
        pos_y += speed_val;
    }
}

void Bullet::descend() {
    // Move down only if within bounds and bullet is active
    if (pos_y > -725.0f && active) {
        pos_y -= speed_val;
    }
}

int main() {
    // Create a bullet instance and demonstrate its functionality
    Bullet testBullet(0.0f, 2.0f);

    // Test movement and state management
    testBullet.ascend();
    std::cout << "Bullet position after moving up: " << testBullet.pos_y << std::endl;

    testBullet.deactivate();
    testBullet.ascend(); // Should not move since inactive
    std::cout << "Bullet position after deactivating and attempting to move up: " << testBullet.pos_y << std::endl;

    testBullet.activate();
    testBullet.descend();
    std::cout << "Bullet position after reactivating and moving down: " << testBullet.pos_y << std::endl;

    return 0;
}

