namespace opencl
{
    template<typename T>
    void transpose_inplace(Array<T> &in, const bool conjugate)
    {
        dim4 iDims = in.dims();

        // Determine if both dimensions are multiples of TILE_DIM
        const bool aligned0 = (iDims[0] % kernel::TILE_DIM) == 0;
        const bool aligned1 = (iDims[1] % kernel::TILE_DIM) == 0;
        const bool bothAligned = aligned0 && aligned1;

        if(conjugate) {
            if(bothAligned)
                kernel::transpose_inplace<T, true, true>(in);
            else
                kernel::transpose_inplace<T, true, false>(in);
        } else {
            if(bothAligned)
                kernel::transpose_inplace<T, false, true>(in);
            else
                kernel::transpose_inplace<T, false, false>(in);
        }
    }
}

