// Abstract interface for event listeners
class Observer {
public:
    virtual void handleNotification(const string& message) = 0;
};

// Event publisher class
class Publisher {
private:
    vector<Observer*> observers;
public:
    void registerObserver(Observer* obs) {
        observers.push_back(obs);
    }

    void deregisterObserver(Observer* obs) {
        observers.erase(remove(observers.begin(), observers.end(), obs), observers.end());
    }

    void broadcast(const string& msg) {
        for (auto observer : observers) {
            observer->handleNotification(msg);
        }
    }
};

// Concrete implementation of an observer
class ConcreteObserver : public Observer {
public:
    void handleNotification(const string& message) override {
        cout << "Received: " << message << endl;
    }
};

int main() {
    Publisher pub;
    ConcreteObserver obsA, obsB;

    pub.registerObserver(&obsA);
    pub.registerObserver(&obsB);

    pub.broadcast("First Message");

    pub.deregisterObserver(&obsA);

    pub.broadcast("Second Message");

    return 0;
}

#include <algorithm>

void moveZerosToEnd(int arr[], int size) {
    int writeIndex = 0;

    // First pass: move all non-zero elements to the front
    for (int readIndex = 0; readIndex < size; ++readIndex) {
        if (arr[readIndex] != 0) {
            arr[writeIndex++] = arr[readIndex];
        }
    }

    // Second pass: fill remaining positions with zeros
    while (writeIndex < size) {
        arr[writeIndex++] = 0;
    }
}

#include <functional>
#include <iostream>

class Callback {
public:
    void AsStdFunction() {
        // Implementation not shown
    }
};

class Child {
private:
    std::function<void()>* callbacks;
    size_t capacity;
    size_t count;

public:
    Child() : callbacks(nullptr), capacity(0), count(0) {}

    ~Child() {
        delete[] callbacks;
    }

    Child& addOnDrainCloseCb(const std::function<void()>& callback) {
        if (count >= capacity) {
            size_t newCapacity = (capacity == 0) ? 4 : capacity * 2;
            std::function<void()>* newCallbacks = new std::function<void()>[newCapacity];
            for (size_t i = 0; i < count; ++i) {
                newCallbacks[i] = callbacks[i];
            }
            delete[] callbacks;
            callbacks = newCallbacks;
            capacity = newCapacity;
        }
        callbacks[count++] = callback;
        return *this;
    }

    void drainAndClose() {
        for (size_t i = 0; i < count; ++i) {
            callbacks[i]();
        }
        std::cout << "Child drained and closed" << std::endl;
    }
};

class Parent {
private:
    Child* childRef;
    std::function<void()> parentCallback;

public:
    Parent(Child* c) : childRef(c), parentCallback(nullptr) {}

    void startDrainSequence(const std::function<void()>& finalizer) {
        parentCallback = finalizer;
        childRef->drainAndClose();
        parentCallback();
    }
};

int main() {
    Child c;
    Parent p(&c);
    Callback cb;
    auto handle_c = c.addOnDrainCloseCb(cb.AsStdFunction());

    p.startDrainSequence([] {
        std::cout << "Parent drained" << std::endl;
    });

    return 0;
}

