// Helper class to handle different data type outputs
class CustomOutputHandler {
public:
    void printValue(std::ostream& stream, AST_Expression::ExpressionType exprType, const AST_Expression::DataValue& value) {
        switch (exprType) {
            case AST_Expression::EV_ushort:
                stream << value.u.ushort_val;
                break;
            case AST_Expression::EV_long:
                stream << value.u.long_val;
                break;
            case AST_Expression::EV_ulong:
                stream << value.u.ulong_val;
                break;
            case AST_Expression::EV_char:
                // Output character as octal escape sequence in single quotes
                stream << "'" << std::oct << static_cast<int>(value.u.char_val) << "'";
                break;
            case AST_Expression::EV_bool:
                stream << (value.u.bool_val ? "true" : "false");
                break;
            default:
                stream << "Unknown expression type";
                break;
        }
    }
};

