#include <boost/archive/text_iarchive.hpp>
#include <boost/serialization/split_member.hpp>

class Coordinate {
private:
    int horizontal;
    int vertical;

    friend class boost::serialization::access;

    template <class Archive>
    void save(Archive &ar, const unsigned int version) const {
        ar & horizontal;
        ar & vertical;
    }

    template <class Archive>
    void load(Archive &ar, const unsigned int version) {
        ar & horizontal;
        ar & vertical;
    }

    BOOST_SERIALIZATION_SPLIT_MEMBER()

public:
    Coordinate() : horizontal(0), vertical(0) {}
    Coordinate(int h, int v) : horizontal(h), vertical(v) {}

    void store(std::ostream &stream) const {
        boost::archive::text_oarchive archive(stream);
        archive << *this;
    }

    void restore(std::istream &stream) {
        boost::archive::text_iarchive archive(stream);
        archive >> *this;
    }

    int getHorizontal() const {
        return horizontal;
    }

    int getVertical() const {
        return vertical;
    }
};

int main() {
    // Initialize a coordinate instance
    Coordinate point(5, 10);

    // Serialize the coordinate
    std::stringstream buffer;
    point.store(buffer);

    // Deserialize into a new instance
    Coordinate restoredPoint;
    restoredPoint.restore(buffer);

    // Display the restored coordinates
    std::cout << "Restored Point - Horizontal: " << restoredPoint.getHorizontal() 
              << ", Vertical: " << restoredPoint.getVertical() << std::endl;

    return 0;
}

