                    int start_bit, int width_bits, MSR::m_function op, double scale_factor)
        : m_msrio(msrio), m_cpu(cpu), m_offset(offset), m_start_bit(start_bit),
          m_width(width_bits), m_operation(op), m_scale(scale_factor) {}

    void write(double input_value) {
        // Compute bit mask for the field width
        uint64_t field_mask = (1ULL << m_width) - 1;

        // Scale and convert input to integer representation
        uint64_t scaled_value = static_cast<uint64_t>(std::round(input_value / m_scale));

        // Align the value to the correct bit position
        uint64_t aligned_value = (scaled_value & field_mask) << m_start_bit;

        // Shift mask accordingly for masked write
        uint64_t shifted_mask = field_mask << m_start_bit;

        // Delegate actual write operation
        m_msrio->write_msr(m_cpu, m_offset, aligned_value, shifted_mask);
    }

private:
    std::shared_ptr<MSRIO> m_msrio;
    int m_cpu;
    uint64_t m_offset;
    int m_start_bit;
    int m_width;
    MSR::m_function m_operation;
    double m_scale;
};

