// Simulated EString class for demonstration purposes
class EString {
private:
    char* data;
public:
    EString(const char* str = "") {
        if (str) {
            size_t len = strlen(str);
            data = new char[len + 1];
            strcpy(data, str);
        } else {
            data = new char[1];
            data[0] = '\0';
        }
    }

    ~EString() {
        delete[] data;
    }

    const char* c_str() const {
        return data;
    }

    size_t length() const {
        return strlen(data);
    }

    EString& operator<<(const char* str) {
        size_t currentLen = strlen(data);
        size_t appendLen = strlen(str);
        char* newData = new char[currentLen + appendLen + 1];
        strcpy(newData, data);
        strcat(newData, str);
        delete[] data;
        data = newData;
        return *this;
    }
};

