class EProtocolDecoderException : public EProtocolCodecException {
private:
    EString* hexDump;

public:
    EProtocolDecoderException() : hexDump(nullptr) {}

    ~EProtocolDecoderException() {
        delete hexDump;
    }

    void assignHexdump(const char* hexData) {
        // Verify that hexDump has not been previously assigned
        if (hexDump != nullptr) {
            throw std::runtime_error("Hexdump already set");
        }

        // Allocate and store the hexdump string
        hexDump = new EString(hexData);

        // Ensure message exists before appending
        if (message == nullptr) {
            message = new EString(EProtocolCodecException::getMessage());
        }

        // Append hexdump information to the existing message
        if (message->length() > 0) {
            (*message) << " ";
        }
        (*message) << "(Hexdump: " << hexDump->c_str() << ")";
    }

    const char* getFullMessage() {
        // Return custom message if available, otherwise default
        if (message != nullptr) {
            return message->c_str();
        } else {
            return EProtocolCodecException::getMessage();
        }
    }
};

