// Base class for screen objects with unique identifiers
class Screen {
public:
    Screen(int identifier) : identifier(identifier) {}
    virtual void show() = 0;
    int getIdentifier() const { return identifier; }
protected:
    int identifier;
};

// Application manager that handles screen lifecycle and display
class Application {
public:
    void registerScreen(Screen* screen) {
        screenRegistry[screen->getIdentifier()] = screen;
    }

    void deregisterScreen(int identifier) {
        auto iter = screenRegistry.find(identifier);
        if (iter != screenRegistry.end()) {
            delete iter->second;
            screenRegistry.erase(iter);
        }
    }

    void presentScreen(int identifier) {
        auto iter = screenRegistry.find(identifier);
        if (iter != screenRegistry.end()) {
            iter->second->show();
        } else {
            std::cout << "Requested screen does not exist" << std::endl;
        }
    }

    ~Application() {
        for (auto& entry : screenRegistry) {
            delete entry.second;
        }
    }

private:
    std::unordered_map<int, Screen*> screenRegistry;
};

// Concrete implementation of a screen with customizable content
class ContentScreen : public Screen {
public:
    ContentScreen(int identifier, const std::string& text) 
        : Screen(identifier), text(text) {}

    void show() override {
        std::cout << "Display " << getIdentifier() << ": " << text << std::endl;
    }

private:
    std::string text;
};

int main() {
    Application app;
    app.registerScreen(new ContentScreen(1, "Welcome to the application"));
    app.registerScreen(new ContentScreen(2, "Configuration panel"));

    app.presentScreen(1);
    app.presentScreen(2);

    app.deregisterScreen(1);
    app.presentScreen(1);

    return 0;
}

