// Retrieves a string value from the Windows registry under HKEY_LOCAL_MACHINE
std::string fetchRegistryString(const std::string& subKeyPath, const std::string& valueName) {
    HKEY hKeyHandle = nullptr;
    std::string resultValue;

    // Attempt to open the specified registry key with read access
    if (RegOpenKeyExA(HKEY_LOCAL_MACHINE, subKeyPath.c_str(), 0, KEY_READ, &hKeyHandle) == ERROR_SUCCESS) {
        DWORD valueType = 0;
        DWORD valueSize = 0;

        // First call to determine required buffer size and type
        if (RegQueryValueExA(hKeyHandle, valueName.c_str(), nullptr, &valueType, nullptr, &valueSize) == ERROR_SUCCESS) {
            // Only process REG_SZ (null-terminated string) type
            if (valueType == REG_SZ && valueSize > 0) {
                // Allocate buffer including space for null terminator
                char* tempBuffer = new char[valueSize];

                // Second call to retrieve actual data
                if (RegQueryValueExA(hKeyHandle, valueName.c_str(), nullptr, &valueType, 
                                     reinterpret_cast<LPBYTE>(tempBuffer), &valueSize) == ERROR_SUCCESS) {
                    resultValue = std::string(tempBuffer);
                }

                delete[] tempBuffer;
            }
        }

        // Always close the registry key handle when done
        RegCloseKey(hKeyHandle);
    }

    return resultValue;
}

// Unit tests using Google Test framework
