// A reference wrapper for sub-vectors with arithmetic operations
template <typename T>
class subvector_view {
private:
    T* elements;
    size_t length;
public:
    subvector_view(T* ptr, size_t len) : elements(ptr), length(len) {}

    // Copy assignment: copy values from another view
    subvector_view& operator=(const subvector_view& src) {
        for (size_t idx = 0; idx < length; ++idx) {
            elements[idx] = src.elements[idx];
        }
        return *this;
    }

    // Addition assignment: add values from another view element-wise
    subvector_view& operator+=(const subvector_view& src) {
        for (size_t idx = 0; idx < length; ++idx) {
            elements[idx] += src.elements[idx];
        }
        return *this;
    }

    // Get the underlying pointer
    T* get_data() const { return elements; }

    // Get the length
    size_t get_size() const { return length; }
};

int main() {
    // Initialize a vector with sample data
    std::vector<float> data = {1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f};

    // Create views over different segments of the data
    subvector_view<float> segment1(&data[0], 4);   // First four elements
    subvector_view<float> segment2(&data[2], 4);   // Last four elements

    // Perform addition operation: segment2 = segment1 + segment2
    segment2 += segment1;

    // Print the updated data
    for (size_t i = 0; i < data.size(); ++i) {
        std::cout << data[i] << " ";
    }
    std::cout << std::endl;

    return 0;
}

