// Custom event dispatcher class that manages callback functions
class EventDispatcher {
private:
    std::vector<void (*)()> callbacks;
public:
    // Add a new callback function to the list
    void addCallback(void (*callback)()) {
        callbacks.push_back(callback);
    }

    // Execute all registered callbacks sequentially
    void triggerEvents() {
        for (size_t i = 0; i < callbacks.size(); ++i) {
            callbacks[i]();
        }
    }
};

