#include <vector>

// Helper function to compute barrelData indices from (eta, phi)
void computeBarrelIndices(int eta, int phi, int& layer, int& sector, int& offset) {
    layer = phi / 8;          // Module index in phi direction
    sector = eta / 8;         // Submodule index in eta direction
    offset = (phi % 8) * 8 + (eta % 8);  // Fine position within submodule
}

int main() {
    // Initialize data containers
    std::vector<int> combEM(72 * 56);
    std::vector<int> combHD(72 * 56);

    // Barrel data: [layer][sector][position] — dimensions: 9 × 7 × 64
    std::vector<std::vector<std::vector<int>>> barrelData(
        9, 
        std::vector<std::vector<int>>(7, std::vector<int>(64, 0))
    );

    // Populate barrelData using phi (outer) and eta (inner) loops
    int phi = 0;
    while (phi < 72) {
        int eta = 0;
        while (eta < 56) {
            int layerIdx, sectorIdx, finePos;
            computeBarrelIndices(eta, phi, layerIdx, sectorIdx, finePos);

            int linearIndex = phi * 56 + eta;

            // Assign EM and HD values to their respective positions
            barrelData[layerIdx][sectorIdx][finePos] = combEM[linearIndex];
            barrelData[layerIdx][sectorIdx][finePos + 32] = combHD[linearIndex];

            ++eta;
        }
        ++phi;
    }

    return 0;
}

