// Perform network stress test by establishing multiple TCP connections and sending packets
void networkStressTest(const std::string& host, int port, size_t numSockets, size_t packetSize) {
    std::cout << "Initiating connection stress test with " << numSockets << " sockets..." << std::endl;
    std::vector<acl::CoreSocket::SOCKET> activeSockets;

    // Establish required number of connections
    for (size_t idx = 0; idx < numSockets; ++idx) {
        acl::CoreSocket::SOCKET newSocket;

        // Attempt to establish TCP connection
        if (!connect_tcp_to(host.c_str(), port, nullptr, &newSocket)) {
            std::cerr << "Failed to connect socket at index " << idx << std::endl;

            // Clean up previously established connections
            for (auto& existingSocket : activeSockets) {
                close_socket(existingSocket);
            }
            return;
        }

        // Configure socket options
        if (!set_tcp_socket_options(newSocket)) {
            std::cerr << "Unable to configure socket options for socket " << idx << std::endl;

            // Clean up all established connections including current one
            for (auto& existingSocket : activeSockets) {
                close_socket(existingSocket);
            }
            close_socket(newSocket);
            return;
        }

        activeSockets.push_back(newSocket);
    }

    // Transmit data through each established connection
    for (auto& socket : activeSockets) {
        char* buffer = new char[packetSize];
        // Initialize buffer content as needed
        // ...

        ssize_t sentBytes = send(socket, buffer, packetSize, 0);
        if (sentBytes != static_cast<ssize_t>(packetSize)) {
            std::cerr << "Transmission error on socket " << socket 
                      << ": sent " << sentBytes << " of " << packetSize << " bytes" << std::endl;
            // Continue with other sockets despite this failure
        }

        delete[] buffer;
    }

    // Terminate all connections
    for (auto& socket : activeSockets) {
        close_socket(socket);
    }
}

