};

// Class to represent an operation symbol
class OperationSymbol {
public:
    OperationSymbol(const std::string& sym) : symbol(sym) {}

    friend std::ostream& operator<<(std::ostream& stream, const OperationSymbol& op) {
        stream << op.symbol;
        return stream;
    }

private:
    std::string symbol;
};

// Function to format and print expression in specified order
void displayExpression(std::ostream& out, int mode, const ValueToken& val, const OperationSymbol& oper) {
    if (mode == 1) {
        // Postfix: value followed by operator
        out << val << " " << oper;
    } else {
        // Prefix: operator followed by value
        out << oper << " " << val;
    }
}

int main() {
    ValueToken expression("5");
    OperationSymbol operation("+");

    std::cout << "Postfix format: ";
    displayExpression(std::cout, 1, expression, operation);
    std::cout << std::endl;

    std::cout << "Prefix format: ";
    displayExpression(std::cout, 0, expression, operation);
    std::cout << std::endl;

    return 0;
}

