    if (name == "OpAlpha") hasAlpha = true;
    if (name == "OpBeta") hasBeta = true;
  }

  if (!hasAlpha || !hasBeta)
  {
    std::cerr << "Missing expected operations in registry" << std::endl;
  }
}

