// Function to compute the maximum possible weight after connecting ropes
int maxWeightAfterConnectingRopes(int weights[], int count, int startMultiplier) {
    // Sort the rope weights in ascending order
    std::sort(weights, weights + count);

    // Array to hold transformed weights (weight * multiplier)
    int transformed[count];

    // Process from largest original weight to smallest, incrementing multiplier each time
    for (int i = count - 1; i >= 0; --i) {
        transformed[i] = weights[i] * startMultiplier;
        ++startMultiplier;
    }

    // Sort the transformed weights to find the maximum
    std::sort(transformed, transformed + count);

    // The maximum value will be the last element after sorting
    return transformed[count - 1];
}

