        int width;   // filter width
        int height;  // filter height
        int depth;   // filter depth
    } dims;
    // other members of filter_t
};

using mat3d_ptr = int***; // Assuming mat3d_ptr is a pointer to a 3D matrix of features

int compute_total_ops(const std::vector<filter_t>& filters, const mat3d_ptr feats, int begin_idx, int finish_idx) {
    int range_size = finish_idx - begin_idx + 1;
    assert(finish_idx >= begin_idx);
    assert(range_size <= static_cast<int>(filters.size()));

    // Extract filter dimensions from the first filter in the list
    int filter_height = filters[0].dims.height;
    int filter_width  = filters[0].dims.width;
    int filter_depth  = filters[0].dims.depth;

    // Compute total operations as product of range size and all filter dimensions
    int total_ops = range_size * filter_height * filter_width * filter_depth;
    return total_ops;
}

#include <iostream>
