enum class Severity { TRACE, INFO, WARN, ERR, CRIT };

class LogSystem {
public:
    LogSystem() : minSeverity(Severity::INFO) {}

    void setMinimumSeverity(Severity sev) {
        minSeverity = sev;
    }

    void enableConsole() {
        targets.push_back(&std::cout);
    }

    void enableFile(const std::string& path) {
        auto* fs = new std::ofstream(path);
        targets.push_back(fs);
    }

    void write(Severity sev, const std::string& msg) {
        if (static_cast<int>(sev) >= static_cast<int>(minSeverity)) {
            std::lock_guard<std::mutex> guard(mtx);
            for (auto* out : targets) {
                *out << timestamp() << " [" << severityName(sev) << "] " << msg << "\n";
            }
        }
    }

    ~LogSystem() {
        for (auto* out : targets) {
            if (out != &std::cout) {
                auto* fs = static_cast<std::ofstream*>(out);
                fs->close();
                delete fs;
            }
        }
    }

private:
    Severity minSeverity;
    std::vector<std::ostream*> targets;
    std::mutex mtx;

    std::string timestamp() {
        std::time_t t = std::time(nullptr);
        char buf[64];
        std::strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", std::localtime(&t));
        return std::string(buf);
    }

    std::string severityName(Severity s) {
        switch (s) {
            case Severity::TRACE:  return "DEBUG";
            case Severity::INFO:   return "INFO";
            case Severity::WARN:   return "WARNING";
            case Severity::ERR:    return "ERROR";
            case Severity::CRIT:   return "FATAL";
            default:               return "UNKNOWN";
        }
    }
};

int main() {
    LogSystem logger;
    logger.enableConsole();
    logger.enableFile("log.txt");
    logger.setMinimumSeverity(Severity::TRACE);

    logger.write(Severity::INFO, "This is an informational message");
    logger.write(Severity::WARN, "This is a warning message");
    logger.write(Severity::ERR, "This is an error message");
    logger.write(Severity::TRACE, "This is a debug message");

    return 0;
}

