// Query the number of value-contiguous segments in positions [l, r]
int find_segment_count(int left_bound, int right_bound) {
    if (left_bound > right_bound) return 0;
    cout << "1 " << left_bound << " " << right_bound << endl;
    int response;
    cin >> response;
