// Swap elements at positions pos1 and pos2
void exchange_positions(int pos1, int pos2) {
    if (pos1 == pos2) return;
    cout << "2 " << pos1 << " " << pos2 << endl;
    int result;
    cin >> result;
}

int main() {
    // Speed up I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int array_size, range1_start, range2_start;
    if (!(cin >> array_size >> range1_start >> range2_start)) return 0;

    // Track how long the current contiguous chain is
    int chain_length = 1;

    while (chain_length < array_size) {
        // Determine if the element at the end of our current chain has a neighbor 
        // in the unprocessed portion of the array
        int total_segments = find_segment_count(chain_length, array_size);
        int remaining_segments = find_segment_count(chain_length + 1, array_size);

        if (total_segments <= remaining_segments) {
            // There's a value-adjacent element in the remaining part
            int low = chain_length + 1;
            int high = array_size;

            // Binary search to locate the adjacent element
            while (low < high) {
                int mid = low + (high - low) / 2;
                int left_part = find_segment_count(chain_length, mid);
                int right_part = find_segment_count(chain_length + 1, mid);

                if (left_part <= right_part) {
                    high = mid;  // Adjacent element is in the left half
                } else {
                    low = mid + 1;  // Adjacent element is in the right half
                }
            }

            // Move the found element next in the chain
            exchange_positions(chain_length + 1, low);
            chain_length++;
        } else {
            // Current end is an endpoint (min or max), reverse the chain to expose the other end
            for (int i = 1; i <= chain_length / 2; ++i) {
                exchange_positions(i, chain_length - i + 1);
            }
            // Continue searching with reversed chain
        }
    }

    // Output the final arrangement
    cout << "3";
    for (int idx = 1; idx <= array_size; ++idx) {
        cout << " " << idx;
    }
    cout << endl;

    return 0;
}

#include <vector>
using namespace std;

class Solution {
public:
    int findMiddleIndex(vector<int>& nums) {
        int n = nums.size();
        int currentSum = 0;
        int total = 0;

        // Compute the total sum of all elements
        for (int val : nums) {
            total += val;
        }

        // Check each index to see if it's a middle index
        for (int j = 0; j < n; ++j) {
            // Left sum is currentSum, right sum is total - currentSum - nums[j]
            if (currentSum == total - currentSum - nums[j]) {
                return j;
            }
            currentSum += nums[j];
        }

        return -1;
    }
};

