#include <algorithm>

class Solution {
public:
    int minimumCost(std::vector<int>& nums) {
        int arraySize = nums.size();
        int smallestSum = INT_MAX;

        // Iterate through all valid pairs (i, j) where 1 <= i < j < n
        for (int firstIndex = 1; firstIndex < arraySize - 1; ++firstIndex) {
            for (int secondIndex = firstIndex + 1; secondIndex < arraySize; ++secondIndex) {
                int currentTotal = nums[0] + nums[firstIndex] + nums[secondIndex];
                if (currentTotal < smallestSum) {
                    smallestSum = currentTotal;
                }
            }
        }

        return smallestSum;
    }
};

