// Helper to add a named child under a given parent object
AA::ObjectWriterPtr appendNamedChild(AA::ObjectWriterPtr &parent,
                                     const std::string &childName,
                                     const AA::MetaData &md) {
    return parent->createChild(AA::ObjectHeader(childName, md));
}

// Write an Alembic archive containing one child named "ac0"
void exportSampleArchive(const std::string &filePath) {
    std::cout << "Starting archive export to: " << filePath << std::endl;

    AA::MetaData emptyMD;
    AO::WriteArchive writerFactory;
    AA::ArchiveWriterPtr archive = writerFactory(filePath, emptyMD);

    AA::ObjectWriterPtr root = setupTopLevelWriter(archive);
    AA::ObjectWriterPtr childObj = appendNamedChild(root, "ac0", emptyMD);

    std::cout << "Archive export completed successfully." << std::endl;
}

// Helper to retrieve a child by index from a parent reader
AA::ObjectReaderPtr getChildByIndex(AA::ObjectReaderPtr &parent, std::size_t idx) {
    return parent->getChild(static_cast<int>(idx));
}

// Read and inspect the first child of the archive
void importSampleArchive(const std::string &filePath) {
    std::cout << "Starting archive import from: " << filePath << std::endl;

    AO::ReadArchive readerFactory;
    AA::ArchiveReaderPtr archive = readerFactory(filePath);
    AA::ObjectReaderPtr root = archive->getTop();

    // Access the first (and only) child
    AA::ObjectReaderPtr child = getChildByIndex(root, 0);

    std::cout << "Retrieved child full name: " << child->getFullName() << std::endl;
    std::cout << "Archive import completed." << std::endl;
}

