// Demonstrates accessing Lua table data using sol2
int main() {
    std::cout << "=== tables ===" << std::endl;

    sol::state lua;

    // Initialize table as an array
    lua.script(R"(arrayTable = {"hello", "world"})");

    // Initialize nested table structure
    lua.script(R"(
        configTable = {
            ["settings"] = {
                ["debug"] = true,
                ["level"] = 5,
            },
            ["title"] = "Configuration",
        }
    )");

    // Retrieve top-level table
    sol::table config = lua["configTable"];

    // Extract nested table
    sol::table settings = config["settings"];

    // Access values using different methods
    bool debugMode = settings.get<bool>("debug");
    int level = settings.get<int>("level");
    std::string title = config["title"];

    std::cout << "Configuration loaded:" << std::endl;
    std::cout << "Title: " << title << std::endl;
    std::cout << "Debug mode: " << (debugMode ? "enabled" : "disabled") 
              << ", Level: " << level << std::endl;

    // Alternative access via chained indexing
    std::string directAccess = lua["configTable"]["settings"]["debug"] 
