namespace {
class OcamlGCFrameEmitter : public GCMetadataPrinter {
public:
  void beginAssembly(Module &M, GCModuleInfo &Info, AsmPrinter &AP) override;
  void finishAssembly(Module &M, GCModuleInfo &Info, AsmPrinter &AP) override;
};
} // end anonymous namespace

static GCMetadataPrinterRegistry::Add<OcamlGCFrameEmitter>
    Z("ocaml", "ocaml 3.10-compatible collector");

void llvm::linkOcamlGCPrinter() {}

// Helper function to construct OCaml symbol names
static void GenerateOcamlSymbol(const Module &M, AsmPrinter &AP, const char *Suffix) {
  StringRef ModuleId = M.getModuleIdentifier();
  std::string SymbolName;

  SymbolName += "caml";
  size_t FirstLetterPos = SymbolName.size();
  SymbolName.append(ModuleId.begin(), llvm::find(ModuleId, '.'));
  SymbolName += "__";
  SymbolName += Suffix;

  // Capitalize first character of module name part
  if (FirstLetterPos < SymbolName.size()) {
    SymbolName[FirstLetterPos] = toupper(SymbolName[FirstLetterPos]);
  }

  SmallString<128> PrefixedName;
  Mangler::getNameWithPrefix(PrefixedName, SymbolName, M.getDataLayout());
  MCSymbol *Sym = AP.OutContext.getOrCreateSymbol(PrefixedName);

  AP.OutStreamer->emitSymbolAttribute(Sym, MCSA_Global);
  AP.OutStreamer->emitLabel(Sym);
}

void OcamlGCFrameEmitter::beginAssembly(Module &M, GCModuleInfo &Info,
                                        AsmPrinter &AP) {
  // Emit code section markers
  AP.OutStreamer->switchSection(AP.getObjFileLowering().getTextSection());
  GenerateOcamlSymbol(M, AP, "code_begin");

  // Emit data section markers
  AP.OutStreamer->switchSection(AP.getObjFileLowering().getDataSection());
  GenerateOcamlSymbol(M, AP, "data_begin");
}

/// finishAssembly - Generate the frame table for OCaml GC compatibility
///
/// The OCaml frame table format:
///   struct align(intptr_t) {
///     uint16_t Count;
///     struct align(intptr_t) {
///       void *Address;
///       uint16_t Size;
///       uint16_t LiveCount;
///       uint16_t Offsets[LiveCount];
///     } Entries[Count];
///   };
///
void OcamlGCFrameEmitter::finishAssembly(Module &M, GCModuleInfo &Info,
                                         AsmPrinter &AP) {
  unsigned PointerSize = M.getDataLayout().getPointerSize();

  // Emit end markers
  AP.OutStreamer->switchSection(AP.getObjFileLowering().getTextSection());
  GenerateOcamlSymbol(M, AP, "code_end");

  AP.OutStreamer->switchSection(AP.getObjFileLowering().getDataSection());
  GenerateOcamlSymbol(M, AP, "data_end");

  // Padding byte as required by OCaml runtime
  AP.OutStreamer->emitIntValue(0, PointerSize);

  // Start frame table section
  AP.OutStreamer->switchSection(AP.getObjFileLowering().getDataSection());
  GenerateOcamlSymbol(M, AP, "frametable");

  // Count valid descriptors
  int DescriptorCount = 0;
  for (const auto &FuncInfo : llvm::make_range(Info.funcinfo_begin(), Info.funcinfo_end())) {
    if (FuncInfo->getStrategy().getName() != getStrategy().getName())
      continue;
    DescriptorCount += FuncInfo->size();
  }

  // Check descriptor count doesn't exceed 16-bit limit
  if (DescriptorCount >= 1 << 16) {
    report_fatal_error("Too many descriptors for ocaml GC");
  }

  AP.emitInt16(DescriptorCount);

  // Align for pointer-sized data
  AP.emitAlignment(PointerSize == 4 ? Align(4) : Align(8));

  // Process each function's GC information
  for (const auto &FuncInfo : llvm::make_range(Info.funcinfo_begin(), Info.funcinfo_end())) {
    if (FuncInfo->getStrategy().getName() != getStrategy().getName())
      continue;

    uint64_t FrameSize = FuncInfo->getFrameSize();
    if (FrameSize >= 1 << 16) {
      report_fatal_error("Function '" + FuncInfo->getFunction().getName() +
                         "' exceeds maximum frame size for OCaml GC: " +
                         Twine(FrameSize) + " >= 65536");
    }

    // Add comments for readability
    AP.OutStreamer->AddComment("live roots for " +
                               Twine(FuncInfo->getFunction().getName()));
    AP.OutStreamer->addBlankLine();

    // Process each call site in the function
    for (auto DescIter = FuncInfo->begin(), DescEnd = FuncInfo->end(); 
         DescIter != DescEnd; ++DescIter) {

      size_t LiveRootCount = FuncInfo->live_size(DescIter);
      if (LiveRootCount >= 1 << 16) {
        report_fatal_error("Function '" + FuncInfo->getFunction().getName() +
                           "' has too many live roots for OCaml GC: " +
                           Twine(LiveRootCount) + " >= 65536");
      }

      // Emit return address
      AP.OutStreamer->emitSymbolValue(DescIter->Label, PointerSize);

      // Emit frame size and live root count
      AP.emitInt16(FrameSize);
      AP.emitInt16(LiveRootCount);

      // Emit stack offsets for live roots
      for (auto RootIter = FuncInfo->live_begin(DescIter), 
           RootEnd = FuncInfo->live_end(DescIter); 
           RootIter != RootEnd; ++RootIter) {

        if (RootIter->StackOffset >= 1 << 16) {
          report_fatal_error("GC root stack offset out of range for OCaml GC");
        }

        AP.emitInt16(RootIter->StackOffset);
      }

      // Align after each descriptor
      AP.emitAlignment(PointerSize == 4 ? Align(4) : Align(8));
    }
  }
}

