// Helper function to compare complex numbers with tolerance
bool approximately_equal(std::complex<double> x, std::complex<double> y,
                         double epsilon = 1e-5) {
  return std::norm(x - y) < epsilon * epsilon;
}

int main(int argc, char **argv) {
  MPI_Init(&argc, &argv);

  int my_rank;
  MPI_Comm_rank(MPI_COMM_WORLD, &my_rank);

  int total_ranks;
  MPI_Comm_size(MPI_COMM_WORLD, &total_ranks);

  // Verify correct number of processes
  if (total_ranks != 2) {
    if (my_rank == 0) {
      std::cerr << "Error: This test requires exactly 2 MPI ranks."
                << std::endl;
    }
    MPI_Finalize();
    return 1;
  }

  const size_t num_qubits = 4;
  QuantumRegister register_state(num_qubits);

  // Initialize to |0000⟩: amplitude 1.0 at index 0 on rank 0
  // All other amplitudes zero by default

  // Step 1: Apply Hadamard gate to qubit 3 (most significant)
  if (my_rank == 0) {
    std::cout << "Applying H(3)..." << std::endl;
  }
  register_state.applyHadamard(3);

  auto local_amplitudes = register_state.getStateVector();
  const double one_over_root_two = 1.0 / std::sqrt(2.0);

  if (my_rank == 0) {
    assert(approximately_equal(local_amplitudes[0], one_over_root_two));
  } else {
    // Local index 0 corresponds to global index 8 (|1000⟩)
    assert(approximately_equal(local_amplitudes[0], one_over_root_two));
  }

  // Step 2: Apply CNOT with control=3, target=0
  if (my_rank == 0) {
    std::cout << "Applying CNOT(3, 0)..." << std::endl;
  }
  register_state.applyCNOT(3, 0);

  local_amplitudes = register_state.getStateVector();

  if (my_rank == 0) {
    // Rank 0 holds indices 0–7; |0000⟩ remains unchanged
    if (approximately_equal(local_amplitudes[0], one_over_root_two)) {
      std::cout << "[Rank 0] |0000⟩ verified." << std::endl;
    } else {
      std::cerr << "[Rank 0] FAILED: |0000⟩ amplitude mismatch." << std::endl;
      MPI_Finalize();
      return 1;
    }
  } else {
    // Rank 1 holds indices 8–15; |1000⟩ → |1001⟩
    // Local index 0: |1000⟩ → amplitude 0
    // Local index 1: |1001⟩ → amplitude 1/sqrt(2)
    if (approximately_equal(local_amplitudes[0], 0.0) &&
        approximately_equal(local_amplitudes[1], one_over_root_two)) {
      std::cout << "[Rank 1] |1001⟩ verified." << std::endl;
    } else {
      std::cerr << "[Rank 1] FAILED: |1001⟩ amplitude mismatch." << std::endl;
      MPI_Finalize();
      return 1;
    }
  }

  MPI_Finalize();
  return 0;
}

