#include "llvm/Transforms/Utils/UnifyFunctionExitNodes.h"
#include "llvm/IR/BasicBlock.h"
#include "llvm/IR/Function.h"
#include "llvm/IR/Instructions.h"
#include "llvm/IR/Type.h"
#include "llvm/Transforms/Utils.h"
using namespace llvm;

namespace {
// Consolidate all unreachable terminators into a single block
bool mergeUnreachableTargets(Function &F) {
  SmallVector<BasicBlock *, 8> unreachableList;

  // Collect all blocks ending with UnreachableInst
  for (auto &BB : F) {
    if (isa<UnreachableInst>(BB.getTerminator())) {
      unreachableList.push_back(&BB);
    }
  }

  // No need to merge if there's only one or none
  if (unreachableList.size() <= 1)
    return false;

  // Create a new unified unreachable block
  BasicBlock *mergedUnreachable = 
      BasicBlock::Create(F.getContext(), "MergedUnreachable", &F);
  new UnreachableInst(F.getContext(), mergedUnreachable);

  // Replace each original unreachable terminator with an unconditional branch
  for (BasicBlock *BB : unreachableList) {
    BB->getTerminator()->eraseFromParent(); // Remove old terminator
    BranchInst::Create(mergedUnreachable, BB);
  }

  return true;
}

// Merge multiple return points into a single return block
bool mergeReturnPoints(Function &F) {
  SmallVector<BasicBlock *, 8> returnBlocks;

  // Find all basic blocks that end with ReturnInst
  for (auto &BB : F) {
    if (isa<ReturnInst>(BB.getTerminator()))
      returnBlocks.push_back(&BB);
  }

  // Nothing to do if zero or one return point
  if (returnBlocks.size() <= 1)
    return false;

  // Create the unified return block
  BasicBlock *mergedReturnBlock = 
      BasicBlock::Create(F.getContext(), "MergedReturn", &F);
  PHINode *phiNode = nullptr;

  if (F.getReturnType()->isVoidTy()) {
    ReturnInst::Create(F.getContext(), nullptr, mergedReturnBlock);
  } else {
    // Build PHI node to merge non-void return values
    phiNode = PHINode::Create(F.getReturnType(), returnBlocks.size(),
                              "MergedRetVal");
    phiNode->insertInto(mergedReturnBlock, mergedReturnBlock->end());
    ReturnInst::Create(F.getContext(), phiNode, mergedReturnBlock);
  }

  // Update each original return block: replace return with branch
  for (BasicBlock *BB : returnBlocks) {
    Instruction *term = BB->getTerminator();
    if (phiNode) {
      Value *retVal = term->getOperand(0);
      phiNode->addIncoming(retVal, BB);
    }
    term->eraseFromParent(); // Remove the return instruction
    BranchInst::Create(mergedReturnBlock, BB);
  }

  return true;
}
} // namespace

PreservedAnalyses UnifyFunctionExitNodesPass::run(
    Function &F, FunctionAnalysisManager &AM) {
  bool modified = false;
  modified |= mergeUnreachableTargets(F);
  modified |= mergeReturnPoints(F);
  return modified ? PreservedAnalyses() : PreservedAnalyses::all();
}

