class Solution {
public:
    int numberOfEmployeesWhoMetTarget(vector<int>& hours, int target) {
        int count = 0;
        int index = 0;
        int size = hours.size();

        while (index < size) {
            if (hours[index] >= target) {
                count++;
            }
            index++;
        }

