#include "rslcpp/rslcpp.hpp"
#include <limits>
#include <rslcpp_exceptions/exceptions.hpp>

namespace rslcpp
{

exit_code_t run_job(int argc, char ** argv, Job::SharedPtr job)
{
  // Acquire singleton time-delay backend instance
  time_delay::CallbackBackend & delay_backend = time_delay::CallbackBackend::getInstance();

  // Initialize ROS 2 context with custom init options
  rclcpp::InitOptions init_opts;
  rclcpp::init(argc, argv, init_opts);

  // Retrieve all nodes managed by the job
  auto node_list = job->create_and_get_nodes();

  // Validate that each node has sim time enabled
  for (auto const & nd : node_list) {
    if (!nd->get_parameter("use_sim_time").as_bool()) {
      throw exceptions::NodeNotUsingSimTime(nd->get_fully_qualified_name());
    }
  }

  // Prepare executor with global context and custom event queue
  auto ctx = rclcpp::contexts::get_global_default_context();
  rclcpp::ExecutorOptions exec_cfg;
  exec_cfg.context = ctx;

  rclcpp::experimental::executors::EventsExecutor executor{
    std::make_unique<rclcpp::experimental::executors::SimpleEventsQueue>(),
    false,
    exec_cfg
  };

  // Register all nodes with the executor
  for (auto const & nd : node_list) {
    executor.add_node(nd);
  }

  // Start simulation at initial time
  auto current_sim_time = job->get_initial_time();

  // Main simulation loop: continue until job signals completion or shutdown requested
  while (!job->get_finished() && rclcpp::ok(ctx)) {

    // Update time delay backend with current simulation timestamp
    delay_backend.set_time(current_sim_time.nanoseconds());

    // Sync all node clocks to current simulation time
    for (auto & nd : node_list) {
      rslcpp::set_clock(current_sim_time, nd->get_clock());
    }

    // Process any delayed callbacks whose deadlines have passed
    delay_backend.execute_ready_delayed_callables();

    // Run all ready callbacks in a single-threaded fashion
    executor.spin_all(
      std::chrono::hours(200 * 365 * 24));  // Approx. 200 years — effectively infinite

    // Determine how far we can advance simulation time
#ifdef RSLCPP__CUSTOM__RCLCPP
    auto next_timer_ns = executor.get_time_until_next_timer();
#else
    // Fallback: assume minimum step of 1 ms if custom rclcpp not used
    auto next_timer_ns = std::chrono::milliseconds(1);
#endif

    // Terminate if no future timers remain
    if (next_timer_ns == std::chrono::nanoseconds::max()) {
      break;
    }

    // Compute earliest upcoming delayed callback time
    rslcpp::time_delay::Duration next_delayed_callable_ns =
      delay_backend.get_time_until_next_delayed_callable();

    // Choose smallest interval to advance simulation
    rclcpp::Duration delta_t;
    if (next_delayed_callable_ns < static_cast<int64_t>(next_timer_ns.count())) {
      delta_t = rclcpp::Duration{std::chrono::nanoseconds(next_delayed_callable_ns)};
    } else {
      delta_t = rclcpp::Duration{next_timer_ns};
    }

    // Advance simulation clock
    current_sim_time += delta_t;
  }

  // Finalize and return exit code
  auto result_code = job->get_exit_code();
  rclcpp::shutdown();
  return result_code;
}

