#include <iostream>
#include <asio.hpp>
#include <functional>

// A class that prints numbers from 0 to 4 with 1-second intervals
class timer_printer
{
public:
  timer_printer(asio::io_context& context)
    : interval_timer_(context, asio::chrono::seconds(1)),
      counter_(0)
  {
    // Start the first asynchronous wait
    interval_timer_.async_wait(std::bind(&timer_printer::tick, this));
  }

  ~timer_printer()
  {
    std::cout << "Final count is " << counter_ << std::endl;
  }

private:
  void tick()
  {
    if (counter_ < 5)
    {
      std::cout << counter_ << std::endl;
      ++counter_;

      // Reschedule the timer for 1 second later
      interval_timer_.expires_at(interval_timer_.expiry() + asio::chrono::seconds(1));
      interval_timer_.async_wait(std::bind(&timer_printer::tick, this));
    }
  }

  asio::steady_timer interval_timer_;
  int counter_;
};

int main()
{
  asio::io_context service;
  timer_printer instance(service);
  service.run();
  return 0;
}

