Y_UNIT_TEST_SUITE(THolderVectorTest) {
    Y_UNIT_TEST(TestCreateEmpty) {
        THolderVector<int> emptyVec;
        UNIT_ASSERT_EQUAL(emptyVec.Size(), 0);
        UNIT_ASSERT(!emptyVec);
    }

    Y_UNIT_TEST(TestCreateNonEmpty) {
        THolderVector<int> vec(5);
        UNIT_ASSERT_EQUAL(vec.Size(), 5);
        UNIT_ASSERT(vec);
        for (size_t idx = 0; idx < vec.Size(); ++idx) {
            UNIT_ASSERT_EQUAL(vec[idx], (int*)nullptr);
        }
    }

    Y_UNIT_TEST(TestResetValue) {
        THolderVector<int> vec;
        vec.PushBack(new int(10));
        vec.PushBack(new int(20));
        UNIT_ASSERT_VALUES_EQUAL(*vec[0], 10);
        UNIT_ASSERT_VALUES_EQUAL(*vec[1], 20);

        vec.Reset(0, MakeHolder<int>(100));
        vec.Reset(1, MakeHolder<int>(200));
        UNIT_ASSERT_VALUES_EQUAL(*vec[0], 100);
        UNIT_ASSERT_VALUES_EQUAL(*vec[1], 200);
    }

    Y_UNIT_TEST(TestResetNoValue) {
        THolderVector<int> vec;
        vec.Resize(3);
        UNIT_ASSERT_EQUAL(vec[1], (int*)nullptr);
        vec.Reset(1, MakeHolder<int>(42));
        UNIT_ASSERT_UNEQUAL(vec[1], (int*)nullptr);
        UNIT_ASSERT_VALUES_EQUAL(*vec[1], 42);
    }

    Y_UNIT_TEST(TestResetSmartPtr) {
        THolderVector<int> vec;
        vec.Resize(2);
        THolder<int> smartPtr(new int(7));
        vec.Reset(0, std::move(smartPtr));
        UNIT_ASSERT_VALUES_EQUAL(*vec[0], 7);
        UNIT_ASSERT(!smartPtr);
    }

    Y_UNIT_TEST(TestSwap) {
        THolderVector<int> first;
        first.PushBack(new int(123));
        THolderVector<int> second;
        first.Swap(second);
        UNIT_ASSERT(first.empty() && second.size() == 1 && *second.front() == 123);
    }

    Y_UNIT_TEST(TestUniquePtr) {
        THolderVector<TString> container;
        std::unique_ptr<TString> ptr(new TString("world"));
        container.PushBack(std::move(ptr));
        UNIT_ASSERT(container.Size() == 1);
        UNIT_ASSERT(ptr.get() == nullptr);
    }
} // Y_UNIT_TEST_SUITE(THolderVectorTest)

