    obj["string"] = "foo";
    obj["array"] = {1, 2};

    // Access elements using JSON pointers (read operations)
    std::cout << obj.at("/number"_json_pointer) << '\n';
    std::cout << obj.at("/string"_json_pointer) << '\n';
    std::cout << obj.at("/array"_json_pointer) << '\n';
    std::cout << obj.at("/array/1"_json_pointer) << '\n';

    // Modify existing values via JSON pointers
    obj["/string"_json_pointer] = "bar";
    std::cout << obj["string"] << '\n';

    // Insert new key-value pair
    obj["/boolean"_json_pointer] = true;
    std::cout << obj << '\n';

    // Update array element at index 1
    obj["/array/1"_json_pointer] = 21;

    // Extend array by assigning to non-existing index 4
    obj["/array/4"_json_pointer] = 44;
    std::cout << obj["array"] << '\n';

