#include <vector>
#include <string>

using namespace std;

vector<int> search(string &pat, string &txt) {
    vector<int> result;
    int patternLen = pat.length();
    int textLen = txt.length();

    // Handle edge case: empty pattern
    if (patternLen == 0) {
        return result;
    }

    // Check each possible starting position in text
    for (int i = 0; i <= textLen - patternLen; ++i) {
        bool match = true;
        for (int j = 0; j < patternLen; ++j) {
            if (txt[i + j] != pat[j]) {
                match = false;
                break;
            }
        }
        if (match) {
            result.push_back(i);
        }
    }

    return result;
}

