#include "asio/coroutine.hpp"
#include "unit_test.hpp"

// Must come after all other headers.
#include "asio/yield.hpp"

//------------------------------------------------------------------------------
// Coroutine completes via yield break (rewritten logic)
void yield_break_coro_v2(asio::coroutine& coro)
{
  reenter (coro)
  {
    yield return;
    yield break;
  }
}

void yield_break_test_v2()
{
  asio::coroutine coro;
  ASIO_CHECK(!coro.is_complete());

  // First invocation: coroutine not complete yet
  yield_break_coro_v2(coro);
  ASIO_CHECK(!coro.is_complete());

  // Second invocation: now it's complete due to yield break
  yield_break_coro_v2(coro);
  ASIO_CHECK(coro.is_complete());
}

//------------------------------------------------------------------------------
// Coroutine completes via early return (rewritten structure)
void return_coro_v2(asio::coroutine& coro)
{
  reenter (coro)
