// Use __int128 for intermediate products to avoid overflow.
using int128 = __int128_t;

// The modulus, read from input.
long long n;

// Calculates bits(x) = ceil(log2(x+1)).
inline int count_bits(long long x) {
    if (x == 0) return 0;
    return 64 - __builtin_clzll(x);
}

// Simulate device timing based on current hypothesis of exponent bits
long long estimate_time(long long base_val, long long exp_guess) {
    long long total_time = 0;
    int128 result = 1;
    int128 current_base = base_val;

    for (int bit_pos = 0; bit_pos < 60; ++bit_pos) {
        if ((exp_guess >> bit_pos) & 1) {
            total_time += (count_bits((long long)result) + 1) * (count_bits((long long)current_base) + 1);
            result = (result * current_base) % n;
        }
        total_time += (count_bits((long long)current_base) + 1) * (count_bits((long long)current_base) + 1);
        current_base = (current_base * current_base) % n;
    }

    return total_time;
}

int main() {
    // Optimize I/O for interactive problems
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::cin >> n;

    // Initialize random number generator with high-quality seed
    std::mt19937_64 rng(std::chrono::steady_clock::now().time_since_epoch().count());
    std::uniform_int_distribution<long long> uniform_dist(2, n - 1);

    // Start with least significant bit known to be 1 (since d is odd)
    long long current_d = 1;

    // Number of samples per bit position for statistical analysis
    const int samples_per_bit = 400;

    // Determine remaining 59 bits (positions 1 through 59)
    for (int pos = 1; pos < 60; ++pos) {
        long double score_diff_total = 0.0L;

        // Create two candidate exponents differing only at position 'pos'
        long long candidate_zero = current_d;                    // Assume bit 'pos' is 0
        long long candidate_one = current_d | (1LL << pos);      // Assume bit 'pos' is 1

        // Collect multiple samples for statistical reliability
        for (int sample_idx = 0; sample_idx < samples_per_bit; ++sample_idx) {
            long long a = uniform_dist(rng);

            // Query the device for actual execution time
            std::cout << "? " << a << "\n";
            long long measured_time;
            std::cin >> measured_time;

            // Compute expected times under both hypotheses
            long long time_zero = estimate_time(a, candidate_zero);
            long long time_one = estimate_time(a, candidate_one);

            // Accumulate difference in squared errors
            int128 error_zero = static_cast<int128>(measured_time) - time_zero;
            int128 error_one = static_cast<int128>(measured_time) - time_one;

            score_diff_total += static_cast<long double>(error_zero) * error_zero -
                                static_cast<long double>(error_one) * error_one;
        }

        // Update our best guess based on which hypothesis fits better
        if (score_diff_total > 0) {
            current_d = candidate_one;
        }
    }

    // Output final recovered private exponent
    std::cout << "! " << current_d << "\n";

    return 0;
}

