// Test basic rate limiting functionality with a single concurrent request limit
TEST(RequestLimiterTest, Basic) {
  // Configure the system to allow at most one concurrent request
  FLAGS_max_concurrent_requests = 1;

  RateLimiter limiter;

  // Initially, no requests are active, so no throttling should occur
  EXPECT_EQ(limiter.is_limited(), false);

  // After incrementing (implicitly via is_limited() logic), one request is active,
  // which meets the limit, so further requests should be throttled
  EXPECT_EQ(limiter.is_limited(), true);

  // Simulate completion of one request by decrementing the active count
  limiter.decrease_one_request();

  // Now there are no active requests, so no throttling should apply again
  EXPECT_EQ(limiter.is_limited(), false);
}

