FTakeRecorderStateProvider::FTakeRecorderStateProvider()
{
	// Register callbacks for take recorder lifecycle events
	UTakeRecorder::OnRecordingInitialized().AddRaw(this, &FTakeRecorderStateProvider::HandleInitialization);
}

void FTakeRecorderStateProvider::HandleInitialization(UTakeRecorder* RecorderPtr)
{
	if (RecorderPtr != nullptr)
	{
		// Set up event handlers for recording lifecycle transitions
		RecorderPtr->OnRecordingStarted().AddRaw(this, &FTakeRecorderStateProvider::HandleRecordingBegins);
		RecorderPtr->OnRecordingCancelled().AddRaw(this, &FTakeRecorderStateProvider::HandleRecordingEnds);
		RecorderPtr->OnRecordingFinished().AddRaw(this, &FTakeRecorderStateProvider::HandleRecordingEnds);

		// Initialize state to exit condition
		CurrentState = EStageCriticalStateEvent::Exit;
	}
}

void FTakeRecorderStateProvider::HandleRecordingBegins(UTakeRecorder* RecorderPtr)
{
	// Transition from Exit to Enter only once per session
	if (CurrentState == EStageCriticalStateEvent::Exit)
	{
		TakeName = RecorderPtr->GetSequence()->GetFName();
		CurrentState = EStageCriticalStateEvent::Enter;

		// Send reliable message indicating critical state entry
		IStageDataProvider::SendMessage<FCriticalStateProviderMessage>(
			EStageMessageFlags::Reliable,
			CurrentState,
			TakeName
		);
	}
}

void FTakeRecorderStateProvider::HandleRecordingEnds(UTakeRecorder* RecorderPtr)
{
	// Transition from Enter to Exit only when currently in Enter state
	if (CurrentState == EStageCriticalStateEvent::Enter)
	{
		CurrentState = EStageCriticalStateEvent::Exit;

		// Send reliable message indicating critical state exit
		IStageDataProvider::SendMessage<FCriticalStateProviderMessage>(
			EStageMessageFlags::Reliable,
			CurrentState,
			TakeName
		);
	}
}
#endif // WITH_EDITOR

