void showHelp() {
    std::cout << "Command line interface for InfiniCCL test suite" << std::endl
              << std::endl;
    std::cout << "Syntax:" << std::endl
              << std::endl;
    std::cout << "infiniccl-test --<device>" << std::endl
              << std::endl;
    std::cout << "  --<device>" << std::endl;
    std::cout << "    Choose the hardware backend: --(nvidia|cambricon|ascend|metax|moore|iluvatar|qy|kunlun|hygon|ali)." << std::endl
              << std::endl;
    std::cout << "The executable will execute tests across all accessible devices of the selected type. "
              << "Control device visibility via environment variables like CUDA_VISIBLE_DEVICES.";
    exit(-1);
}

#define MATCH_DEVICE(OPTION, ENUM) \
    if (input == OPTION) {         \
        options.target_device = ENUM; \
    }

CommandLineOptions parseInput(int argc, char *argv[]) {
    if (argc != 2) {
        showHelp();
    }

    std::string arg_str = argv[1];
    if (arg_str == "--help" || arg_str == "-h") {
        showHelp();
    }

    CommandLineOptions options{};
    try {
        std::string input = arg_str;
        // clang-format off
        MATCH_DEVICE("--nvidia", INFINI_DEVICE_NVIDIA)
        else MATCH_DEVICE("--cambricon", INFINI_DEVICE_CAMBRICON)
        else MATCH_DEVICE("--ascend", INFINI_DEVICE_ASCEND)
        else MATCH_DEVICE("--metax", INFINI_DEVICE_METAX)
        else MATCH_DEVICE("--moore", INFINI_DEVICE_MOORE)
        else MATCH_DEVICE("--iluvatar", INFINI_DEVICE_ILUVATAR)
        else MATCH_DEVICE("--qy", INFINI_DEVICE_QY)
        else MATCH_DEVICE("--kunlun", INFINI_DEVICE_KUNLUN)
        else MATCH_DEVICE("--hygon", INFINI_DEVICE_HYGON)
        else MATCH_DEVICE("--ali", INFINI_DEVICE_ALI)
        else {
            showHelp();
        }
        // clang-format on
    } catch (...) {
        showHelp();
    }
    return options;
}

int main(int argc, char *argv[]) {
    CommandLineOptions options = parseInput(argc, argv);

    int device_count = 0;
    infinirtInit();

    if (infinirtGetDeviceCount(options.target_device, &device_count) != INFINI_STATUS_SUCCESS) {
        std::cerr << "Error: Unable to retrieve device count for the specified backend." << std::endl;
        return -1;
    }

    if (device_count == 0) {
        std::cout << "No compatible devices detected. Skipping test execution." << std::endl;
        return 0;
    } else {
        std::cout << "Detected " << device_count << " device(s). Proceeding with tests..." << std::endl;
    }

    int errors = 0;
    errors += testAllReduce(options.target_device, device_count);
    return errors;
}

