#include <pthread.h>
#include "libcgo.h"

// Retrieve the stack bounds for the current thread
void x_cgo_getstackbound(uintptr bounds[2]) {
    pthread_attr_t attr;
    void *stack_addr = nullptr;
    size_t stack_size = 0;

    // Initialize the attribute structure
    pthread_attr_init(&attr);

#if defined(__GLIBC__) || defined(__BIONIC__) || (defined(__sun) && !defined(__illumos__))
    // Use GNU extension or Solaris-specific function to get thread attributes
    pthread_getattr_np(pthread_self(), &attr);  // GNU/Linux/Bionic extension
    pthread_attr_getstack(&attr, &stack_addr, &stack_size); // retrieves lower bound and size
#elif defined(__illumos__)
    // Illumos-specific variant
    pthread_attr_get_np(pthread_self(), &attr);
    pthread_attr_getstack(&attr, &stack_addr, &stack_size);
#else
    // Unsupported platform: fall back to zeroed values
    stack_addr = nullptr;
    stack_size = 0;
#endif

    // Clean up attribute object
    pthread_attr_destroy(&attr);

    // Synchronize with TSan to avoid false positives on stack reuse
    _cgo_tsan_acquire();
    bounds[0] = reinterpret_cast<uintptr>(stack_addr);
    bounds[1] = bounds[0] + stack_size;
    _cgo_tsan_release();
}

#include "ReduceGlobalVarInitializers.h"
#include "llvm/IR/Constants.h"
#include "llvm/IR/GlobalValue.h"
using namespace llvm;

/// Clears initializers for global variables outside the target chunks
static void extractGVsFromModule(Oracle &O, ReducerWorkItem &WorkItem) {
  auto &M = WorkItem.getModule();

  // Iterate through all global variables using range-based loop
  for (auto GV_iter = M.global_begin(); GV_iter != M.global_end(); ++GV_iter) {
    auto &GV = *GV_iter;

    // Check if this global has an initializer and should be excluded
    if (GV.hasInitializer()) {
      if (!O.shouldKeep(GV)) {  // Assuming Oracle::shouldKeep takes a GV parameter
        GV.setInitializer(nullptr);
        GV.setLinkage(GlobalValue::ExternalLinkage);
        GV.setComdat(nullptr);
      }
    }
  }
}

void llvm::reduceGlobalsInitializersDeltaPass(TestRunner &Test) {
  runDeltaPass(Test, extractGVsFromModule, "Reducing Global Variable Initializers");
}

