// Structure to hold memory pool usage metrics
struct memPoolMetrics
{
    std::uint64_t currentReserved;
    std::uint64_t peakReserved;
    std::uint64_t currentUsed;
    std::uint64_t peakUsed;
};

// Retrieve current and high-watermark memory usage from the pool
void fetchPoolStats(hipMemPool_t pool, memPoolMetrics *metrics)
{
    HIP_CHECK(hipMemPoolGetAttribute(pool, hipMemPoolAttrReservedMemCurrent, &metrics->currentReserved));
    HIP_CHECK(hipMemPoolGetAttribute(pool, hipMemPoolAttrReservedMemHigh, &metrics->peakReserved));
    HIP_CHECK(hipMemPoolGetAttribute(pool, hipMemPoolAttrUsedMemCurrent, &metrics->currentUsed));
    HIP_CHECK(hipMemPoolGetAttribute(pool, hipMemPoolAttrUsedMemHigh, &metrics->peakUsed));
}

// Reset high-watermark counters to current values
void resetPeakCounters(hipMemPool_t pool)
{
    std::uint64_t zero = 0;
    HIP_CHECK(hipMemPoolSetAttribute(pool, hipMemPoolAttrReservedMemHigh, &zero));
    HIP_CHECK(hipMemPoolSetAttribute(pool, hipMemPoolAttrUsedMemHigh, &zero));
}

int main()
{
    hipMemPool_t pool;
    hipDevice_t devId = 0; // Device index to use

    // Set active device
    HIP_CHECK(hipSetDevice(devId));

    // Obtain default memory pool for the device
    HIP_CHECK(hipDeviceGetDefaultMemPool(&pool, devId));

    // Perform a test allocation: 1 MiB
    constexpr std::size_t allocSize = 1024 * 1024;
    void* buffer = nullptr;
    HIP_CHECK(hipMalloc(&buffer, allocSize));

    // Release the allocated memory back to the pool
    HIP_CHECK(hipFree(buffer));

    // Trim the pool's reserved memory to 512 KiB
    constexpr std::size_t targetSize = 512 * 1024;
    HIP_CHECK(hipMemPoolTrimTo(pool, targetSize));

    // Capture statistics before resetting peaks
    memPoolMetrics preReset;
    fetchPoolStats(pool, &preReset);

    std::cout << "Before resetting high-watermarks:" << std::endl;
    std::cout << "  Reserved (current): " << preReset.currentReserved << " bytes" << std::endl;
    std::cout << "  Reserved (max):     " << preReset.peakReserved << " bytes" << std::endl;
    std::cout << "  Used (current):     " << preReset.currentUsed << " bytes" << std::endl;
    std::cout << "  Used (max):         " << preReset.peakUsed << " bytes" << std::endl;

    // Reset high-watermark counters
    resetPeakCounters(pool);

    // Capture statistics after resetting peaks
    memPoolMetrics postReset;
    fetchPoolStats(pool, &postReset);

    std::cout << "After resetting high-watermarks:" << std::endl;
    std::cout << "  Reserved (current): " << postReset.currentReserved << " bytes" << std::endl;
    std::cout << "  Reserved (max):     " << postReset.peakReserved << " bytes" << std::endl;
    std::cout << "  Used (current):     " << postReset.currentUsed << " bytes" << std::endl;
    std::cout << "  Used (max):         " << postReset.peakUsed << " bytes" << std::endl;

    return EXIT_SUCCESS;
}

