    A obj; // Calls default constructor: A()

    A staticArray[3]; // Creates array of 3 objects: A() A() A()

    A* dynamicArray = new A[3]; // Dynamically allocates array of 3 objects: A() A() A()

    delete[] dynamicArray; // Deallocates dynamic array and calls destructors: ~A() ~A() ~A()

