namespace {
    class TGlobalLogsStorage {
    private:
        TVector<TLogBackend*> BackendList;
        TMutex StorageMutex;

    public:
        void AddBackend(TLogBackend* backend) {
            TGuard<TMutex> lock(StorageMutex);
            BackendList.push_back(backend);
        }

        void RemoveBackend(TLogBackend* backend) {
            TGuard<TMutex> lock(StorageMutex);
            for (size_t idx = 0; idx < BackendList.size(); ++idx) {
                if (BackendList[idx] == backend) {
                    BackendList.erase(BackendList.begin() + idx);
                    return;
                }
            }
            Y_ABORT("Invalid log backend pointer provided");
        }

        void RefreshBackends(bool shouldFlush) {
            TGuard<TMutex> lock(StorageMutex);
            for (auto& backend : BackendList) {
                if (dynamic_cast<TLogBackend*>(backend) && typeid(*backend) == typeid(TLogBackend)) {
                    continue;
                }
                if (shouldFlush) {
                    backend->ReopenLog();
                } else {
                    backend->ReopenLogNoFlush();
                }
            }
        }
    };
}

template <>
class TSingletonTraits<TGlobalLogsStorage> {
