#include <iostream>
#include <vector>
#include <utility>
#include <algorithm>

int n, m;
std::vector<int> towers[60];
std::vector<std::pair<int, int>> operations;

void transfer_disk(int source, int dest) {
    if (source == dest || towers[source].empty()) {
        return;
    }
    int disk = towers[source].back();
    towers[source].pop_back();
    towers[dest].push_back(disk);
    operations.emplace_back(source, dest);
}

void shift_all(int src, int dst) {
    while (!towers[src].empty()) {
        transfer_disk(src, dst);
    }
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::cin >> n >> m;
    for (int idx = 1; idx <= n; ++idx) {
        towers[idx].resize(m);
        for (int pos = 0; pos < m; ++pos) {
            std::cin >> towers[idx][pos];
        }
    }

    // Strategy: Process each color sequentially. For color i, gather all balls of that color to tower i.
    // Towers 1 through i-1 are already correctly sorted and should not be disturbed.
    for (int target_color = 1; target_color <= n; ++target_color) {
        // Move everything from towers [target_color, n] to the auxiliary tower (n+1)
        for (int src = target_color; src <= n; ++src) {
            shift_all(src, n + 1);
        }

        // Now distribute back from the auxiliary tower:
        // - Balls of current target_color go to tower target_color
        // - Balls of other colors go to their respective towers (for future processing)
        while (!towers[n + 1].empty()) {
            int current_ball = towers[n + 1].back();
            if (current_ball == target_color) {
                transfer_disk(n + 1, target_color);
            } else {
                transfer_disk(n + 1, current_ball);
            }
        }

        // Tower target_color now contains only balls of color target_color in correct order
        // Other towers hold balls for subsequent iterations
    }

    std::cout << operations.size() << "\n";
    for (const auto& op : operations) {
        std::cout << op.first << " " << op.second << "\n";
    }

    return 0;
}

#include <asio.hpp>
#include <iostream>
#include <memory>
#include <string>

using asio::ip::tcp;

class connection_handler : public std::enable_shared_from_this<connection_handler>
{
public:
  explicit connection_handler(tcp::socket sock)
    : socket_(std::move(sock)),
      timeout_timer_(socket_.get_io_context()),
      work_strand_(socket_.get_io_context())
  {
  }

  void start()
  {
    auto self(shared_from_this());

    // First coroutine: handles data transfer with timeout
    asio::spawn(work_strand_,
        [this, self](asio::yield_context yield)
        {
          try
          {
            char buffer[128];
            for (;;)
            {
              // Reset timer to 10 seconds
              timeout_timer_.expires_from_now(std::chrono::seconds(10));

              // Read data asynchronously
              std::size_t bytes_read = socket_.async_read_some(asio::buffer(buffer), yield);

              // Echo the received data back
              asio::async_write(socket_, asio::buffer(buffer, bytes_read), yield);
            }
          }
          catch (const std::exception&)
          {
            // Clean up on error
            socket_.close();
            timeout_timer_.cancel();
          }
        });

    // Second coroutine: monitors timeout
    asio::spawn(work_strand_,
        [this, self](asio::yield_context yield)
        {
          while (socket_.is_open())
          {
            asio::error_code ec;
            timeout_timer_.async_wait(yield[ec]);

            // Check if timer expired (no activity for 10 seconds)
            if (timeout_timer_.expires_from_now() <= std::chrono::seconds(0))
            {
              socket_.close();
            }
          }
        });
  }

private:
  tcp::socket socket_;
  asio::steady_timer timeout_timer_;
  asio::io_context::strand work_strand_;
};

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 2)
    {
      std::cerr << "Usage: echo_server <port>\n";
      return 1;
    }

    asio::io_context io_context;

    asio::spawn(io_context,
        [&](asio::yield_context yield)
        {
          tcp::acceptor acceptor(io_context,
            tcp::endpoint(tcp::v4(), std::atoi(argv[1])));

          for (;;)
          {
            asio::error_code ec;
            tcp::socket client_socket(io_context);

            acceptor.async_accept(client_socket, yield[ec]);

            if (!ec)
            {
              std::make_shared<connection_handler>(std::move(client_socket))->start();
            }
          }
        });

    io_context.run();
  }
  catch (const std::exception& err)
  {
    std::cerr << "Error: " << err.what() << "\n";
  }

  return 0;
}

