// Custom shutdown flag using atomic-like semantics
struct ShutdownFlag {
    std::mutex mtx;
    std::condition_variable cv;
    bool value = false;

    void set() {
        std::lock_guard<std::mutex> lock(mtx);
        value = true;
        cv.notify_all();
    }

    bool check() const {
        std::lock_guard<std::mutex> lock(mtx);
        return value;
    }

    void wait() {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this] { return value; });
    }
} shutdown_flag;

void handleTerminationSignal(int) {
    spdlog::warn("Received termination signal ({})", std::signal(SIGINT, SIG_IGN));
    shutdown_flag.set();
}

void launchServer(const std::string& addr) {
    QubitEngineServiceImpl impl;
    grpc::ServerBuilder builder;
    builder.AddListeningPort(addr, grpc::InsecureServerCredentials());
    builder.RegisterService(&impl);

    // Optional reflection plugin (commented as original)
    // grpc::reflection::InitProtoReflectionServerBuilderPlugin();

    auto server_ptr = builder.BuildAndStart();
    spdlog::set_level(spdlog::level::debug);
    spdlog::set_pattern("[%Y-%m-%d %H:%M:%S.%e] [%^%l%$] [thread %t] %v");

    spdlog::info("QubitEngine listening at {}", addr);
    spdlog::info("QubitEngine v2 (Debug) - VisualizeCircuit active");

    QuantumMetrics::Instance().Start();

    // Wait until shutdown requested
    do {
        std::this_thread::sleep_for(std::chrono::milliseconds(500));
    } while (!shutdown_flag.check());

    spdlog::info("Initiating graceful shutdown...");
    server_ptr->Shutdown();
}

#ifdef MPI_ENABLED
#include <mpi.h>
#endif

int main(int argc, char* argv[]) {
#ifdef MPI_ENABLED
    MPI_Init(&argc, &argv);
    int my_rank = 0, total_ranks = 1;
    MPI_Comm_rank(MPI_COMM_WORLD, &my_rank);
    MPI_Comm_size(MPI_COMM_WORLD, &total_ranks);

    if (my_rank == 0) {
        spdlog::info("MPI cluster initialized with {} ranks", total_ranks);
        launchServer("0.0.0.0:50051");
    } else {
        try {
            sw::redis::Redis redis_conn("tcp://localhost:6379");
            spdlog::info("Worker rank {} connected to Redis.", my_rank);

            do {
                // Non-blocking probe for incoming MPI messages
                int msg_pending = 0;
                MPI_Status st;
                MPI_Iprobe(MPI_ANY_SOURCE, MPI_ANY_TAG, MPI_COMM_WORLD, &msg_pending, &st);

                // Poll Redis queue with 1s timeout
                auto job_opt = redis_conn.bzpopmax("queue:jobs", 1);
                if (job_opt) {
                    spdlog::info("Rank {} processed job '{}'", my_rank, std::get<1>(*job_opt));
                    // executeJob(std::get<1>(*job_opt)); // placeholder hook
                }
            } while (!shutdown_flag.check());
        } catch (const sw::redis::Error& ex) {
            spdlog::critical("Redis exception: {}", ex.what());
        }
    }

    MPI_Finalize();
#else
    // Standalone mode: single-node gRPC server only
    launchServer("0.0.0.0:50051");
#endif

    return 0;
}

#include <fstream>
#include <iostream>

struct StudentRecord {
    int studentId;
    char fullName[64];
    double gpa;

    // Display student information
    void display() const {
        std::cout << "ID: " << studentId 
                  << " | Name: " << fullName 
                  << " | GPA: " << gpa << std::endl;
    }
};

// Writes a student record to the database file in append mode
void persistStudent(const char* filePath, const StudentRecord& record) {
    std::ofstream file(filePath, std::ios::app);
    if (!file.is_open()) return;

    // Format: ID<TAB>Name<TAB>GPA<NEWLINE>
    file << record.studentId << "\t" 
         << record.fullName << "\t" 
         << record.gpa << "\n";
    file.close();
}

// Reads all student records from file and prints them
void retrieveAndShowStudents(const char* filePath) {
    std::ifstream inputFile(filePath);
    if (!inputFile) {
        std::cerr << "Failed to open file for reading." << std::endl;
        return;
    }

    StudentRecord entry;
    std::cout << "--- STUDENT LIST ---" << std::endl;

    while (inputFile >> entry.studentId) {
        // Skip the tab character after the ID
        inputFile.ignore(1, '\t');

        // Read name up to the next tab
        inputFile.getline(entry.fullName, 64, '\t');

        // Read GPA value
        inputFile >> entry.gpa;

        // Consume the newline at end of line
        inputFile.ignore(100, '\n');

        entry.display();
    }

    inputFile.close();
}

int main() {
    const char* databasePath = "student_records.txt";

    StudentRecord firstStudent = { 12345, "Ivan Ivanov", 5.50 };
    StudentRecord secondStudent = { 55555, "Maria Petrova", 6.00 };

    // Save students to persistent storage
    persistStudent(databasePath, firstStudent);
    persistStudent(databasePath, secondStudent);

    // Load and display stored students
    retrieveAndShowStudents(databasePath);

    return 0;
}

#include "server.hpp"
