namespace http {
namespace server4 {

server::server(asio::io_context& io_context,
    const std::string& addr, const std::string& port_str,
    boost::function<void(const request&, reply&)> handler)
  : request_handler_(handler)
{
  tcp::resolver resolver(io_context);
  auto endpoints = resolver.resolve(addr, port_str);
  asio::ip::tcp::endpoint ep = *endpoints.begin();
  acceptor_.reset(new tcp::acceptor(io_context, ep));
}

#include <asio/yield.hpp>

void server::operator()(asio::error_code ec, std::size_t bytes_transferred)
{
  if (!ec)
  {
    reenter (this)
    {
      // Accept connections in a loop
      do
      {
        socket_.reset(new tcp::socket(acceptor_->get_executor().context()));
        yield acceptor_->async_accept(*socket_, *this);

        // Spawn a new coroutine for each accepted connection
        fork server(*this)();
      } while (is_parent());

      // Prepare buffers and request object for reading client data
      buffer_.reset(new boost::array<char, 8192>);
      request_.reset(new request);
      valid_request_ = boost::indeterminate;

      // Keep reading until we have a full valid request or detect an error
      do
      {
        yield socket_->async_read_some(asio::buffer(*buffer_), *this);
        boost::tie(valid_request_, boost::tuples::ignore)
          = request_parser_.parse(*request_,
              buffer_->data(), buffer_->data() + bytes_transferred);
      } while (boost::indeterminate(valid_request_));

      // Prepare reply object
      reply_.reset(new reply);

      if (valid_request_)
      {
        // Process the valid request using the provided handler
        request_handler_(*request_, *reply_);
      }
      else
      {
        // Return standard bad request response for invalid input
        *reply_ = reply::stock_reply(reply::bad_request);
      }

      // Send the prepared reply back to the client
      yield asio::async_write(*socket_, reply_->to_buffers(), *this);

      // Gracefully close the connection
      socket_->shutdown(tcp::socket::shutdown_both, ec);
    }
  }
  // On error: coroutine terminates; all resources are automatically cleaned up
}

