#if LINEAR_MEMORY_BOUNDS_CHECKS

uint8_t* MemoryHelper::extensionRequest(uint64_t const requiredMinLinearMemSize,
                                        uint32_t const baseDataSectionSize,
                                        uint8_t* const currentLinearMemBase) VB_NOEXCEPT {
    // Early exit if total needed exceeds 32-bit address space
    if ((requiredMinLinearMemSize + baseDataSectionSize) > UINT32_MAX) {
        return nullptr;
    }

    uint32_t const requiredLinearMemSize_32 = static_cast<uint32_t>(requiredMinLinearMemSize);

    Runtime& runtimeRef = *readFromPtr<Runtime*>(pSubI(currentLinearMemBase, Basedata::FromEnd::runtimePtrOffset));
    ExtendableMemory& memManager = runtimeRef.jobMemory_;

    uint32_t const wasmPagesAllocated = readFromPtr<uint32_t>(
        pSubI(currentLinearMemBase, Basedata::FromEnd::linMemWasmSize)
    );
    uint32_t const currentUsedLinearMemSize = readFromPtr<uint32_t>(
        pSubI(currentLinearMemBase, Basedata::FromEnd::actualLinMemByteSize)
    );

    uint32_t const totalRequiredSize = baseDataSectionSize + requiredLinearMemSize_32;
    // Round up to next even number (align to 2 bytes)
    uint32_t const alignedTotalReqSize = (totalRequiredSize + 1U) & ~1_U32;

    // Case 1: Already enough linear memory available
    if (requiredLinearMemSize_32 <= currentUsedLinearMemSize) {
        return memManager.data();
    }

    // Case 2: Requested size exceeds current Wasm heap capacity → trap
    if (requiredLinearMemSize_32 > (wasmPagesAllocated * WasmConstants::wasmPageSize)) {
        return numToP<uint8_t*>(~static_cast<uintptr_t>(0)); // invalid flag
    }

    // Case 3: Enough memory already allocated in ExtendableMemory
    if (memManager.size() >= alignedTotalReqSize) {
        uint8_t* const uninitializedStart = pAddI(currentLinearMemBase, currentUsedLinearMemSize);
        size_t const bytesToZero = static_cast<size_t>(requiredLinearMemSize_32) - static_cast<size_t>(currentUsedLinearMemSize);
        std::memset(uninitializedStart, 0x00, bytesToZero);

        writeToPtr<uint32_t>(
            pSubI(currentLinearMemBase, Basedata::FromEnd::actualLinMemByteSize),
            requiredLinearMemSize_32
        );
        return memManager.data(); // no reallocation occurred
    }

    // Case 4: Need to grow ExtendableMemory
    if (!memManager.hasExtensionRequest()) {
        return nullptr; // cannot grow without callback
    }

    memManager.extensionRequest(alignedTotalReqSize);

    if (memManager.data() != nullptr && memManager.size() >= alignedTotalReqSize) {
        uint8_t* const newLinearBase = pAddI(memManager.data(), baseDataSectionSize);
        uint8_t* const newUninitStart = pAddI(newLinearBase, currentUsedLinearMemSize);
        size_t const bytesToClear = static_cast<size_t>(requiredLinearMemSize_32) - static_cast<size_t>(currentUsedLinearMemSize);
        std::memset(newUninitStart, 0x00, bytesToClear);

        writeToPtr<uint32_t>(
            pSubI(newLinearBase, Basedata::FromEnd::actualLinMemByteSize),
            requiredLinearMemSize_32
        );
        return memManager.data();
    } else {
        return nullptr; // reallocation failed or insufficient size
    }
}

#else

bool MemoryHelper::notifyOfMemoryGrowth(uint8_t* const linearMemBase,
                                        uint32_t const newMemSizeInPages) VB_NOEXCEPT {
    Runtime const& runtimeRef = *readFromPtr<Runtime*>(
        pSubI(linearMemBase, Basedata::FromEnd::runtimePtrOffset)
    );
    return runtimeRef.extendMemory(newMemSizeInPages);
}

