// Convert character to index: 'A'-'Z' -> 0-25, '0'-'9' -> 26-35
inline int char_to_index(char c) {
    if (c >= 'A' && c <= 'Z') {
        return static_cast<int>(c - 'A');
    }
    // Input is guaranteed to be uppercase letters or digits per problem constraints
    return static_cast<int>(c - '0' + 26);
}

// Find longest common subsequence using greedy matching strategy
// s_target: string we iterate through
// positions: precomputed list of indices for each character in s_source
std::string build_subsequence(const std::string& s_target, const std::vector<std::vector<int>>& positions) {
    std::string result;
    if (s_target.empty()) {
        return result;
    }

    result.reserve(s_target.size());

    int last_matched_pos = -1;
    std::vector<int> current_ptr(36, 0);  // pointers into each character's position list

    for (char ch : s_target) {
        int idx = char_to_index(ch);
        auto& pos_list = positions[idx];
        int& ptr = current_ptr[idx];

        // Skip positions that are before or at the last matched position
        while (ptr < static_cast<int>(pos_list.size()) && pos_list[ptr] <= last_matched_pos) {
            ++ptr;
        }

        // If we found a valid position, include this character
        if (ptr < static_cast<int>(pos_list.size())) {
            result.push_back(ch);
            last_matched_pos = pos_list[ptr];
            ++ptr;
        }
    }

    return result;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::string str_a, str_b;
    std::cin >> str_a >> str_b;

    // Precompute character positions for both strings
    std::vector<std::vector<int>> char_positions_a(36);
    std::vector<std::vector<int>> char_positions_b(36);

    for (size_t i = 0; i < str_a.length(); ++i) {
        char_positions_a[char_to_index(str_a[i])].push_back(static_cast<int>(i));
    }
    for (size_t i = 0; i < str_b.length(); ++i) {
        char_positions_b[char_to_index(str_b[i])].push_back(static_cast<int>(i));
    }

    // Try both directions: A→B and B→A
    std::string candidate_1 = build_subsequence(str_a, char_positions_b);
    std::string candidate_2 = build_subsequence(str_b, char_positions_a);

    // Output the longer result
    if (candidate_1.length() > candidate_2.length()) {
        std::cout << candidate_1 << '\n';
    } else {
        std::cout << candidate_2 << '\n';
    }

    return 0;
}

