using namespace std;

int main() {
    // Optimize I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    int median1 = (n + 1) / 2;
    int median2 = n / 2 + 1;

    vector<int> pool(n);
    iota(pool.begin(), pool.end(), 1);

    vector<int> known_pair;

    // Initialize random number generator with time-based seed
    unsigned seed = chrono::steady_clock::now().time_since_epoch().count();
    mt19937 rng(seed);

    while (pool.size() > 2) {
        // Create index array and shuffle to pick two distinct positions
        vector<int> indices(pool.size());
        iota(indices.begin(), indices.end(), 0);
        shuffle(indices.begin(), indices.end(), rng);

        int pos1 = indices[0];
        int pos2 = indices[1];
        int candidate1 = pool[pos1];
        int candidate2 = pool[pos2];

        vector<int> test_set;

        if (pool.size() > 4) {
            // Build query set excluding the two candidates
            for (size_t i = 0; i < pool.size(); ++i) {
                if (i != pos1 && i != pos2) {
                    test_set.push_back(pool[i]);
                }
            }
        } else {
            // Handle case when only 4 elements remain
            for (size_t i = 0; i < pool.size(); ++i) {
                if (i != pos1 && i != pos2) {
                    test_set.push_back(pool[i]);
                }
            }
            // Add previously confirmed pair as padding
            test_set.push_back(known_pair[0]);
            test_set.push_back(known_pair[1]);
        }

        // Output query
        cout << "0 " << test_set.size();
        for (int val : test_set) {
            cout << " " << val;
        }
        cout << endl;

        // Read response
        int res1, res2;
        cin >> res1 >> res2;

        if (res1 == median1 && res2 == median2) {
            if (pool.size() > 4) {
                // Record successful discard pair
                known_pair = {candidate1, candidate2};

                // Update pool by removing selected candidates
                vector<int> new_pool;
                for (size_t i = 0; i < pool.size(); ++i) {
                    if (i != pos1 && i != pos2) {
                        new_pool.push_back(pool[i]);
                    }
                }
                pool = new_pool;
            } else {
                // Found the medians among remaining candidates
                vector<int> result;
                for (size_t i = 0; i < pool.size(); ++i) {
                    if (i != pos1 && i != pos2) {
                        result.push_back(pool[i]);
                    }
                }
                cout << "1 " << result[0] << " " << result[1] << endl;
                return 0;
            }
        }
        // If condition not met, continue loop to try another pair
    }

    return 0;
}

#include "flareqt/updatechecker.h"
#include <QNetworkReply>

UpdateChecker::UpdateChecker(QUrl const& updateUrl)
    : networkManager_(new QNetworkAccessManager(this),
                      &QNetworkAccessManager::deleteLater) {
  connect(networkManager_.data(), &QNetworkAccessManager::finished, this,
          &UpdateChecker::onRequestCompleted);
  networkManager_->get(QNetworkRequest(updateUrl));
}

void UpdateChecker::onRequestCompleted(QNetworkReply* pReply) {
  QSharedPointer<QNetworkReply> reply(pReply, &QNetworkReply::deleteLater);

  // Handle network errors first
  if (reply->error() != QNetworkReply::NoError) {
    emit checkCompleted(true);  // true indicates error occurred
    return;
  }

  // Extract and sanitize the version string from response
  QByteArray rawData = reply->readAll();
  QString candidateVersion = QString::fromUtf8(rawData).trimmed();

  // Validate format: must contain at least one dot (e.g., "1.0")
  if (candidateVersion.indexOf('.') == -1) {
    emit checkCompleted(true);  // invalid format treated as error
    return;
  }

  // Store successful result
  latestVersion_ = candidateVersion;
  emit checkCompleted(false);  // false indicates success
}

#include <iostream>
#include <string>
#include <asio.hpp>

using asio::ip::tcp;

int main(int argc, char* argv[]) {
    try {
        if (argc != 3) {
            std::cerr << "Usage: sync_client <server> <path>\n";
            std::cerr << "Example:\n";
            std::cerr << "  sync_client www.boost.org /LICENSE_1_0.txt\n";
            return 1;
        }

        asio::io_context io_ctx;

        // Resolve the server address and port
        tcp::resolver resolver(io_ctx);
        auto endpoints = resolver.resolve(argv[1], "http");

        // Create and connect socket
        tcp::socket sock(io_ctx);
        asio::connect(sock, endpoints);

        // Build HTTP GET request
        asio::streambuf req_buf;
        std::ostream req_stream(&req_buf);
        req_stream << "GET " << argv[2] << " HTTP/1.0\r\n"
                   << "Host: " << argv[1] << "\r\n"
                   << "Accept: */*\r\n"
                   << "Connection: close\r\n\r\n";

        // Send the complete request
        asio::write(sock, req_buf);

        // Read response status line
        asio::streambuf resp_buf;
        asio::read_until(sock, resp_buf, "\r\n");

        // Parse and validate HTTP version and status code
        std::istream resp_stream(&resp_buf);
        std::string version;
        unsigned int code;
        std::getline(resp_stream >> version >> code, version); // consume rest of line

        if (version.substr(0, 5) != "HTTP/" || !resp_stream) {
            std::cerr << "Invalid HTTP response\n";
            return 1;
        }

        if (code != 200) {
            std::cerr << "HTTP error: " << code << "\n";
            return 1;
        }

        // Read headers until blank line
        asio::read_until(sock, resp_buf, "\r\n\r\n");

        // Print headers
        std::string header;
        while (std::getline(resp_stream, header) && header != "\r") {
            if (!header.empty() && header.back() == '\r') {
                header.pop_back();
            }
            std::cout << header << "\n";
        }
        std::cout << "\n";

        // Output remaining content in buffer
        if (resp_buf.size() > 0) {
            std::cout << &resp_buf;
        }

        // Read remaining body data
        asio::error_code ec;
        while (asio::read(sock, resp_buf, asio::transfer_at_least(1), ec)) {
            if (resp_buf.size() > 0) {
                std::cout << &resp_buf;
            }
        }

        if (ec != asio::error::eof) {
            throw asio::system_error(ec);
        }
    }
    catch (const std::exception& ex) {
        std::cerr << "Error: " << ex.what() << "\n";
        return 1;
    }

    return 0;
}

