// Helper to build dominator tree from scratch
static void constructDomTree(CgFunction &F, CgDomTree &tree) {
    // Reset existing structure if any
    tree.reset();
    // Build new dominator tree using standard algorithm
    tree.buildFrom(F);
}

CgDominatorTree::CgDominatorTree(CgFunction &func)
    : ContextObject(func.getContext()) {
    runOnCgFunction(func);
#ifdef ZEN_ENABLE_MULTIPASS_JIT_LOGGING
    llvm::dbgs() << "\n########## DomTree ##########\n\n";
    dump();
#endif
    func.DomTree = this;
}

void CgDominatorTree::runOnCgFunction(CgFunction &func) {
    computeTree(func);
}

void CgDominatorTree::computeTree(CgFunction &func) {
    // Allocate fresh dominator tree instance
    auto treePtr = std::make_unique<CgDomTree>();
    constructDomTree(func, *treePtr);
    // Transfer ownership
    DT = treePtr.release();
}

void CgDominatorTree::releaseMemory() {
    if (DT) {
        delete DT;
        DT = nullptr;
    }
}

void CgDominatorTree::print(raw_ostream &OS) const {
    if (DT) {
        DT->print(OS);
    }
}

