// Evaluate bitvector literal expressions
void evaluate_bitvector_literals(SMTParser::ParserPtr& parser) {
    std::vector<std::string> test_cases = {
        "#b1010",                     // 4-bit binary representation
        "#x1A",                       // hexadecimal literal (26 decimal)
        "(_ bv42 8)",                 // 42 encoded as 8-bit bitvector
        "(_ bv255 8)"                 // 255 encoded as 8-bit bitvector
    };

    std::cout << "=== Bitvector Literal Evaluation ===" << std::endl;
    for (std::size_t idx = 0; idx < test_cases.size(); ++idx) {
        const std::string& expr_str = test_cases[idx];
        std::cout << "Input: " << expr_str << std::endl;
        auto eval_result = parser->mkExpr(expr_str);
        assert(eval_result && !eval_result->isErr());
        std::cout << "Output: " << parser->toString(eval_result) << "\n\n";
    }
}

// Verify logical operations on bitvectors
void verify_bv_logical_ops(SMTParser::ParserPtr& parser) {
    std::vector<std::string> ops_list = {
        "(bvnot #b1010)",
        "(bvand #b1010 #b1100)",
        "(bvor #b1010 #b1100)",
        "(bvxor #b1010 #b1100)",
        "(bvnand #b1010 #b1100)",
        "(bvnor #b1010 #b1100)",
        "(bvxnor #b1010 #b1100)"
    };

    std::cout << "=== Bitvector Logical Operations ===" << std::endl;
    for (const auto& op_expr : ops_list) {
        std::cout << "Expression: " << op_expr << std::endl;
        auto res_node = parser->mkExpr(op_expr);
        assert(res_node && !res_node->isErr());
        std::cout << "Result: " << parser->toString(res_node) << "\n\n";
    }
}

// Validate arithmetic operations on bitvectors
void validate_bv_arithmetic(SMTParser::ParserPtr& parser) {
    std::vector<std::string> arith_exprs = {
        "(bvneg #b0101)",
        "(bvadd #b0101 #b0011)",
        "(bvsub #b1010 #b0011)",
        "(bvmul #b0101 #b0011)",
        "(bvudiv #b1010 #b0011)",
        "(bvurem #b1010 #b0011)",
        "(bvshl #b0101 #b0011)",
        "(bvlshr #b1010 #b0001)",
        "(bvashr #b1010 #b0001)"
    };

    std::cout << "=== Bitvector Arithmetic Validation ===" << std::endl;
    for (const auto& arith : arith_exprs) {
        std::cout << "Expr: " << arith << std::endl;
        auto computed = parser->mkExpr(arith);
        assert(computed && !computed->isErr());
        std::cout << "Computed: " << parser->toString(computed) << "\n\n";
    }
}

// Check comparison results for signed/unsigned relations
void check_bv_comparisons(SMTParser::ParserPtr& parser) {
    std::vector<std::string> cmp_tests = {
        "(bvult #b0101 #b1010)",     // unsigned less than
        "(bvule #b0101 #b0101)",     // unsigned ≤
        "(bvugt #b1010 #b0101)",     // unsigned greater than
        "(bvuge #b0101 #b0101)",     // unsigned ≥
        "(bvslt #b0101 #b1010)",     // signed less than
        "(bvsle #b0101 #b0101)",     // signed ≤
        "(bvsgt #b0000 #b1111)",     // signed greater than
        "(bvsge #b0101 #b0101)"      // signed ≥
    };

    std::cout << "=== Bitvector Comparison Checks ===" << std::endl;
    for (const auto& cmp : cmp_tests) {
        std::cout << "Comparison: " << cmp << std::endl;
        auto outcome = parser->mkExpr(cmp);
        assert(outcome && (outcome->isTrue() || outcome->isFalse()));
        std::cout << "Outcome: " << parser->toString(outcome) << "\n\n";
    }
}

int main() {
    std::cout << "====== Bitvector Operation Test Suite ======" << std::endl;

    SMTParser::ParserPtr parser = SMTParser::newParser();

    evaluate_bitvector_literals(parser);
    verify_bv_logical_ops(parser);
    validate_bv_arithmetic(parser);
    check_bv_comparisons(parser);

    return 0;
}

