    void Platform::set_resolver(unsigned int if_ndx, quic::Address dns, bool global)
    {
        linux::DBUS _dbus{"org.freedesktop.resolve1", "/org/freedesktop/resolve1", "org.freedesktop.resolve1.Manager"};

        // Configure basic link settings first
        _dbus("SetLinkDefaultRoute", "ib", (int32_t)if_ndx, false);
        _dbus("SetLinkDNSOverTLS", "is", (int32_t)if_ndx, "off");

        // Handle DNS address configuration based on IP version
        if (dns.is_ipv6())
        {
            const auto& addr = dns.in6().sin6_addr.s6_addr;
            static_assert(sizeof(addr) == 16);

            // Build IPv6 DNS entry as byte array
            std::array<uint8_t, 16> ipv6_bytes;
            for (size_t i = 0; i < 16; ++i)
                ipv6_bytes[i] = addr[i];

            _dbus(
                "SetLinkDNSEx",
                "ia(iayqs)",
                (int32_t)if_ndx,
                (int)1,             // one DNS server entry
                (int32_t)AF_INET6,  // IPv6 family
                (int)16,            // 16-byte address
                // Pass bytes individually
                ipv6_bytes[0], ipv6_bytes[1], ipv6_bytes[2],  ipv6_bytes[3],
                ipv6_bytes[4], ipv6_bytes[5], ipv6_bytes[6],  ipv6_bytes[7],
                ipv6_bytes[8], ipv6_bytes[9], ipv6_bytes[10], ipv6_bytes[11],
                ipv6_bytes[12], ipv6_bytes[13], ipv6_bytes[14], ipv6_bytes[15],
                dns.port(),
                nullptr  // no SNI support needed
            );
        }
        else
        {
            // Extract IPv4 address bytes
            uint32_t raw_addr = dns.in4().sin_addr.s_addr;
            std::array<uint8_t, 4> ipv4_bytes;
            for (int i = 0; i < 4; ++i)
                ipv4_bytes[i] = reinterpret_cast<uint8_t*>(&raw_addr)[i];

            _dbus(
                "SetLinkDNSEx",
                "ia(iayqs)",
                (int32_t)if_ndx,
                (int)1,            // one DNS server entry
                (int32_t)AF_INET,  // IPv4 family
                (int)4,            // 4-byte address
                ipv4_bytes[0], ipv4_bytes[1], ipv4_bytes[2], ipv4_bytes[3],
                dns.port(),
                nullptr  // no SNI support needed
            );
        }

        // Configure domain routing behavior
        if (global)
        {
            // Use root domain for highest priority resolution
            _dbus(
                "SetLinkDomains",
                "ia(sb)",
                (int32_t)if_ndx,
                (int)1,
                "."
            );
        }
        else
        {
            // Restrict to internal domains only
            _dbus(
                "SetLinkDomains",
                "ia(sb)",
                (int32_t)if_ndx,
                (int)3,
                "sesh", (int)1,
                "snode", (int)1,
                "loki", (int)1
            );
        }
    }
}  // namespace srouter::dns::sd
#endif

