namespace duckdb {

FdServerTransport::FdServerTransport() : is_connected(false) {
}

FdServerTransport::~FdServerTransport() {
    Disconnect();
}

bool FdServerTransport::Connect() {
    std::lock_guard<std::mutex> guard(io_mutex);
    if (is_connected) {
        return true;
    }
    is_connected = true;
    return true;
}

void FdServerTransport::Disconnect() {
    std::lock_guard<std::mutex> guard(io_mutex);
    is_connected = false;
}

bool FdServerTransport::IsConnected() const {
    return is_connected;
}

void FdServerTransport::Send(const MCPMessage &msg) {
    if (!IsConnected()) {
        MCP_LOG_ERROR("stdio", "Send invoked while not connected");
        throw IOException("Connection not established");
    }

    std::lock_guard<std::mutex> guard(io_mutex);
    try {
        std::string json_payload = msg.ToJSON();
        MCP_LOG_DEBUG("stdio", "Outgoing message (truncated): %s", json_payload.substr(0, 100).c_str());

        // Output to stdout and force immediate flush
        std::cout << json_payload << '\n';
        std::cout.flush();

        MCP_LOG_DEBUG("stdio", "Message successfully transmitted and flushed");
    } catch (const std::exception &err) {
        MCP_LOG_ERROR("stdio", "Transmission failure: %s", err.what());
        throw IOException(std::string("Send operation failed: ") + err.what());
    }
}

MCPMessage FdServerTransport::Receive() {
    if (!IsConnected()) {
        MCP_LOG_ERROR("stdio", "Receive invoked while not connected");
        throw IOException("Connection not established");
    }

    std::lock_guard<std::mutex> guard(io_mutex);
    try {
        MCP_LOG_DEBUG("stdio", "Awaiting input from stdin...");

        std::string input_line;
        if (!std::getline(std::cin, input_line)) {
            MCP_LOG_DEBUG("stdio", "Input stream reached EOF or encountered error");
            throw IOException("Input stream terminated prematurely");
        }

        MCP_LOG_DEBUG("stdio", "Received line (%zu bytes): %s", input_line.size(), input_line.substr(0, 100).c_str());

        if (input_line.empty()) {
            MCP_LOG_WARN("stdio", "Empty line received");
            throw IOException("Invalid empty message");
        }

        return MCPMessage::FromJSON(input_line);
    } catch (const IOException &) {
        throw;
    } catch (const std::exception &err) {
        MCP_LOG_ERROR("stdio", "Parsing or reception error: %s", err.what());
        throw IOException(std::string("Message reception failed: ") + err.what());
    }
}

MCPMessage FdServerTransport::SendAndReceive(const MCPMessage &msg) {
    // In server mode, bidirectional request-response via this method is unsupported
    throw NotImplementedException("SendAndReceive is not applicable in server mode");
}

bool FdServerTransport::Ping() {
    return IsConnected();
}

std::string FdServerTransport::GetConnectionInfo() const {
    return "stdio server transport (stdin/stdout)";
}

