// Helper function to run inference once and print results
void run_inference(
    AutoModel& model,
    const lm_uniform_input_t& input,
    const chat_meta_info_t& meta,
    int max_tokens,
    bool show_profile = true
) {
    std::cout << "Response: ";
    model.start_total_timer();
    std::string result = model.generate_with_prompt(meta, input, max_tokens, std::cout);
    model.stop_total_timer();
    std::cout << std::endl << std::endl;
    if (show_profile) {
        std::cout << model.show_profile() << std::endl;
    }
}

int main(int argc, char* argv[]) {
#ifdef __WINDOWS__
    SetConsoleOutputCP(CP_UTF8);
    SetConsoleCP(CP_UTF8);
    SetThreadPriority(GetCurrentThread(), THREAD_PRIORITY_LOWEST);
#endif

    // Parse command-line arguments
    arg_utils::po::options_description opts("Supported options");
    arg_utils::po::variables_map config;
    opts.add_options()
        ("model,m", arg_utils::po::value<std::string>()->required(), "Path to model file")
        ("Short,s", arg_utils::po::value<bool>()->default_value(true), "Use short prompt")
        ("Preemption,p", arg_utils::po::value<bool>()->default_value(false), "Enable preemption");

    arg_utils::po::store(arg_utils::po::parse_command_line(argc, argv, opts), config);
    arg_utils::po::notify(config);

    std::string selected_model = config["model"].as<std::string>();
    bool use_short_prompt = config["Short"].as<bool>();
    bool enable_preemption = config["Preemption"].as<bool>();

    std::cout << "Selected Model: " << selected_model << std::endl;

    std::string exe_path = utils::get_executable_directory();
    std::string models_root = utils::get_models_directory();
    std::string list_file = exe_path + "/model_list.json";

    model_list loader(list_file, models_root);

    header_print("info", "Initializing chat model...");
    std::string model_path = loader.get_model_path(selected_model);
    auto [name, info_json] = loader.get_model_info(selected_model);
    std::cout << "Model path: " << model_path << std::endl;

    npu_device_global = xrt::device(0);  // Ensure device is initialized before use
    std::unique_ptr<AutoModel> engine = std::make_unique<Qwen2VL>(&npu_device_global);

    engine->load_model(model_path, info_json, -1, enable_preemption);
    engine->set_topk(1);
    engine->set_topp(0.8f);
    engine->set_temperature(0.7f);
    engine->set_repetition_penalty(1.01f);
    engine->set_frequency_penalty(1.01f);

    chat_meta_info_t session_meta;
    lm_uniform_input_t current_input;

    if (use_short_prompt) {
        current_input.prompt = "What is this?";
        std::cout << "Prompt: " << current_input.prompt << std::endl;
        current_input.images.emplace_back("../../../tb_files/panda.png");

        // Run three times as in original
        for (int i = 0; i < 3; ++i) {
            run_inference(*engine, current_input, session_meta, 1024);
            // Reuse same image and prompt for next iteration
        }
    } else {
        std::ifstream prompt_file("../../../../prompt.txt", std::ios::binary);
        if (!prompt_file.is_open()) {
            std::cerr << "Error: Could not open prompt file" << std::endl;
            return 1;
        }

        // Read entire file content into string
        prompt_file.seekg(0, std::ios::end);
        size_t size = prompt_file.tellg();
        prompt_file.seekg(0, std::ios::beg);
        current_input.prompt.resize(size);
        prompt_file.read(current_input.prompt.data(), size);
        prompt_file.close();

        std::cout << "Prompt: " << current_input.prompt << std::endl;
        run_inference(*engine, current_input, session_meta, 1024);
    }

    // Output history info
    auto [text_hist, token_ids] = engine->get_history();
    std::cout << "History length: " << token_ids.size() << std::endl;
    std::cout << std::endl;

    return 0;
}

#include "WifiTypeConfigurator.h"

std::string WifiTypeConfigurator::configure(TerminalTypeEnum& terminalType) {
    switch (terminalType)
    {
    case TerminalTypeEnum::WiFiClient:
        #if defined(DEVICE_CARDPUTER)
            // Configure cardputer-specific WiFi setup
            setupCardputerWifi(); // blocks until a valid network is found and connected
        #elif defined(DEVICE_STICKS3)
            // Initialize WiFi using stored credentials on StickS3
            setupStickWifi(); // attempts connection using saved credentials
        #elif defined(DEVICE_TEMBEDS3) || defined(DEVICE_TEMBEDS3CC1101)
            // TEmbedS3 family uses view-based UI for WiFi selection
            setupTembedWifi(view); // waits until successful connection
        #elif defined(DEVICE_TDISPLAYS3)
            // TDisplayS3 has its own display-driven WiFi setup
            setupTdisplayWifi(view); // loops until connection established
        #else
            // Default ESP32 configuration fallback
            setupS3Wifi(); // tries to reconnect using previously stored settings
        #endif
        return std::string(WiFi.localIP().toString().c_str());
    case TerminalTypeEnum::WiFiAp: {
        // Access Point mode does not require returning an IP string
        return "";
    }
    default:
        // Unsupported or unknown terminal type
        break;
    }
    return "";
}

