#include "llvm/Support/circular_raw_ostream.h"
#include <cstring>
using namespace llvm;

void circular_raw_ostream::write_impl(const char *Ptr, size_t Size) {
  if (BufferSize == 0) {
    TheStream->write(Ptr, Size);
    return;
  }

  // Process each byte individually for clarity
  const char* currentPtr = Ptr;
  size_t remaining = Size;

  while (remaining > 0) {
    // Calculate available space in buffer from current position
    size_t spaceAvailable = BufferSize;
    if (Filled) {
      spaceAvailable = BufferArray + BufferSize - Cur;
    } else {
      spaceAvailable = BufferArray + BufferSize - Cur;
    }

    // Determine how many bytes we can write in this chunk
    size_t chunkSize = std::min(remaining, spaceAvailable);

    // Copy data to buffer
    std::memcpy(Cur, currentPtr, chunkSize);

    // Update pointers and counters
    currentPtr += chunkSize;
    remaining -= chunkSize;
    Cur += chunkSize;

    // Handle buffer wrap-around
    if (Cur >= BufferArray + BufferSize) {
      Cur = BufferArray;
      Filled = true;
    }
  }
}

void circular_raw_ostream::flushBufferWithBanner() {
  if (BufferSize != 0) {
    // Output the banner first
    const char* bannerPtr = Banner;
    while (*bannerPtr != '\0') {
      TheStream->write(bannerPtr, 1);
      ++bannerPtr;
    }
    // Then flush the buffer contents
    flushBuffer();
  }
}

#include <vector>
#include <algorithm>
#include <cmath>

class Solution {
public:
    int maxAbsoluteSum(std::vector<int>& nums) {
        int n = nums.size();

        // Track current positive and negative running sums
        int currentMax = 0;
        int currentMin = 0;
        int globalMax = 0;
        int globalMin = 0;

        for (int i = 0; i < n; ++i) {
            // Update running sums
            currentMax += nums[i];
            currentMin += nums[i];

            // Update global extremes
            if (currentMax > globalMax) {
                globalMax = currentMax;
            }
            if (currentMin < globalMin) {
                globalMin = currentMin;
            }

            // Reset running sums when they go against our goal
            if (currentMax < 0) {
                currentMax = 0;
            }
            if (currentMin > 0) {
                currentMin = 0;
            }
        }

        return std::max(globalMax, std::abs(globalMin));
    }
};

