namespace arch {

    [[gnu::weak]] void disable_interrupts() {
        __asm__ volatile("cli");
    }

    [[gnu::weak]] void enable_interrupts() {
        __asm__ volatile("sti");
    }

    [[gnu::weak]] void wait_for_interrupt() {
        __asm__ volatile("hlt");
    }

    [[gnu::weak]] void hcf() {
        disable_interrupts();
        for (;;) {
            wait_for_interrupt();
        }
    }

    [[gnu::weak]] void pause() {
        __asm__ volatile("pause");
    }

    [[gnu::weak]] void tlb_flush(std::uintptr_t addr_hint, std::uintptr_t range_len) {
        const std::size_t page_count = range_len / PAGE_SIZE;
        if (page_count > 256 || range_len == 0) {
            std::uint64_t cr3_val;
            __asm__ volatile("mov %%cr3, %0" : "=r"(cr3_val) :: "memory");
            __asm__ volatile("mov %0, %%cr3" : : "r"(cr3_val) :: "memory");
        } else {
            for (std::uintptr_t offset = 0; offset < range_len; offset += PAGE_SIZE) {
                __asm__ volatile("invlpg (%0)" : : "r"(addr_hint + offset) : "memory");
            }
        }
    }

    [[gnu::weak]] const char* architecture_name() {
        return "x86_64";
    }

    [[gnu::weak]] int paging_depth() {
        return bootloader::bootloader->is_5_level_paging() ? 5 : 4;
    }

    [[gnu::weak]] void initialize(int phase) {
        if (phase == ARCH_INIT_EARLY) {
            x86_64::init_cpu_data();
            drivers::hpet::init();
            drivers::tsc::init();
            x86_64::gdt::init();
            x86_64::idt::init();
            x86_64::lapic::init(1500);
            drivers::ioapic::init();
        }
        // ARCH_INIT_COMMON case does nothing explicitly
    }

    [[gnu::weak]] void fatal_error(char* reason) {
        x86_64::panic::print_ascii_art();
        klibc::printf("Panic with message \"%s\"\r\n", reason);
    }

    [[gnu::weak]] int install_handler(int irq_num, int handler_type, std::uint64_t flags,
                                      void (*handler)(void*), void* context) {
        return x86_64::irq::create(irq_num, handler_type, handler, context, flags);
    }
}

