// Constructs an InputStreamReader using the default character encoding
// Parameters:
// in - Input stream to wrap
InputStreamReader::InputStreamReader(InputStream *in) : stream( new DataInputStream( in ) )
{
}

// Releases resources and closes the underlying input stream
// After closing, any further operations on this reader will fail
void InputStreamReader::close()
{
	stream->close();
}

// Reads one UTF character from the stream
// Returns:
// The character value, or -1 if no more data is available
int InputStreamReader::read()
{
	return stream->readUTFChar();
}

// Fills a portion of the provided character buffer with data from the stream
// Parameters:
// cbuf - Target array for characters
// offset - Starting index in the array where characters should be placed
// length - Maximum number of characters to read
// Returns:
// Number of characters successfully read, or -1 if end-of-stream is reached immediately
int InputStreamReader::read(wchar_t cbuf[], unsigned int offset, unsigned int length)
{
	unsigned int count = 0;
	unsigned int pos = offset;

	while (pos < offset + length)
	{
		int ch = stream->readUTFChar();
		if (ch != -1)
		{
			cbuf[pos] = static_cast<wchar_t>(ch);
			count++;
			pos++;
		}
		else
		{
			break;
		}
	}

	return (count > 0 || length == 0) ? static_cast<int>(count) : -1;
}

