// Renamed and slightly refactored version of original main logic
int run_ndb_example(const char* socketPath, const char* clusterConnect) {
    MYSQL dbConn;
    mysql_init(&dbConn);
    mysql_connect_and_create(dbConn, socketPath);

    ndb_init();

    // Establish connection to NDB cluster
    Ndb_cluster_connection cluster_conn(clusterConnect);
    if (cluster_conn.connect(4, 5, 1) != 0) {
        std::cerr << "Unable to connect to cluster within 30 seconds." << std::endl;
        exit(EXIT_FAILURE);
    }

    // Wait until storage nodes are ready
    if (cluster_conn.wait_until_ready(30, 0) < 0) {
        std::cerr << "Cluster did not become ready within 30 seconds." << std::endl;
        exit(EXIT_FAILURE);
    }

    // Initialize NDB object
    Ndb myNdb(&cluster_conn, "ndb_examples");
    if (myNdb.init(1024) == -1) {
        std::cerr << "Failed to initialize NDB: " << myNdb.getNdbError().message << std::endl;
        exit(EXIT_FAILURE);
    }

    /*******************************************
     * Validate table schema                   *
     *******************************************/
    int colorColumnIndex = -1;
    {
        const NdbDictionary::Dictionary* dict = myNdb.getDictionary();
        const NdbDictionary::Table* table = dict->getTable("api_scan");
        if (!table) {
            std::cerr << "Dictionary::getTable() failed." << std::endl;
            exit(EXIT_FAILURE);
        }

        Car sampleCar{};
        const NdbDictionary::Column* colColor = table->getColumn("COLOR");
        const NdbDictionary::Column* colBrand = table->getColumn("BRAND");

        if (!colColor || !colBrand ||
            colColor->getLength() != sizeof(sampleCar.color) ||
            colBrand->getLength() != sizeof(sampleCar.brand)) {
            std::cerr << "Incorrect table definition detected." << std::endl;
            exit(EXIT_FAILURE);
        }

        colorColumnIndex = colColor->getColumnNo();
    }

    // Populate data
    if (populate(&myNdb) > 0)
        std::cout << "Data population completed successfully!" << std::endl;

    // Print initial state
    if (scan_print(&myNdb) > 0)
        std::cout << "Initial scan output:" << std::endl;

    // Delete all pink cars
    {
        Car targetCar{};
        snprintf(targetCar.color, sizeof(targetCar.color), "Pink");
        if (scan_delete(&myNdb, colorColumnIndex, targetCar.color) > 0)
            std::cout << "Deletion of pink cars completed successfully!" << std::endl;
    }

    // Print after deletion
    if (scan_print(&myNdb) > 0)
        std::cout << "Post-deletion scan:" << std::endl;

    // Update all Blue cars to Black
    {
        Car oldCar{}, newCar{};
        snprintf(oldCar.color, sizeof(oldCar.color), "Blue");
        snprintf(newCar.color, sizeof(newCar.color), "Black");

        std::cout << "Updating all '" << oldCar.color << "' entries to '" 
                  << newCar.color << "'..." << std::endl;

        if (scan_update(&myNdb, colorColumnIndex, oldCar.color, newCar.color) > 0)
            std::cout << "Update operation completed successfully!" << std::endl;
    }

    // Final print
    if (scan_print(&myNdb) > 0)
        std::cout << "Final scan result:" << std::endl;

    ndb_end(0);
    mysql_close(&dbConn);
    return 0;
}

