#include <iostream>

int main(int argc, char** argv) {
  // Define type alias for convenience
  using EeVelConstr_t = switched_model::EndEffectorVelocityConstraint<3, 2>;

  // Initialize constraint with default settings
  switched_model::EndEffectorVelocityConstraintSettings cfg;
  EeVelConstr_t eeVelConstraint(cfg);

  // Prepare evaluation point: (time, state, input)
  EeVelConstr_t::scalar_t t = 0.0;
  EeVelConstr_t::state_vector_t x = EeVelConstr_t::state_vector_t::Ones();
  EeVelConstr_t::input_vector_t u = EeVelConstr_t::input_vector_t::Ones();

  // Set desired end-effector velocity to constant value
  cfg.desiredEndEffectorVelocity.fill(1.5);

  // Compute constraint values and first-order approximations
  auto constraintVals = eeVelConstraint.getValue(t, x, u);
  auto linearized = eeVelConstraint.getLinearApproximation(t, x, u);

  // Output results
  std::cout << "Constraint residuals:" << std::endl;
  for (const auto& val : constraintVals) {
    std::cout << val << std::endl;
  }

  std::cout << "Jacobian w.r.t. state:" << std::endl;
  for (const auto& row : linearized.derivativeState) {
    std::cout << row.transpose() << std::endl;
  }

  std::cout << "Jacobian w.r.t. input:" << std::endl;
  for (const auto& row : linearized.derivativeInput) {
    std::cout << row.transpose() << std::endl;
  }

  return 0;
}

