class Solution {
public:
    std::vector<int> dailyTemperatures(std::vector<int>& temp) {
        int n = temp.size();
        std::vector<int> result(n, 0);

        // Process each day from left to right
        for (int current_day = 0; current_day < n; ++current_day) {
            // Look ahead for the next warmer day
            for (int future_day = current_day + 1; future_day < n; ++future_day) {
                if (temp[future_day] > temp[current_day]) {
                    result[current_day] = future_day - current_day;
                    break;
                }
            }
        }

        return result;
    }
};

