// Global modulus for the computation
long long MOD;

// Modular multiplication using __int128 to avoid overflow
long long mod_mul(long long x, long long y, long long m) {
    return static_cast<long long>((static_cast<__int128>(x) * y) % m);
}

// Computes bit-length of a number: floor(log2(x)) + 1 for x > 0, else 0
int bit_length(long long val) {
    if (val == 0) return 0;
    return 64 - __builtin_clzll(val);
}

// Queries the device with value 'a' and returns measured time
long long query_time(long long a) {
    std::cout << "? " << a << std::endl;
    long long t;
    std::cin >> t;
    return t;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    // Read modulus
    std::cin >> MOD;

    // Secret exponent accumulator
    long long secret_exp = 0;

    // Random number generator seeded with high-resolution clock
    std::mt19937_64 prng(std::chrono::steady_clock::now().time_since_epoch().count());

    // Recover each bit of the secret exponent (assume up to 60 bits)
    for (int bit_pos = 0; bit_pos < 60; ++bit_pos) {
        long double accumulated_score = 0.0L;
        const int sample_count = 40;

        for (int sample_idx = 0; sample_idx < sample_count; ++sample_idx) {
            // Generate random base in [2, MOD-1]
            long long base_val = std::uniform_int_distribution<long long>(2, MOD - 1)(prng);

            // Query total time for this base
            long long total_duration = query_time(base_val);

            // Precompute powers: base^(2^i) mod MOD for i = 0..59
            std::vector<long long> power_vals(60);
            std::vector<int> power_bit_lens(60);

            power_vals[0] = base_val;
            for (int i = 1; i < 60; ++i) {
                power_vals[i] = mod_mul(power_vals[i - 1], power_vals[i - 1], MOD);
            }

            for (int i = 0; i < 60; ++i) {
                power_bit_lens[i] = bit_length(power_vals[i]) + 1;
            }

            // Compute constant part C(a): sum of squared bit lengths
            long long const_part = 0;
            for (int i = 0; i < 60; ++i) {
                const_part += static_cast<long long>(power_bit_lens[i]) * power_bit_lens[i];
            }

            // Simulate known portion of exponentiation process
            long long current_state = 1;
            long long known_cost = 0;

            for (int i = 0; i < bit_pos; ++i) {
                if ((secret_exp >> i) & 1) {
                    known_cost += static_cast<long long>(bit_length(current_state) + 1) * power_bit_lens[i];
                    current_state = mod_mul(current_state, power_vals[i], MOD);
                }
            }

            // Remaining time after subtracting known parts
            long long residual_time = total_duration - const_part - known_cost;

            // Cost contribution if current bit is 1
            long long cost_if_one = static_cast<long long>(bit_length(current_state) + 1) * power_bit_lens[bit_pos];

            // Score update: positive if residual time suggests d_k = 1
            accumulated_score += static_cast<long double>(residual_time) - static_cast<long double>(cost_if_one) / 2.0L;
        }

        // Decide bit value based on average score
        if (accumulated_score > 0.0L) {
            secret_exp |= (1LL << bit_pos);
        }
    }

    // Output recovered secret exponent
    std::cout << "! " << secret_exp << std::endl;
    return 0;
}

#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    // Optimize I/O operations for performance
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (cin >> n >> m) {
        // Initialize weights for each participant to 1.0
        vector<double> weights(n, 1.0);

        // Decay factor for incorrect predictions
        const double decay = 0.8; 

        for (int round = 0; round < m; ++round) {
            string predictions;
            cin >> predictions;

            // Compute weighted sums for each outcome
            double sum_zero = 0.0;
            double sum_one = 0.0;

            for (int i = 0; i < n; ++i) {
                if (predictions[i] == '0') {
                    sum_zero += weights[i];
                } else {
                    sum_one += weights[i];
                }
            }

            // Determine majority prediction based on weights
            char predicted_outcome = (sum_one > sum_zero) ? '1' : '0';
            cout << predicted_outcome << '\n';

            // Read actual result
            char actual_result;
            cin >> actual_result;

            // Apply penalty to underperforming participants
            double highest_weight = 0.0;
            for (int i = 0; i < n; ++i) {
                if (predictions[i] != actual_result) {
                    weights[i] *= decay;
                }
                if (weights[i] > highest_weight) {
                    highest_weight = weights[i];
                }
            }

            // Prevent numerical underflow by rescaling if needed
            if (highest_weight < 1e-150) {
                for (int i = 0; i < n; ++i) {
                    weights[i] *= 1e150;
                }
            }
        }
    }

    return 0;
}

