#include <vector>
#include <cmath>

class Solution {
public:
    long long expSum4[18];

    // Helper function to compute floor of log base 4 using iterative approach
    int getLogBase4(int x) {
        if (x <= 0) return 0;
        int log4 = 0;
        int power = 1; // 4^0 = 1
        while (power * 4 <= x) {
            power *= 4;
            log4++;
        }
        return log4;
    }

    long long expSum(unsigned x) {
        if (x == 0) return 0;

        // Calculate log base 4 using iterative method instead of countl_zero
        int log4 = getLogBase4(x);
        int base = 1 << (2 * log4); // equivalent to 4^log4
        int remainder = x - base;

        // Compute the sum using the precomputed table and formula
        return expSum4[log4] + static_cast<long long>(remainder) * (log4 + 1LL);
    }

    Solution() {
        // Initialize the expSum4 array with different approach
        expSum4[0] = 1;
        for (int i = 1; i < 18; i++) {
            // Alternative formulation: compute each term explicitly
            long long prev = expSum4[i-1];
            long long additional = 3LL * i * (1LL << (2 * (i-1))) + 1;
            expSum4[i] = prev + additional;
        }
    }

    long long minOperations(std::vector<std::vector<int>>& queries) {
        long long totalOps = 0;
        for (const auto& query : queries) {
            int left = query[0] - 1;
            int right = query[1];

            // Apply the formula with rearranged arithmetic
            long long val = expSum(right) - expSum(left);
            long long result = (val + 1) / 2;
            totalOps += result;
        }
        return totalOps;
    }
};

