// Helper function to check evenness with same behavior as bar
bool __attribute__ ((noinline)) bar(int x) {
    std::cout << "bar(" << x << ")" << std::endl;
    return (x & 1) == 0;  // Bitwise alternative to modulo for even check
}

// Wrapper function that delegates to bar, preserving original interface
bool __attribute__ ((noinline)) foo(int val) {
    std::cout << "foo(" << val << ")" << std::endl;
    return bar(val);
}

// Alternative implementation of boo using different control flow
inline bool boo(int val) {
    bool result;
    if (val % 3 != 0) {
        result = bar(val);
    } else {
        result = foo(val);
    }
    return result;
}

