// Renamed functions for clarity and distinction
void display_message_a() {
    std::cout << "some function!" << std::endl;
}

void display_message_b() {
    std::cout << "some other function!" << std::endl;
}

// Refactored class: same behavior, renamed members
struct example_data {
    int data_value = 30;

    double compute_result() const {
        return 24.5;
    }
};

int main(int, char*[]) {
    std::cout << "=== functions (all) ===" << std::endl;

    sol::state lua_vm;
    lua_vm.open_libraries(sol::lib::base);

    // Insert an instance of example_data into Lua environment
    lua_vm.set("instance", example_data{});

    // Bind free functions using different syntaxes
    lua_vm["func_a"] = display_message_a;
    lua_vm.set_function("func_b", &display_message_b);

    // Bind member function in two ways
    lua_vm["get_result"] = &example_data::compute_result;
    lua_vm.set_function(
        "get_result_bound",
        &example_data::compute_result,
        example_data{}); // pre-bound instance

    // Bind member variable as getter/setter in two ways
    lua_vm["access_data"] = &example_data::data_value;
    lua_vm.set_function(
        "access_data_bound",
        &example_data::data_value,
        example_data{}); // pre-bound instance

    // Execute Lua script with equivalent semantics
    lua_vm.script(R"(
        func_a() -- prints "some function!"
        func_b() -- prints "some other function!"

        -- Call unbound member function with explicit instance
        print(get_result(instance)) -- 24.5

        -- Bound version needs no instance
        print(get_result_bound()) -- 24.5

        -- Unbound variable accessor requires instance
        print(access_data(instance)) -- 30

        -- Bound variable accessor works standalone
        print(access_data_bound()) -- 30

        -- Modify unbound variable via instance
        access_data(instance, 212)

        -- Modify bound variable directly
        access_data_bound(254)

        -- Verify changes
        print(access_data(instance)) -- 212
        print(access_data_bound())   -- 254
    )");

    std::cout << std::endl;
    return 0;
}

