#include "../backend/src/QuantumRegister.hpp"
#include <benchmark/benchmark.h>
#include <iostream>

// Benchmark: Hadamard gate performance (memory-bandwidth limited)
static void BM_HadamardMemoryWall(benchmark::State &state) {
    const int qubitCount = state.range(0);

    try {
        // Allocate quantum register once before timing starts
        QuantumRegister reg(qubitCount);

        // Precompute size-related constants outside loop
        const uint64_t vecSize = 1ULL << qubitCount;
        const size_t bytesPerEntry = sizeof(std::complex<double>); // typically 16 bytes
        const double totalBytesPerIter = static_cast<double>(vecSize) * bytesPerEntry * 2.0;

        for (auto _ : state) {
            // Apply Hadamard to first qubit
            reg.applyHadamard(0);

            // Prevent compiler optimizations and ensure memory clobbering
            benchmark::DoNotOptimize(reg.getStateVector().data());
            benchmark::ClobberMemory();
        }

        // Report throughput in bytes/sec
        state.SetBytesProcessed(static_cast<int64_t>(state.iterations()) *
                                static_cast<int64_t>(totalBytesPerIter));
    } catch (const std::exception &ex) {
        state.SkipWithError("Allocation failed or insufficient memory");
    }
}

// Register benchmarks for specific problem sizes
BENCHMARK(BM_HadamardMemoryWall)
    ->Arg(20)   // ~16 MiB
    ->Arg(25)   // ~512 MiB
    ->Arg(28)   // ~4 GiB
    ->Unit(benchmark::kMillisecond);

BENCHMARK_MAIN();

