#include <iostream>
using namespace std;

int main() {
    int currentDistance;
    cin >> currentDistance;

    int previousColor = -1;  // indicates no prior move yet

    while (currentDistance > 0) {
        bool foundBetterMove = false;

        for (int color = 0; color < 3; ++color) {
            if (color == previousColor) continue;

            // Attempt to move in this direction
            cout << "move " << color << endl;
            int outcome;
            cin >> outcome;

            if (outcome == 1) {
                // Exit reached during the move
                return 0;
            }

            // Ask for updated distance after the move
            cout << "query" << endl;
            int updatedDistance;
            cin >> updatedDistance;

            if (updatedDistance < currentDistance) {
                // This move brought us closer to the exit
                currentDistance = updatedDistance;
                previousColor = color;
                foundBetterMove = true;
                break;
            } else {
                // Move led away or stayed same, so backtrack
                cout << "move " << color << endl;
                int backOutcome;
                cin >> backOutcome;

                if (backOutcome == 1) {
                    // Unexpectedly reached exit on return
                    return 0;
                }
                // Back at original position; distance remains unchanged
            }
        }

        // If no beneficial move was found in this iteration, loop again
        // (though logically with proper input this shouldn't happen)
        if (!foundBetterMove && currentDistance > 0) {
            // In case of stuck condition, just continue to next attempt
            continue;
        }
    }

    // When currentDistance reaches 0, we're at the destination
    return 0;
}

