namespace engine::store::filter::pipe {

// //-------------------------------------------------------------------------
// /// @details
// ///		Activates tracing for the current pipe stack instance
// //-------------------------------------------------------------------------
Error IFilterInstance::traceOn() noexcept {
    if (!m_filters.empty()) {
        m_tracingEnabled = true;
        // Rebuild the filter chain with tracing enabled
        auto tempChain = m_filters;
        for (auto& filter : tempChain) {
            filter->enableTrace();
        }
        m_activeChain = std::move(tempChain);
    }
    return {};
}

// //-------------------------------------------------------------------------
// /// @details
// ///		Deactivates tracing and restores the original filter configuration
// //-------------------------------------------------------------------------
Error IFilterInstance::traceOff() noexcept {
    if (m_tracingEnabled) {
        // Restore original filter setup without tracers
        m_activeChain = m_filters;
        // Release tracer resources
        m_tracers.clear();
        m_tracingEnabled = false;
    }
    return {};
}

// //-------------------------------------------------------------------------
// /// @details
// ///		Resets the trace logging buffer by removing all recorded entries
// //-------------------------------------------------------------------------
Error IFilterInstance::clearTrace() noexcept {
    if (m_tracingEnabled) {
        // Clear the trace history storage
        m_traceBuffer.erase(m_traceBuffer.begin(), m_traceBuffer.end());
    } else {
        // Even when tracing is off, we can clear any buffered data
        m_traceBuffer.clear();
    }
    return {};
}

}  // namespace engine::store::filter::pipe

