namespace rocdecode
{
namespace detail
{
// Internal storage for API table pointer
auto&
get_api_table_storage()
{
    static std::atomic<rocdecodeApiFuncTable*> s_table{ nullptr };
    return s_table;
}

// Helper to copy and initialize profiler-modified API table
void
setup_profiler_table(rocdecodeApiFuncTable* out_const,
                     rocdecodeApiFuncTable* out_mutable)
{
    initialize_rocdecode_api_table(out_const);
    get_api_table_storage().store(out_const, std::memory_order_relaxed);

    copy_rocdecode_api_table(out_mutable, out_const);
}

// Core registration routine — called once via call_once
void
perform_registration()
{
    static rocdecodeApiFuncTable const_api{};
    static rocdecodeApiFuncTable mutable_api{};

    setup_profiler_table(&const_api, &mutable_api);

    void* mutable_ptr = &mutable_api;
    rocprofiler_register_library_indentifier_t lib_id{};

    auto result = rocprofiler_register_library_api_table(
        "rocdecode",
        &ROCPROFILER_REGISTER_IMPORT_FUNC(rocdecode),
        ROCP_REG_VERSION,
        &mutable_ptr,
        1,
        &lib_id);

    if(result == 0)
    {
        printf("[%s] rocdecode identifier %lu\n", ROCP_REG_FILE_NAME, lib_id.handle);

        rocdecodeApiFuncTable* expected = &const_api;
        if(!get_api_table_storage().compare_exchange_strong(expected, &mutable_api))
        {
            std::cerr << "[ERROR] Expected internal implementation table, "
                         "but found something else. Aborting.\n";
            std::abort();
        }
    }
    else if(result != ROCP_REG_NO_TOOLS)
    {
        std::cerr << "[FATAL] Failed to register rocdecode with rocprofiler-register: "
                  << rocprofiler_register_error_string(result) << "\n";
        std::exit(EXIT_FAILURE);
    }
}

// Thread-safe lazy registration guard
void
ensure_registered()
{
    static std::atomic<bool> s_is_registered{ false };

    if(s_is_registered.load(std::memory_order_acquire))
        return;

    // Use recursive mutex to prevent deadlock on re-entrant calls during registration
    static std::recursive_mutex s_mutex{};
    static std::once_flag s_init_flag{};

    std::unique_lock<std::recursive_mutex> lock{s_mutex, std::defer_lock};

    // If this thread already owns the lock (re-entrancy), skip full registration logic
    if(lock.owns_lock()) return;

    lock.lock();

    std::call_once(s_init_flag, perform_registration);

    s_is_registered.store(true, std::memory_order_release);
}
}  // namespace detail

rocdecodeApiFuncTable*
get_rocdecode_api_table()
{
    detail::ensure_registered();
    return detail::get_api_table_storage().load(std::memory_order_relaxed);
}

void
rocdecode_init()
{
    printf("[%s] %s\n", ROCP_REG_FILE_NAME, __FUNCTION__);
}
}  // namespace rocdecode

extern "C" {

void
rocdecode_init(void)
{
    auto* api_table = rocdecode::get_rocdecode_api_table();
    if(api_table && api_table->rocDecCreateDecoder_fn)
        api_table->rocDecCreateDecoder_fn({}, {});
}

}  // extern "C"

#include <vector>
#include <string>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    std::vector<std::string> removeAnagrams(std::vector<std::string>& words) {
        // Handle empty input case
        if (words.empty()) return {};

        // Store sorted versions of each word to check anagram equivalence
        std::vector<std::string> sortedWords;
        for (const auto& word : words) {
            std::string sorted = word;
            std::sort(sorted.begin(), sorted.end());
            sortedWords.push_back(sorted);
        }

        // Build result by comparing adjacent sorted strings
        std::vector<std::string> result;
        result.push_back(words[0]);

        for (size_t i = 1; i < words.size(); ++i) {
            if (sortedWords[i] != sortedWords[i - 1]) {
                result.push_back(words[i]);
            }
        }

        return result;
    }
};

