        std::shared_ptr<SMTParser::DAGNode> exprResult = parser->mkExpr("true");
        assert(exprResult && exprResult->isTrue() && !exprResult->isFalse());
        std::cout << "Input: true" << std::endl;
        std::cout << "Parsed Output: " << parser->toString(exprResult) << std::endl;
        std::cout << "Verification: isTrue = yes" << std::endl;
    }

    {
        SMTParser::ParserPtr parser = SMTParser::newParser();
        std::shared_ptr<SMTParser::DAGNode> exprResult = parser->mkExpr("false");
        assert(exprResult && exprResult->isFalse() && !exprResult->isTrue());
        std::cout << "Input: false" << std::endl;
        std::cout << "Parsed Output: " << parser->toString(exprResult) << std::endl;
        std::cout << "Verification: isFalse = yes" << std::endl;
    }

    // Integer parsing verification
    std::cout << "\n--- Testing Integer Parsing ---" << std::endl;
    {
        SMTParser::ParserPtr parser = SMTParser::newParser();
        std::shared_ptr<SMTParser::DAGNode> intResult = parser->mkExpr("42");
        assert(intResult && parser->toString(intResult) == "42");
        std::cout << "Input: 42" << std::endl;
        std::cout << "Parsed Output: " << parser->toString(intResult) << std::endl;
    }

    // Real number parsing verification
    std::cout << "\n--- Testing Real Number Parsing ---" << std::endl;
    {
        SMTParser::ParserPtr parser = SMTParser::newParser();
        std::shared_ptr<SMTParser::DAGNode> realResult = parser->mkExpr("3.14");
        assert(realResult && parser->toString(realResult) == "3.14");
        std::cout << "Input: 3.14" << std::endl;
        std::cout << "Parsed Output: " << parser->toString(realResult) << std::endl;
    }

    // Complex expression parsing verification
    std::cout << "\n--- Testing Expression Parsing ---" << std::endl;
    {
        SMTParser::ParserPtr parser = SMTParser::newParser();
        std::shared_ptr<SMTParser::DAGNode> complexResult = parser->mkExpr("(and true false)");
        assert(complexResult && complexResult->isFalse());
        std::cout << "Input: (and true false)" << std::endl;
        std::cout << "Parsed Output: " << parser->toString(complexResult) << std::endl;
    }

    return 0;
}

#include <vector>
using namespace std;

class Solution {
public:
    vector<int> plusOne(vector<int>& digits) {
        int n = digits.size();
        vector<int> result = digits;

        // Add 1 to the last digit
        result[n-1] += 1;

        // Process carry from right to left
        for (int i = n - 1; i > 0; --i) {
            if (result[i] >= 10) {
                result[i] -= 10;
                result[i-1] += 1;
            } else {
                break; // No more carry, exit early
            }
        }

        // Handle carry for the first digit
        if (result[0] >= 10) {
            result[0] -= 10;
            result.insert(result.begin(), 1);
        }

        return result;
    }
};

