#include <ocs2_ballbot/generated/jsim.h>
#include <ocs2_ballbot/generated/transforms.h>
#include <ocs2_robotic_tools/rbd_libraries/robcogen/iit/rbd/rbd.h>
#include <ocs2_robotic_tools/rbd_libraries/robcogen/iit/rbd/traits/TraitSelector.h>

TEST(RobcogenModelTest, RobcogenModelValidation) {
  // Initialize joint state variables with random values
  iit::Ballbot::tpl::JointState<double> q, qd, qdd, tau;
  q << 0.5, 0.7, 3.0, 2.0, -1.0;
  qd << 0.5, 0.7, 3.0, 2.0, -1.0;
  qdd.setZero();
  tau << 3.5, 4.5, 6.5;

  // Prepare storage for gravity and Coriolis terms
  Eigen::Matrix<double, 5, 1> G_terms, C_terms;
  G_terms.fill(0.0);
  C_terms.fill(0.0);

  // Setup inertia properties and transformation objects
  using trait_t = typename iit::rbd::tpl::TraitSelector<double>::Trait;
  iit::Ballbot::dyn::tpl::InertiaProperties<trait_t> inertias;
  iit::Ballbot::tpl::ForceTransforms<trait_t> forceXforms;
  iit::Ballbot::tpl::MotionTransforms<trait_t> motionXforms;

  // Compute gravity and Coriolis-Centrifugal terms using inverse dynamics
  iit::Ballbot::dyn::tpl::InverseDynamics<trait_t> invdyn(inertias, motionXforms);
  invdyn.G_terms(G_terms, q);
  invdyn.C_terms(C_terms, q, qd);

  // Compute accelerations via forward dynamics
  iit::Ballbot::dyn::tpl::ForwardDynamics<trait_t> fwdDyn(inertias, motionXforms);
  fwdDyn.fd(qdd, q, qd, tau);

  // Output results for verification
  std::cout << "qdd from forward dynamics: " << qdd.transpose() << std::endl;
  std::cout << "Gravity terms (G): " << G_terms.transpose() << std::endl;

  // Second test case with different inputs
  q << 0.5, 0.7, 3.0, 2.0, -1.0;
  qd << 0.5, 0.7, 12.0, 2.0, -1.0;
  qdd.setZero();
  tau << 10.5, 4.5, 6.5;
  fwdDyn.fd(qdd, q, qd, tau);
  std::cout << "qdd from forward dynamics (second scenario): " << qdd.transpose() << std::endl;
}

