// Test to verify thread safety of UI printing functions under concurrent access
TEST(UIThreadSafetyTest, ConcurrentPrinting) {
  std::vector<std::thread> worker_threads;
  const int num_threads = 10;
  const int iterations_per_thread = 50;

  // Launch multiple threads that concurrently call UI print functions
  for (int t = 0; t < num_threads; ++t) {
    worker_threads.emplace_back([t, iterations_per_thread]() {
      for (int k = 0; k < iterations_per_thread; ++k) {
        // Construct unique identifiers and messages for each call
        std::string tool_name = "tool_" + std::to_string(t);
        std::string arg_json = "{\"arg\":" + std::to_string(k) + "}";
        std::string result_msg = "result_" + std::to_string(k);

        PrintToolCallMessage(tool_name, arg_json, "  ", 0);
        PrintToolResultMessage(tool_name, result_msg, "completed", "  ");
      }
    });
  }

  // Wait for all threads to complete execution
  for (auto& thread : worker_threads) {
    thread.join();
  }
}

