Y_UNIT_TEST_SUITE(TStrSpnTest) {
    Y_UNIT_TEST(FindFirstOf) {
        const TString text("some text!");

        // Check first character matching any of 'm', 'o', 's'
        UNIT_ASSERT_EQUAL(TCompactStrSpn("mos").FindFirstOf(text.begin(), text.end()), text.begin());
        UNIT_ASSERT_EQUAL(TCompactStrSpn("mos").FindFirstOf(text.c_str()), text.begin());

        // Check first occurrence of 'x' or 't'
        UNIT_ASSERT_EQUAL(TCompactStrSpn("xt").FindFirstOf(text.begin(), text.end()), text.begin() + 5);
        UNIT_ASSERT_EQUAL(TCompactStrSpn("xt").FindFirstOf(text.c_str()), text.begin() + 5);

        // Check first punctuation mark at end
        UNIT_ASSERT_EQUAL(TCompactStrSpn(".?!").FindFirstOf(text.begin(), text.end()), text.end() - 1);
        UNIT_ASSERT_EQUAL(TCompactStrSpn(".?!").FindFirstOf(text.c_str()), text.end() - 1);

        // Check no match case
        UNIT_ASSERT_EQUAL(TCompactStrSpn("abc").FindFirstOf(text.begin(), text.end()), text.end());
        UNIT_ASSERT_EQUAL(TCompactStrSpn("abc").FindFirstOf(text.c_str()), text.end());

        // Test with empty string (must be const to avoid side effects)
        const TString blank;
        UNIT_ASSERT_EQUAL(TCompactStrSpn("abc").FindFirstOf(blank.begin(), blank.end()), blank.end());
        UNIT_ASSERT_EQUAL(TCompactStrSpn("abc").FindFirstOf(blank.c_str()), blank.end());
    }

    Y_UNIT_TEST(FindFirstNotOf) {
        const TString data("abacabaxyz");

        // Characters not in "123" start from the very beginning
        UNIT_ASSERT_EQUAL(TCompactStrSpn("123").FindFirstNotOf(data.begin(), data.end()), data.begin());
        UNIT_ASSERT_EQUAL(TCompactStrSpn("123").FindFirstNotOf(data.c_str()), data.begin());

        // First character not in "abc" is 'y' at position 7
        UNIT_ASSERT_EQUAL(TCompactStrSpn("abc").FindFirstNotOf(data.begin(), data.end()), data.begin() + 7);
        UNIT_ASSERT_EQUAL(TCompactStrSpn("abc").FindFirstNotOf(data.c_str()), data.begin() + 7);

        // First character not in "abcxy" is 'z' at second-to-last position
        UNIT_ASSERT_EQUAL(TCompactStrSpn("abcxy").FindFirstNotOf(data.begin(), data.end()), data.end() - 1);
        UNIT_ASSERT_EQUAL(TCompactStrSpn("abcxy").FindFirstNotOf(data.c_str()), data.end() - 1);

        // All characters matched when pattern includes "abcxyz"
        UNIT_ASSERT_EQUAL(TCompactStrSpn("abcxyz").FindFirstNotOf(data.begin(), data.end()), data.end());
        UNIT_ASSERT_EQUAL(TCompactStrSpn("abcxyz").FindFirstNotOf(data.c_str()), data.end());

        // Empty string tests
        const TString blank;
        UNIT_ASSERT_EQUAL(TCompactStrSpn("abc").FindFirstNotOf(blank.begin(), blank.end()), blank.end());
        UNIT_ASSERT_EQUAL(TCompactStrSpn("abc").FindFirstNotOf(blank.c_str()), blank.end());
    }

    Y_UNIT_TEST(FindFirstOfReverse) {
        TStringBuf s("some text");

        // Reverse search for 'x' or 't' should find 't' at the end first
        UNIT_ASSERT_EQUAL(TCompactStrSpn("xt").FindFirstOf(s.rbegin(), s.rend()), s.rbegin());

        // Reverse search for 'm', 'o', 's' finds 's' near the end
        UNIT_ASSERT_EQUAL(TCompactStrSpn("mos").FindFirstOf(s.rbegin(), s.rend()), s.rend() - 3);

        // Reverse search for 's' finds it at last position
        UNIT_ASSERT_EQUAL(TCompactStrSpn("s").FindFirstOf(s.rbegin(), s.rend()), s.rend() - 1);

        // No match in reverse
        UNIT_ASSERT_EQUAL(TCompactStrSpn("abc").FindFirstOf(s.rbegin(), s.rend()), s.rend());

        // Empty string test
        TStringBuf blank;
        UNIT_ASSERT_EQUAL(TCompactStrSpn("abc").FindFirstOf(blank.rbegin(), blank.rend()), blank.rend());
    }

    Y_UNIT_TEST(FindFirstNotOfReverse) {
        TStringBuf s("_abacabaxyz");

        // First char not in "abc" from the end is '_'
        UNIT_ASSERT_EQUAL(TCompactStrSpn("abc").FindFirstNotOf(s.rbegin(), s.rend()), s.rbegin());

        // First char not in "xyz" from the end is 'a' at offset 3
        UNIT_ASSERT_EQUAL(TCompactStrSpn("xyz").FindFirstNotOf(s.rbegin(), s.rend()), s.rbegin() + 3);

        // First char not in "abcxyz" from the end is '_' near beginning
        UNIT_ASSERT_EQUAL(TCompactStrSpn("abcxyz").FindFirstNotOf(s.rbegin(), s.rend()), s.rend() - 1);

        // All chars matched when including underscore
        UNIT_ASSERT_EQUAL(TCompactStrSpn("abcxyz_").FindFirstNotOf(s.rbegin(), s.rend()), s.rend());

        // Empty string test
        TStringBuf blank;
        UNIT_ASSERT_EQUAL(TCompactStrSpn("abc").FindFirstNotOf(blank.rbegin(), blank.rend()), blank.rend());
    }
} // Y_UNIT_TEST_SUITE(TStrSpnTest)

