using namespace aeronet;

/// Demonstrates TLS session ticket setup for resumption.
///
/// Enables 0-RTT resumption via tickets, avoiding server-side cache.
///
/// Verification with OpenSSL:
///   # Initial handshake, save session
///   openssl s_client -connect localhost:8443 -sess_out session.pem
///
///   # Resumed handshake, reuse saved session
///   openssl s_client -connect localhost:8443 -sess_in session.pem
int main(int argc, char** argv) {
  if (argc < 3 || argc > 5) {
    std::cerr << "Usage: " << argv[0] << " <cert.pem> <key.pem> [port] [--static-key]\n\n";
    std::cerr << "Options:\n";
    std::cerr << "  --static-key  Use fixed session ticket encryption key (no rotation)\n";
    return EXIT_FAILURE;
  }

  std::string certFile = argv[1];
  std::string keyFile  = argv[2];
  uint16_t listenPort = 8443;
  bool enableStaticKey = false;

  int idx = 3;
  while (idx < argc) {
    std::string token = argv[idx];
    if ("--static-key" == token) {
      enableStaticKey = true;
    } else {
      try {
        listenPort = static_cast<uint16_t>(std::stoi(token));
      } catch (...) {
        std::cerr << "Warning: Invalid port '" << token << "', defaulting to 8443\n";
      }
    }
    ++idx;
  }

  SignalHandler::Enable();

  try {
    HttpServerConfig serverConfig;
    serverConfig.withPort(listenPort).withTlsCertKey(certFile, keyFile);

    if (enableStaticKey) {
      // Fixed key mode: same key used across restarts/servers.
      // Critical for multi-instance deployments sharing ticket decryption.
      //
      // In real systems, fetch from secure vault; never hardcode or use rand().
      // Format: 48 bytes = 16B name + 16B AES key + 16B HMAC key.
      TLSConfig::SessionTicketKey fixedKey;
      for (auto& byte : fixedKey) {
        byte = static_cast<std::byte>(std::rand() % 256);  // NOLINT - only for demo!
      }
      serverConfig.tls.withTlsSessionTicketKey(std::move(fixedKey));
      std::cout << "Session tickets active with fixed key (rotation OFF)\n";
    } else {
      // Auto-rotation mode: ideal for single-node setups.
      // Keys rotate automatically after configured lifetime.
      serverConfig.tls.withTlsSessionTickets(true)
          .withTlsSessionTicketLifetime(std::chrono::hours{2})
          .withTlsSessionTicketMaxKeys(4);
      std::cout << "Session tickets active with automatic rotation\n";
      std::cout << "  Rotation interval: 2 hours\n";
      std::cout << "  Max keys retained: 4\n";
    }

    Router routeTable;
    routeTable.setDefault([](const HttpRequest& request) {
      HttpResponse response(128U, http::StatusCodeOK);
      response.bodyAppend("Hello from aeronet with TLS session tickets!\n");
      response.bodyAppend("Path: ");
      response.bodyAppend(request.path());
      response.bodyAppend("\nTLS Version: ");
      response.bodyAppend(request.tlsVersion());
      response.bodyAppend("\nCipher: ");
      response.bodyAppend(request.tlsCipher());
      response.bodyAppend("\n");
      return response;
    });

    SingleHttpServer instance(std::move(serverConfig), std::move(routeTable));

    std::cout << "Listening on port " << listenPort << "\n";
    std::cout << "\nTest session resumption:\n";
    std::cout << "  openssl s_client -connect localhost:" << listenPort << " -sess_out session.pem\n";
    std::cout << "  openssl s_client -connect localhost:" << listenPort << " -sess_in session.pem\n";
    std::cout << "  (Check for 'Reused, TLSv1.3' in output)\n\n";

    instance.run();

    const auto metrics = instance.stats();
    std::cout << "\nServer metrics:\n";
    std::cout << "  Requests handled: " << metrics.totalRequestsServed << '\n';
    std::cout << "  TLS handshakes:   " << metrics.tlsHandshakesSucceeded << '\n';
  } catch (const std::exception& err) {
    std::cerr << "Fatal error: " << err.what() << '\n';
    return EXIT_FAILURE;
  }
}

