#include <iostream>
#include <fstream>
#include "program.hpp"

int main() {
    char input_file[MAX_FILE_NAME];

    std::cout << "Enter file name: ";
    std::cin.getline(input_file, MAX_FILE_NAME);

    std::ifstream input_stream(input_file);
    if (!input_stream.is_open()) {
        std::cout << "Invalid file name!\n";
        return -1;
    }

    std::ofstream output_stream("Result.txt");
    if (!output_stream.is_open()) {
        std::cout << "Could not create Result file!";
        input_stream.close();
        return -1;
    }

    while (input_stream.good()) {
        program_context ctx;
        int status = read_program(ctx, input_stream);

        if (status == 1) {
            output_stream << ctx.program_name << '\n';
            for (int idx = 0; idx < ALPHABET_SIZE; ++idx) {
                if (ctx.defined[idx]) {
                    output_stream 
                        << static_cast<char>('a' + idx)
                        << '='
                        << ctx.values[idx] << '\n';
                }
            }
        } else if (status == 0) {
            output_stream << ctx.program_name << ' ' << FAIL_MESSAGE << '\n';
        }

        clear_context(ctx);
    }

    input_stream.close();
    output_stream.close();
    return 0;
}

