Void ACPIFactoryInterface::Reboot() {
  // Perform hardware reset using keyboard controller and IDT invalidation
  asm volatile(
      "cli; "
      "1: in al, 0x64; "
      "test al, 2; "
      "jnz 1b; "
      "mov al, 0xD1; "
      "out 0x64, al; "
      "2: in al, 0x64; "
      "test al, 2; "
      "jnz 2b; "
      "mov al, 0xFE; "
      "out 0x60, al; "
      "xor rax, rax; "
      "lidt [rax]; "
      "3: jmp 3b; ");
}
}  // namespace Kernel

