namespace RC {

#ifdef RC_LOGGING
    std::ofstream log_stream;

    void close_log_file() {
        if (log_stream.is_open()) {
            log_stream.close();
        }
    }
#endif

    void initialize_logging() {
#ifdef RC_LOGGING
        std::error_code err;

        // Ensure the root directory exists
        std::filesystem::create_directories(ReCraftCore::GetRootDir(), err);

        // Handle existing log files: rotate current log to .last.txt
        const std::string root_dir = ReCraftCore::GetRootDir();
        const std::string current_log = root_dir + "/log.txt";
        const std::string backup_log = root_dir + "/log.last.txt";

        if (std::filesystem::exists(current_log, err)) {
            if (std::filesystem::exists(backup_log, err)) {
                std::filesystem::remove(backup_log, err);
            }
            std::filesystem::rename(current_log, backup_log, err);
        }

        // Open new log file
        log_stream.open(current_log);
#endif
    }

    void finalize_logging() {
#ifdef RC_LOGGING
        close_log_file();
#endif
    }

    void write_crash_report(const std::string& message) {
        std::ofstream crash_file(ReCraftCore::GetRootDir() + "/crash.txt");
        if (crash_file.is_open()) {
            crash_file << message;
            crash_file.close();
        }

#ifdef RC_LOGGING
        close_log_file();
#endif
    }

    void log_message(const std::string& text) {
#ifdef RC_LOGGING
        if (log_stream.is_open()) {
            log_stream << text << std::endl;
        }
#endif
    }

    void display_crash_screen(const std::string& error_msg) {
        gfxInitDefault();
        consoleInit(GFX_TOP, nullptr);

        std::cout << "ReCraft - " GIT_BRANCH " - " GIT_COMMIT " Error Handler\n\n";
        std::cout << error_msg << std::endl;
        std::cout << "\nPress START to exit...\n";

        while (aptMainLoop) {
            hidScanInput();

            if (hidKeysDown() & KEY_START) {
                break;
            }

            gspWaitForVBlank();
            gfxSwapBuffers();
        }
    }

