{
	// Configuration flag: whether tint initialization fixes should be applied
	static REX::TOML::Bool<> bApplyTintFixes{ "Fixes"sv, "bInitTints"sv, true };

	ModuleInitTints::ModuleInitTints() :
		Module("Init Tints", &bApplyTintFixes)
	{}

	bool ModuleInitTints::DoQuery() const noexcept
	{
		return true; // Always available for installation
	}

	bool ModuleInitTints::DoInstall([[maybe_unused]] F4SE::MessagingInterface::Message* a_msg) noexcept
	{
		const bool isNG = RELEX::IsRuntimeNG();
		const bool isAE = RELEX::IsRuntimeAE();

		if (!isNG && !isAE)
		{
			// Original Game (OG) path
			constexpr auto TARGET_OFFSET_1 = 0x63D;
			constexpr auto TARGET_OFFSET_2 = 0x850;
			constexpr auto SKIP_PATCH_SIZE_1 = 0x19;
			constexpr auto SKIP_PATCH_SIZE_2 = 0x19;

			auto baseAddr1 = REL::ID(588474).address();
			RELEX::WriteSafeNop(baseAddr1 + TARGET_OFFSET_1, SKIP_PATCH_SIZE_1);
			RELEX::WriteSafeNop(baseAddr1 + TARGET_OFFSET_2, SKIP_PATCH_SIZE_2);

			RELEX::WriteSafeNop(REL::ID(779416).address() + 0x21, SKIP_PATCH_SIZE_1);
			RELEX::WriteSafeNop(REL::ID(1444263).address() + 0x54, SKIP_PATCH_SIZE_2);

			// Force return value to true (0x01) in facegen/tint check function
			RELEX::WriteSafe(REL::ID(1088335).address(), { 0xB0, 0x01, 0xC3, 0x90, 0x90 });

			// Unconditional jump over tint-restricting block
			RELEX::WriteSafe(REL::ID(1264833).address() + 0xF9, { 0xE9, 0x9C, 0x00, 0x00, 0x00, 0x90 });
		}
		else
		{
			// New Game / Anniversary Edition (NG/AE) path
			constexpr auto NOP_SIZE = 0x35;
			constexpr auto SKIP_PATCH_SIZE_NG = 0x19;
			constexpr auto SKIP_PATCH_SIZE_AE = 0x3B;

			auto baseAddr2 = REL::ID(2207355).address();
			RELEX::WriteSafeNop(baseAddr2 + 0x654, NOP_SIZE);
			RELEX::WriteSafeNop(baseAddr2 + 0x89B, NOP_SIZE);

			if (isNG)
				RELEX::WriteSafeNop(REL::ID(2192358).address() + 0x44, SKIP_PATCH_SIZE_NG);
			else
				RELEX::WriteSafeNop(REL::ID(2192358).address() + 0x47, SKIP_PATCH_SIZE_AE);

			// Override tint-check function to always return true
			const auto forceTruePatch = isNG ? 2320239 : 7113302;
			RELEX::WriteSafe(REL::ID(forceTruePatch).address(), { 0xB0, 0x01, 0xC3, 0x90, 0x90 });

			// Bypass further tint restriction logic via unconditional jump
			RELEX::WriteSafe(REL::ID(2207492).address() + 0xF3, { 0xE9, 0x7D, 0x00, 0x00, 0x00, 0x90 });
		}

		return true;
	}

	bool ModuleInitTints::DoListener([[maybe_unused]] F4SE::MessagingInterface::Message* a_msg) noexcept
	{
		return true;
	}

	bool ModuleInitTints::DoPapyrusListener([[maybe_unused]] RE::BSScript::IVirtualMachine* a_vm) noexcept
	{
		return true;
	}
