std::string LogicalAggregatePrintInfo::toString() const {
    std::string output;
    output.append("Group By: ");
    output.append(binder::ExpressionUtil::toString(groupingExpressions));
    output.append(", Aggregates: ");
    output.append(binder::ExpressionUtil::toString(aggExpressions));
    return output;
}

void LogicalAggregate::computeFactorizedSchema() {
    resetSchema();
    auto groupIdx = schema->createGroup();
    populateGroupAndScopeForAll(groupIdx);
}

void LogicalAggregate::computeFlatSchema() {
    resetSchema();
    schema->createGroup();
    populateGroupAndScopeForAll(0 /* groupIdx */);
}

f_group_pos_set LogicalAggregate::getGroupsPosToFlatten() {
    auto [nonFlatGroup, flatGroups] =
        FlattenAllButOne::getGroupsPosToFlatten(getGroupingKeys(), *children[0]->getSchema());

    // Ensure distinct aggregates are flattened if they depend on a different group than the main non-flat group
    if (nonFlatGroup != INVALID_F_GROUP_POS) {
        for (auto& agg : aggExpressions) {
            auto aggFuncExpr = agg->constPtrCast<binder::AggregateFunctionExpression>();
            GroupDependencyAnalyzer depAnalyzer(false /* trackDependentExprs */,
                *children[0]->getSchema());
            depAnalyzer.visit(agg);

            // Add all required flat groups from analysis
            for (auto grp : depAnalyzer.getRequiredFlatGroups()) {
                flatGroups.insert(grp);
            }

            // For distinct aggregates, also require flattening of dependent groups unless they match the main group
            if (aggFuncExpr->isDistinct()) {
                for (auto grp : depAnalyzer.getDependentGroups()) {
                    if (grp != nonFlatGroup) {
                        flatGroups.insert(grp);
                    }
                }
            }
        }
    }

    return flatGroups;
}

std::string LogicalAggregate::getExpressionsForPrinting() const {
    std::string buffer = "Group By [";
    for (const auto& expr : groupingExpressions) {
        buffer += expr->toString() + ", ";
    }
    for (const auto& expr : dependentKeys) {
        buffer += expr->toString() + ", ";
    }
    buffer += "], Aggregate [";
    for (const auto& expr : aggExpressions) {
        buffer += expr->toString() + ", ";
    }
    buffer += "]";
    return buffer;
}

void LogicalAggregate::populateGroupAndScopeForAll(f_group_pos groupIdx) {
    for (auto& expr : groupingExpressions) {
        schema->insertToGroupAndScopeMayRepeat(expr, groupIdx);
    }
    for (auto& expr : dependentKeys) {
        schema->insertToGroupAndScopeMayRepeat(expr, groupIdx);
    }
    for (auto& expr : aggExpressions) {
        schema->insertToGroupAndScopeMayRepeat(expr, groupIdx);
    }
}

