// Override method to intercept requests
void SimpleAdBlocker::interceptRequest(QWebEngineUrlRequestInfo &requestInfo)
{
    if (!m_active) return;

    QUrl currentUrl = requestInfo.requestUrl();
    QString fullUrl = currentUrl.toString();
    QString domainPart = currentUrl.host();

    // Iterate through each known tracker/ad domain
    for (const QString &entity : m_blockedDomains) {
        if (domainPart.contains(entity, Qt::CaseInsensitive) ||
            fullUrl.contains(entity, Qt::CaseInsensitive)) {
            requestInfo.block(true);
            return;
        }
    }
}

