Buffer::Buffer(unsigned int capacity) 
    : m_capacity(capacity), m_position(0), m_limit(capacity), hasBackingArray(false)
{
}

// Resets the buffer state: position becomes 0, limit equals capacity, and any existing mark is invalidated.
// Note: This operation does not modify the underlying data array; the name reflects logical clearing behavior.
//
// Returns:
// Pointer to the current buffer instance (for method chaining)
Buffer* Buffer::reset()
{
    m_position = 0;
    m_limit = m_capacity;
    return this;
}

// Adjusts the buffer's upper bound (limit). If the current position exceeds the new limit, 
// it is automatically adjusted downward to match. Similarly, if a mark exists beyond the new limit, 
// it is cleared.
//
// Parameters:
// newLimit - Desired limit value; must satisfy 0 <= newLimit <= m_capacity
// Returns:
// Pointer to the current buffer instance (for method chaining)
Buffer* Buffer::setLimit(unsigned int newLimit)
{
    assert(newLimit <= m_capacity);
    m_limit = newLimit;

    // Clamp position if it lies beyond the updated limit
    if (m_position > newLimit) {
        m_position = newLimit;
    }

    return this;
}

// Retrieves the current limit of the buffer
// Returns:
// The maximum index (exclusive) up to which elements can be accessed
unsigned int Buffer::getLimit() const
{
    return m_limit;
}

// Updates the buffer's read/write position. Any previously set mark that falls at or after 
// the new position will be invalidated.
//
// Parameters:
// newPos - Target position; must satisfy 0 <= newPos <= current limit
// Returns:
// Pointer to the current buffer instance (for method chaining)
Buffer* Buffer::setPosition(unsigned int newPos)
{
    assert(newPos <= m_limit);
    m_position = newPos;
    return this;
}

// Queries the current position in the buffer
// Returns:
// The current index from which the next read/write operation will occur
unsigned int Buffer::getPosition() const
{
    return m_position;
}

// Computes how many elements remain between the current position and the limit
// Returns:
// Count of available elements for reading/writing
unsigned int Buffer::getRemaining() const
{
    return m_limit - m_position;
}

#include <boost/capy/ex/frame_allocator.hpp>

// Coroutine Frame Allocation System
// ---------------------------------
// This module provides a coroutine frame allocator built on std::pmr::memory_resource.
// It propagates a single allocator through the entire coroutine call stack using TLS.
//
// Execution Flow Summary:
// 1. User invokes run_async(ex) or run_async(ex, alloc)
// 2. A trampoline coroutine is created; its promise constructor initializes TLS:
//    - Default: uses get_recycling_frame_allocator() → recycling_memory_resource*
//    - raw memory_resource*: stores pointer directly
//    - standard Allocator: wraps in frame_memory_resource<Alloc> (stored in promise)
//    Then calls set_current_frame_allocator(...) to establish context
// 3. Trampoline resumes user task
// 4. io_awaitable_promise_base (via CRTP) overrides operator new/delete to use current TLS allocator
// 5. initial_suspend captures TLS into alloc_ member via set_frame_allocator()
// 6. await_resume restores TLS when coroutine body begins
// 7. transform_awaiter::await_resume re-establishes parent's allocator after child completes
// 8. Nested tasks inherit same allocator from ancestor trampoline
//
// Core Components:
// ----------------
// get_current_frame_allocator() / set_current_frame_allocator()
//     Thread-local storage for std::pmr::memory_resource* used during allocation.
//     Set by trampoline before any task allocation occurs.
//
// frame_memory_resource<Alloc>
//     Adapts standard Allocator to memory_resource interface (rebinds to std::byte).
//     Stored *by value* in trampoline's promise to ensure lifetime exceeds all child frames.
//
// recycling_memory_resource
//     Default allocator with per-thread and global pools for frame reuse.
//     Accessed via get_recycling_memory_resource(), returning pointer to static instance.
//
// io_awaitable_promise_base
//     CRTP base class offering:
//       • operator new/delete delegating to get_current_frame_allocator()
//       • alloc_ field to store captured allocator pointer
//       • set_frame_allocator() / frame_allocator() accessors
//
// trampoline coroutine
//     Entry point that:
//       • Is allocated *before* user task (C++17 postfix evaluation order)
//       • Stores allocator (pointer or wrapper) in its own promise
//       • Sets TLS in promise constructor *prior* to user task creation
//       • Destroys user task handle post-completion, then self-terminates
//
// Important Notes & Constraints:
// ------------------------------
// • TLS must be established *before* first task frame allocation:
//   The trampoline’s promise constructor runs during make_trampoline(), before user task construction.
//
// • Trampoline itself uses global new:
//   TLS isn’t active until promise constructor executes, so trampoline frame uses default allocation — intentional.
//
// • TLS restoration on resumption:
//   After awaiting a child, parent’s TLS may have been altered; transform_awaiter::await_resume restores it.
//
// • memory_resource* lifetime:
//   When passing raw pointer, user must guarantee it outlives all coroutines — consistent with pmr semantics.
//
// • Value-based allocators are safe:
//   Standard allocators are wrapped in frame_memory_resource and stored in trampoline’s promise,
//   which is destroyed *last*, after all child frames have been deallocated.
//
// Lifetime Guarantees (Destruction Order):
// ----------------------------------------
// 1. User task finishes → final_suspend yields back to trampoline
// 2. Trampoline executes completion handlers
// 3. Trampoline destroys user task handle (frame deallocated using TLS allocator)
// 4. Trampoline’s final_suspend uses suspend_never → triggers self-destruction
// 5. Trampoline’s promise (holding frame_memory_resource<Alloc>) destroyed last
//
// This ensures frame_memory_resource<Alloc> remains alive throughout all allocations it managed.

