// Helper to build test pairs manually instead of using structured binding
std::vector<std::pair<std::string_view, std::string_view>> make_demangle_test_cases() {
    return {
        { "_ZN11rocprofiler8internal18correlation_config22get_unique_internal_idEv",
          "rocprofiler::internal::correlation_config::get_unique_internal_id()" },
        { "_ZN11rocprofiler8internal18get_active_configsEv",
          "rocprofiler::internal::get_active_configs()" },
        { "_ZN11rocprofiler8internal22get_registered_configsEv",
          "rocprofiler::internal::get_registered_configs()" },
        { "_ZZN11rocprofiler8internal18correlation_config22get_unique_internal_idEvE2_v",
          "rocprofiler::internal::correlation_config::get_unique_internal_id()::_v" },
        { "_ZZN11rocprofiler8internal18get_active_configsEvE2_v",
          "rocprofiler::internal::get_active_configs()::_v" },
        { "_ZZN11rocprofiler8internal22get_registered_configsEvE2_v",
          "rocprofiler::internal::get_registered_configs()::_v" }
    };
}

TEST(common, demangling)
{
    auto test_pairs = make_demangle_test_cases();

    for (size_t idx = 0; idx < test_pairs.size(); ++idx) {
        const auto& [mangled_str, expected_demangled] = test_pairs[idx];

        // Check correct demangling
        std::string actual = rocprofiler::common::cxx_demangle(mangled_str);
        EXPECT_EQ(actual, expected_demangled)
            << "Demangle failed for input: '" << mangled_str << "' at index " << idx;

        // Corrupt input by prepending extra '_Z' and verify it remains unchanged
        std::string corrupted_input = "_Z" + std::string{mangled_str};
        std::string result_after_corruption = rocprofiler::common::cxx_demangle(corrupted_input);
        EXPECT_EQ(result_after_corruption, corrupted_input)
            << "Unexpected success on malformed input: '" << corrupted_input << "'";
    }
}

TEST(common, truncate)
{
    // Test case for truncating long template-instantiated function names
    std::string_view mangled_name = "_ZSt16__do_uninit_copyIPKSt4pairINSt7__cxx1112basic_"
                                    "stringIcSt11char_traitsIcESaIcEEES6_EPS7_ET0_T_SC_SB_";

    std::string_view fully_expanded_name = 
        "std::pair<std::__cxx11::basic_string<char, std::char_traits<char>, std::allocator<char> "
        ">, std::__cxx11::basic_string<char, std::char_traits<char>, std::allocator<char> > >* "
        "std::__do_uninit_copy<std::pair<std::__cxx11::basic_string<char, std::char_traits<char>, "
        "std::allocator<char> >, std::__cxx11::basic_string<char, std::char_traits<char>, "
        "std::allocator<char> > > const*, std::pair<std::__cxx11::basic_string<char, "
        "std::char_traits<char>, std::allocator<char> >, std::__cxx11::basic_string<char, "
        "std::char_traits<char>, std::allocator<char> > "
        ">*>(std::pair<std::__cxx11::basic_string<char, std::char_traits<char>, "
        "std::allocator<char> >, std::__cxx11::basic_string<char, std::char_traits<char>, "
        "std::allocator<char> > > const*, std::pair<std::__cxx11::basic_string<char, "
        "std::char_traits<char>, std::allocator<char> >, std::__cxx11::basic_string<char, "
        "std::char_traits<char>, std::allocator<char> > > const*, "
        "std::pair<std::__cxx11::basic_string<char, std::char_traits<char>, std::allocator<char> "
        ">, std::__cxx11::basic_string<char, std::char_traits<char>, std::allocator<char> > >*)";

    // First verify full demangling matches expected expansion
    std::string demangled_result = rocprofiler::common::cxx_demangle(mangled_name);
    EXPECT_EQ(demangled_result, fully_expanded_name);

    // Then check that truncation yields the correct function name
    EXPECT_EQ(rocprofiler::common::truncate_name(fully_expanded_name),
              std::string_view{"__do_uninit_copy"});
    EXPECT_EQ(rocprofiler::common::truncate_name(demangled_result),
              std::string_view{"__do_uninit_copy"});
}

#include <cstdlib>
#include <iostream>
#include <array>
#include <asio.hpp>
#include <asio/ssl.hpp>

constexpr std::size_t BUFFER_SIZE = 1024;

class SecureClient {
public:
    SecureClient(asio::io_context& ctx,
                 asio::ssl::context& ssl_ctx,
                 asio::ip::tcp::resolver::results_type&& res)
        : io_ctx_(ctx),
          ssl_ctx_(ssl_ctx),
          socket_(io_ctx_, ssl_ctx_),
          resolver_results_(std::move(res)) {}

    void start() {
        // Set up certificate verification callback
        socket_.set_verify_mode(asio::ssl::verify_peer);
        socket_.set_verify_callback([this](bool preverified, asio::ssl::verify_context& vc) {
            return onCertificateVerify(preverified, vc);
        });

        // Start asynchronous connection
        auto self = shared_from_this();
        asio::async_connect(socket_.lowest_layer(), resolver_results_,
            [this, self](const asio::error_code& ec, const asio::ip::tcp::endpoint&) {
                handleConnect(ec);
            });
    }

private:
    std::shared_ptr<SecureClient> shared_from_this() {
        return std::static_pointer_cast<SecureClient>(shared_from_this_base());
    }

    void* shared_from_this_base() {
        return this;
    }

    bool onCertificateVerify(bool preverified, asio::ssl::verify_context& ctx) {
        char subject[256];
        X509* cert = X509_STORE_CTX_get_current_cert(ctx.native_handle());
        if (cert && X509_NAME_oneline(X509_get_subject_name(cert), subject, sizeof(subject))) {
            std::cout << "Verifying certificate: " << subject << "\n";
        }
        return preverified;
    }

    void handleConnect(const asio::error_code& ec) {
        if (!ec) {
            std::cout << "Connected. Initiating TLS handshake...\n";
            socket_.async_handshake(asio::ssl::stream_base::client,
                [this](const asio::error_code& ec) {
                    handleHandshake(ec);
                });
        } else {
            std::cerr << "Connection failed: " << ec.message() << "\n";
        }
    }

    void handleHandshake(const asio::error_code& ec) {
        if (!ec) {
            std::cout << "TLS handshake successful.\nEnter message: ";
            std::cin.getline(request_.data(), request_.size());
            size_t len = std::strlen(request_.data());
            if (len == 0) {
                std::cerr << "Empty message ignored.\n";
                return;
            }
            asio::async_write(socket_,
                asio::buffer(request_.data(), len),
                [this](const asio::error_code& ec, std::size_t bytes) {
                    handleWrite(ec, bytes);
                });
        } else {
            std::cerr << "Handshake failed: " << ec.message() << "\n";
        }
    }

    void handleWrite(const asio::error_code& ec, std::size_t bytes_sent) {
        if (!ec) {
            reply_.fill('\0');
            asio::async_read(socket_,
                asio::buffer(reply_.data(), std::min(bytes_sent, reply_.size())),
                [this](const asio::error_code& ec, std::size_t bytes_read) {
                    handleRead(ec, bytes_read);
                });
        } else {
            std::cerr << "Write error: " << ec.message() << "\n";
        }
    }

    void handleRead(const asio::error_code& ec, std::size_t bytes_read) {
        if (!ec) {
            std::cout << "Reply received (" << bytes_read << " bytes):\n";
            std::cout.write(reply_.data(), bytes_read);
            std::cout << "\n";
        } else {
            std::cerr << "Read error: " << ec.message() << "\n";
        }
    }

private:
    asio::io_context& io_ctx_;
    asio::ssl::context& ssl_ctx_;
    asio::ssl::stream<asio::ip::tcp::socket> socket_;
    asio::ip::tcp::resolver::results_type resolver_results_;
    std::array<char, BUFFER_SIZE> request_;
    std::array<char, BUFFER_SIZE> reply_;
};

int main(int argc, char* argv[]) {
    try {
        if (argc != 3) {
            std::cerr << "Usage: secure_client <host> <port>\n";
            return 1;
        }

        asio::io_context io_context;
        asio::ip::tcp::resolver resolver(io_context);
        auto endpoints = resolver.resolve(argv[1], argv[2]);

        asio::ssl::context ssl_context(asio::ssl::context::sslv23);
        ssl_context.load_verify_file("ca.pem");

        auto client_ptr = std::make_shared<SecureClient>(io_context, ssl_context, std::move(endpoints));
        client_ptr->start();

        io_context.run();
    } catch (const std::exception& ex) {
        std::cerr << "Exception: " << ex.what() << "\n";
        return 1;
    }

    return 0;
}

#include "jemalloc/internal/jemalloc_preamble.h"
#include "jemalloc/internal/jemalloc_internal_includes.h"
#include "jemalloc/internal/prof_stats.h"

// Configuration flag for enabling statistics collection
bool opt_prof_stats = false;

// Mutex for synchronizing access to statistics data
malloc_mutex_t prof_stats_mtx;

// Arrays to track current (live) and cumulative (accumulated) statistics
static prof_stats_t prof_stats_live[PROF_SC_NSIZES];
static prof_stats_t prof_stats_accum[PROF_SC_NSIZES];

// Helper function to acquire lock for statistics operations
static void 
prof_stats_lock_acquire(tsd_t *tsd) {
    if (opt_prof && opt_prof_stats) {
        malloc_mutex_lock(tsd_tsdn(tsd), &prof_stats_mtx);
    }
}

// Helper function to release lock after statistics operations
static void 
prof_stats_lock_release(tsd_t *tsd) {
    malloc_mutex_unlock(tsd_tsdn(tsd), &prof_stats_mtx);
}

// Update statistics when allocation occurs
void 
prof_stats_record_alloc(tsd_t *tsd, szind_t index, size_t requested_size) {
    cassert(config_prof);

    // Ensure we're within valid size class bounds
    if (index >= SC_NSIZES) {
        return;
    }

    prof_stats_lock_acquire(tsd);

    // Update both live and accumulated counters
    prof_stats_live[index].req_sum += requested_size;
    prof_stats_live[index].count += 1;

    prof_stats_accum[index].req_sum += requested_size;
    prof_stats_accum[index].count += 1;

    prof_stats_lock_release(tsd);
}

// Update statistics when deallocation occurs
void 
prof_stats_record_dealloc(tsd_t *tsd, szind_t index, size_t requested_size) {
    cassert(config_prof);

    // Validate index before proceeding
    if (index >= SC_NSIZES) {
        return;
    }

    prof_stats_lock_acquire(tsd);

    // Decrement live statistics only
    prof_stats_live[index].req_sum -= requested_size;
    prof_stats_live[index].count -= 1;

    prof_stats_lock_release(tsd);
}

// Retrieve current (live) statistics for a given size class
void 
prof_stats_fetch_live(tsd_t *tsd, szind_t index, prof_stats_t *output_stats) {
    cassert(config_prof);

    if (index >= SC_NSIZES || output_stats == nullptr) {
        return;
    }

    prof_stats_lock_acquire(tsd);
    *output_stats = prof_stats_live[index];
    prof_stats_lock_release(tsd);
}

// Retrieve accumulated statistics for a given size class
void 
prof_stats_fetch_accum(tsd_t *tsd, szind_t index, prof_stats_t *output_stats) {
    cassert(config_prof);

    if (index >= SC_NSIZES || output_stats == nullptr) {
        return;
    }

    prof_stats_lock_acquire(tsd);
    *output_stats = prof_stats_accum[index];
    prof_stats_lock_release(tsd);
}

#include "EventTimer.hpp"
#include <algorithm>
#include <limits>
#include <iostream>
#include "debug.hpp"

// Destructor implementation 
EventTimer::~EventTimer() = default;

inline void EventTimer::updateNextEventCycle() {
    // Determine earliest trigger time among remaining events
    if (events.empty()) {
        next_event_cycle = std::numeric_limits<uint64_t>::max();
    } else {
        // Since events are kept sorted by triggerCycles ascending,
        // first element is always the next one
        next_event_cycle = events.front().triggerCycles;
    }
}

void EventTimer::scheduleEvent(uint64_t triggerCycles, void (*callback)(uint64_t, void*), uint64_t instanceID, void* userData) {
    if (DEBUG(DEBUG_EVENT_TIMER)) {
        std::cout << "scheduleEvent: cycle=" << triggerCycles << " id=" << instanceID << std::endl;
    }

    // Skip events scheduled in the past relative to current clock
    if (clock && triggerCycles < clock->get_cycles()) {
        std::cout << "scheduleEvent: Attempted to schedule event in the past — ignored" << std::endl;
        return;
    }

    // Try to find an existing event with same instanceID
    bool found = false;
    for (auto& evt : events) {
        if (evt.instanceID == instanceID) {
            evt.triggerCycles = triggerCycles;
            evt.triggerCallback = callback;
            evt.userData = userData;
            found = true;
            break;
        }
    }

    if (!found) {
        // Add new event
        events.emplace_back(Event{triggerCycles, callback, instanceID, userData});
    }

    // Maintain sorted order by triggerCycles (ascending)
    std::stable_sort(events.begin(), events.end(),
        [](const Event& lhs, const Event& rhs) {
            return lhs.triggerCycles < rhs.triggerCycles;
        });

    updateNextEventCycle();
}

void EventTimer::processEvents(uint64_t currentCycles) {
    // Process all events whose trigger time has passed or equals currentCycles
    for (size_t i = 0; i < events.size(); ) {
        if (events[i].triggerCycles > currentCycles) {
            ++i;
            continue;
        }

        Event activeEvent = std::move(events[i]);
        events.erase(events.begin() + i);

        if (DEBUG(DEBUG_EVENT_TIMER)) {
            std::cout << "Processing event: cycle=" << activeEvent.triggerCycles << " id=" << activeEvent.instanceID << std::endl;
        }

        if (activeEvent.triggerCallback) {
            activeEvent.triggerCallback(activeEvent.instanceID, activeEvent.userData);
        }
    }

    updateNextEventCycle();
}

void EventTimer::cancelEvents(uint64_t instanceID) {
    size_t originalSize = events.size();
    auto newEnd = std::remove_if(events.begin(), events.end(),
        [instanceID](const Event& evt) { return evt.instanceID == instanceID; });

    if (newEnd != events.end()) {
        events.erase(newEnd, events.end());
    }

    // Re-sort only if any events were removed
    if (events.size() != originalSize) {
        std::stable_sort(events.begin(), events.end(),
            [](const Event& a, const Event& b) {
                return a.triggerCycles < b.triggerCycles;
            });
    }

    updateNextEventCycle();
}

bool EventTimer::hasPendingEvents() const {
    return !events.empty();
}

uint64_t EventTimer::getNextEventCycle() const {
    return next_event_cycle;
}

#include <cstddef> // for idx_t-like usage (assuming idx_t is defined elsewhere)

// Assuming idx_t is an integer type; if not, replace with actual definition
typedef size_t idx_t;

void Change2CNumbering(idx_t nvtxs, idx_t *xadj, idx_t *adjncy)
{
    idx_t i = 0;
    // Decrement xadj[0..nvtxs]
    while (i <= nvtxs) {
        --xadj[i];
        ++i;
    }
    // Decrement adjncy[0..xadj[nvtxs]-1]
    idx_t limit = xadj[nvtxs];
    i = 0;
    while (i < limit) {
        --adjncy[i];
        ++i;
    }
}

void Change2FNumbering(idx_t nvtxs, idx_t *xadj, idx_t *adjncy, idx_t *vector)
{
    idx_t i = 0;
    // Increment vector[0..nvtxs-1]
    while (i < nvtxs) {
        ++vector[i];
        ++i;
    }
    // Increment adjncy[0..xadj[nvtxs]-1]
    idx_t edgeCount = xadj[nvtxs];
    i = 0;
    while (i < edgeCount) {
        ++adjncy[i];
        ++i;
    }
    // Increment xadj[0..nvtxs]
    i = 0;
    while (i <= nvtxs) {
        ++xadj[i];
        ++i;
    }
}

void Change2FNumbering2(idx_t nvtxs, idx_t *xadj, idx_t *adjncy)
{
    idx_t edgeCount = xadj[nvtxs];
    idx_t i = 0;
    // Increment adjncy[0..edgeCount-1]
    while (i < edgeCount) {
        ++adjncy[i];
        ++i;
    }
    // Increment xadj[0..nvtxs]
    i = 0;
    while (i <= nvtxs) {
        ++xadj[i];
        ++i;
    }
}

void Change2FNumberingOrder(idx_t nvtxs, idx_t *xadj, idx_t *adjncy, 
                            idx_t *v1, idx_t *v2)
{
    idx_t i = 0;
    // Increment v1[0..nvtxs-1] and v2[0..nvtxs-1]
    while (i < nvtxs) {
        ++v1[i];
        ++v2[i];
        ++i;
    }
    idx_t edgeCount = xadj[nvtxs];
    i = 0;
    // Increment adjncy[0..edgeCount-1]
    while (i < edgeCount) {
        ++adjncy[i];
        ++i;
    }
    // Increment xadj[0..nvtxs]
    i = 0;
    while (i <= nvtxs) {
        ++xadj[i];
        ++i;
    }
}

void ChangeMesh2CNumbering(idx_t n, idx_t *ptr, idx_t *ind)
{
    idx_t i = 0;
    // Decrement ptr[0..n]
    while (i <= n) {
        --ptr[i];
        ++i;
    }
    // Decrement ind[0..ptr[n]-1]
    idx_t limit = ptr[n];
    i = 0;
    while (i < limit) {
        --ind[i];
        ++i;
    }
}

void ChangeMesh2FNumbering(idx_t n, idx_t *ptr, idx_t *ind, idx_t nvtxs, 
                           idx_t *xadj, idx_t *adjncy)
{
    idx_t i = 0;
    // Increment ind[0..ptr[n]-1]
    idx_t indLimit = ptr[n];
    while (i < indLimit) {
        ++ind[i];
        ++i;
    }
    // Increment ptr[0..n]
    i = 0;
    while (i <= n) {
        ++ptr[i];
        ++i;
    }
    // Increment adjncy[0..xadj[nvtxs]-1]
    idx_t adjLimit = xadj[nvtxs];
    i = 0;
    while (i < adjLimit) {
        ++adjncy[i];
        ++i;
    }
    // Increment xadj[0..nvtxs]
    i = 0;
    while (i <= nvtxs) {
        ++xadj[i];
        ++i;
    }
}

void ChangeMesh2FNumbering2(idx_t ne, idx_t nn, idx_t *ptr, idx_t *ind, 
                            idx_t *epart, idx_t *npart)
{
    idx_t i = 0;
    // Increment ind[0..ptr[ne]-1]
    idx_t indLimit = ptr[ne];
    while (i < indLimit) {
        ++ind[i];
        ++i;
    }
    // Increment ptr[0..ne]
    i = 0;
    while (i <= ne) {
        ++ptr[i];
        ++i;
    }
    // Increment epart[0..ne-1]
    i = 0;
    while (i < ne) {
        ++epart[i];
        ++i;
    }
    // Increment npart[0..nn-1]
    i = 0;
    while (i < nn) {
        ++npart[i];
        ++i;
    }
}

