// Operator class representing someone who operates a vehicle
class Operator {
private:
    int yearsOfService;
    Vehicle* assignedVehicle = nullptr; // aggregation relationship
                                        // the Vehicle exists independently of the Operator
public:
    Operator(int serviceYears, Vehicle* vehicle) 
        : yearsOfService(serviceYears), assignedVehicle(vehicle) {}

    void showDetails() const {
        cout << "Operator service years: " << yearsOfService << '\n';
        if (assignedVehicle != nullptr) {
            assignedVehicle->display();
        }
    }
};

