    {
        Operator firstOperator(7, &v);
        firstOperator.showDetails();
    } // firstOperator's destructor is called here

    // the Vehicle continues to exist independently after firstOperator goes out of scope
    Operator secondOperator(12, &v); // another operator begins using the same vehicle
    secondOperator.showDetails();
}

