namespace Sass {

  // Overload for Custom_Error: returns itself as a Value*
  Value* To_Value::operator()(Custom_Error* err) {
    return err;
  }

  // Overload for Custom_Warning: returns itself as a Value*
  Value* To_Value::operator()(Custom_Warning* warn) {
    return warn;
  }

  // Overload for Boolean: returns itself as a Value*
  Value* To_Value::operator()(Boolean* flag) {
    return flag;
  }

  // Overload for Number: returns itself as a Value*
  Value* To_Value::operator()(Number* val) {
    return val;
  }

  // Overload for Color_RGBA: returns itself as a Value*
  Value* To_Value::operator()(Color_RGBA* rgba) {
    return rgba;
  }

  // Overload for Color_HSLA: returns itself as a Value*
  Value* To_Value::operator()(Color_HSLA* hsla) {
    return hsla;
  }

  // Overload for String_Constant: returns itself as a Value*
  Value* To_Value::operator()(String_Constant* strConst) {
    return strConst;
  }

  // Overload for String_Quoted: returns itself as a Value*
  Value* To_Value::operator()(String_Quoted* quotedStr) {
    return quotedStr;
  }

  // Overload for List: constructs a new List with transformed elements
  Value* To_Value::operator()(List* lst) {
    List_Obj newLst = SASS_MEMORY_NEW(List,
                                     lst->pstate(),
                                     lst->length(),
                                     lst->separator(),
                                     lst->is_arglist(),
                                     lst->is_bracketed());

    size_t idx = 0;
    size_t total = lst->length();
    while (idx < total) {
      Value* elem = (*lst)[idx]->perform(this);
      newLst->append(elem);
      ++idx;
    }
    return newLst.detach();
  }

  // Overload for Map: returns itself as a Value*
  Value* To_Value::operator()(Map* mp) {
    return mp;
  }

  // Overload for Null: returns itself as a Value*
  Value* To_Value::operator()(Null* nullVal) {
    return nullVal;
  }

  // Overload for Function: returns itself as a Value*
  Value* To_Value::operator()(Function* func) {
    return func;
  }

  // Overload for Argument: if named, returns nullptr; else evaluate value
  Value* To_Value::operator()(Argument* arg) {
    if (!arg->name().empty()) {
      return nullptr;
    }
    return arg->value()->perform(this);
  }

  // Overload for SelectorList: converts to quoted string
  Value* To_Value::operator()(SelectorList* selList) {
    return SASS_MEMORY_NEW(String_Quoted,
                           selList->pstate(),
                           selList->to_string(ctx.c_options));
  }

  // Overload for Binary_Expression: converts to quoted string
  Value* To_Value::operator()(Binary_Expression* binExpr) {
    return SASS_MEMORY_NEW(String_Quoted,
                           binExpr->pstate(),
                           binExpr->to_string(ctx.c_options));
  }

}

#include <sol/sol.hpp>
#include <cassert>

int main() {
    // Initialize Lua state
    sol::state lua_vm;

    // Define the Lua function: func(a, b) = (a + b) * 2
    lua_vm.script("function compute_sum(a, b) return (a + b) * 2 end");

    // Retrieve the function reference by name
    sol::object func_obj = lua_vm["compute_sum"];
    assert(func_obj.get_type() == sol::type::function);

    // Get raw Lua state pointer for low-level stack manipulation
    lua_State* L = lua_vm.lua_state();

    // Push a traceback handler onto the stack for error handling
    int top_before = lua_gettop(L);
    sol::stack::push(L, sol::default_traceback_error_handler);
    sol::stack_reference err_handler(L, -1);

    // Push the function onto the stack
    func_obj.push();

    // Create a callable wrapper using the traceback handler
    sol::stack_aligned_stack_handler_function wrapped_func(
        L, -2, err_handler);  // function at -2, handler at -1

    // Prepare arguments on the stack: push integers 5 and 6
    lua_pushinteger(L, static_cast<lua_Integer>(5));
    lua_pushinteger(L, static_cast<lua_Integer>(6));

    // Execute the function with 2 arguments
    int retval_count = wrapped_func(sol::stack_count(2));
    assert(retval_count == 1);  // Expect one return value

    // Extract the result from the top of the stack
    int computed_result = static_cast<int>(lua_tointeger(L, -1));
    lua_pop(L, 1);  // Pop the result

    // Clean up the traceback handler
    err_handler.pop();

    // Verify final stack state is clean
    assert(lua_gettop(L) == top_before);

    // Validate correctness of computation
    assert(computed_result == 22);

    return 0;
}

