#include <gtest/gtest.h>
#include <cstddef>

/**
 * @brief Verifies PC address correction for GFX950 architecture.
 */
template <typename SampleRecordType>
class GpuPcCorrectionGFX950 : public MidMacroPCCorrection<GFX950, SampleRecordType>
{
private:
    using BaseClass = MidMacroPCCorrection<GFX950, SampleRecordType>;

public:
    void generateSample(uint64_t programCounter, bool isMidMacro) override
    {
        // Only stochastic sampling supports mid_macro mode on GFX950
        if constexpr (!std::is_same_v<SampleRecordType,
                                      rocprofiler_pc_sampling_record_stochastic_v0_t>)
        {
            // Force mid_macro flag to false for non-stochastic records
            isMidMacro = false;
        }
        // Delegate to base implementation
        BaseClass::generateSample(programCounter, isMidMacro);
    }

    uint64_t computeTargetPC(uint64_t rawPc, bool isMidMacro) override
    {
        // Per hardware specification: when mid_macro is active, subtract 2 DWORDs (8 bytes)
        return isMidMacro ? (rawPc - 2u * sizeof(uint32_t)) : rawPc;
    }
};

TEST(pcs_parser, gfx950_validation)
{
    GpuPcCorrectionGFX950<rocprofiler_pc_sampling_record_host_trap_v0_t>{}.runTest();
    GpuPcCorrectionGFX950<rocprofiler_pc_sampling_record_stochastic_v0_t>{}.runTest();
    std::cout << "GFX950 validation completed." << std::endl;
}

