/**
 * Fixture for embedding configuration tests — sets up isolated filesystem & env vars.
 */
struct EmbeddingConfigTestSetup {
    fs::path tempRoot;
    fs::path dataPath;
    fs::path configPath;
    std::optional<yams::test::ScopedEnvVar> cfgEnv;
    std::optional<yams::test::ScopedEnvVar> datEnv;
    std::optional<yams::test::ScopedEnvVar> nonIntEnv;
    std::optional<yams::test::ScopedEnvVar> daemonOffEnv;
    std::optional<yams::test::ScopedEnvVar> xdgDataEnv;
    std::optional<yams::test::ScopedEnvVar> xdgCfgEnv;

    EmbeddingConfigTestSetup() {
        // Unique temp dir per process
        tempRoot = fs::temp_directory_path() / ("yams_embed_cfg_" + std::to_string(::getpid()));
        fs::create_directories(tempRoot);

        dataPath = tempRoot / "data_store";
        fs::create_directories(dataPath);

        configPath = tempRoot / "config_dir";
        fs::create_directories(configPath);

        // Override config/data paths via env (checked before XDG)
        cfgEnv.emplace("YAMS_CONFIG", (configPath / "settings.toml").string());
        datEnv.emplace("YAMS_DATA_DIR", dataPath.string());

        // Suppress interactive prompts
        nonIntEnv.emplace("YAMS_NON_INTERACTIVE", std::optional<std::string>("1"));

        // Prevent daemon startup during tests
        daemonOffEnv.emplace("YAMS_CLI_DISABLE_DAEMON_AUTOSTART", std::optional<std::string>("1"));

        // Fallback Unix paths (for compatibility)
        xdgDataEnv.emplace("XDG_DATA_HOME", dataPath.string());
        xdgCfgEnv.emplace("XDG_CONFIG_HOME", configPath.string());
    }

    ~EmbeddingConfigTestSetup() {
        // Explicitly reset in reverse order to avoid dangling references
        cfgEnv.reset();
        datEnv.reset();
        nonIntEnv.reset();
        daemonOffEnv.reset();
        xdgDataEnv.reset();
        xdgCfgEnv.reset();

        std::error_code err;
        fs::remove_all(tempRoot, err);
    }

    void installModel(const std::string& name) {
        // Models live under YAMS_DATA_DIR/models/
        fs::path modelsBase = dataPath / "models";
        fs::path modelDir = modelsBase / name;
        fs::create_directories(modelDir);
        std::ofstream(modelDir / "model.onnx").close();
    }

    int execute(const std::vector<std::string>& cmdline) {
        auto cli = std::make_unique<yams::cli::YamsCLI>();
        std::vector<char*> rawArgs;
        rawArgs.reserve(cmdline.size());
        std::transform(cmdline.begin(), cmdline.end(), std::back_inserter(rawArgs),
                       [](const std::string& s) { return const_cast<char*>(s.c_str()); });
        return cli->run(static_cast<int>(rawArgs.size()), rawArgs.data());
    }
};

} // namespace

