#include "ByteArrayInputStream.h"
#include <cstddef>
#include "util/console/ArrayWithLength.h"
#include "win/extraX64.h"

// Constructor: initializes stream with specified buffer, offset, and length
ByteArrayInputStream::ByteArrayInputStream(
    byteArray    buf,
    unsigned int startOffset,
    unsigned int maxLen
)
: pos(startOffset),
  count(std::min(startOffset + maxLen, buf.length)),
  mark(startOffset) {
    this->buf = buf;
}

// Constructor: creates stream using entire buffer, starting at position 0
ByteArrayInputStream::ByteArrayInputStream(byteArray buf)
: pos(0),
  count(buf.length),
  mark(0) {
    this->buf = buf;
}

// Reads a single byte from the stream
// Returns value in [0,255] or -1 if no more data available
int ByteArrayInputStream::read() {
    if (pos >= count) return -1;
    return static_cast<int>(buf[pos++]);
}

// Reads bytes into provided buffer b, equivalent to read(b, 0, b.length)
int ByteArrayInputStream::read(byteArray b) { 
    return read(b, 0, b.length); 
}

// Reads up to 'length' bytes into buffer 'b' starting at index 'offset'
// Copies data from internal buffer to destination array
int ByteArrayInputStream::read(
    byteArray    b,
    unsigned int destOffset,
    unsigned int length
) {
    if (pos == count) return -1;

    // Determine how many bytes can actually be read
    int availableBytes = count - pos;
    int bytesToRead = length < static_cast<unsigned int>(availableBytes) ? length : availableBytes;

    // Copy data from internal buffer to output buffer
    XMemCpy(&b[destOffset], &buf[pos], bytesToRead);

    // Advance position and return number of bytes read
    pos += bytesToRead;
    return bytesToRead;
}

// No-op implementation: closing this stream has no effect
void ByteArrayInputStream::close() { }

// Skips 'n' bytes forward in the stream
// Returns actual number of bytes skipped
std::int64_t ByteArrayInputStream::skip(std::int64_t n) {
    std::int64_t proposedPos = pos + n;

    // Clamp position to not exceed available data
    if (proposedPos > count) {
        proposedPos = count;
    }

    std::int64_t skipped = proposedPos - pos;
    pos = static_cast<unsigned int>(proposedPos);
    return skipped;
}

// Destructor: releases allocated memory for buffer if it was dynamically allocated
ByteArrayInputStream::~ByteArrayInputStream() {
    if (buf.data != nullptr) {
        delete[] buf.data;
        buf.data = nullptr;
    }
}

