namespace sdb {

LockfileFeature::LockfileFeature(Server& server)
  : SerenedFeature{server, name()} {
  setOptional(false);
}

void LockfileFeature::start() {
  auto& dbPath = server().getFeature<DatabasePathFeature>();
  _lock_filename = dbPath.subdirectoryName("LOCK");

  SDB_ASSERT(!_lock_filename.empty());

  // Attempt to verify existing lock file
  int errCode = SdbVerifyLockFile(_lock_filename.c_str());
  if (errCode != ERROR_OK) {
    std::string pidStr;
    try {
      pidStr = file_utils::Slurp(_lock_filename);
    } catch (...) {
      // Ignore exceptions during read
    }

    if (pidStr.empty()) {
      SDB_FATAL_EXIT_CODE(
        "xxxxx", sdb::Logger::FIXME, EXIT_COULD_NOT_LOCK,
        "failed to read/write lockfile, please check the file permissions "
        "of the lockfile '",
        _lock_filename, "'");
    } else {
      SDB_FATAL_EXIT_CODE(
        "xxxxx", sdb::Logger::FIXME, EXIT_COULD_NOT_LOCK,
        "database is locked by process ", pidStr,
        "; please stop it first and check that the lockfile '", _lock_filename,
        "' goes away. If you are sure no other serened process is ",
        "running, please remove the lockfile '", _lock_filename,
        "' and try again");
    }
  }

  // Remove stale lock file if exists
  if (SdbExistsFile(_lock_filename.c_str())) {
    errCode = SdbUnlinkFile(_lock_filename.c_str());
    if (errCode != ERROR_OK) {
      SDB_FATAL_EXIT_CODE(
        "xxxxx", sdb::Logger::FIXME, EXIT_COULD_NOT_LOCK,
        "failed to remove an abandoned lockfile in the database "
        "directory, please check the file permissions of the lockfile '",
        _lock_filename, "': ", GetErrorStr(errCode));
    }
  }

  // Create new lock file
  errCode = SdbCreateLockFile(_lock_filename.c_str());
  if (errCode != ERROR_OK) {
    SDB_FATAL_EXIT_CODE("xxxxx", sdb::Logger::FIXME, EXIT_COULD_NOT_LOCK,
                        "failed to lock the database directory using '",
                        _lock_filename, "': ", GetErrorStr(errCode));
  }

  // Register cleanup handler for shutdown
  auto cleanupHandler = std::make_unique<CleanupFunctions::CleanupFunction>(
    [&](int exitCode, void* userData) {
      // Ignore return value on cleanup
      std::ignore = SdbDestroyLockFile(_lock_filename.c_str());
    });
  CleanupFunctions::registerFunction(std::move(cleanupHandler));
}

void LockfileFeature::unprepare() {
  // Clean up lock file during feature shutdown
  std::ignore = SdbDestroyLockFile(_lock_filename.c_str());
}

}  // namespace sdb

