using namespace llvm;

/// Parses a comma-separated feature string and populates the given vector.
void SubtargetFeatures::Split(std::vector<std::string> &V, StringRef S) {
  SmallVector<StringRef, 3> Parts;
  S.split(Parts, ',', /*MaxSplit=*/-1, /*KeepEmpty=*/false);

  V.clear();
  V.reserve(Parts.size());

  for (StringRef Part : Parts) {
    if (!Part.empty())
      V.emplace_back(Part.str());
  }
}

/// Adds a single feature string to the internal list, handling flags and case normalization.
void SubtargetFeatures::AddFeature(StringRef FeatureStr, bool Enable) {
  if (FeatureStr.empty())
    return;

  // Normalize to lowercase
  std::string Lowered = FeatureStr.lower();

  // Check if already has explicit flag (+/-)
  bool HasFlag = (Lowered.front() == '+' || Lowered.front() == '-');

  if (HasFlag) {
    Features.push_back(std::move(Lowered));
  } else {
    Features.push_back(std::string(Enable ? "+" : "-") + Lowered);
  }
}

/// Appends multiple features from another collection.
void SubtargetFeatures::addFeaturesVector(
    const ArrayRef<std::string> AdditionalFeatures) {
  Features.insert(Features.end(), 
                  AdditionalFeatures.begin(), 
                  AdditionalFeatures.end());
}

/// Constructor: initializes features by parsing the input string.
SubtargetFeatures::SubtargetFeatures(StringRef Initial) {
  Split(Features, Initial);
}

/// Returns all features as a comma-separated string.
std::string SubtargetFeatures::getString() const {
  return join(Features, ",");
}

/// Outputs features to a stream, space-separated with trailing newline.
void SubtargetFeatures::print(raw_ostream &OS) const {
  bool First = true;
  for (const auto &F : Features) {
    if (!First) OS << ' ';
    OS << F;
    First = false;
  }
  OS << '\n';
}

#if !defined(NDEBUG) || defined(LLVM_ENABLE_DUMP)
LLVM_DUMP_METHOD void SubtargetFeatures::dump() const {
  print(dbgs());
}
#endif

/// Populates default features based on target triple information.
void SubtargetFeatures::getDefaultSubtargetFeatures(const Triple& TargetTriple) {
  // TODO: Consider moving this logic to tablegen or IR metadata for better maintainability.

  if (TargetTriple.getVendor() != Triple::Apple)
    return;

  switch (TargetTriple.getArch()) {
    case Triple::ppc:
      AddFeature("altivec");
      break;
    case Triple::ppc64:
      AddFeature("64bit");
      AddFeature("altivec");
      break;
    default:
      break;
  }
}

