// Pseudorandom number generator instance
Random Math::rand = Random();

// Generates a pseudorandom double in the range [0.0, 1.0)
// Uses an internal Random object that's created once and reused
// Thread-safe implementation for concurrent access
double Math::random() {
    return Math::rand.nextDouble();
}

// Rounds a double value to the nearest long integer
// Implementation follows: (long)Math.floor(a + 0.5d)
// Handles special cases: NaN → 0, overflow → MIN/MAX values
std::int64_t Math::round(double d) {
    return static_cast<std::int64_t>(floor(d + 0.5));
}

// Integer maximum function
int Math::_max(int x, int y) {
    return (x > y) ? x : y;
}

// Integer minimum function
int Math::_min(int x, int y) {
    return (x < y) ? x : y;
}

// Floating-point maximum function
float Math::_max(float x, float y) {
    return (x > y) ? x : y;
}

// Floating-point minimum function
float Math::_min(float x, float y) {
    return (x < y) ? x : y;
}

// Wraps an angle in degrees to the range [-180, 180)
float Math::wrapDegrees(float angle) {
    // Normalize to [0, 360)
    while (angle >= 360.0f) {
        angle -= 360.0f;
    }
    while (angle < 0.0f) {
        angle += 360.0f;
    }
    // Shift to [-180, 180)
    if (angle >= 180.0f) {
        angle -= 360.0f;
    }
    return angle;
}

// Wraps an angle in degrees to the range [-180, 180)
double Math::wrapDegrees(double angle) {
    // Normalize to [0, 360)
    while (angle >= 360.0) {
        angle -= 360.0;
    }
    while (angle < 0.0) {
        angle += 360.0;
    }
    // Shift to [-180, 180)
    if (angle >= 180.0) {
        angle -= 360.0;
    }
    return angle;
}

