// Apply Wi-Fi power state: disable or enable connection with stored credentials
void applyWifiPower(bool isActive) {
    if (!isActive) {
        // Disable Wi-Fi auto-reconnect and disconnect current connection
        WiFi.setAutoReconnect(false);
        WiFi.disconnect(true, true);
        WiFi.mode(WIFI_OFF);
        return;
    }

    // Enable station mode and auto-reconnect
    WiFi.mode(WIFI_STA);
    WiFi.setAutoReconnect(true);

    String storedSsid, storedPass;
    if (wifiStoreLoad(storedSsid, storedPass)) {
        // Begin connection using loaded credentials
        WiFi.begin(storedSsid.c_str(), storedPass.c_str());
    } else {
        // No valid credentials found; disable auto-reconnect and disconnect
        WiFi.setAutoReconnect(false);
        WiFi.disconnect(true, true);
    }
}

// Reset Wi-Fi settings by clearing saved credentials and disconnecting
void wifiResetSettings() {
    Preferences prefs;
    prefs.begin("rh_wifi", false);
    prefs.putString("ssid", "");
    prefs.putString("pass", "");
    prefs.end();

    // Force disconnection from current network
    WiFi.disconnect(true, true);
    delay(50);
}

