#include <asio.hpp>
#include <iostream>

// Reimplementation using a different control flow and variable naming
class bank_account_v2
{
    int current_balance_ = 0;
    mutable asio::thread_pool executor{1};

public:
    void credit(int value)
    {
        auto future = asio::post(
            executor,
            asio::use_future([=] {
                current_balance_ += value;
            })
        );
        future.get();
    }

    bool debit(int value)
    {
        auto future = asio::post(
            executor,
            asio::use_future([=] {
                if (current_balance_ >= value) {
                    current_balance_ -= value;
                    return true;
                }
                return false;
            })
        );
        return future.get();
    }

    int get_balance() const
    {
        auto future = asio::post(
            executor,
            asio::use_future([=] {
                return current_balance_;
            })
        );
        return future.get();
    }
};

int main()
{
    bank_account_v2 account;
    account.credit(20);
    account.debit(10);
    std::cout << "balance = " << account.get_balance() << "\n";
}

