// Configuration constants for buffer management
constexpr std::size_t BUFFER_CAPACITY = 8192;
constexpr std::size_t TRIGGER_LEVEL   = BUFFER_CAPACITY / 4;

rocprofiler_buffer_id_t retired_cid_buffer;

void handle_tracing_data(
    rocprofiler_context_id_t /* ctx */,
    rocprofiler_buffer_id_t /* buf_id */,
    rocprofiler_record_header_t** record_headers,
    std::size_t num_records,
    void* /* user_ptr */,
    uint64_t /* dropped_count */)
{
    std::ostringstream oss;
    for (std::size_t idx = 0; idx < num_records; ++idx) {
        auto* hdr = record_headers[idx];
        if (!hdr) {
            throw std::runtime_error{
                "rocprofiler returned a null header pointer — unexpected condition"};
        }

        if (hdr->hash != rocprofiler_record_header_compute_hash(hdr->category, hdr->kind)) {
            throw std::runtime_error{"record hash mismatch: category | kind ≠ hash"};
        }

        if (hdr->category == ROCPROFILER_BUFFER_CATEGORY_TRACING) {
            if (hdr->kind == ROCPROFILER_BUFFER_TRACING_CORRELATION_ID_RETIREMENT) {
                auto* retire_rec =
                    static_cast<rocprofiler_buffer_tracing_correlation_id_retirement_record_t*>(
                        hdr->payload);
                oss << "... The retired internal correlation id is: "
                    << retire_rec->internal_correlation_id;
                oss << ", timestamp: " << retire_rec->timestamp;
                oss << '\n';
                // TODO: verify retiring timestamp > max PC sample timestamp for this CID
            }
        }
    }

    *utils::get_output_stream() << oss.str();
}

void setup_cid_retirement_service(rocprofiler_context_id_t context)
{
    ROCPROFILER_CALL(
        rocprofiler_create_buffer(context,
                                  BUFFER_CAPACITY,
                                  TRIGGER_LEVEL,
                                  ROCPROFILER_BUFFER_POLICY_LOSSLESS,
                                  handle_tracing_data,
                                  nullptr,
                                  &retired_cid_buffer),
        "buffer creation");

    ROCPROFILER_CALL(
        rocprofiler_configure_buffer_tracing_service(
            context,
            ROCPROFILER_BUFFER_TRACING_CORRELATION_ID_RETIREMENT,
            nullptr,
            0,
            retired_cid_buffer),
        "configure tracing service for CID retirement");
}

void flush_cid_retirements()
{
    ROCPROFILER_CALL(rocprofiler_flush_buffer(retired_cid_buffer),
                     "failed to flush CID retirement buffer");
    *utils::get_output_stream() << "CID retirements flushed..." << std::endl;
}

