namespace lbug {
namespace function {

// Helper: determines if negation would overflow for a given type
template<typename T>
static bool canNegateWithoutOverflow(T value) {
    return value != NumericLimits<T>::minimum();
}

// Core logic: compute absolute value safely, returns false on overflow
template<typename T>
static bool safeAbsCompute(T input, T& output) {
    if (!canNegateWithoutOverflow(input)) {
        return false;
    }
    output = input < 0 ? -input : input;
    return true;
}

// Wrapper struct to encapsulate in-place absolute value operations
struct InPlaceAbsoluteValue {
    template<typename Type>
    static bool apply(Type& source, Type& target);
};

// Explicit specializations for each supported integer width
template<>
bool InPlaceAbsoluteValue::apply(int8_t& src, int8_t& dst) {
    return safeAbsCompute<int8_t>(src, dst);
}

template<>
bool InPlaceAbsoluteValue::apply(int16_t& src, int16_t& dst) {
    return safeAbsCompute<int16_t>(src, dst);
}

template<>
bool InPlaceAbsoluteValue::apply(int32_t& src, int32_t& dst) {
    return safeAbsCompute<int32_t>(src, dst);
}

template<>
bool InPlaceAbsoluteValue::apply(int64_t& src, int64_t& dst) {
    return safeAbsCompute<int64_t>(src, dst);
}

// Public interface: throws exception on overflow for fixed-width integers
template<>
void Abs::operation(int8_t& val, int8_t& out) {
    if (!InPlaceAbsoluteValue::apply(val, out)) {
        throw common::OverflowException{
            std::format("Overflow occurred when computing abs({}) — value out of INT8 range.",
                common::TypeUtils::toString(val))
        };
    }
}

template<>
void Abs::operation(int16_t& val, int16_t& out) {
    if (!InPlaceAbsoluteValue::apply(val, out)) {
        throw common::OverflowException{
            std::format("Overflow occurred when computing abs({}) — value out of INT16 range.",
                common::TypeUtils::toString(val))
        };
    }
}

template<>
void Abs::operation(int32_t& val, int32_t& out) {
    if (!InPlaceAbsoluteValue::apply(val, out)) {
        throw common::OverflowException{
            std::format("Overflow occurred when computing abs({}) — value out of INT32 range.",
                common::TypeUtils::toString(val))
        };
    }
}

template<>
void Abs::operation(int64_t& val, int64_t& out) {
    if (!InPlaceAbsoluteValue::apply(val, out)) {
        throw common::OverflowException{
            std::format("Overflow occurred when computing abs({}) — value out of INT64 range.",
                common::TypeUtils::toString(val))
        };
    }
}

// Specialization for int128: no overflow possible, direct computation
template<>
void Abs::operation(common::int128_t& val, common::int128_t& out) {
    out = (val < 0) ? -val : val;
}

} // namespace function
} // namespace lbug

#include "../core/clauses/bk-clauses.hpp"
#include <CLI/CLI.hpp>
#include <iostream>
#include <unordered_map>
#include <string>
#include <vector>

int main(int argc, char* argv[]) {
    // Initialize CLI application with description
    CLI::App cli_app{"beekeeperman"};

    // Storage for parsed data
    std::string selected_verb;
    std::unordered_map<std::string, std::string> flag_value_map;
    std::vector<std::string> positional_args;

    // Dynamically register all available commands from registry
    for (const auto& [cmd_name, cmd_info] : clauses_registry) {
        // Add subcommand with name and description
        CLI::App* sub_cmd = cli_app.add_subcommand(cmd_name, cmd_info.description);

        // Set callback to capture which verb was invoked
        sub_cmd->callback([&]() {
            selected_verb = cmd_name;
        });

        // Register each allowed option for this command
        for (const auto& opt_def : cmd_info.allowed_options) {
            std::string long_opt = "--" + opt_def.long_name;
            if (!opt_def.short_name.empty()) {
                long_opt += ",-" + opt_def.short_name;
            }

            if (opt_def.requires_value) {
                // Option expects a value
                sub_cmd->add_option(long_opt, flag_value_map[opt_def.long_name])
                    ->required(false);
            } else {
                // Boolean flag
                sub_cmd->add_flag(long_opt, [&](std::size_t) {
                    flag_value_map[opt_def.long_name] = "true";
                });
            }
        }

        // Accept remaining positional arguments as subjects
        sub_cmd->add_option("positional", positional_args, "Input subjects")
            ->expected(-1); // Allow multiple values
    }

    // Enforce that exactly one subcommand must be present
    try {
        cli_app.require_subcommand();
        cli_app.parse(argc, argv);
    } catch (const CLI::Error& err) {
        return cli_app.exit(err);
    }

    // Execute the handler associated with the selected verb
    auto it = clauses_registry.find(selected_verb);
    if (it == clauses_registry.end()) {
        std::cerr << "Internal error: verb '" << selected_verb << "' not found in registry." << std::endl;
        return 1;
    }

    command_streams result = it->second.handler(flag_value_map, positional_args);

    // Output results in order: stderr first, then stdout, finally exit code
    if (!result.stderr_str.empty()) {
        std::cerr << result.stderr_str << '\n';
    }
    if (!result.stdout_str.empty()) {
        std::cout << result.stdout_str << '\n';
    }

    return result.errcode;
}

