// Custom class with controlled construction/destruction
class sacred {
private:
    sacred() : value(0) {}
    sacred(int v) : value(v) {}
    ~sacred() {}

public:
    struct destroyer {
        void operator()(sacred* ptr) const {
            release(*ptr);
        }
    };

    const int value;

    static std::unique_ptr<sacred, destroyer> instantiate() {
        std::cout << "instantiating 'sacred' unique_ptr and "
                     "allowing sol/Lua to manage it"
                  << std::endl;
        return std::unique_ptr<sacred, destroyer>(new sacred(50));
    }

    static void construct(sacred& raw_memory) {
        std::cout << "constructing 'sacred' object at "
                  << static_cast<void*>(&raw_memory)
                  << std::endl;
        new (&raw_memory) sacred();
    }

    static void release(sacred& obj) {
        std::cout << "releasing 'sacred' object at "
                  << static_cast<void*>(&obj)
                  << std::endl;
        obj.~sacred();
    }
};

