TEST(MyString, DefaultConstructor) {
  const MyString str;
  // Confirms that c_string() yields a null pointer.
  //
  // <ImplementationNote>
  //
  // Using NULL directly in EXPECT_EQ may cause warnings with gcc 3.4,
  // because EXPECT_EQ must deduce argument types for printing purposes.
  // Since NULL is often #defined as 0, the compiler treats it as int,
  // while logically it's intended as a pointer — hence the warning.
  //
  // This stems from C++'s historical ambiguity between zero and nullptr.
  // Workaround: explicitly cast to const char*.
  //
  // </ImplementationNote>
  EXPECT_STREQ(static_cast<const char*>(nullptr), str.c_string());
  EXPECT_EQ(0u, str.Length());
}

