// Constructor for PPCXCOFFStreamer - initializes base MCXCOFFStreamer with provided components
PPCXCOFFStreamer::PPCXCOFFStreamer(MCContext &Context,
                                   std::unique_ptr<MCAsmBackend> MAB,
                                   std::unique_ptr<MCObjectWriter> OW,
                                   std::unique_ptr<MCCodeEmitter> Emitter)
    : MCXCOFFStreamer(Context, std::move(MAB), std::move(OW),
                      std::move(Emitter)) {}

// Emit a prefixed instruction with alignment handling to prevent crossing 64-byte boundaries
void PPCXCOFFStreamer::emitPrefixedInstruction(const MCInst &Inst,
                                               const MCSubtargetInfo &STI) {
  // Ensure prefixed instructions do not cross a 64-byte boundary:
  // Insert padding (up to 4 bytes) before the instruction if needed.
  emitCodeAlignment(Align(64), &STI, /*MaxBytesToEmit=*/4);

  // Now emit the actual prefixed instruction.
  // The previous alignment call may have started a new fragment; this instruction
  // will begin in that newly created fragment.
  MCXCOFFStreamer::emitInstruction(Inst, STI);
}

// Override emitInstruction to handle prefixed instructions specially
void PPCXCOFFStreamer::emitInstruction(const MCInst &Inst,
                                       const MCSubtargetInfo &STI) {
  // Get the code emitter and cast it to PPC-specific version
  PPCMCCodeEmitter *Emitter =
      static_cast<PPCMCCodeEmitter *>(getAssembler().getEmitterPtr());

  // Only apply special logic for prefixed instructions
  if (!Emitter->isPrefixedInstruction(Inst)) {
    // For non-prefixed instructions, delegate to base class
    MCXCOFFStreamer::emitInstruction(Inst, STI);
    return;
  }

  // Handle prefixed instructions with alignment constraints
  emitPrefixedInstruction(Inst, STI);
}

// Factory function to instantiate a PPC XCOFF streamer
MCXCOFFStreamer *
llvm::createPPCXCOFFStreamer(MCContext &Context,
                             std::unique_ptr<MCAsmBackend> MAB,
                             std::unique_ptr<MCObjectWriter> OW,
                             std::unique_ptr<MCCodeEmitter> Emitter) {
  return new PPCXCOFFStreamer(Context, std::move(MAB), std::move(OW),
                              std::move(Emitter));
}

