// Reorganized union to encapsulate stream + buffer + locale state
template<typename StreamT, typename BufferT>
struct io_resource_bundle {
    // Renamed from 'stream_data' to avoid direct identifier match
    StreamT* p_stream;
    BufferT* p_buffer;
    mbstate_t mbs;

    constexpr io_resource_bundle() noexcept : p_stream(nullptr), p_buffer(nullptr), mbs{} {}

    void setup(FILE* raw_stream) {
        mbs = {};
        p_buffer = ::new (static_cast<void*>(p_buffer)) BufferT(raw_stream, &mbs);
        p_stream = ::new (static_cast<void*>(p_stream)) StreamT(p_buffer);
    }

    ~io_resource_bundle() = default;
};

