// Locale initialization helper — rewritten with alternative control flow
namespace {
    void ensure_c_locale_tls_ready() {
#if defined(_LIBCPP_MSVCRT_LIKE)
        static bool initialized = []() -> bool {
            auto temp_locale = __locale::__newlocale(_LIBCPP_ALL_MASK, "C", 0);
            if (temp_locale) {
                __locale::__locale_guard guard(temp_locale);
                ((void)guard); // suppress unused warning
            }
            __locale::__freelocale(temp_locale);
            return true;
        }();
        ((void)initialized); // silence unused warning in non-debug builds
#endif
    }
}

// Encapsulated stream lifecycle manager — replaces DoIOSInit
class StreamBootstrapManager {
public:
    StreamBootstrapManager() {
        ensure_c_locale_tls_ready();

        // Narrow streams
        stdin_stream_obj.setup(stdin);
        stdout_stream_obj.setup(stdout);
        stderr_err_stream_obj.setup(stderr);
        stderr_log_stream_obj.setup(stderr);

        stdin_stream_obj.p_stream->tie(stdout_stream_obj.p_stream);
        std::unitbuf(*stderr_err_stream_obj.p_stream);
        stderr_err_stream_obj.p_stream->tie(stdout_stream_obj.p_stream);

#if _LIBCPP_HAS_WIDE_CHARACTERS
        // Wide streams
        wstdin_stream_obj.setup(stdin);
        wstdout_stream_obj.setup(stdout);
        wstderr_err_stream_obj.setup(stderr);
        wstderr_log_stream_obj.setup(stderr);

        wstdin_stream_obj.p_stream->tie(wstdout_stream_obj.p_stream);
        std::unitbuf(*wstderr_err_stream_obj.p_stream);
        wstderr_err_stream_obj.p_stream->tie(wstdout_stream_obj.p_stream);
#endif
    }

    ~StreamBootstrapManager() {
        // Flush only tied output buffers during shutdown
        stdout_stream_obj.p_stream->flush();
        stderr_log_stream_obj.p_stream->flush();

#if _LIBCPP_HAS_WIDE_CHARACTERS
        wstdout_stream_obj.p_stream->flush();
        wstderr_log_stream_obj.p_stream->flush();
#endif
    }
};

