using namespace llvm;

// Propagate profile counts within an SCC by aggregating incoming contributions
// from other nodes in the same SCC, then apply updates atomically.
template <typename CallGraphType>
void SyntheticCountsUtils<CallGraphType>::propagateFromSCC(
    const SccTy &sccNodesList,
    GetProfCountTy GetProfCount,
    AddCountTy AddCount) {

  DenseSet<NodeRef> sccMemberSet;
  SmallVector<std::pair<NodeRef, EdgeRef>, 8> internalEdges;
  SmallVector<std::pair<NodeRef, EdgeRef>, 8> externalEdges;

  // Populate set of SCC members for quick lookup
  for (const NodeRef node : sccNodesList)
    sccMemberSet.insert(node);

  // Classify outgoing edges: those staying inside SCC vs leaving it
  for (const NodeRef srcNode : sccMemberSet) {
    using ChildRange = decltype(children_edges<CallGraphType>(srcNode));
    for (auto edgeIt = children_edges<CallGraphType>(srcNode).begin(),
              edgeEnd = children_edges<CallGraphType>(srcNode).end();
         edgeIt != edgeEnd; ++edgeIt) {
      const EdgeRef edge = *edgeIt;
      const NodeRef destNode = CGT::edge_dest(edge);
      if (sccMemberSet.count(destNode))
        internalEdges.emplace_back(srcNode, edge);
      else
        externalEdges.emplace_back(srcNode, edge);
    }
  }

  // Accumulate additional counts per node due to intra-SCC propagation
  DenseMap<NodeRef, Scaled64> deltaCounts;
  for (const auto &edgeInfo : internalEdges) {
    const NodeRef caller = edgeInfo.first;
    const EdgeRef callEdge = edgeInfo.second;
    auto maybeCount = GetProfCount(caller, callEdge);
    if (!maybeCount.hasValue())
      continue;
    const NodeRef callee = CGT::edge_dest(callEdge);
    deltaCounts[callee] += *maybeCount;
  }

  // Apply accumulated deltas to all affected nodes in SCC
  for (const auto &pair : deltaCounts)
    AddCount(pair.first, pair.second);

  // Propagate counts across edges leading outside the SCC
  for (const auto &edgeInfo : externalEdges) {
    const NodeRef caller = edgeInfo.first;
    const EdgeRef callEdge = edgeInfo.second;
    auto maybeCount = GetProfCount(caller, callEdge);
    if (!maybeCount.hasValue())
      continue;
    const NodeRef callee = CGT::edge_dest(callEdge);
    AddCount(callee, *maybeCount);
  }
}

// Traverse the call graph in top-down SCC order and propagate counts accordingly.
// The SCC iterator yields bottom-up order, so we reverse before processing.
template <typename CallGraphType>
void SyntheticCountsUtils<CallGraphType>::propagate(
    const CallGraphType &callGraph,
    GetProfCountTy GetProfCount,
    AddCountTy AddCount) {

  std::vector<SccTy> sccList;
  for (auto iter = scc_begin(callGraph); !iter.isAtEnd(); ++iter)
    sccList.push_back(*iter);

  // Process SCCs from roots toward leaves (topological order)
  for (auto rit = sccList.rbegin(), rend = sccList.rend(); rit != rend; ++rit)
    propagateFromSCC(*rit, GetProfCount, AddCount);
}

// Explicit template instantiations
template class llvm::SyntheticCountsUtils<const CallGraph *>;
template class llvm::SyntheticCountsUtils<ModuleSummaryIndex *>;

#include <iostream>
#include <string>
#include <asio/ip/tcp.hpp>

using asio::ip::tcp;

int main(int argc, char* argv[]) {
    try {
        if (argc != 3) {
            std::cerr << "Usage: http_client <server> <path>\n"
                      << "Example:\n"
                      << "  http_client www.boost.org /LICENSE_1_0.txt\n";
            return 1;
        }

        tcp::iostream connection;

        // Set a timeout of 60 seconds for the entire operation
        connection.expires_after(std::chrono::seconds(60));

        // Connect to the specified server on the HTTP port
        connection.connect(argv[1], "http");

        if (!connection) {
            std::cerr << "Connection failed: " << connection.error().message() << "\n";
            return 1;
        }

        // Build and send HTTP GET request
        connection << "GET " << argv[2] << " HTTP/1.0\r\n"
                   << "Host: " << argv[1] << "\r\n"
                   << "Accept: */*\r\n"
                   << "Connection: close\r\n\r\n";

        // Read and validate HTTP version
        std::string version;
        connection >> version;

        // Read status code
        unsigned int code;
        connection >> code;

        // Read status message (rest of line after status code)
        std::string msg;
        std::getline(connection, msg);

        // Verify response format
        if (!connection || version.substr(0, 5) != "HTTP/") {
            std::cerr << "Malformed HTTP response received\n";
            return 1;
        }

        // Check for successful status
        if (code != 200U) {
            std::cerr << "HTTP error: " << code << " " << msg << "\n";
            return 1;
        }

        // Print headers until blank line
        std::string line;
        while (std::getline(connection, line)) {
            if (line.empty() || line == "\r") break;
            std::cout << line << "\n";
        }
        std::cout << "\n";  // Blank line after headers

        // Output the body content
        std::cout << connection.rdbuf();
    }
    catch (const std::exception& ex) {
        std::cerr << "Runtime error: " << ex.what() << "\n";
        return 1;
    }

    return 0;
}

