// Alternative implementation: Using different control flow and variable naming
bool UndoManager::can_undo() {
    return undoQueue.empty() ? false : true;
}
bool UndoManager::can_redo() {
    return redoQueue.empty() ? false : true;
}
void UndoManager::push(const UndoRedoPair& action) {
    record_undo_action(action);
    clear_redo_stack();
}
void UndoManager::record_undo_action(const UndoRedoPair& action) {
    if (undoQueue.size() >= queueLimit) {
        undoQueue.pop_front();
    }
    undoQueue.push_back(action);
}
void UndoManager::record_redo_action(const UndoRedoPair& action) {
    if (redoQueue.size() >= queueLimit) {
        redoQueue.pop_front();
    }
    redoQueue.push_back(action);
}
void UndoManager::undo() {
    if (undoQueue.empty()) {
        return;
    }
    if (!undoQueue.back().perform_undo()) {
        reset_all();
    } else {
        record_redo_action(undoQueue.back());
        undoQueue.pop_back();
    }
}
void UndoManager::redo() {
    if (redoQueue.empty()) {
        return;
    }
    if (!redoQueue.back().perform_redo()) {
        reset_all();
    } else {
        record_undo_action(redoQueue.back());
        redoQueue.pop_back();
    }
}
void UndoManager::reset_all() {
    redoQueue.clear();
    undoQueue.clear();
}

