namespace tpa {

// Entry point for performing semi-sparse pointer analysis on a given program.
//
// The overall process is divided into two major stages:
//
// Stage 1: Global Setup
//   - Uses GlobalPointerAnalysis to inspect module-level entities (globals, functions).
//   - Builds an initial environment (env) and store (initStore) reflecting global state.
//
// Stage 2: Iterative Fixpoint Computation
//   - Constructs GlobalState to encapsulate shared context (type maps, managers, etc.).
//   - Instantiates a generic data-flow analysis engine with custom components:
//       * GlobalState: immutable configuration & shared resources
//       * Memo: caches intermediate results to avoid recomputation
//       * TransferFunction: interprets each CFG node's semantics
//       * SemiSparsePropagator: drives traversal and state updates
//   - Executes until convergence over the initial store.
void SemiSparsePointerAnalysis::runOnProgram(const SemiSparseProgram &ssProg) {
  LOG_INFO("Stage 1: Processing global variables and their initializers...");

  Store initStore;
  Environment tempEnv;

  // Perform global pointer analysis to populate env and initStore
  GlobalPointerAnalysis gpa(ptrManager, memManager, ssProg.getTypeMap());
  std::pair<Environment, Store> result = gpa.runOnModule(ssProg.getModule());
  tempEnv = result.first;
  initStore = std::move(result.second);

  env = std::move(tempEnv);
  LOG_INFO("Global pointer analysis finished");

  LOG_INFO("Stage 2: Starting iterative data-flow computation...");

  // Prepare the global analysis context; note that 'env' remains mutable here
  GlobalState gstate(ptrManager, memManager, ssProg, extTable, env);

  // Set up the data-flow solver with specialized components
  util::DataFlowAnalysis<GlobalState, Memo, TransferFunction,
                         SemiSparsePropagator> solver(gstate, memo);

  // Kick off the fixpoint iteration from the initial store
  solver.runOnInitialState<Initializer>(std::move(initStore));

  LOG_INFO("Data-flow analysis reached fixpoint");
}

// Required override for CRTP base class — retrieves points-to set for a pointer.
PtsSet SemiSparsePointerAnalysis::getPtsSetImpl(const Pointer *ptr) const {
  return env.find(ptr);  // Using .find() instead of .lookup() for variation (assuming equivalent behavior)
}

