MatchForwardOrderSafe::token MatchForwardOrderSafe::choose(const bool b) {
  // Return token A if condition is true, otherwise token B
  return b ? token::A : token::B;
}

unsigned int
MatchForwardOrderSafe::encode(const MatchForwardOrderSafe::token x) {
  // Lambda function to handle encoding based on token type
  auto encode_lambda = [&]() -> unsigned int {
    switch (x) {
      case token::A:
        // Encode A as 1 (0 + 1)
        return 1u;
      case token::B:
        // Encode B as 0
        return 0u;
      default:
        // Should not reach here, but for safety
        return 0u;
    }
  };

  return encode_lambda();
}

