namespace unravel
{
    selection_action_t::selection_action_t(editing_manager* mgr,
                                           const std::vector<entt::meta_any>& prev_sel,
                                           const std::vector<entt::meta_any>& curr_sel, bool is_select)
        : manager(mgr), old_selection(prev_sel), new_selection(curr_sel), is_select(is_select)
    {
        action_name = is_select ? "Select" : "Unselect";
        can_undo = true;
    }

    void selection_action_t::do_action()
    {
        if (!manager)
            return;

        // Apply the current (new) selection state via internal helper
        manager->apply_selection_impl(new_selection);
    }

    void selection_action_t::undo_action()
    {
        if (!manager)
            return;

        // Revert to the prior (old) selection state via internal helper
        manager->apply_selection_impl(old_selection);
    }

    auto selection_action_t::is_mergeable(const editing_action_t& earlier) const -> bool
    {
        const auto& other_sel_action = static_cast<const selection_action_t&>(earlier);

        // Only merge if both actions have the same operation type (select/unselect)
        if (other_sel_action.is_select != is_select)
            return false;

        // Empty selections are trivially mergeable
        if (old_selection.empty() && other_sel_action.new_selection.empty())
            return true;

        // Size mismatch implies non-mergeability
        if (old_selection.size() != other_sel_action.new_selection.size())
            return false;

        // Check set equality (order-insensitive): every element in old must appear in earlier's new
        for (const auto& item_in_old : old_selection)
        {
            bool match_found = false;
            for (const auto& item_in_earlier_new : other_sel_action.new_selection)
            {
                if (item_in_old == item_in_earlier_new)
                {
                    match_found = true;
                    break;
                }
            }
            if (!match_found)
                return false;
        }

        return true;
    }

    void selection_action_t::merge_with(const editing_action_t& earlier)
    {
        const auto& other_sel_action = static_cast<const selection_action_t&>(earlier);

        // Preserve the earliest starting point (from previous action's old)
        old_selection = other_sel_action.old_selection;
        // Retain the latest target state (current action's new remains unchanged)
        // (new_selection is already up-to-date from construction)
    }

    auto selection_action_t::is_valid() const -> bool
    {
        return manager != nullptr;
    }
} // namespace unravel

