#include "ConstrainedMeshSmoothers.h"
#include "MatrixSolver.h"
#include "ConstrainedPoissonSolver.h"

bool FBiHarmonicMeshSmoother::ComputeSmoothedMeshPositions(TArray<FVector3d>& OutPositions)
{
    UpdateSolverConstraints();

    // Prepare right-hand side vector for the biharmonic system
    FSOAPositions RHSVector(InternalVertexCount);

    if (InternalVertexCount != VertexCount) // boundary vertices present
    {
        for (int32 axis = 0; axis < 3; ++axis)
        {
            RHSVector.Array(axis) = BoundaryOperator * BoundaryPositions.Array(axis);
        }
    }
    else
    {
        RHSVector.ZeroInitialize();
    }

    // Solve the constrained optimization problem
    FSOAPositions ResultVector(InternalVertexCount);
    bool bSolvedSuccessfully = ConstrainedSolver->Solve(RHSVector, ResultVector);

    // Apply post-fix constraints if any
    ApplyPostFixConstraints(ResultVector);

    // Prepare output buffer with correct size and capacity
    const int32 TotalVertices = VtxLinearization.ToId().Num();
    OutPositions.Reset(TotalVertices);
    OutPositions.SetNumUninitialized(TotalVertices);

    // Populate internal vertex positions from solution
    TransferInternalSolution(ResultVector, OutPositions);

    // Fill in boundary vertex positions
    TransferBoundaryPositions(OutPositions);

    return bSolvedSuccessfully;
}

bool FCGBiHarmonicMeshSmoother::ComputeSmoothedMeshPositions(TArray<FVector3d>& OutPositions)
{
    UpdateSolverConstraints();

    // Construct source term for the CG-based solver
    FSOAPositions RHSVector(InternalVertexCount);

    if (InternalVertexCount != VertexCount) // non-empty boundary set
    {
        for (int32 dim = 0; dim < 3; ++dim)
        {
            RHSVector.Array(dim) = BoundaryOperator * BoundaryPositions.Array(dim);
        }
    }
    else
    {
        RHSVector.FillZero();
    }

    // Compute solution using constrained conjugate gradient method
    FSOAPositions SolutionArray(InternalVertexCount);
    bool bSuccess = ConstrainedSolver->Solve(RHSVector, SolutionArray);

    // Enforce additional post-fix constraints
    ApplyPostFixConstraints(SolutionArray);

    // Resize output array to hold all vertex positions
    const int32 MaxIndex = VtxLinearization.ToId().Num();
    OutPositions.Empty(MaxIndex);
    OutPositions.AddDefaulted(MaxIndex);

    // Copy computed internal node coordinates into output structure
    MoveInternalResultsIntoOutput(SolutionArray, OutPositions);

    // Ensure boundary nodes are correctly assigned
    MoveBoundaryNodesIntoOutput(OutPositions);

    return bSuccess;
}

