#include <vector>

// Helper function to send a query and get the response
int performQuery(int slice) {
    std::cout << "? " << slice << std::endl;
    int result;
    std::cin >> result;
    if (result == -1) {
        std::exit(0); // Terminate on judge error
    }
    return result;
}

// Helper function to output a matched pair
void reportMatch(int first, int second) {
    std::cout << "! " << first << " " << second << std::endl;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::cin >> n;

    // Track which slices have been paired
    std::vector<bool> isPaired(2 * n + 1, false);
    // Store indices of currently unmatched slices
    std::vector<int> unmatchedSlices;
    // Current count of distinct mineral types in the device
    int currentDistinctCount = 0;

    for (int idx = 1; idx <= 2 * n; ++idx) {
        if (isPaired[idx]) {
            continue;
        }

        int newDistinctCount = performQuery(idx);

        if (newDistinctCount > currentDistinctCount) {
            // This slice introduces a new mineral type
            unmatchedSlices.push_back(idx);
            currentDistinctCount = newDistinctCount;
        } else {
            // This slice completes a pair with an existing unmatched slice
            int targetCount = newDistinctCount;

            // Search backwards through unmatched slices to find the match
            for (int pos = static_cast<int>(unmatchedSlices.size()) - 1; pos >= 0; --pos) {
                int candidate = unmatchedSlices[pos];
                int testResult = performQuery(candidate);

                if (testResult == targetCount) {
                    // Found matching pair: idx and candidate
                    reportMatch(idx, candidate);
                    isPaired[idx] = true;
                    isPaired[candidate] = true;

                    // Remove the matched slice from unmatched list
                    unmatchedSlices.erase(unmatchedSlices.begin() + pos);
                    currentDistinctCount = testResult;
                    break;
                } else {
                    // Restore state by querying again (to revert the toggle effect)
                    performQuery(candidate);
                }
            }
        }
    }

    return 0;
}

#include "ReduceFunctionBodies.h"
#include "Delta.h"
#include "Utils.h"
#include "llvm/IR/GlobalValue.h"
#include "llvm/IR/Instructions.h"
using namespace llvm;

// Removes function bodies for functions not marked for preservation and without alias references
static void extractFunctionBodiesFromModule(Oracle &O,
                                            ReducerWorkItem &WorkItem) {
  Module &M = WorkItem.getModule();
  for (auto I = M.begin(), E = M.end(); I != E; ++I) {
    Function &F = *I;
    if (!F.isDeclaration() && !hasAliasUse(F) && !O.shouldKeep()) {
      F.dropAllReferences(); // Equivalent to deleteBody() + clearing linkage
      F.setComdat(nullptr);
    }
  }
}

void llvm::reduceFunctionBodiesDeltaPass(TestRunner &Test) {
  runDeltaPass(Test, extractFunctionBodiesFromModule,
               "Reducing Function Bodies");
}

// Clears personality, prefix, and prologue data from functions when not preserved
static void reduceFunctionData(Oracle &O, ReducerWorkItem &WorkItem) {
  Module &M = WorkItem.getModule();
  for (auto I = M.begin(), E = M.end(); I != E; ++I) {
    Function &F = *I;

    // Clear personality function if no exception handling is present
    if (F.hasPersonalityFn()) {
      bool hasEH = any_of(M, [](const BasicBlock &BB) {
        return BB.isEHPad() || isa<ResumeInst>(BB.getTerminator());
      });
      if (!hasEH && !O.shouldKeep()) {
        F.setPersonalityFn(nullptr);
      }
    }

    // Remove prefix and prologue data if not needed
    if (F.hasPrefixData() && !O.shouldKeep())
      F.setPrefixData(nullptr);
    if (F.hasPrologueData() && !O.shouldKeep())
      F.setPrologueData(nullptr);
  }
}

void llvm::reduceFunctionDataDeltaPass(TestRunner &Test) {
  runDeltaPass(Test, reduceFunctionData, "Reducing Function Data");
}

