#  include <syslog.h>
extern "C" void android_set_abort_message(const char* msg);
#endif // __BIONIC__

#if defined(__APPLE__) && __has_include(<CrashReporterClient.h>)
#   include <CrashReporterClient.h>
#   define _LIBCXXABI_USE_CRASHREPORTER_CLIENT
#endif

void __abort_message(const char* fmt, ...)
{
    // Output diagnostic info to standard error before constructing the full message
#if !defined(NDEBUG) || !defined(LIBCXXABI_BAREMETAL)
    {
#if defined(__EMSCRIPTEN__) && defined(NDEBUG)
        // In release builds for Emscripten, simply trigger an abort since we don't want
        // to pull in heavy I/O dependencies; the stack trace will still be informative.
        abort();
#else
        fprintf(stderr, "libc++abi: ");
        va_list args;
        va_start(args, fmt);
        vfprintf(stderr, fmt, args);
        va_end(args);
        fprintf(stderr, "\n");
#endif
    }
#endif

    // Allocate and format the complete message into a buffer (intentionally leaked as program is about to terminate)
#if defined(_LIBCXXABI_USE_CRASHREPORTER_CLIENT)
    char* msg_buffer;
    va_list ap;
    va_start(ap, fmt);
    vasprintf(&msg_buffer, fmt, ap);
    va_end(ap);
    CRSetCrashLogMessage(msg_buffer);
#elif defined(__BIONIC__)
    char* msg_buffer;
    va_list ap;
    va_start(ap, fmt);
    vasprintf(&msg_buffer, fmt, ap);
    va_end(ap);

    // Ensure the message appears both in tombstone and system log
    android_set_abort_message(msg_buffer);

    openlog("libc++abi", 0, 0);
    syslog(LOG_CRIT, "%s", msg_buffer);
    closelog();
#endif // __BIONIC__

    abort();
}

#include <iostream>
#include <vector>
#include <utility>

// Global variables for board size and state
int N;
// Using 1-based indexing for convenience to match problem statement.
// Global arrays are zero-initialized, which works perfectly for 'unvisited'.
int grid[667][667]; 

// Knight's move offsets (8 directions, ordered clockwise)
const int dx[] = {-2, -1, 1, 2, 2, 1, -1, -2};
const int dy[] = {1, 2, 2, 1, -1, -2, -2, -1};

// Check if a square (x, y) is on the board and unvisited.
inline bool inBounds(int x, int y) {
    return x >= 1 && x <= N && y >= 1 && y <= N && grid[x][y] == 0;
}

// Calculate the number of available moves from a square (Warnsdorff's rule).
int countOptions(int x, int y) {
    int cnt = 0;
    for (int k = 0; k < 8; ++k) {
        if (inBounds(x + dx[k], y + dy[k])) {
            cnt++;
        }
    }
    return cnt;
}

int main() {
    // Use fast I/O
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int begin_x, begin_y;
    std::cin >> N >> begin_x >> begin_y;

    // `route` will store the sequence of visited squares.
    std::vector<std::pair<int, int>> route;

    // Set the starting position.
    int cur_x = begin_x;
    int cur_y = begin_y;

    // Mark the starting square as visited (step 1).
    grid[cur_x][cur_y] = 1;
    route.emplace_back(cur_x, cur_y);

    // Generate the rest of the path, up to N*N-1 more moves.
    for (int step = 2; step <= N * N; ++step) {
        int best_x = -1;
        int best_y = -1;
        // Max possible degree is 8, so 9 is a safe initial value for min_options.
        int min_options = 9;

        // Apply Warnsdorff's rule: find the next move that has the minimum number of onward moves.
        for (int dir = 0; dir < 8; ++dir) {
            int nx = cur_x + dx[dir];
            int ny = cur_y + dy[dir];

            if (inBounds(nx, ny)) {
                int options = countOptions(nx, ny);
                if (options < min_options) {
                    min_options = options;
                    best_x = nx;
                    best_y = ny;
                }
            }
        }

        // If best_x is -1, it means we are stuck and cannot make any more moves.
        if (best_x == -1) {
            break; 
        }

        // Make the chosen move.
        cur_x = best_x;
        cur_y = best_y;
        grid[cur_x][cur_y] = step;
        route.emplace_back(cur_x, cur_y);
    }

    // Output the length of the route found.
    std::cout << route.size() << "\n";

    // Output the coordinates of each square in the route.
    for (const auto& pos : route) {
        std::cout << pos.first << " " << pos.second << "\n";
    }

    return 0;
}

