#include <iostream>
#include <vector>
#include <stepit/plugin.h>
#include <stepit/pyutils/npz_reader.h>
using namespace stepit;

int main(int argc, char **argv) {
  if (argc != 2) {
    std::cerr << "Usage: " << argv[0] << " <npz_file>" << std::endl;
    return 1;
  }

  try {
    NpzReader npz(argv[1]);

    // Initialize column width tracking variables
    std::size_t name_width = 4;
    std::size_t shape_width = 5;

    std::vector<std::string> var_names = npz.keys();
    std::vector<std::string> shape_strings;
    std::vector<std::string> dtype_strings;

    // Process each variable to determine formatting widths and collect metadata
    for (const auto &var_name : var_names) {
      // Update maximum name length
      name_width = std::max(name_width, var_name.length());

      // Format shape as string like "(dim1, dim2, ...)"
      shape_strings.push_back(fmt::format("({})", fmt::join(npz[var_name].shape, ", ")));
      shape_width = std::max(shape_width, shape_strings.back().length());

      // Store data type
      dtype_strings.push_back(npz[var_name].dtype);
    }

    // Add padding to column widths
    name_width += 2;
    shape_width += 2;

    // Print header
    std::cout << fmt::format("{:<{}}{:<{}}{}\n", 
                            "Name", name_width, 
                            "Shape", shape_width, 
                            "Dtype")
              << std::string(name_width + shape_width + 15, '-') << std::endl;

    // Print each variable's information
    for (std::size_t idx{}; idx < var_names.size(); ++idx) {
      std::cout << fmt::format("{:<{}}{:<{}}{}", 
                              var_names[idx], name_width, 
                              shape_strings[idx], shape_width, 
                              dtype_strings[idx]) 
                << std::endl;
    }

  } catch (const std::exception &err) {
    std::cerr << kRed << "ERROR: " << kClear << err.what() << std::endl;
    return 1;
  }

  return 0;
}

