namespace http {
namespace server3 {

server::server(const std::string& addr, const std::string& port_str,
    const std::string& root_dir, std::size_t worker_count)
  : worker_count_(worker_count),
    io_ctx_(io_context_),
    stop_signals_(io_context_),
    tcp_acceptor_(io_context_),
    active_connection_(),
    req_handler_(root_dir)
{
  // Set up signal handlers for graceful shutdown
  stop_signals_.add(SIGINT);
  stop_signals_.add(SIGTERM);
#if defined(SIGQUIT)
  stop_signals_.add(SIGQUIT);
#endif

  stop_signals_.async_wait([this](const asio::error_code&, int) {
    handle_stop();
  });

  // Resolve and bind endpoint
  asio::ip::tcp::resolver resolver(io_context_);
  auto endpoints = resolver.resolve(addr, port_str);
  auto ep = *endpoints.begin();

  tcp_acceptor_.open(ep.protocol());
  tcp_acceptor_.set_option(asio::ip::tcp::acceptor::reuse_address(true));
  tcp_acceptor_.bind(ep);
  tcp_acceptor_.listen();

  initiate_accept();
}

void server::run()
{
  // Launch worker threads to process I/O operations
  std::vector<std::unique_ptr<std::thread>> workers;
  workers.reserve(worker_count_);

  for (std::size_t i = 0; i < worker_count_; ++i) {
    workers.emplace_back(std::make_unique<std::thread>(
        [this]() { io_context_.run(); }));
  }

  // Join all worker threads
  for (auto& t : workers) {
    if (t && t->joinable()) {
      t->join();
    }
  }
}

void server::initiate_accept()
{
  active_connection_.reset(new connection(io_context_, req_handler_));
  tcp_acceptor_.async_accept(
      active_connection_->socket(),
      [this](const asio::error_code& ec) {
        handle_new_connection(ec);
      });
}

void server::handle_new_connection(const asio::error_code& err)
{
  if (!err) {
    active_connection_->start();
  }
  initiate_accept();
}

void server::handle_stop()
{
  io_context_.stop();
}

