// Helper function to set blend state components
inline void ConfigureBlendState(IDirect3DDevice9* device, 
                                D3DBLEND src, D3DBLEND dst, 
                                D3DBLEND srcA, D3DBLEND dstA) {
    device->SetRenderState(D3DRS_SRCBLEND, src);
    device->SetRenderState(D3DRS_DESTBLEND, dst);
    device->SetRenderState(D3DRS_SRCBLENDALPHA, srcA);
    device->SetRenderState(D3DRS_DESTBLENDALPHA, dstA);
}

// Helper function to configure alpha test settings
inline void SetupAlphaTest(IDirect3DDevice9* device, u8 reference, D3DCMPFUNC func) {
    device->SetRenderState(D3DRS_ALPHAREF, reference);
    device->SetRenderState(D3DRS_ALPHAFUNC, func);
}

// Helper function to configure depth test settings
inline void ConfigureDepthState(IDirect3DDevice9* device, bool enable, bool writeEnable, D3DCMPFUNC func) {
    device->SetRenderState(D3DRS_ZENABLE, enable ? D3DZB_TRUE : D3DZB_FALSE);
    device->SetRenderState(D3DRS_ZWRITEENABLE, writeEnable);
    device->SetRenderState(D3DRS_ZFUNC, func);
}

