                                D3DSTENCILOP failOp, 
                                D3DSTENCILOP zFailOp, 
                                D3DSTENCILOP passOp) {
    device->SetRenderState(D3DRS_STENCILFAIL, failOp);
    device->SetRenderState(D3DRS_STENCILZFAIL, zFailOp);
    device->SetRenderState(D3DRS_STENCILPASS, passOp);
}

