#include <iostream>

// Helper function to perform a query and return the result
int performQuery(int left, int right) {
    std::cout << "? " << left << " " << right << std::endl;
    int response;
    std::cin >> response;
    return response;
}

void processTestCase() {
    int arraySize;
    std::cin >> arraySize;

    // Step 1: Locate reference element (position of value n-1)
    int referencePos = performQuery(1, arraySize);

    int searchLeft, searchRight;
    bool referenceOnLeftSide;

    if (referencePos < arraySize && performQuery(referencePos, arraySize) == referencePos) {
        // The maximum element (n) lies in the right segment [referencePos+1, arraySize]
        searchLeft = referencePos + 1;
        searchRight = arraySize;
        referenceOnLeftSide = true;
    } else {
        // The maximum element (n) lies in the left segment [1, referencePos-1]
        searchLeft = 1;
        searchRight = referencePos - 1;
        referenceOnLeftSide = false;
    }

    // Step 2: Binary search to find exact position of maximum element (n)
    while (searchLeft < searchRight) {
        int mid = searchLeft + (searchRight - searchLeft) / 2;

        if (referenceOnLeftSide) {
            // Reference is on the left side of current search range
            // Check if max element is in [searchLeft, mid]
            if (performQuery(referencePos, mid) == referencePos) {
                searchRight = mid;  // Max element is in left half
            } else {
                searchLeft = mid + 1;  // Max element is in right half
            }
        } else {
            // Reference is on the right side of current search range
            // Check if max element is in [mid+1, searchRight]
            if (performQuery(mid + 1, referencePos) == referencePos) {
                searchLeft = mid + 1;  // Max element is in right half
            } else {
                searchRight = mid;  // Max element is in left half
            }
        }
    }

    std::cout << "! " << searchLeft << std::endl;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int testCaseCount;
    std::cin >> testCaseCount;

    for (int t = 0; t < testCaseCount; ++t) {
        processTestCase();
    }

    return 0;
}

