Y_UNIT_TEST_SUITE(MincoreSuite) {
    static const char* TestFileName_("./mapped_file");

    Y_UNIT_TEST(TestMemoryMappingAndCorePresence) {
        // Prepare test data: fill buffer with arbitrary content
        TVector<char> testData(2_MB);
        for (size_t i = 0; i < testData.size(); ++i) {
            testData[i] = static_cast<char>(i % 256);
        }

        // Create temporary file and write data
        TTempFile fileCleanup(TestFileName_);
        TFile outputFile(TestFileName_, CreateAlways | WrOnly);
        outputFile.Write(testData.data(), testData.size());
        outputFile.Close();

        // Map the file into memory
        TFileMap memoryMappedFile(TestFileName_, TMemoryMapCommon::oRdWr);
        memoryMappedFile.Map(0, memoryMappedFile.Length());

        // Verify mapping integrity
        UNIT_ASSERT_EQUAL(memoryMappedFile.MappedSize(), testData.size());
        UNIT_ASSERT_EQUAL(memoryMappedFile.Length(), static_cast<i64>(testData.size()));

