        size_t pageCount = memoryMappedFile.Length() / NSystemInfo::GetPageSize();
        TVector<unsigned char> pageFlags(pageCount);
        InCoreMemory(memoryMappedFile.Ptr(), memoryMappedFile.Length(), pageFlags.data(), pageFlags.size());

        // On Linux, verify all pages are present in core
