#include <iostream>
#include <vector>
#include <algorithm>
#include <random>
using namespace std;

// Heuristic-based greedy placement to avoid rectangles
// Constraints: n * m <= 100000, so we assume max(n, m) <= 100000 and min(n, m) <= 316

const int MAX_DIM = 350; // Safe upper bound for the smaller dimension

// Track which pairs of rows have been used together in any column
bool pair_used[MAX_DIM][MAX_DIM] = {false};

// Degree count: how many other rows each row has already been paired with
int row_degree[MAX_DIM] = {0};

struct Coordinate {
    int x, y;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int input_rows, input_cols;
    if (!(cin >> input_rows >> input_cols)) return 0;

    bool transposed = false;
    int rows = input_rows;
    int cols = input_cols;

    // Ensure rows <= cols for optimization (smaller dimension as rows)
    if (rows > cols) {
        swap(rows, cols);
        transposed = true;
    }

    // Initialize random generator with fixed seed for deterministic behavior
    mt19937 rng(12345);

    vector<int> row_order(rows);
    for (int i = 0; i < rows; ++i) {
        row_order[i] = i;
    }

    vector<Coordinate> placements;

    // Process each column independently
    for (int col_idx = 0; col_idx < cols; ++col_idx) {
        // Randomize row order using shuffle
        shuffle(row_order.begin(), row_order.end(), rng);

        // Sort by degree (ascending) to prioritize less-constrained rows
        stable_sort(row_order.begin(), row_order.end(), [&](int a, int b) {
            return row_degree[a] < row_degree[b];
        });

        vector<int> selected_rows;

        // Greedy selection: pick rows that don't conflict with already-selected ones in this column
        for (int r : row_order) {
            bool can_add = true;
            for (int prev_r : selected_rows) {
                if (pair_used[r][prev_r]) {
                    can_add = false;
                    break;
                }
            }
            if (can_add) {
                selected_rows.push_back(r);
            }
        }

        // Record placements and update constraints
        for (size_t i = 0; i < selected_rows.size(); ++i) {
            int r1 = selected_rows[i];
            placements.push_back({r1 + 1, col_idx + 1});

            for (size_t j = i + 1; j < selected_rows.size(); ++j) {
                int r2 = selected_rows[j];
                pair_used[r1][r2] = true;
                pair_used[r2][r1] = true;
                row_degree[r1]++;
                row_degree[r2]++;
            }
        }
    }

    cout << placements.size() << '\n';
    for (const auto& pt : placements) {
        if (transposed) {
            cout << pt.y << ' ' << pt.x << '\n'; // Swap back coordinates
        } else {
            cout << pt.x << ' ' << pt.y << '\n';
        }
    }

    return 0;
}

