namespace YimMenu::Stats
{
    // Helper to compute character index from stats
    int DetermineCharacterSlot()
    {
        int charSlot = 0;
        STATS::STAT_GET_INT("MPPLY_LAST_MP_CHAR"_J, &charSlot, -1);
        return charSlot;
    }

    // Process stat name: lowercase and replace 'mpx' prefix if needed
    std::string NormalizeStatIdentifier(std::string identifier)
    {
        // Convert entire string to lowercase
        for (auto& ch : identifier) {
            ch = static_cast<char>(::tolower(static_cast<unsigned char>(ch)));
        }

        // If starts with "mpx", replace third char with current char index digit
        if (identifier.size() >= 3 && identifier.substr(0, 3) == "mpx") {
            int slot = DetermineCharacterSlot();
            if (slot >= 0 && slot <= 9) {
                identifier[2] = static_cast<char>('0' + slot);
            }
        }

        return identifier;
    }

    // Wrapper to get hash of normalized stat name
    uint32_t GetStatHash(const std::string& rawName)
    {
        return Joaat(NormalizeStatIdentifier(rawName));
    }

    // Set integer stat
    void WriteIntegerStat(const std::string& name, int val)
    {
        STATS::STAT_SET_INT(GetStatHash(name), val, TRUE);
    }

    // Set boolean stat
    void WriteBooleanStat(const std::string& name, bool val)
    {
        STATS::STAT_SET_BOOL(GetStatHash(name), val, TRUE);
    }

    // Set float stat
    void WriteFloatingStat(const std::string& name, float val)
    {
        STATS::STAT_SET_FLOAT(GetStatHash(name), val, TRUE);
    }

    // Set date stat
    void WriteDateStat(const std::string& name, const Date* datePtr)
    {
        STATS::STAT_SET_DATE(GetStatHash(name), datePtr, sizeof(Date), TRUE);
    }

    // Set string stat
    void WriteStringStat(const std::string& name, const char* strVal)
    {
        STATS::STAT_SET_STRING(GetStatHash(name), strVal, TRUE);
    }

    // Read integer stat
    int ReadIntegerStat(const std::string& name)
    {
        int result = 0;
        STATS::STAT_GET_INT(GetStatHash(name), &result, -1);
        return result;
    }

    // Read boolean stat
    bool ReadBooleanStat(const std::string& name)
    {
        BOOL temp = FALSE;
        STATS::STAT_GET_BOOL(GetStatHash(name), &temp, -1);
        return static_cast<bool>(temp);
    }

    // Read float stat
    float ReadFloatingStat(const std::string& name)
    {
        float result = 0.0f;
        STATS::STAT_GET_FLOAT(GetStatHash(name), &result, -1);
        return result;
    }

    // Read date stat
    Date ReadDateStat(const std::string& name)
    {
        Date result{};
        STATS::STAT_GET_DATE(GetStatHash(name), &result, sizeof(Date), -1);
        return result;
    }

    // Read string stat (native is null-safe)
