void mix_voice(Renderer *track, float *output_buffer, Voice *voice, int sample_count)
{
    if (sample_count < 0)
        return;

    sample_t *src_ptr;
    int remaining = sample_count;

    if (voice->status & VOICE_STOPPING)
    {
        if (remaining > MAX_DIE_TIME)
            remaining = MAX_DIE_TIME;

        src_ptr = resample_voice(track, voice, &remaining);
        if (remaining <= 0)
            return;

        ramp_out(src_ptr, output_buffer, voice, remaining);
        voice->status = 0;
    }
    else
    {
        src_ptr = resample_voice(track, voice, &remaining);
        if (remaining <= 0)
            return;

        // Handle panning cases
        if (voice->right_mix == 0)          // Fully left
        {
            if (voice->eg1.env.bUpdating || voice->tremolo_phase_increment != 0)
                mix_single_left_signal(track->control_ratio, src_ptr, output_buffer, voice, remaining);
            else
                mix_single_left(src_ptr, output_buffer, voice, remaining);
        }
        else if (voice->left_mix == 0)      // Fully right
        {
            if (voice->eg1.env.bUpdating || voice->tremolo_phase_increment != 0)
                mix_single_right_signal(track->control_ratio, src_ptr, output_buffer, voice, remaining);
            else
                mix_single_right(src_ptr, output_buffer, voice, remaining);
        }
        else                                // Mixed stereo
        {
            if (voice->eg1.env.bUpdating || voice->tremolo_phase_increment)
                mix_mystery_signal(track->control_ratio, src_ptr, output_buffer, voice, remaining);
            else
                mix_mystery(track->control_ratio, src_ptr, output_buffer, voice, remaining);
        }

        voice->sample_offset += remaining;
    }
}

