// Custom exception for better error reporting
struct ParseError : public std::runtime_error {
    explicit ParseError(const std::string& msg) : std::runtime_error("ParseError: " + msg) {}
};

struct ConversionError : public std::runtime_error {
    explicit ConversionError(const std::string& msg) : std::runtime_error("ConversionError: " + msg) {}
};

struct TranslationError : public std::runtime_error {
    explicit TranslationError(const std::string& msg) : std::runtime_error("TranslationError: " + msg) {}
};

// Singleton registry initializer — now lazily initializes only once
class MlirEnvironment {
public:
    static MlirEnvironment& get() {
        static MlirEnvironment env;
        return env;
    }

    mlir::DialectRegistry& getRegistry() {
        ensureInitialized();
        return registry_;
    }

    void ensureInitialized() {
        if (!initialized_) {
            mlir::registerAllDialects(registry_);
            mlir::registerAllPasses();
            ::sdfg::codegen::register_default_dispatchers();
            ::sdfg::serializer::register_default_serializers();
            initialized_ = true;
        }
    }

private:
    MlirEnvironment() : initialized_(false) {}
    bool initialized_;
    mlir::DialectRegistry registry_;
};

// Wrapper class for MLIR module operations
class WrappedModule {
public:
    explicit WrappedModule(const std::string& source_code) {
        auto& env = MlirEnvironment::get();
        env.ensureInitialized();

        ctx_ = std::make_unique<mlir::MLIRContext>();
        ctx_->appendDialectRegistry(env.getRegistry());
        ctx_->loadAllAvailableDialects();

        // Validate input first
        if (source_code.empty()) {
            throw ParseError("Input MLIR source is empty");
        }

        // Parse the module
        auto module = mlir::parseSourceString<mlir::ModuleOp>(source_code, ctx_.get());
        if (!module) {
            throw ParseError("Failed to parse MLIR module from string");
        }
        module_ = std::move(module);
    }

    std::string toString() const {
        std::ostringstream oss;
        llvm::raw_os_ostream stream(oss);
        module_->print(stream);
        return oss.str();
    }

    void applyTransformations() {
        mlir::PassManager pm(ctx_.get());
        pm.addPass(mlir::createLinalgSpecializeGenericOpsPass());
        pm.addPass(mlir::createLinalgFoldUnitsPass());  // Additional transformation

        if (mlir::failed(pm.run(*module_))) {
            throw ConversionError("Module transformation failed during optimization");
        }
    }

    std::string exportSDFG() {
        std::ostringstream oss;
        llvm::raw_os_ostream stream(oss);

        auto op = module_->getOperation();
        if (!mlir::isa<mlir::ModuleOp>(op)) {
            throw TranslationError("Top-level operation is not a ModuleOp");
        }

        if (mlir::failed(mlir::sdfg::translateToSDFG(op, stream))) {
            throw TranslationError("SDFG translation failed");
        }

        return oss.str();
    }

    mlir::Operation* getRoot() { return module_->getOperation(); }

private:
    std::unique_ptr<mlir::MLIRContext> ctx_;
    mlir::OwningOpRef<mlir::ModuleOp> module_;
};

} // namespace

PYBIND11_MODULE(_sdfg_mlir, mod) {
    mod.doc() = "Python bindings for MLIR-to-SDFG conversion pipeline";

    py::class_<WrappedModule>(mod, "MLIRModule")
        .def(py::init<const std::string&>(), py::arg("source"), "Construct an MLIR module from textual IR")
        .def("to_string", &WrappedModule::toString, "Return the MLIR module as a formatted string")
        .def("apply_transforms", &WrappedModule::applyTransformations, "Apply Linalg-specific optimizations")
        .def("export_sdfg", &WrappedModule::exportSDFG, "Convert the module into serialized SDFG format")
        .def("root", &WrappedModule::getRoot, "Access the top-level operation");
}

