void ServerCommandDispatcher::logAdminCommand(
    std::shared_ptr<CommandSender> source,
    int                            logFlags,
    ChatPacket::EChatPacketMessage msgType,
    const std::wstring&            msgContent,
    int                            extraData,
    const std::wstring&            extraMsg
) {
    auto* playerList = MinecraftServer::getInstance()->getPlayers();

    // Notify all ops except the sender (if flagged)
    std::for_each(playerList->players.begin(), playerList->players.end(),
        [&](const std::shared_ptr<ServerPlayer>& playerPtr) {
            if (playerPtr != source && playerList->isOp(playerPtr)) {
                // TODO: Enhance chat packet to carry full metadata (sender name, args, etc.)
                // For now, message sending is commented out pending implementation
                // playerPtr->sendMessage(msgContent, msgType, extraData, extraMsg);
            }
        });

    // Deliver message to source unless explicitly suppressed
    if ((logFlags & LOGTYPE_DONT_SHOW_TO_SELF) == 0) {
        source->sendMessage(msgContent, msgType, extraData, extraMsg);
    }
}

