class OverlayDebugPanel : public rex::ui::ImGuiDialog {
 public:
  explicit OverlayDebugPanel(rex::ui::ImGuiDrawer* drawer)
      : rex::ui::ImGuiDialog(drawer) {}

 protected:
  void RenderFrame(ImGuiIO& io) override {
    ImVec2 pos = ImVec2(10.0f, 10.0f);
    ImVec2 size = ImVec2(220.0f, 60.0f);
    ImGui::SetNextWindowPos(pos, ImGuiCond_FirstUseEver);
    ImGui::SetNextWindowSize(size, ImGuiCond_FirstUseEver);
    ImGui::SetNextWindowBgAlpha(0.5f);

    if (ImGui::Begin("Debug##overlay", nullptr, ImGuiWindowFlags_NoCollapse)) {
      float fps = io.Framerate;
      float ms_per_frame = (fps > 0.0f) ? (1000.0f / fps) : 0.0f;
      ImGui::Text("%.1f FPS (%.2f ms)", fps, ms_per_frame);
    }
    ImGui::End();
  }
};

class Band3Application : public rex::ReXApp {
 public:
  using Base = rex::ReXApp;
  using Base::Base;

  std::unique_ptr<OverlayDebugPanel> debug_panel_;

  static std::unique_ptr<rex::ui::WindowedApp> BuildInstance(
      rex::ui::WindowedAppContext& context) {
    REXCVAR_SET(log_file, std::string("band3.log"));
    REXCVAR_SET(log_level, std::string("info"));

    return std::unique_ptr<Band3Application>(
        new Band3Application(context, "band3",
            {PPC_CODE_BASE, PPC_CODE_SIZE, PPC_IMAGE_BASE,
             PPC_IMAGE_SIZE, PPCFuncMappings}));
  }

  void AfterInitialization() override {
    band3::InitializeConfig();
    const auto& config = band3::GetConfig();
    rex::cvar::SetFlagByName("log_level", config.log_level);
  }

  void SetupUIComponents(rex::ui::ImGuiDrawer* drawer) override {
    const auto& settings = band3::GetConfig();

    if (settings.fullscreen) {
      window()->EnableFullscreen(true);
    }

    if (settings.show_debug && drawer != nullptr) {
      debug_panel_ = std::make_unique<OverlayDebugPanel>(drawer);
    } else {
      debug_panel_.reset();
    }
  }
};

REX_DEFINE_APP(band3, Band3Application::BuildInstance)

#include "ncl.h"
/*----------------------------------------------------------------------------------------------------------------------
|	Constructs a NxsException by copying the provided message and capturing parsing location details.
*/
NxsException::NxsException(
  const NxsString &message,	/* user-facing error description */
  file_pos position,		/* current position in the input file */
  long lineNum,				/* current line number in the file */
  long colNum)				/* current column number on the line */
	{
	pos		= position;
	line	= lineNum;
	col		= colNum;
	msg		= message;
	}
/*----------------------------------------------------------------------------------------------------------------------
|	Constructs a NxsException using an error message and extracting location data from a token object.
*/
NxsException::NxsException(
  const NxsString &description,	/* descriptive error text */
  const NxsToken &token)		/* token that triggered the exception (source of location info) */
	{
	msg		= description; 
	pos		= token.GetFilePosition();
	line	= token.GetFileLine();
	col		= token.GetFileColumn();
  	}

