#define DEBUG_TYPE "valuesymtab"

// Destructor: only active in debug builds; prints remaining entries and asserts emptiness
ValueSymbolTable::~ValueSymbolTable() {
#ifndef NDEBUG
  for (const auto &entry : vmap) {
    dbgs() << "Value still in symbol table! Type = '"
           << *entry.getValue()->getType() << "' Name = '" << entry.getKeyData()
           << "'\n";
  }
  assert(vmap.empty() && "Values remain in symbol table!");
#endif
}

// Helper: generate a unique suffix and insert into map; returns new ValueName*
ValueName *ValueSymbolTable::makeUniqueName(Value *val, SmallString<256> &buffer) {
  const size_t originalLen = buffer.size();

  // Keep trying until insertion succeeds
  bool inserted = false;
  do {
    buffer.resize(originalLen);
    raw_svector_ostream stream(buffer);

    if (auto *gv = dyn_cast<GlobalValue>(val)) {
      const Module *mod = gv->getParent();
      if (mod) {
        Triple target(mod->getTargetTriple());
        if (!target.isNVPTX()) {
          stream << ".";
        }
      } else {
        stream << ".";
      }
    } else {
      stream << ".";
    }

    stream << ++LastUnique;

    auto result = vmap.insert(std::make_pair(buffer.str(), val));
    inserted = result.second;
    if (inserted) {
      return &*(result.first);
    }
  } while (!inserted);

  // Should never reach here — loop always exits on success
  llvm_unreachable("Failed to generate unique name");
}

// Re-insert a named value; rename if necessary due to conflict
void ValueSymbolTable::reinsertValue(Value *val) {
  assert(val->hasName() && "Cannot insert value without a name into symbol table");

  // Attempt direct insertion first
  if (vmap.insert(val->getValueName())) {
    return;
  }

  // Conflict occurred — need to rename
  SmallString<256> candidateName(val->getName().begin(), val->getName().end());

  // Free old name to avoid leaks
  MallocAllocator allocator;
  val->getValueName()->Destroy(allocator);

  // Generate new unique name and assign
  ValueName *newName = makeUniqueName(val, candidateName);
  val->setValueName(newName);
}

// Remove a previously inserted ValueName
void ValueSymbolTable::removeValueName(ValueName *name) {
  vmap.remove(name);
}

// Create a new named entry; auto-renames on conflict
ValueName *ValueSymbolTable::createValueName(StringRef name, Value *val) {
  // Enforce maximum name length if configured
  if (MaxNameSize > -1 && name.size() > static_cast<unsigned>(MaxNameSize)) {
    name = name.substr(0, std::max(1u, static_cast<unsigned>(MaxNameSize)));
  }

  // Try inserting directly
  auto [iter, success] = vmap.insert(std::make_pair(name, val));
  if (success) {
    return &*iter;
  }

  // Conflict — fall back to uniquing
  SmallString<256> base(name.begin(), name.end());
  return makeUniqueName(val, base);
}

#if !defined(NDEBUG) || defined(LLVM_ENABLE_DUMP)
// Debug dump: iterate over all entries and print values
LLVM_DUMP_METHOD void ValueSymbolTable::dump() const {
  for (const auto &item : *this) {
    item.getValue()->dump();
  }
}
#endif

