#include <mplot/loadpng.h>
#include <mplot/Visual.h>
#include <mplot/VisualDataModel.h>
#include <mplot/GridVisual.h>
#include <mplot/HexGridVisual.h>

// Helper lambda to bind and configure GridVisual
auto makeGridVisual = [](mplot::Visual& v, sm::grid* g, const sm::vec<float,3>& pos,
                         std::vector<float>* data, const std::string& label) {
    auto gv = std::make_unique<mplot::GridVisual<float>>(g, pos);
    v.bindmodel(gv);
    gv->gridVisMode = mplot::GridVisMode::RectInterp;
    gv->setScalarData(data);
    gv->cm.setType(mplot::ColourMapType::GreyscaleInv);
    gv->zScale.null_scaling();
    gv->addLabel(label, {0, -0.2f, 0}, mplot::TextFeatures(0.1f));
    gv->finalize();
    v.addVisualModel(std::move(gv));
};

// Helper lambda to bind and configure HexGridVisual
auto makeHexGridVisual = [](mplot::Visual& v, sm::hexgrid* hg, const sm::vec<float,3>& pos,
                            std::vector<float>* data, const std::string& label) {
    auto hgv = std::make_unique<mplot::HexGridVisual<float>>(hg, pos);
    v.bindmodel(hgv);
    hgv->setScalarData(data);
    hgv->cm.setType(mplot::ColourMapType::GreyscaleInv);
    hgv->zScale.null_scaling();
    hgv->addLabel(label, {-hg->width()/2.0f, -0.2f - hg->height()/2.0f, 0}, mplot::TextFeatures(0.1f));
    hgv->finalize();
    v.addVisualModel(std::move(hgv));
};

int main() {
    // Initialize visualizer window
    mplot::Visual viewer(1400, 1300, "Demo of grid showing a resampled image");
    viewer.setSceneTrans(sm::vec<float,3>({-2.60691f, 1.39885f, -11.1f}));

    // Configuration constants
    constexpr unsigned int downscaleFactor = 2U;
    const sm::vec<float,2> baseSpacing = {0.02f, 0.02f};
    const sm::vec<float,2> coarseSpacing = baseSpacing * static_cast<float>(downscaleFactor);

    // Define grids: original and coarsened
    sm::grid originalGrid(256U, 64U, baseSpacing);
    std::cout << "Original grid extents: (xmin,xmax,ymin,ymax): " << originalGrid.extents() << '\n';

    sm::grid coarseGrid(256U / downscaleFactor, 64U / downscaleFactor, coarseSpacing);
    std::cout << "Coarse grid extents: (xmin,xmax,ymin,ymax): " << coarseGrid.extents() << '\n';

    // Load image
    const std::string imagePath = "../examples/bike256_64.png";
    std::vector<float> pixelData; // BLTR layout as per loadpng default
    sm::vec<unsigned int,2> imgDims = mplot::loadpng(imagePath, pixelData);
    std::cout << "Loaded image dimensions: " << imgDims << '\n';

    if (imgDims[0] != 256) {
        std::cerr << "Error: Unexpected image width.\n";
        return -1;
    }

    // Resample onto coarse grid
    const sm::vec<float,2> imgScale{1.0f, 1.0f};
    const sm::vec<float,2> imgOffset{0.0f, 0.0f};
    std::vector<float> resampledOnGrid = coarseGrid.resample_image(pixelData, imgDims[0], imgScale, imgOffset);

    // Prepare hexagonal grid for alternative sampling
    sm::vec<float,2> coarseDx = coarseGrid.get_dx();
    sm::hexgrid hexGrid(coarseDx[0], coarseGrid.width() * 2.0f, 0.0f);
    hexGrid.setRectangularBoundary(coarseGrid.width(), coarseGrid.height());

    // Scale image to match hexgrid's natural coordinate system
    const sm::vec<float,2> hexImgScale{static_cast<float>(coarseGrid.width()), static_cast<float>(coarseGrid.width())};
    std::vector<float> resampledOnHex = hexGrid.resampleImage(pixelData, imgDims[0], hexImgScale, imgOffset);

    // Visualize original image on fine grid
    makeGridVisual(viewer, &originalGrid, {0.0f, 0.0f, 0.0f}, &pixelData, "Original");

    // Visualize resampled image on coarse grid
    makeGridVisual(viewer, &coarseGrid, {0.0f, -2.0f, 0.0f}, &resampledOnGrid, "Resampled to coarser grid");

    // Visualize resampled image on hex grid
    makeHexGridVisual(viewer, &hexGrid,
                      {coarseGrid.width() / 2.0f, coarseGrid.height() / 2.0f - 4.0f, 0.0f},
                      &resampledOnHex, "Resampled to hexgrid");

    // Keep window open until user closes it
    viewer.keepOpen();
    return 0;
}

#include "llvm/IR/DiagnosticHandler.h"
#include "llvm/Support/CommandLine.h"
#include "llvm/Support/Regex.h"

using namespace llvm;

namespace {
// Structure to hold and manage a regular expression pattern for filtering pass names
struct PassRemarkFilter {
  std::shared_ptr<Regex> Pattern;

  void assign(const std::string &Input) {
    if (!Input.empty()) {
      Pattern = std::make_shared<Regex>(Input);
      std::string ErrorMsg;
      if (!Pattern->isValid(ErrorMsg)) {
        report_fatal_error(Twine("Invalid regex '") + Input +
                           "' used in -pass-remarks flag: " + ErrorMsg,
                           false);
      }
    } else {
      Pattern.reset();
    }
  }
};

// Global instances corresponding to each command-line option
static PassRemarkFilter PassedFilter;
static PassRemarkFilter MissedFilter;
static PassRemarkFilter AnalysisFilter;

// Command-line flags to control remark emission
static cl::opt<PassRemarkFilter, true, cl::parser<std::string>> 
    PassRemarksFlag(
        "pass-remarks", 
        cl::value_desc("pattern"),
        cl::desc("Activate optimization remarks from passes matching the provided regex"),
        cl::Hidden, 
        cl::location(PassedFilter), 
        cl::ValueRequired);

static cl::opt<PassRemarkFilter, true, cl::parser<std::string>> 
    PassRemarksMissedFlag(
        "pass-remarks-missed", 
        cl::value_desc("pattern"),
        cl::desc("Activate missed optimization remarks from matching passes"),
        cl::Hidden, 
        cl::location(MissedFilter), 
        cl::ValueRequired);

static cl::opt<PassRemarkFilter, true, cl::parser<std::string>> 
    PassRemarksAnalysisFlag(
        "pass-remarks-analysis", 
        cl::value_desc("pattern"),
        cl::desc("Activate analysis remarks from passes that match the pattern"),
        cl::Hidden, 
        cl::location(AnalysisFilter), 
        cl::ValueRequired);
}

// Check if analysis remarks are enabled for a given pass name
bool DiagnosticHandler::isAnalysisRemarkEnabled(StringRef PassName) const {
  return AnalysisFilter.Pattern && AnalysisFilter.Pattern->match(PassName);
}

// Check if missed optimization remarks are enabled for a given pass name
bool DiagnosticHandler::isMissedOptRemarkEnabled(StringRef PassName) const {
  return MissedFilter.Pattern && MissedFilter.Pattern->match(PassName);
}

// Check if passed optimization remarks are enabled for a given pass name
bool DiagnosticHandler::isPassedOptRemarkEnabled(StringRef PassName) const {
  return PassedFilter.Pattern && PassedFilter.Pattern->match(PassName);
}

// Determine whether any type of remark is currently enabled
bool DiagnosticHandler::isAnyRemarkEnabled() const {
  return PassedFilter.Pattern || MissedFilter.Pattern || AnalysisFilter.Pattern;
}

#include "Alias/TPA/PointerAnalysis/Engine/GlobalState.h"
#include "Alias/TPA/PointerAnalysis/Engine/TransferFunction.h"
#include "Alias/TPA/PointerAnalysis/Program/CFG/CFG.h"

namespace tpa {

void TransferFunction::processEntry(const ProgramPoint &entryPoint,
                                    EvalResult &outcomes) {
  assert(localState != nullptr);

  // Propagate top-level points-to information
  propagateTopLevelSuccessors(entryPoint, outcomes);

  // Propagate memory-level points-to information
  propagateMemLevelSuccessors(entryPoint, *localState, outcomes);

  // Ensure return targets are revisited upon function entry to maintain
  // fixpoint correctness when new return edges have been introduced.
  //
  // Important: This unconditional enqueue is by design. The SemiSparsePropagator
  // maintains a memoization cache (Memo) and only re-evaluates the exit node
  // if its store state has actually changed. Thus, even though the exit node
  // gets enqueued on every entry, redundant work is avoided through the
  // memoization mechanism—preserving both correctness and termination.

  const auto &controlFlowGraph = entryPoint.getCFGNode()->getCFG();
  if (!controlFlowGraph.isNonReturning()) {
    outcomes.addTopLevelProgramPoint(
        ProgramPoint(entryPoint.getContext(), controlFlowGraph.getExitNode()));
  }
}

} // namespace tpa

