#include <hip/hip_runtime.h>
#include <cstddef>
#include <cstdlib>
#include <iostream>

int main() {
    // Initialize the HIP runtime environment
    hipError_t init_result = hipInit(0);
    if (init_result != hipSuccess) {
        std::cerr << "HIP initialization failed." << std::endl;
        return EXIT_FAILURE;
    }

    // Retrieve the default asynchronous stream for the current thread
    hipStream_t default_stream = hipStreamPerThread;

    // Allocate device memory
    void* device_memory = nullptr;
    const std::size_t buffer_size = 1024;

    hipError_t alloc_result = hipMalloc(&device_memory, buffer_size);
    if (alloc_result != hipSuccess) {
        std::cerr << "Device memory allocation failed." << std::endl;
        return EXIT_FAILURE;
    }

    // Asynchronously initialize the allocated memory to zero
    hipError_t memset_result = hipMemsetAsync(device_memory, 0, buffer_size, default_stream);
    if (memset_result != hipSuccess) {
        std::cerr << "Memory initialization operation failed." << std::endl;
        hipFree(device_memory);  // Clean up before exiting
        return EXIT_FAILURE;
    }

    // Ensure all operations in the stream are completed
    hipError_t sync_result = hipStreamSynchronize(default_stream);
    if (sync_result != hipSuccess) {
        std::cerr << "Stream synchronization failed." << std::endl;
        hipFree(device_memory);  // Clean up before exiting
        return EXIT_FAILURE;
    }

    // Release the device memory
    hipError_t free_result = hipFree(device_memory);
    if (free_result != hipSuccess) {
        std::cerr << "Memory deallocation failed." << std::endl;
        return EXIT_FAILURE;
    }

    std::cout << "All HIP operations completed successfully using per-thread stream." << std::endl;
    return EXIT_SUCCESS;
}

