#include "Core/Async.hpp"
#include <CTRPluginFramework.hpp>
#include <mutex>
#include "Core/Debug.hpp"
#include "Core/Utils/Utils.hpp"
#include "CoreGlobals.hpp"
#include "Helpers/Timer.hpp"
#include "Helpers/Allocation.hpp"

namespace CTRPF = CTRPluginFramework;
using namespace Core;

// Timer used to detect async task timeouts
static Core::Timer asyncExecutionTimeout(CTRPF::Milliseconds(5000));

// Resets the timeout timer when called externally (e.g., from game loop)
void Core::AsyncRestartClock() {
    asyncExecutionTimeout.Restart();
}

// Hook function invoked periodically during coroutine execution
void Core::_AsyncTimeoutCheck(lua_State *L, lua_Debug *ar) {
    if (asyncExecutionTimeout.Expired()) {
        luaL_error(L, "Async coroutine exceeded execution time (5000 ms)");
    }
}

// ============================================================================
// Module: Async
// Provides asynchronous task scheduling with timeout protection
// ============================================================================

/*
- Creates an AsyncTask object that wraps a given function.
  The function is stored as a reference and executed later via .run()
## func: function
## return: AsyncTask
### Async.create
*/
static int l_Async_Create(lua_State *L) {
    luaL_checktype(L, 1, LUA_TFUNCTION);

    // Create new table representing the task
    lua_newtable(L);

    // Store the function under key "_taskF"
    lua_pushvalue(L, 1);
    lua_setfield(L, -2, "_taskF");

    // Assign metatable "AsyncTask"
    luaC_setmetatable(L, "AsyncTask");
    return 1;
}

/*
- Schedules a coroutine to run asynchronously alongside the main game thread.
  Includes timeout monitoring via hook.
## func: function
### Async.run
*/
static int l_Async_Run(lua_State *L) {
    luaL_checktype(L, 1, LUA_TFUNCTION);

    // Create new coroutine
    lua_State *coro = lua_newthread(L);

    // Move function into coroutine stack
    lua_pushvalue(L, 1);
    lua_xmove(L, coro, 1);

    // Set up timeout hook: check every 100 instructions
    lua_sethook(coro, Core::_AsyncTimeoutCheck, LUA_MASKCOUNT, 100);

    // Add task to scheduler
    Scheduler::getInstance().AddTask(L, -1);

    // Clean up coroutine reference from stack
    lua_pop(L, 1);
    return 0;
}

/*
- Yields current async task until specified time has passed.
  If no argument given, waits one frame (0 seconds).
## seconds: number?
## return: boolean
### Async.wait
*/
static int l_Async_Wait(lua_State *L) {
    // Verify we're inside a valid async task context
    if (!Scheduler::getInstance().IsValidTask(L)) {
        return luaL_error(L, "use an async task to execute this function");
    }

    const int argCount = lua_gettop(L);
    if (argCount > 0) {
        if (!lua_isnumber(L, 1)) {
            return luaL_error(L, "bad #1 argument type (expected number)");
        }

        double seconds = lua_tonumber(L, 1);
        if (seconds < 0.0) {
            return luaL_error(L, "bad time value");
        }

        return Scheduler::getInstance().CreateWait(
            L,
            UniqueAlloc::alloc<AsyncWaitHandler>(static_cast<float>(seconds))
        );
    } else {
        // Default wait: single tick/frame
        return Scheduler::getInstance().CreateWait(
            L,
            UniqueAlloc::alloc<AsyncWaitHandler>(0.0f)
        );
    }
}

// ============================================================================
// Internal: Register metatable for AsyncTask objects
// ============================================================================
static inline void _RegisterAsyncTaskMetatable(lua_State *L) {
    luaL_newmetatable(L, "AsyncTask");

    // __index table (empty for now)
    lua_newtable(L);
    lua_setfield(L, -2, "__index");

    // Prevent modification via __newindex
    lua_pushcfunction(L, luaC_invalid_newindex);
    lua_setfield(L, -2, "__newindex");

    // Set name for debugging
    lua_pushstring(L, "AsyncTask");
    lua_setfield(L, -2, "__name");

    lua_pop(L, 1);
}

// ============================================================================
// Public API: Initialize and expose Async module
// ============================================================================
bool Core::RegisterAsyncModule(lua_State *L) {
    _RegisterAsyncTaskMetatable(L);

    // Create global 'Async' table
    lua_newtable(L);

    // Bind methods
    lua_pushcfunction(L, l_Async_Create);
    lua_setfield(L, -2, "create");

    lua_pushcfunction(L, l_Async_Run);
    lua_setfield(L, -2, "run");

    lua_pushcfunction(L, l_Async_Wait);
    lua_setfield(L, -2, "wait");

    // Export to global scope
    lua_setglobal(L, "Async");

    return true;
}

