// Flip the color: Red becomes Blue and vice versa
EnumSwitchQualified::Outer::color
EnumSwitchQualified::Outer::flip(const EnumSwitchQualified::Outer::color c) {
  return [&]() -> color {
    switch (c) {
      case color::Red:
        return color::Blue;
      case color::Blue:
        return color::Red;
      default:
        return color::Red; // fallback for safety
    }
  }();
}

// Convert color to numeric code: Red=1, Blue=2
unsigned int
EnumSwitchQualified::Outer::code(const EnumSwitchQualified::Outer::color c) {
  return [&]() -> unsigned int {
    switch (c) {
      case color::Red:
        return 1u;
      case color::Blue:
        return 2u;
      default:
        return 0u; // fallback for safety
    }
  }();
}

