    // Handle entity impact if present
    if (impact->targetEntity != nullptr)
    {
        DamageSource *source = DamageSource::thrown(shared_from_this(), owner);
        impact->targetEntity->takeDamage(source, 0);
        delete source;
    }

    // Emit visual particles around impact point
    int particleCount = 32;
    for (int idx = 0; idx < particleCount; ++idx)
    {
        level->spawnParticle(eParticleType_ender,
                             x,
                             y + random->nextDouble() * 2.0,
                             z,
