// Modified active object pattern implementation
class bank_account
{
    int current_balance_ = 0;
    mutable thread_pool worker_pool_{1};
public:
    void credit(int value)
    {
        post(worker_pool_, [this, value]
            {
                current_balance_ += value;
            });
    }

    void debit(int value)
    {
        post(worker_pool_, [this, value]
            {
                if (current_balance_ >= value)
                    current_balance_ -= value;
            });
    }

    void show_status() const
    {
        post(worker_pool_, [this]
            {
                std::cout << "account balance = " << current_balance_ << "\n";
            });
    }

    ~bank_account()
    {
        worker_pool_.join();
    }
};

int main()
{
    bank_account account;
    account.credit(20);
    account.debit(10);
    account.show_status();
}

