// Perform a swap operation via interactive communication
void perform_swap(int x, int y) {
    if (x == y) return;
    std::cout << "2 " << x << " " << y << std::endl;
    int temp;
    std::cin >> temp;
}

// Perform a query operation to check adjacency in the sequence
int perform_query(int left, int right) {
    std::cout << "1 " << left << " " << right << std::endl;
    int result;
    std::cin >> result;
    return result;
}

// Output the final reconstructed permutation
void output_result(const std::vector<int>& result_permutation) {
    std::cout << "3";
    for (size_t idx = 1; idx < result_permutation.size(); ++idx) {
        std::cout << " " << result_permutation[idx];
    }
    std::cout << std::endl;
}

int main() {
    // Optimize I/O operations
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n, len1, len2;
    std::cin >> n >> len1 >> len2;

    // Track where each original element currently resides
    std::vector<int> current_position(n + 1);
    std::iota(current_position.begin(), current_position.end(), 0);

    // Build the chain incrementally: at step i, positions 1..i contain a contiguous value chain
    for (int step = 1; step < n; ++step) {
        // Try each remaining position as candidate for extending the chain
        for (int candidate = step + 1; candidate <= n; ++candidate) {
            // Move candidate to position step+1 for testing
            perform_swap(step + 1, candidate);
            std::swap(current_position[step + 1], current_position[candidate]);

            // Check if adjacent values exist between positions step and step+1
            // Query returns 3 if values are consecutive, 2 otherwise
            if (perform_query(step, step + 1) == 3) {
                // Found a valid neighbor - keep it in place and continue
                break;
            }

            // Not a valid neighbor - restore previous state
            perform_swap(step + 1, candidate);
            std::swap(current_position[step + 1], current_position[candidate]);
        }
    }

    // Now reconstruct the actual values based on final positions
    std::vector<int> final_values(n + 1);
    for (int pos = 1; pos <= n; ++pos) {
        final_values[current_position[pos]] = pos;
    }

    // Output the solution (either ascending or descending sequence)
    output_result(final_values);

    return 0;
}

#include <format>
