int main()
{
    // Initialize the visualization window with title and dimensions
    mplot::Visual scene(1024, 768, "Generated using mplot::GraphVisual");

    // Instantiate a GraphVisual for double-precision data at origin
    auto graph = std::make_unique<mplot::GraphVisual<double>>(sm::vec<float>{0.0f, 0.0f, 0.0f});

    // Link the graph to the scene (required setup step)
    scene.bindmodel(graph);

    // Prepare x-axis data: 11 points from 0 to 10 inclusive
    sm::vvec<double> abscissae;
    abscissae.linspace(0, 10, 11);

    // Define y-values manually (arbitrary sample data)
    sm::vvec<double> ordinates = {5, 8, 2, 9, 1, 2, 4, 5, 8, 3, 1};

    // Configure primary dataset style: crimson line
    mplot::DatasetStyle primaryStyle(mplot::stylepolicy::lines);
    primaryStyle.linecolour = mplot::colour::crimson;

    // Set fixed vertical range for clarity
    graph->setlimits_y(0, 10);

    // Feed data into the graph
    graph->setdata(abscissae, ordinates, primaryStyle);

    // Secondary style for horizontal reference line at y=7
    mplot::DatasetStyle refLineStyle(mplot::stylepolicy::lines);
    refLineStyle.linecolour = mplot::colour::grey68;
    refLineStyle.linewidth = primaryStyle.linewidth * 0.6f;

    // Compute intersection points between curve and y=7, draw vertical markers
    sm::vvec<double> crossingPoints = graph->add_y_crossing_lines(abscissae, ordinates, 7, primaryStyle, refLineStyle);

    // Format annotation string listing crossing x-values
    std::ostringstream oss;
    size_t count = crossingPoints.size();
    if (count > 0) {
        for (size_t idx = 0; idx < count; ++idx) {
            if (idx == 0 || idx == count - 1) {
                oss << (idx == count - 1 ? "" : "");
            } else {
                oss << ", ";
            }
            oss << (idx == count - 1 ? " and " : "") << std::format("{:.2f}", crossingPoints[idx]);
        }
    } else {
        oss << "[no intersections]";
    }

    // Place descriptive label in lower-left corner
    graph->addLabel(
        std::format("y=7 intersects at x = {}", oss.str()),
        {0.05f, 0.05f, 0.0f},
        mplot::TextFeatures{0.03f}
    );

    // Finalize geometry generation before rendering
    graph->finalize();

    // Transfer ownership of graph to scene
    scene.addVisualModel(std::move(graph));

    // Launch interactive viewer loop
    scene.keepOpen();

    // Memory cleanup handled automatically via RAII
    return 0;
}

