// Custom comparator function to sort pairs by their second value in ascending order
bool sortBySecond(const pair<int, int>& x, const pair<int, int>& y) {
    return x.second < y.second;
}

int main() {
    // Initialize vector with integer pairs
    vector<pair<int, int>> data = {{5, 2}, {8, 1}, {4, 3}};

    // Sort by first element (default behavior of pair comparison)
    sort(data.begin(), data.end());

    cout << "Sorted by first component: ";
    for (auto it = data.begin(); it != data.end(); ++it) {
        cout << "(" << it->first << ", " << it->second << ") ";
    }
    cout << endl;

    // Sort by second element using custom comparator
    sort(data.begin(), data.end(), sortBySecond);

    cout << "Sorted by second component: ";
    for (auto it = data.begin(); it != data.end(); ++it) {
        cout << "(" << it->first << ", " << it->second << ") ";
    }
    cout << endl;

    return 0;
}

#include "BufferedOutputStream.h"
#include "util/console/ArrayWithLength.h"
#include "win/extraX64.h"

// Constructs a buffered output stream wrapping the given output stream with a custom buffer size
BufferedOutputStream::BufferedOutputStream(OutputStream* out, int size) {
    underlyingStream = out;
    buffer           = byteArray(size);
    bufferPosition   = 0;
}

// Destructor: releases allocated memory for the internal buffer
BufferedOutputStream::~BufferedOutputStream() { 
    delete buffer.data; 
}

// Ensures all buffered data is written to the underlying stream and resets the buffer position
void BufferedOutputStream::flush() {
    underlyingStream->write(buffer, 0, bufferPosition);
    bufferPosition = 0;
}

// Closes the stream by first flushing remaining data, then closing the underlying stream
void BufferedOutputStream::close() {
    flush();
    underlyingStream->close();
}

// Writes a specified number of bytes from an array to the buffered stream
// If the requested write exceeds or equals the buffer capacity, bypass buffering entirely
void BufferedOutputStream::write(
    byteArray    data,
    unsigned int startIndex,
    unsigned int count
) {
    // Direct write if data size is larger than or equal to buffer capacity
    if (count >= buffer.length) {
        flush();
        underlyingStream->write(data, startIndex, count);
    } else {
        // Otherwise, copy byte-by-byte using the single-byte write method
        for (unsigned int i = 0; i < count; ++i) {
            write(data[startIndex + i]);
        }
    }
}

// Convenience overload: writes entire byte array using default offset 0 and full length
void BufferedOutputStream::write(byteArray data) { 
    write(data, 0, data.length); 
}

// Writes a single byte to the buffer; flushes when buffer becomes full
void BufferedOutputStream::write(unsigned int value) {
    buffer[bufferPosition++] = static_cast<byte>(value);

    // Auto-flush when buffer is completely filled
    if (bufferPosition == buffer.length) {
        flush();
    }
}

