#include <iostream>
#include <string>

// Global variables for the state machine
int passagesPerChamber;
int passagesTakenFromCurrent = 0;

void processJourney() {
    // Read number of passages per chamber
    std::cin >> passagesPerChamber;

    std::string currentStatus;
    while (std::cin >> currentStatus && currentStatus != "treasure") {
        if (currentStatus == "center") {
            // First visit to a new chamber
            // Initialize exploration: take first passage, mark as 'left'
            passagesTakenFromCurrent = 1;
            std::cout << "0 left 0" << std::endl;
        } 
        else if (currentStatus == "left") {
            // Currently exploring this chamber
            if (passagesTakenFromCurrent < passagesPerChamber - 1) {
                // Not yet at last passage
                std::cout << "1 left 1" << std::endl;
            } 
            else {
                // This is the final passage in this chamber
                std::cout << "1 right 1" << std::endl;
            }
            passagesTakenFromCurrent++;
        } 
        else if (currentStatus == "right") {
            // Chamber already fully explored
            std::cout << "0 right 0" << std::endl;
        }
    }
}

int main() {
    // Optimize I/O performance
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    processJourney();
    return 0;
}

