#include <asio.hpp>
#include <boost/bind.hpp>
#include <istream>
#include <iostream>
#include <ostream>
#include "icmp_header.hpp"
#include "ipv4_header.hpp"

using asio::ip::icmp;
using asio::steady_timer;

namespace chrono = asio::chrono;

class icmp_pinger {
public:
    icmp_pinger(asio::io_context& ctx, const std::string& target_host)
        : resolver_(ctx),
          sock_(ctx, icmp::v4()),
          timer_(ctx),
          seq_num_(0),
          reply_count_(0)
    {
        auto endpoints = resolver_.resolve(icmp::v4(), target_host, "");
        dest_endpoint_ = *endpoints.begin();

        initiate_request();
        prepare_for_response();
    }

private:
    void initiate_request() {
        const std::string payload = "\"Hello!\" from Asio ping.";

        icmp_header req;
        req.type(icmp_header::echo_request);
        req.code(0);
        req.identifier(get_unique_id());
        req.sequence_number(++seq_num_);
        compute_checksum(req, payload.begin(), payload.end());

        asio::streambuf buffer;
        std::ostream os(&buffer);
        os << req << payload;

        send_time_ = steady_timer::clock_type::now();
        sock_.send_to(buffer.data(), dest_endpoint_);

        // Set timeout for this request
        reply_count_ = 0;
        timer_.expires_at(send_time_ + chrono::seconds(5));
        timer_.async_wait(boost::bind(&icmp_pinger::on_timeout, this));
    }

    void on_timeout() {
        if (reply_count_ == 0) {
            std::cout << "Request timed out" << std::endl;
        }

        // Enforce minimum delay between consecutive pings
        timer_.expires_at(send_time_ + chrono::seconds(1));
        timer_.async_wait(boost::bind(&icmp_pinger::initiate_request, this));
    }

    void prepare_for_response() {
        reply_buffer_.consume(reply_buffer_.size());
        sock_.async_receive(reply_buffer_.prepare(65536),
            boost::bind(&icmp_pinger::process_incoming_packet, this, _2));
    }

    void process_incoming_packet(std::size_t bytes_received) {
        reply_buffer_.commit(bytes_received);

        std::istream is(&reply_buffer_);
        ipv4_header ip_hdr;
        icmp_header icmp_hdr;
        is >> ip_hdr >> icmp_hdr;

        if (!is) return;

        // Validate: must be echo reply, match our ID and expected sequence
        if (icmp_hdr.type() == icmp_header::echo_reply &&
            icmp_hdr.identifier() == get_unique_id() &&
            icmp_hdr.sequence_number() == seq_num_) {

            if (reply_count_++ == 0) {
                timer_.cancel(); // Cancel pending timeout
            }

            auto now = chrono::steady_clock::now();
            auto latency = now - send_time_;
            std::size_t data_len = bytes_received - ip_hdr.header_length();

            std::cout << data_len << " bytes from " << ip_hdr.source_address()
                      << ": icmp_seq=" << icmp_hdr.sequence_number()
                      << ", ttl=" << static_cast<int>(ip_hdr.time_to_live())
                      << ", time="
                      << chrono::duration_cast<chrono::milliseconds>(latency).count()
                      << " ms" << std::endl;
        }

        prepare_for_response();
    }

    static unsigned short get_unique_id() {
#if defined(_WIN32) || defined(_WIN64)
        return static_cast<unsigned short>(GetCurrentProcessId());
#else
        return static_cast<unsigned short>(getpid());
#endif
    }

    icmp::resolver resolver_;
    icmp::endpoint dest_endpoint_;
    icmp::socket sock_;
    steady_timer timer_;
    unsigned short seq_num_;
    chrono::steady_clock::time_point send_time_;
    asio::streambuf reply_buffer_;
    std::size_t reply_count_;
};

int main(int argc, char* argv[]) {
    try {
        if (argc != 2) {
            std::cerr << "Usage: ping <hostname_or_ip>" << std::endl;
#if !defined(_WIN32) && !defined(_WIN64)
            std::cerr << "(This program may require elevated privileges.)" << std::endl;
#endif
            return EXIT_FAILURE;
        }

        asio::io_context context;
        icmp_pinger pinger(context, argv[1]);
        context.run();
    }
    catch (const std::exception& ex) {
        std::cerr << "Error: " << ex.what() << std::endl;
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

#include <iostream>
#include <vector>
#include <string>

int main() {
    // Optimize I/O for competitive programming scenarios
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    // Grid size parameters
    const int rows = 20;
    const int cols = 20;

    // Output grid dimensions
    std::cout << rows << " " << cols << '\n';

    // Initialize grid with walls ('0')
    std::vector<std::string> maze(rows, std::string(cols, '0'));

    // Set cross center point (slightly offset from exact center)
    const int cross_row = 10;
    const int cross_col = 10;

    // Draw vertical line of the cross
    for (int r = 0; r < rows; ++r) {
        maze[r][cross_col] = '1';
    }

    // Draw horizontal line of the cross
    for (int c = 0; c < cols; ++c) {
        maze[cross_row][c] = '1';
    }

    // Display the resulting map
    for (int r = 0; r < rows; ++r) {
        std::cout << maze[r] << '\n';
    }

    return 0;
}

