// Signal handler to gracefully stop client and server on Ctrl+C
void signal_handler(int signum) {
    (void)signum; // Suppress unused parameter warning
    StopClient();
    StopServer();
}

int main() {
    // Set up signal handler for SIGINT (Ctrl+C)
    std::signal(SIGINT, signal_handler);

    // Launch server and client in separate threads
    {
        std::thread worker_server(RunServer);
        std::thread worker_client(RunClient);

        // Wait for client thread to complete
        worker_client.join();
        // Wait for server thread to complete
        worker_server.join();
    }

    return 0;
}

