#include "pugixml.hpp"
#include <cstring>
#include <iostream>

// Check if the node has a 'Timeout' attribute less than 20
bool is_short_timeout(pugi::xml_node node) {
    return node.attribute("Timeout").as_int() < 20;
}

// Predicate structure to check for 'AllowRemote' attribute or node property
struct remote_access_checker {
    // Overload for attributes: checks if attribute name matches "AllowRemote"
    bool operator()(pugi::xml_attribute attr) const {
        return std::strcmp(attr.name(), "AllowRemote") == 0;
    }

    // Overload for nodes: checks if node has AllowRemote set to true
    bool operator()(pugi::xml_node node) const {
        return node.attribute("AllowRemote").as_bool();
    }
};

int main() {
    pugi::xml_document doc;
    if (!doc.load_file("xgconsole.xml")) return -1;

    pugi::xml_node tools = doc.child("Profile").child("Tools");

    // Use find_child with predicate — searches only direct children
    std::cout << tools.find_child(remote_access_checker()).attribute("Filename").value() << std::endl;

    // Use find_node with predicate — searches entire subtree in depth-first order
    std::cout << doc.find_node(remote_access_checker()).attribute("Filename").value() << std::endl;

    // Use find_attribute with predicate on the last child of tools
    std::cout << tools.last_child().find_attribute(remote_access_checker()).value() << std::endl;

    // Demonstrate using function pointer instead of function object
    std::cout << tools.find_child(is_short_timeout).attribute("Filename").value() << std::endl;

    return 0;
}

