// Custom module implementation for DataprepCore functionality
class FDataprepCoreModule : public IModuleInterface
{
public:
	virtual void StartupModule() override
	{
		// Initialize and register the mount point for the Dataprep core library's root package directory
		const FString RootPackagePath = DataprepCorePrivateUtils::GetRootPackagePath() + TEXT("/");
		const FString TempDirPath = DataprepCorePrivateUtils::GetRootTemporaryDir();
		FPackageName::RegisterMountPoint(RootPackagePath, TempDirPath);
	}

	virtual void ShutdownModule() override
	{
		// Clean up by unregistering the previously registered mount point
		const FString RootPackagePath = DataprepCorePrivateUtils::GetRootPackagePath() + TEXT("/");
		const FString TempDirPath = DataprepCorePrivateUtils::GetRootTemporaryDir();
		FPackageName::UnRegisterMountPoint(RootPackagePath, TempDirPath);
	}
};

