#include <unitree/robot/go2/video/video_client.hpp>
#include <iostream>
#include <fstream>
#include <ctime>

int main() {
    // Initialize the communication channel
    unitree::robot::ChannelFactory::Instance()->Init(0);

    // Create and configure video client
    unitree::robot::go2::VideoClient video_client;
    video_client.SetTimeout(1.0f);
    video_client.Init();

    std::vector<uint8_t> frame_data;
    int status_code;

    // Continuously capture and save images
    while (true) {
        status_code = video_client.GetImageSample(frame_data);

        if (status_code == 0) {
            // Generate timestamp-based filename
            time_t current_time;
            struct tm *time_struct;
            char time_buffer[80];

            time(&current_time);
            time_struct = localtime(&current_time);
            strftime(time_buffer, sizeof(time_buffer), "%Y%m%d%H%M%S.jpg", time_struct);

            std::string filename(time_buffer);
            std::ofstream output_file(filename, std::ios::binary);

            if (output_file.is_open()) {
                output_file.write(reinterpret_cast<const char*>(frame_data.data()), 
                                  frame_data.size());
                output_file.close();
                std::cout << "Image captured and saved as: " << filename << std::endl;
            } else {
                std::cerr << "Warning: Could not create file " << filename << std::endl;
            }
        }

        // Wait for 3 seconds before next capture
        sleep(3);
    }

    return 0;
}

#include <engLib/eng.h>
namespace engine::task::actionTransform {
//-----------------------------------------------------------------
/// @details
///		Initialization logic for the transform task
//-----------------------------------------------------------------
Error Task::beginTask() noexcept {
    // First, establish connection to the target endpoint
    if (!(m_targetEndpoint = IServiceEndpoint::getTargetEndpoint(
              {.jobConfig = jobConfig(),
               .taskConfig = taskConfig(),
               .serviceConfig = taskConfig()["target"],
               .openMode = OPEN_MODE::TRANSFORM})))
        return m_targetEndpoint.ccode();

    // Determine appropriate mode for opening the source endpoint
    OPEN_MODE srcOpenMode{};
    const auto& tc = m_targetEndpoint->config.taskConfig;

    bool needsPolicies  = tc.lookup<bool>("wantsPolicies");
    bool needsContext   = tc.lookup<bool>("wantsContext");
    bool needsText      = tc.lookup<bool>("wantsText");
    bool needsData      = tc.lookup<bool>("wantsData");

    if (needsPolicies || needsContext || needsText) {
        srcOpenMode = needsData ? OPEN_MODE::SOURCE_INDEX : OPEN_MODE::INDEX;
    } else {
        srcOpenMode = OPEN_MODE::SOURCE;
    }

    // Now open the source endpoint with determined mode
    if (!(m_sourceEndpoint = IServiceEndpoint::getSourceEndpoint(
              {.jobConfig = jobConfig(),
               .taskConfig = taskConfig(),
               .serviceConfig = taskConfig()["source"],
               .openMode = srcOpenMode})))
        return m_sourceEndpoint.ccode();

    // Proceed with base class initialization
    return Parent::beginTask();
}
//-----------------------------------------------------------------
///	@details
///		Handles incoming JSON-formatted line and creates an entry
/// @param[in] line
///		A single line of input in JSON format
/// @param[in] parent
///		URL of the current parent context
//-----------------------------------------------------------------
ErrorOr<Entry> Task::processLine(TextView line, const Url &parent) noexcept {
    // Use base processing for lines starting with 'A'
    auto entry = Parent::processLine("A"_tv, line, parent);
    if (entry.hasCcode()) return entry;

    // Set required flags for transformation pipeline
    auto& e = entry.value();
    e.flags(e.flags() | Entry::FLAGS::INDEX |
                       Entry::FLAGS::CLASSIFY |
                       Entry::FLAGS::OCR);

    return entry;
}
//-----------------------------------------------------------------
/// @details
///		Performs final transformation on a processed entry
/// @param[in] entry
///		The entry to finalize and route appropriately
//-----------------------------------------------------------------
Error Task::processItem(Entry &entry) noexcept {
    // Let base class handle core processing
    if (auto ccode = Parent::processItem(entry)) return ccode;

    // Post-processing: remove classifications to reduce output size
    // since transformed entries are not further processed downstream
    entry.classifications.clear();

    // Handle result based on outcome
    if (entry.objectFailed()) {
        if (entry.completionCode() == Ec::Skipped) {
            // Skipped items go directly to completed without writing output
            MONITOR(addCompleted, 1, entry.size());
        } else {
            // Failed items get logged and recorded
            MONITOR(addFailed, 1, entry.size());
            if (auto ccode = Parent::writeError(entry, entry.completionCode()))
                return ccode;
        }
    } else {
        // Successful transformation
        MONITOR(addCompleted, 1, entry.size());
        if (auto ccode = Parent::writeResult('A', entry)) return ccode;
    }

    return {};
}
}  // namespace engine::task::actionTransform

#include "core/commands/Command.hpp"
#include "game/gta/Pools.hpp"
#include "game/gta/Object.hpp"

namespace YimMenu::Features
{
    class RemoveAllObjects : public Command
    {
        using Command::Command;
        virtual void Execute() override
        {
            for (auto&& item : Pools::GetObjects())
            {
                if (item && !item.IsMissionCritical())
                    item.Delete();
            }
        }
    };

    class RemoveAllCameras : public Command
    {
        using Command::Command;
        virtual void Execute() override
        {
            for (auto&& cam : Pools::GetObjects())
            {
                if (cam && cam.As<Object>().IsCamera() && !cam.IsMissionCritical())
                    cam.Delete();
            }
        }
    };

    class RemoveAllPeds : public Command
    {
        using Command::Command;
        virtual void Execute() override
        {
            for (auto&& entity : Pools::GetPeds())
            {
                if (!entity.IsPlayer() && !entity.IsMissionCritical())
                    entity.Delete();
            }
        }
    };

    class RemoveAllVehicles : public Command
    {
        using Command::Command;
        virtual void Execute() override
        {
            for (auto&& vehicle : Pools::GetVehicles())
            {
                if (!vehicle.IsMissionCritical())
                    vehicle.Delete();
            }
        }
    };

    static RemoveAllCameras _RemoveAllCameras("delcams", "Remove All Cameras", "Removes all cameras from the game");
    static RemoveAllObjects _RemoveAllObjects{"delobjs", "Remove All Objects", "Removes all non-mission-critical objects in the game world"};
    static RemoveAllPeds _RemoveAllPeds{"delpeds", "Remove All Peds", "Removes all non-player, non-mission-critical peds"};
    static RemoveAllVehicles _RemoveAllVehs{"delvehs", "Remove All Vehicles", "Removes all non-mission-critical vehicles"};
}

