#include "coercions.h"
#include <iostream>

namespace {
int errorCount = 0;

void verifyCondition(bool result, const char* description, int lineNumber)
{
    if (!result) {
        std::cout << "Error " __FILE__ "(" << lineNumber << "): " << description
             << "    (failed)" << std::endl;
        if (0 <= errorCount && errorCount <= 100) {
            ++errorCount;
        }
    }
}
}  // close unnamed namespace

#define VERIFY(X) \
    verifyCondition((X), #X, __LINE__)

int main() {
    // Validation 1: boolean type conversion
    {
        VERIFY(Coercions::test_add_true == 6);
        VERIFY(Coercions::test_add_false == 5);
        std::cout << "Validation 1 (boolean type conversion): SUCCESS" << std::endl;
    }

    // Validation 2: struct/class type conversion
    {
        VERIFY(Coercions::test_double_wrapped == 14);
        std::cout << "Validation 2 (struct/class type conversion): SUCCESS" << std::endl;
    }

    // Validation 3: multiple-step type conversion
    {
        VERIFY(Coercions::test_add_boolbox == 11);
        std::cout << "Validation 3 (multiple-step type conversion): SUCCESS" << std::endl;
    }

    // Validation 4: callable object type conversion
    {
        VERIFY(Coercions::test_fun_coercion == 10);
        std::cout << "Validation 4 (callable object type conversion): SUCCESS" << std::endl;
    }

    if (errorCount == 0) {
        std::cout << "\nAll coercion validations completed successfully!" << std::endl;
    } else {
        std::cout << "\n" << errorCount << " validation(s) failed!" << std::endl;
    }

    return errorCount;
}

