template<typename WorkerType>
static TSharedRef<IPlasticSourceControlWorker, ESPMode::ThreadSafe> MakePlasticWorker()
{
	return MakeShareable(new WorkerType());
}

// Structure to hold operation registration data
struct FOperationRegistration
{
	const TCHAR* Name;
	FGetPlasticSourceControlWorker Creator;
};

void FPlasticSourceControlModule::StartupModule()
{
	// Define operations in a compact table-driven style
	static const FOperationRegistration Operations[] = {
		{ TEXT("Connect"),         FGetPlasticSourceControlWorker::CreateStatic(&MakePlasticWorker<FPlasticConnectWorker>) },
		{ TEXT("CheckOut"),        FGetPlasticSourceControlWorker::CreateStatic(&MakePlasticWorker<FPlasticCheckOutWorker>) },
		{ TEXT("UpdateStatus"),    FGetPlasticSourceControlWorker::CreateStatic(&MakePlasticWorker<FPlasticUpdateStatusWorker>) },
		{ TEXT("MarkForAdd"),      FGetPlasticSourceControlWorker::CreateStatic(&MakePlasticWorker<FPlasticMarkForAddWorker>) },
		{ TEXT("Delete"),          FGetPlasticSourceControlWorker::CreateStatic(&MakePlasticWorker<FPlasticDeleteWorker>) },
		{ TEXT("Revert"),          FGetPlasticSourceControlWorker::CreateStatic(&MakePlasticWorker<FPlasticRevertWorker>) },
		{ TEXT("RevertUnchanged"), FGetPlasticSourceControlWorker::CreateStatic(&MakePlasticWorker<FPlasticRevertUnchangedWorker>) },
		{ TEXT("RevertAll"),       FGetPlasticSourceControlWorker::CreateStatic(&MakePlasticWorker<FPlasticRevertAllWorker>) },
		{ TEXT("MakeWorkspace"),   FGetPlasticSourceControlWorker::CreateStatic(&MakePlasticWorker<FPlasticMakeWorkspaceWorker>) },
		{ TEXT("Sync"),            FGetPlasticSourceControlWorker::CreateStatic(&MakePlasticWorker<FPlasticSyncWorker>) },
		{ TEXT("CheckIn"),         FGetPlasticSourceControlWorker::CreateStatic(&MakePlasticWorker<FPlasticCheckInWorker>) },
		{ TEXT("Copy"),            FGetPlasticSourceControlWorker::CreateStatic(&MakePlasticWorker<FPlasticCopyWorker>) },
		{ TEXT("Resolve"),         FGetPlasticSourceControlWorker::CreateStatic(&MakePlasticWorker<FPlasticResolveWorker>) }
	};

	// Register each worker using a loop instead of repeated calls
	for (const auto& Op : Operations)
	{
		PlasticSourceControlProvider.RegisterWorker(Op.Name, Op.Creator);
	}

	// Load configuration settings
	PlasticSourceControlSettings.LoadSettings();

	// Bind provider to the modular feature system
	IModularFeatures::Get().RegisterModularFeature(TEXT("SourceControl"), &PlasticSourceControlProvider);
}

void FPlasticSourceControlModule::ShutdownModule()
{
	// Ensure provider is closed before module unloads
	PlasticSourceControlProvider.Close();

	// Remove binding from modular features registry
	IModularFeatures::Get().UnregisterModularFeature(TEXT("SourceControl"), &PlasticSourceControlProvider);
}

void FPlasticSourceControlModule::SaveSettings()
{
	// Skip saving if running unattended or as a commandlet
	if (FApp::IsUnattended() || IsRunningCommandlet())
	{
		return;
	}

	PlasticSourceControlSettings.SaveSettings();
}

