namespace NPerforator::NLinguist::NPython {
    TMaybe<TPythonVersion> TryScanVersion(TConstArrayRef<char> data);
}

TEST(PythonVersionParsing, TryScanVersion) {
    struct TestCase {
        TString Input;
        bool ExpectSuccess;
        TPythonVersion Expected;
    };

    TVector<TestCase> cases = {
        {"Python 3.10.0", true, {3, 10, 0}},
        {"Python 3.10.1", true, {3, 10, 1}},
        {"Python 2.7", true, {2, 7, 0}},
        {"Python 2.7.10", true, {2, 7, 10}},
        {"Python 3.8.15", true, {3, 8, 15}},
        {"Python 3.12.0", true, {3, 12, 0}},
        {"Python 3.12.1", true, {3, 12, 1}},
        {"Python 2.8.3", true, {2, 8, 3}},
        {"Python version 3.10.0, 64 bit", true, {3, 10, 0}},
        {"Version: Python 2.7.15", true, {2, 7, 15}},
        {"Python 4.0.0", false, {}},
        {"No version here", false, {}},
        {"Python v9.8.7", false, {}}
    };

    for (const auto& test : cases) {
        TMaybe<TPythonVersion> parsed = TryScanVersion(
            TConstArrayRef<char>{test.Input.data(), test.Input.size()}
        );

        if (test.ExpectSuccess) {
            ASSERT_TRUE(parsed.Defined()) 
                << "Expected to parse version from: '" << test.Input << "'";

            TString expStr = std::to_string(test.Expected.MajorVersion) + "." +
                             std::to_string(test.Expected.MinorVersion) + "." +
                             std::to_string(test.Expected.MicroVersion);
            TString actStr = std::to_string(parsed->MajorVersion) + "." +
                             std::to_string(parsed->MinorVersion) + "." +
                             std::to_string(parsed->MicroVersion);

            EXPECT_EQ(parsed->MajorVersion, test.Expected.MajorVersion)
                << "Major version mismatch on input '" << test.Input 
                << "' (expected " << expStr << ", got " << actStr << ")";
            EXPECT_EQ(parsed->MinorVersion, test.Expected.MinorVersion)
                << "Minor version mismatch on input '" << test.Input 
                << "' (expected " << expStr << ", got " << actStr << ")";
            EXPECT_EQ(parsed->MicroVersion, test.Expected.MicroVersion)
                << "Micro version mismatch on input '" << test.Input 
                << "' (expected " << expStr << ", got " << actStr << ")";
        } else {
            EXPECT_FALSE(parsed.Defined())
                << "Should not have parsed version from: '" << test.Input << "'";
        }
    }
}

