int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int b, w, x, y;
    if (cin >> b >> w >> x >> y) {
        // Determine minimum width needed for top and bottom sections
        int top_width = (w == 1) ? 1 : 2 * (w - 1) + 1;
        int bot_width = (b == 1) ? 1 : 2 * (b - 1) + 1;
        int cols = max(top_width, bot_width);

        vector<string> result;

        // Top section: black background with white islands
        if (w > 1) {
            string row1 = "";
            for (int i = 0; i < w - 1; ++i) {
                row1 += "@.";
            }
            row1 += '@';
            while ((int)row1.length() < cols) row1 += '@';
            result.push_back(row1);

            result.push_back(string(cols, '@'));
        } else {
            result.push_back(string(cols, '@'));
        }

        // Bottom section: white background with black islands
        if (b > 1) {
            result.push_back(string(cols, '.'));

            string row4 = "";
            for (int i = 0; i < b - 1; ++i) {
                row4 += ".@";
            }
            row4 += '.';
            while ((int)row4.length() < cols) row4 += '.';
            result.push_back(row4);
        } else {
            result.push_back(string(cols, '.'));
        }

        cout << result.size() << " " << cols << "\n";
        for (const auto& line : result) {
            cout << line << "\n";
        }
