#include <shmem.h>
#include <stdio.h>

int main(void) {
    // Initialize the SHMEM runtime environment
    shmem_init();

    // Determine current PE identity and total count
    int my_id = shmem_my_pe();     // Current processing element index
    int total_pe = shmem_n_pes();  // Total number of processing elements

    // Print initial greeting from each PE
    printf("Greetings from PE %d among %d PEs\n", my_id, total_pe);

    // -------------------------------------------------------------------------
    // Enhanced communication example: bidirectional data exchange
    // -------------------------------------------------------------------------

    // Allocate symmetric memory for integer storage
    int* shared_data = (int*) shmem_malloc(sizeof(int));

    // Each PE writes its own identifier into the shared location
    *shared_data = my_id;

    // Ensure all PEs have completed their write before proceeding
    shmem_barrier_all();

    // Compute neighbor indices for communication (circular ring topology)
    int predecessor = (my_id + total_pe - 1) % total_pe;
    int successor   = (my_id + 1) % total_pe;

    int val_from_pred;
    int val_from_succ;

    // Perform non-blocking gets from both neighbors
    shmem_int_get(&val_from_pred, shared_data, 1, predecessor);
    shmem_int_get(&val_from_succ,   shared_data, 1, successor);

    // Wait for all remote operations to complete locally
    shmem_quiet();

    // Report received values from both directions
    printf("PE %d got value %d from predecessor PE %d and value %d from successor PE %d\n",
           my_id, val_from_pred, predecessor, val_from_succ, successor);

    // -------------------------------------------------------------------------
    // Resource cleanup and finalization
    // -------------------------------------------------------------------------
    shmem_free(shared_data);
    shmem_finalize();

    return 0;
}

