//--------------------------------------------------------------------------
// Custom plugin context for instruction tracing functionality
class trace_manager : public plugmod_t, public event_listener_t
{
private:
    int m_instruction_count = 0;
    static constexpr int m_max_instructions = 20;

public:
    ~trace_manager() override
    {
        // Event listeners are automatically cleaned up on module unload
    }

    bool idaapi run(size_t) override;
    ssize_t idaapi on_event(ssize_t code, va_list va) override;
};

//--------------------------------------------------------------------------
// Event handler for debugger notifications
ssize_t idaapi trace_manager::on_event(ssize_t code, va_list va)
{
    switch (code)
    {
        case dbg_process_start:
            // Reset the instruction counter when process starts
            m_instruction_count = 0;
            break;

        case dbg_run_to:
            msg("tracer: entrypoint reached\n");
            enable_insn_trace(true);
            request_continue_process();
            run_requests();
            break;

        case dbg_trace:
            {
                // Extract thread ID and instruction pointer from arguments
                /*thid_t tid =*/ va_arg(va, thid_t);
                ea_t current_ip = va_arg(va, ea_t);
                msg("[%d] tracing over: %a\n", m_instruction_count, current_ip);

                if (m_instruction_count == m_max_instructions)
                {
                    disable_step_trace();
                    suspend_process();
                    msg("process suspended after tracing %d instructions\n", m_max_instructions);
                }
                else
                {
                    ++m_instruction_count;
                }
            }
            break;

        case dbg_process_exit:
            unhook_event_listener(HT_DBG, this);
            break;
    }
    return 0;
}

//--------------------------------------------------------------------------
// Plugin execution entry point
bool idaapi trace_manager::run(size_t)
{
    if (!hook_event_listener(HT_DBG, this))
    {
        warning("Failed to hook debugger notification point");
        return true;
    }

    if (dbg == nullptr)
        load_debugger("win32", false);

    // Attempt to run to the program's entry point
    if (!run_to(inf_get_start_ea()))
        unhook_event_listener(HT_DBG, this);

    return true;
}

//--------------------------------------------------------------------------
// Plugin initialization function
static plugmod_t* idaapi init()
{
    // Restrict plugin to x86 PE executables only
    if (PH.id != PLFM_386 || inf_get_filetype() != f_PE)
        return nullptr;

    return new trace_manager();
}

