#include <vector>
using namespace std;

// LeetCode 136: Single Number (Type III Clone)
// Given a non-empty array of integers nums, every element appears twice except for one. Find that single one.
// You must implement a solution with a linear runtime complexity and use only constant extra space.
class Solution {
public:
    int singleNumber(vector<int>& nums) {
        int result = 0;
        for (int i = 0; i < nums.size(); ++i) {
            result ^= nums[i];
        }
        return result;
    }
};

// Logic Explanation:
// This implementation uses the XOR bitwise operation to identify the unique number.
// Key properties of XOR used:
// - Any number XORed with itself yields 0 (x ^ x = 0)
// - Any number XORed with 0 remains unchanged (x ^ 0 = x)
// - XOR is commutative and associative, so order doesn't affect the outcome
// As all duplicate numbers appear exactly twice, their contributions cancel out,
// leaving only the number that appears once.
// Time Complexity: O(n) — single pass through the input array
// Space Complexity: O(1) — only one integer variable used for accumulation

