#include <iostream>
#include <vector>
#include <algorithm>
#include <cassert>

// Global variables for simplicity in competitive programming context
int n;
std::vector<int> arr;
std::vector<int> pos;
std::vector<std::pair<int, int>> operations;

// Perform an operation and record it
void execute_operation(int x, int y) {
    if (x <= 0 || y <= 0 || x + y >= n) {
        return; // Invalid operation - should not occur in correct usage
    }
    operations.push_back({x, y});

    std::vector<int> part1, part2, part3;
    part1.assign(arr.begin(), arr.begin() + x);
    part2.assign(arr.begin() + x, arr.begin() + n - y);
    part3.assign(arr.begin() + n - y, arr.end());

    arr.clear();
    arr.insert(arr.end(), part3.begin(), part3.end());
    arr.insert(arr.end(), part2.begin(), part2.end());
    arr.insert(arr.end(), part1.begin(), part1.end());

    // Update position mapping
    for (int idx = 0; idx < n; ++idx) {
        pos[arr[idx]] = idx + 1;
    }
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::cin >> n;
    arr.resize(n);
    pos.resize(n + 1);

    for (int i = 0; i < n; ++i) {
        std::cin >> arr[i];
        pos[arr[i]] = i + 1;
    }

    if (n == 3) {
        // For n=3, only possible operation is full reversal
        // Choose lexicographically smaller between current and reversed array
        std::vector<int> reversed_arr = arr;
        std::reverse(reversed_arr.begin(), reversed_arr.end());
        if (reversed_arr < arr) {
            execute_operation(1, 1);
        }
    } else {
        // For n >= 4, sort the permutation using allowed operations
        // Strategy: place each number i at position i sequentially
        for (int target_value = 1; target_value <= n; ++target_value) {
            int current_pos = pos[target_value];
            if (current_pos == target_value) {
                continue;
            }

            // Move element to front (position 1) if not already there
            if (current_pos > 1) {
                execute_operation(current_pos - 1, 1);
                execute_operation(n - 1, 1);
            }

            // Now target_value is at position 1
            // Move it to its correct position (target_value)
            if (target_value > 1) {
                execute_operation(1, n - target_value);
                execute_operation(target_value, 1);
            }
        }
    }

    std::cout << operations.size() << "\n";
    for (const auto& op : operations) {
        std::cout << op.first << " " << op.second << "\n";
    }

    return 0;
}

