#include "PipelineExecutor.h"
#include "Processor.h"
#include "PipelineV2.h"
#include "PipelineBuffer.h"

using namespace db;

PipelineExecutor::PipelineExecutor(PipelineV2* pipeline,
                                   ExecutionContext* ctxt)
    : _pipeline(pipeline),
      _ctxt(ctxt)
{
}

PipelineExecutor::~PipelineExecutor() {
}

void PipelineExecutor::init() {
    // Populate initial worklist with source processors
    auto& pending = _activeStack;
    for (auto src : _pipeline->sources()) {
        pending.push(src);
    }
}

void PipelineExecutor::execute() {
    init();
    while (!(_activeStack.empty() && _updateQueue.empty())) {
        if (_activeStack.empty()) {
            // If active stack is empty but update queue isn't, break to avoid infinite loop
            break;
        }
        executeStep();
    }
}

void PipelineExecutor::executeStep() {
    auto& pending = _activeStack;
    auto& readyList = _updateQueue;

    // Drain the active stack until we find a runnable processor or it becomes empty
    bool foundRunnable = false;
    while (!pending.empty() && !foundRunnable) {
        Processor* candidate = pending.top();
        pending.pop();

        if (candidate->canExecute()) {
            readyList.push(candidate);
            foundRunnable = true;
        }
    }

    // Process all currently ready processors
    while (!readyList.empty()) {
        Processor* proc = readyList.front();
        readyList.pop();

        if (!proc->isPrepared()) {
            proc->prepare(_ctxt);
        }

        if (proc->isFinished()) {
            proc->reset();
        }

        proc->execute();

        // If still not done, push back onto pending stack for later resumption
        if (!proc->isFinished()) {
            pending.push(proc);
        }

        proc->setScheduled(false);

        // Enqueue any newly schedulable downstream processors
        for (PipelineOutputPort* out : proc->outputs()) {
            PipelineInputPort* inp = out->getConnectedPort();
            if (inp) {
                Processor* downstream = inp->getProcessor();
                if (!downstream->isScheduled() && downstream->canExecute()) {
                    readyList.push(downstream);
                    downstream->setScheduled(true);
                }
            }
        }
    }
}

