// Helper lambda to check if a section matches any of the discard patterns
inline bool shouldDiscard(const Section &sec) {
    const std::string name = sec.getName();
    return sec.matchPattern(".text.f1*") || sec.matchPattern(".rela.text.f1*");
}

// Base class for discard plugins — encapsulates common behavior
class DiscardBase : public Plugin {
protected:
    std::vector<Section> m_sectionsToDiscard;

    void collectSections(Section S) {
        if (shouldDiscard(S)) {
            m_sectionsToDiscard.emplace_back(std::move(S));
        }
    }

    Status performDiscard(bool Trace) {
        for (auto &section : m_sectionsToDiscard) {
            std::cout << "Discarding section " << section.getName() << "\n";
            section.markAsDiscarded();
        }
        return Plugin::Status::SUCCESS;
    }

public:
    uint32_t GetLastError() override { return 0; }
    std::string GetLastErrorAsString() override { return "SUCCESS"; }
    void Destroy() override {}
};

class DLL_A_EXPORT DiscardPlugin : public SectionIteratorPlugin, public DiscardBase {
public:
    DiscardPlugin() : SectionIteratorPlugin("DISCARD") {}

    void Init(std::string /* Options */) override {}

    void processSection(Section S) override {
        collectSections(std::move(S));
    }

    Status Run(bool Trace) override {
        return performDiscard(Trace);
    }

    std::string GetName() override { return "DISCARD"; }
};

class DLL_A_EXPORT DiscardPluginSM : public SectionMatcherPlugin, public DiscardBase {
public:
    DiscardPluginSM() : SectionMatcherPlugin("DiscardPluginSM") {}

    void Init(std::string /* Options */) override {}

    void processSection(Section S) override {
        collectSections(std::move(S));
    }

    Status Run(bool Trace) override {
        return performDiscard(Trace);
    }

    std::string GetName() override { return "DiscardPluginSM"; }
};

