extern "C" {
bool DLL_A_EXPORT RegisterAll() {
    g_pluginRegistry["DISCARD"] = new DiscardPlugin{};
    g_pluginRegistry["DiscardPluginSM"] = new DiscardPluginSM{};
    return true;
}

PluginBase *DLL_A_EXPORT getPlugin(const char *name) {
    auto it = g_pluginRegistry.find(name);
    return (it != g_pluginRegistry.end()) ? static_cast<PluginBase*>(it->second) : nullptr;
}

void DLL_A_EXPORT Cleanup() {
    for (auto &pair : g_pluginRegistry) {
        delete pair.second;
    }
    g_pluginRegistry.clear();
}
