#include <vector>
#include <algorithm>
#include <cmath>

class Solution {
public:
    int minOperations(std::vector<int>& nums) {
        int totalElements = nums.size();
        int onesCount = std::count(nums.begin(), nums.end(), 1);

        // If there's at least one 1, we only need to convert remaining elements
        if (onesCount > 0) {
            return totalElements - onesCount;
        }

        int minimumSteps = 10000000; // Initialize with a large value

        // Check all possible subarrays to find the shortest one with GCD = 1
        for (int start = 0; start < totalElements; ++start) {
            int currentGcd = nums[start];
            for (int end = start + 1; end < totalElements; ++end) {
                currentGcd = std::gcd(currentGcd, nums[end]);

                if (currentGcd == 1) {
                    // Operations needed: (end - start) to create a 1, then (totalElements - 1) to convert rest
                    int stepsNeeded = (end - start) + (totalElements - 1);
                    minimumSteps = std::min(minimumSteps, stepsNeeded);
                    break;
                }
            }
        }

        return (minimumSteps == 10000000) ? -1 : minimumSteps;
    }
};

#include <vector>
#include <numeric>
#include <algorithm>

class Solution {
public:
    long long maxPower(std::vector<int>& stations, int r, int k) {
        // Determine search bounds for binary search
        long long low = 0;
        long long high = std::accumulate(stations.begin(), stations.end(), 0LL) + k;
        long long result = 0;

        // Binary search for maximum achievable minimum power
        while (low <= high) {
            long long mid = low + (high - low) / 2;

            if (canAchieve(stations, r, mid, k)) {
                result = mid;
                low = mid + 1;  // Try for higher minimum power
            } else {
                high = mid - 1; // Reduce requirement
            }
        }

        return result;
    }

private:
    bool canAchieve(std::vector<int>& stations, int radius, long long targetPower, int extraStations) {
        int cityCount = stations.size();

        // Calculate initial window power for first city
        long long currentPower = 0;
        for (int i = 0; i <= std::min(radius, cityCount - 1); ++i) {
            currentPower += stations[i];
        }

        // Track additional stations placed at each position
        std::vector<long long> placements(cityCount, 0);

        for (int city = 0; city < cityCount; ++city) {
            // Expand window to include right boundary if possible
            int rightBound = city + radius;
            if (rightBound < cityCount && rightBound > radius + city - 1) {
                currentPower += stations[rightBound];
            }

            // Check if current power meets target
            if (currentPower < targetPower) {
                long long deficit = targetPower - currentPower;

                if (deficit > extraStations) {
                    return false;
                }

                // Place stations at furthest position in coverage range
                int placementPos = std::min(cityCount - 1, rightBound);
                placements[placementPos] += deficit;
                currentPower = targetPower;
                extraStations -= deficit;
            }

            // Shrink window from left side as we move to next city
            int leftBound = city - radius;
            if (leftBound >= 0) {
                currentPower -= stations[leftBound] + placements[leftBound];
            }
        }

        return true;
    }
};

