#include <iostream>
#include <vector>
#include <string>

int main() {
    // Design a winding path on a 20x20 grid to simulate a constrained movement corridor
    // The path is constructed to approximate a Hamiltonian-like traversal with limited branching
    // This setup aims to maximize the chance of synchronization failure under random motion

    const int ROWS = 20;
    const int COLS = 20;

    std::cout << ROWS << " " << COLS << "\n";

    std::vector<std::string> map(ROWS, std::string(COLS, '0'));

    // Build horizontal corridors in alternating directions
    for (int row = 0; row < ROWS; ++row) {
        if (row % 2 == 0) {
            // Fill entire even rows with passable cells
            for (int col = 0; col < COLS; ++col) {
                map[row][col] = '1';
            }
        } else {
            // For odd rows, place only one passable cell to link adjacent rows
            // Alternate connection points: right side for rows 1,5,9,... and left side for rows 3,7,11,...
            if ((row / 2) % 2 == 0) {
                map[row][COLS - 1] = '1';  // Connect at right end
            } else {
                map[row][0] = '1';          // Connect at left end
            }
        }
    }

    // Output the resulting grid
    for (const auto& line : map) {
        std::cout << line << "\n";
    }

    return 0;
}

