#include <stack>
using namespace std;

// LeetCode 210: Course Schedule II (Type III Clone)
// Modified implementation using DFS-based topological sort with improved adjacency handling
class Solution {
public:
    // Helper function to detect cycles using DFS with adjacency list representation
    bool hasCycle(int node, vector<int>& color, const vector<vector<int>>& adj) {
        color[node] = 1; // Mark as being visited

        for (int neighbor : adj[node]) {
            if (color[neighbor] == 1) {
                return true; // Back edge found - cycle detected
            }
            if (color[neighbor] == 0 && hasCycle(neighbor, color, adj)) {
                return true;
            }
        }

        color[node] = 2; // Mark as fully processed
        return false;
    }

    // DFS helper for topological ordering
    void dfsTopo(int node, vector<bool>& visited, stack<int>& order, const vector<vector<int>>& adj) {
        visited[node] = true;

        for (int neighbor : adj[node]) {
            if (!visited[neighbor]) {
                dfsTopo(neighbor, visited, order, adj);
            }
        }

        order.push(node);
    }

    vector<int> findOrder(int numCourses, vector<vector<int>>& prerequisites) {
        // Build adjacency list: for prerequisite [a, b], b -> a (b must be taken before a)
        vector<vector<int>> adj(numCourses);
        for (const auto& prereq : prerequisites) {
            int course = prereq[0];
            int pre = prereq[1];
            adj[pre].push_back(course);
        }

        // Check for cycles using three-color marking
        vector<int> color(numCourses, 0); // 0: unvisited, 1: visiting, 2: visited
        for (int i = 0; i < numCourses; ++i) {
            if (color[i] == 0 && hasCycle(i, color, adj)) {
                return {}; // Cycle exists, impossible to finish all courses
            }
        }

        // Perform topological sort via DFS
        vector<bool> visited(numCourses, false);
        stack<int> topoStack;

        for (int i = 0; i < numCourses; ++i) {
            if (!visited[i]) {
                dfsTopo(i, visited, topoStack, adj);
            }
        }

        // Convert stack to result vector (reverse of finishing times)
        vector<int> result;
        while (!topoStack.empty()) {
            result.push_back(topoStack.top());
            topoStack.pop();
        }

        return result;
    }
};

#include <RegexPayloadProcessorHTTP.h>
#include <spdlog/spdlog.h>

void RegexPayloadProcessorHTTP::Process(http::request<http::string_body> const& req, tcp::socket& sock) {
    http::response<http::string_body> response;
    response.version(req.version());
    response.keep_alive(req.keep_alive());
    response.result(http::status::ok);
    response.set(http::field::content_type, "application/json; charset=UTF-8");
    response.set(http::field::vary, "Origin");

    bool matched = false;
    for (const auto& [pattern, handler] : m_resMap) {
        if (std::regex_search(req.body(), pattern.m_rx)) {
            response.body() = handler->dump();
            response.prepare_payload();
            http::write(sock, response);
            matched = true;
            break;
        }
    }

    if (!matched) {
        spdlog::error("Regex processor {} failed to find any valid response for the packet, dropping the packet.\nPacket contents: {}", GetRoute(), req.body());
    }
}

