using test_service_package::IntRequest;
using test_service_package::IntReply;
using test_service_package::Decompositor;

class DecompositionClient {
 public:
  explicit DecompositionClient(std::shared_ptr<Channel> channel)
      : stub_(Decompositor::NewStub(channel)) {}

  std::string RequestDecomposition(const int& input_value) {
    IntRequest request;
    request.set_value(input_value);

    IntReply response;
    ClientContext context;

    Status rpc_status = stub_->Decompose(&context, request, &response);

    if (rpc_status.ok()) {
      return response.message();
    } else {
      std::cerr << "Error code: " << rpc_status.error_code() 
                << ", message: " << rpc_status.error_message() << std::endl;
      return "RPC invocation failed";
    }
  }

 private:
  std::unique_ptr<Decompositor::Stub> stub_;
};

int main(int argc, char** argv) {
  // Create client with insecure connection to local gRPC server
  DecompositionClient client(grpc::CreateChannel(
      "localhost:50051", grpc::InsecureChannelCredentials()));

  int number_to_decompose = 42;
  std::string result = client.RequestDecomposition(number_to_decompose);

  std::cout << "Received from Decompositor service: " << result << std::endl;

  return 0;
}

