#include <cstddef>

// Redefine PTMF structure with alternative field organization
struct MemberFunctionPointer {
    std::ptrdiff_t this_adjustment;   // adjustment to 'this' pointer
    std::ptrdiff_t vtable_index;      // index in vtable (-1 indicates non-virtual)
    union FunctionInfo {
        void* direct_address;         // address for non-virtual functions
        std::ptrdiff_t vtable_slot;   // slot offset for virtual functions
    } function;
};

// Initialize null member function pointer
const MemberFunctionPointer null_mfp = {0, -1, {nullptr}};

/* clang-format off */
asm void test_member_function_ptr(register MemberFunctionPointer* mfp) {
  nofralloc
  // Load all three components of the member function pointer
  lwz r4, MemberFunctionPointer.this_adjustment(mfp)
  lwz r5, MemberFunctionPointer.vtable_index(mfp)
  lwz r6, MemberFunctionPointer.function(mfp)

  // Set result to 1 initially
  li r3, 1

  // Check each component for zero/non-zero values
  cmpwi cr0, r4, 0
  cmpwi cr1, r5, -1
  cmpwi cr2, r6, 0

  // Return false if any component indicates null
  beq cr0, @check_vtable
  li r3, 0
  blr

@check_vtable:
  beq cr1, @check_function
  li r3, 0
  blr

@check_function:
  beq cr2, @done
  li r3, 0
  blr

@done:
  blr
}

asm void call_member_function_ptr(...) {
  nofralloc
  // Extract components from member function pointer
  lwz r0, MemberFunctionPointer.this_adjustment(r12)
  lwz r11, MemberFunctionPointer.vtable_index(r12)
  lwz r12, MemberFunctionPointer.function(r12)

  // Adjust 'this' pointer
  add r3, r3, r0

  // Handle virtual vs non-virtual function calls
  cmpwi r11, -1
  beq @non_virtual

  // Virtual function path: traverse vtable
  lwzx r12, r3, r12     // load vtable pointer
  lwzx r12, r12, r11    // load function address from vtable slot
  b @dispatch

@non_virtual:
  // Non-virtual function: use direct address
  // (function address already loaded in r12)

@dispatch:
  // Setup and branch to target function
  mtctr r12
  bctr
}
