#include <iostream>
#include <fstream>
#include <string>
#include <vector>

int main(int argc, char* argv[]) {
    std::string rootPath = "";
    bool all_ok = true;
    std::cout << "Starting diagnostic read for .ans files in " << rootPath << std::endl;

    int counter = 1;
    while (counter <= 10) {
        std::string fname = rootPath + std::to_string(counter) + ".ans";
        std::cout << "\n--- Reading file: " << fname << " ---" << std::endl;

        std::ifstream input(fname);
        if (!input.is_open()) {
            std::cerr << "  [ERROR] Could not open the file. It may not exist." << std::endl;
            all_ok = false;
            counter++;
            continue;
        }

        // Verify file is not empty
        input.seekg(0, std::ios::end);
        if (input.tellg() == 0) {
            std::cerr << "  [ERROR] File is completely empty." << std::endl;
            all_ok = false;
            input.close();
            counter++;
            continue;
        }
        input.seekg(0, std::ios::beg);

        std::vector<std::pair<int, int>> dataPoints;
        int row, col;
        while (input >> row >> col) {
            dataPoints.emplace_back(row, col);
        }

        // Determine why reading stopped
        if (input.eof()) {
            if (dataPoints.empty()) {
                std::cerr << "  [WARNING] File opened but contained no valid integer pairs." << std::endl;
            } else {
                std::cout << "  [SUCCESS] Successfully read " << dataPoints.size() << " pairs of integers." << std::endl;
            }
        } else if (input.fail()) {
            std::cerr << "  [ERROR] Reading failed. The file may contain non-integer data or be malformed." << std::endl;
            all_ok = false;
        }

        input.close();
        counter++;
    }

    std::cout << "\n--- Summary ---" << std::endl;
    if (all_ok) {
        std::cout << "All checked .ans files were read successfully." << std::endl;
    } else {
        std::cout << "There were errors reading one or more .ans files. Please review the logs above." << std::endl;
    }

    return 0;
}

