bool NResource::FindExact(const TStringBuf key, TString* out) {
    return CommonStore()->FindExact(key, out);
}

void NResource::FindMatch(const TStringBuf subkey, TResources* out) {
    struct MatchFinder : public IMatch {
        inline MatchFinder(TResources* result)
            : Result(result)
        {
        }

        void OnMatch(const TResource& res) override {
            Result->push_back(res);
        }

        TResources* Result;
    };

    MatchFinder finder(out);
    CommonStore()->FindMatch(subkey, finder);
}

bool NResource::Has(const TStringBuf key) {
    return CommonStore()->Has(key);
}

TString NResource::Find(const TStringBuf key) {
    TString value;
    if (FindExact(key, &value)) {
        return value;
    }
    ythrow yexception() << "can not find resource with path " << key;
}

size_t NResource::Count() noexcept {
    return CommonStore()->Count();
}

TStringBuf NResource::KeyByIndex(size_t idx) {
    return CommonStore()->KeyByIndex(idx);
}

TVector<TStringBuf> NResource::ListAllKeys() {
    const size_t total = Count();
    TVector<TStringBuf> keys;
    keys.reserve(total);

    for (size_t index = 0; index < total; ++index) {
        keys.push_back(KeyByIndex(index));
    }

    return keys;
}

#include <Application.h>
#include <File.h>
#include <TranslatorRoster.h>
#include <iostream>
#include <cstring>

class TextConverterApp : public BApplication
{
public:
	TextConverterApp(int argc, char** argv)
		:
		BApplication("application/x-vnd.demo-textconverter"),
		fArgc(argc),
		fArgv(argv)
	{
	}

	void ReadyToRun() override
	{
		if (fArgc < 2) {
			std::cerr << "Usage: " << fArgv[0] << " <rtf_input_file>" << std::endl;
			PostMessage(B_QUIT_REQUESTED);
			return;
		}

		const char* sourcePath = fArgv[1];

		// Attempt to open the source RTF file for reading
		BFile inputFile(sourcePath, B_READ_ONLY);
		if (inputFile.InitCheck() != B_OK) {
			std::cerr << "Error: Unable to access input file '" << sourcePath << "'" << std::endl;
			PostMessage(B_QUIT_REQUESTED);
			return;
		}

		// Prepare output file for plain text
		BFile outputFile("converted_output.txt",
			B_CREATE_FILE | B_ERASE_FILE | B_WRITE_ONLY);

		// Acquire default translator roster
		BTranslatorRoster* roster = BTranslatorRoster::Default();
		if (!roster) {
			std::cerr << "Critical: Could not retrieve system translator roster" << std::endl;
			PostMessage(B_QUIT_REQUESTED);
			return;
		}

		// Perform translation from RTF to plain text ('TEXT' format)
		status_t result = roster->Translate(&inputFile, nullptr, nullptr, &outputFile, 'TEXT');
		if (result != B_OK) {
			std::cerr << "Conversion error: " << strerror(result) << std::endl;
		} else {
			std::cout << "Success: RTF content converted and saved as 'converted_output.txt'" << std::endl;
		}

		// Terminate application after processing
		PostMessage(B_QUIT_REQUESTED);
	}

private:
	int fArgc;
	char** fArgv;
};

int main(int argc, char** argv)
{
	TextConverterApp app(argc, argv);
	app.Run();
	return 0;
}

#include "debugger/MemoryWatch.hpp"

MemoryWatch::MemoryWatch() {
    // Initialize empty watch list
}

void MemoryWatch::add(uint32_t beginAddr, uint32_t endAddr) {
    // Construct new watch entry using provided addresses
    watch_entry_t newEntry;
    newEntry.start = beginAddr;
    newEntry.end   = endAddr;

    // Append to the internal container
    watches.emplace_back(newEntry);
}

void MemoryWatch::remove(uint32_t firstAddress) {
    // Erase any entries whose starting address equals firstAddress
    for (auto iter = watches.begin(); iter != watches.end(); ++iter) {
        if (iter->start == firstAddress) {
            watches.erase(iter);
            return;
        }
    }
}

void MemoryWatch::clear() {
    // Remove all registered memory watches
    watches.clear();
}

