using namespace std;

// Function to write user input into a file named "data.txt"
void writeToFile() {
    ofstream outputFile;
    char buffer[128];
    char choice;

    outputFile.open("data.txt");
    if (!outputFile.is_open()) {
        cerr << "Error: Cannot open file for writing." << endl;
        cin.ignore(); // Clear input buffer
        cin.get();    // Wait for keypress (equivalent to getch())
        exit(EXIT_FAILURE);
    }

    do {
        cout << "Enter line of text: ";
        cin.ignore(); // Clear any leftover newline
        cin.getline(buffer, 127);
        outputFile << buffer << '\n';

        cout << "Continue entering lines? (y/n): ";
        cin >> choice;
        cin.ignore(); // Discard trailing newline after char input
    } while (choice == 'y' || choice == 'Y');

    outputFile.close();
}

// Function to read and display contents of the file
void readFileAndPrint() {
    ifstream inputFile;
    char ch;

    cout << "File contents:" << endl;
    inputFile.open("data.txt");
    if (!inputFile.is_open()) {
        cerr << "Error: Cannot open file for reading." << endl;
        cin.ignore();
        cin.get();
        exit(EXIT_FAILURE);
    }

    while (inputFile.get(ch)) {
        cout.put(ch);
    }

    inputFile.close();
}

int main() {
    writeToFile();
    readFileAndPrint();
    return 0;
}

