MainWindow::MainWindow(QWidget *parent)
    : QMainWindow(parent)
    , ui(new Ui::MainWindow)
{
    ui->setupUi(this);
    this->initializeVisualizationWidget();
    this->createHexSurface();
}

MainWindow::~MainWindow() { delete ui; }

void MainWindow::createHexSurface()
{
    // Initialize hexagonal grid with radius 0.6f and spacing 0.01f
    this->hexGrid = std::make_unique<sm::hexgrid>(0.01f, 3.0f, 0.0f);
    this->hexGrid->setCircularBoundary(0.6f);

    // Prepare scalar field for surface height using sine modulation
    const size_t pointCount = this->hexGrid->num();
    this->surfaceHeights.resize(pointCount, 0.0f);

    size_t idx = 0;
    while (idx < pointCount) {
        float xCoord = this->hexGrid->d_x[idx];
        float yCoord = this->hexGrid->d_y[idx];
        float waveProduct = std::sin(20.0f * xCoord) * std::sin(10.0f * yCoord);
        this->surfaceHeights[idx] = 0.05f + 0.05f * waveProduct;
        ++idx;
    }

    // Define visual offset for rendering
    sm::vec<float, 3> renderOffset = { 0.0f, -0.05f, 0.0f };

    // Construct HexGridVisual instance
    auto hexVisual = std::make_unique<mplot::HexGridVisual<float, mplot::qt::gl_version>>(
        this->hexGrid.get(), renderOffset);

    // Register model with visualization context
    static_cast<mplot::qt::viswidget<0>*>(this->vizWidgetPtr)->v.bindmodel(hexVisual);

    // Attach scalar data to visual representation
    hexVisual->setScalarData(&this->surfaceHeights);

    // Move ownership into base VisualModel pointer and add to list
    std::unique_ptr<mplot::VisualModel<mplot::qt::gl_version>> basePtr = std::move(hexVisual);
    static_cast<mplot::qt::viswidget<0>*>(this->vizWidgetPtr)->newvisualmodels.push_back(std::move(basePtr));
}

void MainWindow::initializeVisualizationWidget()
{
    // Instantiate OpenGL visualization widget
    mplot::qt::viswidget<0>* vw = new mplot::qt::viswidget<0>(this->parentWidget());

    // Enable default lighting effects
    vw->v.lightingEffects();

    // Embed widget into main window layout
    this->ui->verticalLayout->addWidget(vw);

    // Store reference for later use
    this->vizWidgetPtr = vw;
}

void MainWindow::on_pushButton_clicked()
{
    std::cout << "Adding a GraphVisual...\n";

    // Create new graph visual at current location
    auto graphVisual = std::make_unique<mplot::GraphVisual<double, mplot::qt::gl_version>>(this->graphPosition);

    // Bind to shared rendering context
    static_cast<mplot::qt::viswidget<0>*>(this->vizWidgetPtr)->v.bindmodel(graphVisual);

    // Configure as 3D curve (x vs x^2)
    graphVisual->twodimensional(false);

    // Generate sample data points
    sm::vvec<double> abscissas;
    abscissas.linspace(-1.5, 1.5, 25);
    auto ordinates = abscissas.pow(2);

    // Assign data to visual
    graphVisual->setdata(abscissas, ordinates);

    // Transfer ownership and register
    std::unique_ptr<mplot::VisualModel<mplot::qt::gl_version>> baseGraph = std::move(graphVisual);
    static_cast<mplot::qt::viswidget<0>*>(this->vizWidgetPtr)->newvisualmodels.push_back(std::move(baseGraph));

    // Force immediate redraw
    this->vizWidgetPtr->update();

    // Shift next graph vertically
    this->graphPosition[1] += 1.2f;
}

