#include <iostream>
#include <vector>
#include <cstdlib>
#include <boost/test/unit_test.hpp>

// Helper alias for clarity
using bit_vector = std::vector<bool>;

// Forward declarations of test helpers (assumed from headers)
void test_equal_bits(const bit_vector&, const auto&, const char*);
void test_rank_select1(const bit_vector&, const auto&, const char*);
void test_delta(const auto&, const char*);
void test_select_enumeration(const bit_vector&, const auto&, const char*);

BOOST_AUTO_TEST_SUITE(elias_fano_tests)

BOOST_AUTO_TEST_CASE(random_bit_vectors)
{
    std::srand(42);
    constexpr size_t N = 10000;

    // Iterate over various densities: 1/2, 1/4, ..., 1/128
    for (size_t exp = 1; exp <= 7; ++exp) {
        double density = 1.0 / (1ULL << exp);

        // Generate random bit vector
        bit_vector original(N);
        for (size_t idx = 0; idx < N; ++idx) {
            original[idx] = (std::rand() % (1U << exp)) == 0;
        }

        // Build Elias-Fano structure
        succinct::bit_vector_builder builder;
        for (bool bit : original) {
            builder.push_back(bit);
        }
        succinct::elias_fano ef(&builder);

        // Run all validation tests
        test_equal_bits(original, ef, "Random bitmap");
        test_rank_select1(original, ef, "Random bitmap");
        test_delta(ef, "Random bitmap");
        test_select_enumeration(original, ef, "Random bitmap");
    }
}

BOOST_AUTO_TEST_CASE(empty_bit_vector)
{
    constexpr size_t N = 10000;
    succinct::bit_vector_builder builder(N);
    succinct::elias_fano ef(&builder);

    BOOST_CHECK_EQUAL(0u, ef.num_ones());

    bit_vector empty(N, false);
    test_equal_bits(empty, ef, "Empty bitmap");
    test_select_enumeration(empty, ef, "Empty bitmap");
}

BOOST_AUTO_TEST_CASE(single_set_bit)
{
    constexpr size_t N = 10000;
    size_t pos = 37;

    // Construct reference vector
    bit_vector ref(N, false);
    ref[pos] = true;

    // Build EF structure
    succinct::bit_vector_builder builder;
    builder.set(pos, 1);
    succinct::elias_fano ef(&builder);

    BOOST_CHECK_EQUAL(1u, ef.num_ones());

    test_equal_bits(ref, ef, "Only one value");
    test_rank_select1(ref, ef, "Only one value");
    test_delta(ef, "Only one value");
    test_select_enumeration(ref, ef, "Only one value");
}

BOOST_AUTO_TEST_CASE(all_ones_bitmap)
{
    constexpr size_t N = 10000;

    // Reference full vector
    bit_vector full(N, true);

    // Build EF from all-ones builder
    succinct::bit_vector_builder builder;
    for (size_t i = 0; i < N; ++i) {
        builder.push_back(true);
    }
    succinct::elias_fano ef(&builder);

    test_equal_bits(full, ef, "Full bitmap");
    test_rank_select1(full, ef, "Full bitmap");
    test_delta(ef, "Full bitmap");
    test_select_enumeration(full, ef, "Full bitmap");
}

BOOST_AUTO_TEST_SUITE_END()

#include "utl/JsonEncode.h"
#include <cstring>

void JSONStrEncode(const char *cc, String &str) {
    size_t len = std::strlen(cc);
    for (size_t idx = 0; idx < len; ++idx) {
        unsigned char ch = static_cast<unsigned char>(cc[idx]);

        switch (ch) {
            case '"':
                str += "\\\"";
                break;
            case '\\':
                str += "\\\\";
                break;
            case '/':
                str += "\\/";
                break;
            case '\b':
                str += "\\b";
                break;
            case '\r':
                str += "\\r";
                break;
            case '\n':
                str += "\\n";
                break;
            case '\t':
                str += "\\t";
                break;
            default:
                if (ch < ' ') {
                    str += "\\u00";
                    const char hexDigits[] = "0123456789ABCDEF";
                    str += hexDigits[(ch >> 4) & 0x0F];
                    str += hexDigits[ch & 0x0F];
                } else {
                    str += static_cast<char>(ch);
                }
                break;
        }
    }
}

