#include "InputStreamReader.h"
#include "DataInputStream.h"

// Constructs an InputStreamReader using the default character encoding.
// Parameters:
// in - The underlying InputStream to read from
InputStreamReader::InputStreamReader(InputStream* in)
: stream(new DataInputStream(in)) {}

// Releases resources and closes the underlying input stream.
// After closing, any further operations (read, ready, mark, reset, skip) will fail.
// Closing an already-closed stream is safe and has no effect.
void InputStreamReader::close() { 
    stream->close(); 
}

// Reads one UTF character from the stream.
// Returns:
// The 16-bit character value, or -1 if end-of-stream is reached
int InputStreamReader::read() { 
    return stream->readUTFChar(); 
}

// Reads multiple characters into a provided buffer.
// Parameters:
// cbuf - Target wide character array
// offset - Starting index in cbuf where characters will be placed
// length - Maximum number of characters to attempt to read
// Returns:
// Number of characters actually read, or -1 if no characters could be read due to EOF
int InputStreamReader::read(
    wchar_t      cbuf[],
    unsigned int offset,
    unsigned int length
) {
    unsigned int count = 0;
    unsigned int index = offset;

    while (count < length && index < offset + length) {
        int rawChar = stream->readUTFChar();
        if (rawChar != -1) {
            cbuf[index] = static_cast<wchar_t>(rawChar);
            count++;
            index++;
        } else {
            break;
        }
    }

    return (count > 0 || length == 0) ? count : -1;
}

