namespace tpa
{
namespace
{
// Determines whether a CFG node belongs to the top-level category.
// Top-level nodes (Alloc, Copy, Offset) influence only the environment (Env),
// without touching the memory store (Store).
bool isTopLevel(const CFGNode* node)
{
	return node->isAllocNode() || node->isCopyNode() || node->isOffsetNode();
}
} // anonymous namespace

// Attempts to update the memoization cache with a new store state at a program point.
// Returns true if the memo was updated (i.e., the state changed), and enqueues the point.
bool SemiSparsePropagator::enqueueIfMemoChange(const ProgramPoint& pp, const Store& store)
{
	if (memo.update(pp, store))
	{
		workList.enqueue(pp);
		return true;
	}
	return false;
}

// Handles propagation for top-level operations: Alloc, Copy, Offset.
// Since these do not alter the Store, we simply enqueue the successor without merging.
// Environment changes are applied directly via GlobalState.
void SemiSparsePropagator::propagateTopLevel(const EvalSuccessor& evalSucc)
{
	workList.enqueue(evalSucc.getProgramPoint());
	//errs() << "\tENQ(T) " << evalSucc.getProgramPoint() << "\n";
}

// Manages propagation for memory-affecting operations: Load, Store, Call, Ret.
// These require store merging; propagation occurs only if the outgoing store differs.
void SemiSparsePropagator::propagateMemLevel(const EvalSuccessor& evalSucc)
{
	const auto *node = evalSucc.getProgramPoint().getCFGNode();
	assert(!isTopLevel(node));
	assert(evalSucc.getStore() != nullptr);

	bool updated = enqueueIfMemoChange(evalSucc.getProgramPoint(), *evalSucc.getStore());
	//if (updated)
	//	errs() << "\tENQ(M) " << evalSucc.getProgramPoint() << "\n";
}

// Entry point for propagating analysis results across successors.
// Routes each successor based on its node type (top-level vs. memory-level).
void SemiSparsePropagator::propagate(const EvalResult& evalResult)
{
	for (const auto& succ : evalResult)
	{
		if (succ.isTopLevel())
			propagateTopLevel(succ);
		else
			propagateMemLevel(succ);
	}
}
} // namespace tpa

