// List of candidate paths for CA certificate bundles across Linux distributions
static const std::string ca_cert_candidates[] = {
    "/etc/ssl/certs/ca-certificates.crt",       // Arch, Debian, Ubuntu, Gentoo
    "/etc/pki/ca-trust/extracted/pem/tls-ca-bundle.pem",  // RHEL/CentOS 7+
    "/etc/pki/tls/certs/ca-bundle.crt",        // RHEL/CentOS 6
    "/etc/ssl/ca-bundle.pem",                  // OpenSUSE
    "/etc/ssl/cert.pem"                        // Alpine Linux
};

// Search through known CA cert file locations; return first existing one or empty string
std::string LocateCACertificate(DatabaseInstance &db) {
	for (const auto &candidate : ca_cert_candidates) {
		struct stat info;
		if (stat(candidate.c_str(), &info) == 0) {
			DUCKDB_LOG_DEBUG(db, "gcs.LocateCACertificate", "Found CA bundle at: %s", candidate.c_str());
			return candidate;
		}
	}
	return "";
}

// Core initialization logic shared between extension entry point and Load()
static void InitializeGCSExtension(ExtensionLoader &loader) {
	auto &db_instance = loader.GetDatabaseInstance();

	// Attempt to locate system CA certificate bundle
	std::string ca_bundle_path = LocateCACertificate(db_instance);

	// Register GCS-aware filesystem handler
	auto &fs = db_instance.GetFileSystem();
	fs.RegisterSubSystem(std::make_unique<GCSFileSystem>(ca_bundle_path));

	// Install secret handling functions
	CreateGCSSecretFunctions::Register(loader);

	// Configure optional runtime parameters via DBConfig
	auto &config = DBConfig::GetConfig(db_instance);
	GCSReadOptions default_opts;

	config.AddExtensionOption("gcs_enable_metadata_cache",
	                          "Enable caching of object metadata (size, mtime) to reduce API calls. "
	                          "Disable for debugging or frequently changing files.",
	                          LogicalType::BOOLEAN, Value::BOOLEAN(default_opts.enable_caches));
	config.AddExtensionOption("gcs_metadata_cache_ttl",
	                          "Cache validity period in seconds for metadata entries. Default: 300s.",
	                          LogicalType::INTEGER, Value::INTEGER(default_opts.metadata_cache_ttl_seconds));
	config.AddExtensionOption("gcs_list_cache_ttl",
	                          "TTL for directory listing cache used during glob operations. Default: 60s.",
	                          LogicalType::INTEGER, Value::INTEGER(default_opts.list_cache_ttl_seconds));
	config.AddExtensionOption("gcs_max_metadata_cache_entries",
	                          "Upper bound on number of cached metadata entries. LRU eviction applies.",
	                          LogicalType::UBIGINT, Value::UBIGINT(default_opts.max_metadata_cache_entries));
	config.AddExtensionOption("gcs_max_list_cache_entries",
	                          "Upper bound on number of cached list entries. LRU eviction applies.",
	                          LogicalType::UBIGINT, Value::UBIGINT(default_opts.max_list_cache_entries));
	config.AddExtensionOption("gcs_transfer_concurrency",
	                          "Number of parallel workers for data transfer. Default: 5.",
	                          LogicalType::INTEGER, Value::INTEGER(default_opts.transfer_concurrency));
#ifdef GCS_ENABLE_GRPC
	config.AddExtensionOption("gcs_enable_grpc",
	                          "Use gRPC transport layer instead of HTTP. May improve performance on GCP. Default: false.",
	                          LogicalType::BOOLEAN, Value::BOOLEAN(default_opts.enable_grpc));
#endif
}

// Public interface method required by DuckDB extension ABI
void GcsExtension::Load(ExtensionLoader &loader) {
	InitializeGCSExtension(loader);
}

// Extension name accessor
std::string GcsExtension::Name() {
	return "gcs";
}

} // namespace duckdb

// C-linkage entry point for dynamic loading
extern "C" {
DUCKDB_CPP_EXTENSION_ENTRY(gcs, loader) {
	duckdb::InitializeGCSExtension(loader);
}
