namespace hsa
{
namespace detail
{
// Renamed from get_hsa_api_table_impl()
auto&
fetch_api_table_storage()
{
    static std::atomic<HsaApiTable*> s_api_table_ptr{ nullptr };
    return s_api_table_ptr;
}

// Renamed from register_profiler_impl()
void
init_and_inject_hooks()
{
    // Create immutable base table
    static HsaApiTable const_base_table{};
    initialize_hsa_api_table(&const_base_table);

    // Atomically install base table first
    auto& stored_ptr = fetch_api_table_storage();
    stored_ptr.exchange(&const_base_table);

    // Prepare modifiable copy for profiler instrumentation
    static HsaApiTable instrumented_table{};
    copy_hsa_api_table(&instrumented_table, &const_base_table);

    void* instrumented_ptr = &instrumented_table;

    rocprofiler_register_library_indentifier_t lib_id{};
    auto status = rocprofiler_register_library_api_table(
        "hsa",
        &ROCPROFILER_REGISTER_IMPORT_FUNC(hsa),
        ROCP_REG_VERSION,
        &instrumented_ptr,
        1,
        &lib_id);

    if (status == 0)
    {
        printf("[%s] hsa identifier %lu\n", ROCP_REG_FILE_NAME, lib_id.handle);

        // Attempt to atomically replace with instrumented version
        HsaApiTable* expected = &const_base_table;
        if (!stored_ptr.compare_exchange_strong(expected, &instrumented_table))
        {
            std::cerr << "[ERROR] Expected const table during replacement, but found "
                         "something else. Internal inconsistency.\n";
            std::abort();
        }
    }
    else if (status != ROCP_REG_NO_TOOLS)
    {
        std::cerr << "Failed to register HSA library with rocprofiler-register: "
                  << rocprofiler_register_error_string(status) << "\n";
        std::exit(EXIT_FAILURE);
    }
}

// Renamed from register_profiler()
void
ensure_registration()
{
    static std::atomic<bool> is_initialized{ false };

    if (!is_initialized.load(std::memory_order_acquire))
    {
        using lock_type = std::recursive_mutex;
        using guard_type = std::unique_lock<lock_type>;

        static std::once_flag init_once{};
        static lock_type registration_mutex{};

        guard_type lk{ registration_mutex, std::defer_lock };

        // Avoid deadlock if same thread re-enters during registration
        if (lk.owns_lock()) return;

        lk.lock();

        std::call_once(init_once, init_and_inject_hooks);

        is_initialized.store(true, std::memory_order_release);
    }
}
}  // namespace detail

HsaApiTable*
get_current_hsa_table()
{
    detail::ensure_registration();
    return detail::fetch_api_table_storage().load(std::memory_order_relaxed);
}

void
hsa_init_wrapper()
{
    printf("[%s] %s\n", ROCP_REG_FILE_NAME, __FUNCTION__);
}
}  // namespace hsa

extern "C" {

void
hsa_init(void)
{
    hsa::get_current_hsa_table()->hsa_init_fn();
}

