using namespace llvm;

// Removes functions not marked for preservation based on Oracle criteria
static void filterAndRemoveUnusedFunctions(Oracle &O, ReducerWorkItem &WorkItem) {
  Module &Program = WorkItem.getModule();

  // Collect candidate functions for removal
  SmallPtrSet<Constant *, 8> CandidatesForRemoval;

  for (Function &F : Program.functions()) {
    // Skip intrinsics unless they're unused and have no external dependencies
    bool shouldConsiderRemoval = !F.isIntrinsic() || F.use_empty();

    // Additional checks: no alias or block address references, and Oracle doesn't require keeping
    if (shouldConsiderRemoval && !hasAliasOrBlockAddressUse(F) && !O.shouldKeep()) {
      CandidatesForRemoval.insert(&F);
    }
  }

  // Remove from used lists first to minimize lingering references
  removeFromUsedLists(Program, [&](Constant *C) -> bool {
    return CandidatesForRemoval.contains(C);
  });

  // Clear function bodies in batch before deletion
  for (Constant *Func : CandidatesForRemoval) {
    Func->dropAllReferences();
  }

  // Final cleanup: replace remaining uses and erase from module
  for (Constant *Func : CandidatesForRemoval) {
    // Substitute with default value for type
    Func->replaceAllUsesWith(getDefaultValue(Func->getType()));

    // Erase the function node from the module
    cast<Function>(Func)->eraseFromParent();
  }
}

void llvm::reduceFunctionsDeltaPass(TestRunner &Test) {
  runDeltaPass(Test, filterAndRemoveUnusedFunctions, "Filtering Functions");
}

#include "Alias/TPA/Context/Context.h"
#include "Alias/TPA/Context/ProgramPoint.h"
using namespace llvm;

namespace context {

// Adds a new context frame based on a ProgramPoint object.
// Delegates to the two-argument version after extracting components.
const Context *Context::pushContext(const ProgramPoint &pp) {
  return pushContext(pp.getContext(), pp.getInstruction());
}

// Creates and registers a new context frame using an instruction and its caller's context.
// Parameters:
//   ctx - the calling context (parent)
//   inst - the call instruction that triggers this context transition
// Returns: pointer to the canonical (interned) Context instance
const Context *Context::pushContext(const Context *ctx,
                                    const Instruction *inst) {
  // Construct a temporary context for lookup/insertion
  Context tempCtx(inst, ctx);

  // Insert into the global set; returns iterator to existing or newly inserted element
  auto [itr, inserted] = ctxSet.insert(tempCtx);

  // Return address of the interned context object
  return &(*itr);
}

// Removes the topmost context frame.
// Precondition: context stack is non-empty.
// Returns: the preceding (caller's) context
const Context *Context::popContext(const Context *ctx) {
  assert(nullptr != ctx && 0 != ctx->sz && "Attempted to pop from empty context");
  return ctx->predContext;
}

// Provides access to the unique global context used for static/global analysis.
// Ensures only one global context exists via interning.
const Context *Context::getGlobalContext() {
  Context globalCtx;
  auto [itr, _] = ctxSet.insert(globalCtx);
  return &(*itr);
}

// Exposes all contexts created so far for inspection or reporting.
// Builds and returns a vector of pointers to all interned contexts.
std::vector<const Context *> Context::getAllContexts() {
  std::vector<const Context *> result;
  result.reserve(ctxSet.size());

  for (auto const &item : ctxSet) {
    result.push_back(&item);
  }

  return result;
}

} // namespace context

#include <vector>
#include <algorithm>

class Solution {
public:
    int findContentChildren(std::vector<int>& g, std::vector<int>& s) {
        // Sort the greed factors and cookie sizes in ascending order
        std::sort(g.begin(), g.end());
        std::sort(s.begin(), s.end());

        int childrenIndex = 0;
        int cookiesIndex = 0;
        int satisfiedCount = 0;

        // Traverse both arrays to match children with cookies
        while (childrenIndex < g.size() && cookiesIndex < s.size()) {
            if (g[childrenIndex] <= s[cookiesIndex]) {
                // Current cookie can satisfy current child
                satisfiedCount++;
                childrenIndex++;
                cookiesIndex++;
            } else {
                // Current cookie is too small, try next larger cookie
                cookiesIndex++;
            }
        }

        return satisfiedCount;
    }
};

