    // Normalize line endings in input string according to specified type
    std::string FixLineEndings(const std::string& input, LineEnding mode) {
        if (mode == LineEnding::Mixed) {
            return input;
        }

        std::string output;
        output.reserve(input.size());

        auto iter = input.begin();
        while (iter != input.end()) {
            if (*iter == '\r') {
                ++iter;
                bool hasLF = (iter != input.end() && *iter == '\n');
                if (hasLF) {
                    ++iter;
                }

                if (static_cast<int>(mode) & static_cast<int>(LineEnding::CR)) {
                    output.push_back('\r');
                }
                if (static_cast<int>(mode) & static_cast<int>(LineEnding::LF)) {
                    output.push_back('\n');
                }
            }
            else if (*iter >= '\n' && *iter <= '\f') {
                if (static_cast<int>(mode) & static_cast<int>(LineEnding::CR)) {
                    output.push_back('\r');
                }
                if (static_cast<int>(mode) & static_cast<int>(LineEnding::LF)) {
                    output.push_back('\n');
                }
            }
            else {
                output.push_back(*iter);
            }

            ++iter;
        }

        return output;
    }

}

#include "comms/torchcomms/ncclx/TorchWorkNCCLX.hpp"

namespace torch::comms {

TorchWorkNCCLX::WorkStatus TorchWorkNCCLXQueue::garbageCollectLocked() {
  TorchWorkNCCLX::WorkStatus prev_status = TorchWorkNCCLX::WorkStatus::COMPLETED;

  // Iterate over all stream queues
  for (auto iter = stream_work_queues_.begin(); iter != stream_work_queues_.end(); ) {
    auto& queue_ref = iter->second;

    // Process each work item in this stream's queue
    while (!queue_ref.empty()) {
      auto current_work = queue_ref.front();
      auto current_status = current_work->checkStatus();

      prev_status = current_status;

      if (current_status == TorchWorkNCCLX::WorkStatus::COMPLETED) {
        queue_ref.pop();
      } else if (
          current_status == TorchWorkNCCLX::WorkStatus::TIMEDOUT ||
          current_status == TorchWorkNCCLX::WorkStatus::ERROR) {
        return current_status;
      } else {
        // Stop processing this stream’s queue: work is not yet ready
        break;
      }
    }

    // Remove empty stream queues from the map
    if (queue_ref.empty()) {
      iter = stream_work_queues_.erase(iter);
    } else {
      ++iter;
    }
  }

  return prev_status;
}

// Thread-safe wrapper using mutex lock
TorchWorkNCCLX::WorkStatus TorchWorkNCCLXQueue::garbageCollect() {
  std::lock_guard<std::mutex> guard(work_queues_mutex_);
  return garbageCollectLocked();
}

// Finalize: drain remaining work and clean up
TorchWorkNCCLX::WorkStatus TorchWorkNCCLXQueue::finalize() {
  std::lock_guard<std::mutex> guard(work_queues_mutex_);

  TorchWorkNCCLX::WorkStatus final_status = TorchWorkNCCLX::WorkStatus::COMPLETED;

  // Keep collecting until queue is empty or terminal status reached
  while (!stream_work_queues_.empty()) {
    final_status = garbageCollectLocked();
    if (final_status == TorchWorkNCCLX::WorkStatus::ERROR ||
        final_status == TorchWorkNCCLX::WorkStatus::TIMEDOUT ||
        final_status == TorchWorkNCCLX::WorkStatus::COMPLETED) {
      break;
    }
  }

  // Ensure no dangling references remain
  stream_work_queues_.clear();
  return final_status;
}

// Enqueue new work for a given CUDA stream
void TorchWorkNCCLXQueue::enqueueWork(
    c10::intrusive_ptr<TorchWorkNCCLX> work,
    cudaStream_t stream_id) {
  std::lock_guard<std::mutex> guard(work_queues_mutex_);
  stream_work_queues_[stream_id].push(std::move(work));
}

