// Memoization map to store previously queried matrix values
std::map<std::pair<int, int>, long long> memo_cache;
long long matrix_size;

// Query function with memoization to avoid redundant queries
long long fetch_value(int row, int col) {
    auto key = std::make_pair(row, col);
    if (memo_cache.find(key) != memo_cache.end()) {
        return memo_cache[key];
    }

    std::cout << "QUERY " << row << " " << col << std::endl;
    long long value;
    std::cin >> value;

    // Handle input errors gracefully
    if (std::cin.fail()) {
        exit(0);
    }

    memo_cache[key] = value;
    return value;
}

// Count how many elements in the matrix are <= threshold using staircase traversal
long long count_less_or_equal(long long threshold) {
    long long total = 0;
    int column = matrix_size;

    for (int row = 1; row <= matrix_size; ++row) {
        // Move left while current value exceeds threshold
        while (column >= 1 && fetch_value(row, column) > threshold) {
            --column;
        }
        total += column;
    }

    return total;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    long long target_rank;
    std::cin >> matrix_size >> target_rank;

    long long lower_bound, upper_bound;

    if (matrix_size > 0) {
        // Set initial search bounds using corner values
        lower_bound = fetch_value(1, 1);
        upper_bound = fetch_value(matrix_size, matrix_size);
    } else {
        // Handle edge case where matrix size is zero
        std::cout << "DONE " << 0 << std::endl;
        return 0;
    }

    long long result = upper_bound;

    // Binary search for the k-th smallest element
    while (lower_bound <= upper_bound) {
        long long mid_value = lower_bound + (upper_bound - lower_bound) / 2;

        if (count_less_or_equal(mid_value) >= target_rank) {
            result = mid_value;
            upper_bound = mid_value - 1;
        } else {
            lower_bound = mid_value + 1;
        }
    }

    std::cout << "DONE " << result << std::endl;
    return 0;
}

