#include <iostream>

// Helper function to send a move command and get the response
int execute_move(int color) {
    std::cout << "move " << color << std::endl;
    int response;
    std::cin >> response;
    return response;
}

// Helper function to request current distance to the target
int request_distance() {
    std::cout << "query" << std::endl;
    int distance;
    std::cin >> distance;
    return distance;
}

int main() {
    // Optimize I/O for interactive problems
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int starting_depth;
    std::cin >> starting_depth;
    int remaining_depth = starting_depth;

    // Immediate exit if already at the target
    if (remaining_depth == 0) {
        return 0;
    }

    int upward_color = -1;

    // --- Initial phase: determine first upward direction ---
    // Try colors 0 and 1; if both go deeper, color 2 must be upward
    for (int trial_color = 0; trial_color < 2; ++trial_color) {
        if (execute_move(trial_color) == 1) {
            return 0;
        }

        int new_depth = request_distance();
        if (new_depth < remaining_depth) {
            upward_color = trial_color;
            break;
        }

        // Return to original position
        execute_move(trial_color);
    }

    // If neither 0 nor 1 worked, then 2 is the upward direction
    if (upward_color == -1) {
        upward_color = 2;
        if (execute_move(upward_color) == 1) {
            return 0;
        }
    }

    remaining_depth--;
    int last_used_color = upward_color;

    // --- Main loop: continue until reaching the target ---
    while (remaining_depth > 0) {
        // Compute alternative colors using modular arithmetic
        int alt1 = (last_used_color + 1) % 3;
        int alt2 = (last_used_color + 2) % 3;

        // Test first alternative
        if (execute_move(alt1) == 1) {
            return 0;
        }

        int depth_after_alt1 = request_distance();
        if (depth_after_alt1 < remaining_depth) {
            upward_color = alt1;
        } else {
            // First alternative didn't help; revert and try second
            execute_move(alt1);
            upward_color = alt2;
            if (execute_move(upward_color) == 1) {
                return 0;
            }
        }

        remaining_depth--;
        last_used_color = upward_color;
    }

    return 0;
}

