#include <library/cpp/getopt/last_getopt.h>
#include <array>
#include <atomic>
#include <cstdio>
#include <thread>
#include <vector>
#include <sched.h>
#include <unistd.h>

// Global flag to signal worker threads to stop
static std::atomic<bool> gRunning{true};

// Target function for uprobe testing — must remain noinline and extern "C"
extern "C" __attribute__((noinline)) void target_func() {
    static volatile int sink = 0;
    (void)sink; // Prevent optimization of the function body
}

// Worker functions — each provides a unique call site for stack diversity
__attribute__((noinline)) void WorkerA() {
    while (gRunning.load(std::memory_order_relaxed)) {
        target_func();
    }
}

__attribute__((noinline)) void WorkerB() {
    while (gRunning.load(std::memory_order_relaxed)) {
        target_func();
    }
}

__attribute__((noinline)) void WorkerC() {
    while (gRunning.load(std::memory_order_relaxed)) {
        target_func();
    }
}

__attribute__((noinline)) void WorkerD() {
    while (gRunning.load(std::memory_order_relaxed)) {
        target_func();
    }
}

// Function pointer type and array of worker implementations
using TWorkerFn = void (*)();
static constexpr std::array<TWorkerFn, 4> Workers = {
    WorkerA,
    WorkerB,
    WorkerC,
    WorkerD,
};

// Bind current thread to specific CPU core
static void AffinityToCore(int coreId) {
    cpu_set_t mask;
    CPU_ZERO(&mask);
    CPU_SET(coreId, &mask);
    if (sched_setaffinity(0, sizeof(mask), &mask) != 0) {
        perror("sched_setaffinity");
        // Continue execution even on failure
    }
}

// Query number of online CPUs
static int GetOnlineCpuCount() {
    long count = sysconf(_SC_NPROCESSORS_ONLN);
    if (count <= 0) {
        throw std::runtime_error("Failed to determine number of online CPUs");
    }
    return static_cast<int>(count);
}

int main(int argc, const char* argv[]) {
    int runTimeSeconds = 30;
    int threadCount = 0;

    // Parse command-line options
    NLastGetopt::TOpts opts;
    opts.AddLongOption("duration", "How long to run (seconds)")
        .RequiredArgument("SECONDS")
        .DefaultValue("30")
        .StoreResult(&runTimeSeconds);

    opts.AddLongOption("threads", "Number of worker threads (0 = auto, one per CPU)")
        .RequiredArgument("N")
        .DefaultValue("0")
        .StoreResult(&threadCount);

    NLastGetopt::TOptsParseResult(&opts, argc, argv);

    const int numCores = GetOnlineCpuCount();
    const int actualThreads = (threadCount > 0) ? threadCount : numCores;

    std::vector<std::thread> workers;
    workers.reserve(actualThreads);

    for (int i = 0; i < actualThreads; ++i) {
        int assignedCore = i % numCores;
        int workerIdx = i % static_cast<int>(Workers.size());
        workers.emplace_back([assignedCore, workerIdx]() {
            AffinityToCore(assignedCore);
            Workers[workerIdx]();
        });
    }

    // Allow workload to run for specified time
    sleep(runTimeSeconds);

    // Signal termination and wait for all workers
    gRunning.store(false, std::memory_order_relaxed);
    for (auto& w : workers) {
        w.join();
    }

    return 0;
}

#include <QtTest/QtTest>
#include "PlainTestSuite.h"
#include "Logger.h"
#include "MemoryKey.h"
#include "BeginToExposePrivateMember.h"
#include "PathUndoRedoer.h"
#include "EndToExposePrivateMember.h"

class PathUndoRedoerTest : public PlainTestSuite {
  Q_OBJECT
 public:
 private slots:
  void test_undo_only() {
    PathUndoRedoer undoRedoManager;

    // Initial state checks
    QVERIFY(!undoRedoManager.undoPathAvailable());
    undoRedoManager("1");
    QVERIFY(!undoRedoManager.undoPathAvailable());
    QCOMPARE(undoRedoManager.undoStack.size(), 1);
    QCOMPARE(undoRedoManager.undoStack.top(), QString("1"));

    // Add second path entry
    undoRedoManager("2");
    QVERIFY(undoRedoManager.undoPathAvailable());
    QCOMPARE(undoRedoManager.undoStack.size(), 2);
    QCOMPARE(undoRedoManager.undoStack.top(), QString("2"));

    // Check redo state before any undo
    QVERIFY(!undoRedoManager.redoPathAvailable());
    QVERIFY(undoRedoManager.redoStack.isEmpty());
    QCOMPARE(undoRedoManager.onRedoPath(), QString()); // Attempt redo when none available

    // Verify state remains unchanged after failed redo
    QVERIFY(undoRedoManager.undoPathAvailable());
    QCOMPARE(undoRedoManager.undoStack.size(), 2);
    QCOMPARE(undoRedoManager.undoStack.top(), QString("2"));
    QVERIFY(!undoRedoManager.redoPathAvailable());
    QVERIFY(undoRedoManager.redoStack.isEmpty());

    // Perform first undo
    QCOMPARE(undoRedoManager.onUndoPath(), QString("1"));
    QVERIFY(!undoRedoManager.undoPathAvailable());
    QCOMPARE(undoRedoManager.undoStack.size(), 1);
    QCOMPARE(undoRedoManager.undoStack.top(), QString("1"));
    QVERIFY(undoRedoManager.redoPathAvailable());
    QCOMPARE(undoRedoManager.redoStack.size(), 1);
    QCOMPARE(undoRedoManager.redoStack.top(), QString("2"));

    // Redo operation
    undoRedoManager.onRedoPath();
    QVERIFY(undoRedoManager.undoPathAvailable());
    QCOMPARE(undoRedoManager.undoStack.size(), 2);
    QCOMPARE(undoRedoManager.undoStack.top(), QString("2"));
    QVERIFY(!undoRedoManager.redoPathAvailable());
    QVERIFY(undoRedoManager.redoStack.isEmpty());

    // Add more entries to test stack behavior
    undoRedoManager("3");
    QVERIFY(undoRedoManager.undoPathAvailable());
    QCOMPARE(undoRedoManager.undoStack.size(), 3);
    QCOMPARE(undoRedoManager.undoStack.top(), QString("3"));
    QVERIFY(!undoRedoManager.redoPathAvailable());
    QVERIFY(undoRedoManager.redoStack.isEmpty());

    undoRedoManager("4");
    QVERIFY(undoRedoManager.undoPathAvailable());
    QCOMPARE(undoRedoManager.undoStack.size(), 4);
    QCOMPARE(undoRedoManager.undoStack.top(), QString("4"));
    QVERIFY(!undoRedoManager.redoPathAvailable());
    QVERIFY(undoRedoManager.redoStack.isEmpty());

    // Multiple undos with redo tracking
    QCOMPARE(undoRedoManager.onUndoPath(), QString("3"));
    QVERIFY(undoRedoManager.undoPathAvailable());
    QCOMPARE(undoRedoManager.undoStack.size(), 3);
    QCOMPARE(undoRedoManager.undoStack.top(), QString("3"));
    QVERIFY(undoRedoManager.redoPathAvailable());
    QCOMPARE(undoRedoManager.redoStack.size(), 1);
    QCOMPARE(undoRedoManager.redoStack.top(), QString("4"));

    QCOMPARE(undoRedoManager.onUndoPath(), QString("2"));
    QVERIFY(undoRedoManager.undoPathAvailable());
    QCOMPARE(undoRedoManager.undoStack.size(), 2);
    QCOMPARE(undoRedoManager.undoStack.top(), QString("2"));
    QVERIFY(undoRedoManager.redoPathAvailable());
    QCOMPARE(undoRedoManager.redoStack.size(), 2);
    QCOMPARE(undoRedoManager.redoStack.top(), QString("3"));

    QCOMPARE(undoRedoManager.onUndoPath(), QString("1"));
    QVERIFY(!undoRedoManager.undoPathAvailable());
    QCOMPARE(undoRedoManager.undoStack.size(), 1);
    QCOMPARE(undoRedoManager.undoStack.top(), QString("1"));
    QVERIFY(undoRedoManager.redoPathAvailable());
    QCOMPARE(undoRedoManager.redoStack.size(), 3);
    QCOMPARE(undoRedoManager.redoStack.top(), QString("2"));

    // Final attempt to undo when none available
    QCOMPARE(undoRedoManager.onUndoPath(), QString());
    QVERIFY(!undoRedoManager.undoPathAvailable());
    QCOMPARE(undoRedoManager.undoStack.size(), 1);
    QCOMPARE(undoRedoManager.undoStack.top(), QString("1"));
    QVERIFY(undoRedoManager.redoPathAvailable());
    QCOMPARE(undoRedoManager.redoStack.size(), 3);
    QCOMPARE(undoRedoManager.redoStack.top(), QString("2"));
  }
};
