// Constructs a new byte array output stream with an initial buffer capacity of 32 bytes
ByteArrayOutputStream::ByteArrayOutputStream() {
    count = 0;
    buf   = byteArray(32);
}

// Constructs a new byte array output stream with the specified initial buffer size
ByteArrayOutputStream::ByteArrayOutputStream(unsigned int initialCapacity) {
    count = 0;
    buf   = byteArray(initialCapacity);
}

// Destructor: releases allocated memory for the internal buffer
ByteArrayOutputStream::~ByteArrayOutputStream() {
    if (buf.data != nullptr) {
        delete[] buf.data;
    }
}

// Writes a single byte to the stream; expands buffer if needed
void ByteArrayOutputStream::write(unsigned int value) {
    // Ensure sufficient space before writing
    if (count + 1 >= buf.length) {
        buf.resize(buf.length * 2);
    }
    buf[count] = static_cast<byte>(value);
    ++count;
}

// Writes all bytes from the given byte array to the stream
void ByteArrayOutputStream::write(byteArray source) {
    write(source, 0, source.length);
}

// Writes a subsequence of bytes from the source array to the stream
void ByteArrayOutputStream::write(
    byteArray    source,
    unsigned int startIndex,
    unsigned int length
) {
    assert(source.length >= startIndex + length);

    // Expand buffer if necessary to accommodate new data
    if (count + length >= buf.length) {
        unsigned int requiredSize = std::max(count + length + 1, buf.length * 2);
        buf.resize(requiredSize);
    }

    // Copy data from source to internal buffer
    XMemCpy(&buf[count], &source[startIndex], length);
    count += length;
}

// No-op implementation: closing this stream has no effect
void ByteArrayOutputStream::close() {}

// Returns a copy of the current contents of the stream as a new byte array
byteArray ByteArrayOutputStream::toByteArray() const {
    byteArray result(count);
    if (count > 0) {
        memcpy(result.data, buf.data, count);
    }
    return result;
}

#include <sm/vvec>
