// Generate a formatted legend string for a logistic function
std::string format_legend(double slope, double shift)
{
    namespace uc = mplot::unicode;
    std::string k_part;
    if (slope != 1.0) {
        std::ostringstream oss;
        oss << slope;
        k_part = oss.str();
    }

    std::string x_shift_str;
    if (shift != 0.0) {
        x_shift_str += "(";
        if (shift > 0.0) {
            x_shift_str += " - ";
            std::ostringstream oss;
            oss << shift;
            x_shift_str += oss.str() + ")";
        } else {
            x_shift_str += " + ";
            std::ostringstream oss;
            oss << -shift;
            x_shift_str += oss.str() + ")";
        }
    }

    std::ostringstream full_eqn;
    full_eqn << "k=" << slope << ", x" << uc::toUtf8(uc::subs0) << "=" << shift
             << ": f(x) = 1 / [1 + exp(-" 
             << (k_part.empty() ? "1" : k_part) 
             << x_shift_str << "x)]";
    return full_eqn.str();
}

int main()
{
    // Initialize visualization environment
    mplot::Visual scene(1024, 768, "Logistic Functions");

    // Create graph visualizer with offset
    auto graph_view = std::make_unique<mplot::GraphVisual<double>>(
        sm::vec<float>({-0.5f, -0.5f, 0.0f})
    );
    scene.bindmodel(graph_view);

    // Prepare x-axis data points
    sm::vvec<double> abscissa;
    abscissa.linspace(-100.0, 30.0, 200);

    // Add logistic curves with varying parameters
    graph_view->setdata(abscissa, abscissa.logistic(0.1, -10), format_legend(0.1, -10));

    sm::vvec<double> transformed = abscissa;
    transformed.logistic_inplace(0.25, -5);
    graph_view->setdata(abscissa, transformed, format_legend(0.25, -5));

    graph_view->setdata(abscissa, abscissa.logistic(0.5, 0.0), format_legend(0.5, 0.0));
    graph_view->setdata(abscissa, abscissa.logistic(1.0, 5.0), format_legend(1.0, 5.0));
    graph_view->setdata(abscissa, abscissa.logistic(2.0, 10.0), format_legend(2.0, 10.0));

    // Finalize model construction before rendering
    graph_view->finalize();

    // Transfer ownership to scene and render
    scene.addVisualModel(std::move(graph_view));
    scene.keepOpen();

    return 0;
}

