#include <iostream>
#include <vector>
#include <string>
#include <numeric>
#include <algorithm>

// Function to output a query for the given set S
void send_query(const std::vector<int>& s) {
    std::cout << "? " << s.size();
    for (int val : s) {
        std::cout << " " << val;
    }
    std::cout << std::endl;
}

// Function to output a guessed number
void output_guess(int guess) {
    std::cout << "! " << guess << std::endl;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::cin >> n;

    // Two candidate sets: one for when last answer was YES, one for NO
    std::vector<int> yes_set(n);
    std::iota(yes_set.begin(), yes_set.end(), 1);
    std::vector<int> no_set;

    // Continue until only 2 or fewer candidates remain
    while (yes_set.size() + no_set.size() > 2) {
        // Determine split points for both sets
        size_t half_yes = yes_set.size() / 2;
        size_t half_no = no_set.size() / 2;

        std::vector<int> query_list;

        // Build query set from first halves of both sets
        if (half_yes > 0) {
            query_list.insert(query_list.end(), 
                             yes_set.begin(), yes_set.begin() + half_yes);
        }
        if (half_no > 0) {
            query_list.insert(query_list.end(), 
                             no_set.begin(), no_set.begin() + half_no);
        }

        send_query(query_list);

        std::string answer;
        std::cin >> answer;

        // Split original sets into halves
        std::vector<int> yes_first(yes_set.begin(), yes_set.begin() + half_yes);
        std::vector<int> yes_second(yes_set.begin() + half_yes, yes_set.end());
        std::vector<int> no_first(no_set.begin(), no_set.begin() + half_no);
        std::vector<int> no_second(no_set.begin() + half_no, no_set.end());

        std::vector<int> next_yes, next_no;

        if (answer == "YES") {
            // If YES: new yes_set = first halves of both old sets
            next_yes.reserve(yes_first.size() + no_first.size());
            next_yes.insert(next_yes.end(), yes_first.begin(), yes_first.end());
            next_yes.insert(next_yes.end(), no_first.begin(), no_first.end());

            // New no_set = second half of old yes_set
            next_no = std::move(yes_second);
        } else { // NO
            // If NO: new yes_set = second halves of both old sets
            next_yes.reserve(yes_second.size() + no_second.size());
            next_yes.insert(next_yes.end(), yes_second.begin(), yes_second.end());
            next_yes.insert(next_yes.end(), no_second.begin(), no_second.end());

            // New no_set = first half of old yes_set
            next_no = std::move(yes_first);
        }

        yes_set = std::move(next_yes);
        no_set = std::move(next_no);
    }

    // Collect remaining candidates and test them
    std::vector<int> candidates;
    candidates.insert(candidates.end(), yes_set.begin(), yes_set.end());
    candidates.insert(candidates.end(), no_set.begin(), no_set.end());

    for (int num : candidates) {
        output_guess(num);
        std::string feedback;
        std::cin >> feedback;
        if (feedback == ":)") {
            return 0;
        }
    }

    return 0;
}

#include "llvm/Transforms/IPO/ElimAvailExtern.h"
#include "llvm/ADT/STLExtras.h"
#include "llvm/ADT/Statistic.h"
#include "llvm/IR/Constant.h"
#include "llvm/IR/DebugInfoMetadata.h"
#include "llvm/IR/Function.h"
#include "llvm/IR/GlobalValue.h"
#include "llvm/IR/GlobalVariable.h"
#include "llvm/IR/MDBuilder.h"
#include "llvm/IR/Module.h"
#include "llvm/Support/CommandLine.h"
#include "llvm/Transforms/IPO.h"
#include "llvm/Transforms/Utils/GlobalStatus.h"
#include "llvm/Transforms/Utils/ModuleUtils.h"

using namespace llvm;

#define DEBUG_TYPE "elim-avail-extern"

// Command-line flag: convert available_externally to internal linkage with unique name
static cl::opt<bool> ConvertToInternal(
    "avail-extern-to-local", cl::Hidden,
    cl::desc("Transform available_externally definitions into local symbols "
             "with unique names to prevent collisions across modules."));

STATISTIC(FuncsRemoved, "Count of eliminated function bodies");
STATISTIC(FuncsCloned,   "Count of functions duplicated as locals");
STATISTIC(GlobalsRemoved, "Count of global variables stripped");

// Helper: erase body of function and increment removal counter
void purgeFunction(Function &func) {
  func.dropAllReferences(); // ensures no dangling uses before deletion
  ++FuncsRemoved;
}

// Clone an available_externally function locally, preserving original as external declaration
// Direct call sites use the clone; other uses (e.g., address-taken) refer to original
static void duplicateAsLocal(Module &mod, Function &func) {
  assert(func.hasAvailableExternallyLinkage());
  assert(!func.isDeclaration());

  // If no direct call uses exist, just delete instead of cloning
  bool hasDirectCall = false;
  for (auto &U : func.uses()) {
    if (isa<CallBase>(U.getUser())) {
      hasDirectCall = true;
      break;
    }
  }
  if (!hasDirectCall) {
    purgeFunction(func);
    return;
  }

  std::string oldName = func.getName().str();
  std::string uniqSuffix = "__uniq" + getUniqueModuleId(&mod);
  std::string newName = oldName + uniqSuffix;

  func.setName(newName);

  // Update subprogram metadata if present
  if (DISubprogram *SP = func.getSubprogram()) {
    MDString *newMD = MDString::get(mod.getContext(), newName);
    SP->replaceLinkageName(newMD);
  }

  func.setLinkage(GlobalValue::InternalLinkage);

  // Create external declaration for non-call uses (e.g., address-of)
  FunctionType *FTy = func.getFunctionType();
  unsigned AS = func.getAddressSpace();
  Function *extDecl = Function::Create(FTy, GlobalValue::ExternalLinkage, AS, oldName, &mod);

  // Redirect only non-call uses to the external declaration
  for (Use &U : make_early_inc_range(func.uses())) {
    if (!isa<CallBase>(U.getUser()))
      U.set(extDecl);
  }

  ++FuncsCloned;
}

// Core elimination logic: strip initializers from globals and bodies from functions
static bool pruneAvailableExternally(Module &mod) {
  bool modified = false;

  // Step 1: Process global variables with available_externally linkage
  for (GlobalVariable &gv : mod.globals()) {
    if (!gv.hasAvailableExternallyLinkage())
      continue;

    if (gv.hasInitializer()) {
      Constant *init = gv.getInitializer();
      gv.setInitializer(nullptr);
      if (isSafeToDestroyConstant(init))
        init->destroyConstant();
    }

    gv.removeDeadConstantUsers();
    gv.setLinkage(GlobalValue::ExternalLinkage);
    ++GlobalsRemoved;
    modified = true;
  }

  // Step 2: Process functions with available_externally linkage
  for (Function &f : make_early_inc_range(mod)) {
    if (f.isDeclaration() || !f.hasAvailableExternallyLinkage())
      continue;

    if (ConvertToInternal)
      duplicateAsLocal(mod, f);
    else
      purgeFunction(f);

    f.removeDeadConstantUsers();
    modified = true;
  }

  return modified;
}

// Pass entry point: run elimination on module
PreservedAnalyses
EliminateAvailableExternallyPass::run(Module &M, ModuleAnalysisManager &) {
  if (!pruneAvailableExternally(M))
    return PreservedAnalyses::all();

  return PreservedAnalyses::none();
}

#include <iostream>
#include <vector>
#include <madvoro/Voronoi3D.hpp>

int main(int argc, char *argv[]) {
    // Define bounding box corners
    MadVoro::Vector3D lowerLeft(-10.0, -10.0, -10.0);
    MadVoro::Vector3D upperRight(10.0, 10.0, 10.0);

    // Initialize Voronoi diagram with the specified bounds
    MadVoro::Voronoi3D voronoi(lowerLeft, upperRight);

    // Input point set for generating the Voronoi diagram
    std::vector<MadVoro::Vector3D> sites = {
        { -0.115, 4.484, 0.688 },
        { -6.121, 6.335, -9.093 },
        { -5.529, -7.464, 2.459 },
        { -3.448, -7.794, -6.939 },
        { -3.231, 8.213, -7.829 },
        { 5.204, 9.943, 6.175 },
        { -7.018, 7.155, -0.226 },
        { 0.567, 2.263, -0.962 },
        { 9.998, -3.030, 7.772 },
        { 3.811, 6.672, -8.231 },
        { 4.252, -8.460, -2.693 },
        { 5.184, 0.449, -1.665 },
        { -3.333, 3.909, 5.544 },
        { 3.495, -0.703, 5.494 },
        { -4.844, 4.808, -4.166 },
        { 3.016, -0.006, -1.534 },
        { -3.990, -1.579, 0.691 },
        { 6.928, 1.059, 6.088 },
        { 9.439, -6.873, 5.741 },
        { 6.238, -6.793, -4.822 }
    };

    // Retrieve and display bounding box after construction
    auto bounds = voronoi.GetBoxCoordinates();

    // Construct the Voronoi diagram using the provided points
    voronoi.Build(sites);

    std::cout << "Lower-left corner: " << bounds.first 
              << ", Upper-right corner: " << bounds.second << std::endl;
    std::cout << "Total number of sites (cells): " << voronoi.GetPointNo() << std::endl;

    // Analyze cell for a specific site (index 3)
    size_t targetSiteIdx = 3;
    const MadVoro::face_vec& faceIndices = voronoi.GetCellFaces(targetSiteIdx);

    std::cout << "Site #" << targetSiteIdx 
              << " at position " << voronoi.GetMeshPoint(targetSiteIdx) 
              << " has " << faceIndices.size() << " faces." << std::endl;
    std::cout << "Hence, it has " << faceIndices.size() << " neighboring cells." << std::endl;

    // Get all face vertex coordinates
    std::vector<MadVoro::Vector3D> allFaceVertices = voronoi.GetFacePoints();

    std::cout << "\nDetailed face information:" << std::endl;
    for (size_t fIdx : faceIndices) {
        // Compute center of mass for this face
        MadVoro::Vector3D faceCM = voronoi.FaceCM(fIdx);

        // Get neighbor pair for this face
        std::pair<size_t, size_t> adjacentSites = voronoi.GetFaceNeighbors(fIdx);

        // Determine which neighbor is not the current site
        size_t otherSite = (adjacentSites.first == targetSiteIdx) ? adjacentSites.second : adjacentSites.first;

        std::cout << "Face " << fIdx << ": neighbor is site #" << otherSite 
                  << " (" << voronoi.GetMeshPoint(otherSite) << ")" << std::endl;

        // Output vertices belonging to this face
        const std::vector<size_t>& vertexList = voronoi.GetPointsInFace(fIdx);
        std::cout << "  Vertices: ";
        for (size_t vIdx : vertexList) {
            std::cout << allFaceVertices[vIdx] << ", ";
        }
        std::cout << "\b\b" << std::endl;
    }

    return 0;
}

