#include <climits>

class Solution {
public:
    long long minimumRemoval(std::vector<int>& beans) {
        std::sort(beans.begin(), beans.end());

        long long totalSum = 0;
        for (int bean : beans) {
            totalSum += bean;
        }

        long long minRemovals = LLONG_MAX;
        int size = beans.size();

        for (int index = 0; index < size; ++index) {
            long long remainingBeans = static_cast<long long>(beans[index]) * (size - index);
            long long removalsNeeded = totalSum - remainingBeans;
            if (removalsNeeded < minRemovals) {
                minRemovals = removalsNeeded;
            }
        }

        return minRemovals;
    }
};

class Solution {
public:
    int pivotIndex(vector<int>& nums) {
        int n = nums.size();
        int rightSum = 0;
        for (int x : nums) {
            rightSum += x;
        }

        int leftSum = 0;
        for (int i = 0; i < n; ++i) {
            rightSum -= nums[i];
            if (leftSum == rightSum) {
                return i;
            }
            leftSum += nums[i];
        }
        return -1;
    }
};

