#include <iostream>
#include <list>

void process() {
    int n;
    std::cin >> n;
    std::list<int> pens;

    // Initialize the list with pen indices from 0 to n-1
    for (int idx = 0; idx < n; ++idx) {
        pens.push_back(idx);
    }

    // Continue until only two pens remain
    while (pens.size() > 2) {
        // Extract three pens from the front of the list
        int a = pens.front(); pens.pop_front();
        int b = pens.front(); pens.pop_front();
        int c = pens.front(); pens.pop_front();

        // Test pens 'a' and 'b'
        std::cout << "0 " << a << std::endl;
        int result_a;
        std::cin >> result_a;

        std::cout << "0 " << b << std::endl;
        int result_b;
        std::cin >> result_b;

        // Determine which pens survive based on test results
        if (result_a == 1 && result_b == 1) {
            // Both have ink: keep a and b, discard c
            pens.push_back(a);
            pens.push_back(b);
        } else if (result_a == 1 && result_b == 0) {
            // Only a has ink: keep a and c, discard b
            pens.push_back(a);
            pens.push_back(c);
        } else if (result_a == 0 && result_b == 1) {
            // Only b has ink: keep b and c, discard a
            pens.push_back(b);
            pens.push_back(c);
        } else {
            // Neither a nor b has ink: keep only c
            pens.push_back(c);
        }
    }

    // Output the final two surviving pens
    int first = pens.front(); pens.pop_front();
    int second = pens.front(); pens.pop_front();
    std::cout << "1 " << first << " " << second << std::endl;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int test_cases;
    std::cin >> test_cases;
    while (test_cases--) {
        process();
    }

    return 0;
}

