std::string LogicalPlanUtil::encodeJoin(LogicalPlan& plan) {
    return encode(plan.getLastOperator().get());
}

std::string LogicalPlanUtil::encode(LogicalOperator* op) {
    std::string buffer;
    buildEncoding(op, buffer);
    return buffer;
}

void LogicalPlanUtil::buildEncoding(LogicalOperator* node, std::string& output) {
    auto type = node->getOperatorType();

    if (type == LogicalOperatorType::CROSS_PRODUCT) {
        appendCrossProductMarker(output);
        for (size_t idx = 0; idx < node->getNumChildren(); ++idx) {
            output += "[";
            buildEncoding(node->getChild(idx).get(), output);
            output += "]";
        }
    } else if (type == LogicalOperatorType::INTERSECT) {
        appendIntersectMarker(node, output);
        for (size_t idx = 0; idx < node->getNumChildren(); ++idx) {
            output += "[";
            buildEncoding(node->getChild(idx).get(), output);
            output += "]";
        }
    } else if (type == LogicalOperatorType::HASH_JOIN) {
        appendHashJoinMarker(node, output);
        output += "[";
        buildEncoding(node->getChild(0).get(), output);
        output += "][";
        buildEncoding(node->getChild(1).get(), output);
        output += "]";
    } else if (type == LogicalOperatorType::EXTEND) {
        appendExtendMarker(node, output);
        buildEncoding(node->getChild(0).get(), output);
    } else if (type == LogicalOperatorType::SCAN_NODE_TABLE) {
        appendScanNodeTableMarker(node, output);
    } else if (type == LogicalOperatorType::FILTER) {
        appendFilterMarker(output);
        buildEncoding(node->getChild(0).get(), output);
    } else {
        // Fallback: recursively process all children
        for (size_t childIdx = 0; childIdx < node->getNumChildren(); ++childIdx) {
            buildEncoding(node->getChild(childIdx).get(), output);
        }
    }
}

void LogicalPlanUtil::appendCrossProductMarker(std::string& out) {
    out += "CP()";
}

void LogicalPlanUtil::appendIntersectMarker(LogicalOperator* baseOp, std::string& out) {
    auto& intersectOp = baseOp->constCast<LogicalIntersect>();
    out += "I(" + intersectOp.getIntersectNodeID()->toString() + ")";
}

void LogicalPlanUtil::appendHashJoinMarker(LogicalOperator* baseOp, std::string& out) {
    auto& joinOp = baseOp->constCast<LogicalHashJoin>();
    out += "HJ(" + joinOp.getExpressionsForPrinting() + ")";
}

void LogicalPlanUtil::appendExtendMarker(LogicalOperator* baseOp, std::string& out) {
    auto& extendOp = baseOp->constCast<LogicalExtend>();
    out += "E(" + extendOp.getNbrNode()->toString() + ")";
}

void LogicalPlanUtil::appendScanNodeTableMarker(LogicalOperator* baseOp, std::string& out) {
    auto& scanOp = baseOp->constCast<LogicalScanNodeTable>();
    if (scanOp.getScanType() == LogicalScanNodeTableType::PRIMARY_KEY_SCAN) {
        out += "IndexScan";
    } else {
        out += "S";
    }
    out += "(" + scanOp.getNodeID()->constCast<PropertyExpression>().getRawVariableName() + ")";
}

void LogicalPlanUtil::appendFilterMarker(std::string& out) {
    out += "Filter()";
}

