#include <iostream>
#include <vector>
#include <numeric>
#include <random>
#include <algorithm>

// Function to perform a query operation
int performQuery(int value) {
    std::cout << "? " << value << std::endl;
    int result;
    std::cin >> result;
    if (result == -1) {
        exit(0); // Handle error condition as per problem specification
    }
    return result;
}

// Function to output the final answer pair
void reportAnswer(int first, int second) {
    std::cout << "! " << first << " " << second << std::endl;
}

// Recursive function to solve the pairing problem using divide-and-conquer
void processSlices(std::vector<int>& sliceList) {
    // Base cases: empty list or only two elements
    if (sliceList.empty()) {
        return;
    }
    if (sliceList.size() == 2) {
        reportAnswer(sliceList[0], sliceList[1]);
        return;
    }

    // Select pivot from the end of the list (shuffled input ensures randomness)
    int pivot = sliceList.back();
    sliceList.pop_back();

    // Query with the pivot element
    performQuery(pivot);

    // Initialize groups: one containing the pivot and its matches, another for others
    std::vector<int> sameGroup;
    sameGroup.push_back(pivot);
    std::vector<int> diffGroup;

    // Track current number of distinct types in the device
    int distinctCount = 1;

    // Partition remaining slices based on behavior when added to the device
    for (int item : sliceList) {
        int newDistinctCount = performQuery(item);

        if (newDistinctCount == distinctCount) {
            // Adding this item did not increase distinct count → its pair is already present
            sameGroup.push_back(item);
        } else {
            // Adding this item increased distinct count → its pair is not present yet
            diffGroup.push_back(item);
            distinctCount = newDistinctCount; // Update count for next iterations
        }
    }

    // Clear device by removing all items in sameGroup (toggle them out)
    for (int item : sameGroup) {
        performQuery(item);
    }

    // Recursively process both partitions
    processSlices(sameGroup);
    processSlices(diffGroup);
}

int main() {
    // Optimize I/O operations
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::cin >> n;
    if (n == 0) {
        return 0;
    }

    // Create initial list [1, 2, ..., 2n]
    std::vector<int> allItems(2 * n);
    std::iota(allItems.begin(), allItems.end(), 1);

    // Shuffle to randomize order and avoid worst-case pivot selection
    std::random_device rd;
    std::mt19937 engine(rd());
    std::shuffle(allItems.begin(), allItems.end(), engine);

    // Start processing
    processSlices(allItems);

    return 0;
}

