// Determine and print the size of a binary file using seek operations
void demoFileSize() {
    // Open the file in binary mode for precise byte-level measurement
    std::ifstream inputFile("image.png", std::ios::binary);
    if (!inputFile) return;

    // Reposition the get pointer to the end of the file
    inputFile.seekg(0, std::ios::end);

    // Retrieve the current position, which corresponds to the file size in bytes
    std::streampos fileSize = inputFile.tellg();

    // Output the computed file size
    std::cout << "File size: " << fileSize << " bytes" << std::endl;

    // Reset the file pointer to the beginning for potential subsequent reads
    inputFile.seekg(0, std::ios::beg);
}

