class Solution {
public:
    void merge(std::vector<int>& nums1, int m, std::vector<int>& nums2, int n) {
        // Copy elements from nums2 to the end of valid elements in nums1
        for (int i = 0; i < n; ++i) {
            nums1[m + i] = nums2[i];
        }

        // Sort the entire nums1 array to get merged sorted result
        std::sort(nums1.begin(), nums1.begin() + m + n);
    }
};

