// Custom buffer class that holds time data as a shared resource
class time_buffer
{
public:
  explicit time_buffer(const std::string& time_str)
    : stored_data_(std::make_shared<std::vector<char>>(time_str.begin(), time_str.end())),
      buffer_view_(asio::buffer(*stored_data_))
  {
  }

  // Support for Asio's buffer sequence interface
  using const_buffer_type = asio::const_buffer;
  using iterator_type = const const_buffer_type*;

  iterator_type begin() const { return &buffer_view_; }
  iterator_type end() const { return &buffer_view_ + 1; }

private:
  std::shared_ptr<std::vector<char>> stored_data_;
  asio::const_buffer buffer_view_;
};

// Handles individual client connections
class connection_handler
  : public std::enable_shared_from_this<connection_handler>
{
public:
  connection_handler(tcp::socket sock)
    : client_socket_(std::move(sock))
  {
  }

  void initiate()
  {
    send_time_info();
  }

private:
  void send_time_info()
  {
    std::time_t current_time = std::time(nullptr);
    std::string time_string = std::ctime(&current_time);

    time_buffer buffer(time_string);
    auto self(shared_from_this());

    asio::async_write(client_socket_, buffer,
        [this, self](const std::error_code& error, std::size_t bytes_transferred)
        {
          // Connection handling logic could be extended here
        });
  }

  tcp::socket client_socket_;
};

// Main server class managing incoming connections
class time_server
{
public:
  time_server(asio::io_context& context, unsigned short port_number)
    : listener_(context, tcp::endpoint(tcp::v4(), port_number))
  {
    await_new_connection();
  }

private:
  void await_new_connection()
  {
    listener_.async_accept(
        [this](const std::error_code& error, tcp::socket new_socket)
        {
          if (!error)
          {
            std::make_shared<connection_handler>(std::move(new_socket))->initiate();
          }
          await_new_connection();
        });
  }

  tcp::acceptor listener_;
};

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 2)
    {
      std::cerr << "Usage: time_server <port>\n";
      return 1;
    }

    asio::io_context io_context;
    time_server server(io_context, static_cast<unsigned short>(std::atoi(argv[1])));
    io_context.run();
  }
  catch (const std::exception& exception)
  {
    std::cerr << "Runtime error: " << exception.what() << "\n";
    return 1;
  }

  return 0;
}

