LogToFile::LogToFile(std::string const& filename, int flags)
    : Logger::Listener(flags),
      mFilename(filename)
{
    // Attempt to open and immediately close the file to clear its contents
    std::ofstream tempStream(filename);
    if (tempStream.is_open())
    {
        tempStream.close();
    }
    else
    {
        // If opening fails, invalidate the filename to prevent future attempts
        mFilename.clear();
    }
}

void LogToFile::Report(std::string const& message)
{
    if (!mFilename.empty())
    {
        // Open file in append mode
        std::ofstream logStream(mFilename, std::ios_base::app);
        if (logStream.is_open())
        {
            logStream << message;
            logStream.close();
        }
        else
        {
            // On failure, reset filename to avoid repeated failed attempts
            mFilename.clear();
        }
    }
}

