extern "C" {
// Destructor function pointer type definition
typedef void (*destructor_func)(void *);

// Weak implementation of __cxa_thread_atexit_impl for compatibility with older glibc versions.
// It's marked as weak to allow newer systems' libc implementations to override it.
// Since the engine typically terminates when threads end, thread-local storage cleanup
// isn't strictly required at thread exit.
[[gnu::weak]] int __cxa_thread_atexit_impl(destructor_func func, void *obj,
                                           void *dso_symbol) {
    // Return success (0) without performing any action
    return 0;
}

// Implementation of getrandom syscall wrapper for systems lacking full glibc support.
// This function provides entropy by invoking the kernel's getrandom(2) system call.
ssize_t getrandom(void *buf, size_t len, unsigned int opts) {
    return syscall(SYS_getrandom, buf, len, opts);
}
}

#include "FiberPool.hpp"
