namespace YimMenu
{
    void FiberPool::InitializeImplementation(int fiber_count)
    {
        for (std::size_t index = 0; index < static_cast<std::size_t>(fiber_count); ++index)
        {
            ScriptMgr::RegisterScript(std::make_unique<Script>(&ScriptEntryFunction));
        }
    }

    void FiberPool::CleanupImplementation()
    {
        std::scoped_lock guard(m_Mutex);
        while (!m_Jobs.empty())
            m_Jobs.pop();
    }

    void FiberPool::EnqueueTask(std::function<void()> task)
    {
        std::scoped_lock guard(m_Mutex);
        m_Jobs.push(std::move(task));
    }

    void FiberPool::ProcessNextJob()
    {
        std::unique_lock guard(m_Mutex);
        if (!m_Jobs.empty())
        {
            auto current_task = std::move(m_Jobs.top());
            m_Jobs.pop();
            guard.unlock();
            std::invoke(std::move(current_task));
        }
    }

    void FiberPool::ScriptEntryFunction()
    {
        while (g_Running)
        {
            FiberPool::GetReference().ProcessNextJob();
            ScriptMgr::PauseExecution();
        }
    }
}

