class TMultiHashTest : public TTestBase {
    UNIT_TEST_SUITE(TMultiHashTest);
    UNIT_TEST(TestStrInt)
    UNIT_TEST(TestIntStr)
    UNIT_TEST(TestSimpleCollision)
    UNIT_TEST(TestTypes)
    UNIT_TEST_SUITE_END();

private:
    inline void TestStrInt() {
        // Verify hash consistency for string followed by int
        const TString key = "1234567";
        const int value = 123;
        UNIT_ASSERT_EQUAL(MultiHash(key, static_cast<int>(value)), static_cast<size_t>(ULL(17038203285960021630)));
    }

    inline void TestIntStr() {
        // Verify hash consistency for int followed by string
        const int value = 123;
        const TString key = "1234567";
        UNIT_ASSERT_EQUAL(MultiHash(static_cast<int>(value), key), static_cast<size_t>(ULL(9973288649881090712)));
    }

    inline void TestSimpleCollision() {
        // Ensure different inputs produce different hashes
        UNIT_ASSERT_UNEQUAL(MultiHash(1, 1, 0), MultiHash(2, 2, 0));
    }

    inline void TestTypes() {
        // Verify type-agnostic hashing for numeric types
        const TString prefix = "aaa";
        const i64 val64 = 123;
        const i32 val32 = 123;
        const ui64 uval64 = 123;
        const ui32 uval32 = 123;

        UNIT_ASSERT_EQUAL(MultiHash(prefix, static_cast<ui64>(val64)), MultiHash(prefix, 123));
        UNIT_ASSERT_EQUAL(MultiHash(prefix, static_cast<i64>(val64)), MultiHash(prefix, 123));
        UNIT_ASSERT_EQUAL(MultiHash(prefix, static_cast<i32>(val32)), MultiHash(prefix, 123));
        UNIT_ASSERT_EQUAL(MultiHash(prefix, static_cast<ui32>(uval32)), MultiHash(prefix, 123));

        // Also test negative values
        const i64 neg64 = -123;
        const i32 neg32 = -123;
        UNIT_ASSERT_EQUAL(MultiHash(prefix, static_cast<i64>(neg64)), MultiHash(prefix, -123));
        UNIT_ASSERT_EQUAL(MultiHash(prefix, static_cast<i32>(neg32)), MultiHash(prefix, -123));
    }
};

