// Global state objects
std::unique_ptr<PinocchioInterface> robotInterface;
std::shared_ptr<PinocchioGeometryInterface> geometryInterface;
std::unique_ptr<GeometryInterfaceVisualization> visualizer;
sensor_msgs::JointState lastJointState;
std::unique_ptr<ros::Publisher> visualizationPublisher;

void handleJointStateUpdate(const sensor_msgs::JointStateConstPtr& jointStateMsg) {
    // Skip if no change in joint positions
    if (lastJointState.position == jointStateMsg->position) {
        return;
    }

    // Update stored state
    lastJointState.position = jointStateMsg->position;

    // Prepare configuration vector: first 3 entries are fixed (base), next 6 from joints
    Eigen::VectorXd jointPositions(9);
    jointPositions.setZero(); // Initialize all to zero

    // Helper lambda to copy relevant joint values
    auto copyJointValues = [&](const std::vector<double>& src, Eigen::Ref<Eigen::VectorXd> dst, size_t startIdx) {
        for (size_t i = 0; i < src.size() && (startIdx + i) < dst.size(); ++i) {
            dst(startIdx + i) = src[i];
        }
    };

    copyJointValues(lastJointState.position, jointPositions, 3);

    // Publish updated distance information
    visualizer->publishDistances(jointPositions);
}

int main(int argc, char** argv) {
    // Initialize ROS node
    ros::init(argc, argv, "distance_visualization");
    ros::NodeHandle nh;

    // Load required file paths
    std::string urdfFilePath, taskConfigPath;
    nh.getParam("/urdfFile", urdfFilePath);
    nh.getParam("/taskFile", taskConfigPath);

    // Parse task configuration using property tree
    boost::property_tree::ptree configTree;
    boost::property_tree::read_info(taskConfigPath, configTree);

    // Extract model type
    ManipulatorModelType robotModelType = loadManipulatorType(taskConfigPath, "model_information.manipulatorModelType");

    // Extract list of joints to remove (if any)
    std::vector<std::string> excludedJointNames;
    loadData::loadStdVector<std::string>(taskConfigPath, "model_information.removeJoints", excludedJointNames, true);

    // Extract base frame name
    std::string kinematicBaseFrame;
    loadData::loadPtreeValue<std::string>(configTree, kinematicBaseFrame, "model_information.baseFrame", false);

    // Construct Pinocchio interface
    robotInterface = std::make_unique<PinocchioInterface>(
        ::ocs2::mobile_manipulator::createPinocchioInterface(urdfFilePath, robotModelType));

    // Print model info summary
    std::cerr << "\n #### Model Information:";
    std::cerr << "\n #### =============================================================================\n";
    std::cerr << "\n #### model_information.manipulatorModelType: " << static_cast<int>(robotModelType);
    std::cerr << "\n #### model_information.removeJoints: ";
    for (const auto& jointName : excludedJointNames) {
        std::cerr << "\"" << jointName << "\" ";
    }
    std::cerr << "\n #### model_information.baseFrame: \"" << kinematicBaseFrame << "\"";

    // Load self-collision constraints
    std::vector<std::pair<size_t, size_t>> collisionObjectIndices;
    std::vector<std::pair<std::string, std::string>> collisionLinkPairs;
    loadData::loadStdVectorOfPair(taskConfigPath, "selfCollision.collisionObjectPairs", collisionObjectIndices);
    loadData::loadStdVectorOfPair(taskConfigPath, "selfCollision.collisionLinkPairs", collisionLinkPairs);

    // Log loaded object pairs
    std::cerr << "\nLoaded collision object pairs: ";
    for (const auto& pair : collisionObjectIndices) {
        std::cerr << "[" << pair.first << ", " << pair.second << "] ";
    }

    // Log link pairs
    std::cerr << "\nLoaded collision link pairs: ";
    for (const auto& pair : collisionLinkPairs) {
        std::cerr << "[" << pair.first << ", " << pair.second << "] ";
    }
    std::cerr << std::endl;

    // Build geometry interface
    geometryInterface = std::make_shared<PinocchioGeometryInterface>(*robotInterface, collisionLinkPairs, collisionObjectIndices);

    // Initialize visualizer
    visualizer = std::make_unique<GeometryInterfaceVisualization>(*robotInterface, *geometryInterface, nh, kinematicBaseFrame);

    // Subscribe to joint states
    ros::Subscriber jointStateSub = nh.subscribe("joint_states", 1, &handleJointStateUpdate);

    // Run ROS event loop
    ros::spin();
    return 0;
}

