bool FCrashDebugHelperWindows::CreateMinidumpDiagnosticReport(const FString& DumpFilePath)
{
    // Early exit if stack walk initialization fails or dump file cannot be opened
    FWindowsPlatformStackWalkExt StackWalker(CrashInfo);
    if (!StackWalker.InitStackWalking() || !StackWalker.OpenDumpFile(DumpFilePath))
    {
        UE_LOG(LogCrashDebugHelper, Warning, TEXT("Failed to initialize stack walking or open crash dump: %s"), *DumpFilePath);
        return false;
    }

    // Skip processing if changelist info is invalid
    if (CrashInfo.BuiltFromCL == FCrashInfo::INVALID_CHANGELIST)
    {
        UE_LOG(LogCrashDebugHelper, Warning, TEXT("Invalid built-from changelist number"));
        return false;
    }

    // Gather diagnostic data from the minidump
    FCrashModuleInfo ExeVersionInfo;
    StackWalker.GetExeFileVersionAndModuleList(ExeVersionInfo);

    StackWalker.InitSymbols();
    StackWalker.SetSymbolPathsFromModules();
    StackWalker.GetModuleInfoDetailed();
    StackWalker.GetSystemInfo();
    StackWalker.GetThreadInfo();
    StackWalker.GetExceptionInfo();
    StackWalker.GetCallstacks();

    // Include source context around the crash point
    AddSourceToReport();

    return true;
}

