/// @brief Launches a kernel-level task from a given entry point.
/// @note Allocates a fresh stack context; any local state in the calling function becomes inaccessible.
/// @param entry_point address of the task's starting instruction.
/// @param task_id unique identifier assigned by the kernel for this task.
/// @return true if the task was successfully registered, false otherwise.
bool rtl_create_kernel_task(HAL::StackFramePtr entry_point, const KID task_id) {
  if (!task_id || entry_point == nullptr) return false;
  return KernelTaskHelper::Add(entry_point, task_id);
