ProcessID rtl_create_user_process(rtl_start_kind entry_func, const Char* name) {
  if (!name || *name == '\0') return kSchedInvalidPID;
  return UserProcessScheduler::The().Spawn(name, reinterpret_cast<VoidPtr>(entry_func), nullptr);
}

