// Process a single test case by adaptively querying for words
void processTestCase() {
    int totalWordsNeeded;
    std::cin >> totalWordsNeeded;

    std::set<std::string> collectedWords;

    // Try each starting letter from 'a' to 'z'
    for (char startChar = 'a'; startChar <= 'z'; ++startChar) {
        if (collectedWords.size() >= static_cast<size_t>(totalWordsNeeded)) {
            break;
        }

        std::string currentPrefix(1, startChar);
        int queryCount = 1;

        // Use exponential search strategy to find words with this prefix
        while (true) {
            if (collectedWords.size() >= static_cast<size_t>(totalWordsNeeded)) {
                break;
            }

            std::cout << "query " << currentPrefix << " " << queryCount << std::endl;

            int actualCount;
            std::cin >> actualCount;

            // Read the returned words
            for (int i = 0; i < actualCount; ++i) {
                std::string word;
                std::cin >> word;
                collectedWords.insert(word);
            }

            // If we got fewer words than requested, no more words exist for this prefix
            if (actualCount < queryCount) {
                break;
            }

            // Early termination if we've collected all needed words
            if (queryCount == totalWordsNeeded) {
                break;
            }

            // Double the query size for next iteration, but cap at totalWordsNeeded
            queryCount *= 2;
            if (queryCount > totalWordsNeeded) {
                queryCount = totalWordsNeeded;
            }
        }
    }

    // Output the collected words
    std::cout << "answer";
    for (const std::string& word : collectedWords) {
        std::cout << " " << word;
    }
    std::cout << std::endl;
}

int main() {
    // Optimize I/O performance
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int testCaseCount;
    std::cin >> testCaseCount;

    while (testCaseCount-- > 0) {
        processTestCase();
    }

    return 0;
}

