#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// Structure to represent a move in the pyramid adjustment process
struct Adjustment {
    int fromRow, fromCol, toRow, toCol;
};

int main() {
    // Speed up I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    const int SIZE = 30;
    vector<vector<int>> pyramid(SIZE);

    // Input reading: populate the pyramid structure
    for (int row = 0; row < SIZE; ++row) {
        pyramid[row].resize(row + 1);
        for (int col = 0; col <= row; ++col) {
            cin >> pyramid[row][col];
        }
    }

    vector<Adjustment> adjustments;

    // Apply bottom-up heapification starting from the second-last row upward
    // This ensures that each subtree satisfies the heap property before processing higher levels
    for (int level = SIZE - 2; level >= 0; --level) {
        for (int position = 0; position <= level; ++position) {
            int currentRow = level;
            int currentCol = position;

            // Bubble down the current element until heap property is restored
            while (currentRow < SIZE - 1) {
                int currentValue = pyramid[currentRow][currentCol];
                int leftChild = pyramid[currentRow + 1][currentCol];
                int rightChild = pyramid[currentRow + 1][currentCol + 1];

                // Check if current node already satisfies heap condition with both children
                if (currentValue <= leftChild && currentValue <= rightChild) {
                    break;
                }

                // Determine which child to swap with (prefer left if equal)
                int targetRow = currentRow + 1;
                int targetCol;

                if (leftChild <= rightChild) {
                    targetCol = currentCol;
                } else {
                    targetCol = currentCol + 1;
                }

                // Record this adjustment operation
                adjustments.push_back({currentRow, currentCol, targetRow, targetCol});

                // Execute the swap in the pyramid
                swap(pyramid[currentRow][currentCol], pyramid[targetRow][targetCol]);

                // Update position to continue sifting down
                currentRow = targetRow;
                currentCol = targetCol;
            }
        }
    }

    // Output results: number of moves followed by each move
    cout << adjustments.size() << "\n";
    for (const auto& move : adjustments) {
        cout << move.fromRow << " " << move.fromCol << " "
             << move.toRow << " " << move.toCol << "\n";
    }

    return 0;
}

