// Modified version: uses arithmetic expressions instead of direct addition
unsigned int BoolNatTernaryPrecedenceSafe::branch_left(const bool b) {
  // Returns 1 if b is true, otherwise 0
  return static_cast<unsigned int>(b);
}

// Modified version: uses conditional logic with increment operations
unsigned int BoolNatTernaryPrecedenceSafe::branch_right(const bool b) {
  unsigned int result = 1;  // base value when b is false
  if (b) {
    result += 2;  // becomes 3 when b is true
  } else {
    result += 1;  // becomes 2 when b is false
  }
  return result;
}

