class Solution {
public:
    vector<int> findDisappearedNumbers(vector<int>& nums) {
        int size = nums.size();

        // Mark the presence of numbers by negating values at corresponding indices
        for (int i = 0; i < size; ++i) {
            int pos = abs(nums[i]) - 1;
            if (nums[pos] > 0) {
                nums[pos] = -nums[pos];
            }
        }

        // Collect indices that remain positive (missing numbers)
        vector<int> result;
        for (int i = 0; i < size; ++i) {
            if (nums[i] > 0) {
                result.push_back(i + 1);
            }
        }

        return result;
    }
};

#include <iostream>
#include <vector>
#include <algorithm>

int n;
std::vector<std::vector<int>> inv_parity;

// Safely gets inversion parity for range [l, r]
int get_range_parity(int l, int r) {
    if (l >= r) return 0;
    return inv_parity[l][r];
}

// Compute whether element at position i is greater than element at position j
// using the parity of inversions in overlapping ranges
int compare_positions(int i, int j) {
    // For i < j: [p_i > p_j] = parity of inversions in [i,j] minus those in subranges
    // Using XOR to compute the parity difference
    int full = get_range_parity(i, j);
    int left = get_range_parity(i + 1, j);
    int right = get_range_parity(i, j - 1);
    int inner = get_range_parity(i + 1, j - 1);

    // Inclusion-exclusion: full - left - right + inner mod 2
    // Which simplifies to XOR of all four values
    return full ^ left ^ right ^ inner;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::cin >> n;

    if (n == 1) {
        std::cout << "1 1\n";
        return 0;
    }

    // Initialize the parity table
    inv_parity.resize(n + 2, std::vector<int>(n + 2, 0));

    // Query all subarray inversion parities
    for (int left = 1; left <= n; ++left) {
        for (int right = left + 1; right <= n; ++right) {
            std::cout << "0 " << left << " " << right << "\n";
            std::cin >> inv_parity[left][right];
        }
    }

    // Build comparison function based on relative ordering
    auto is_less = [&](int pos_i, int pos_j) -> bool {
        if (pos_i == pos_j) return false;

        if (pos_i < pos_j) {
            // If positions are in increasing order, p[pos_i] < p[pos_j] when no inversion
            return compare_positions(pos_i, pos_j) == 0;
        } else {
            // If positions are in decreasing order, use symmetry
            return compare_positions(pos_j, pos_i) == 1;
        }
    };

    // Create index array and sort according to permutation values
    std::vector<int> idx(n);
    for (int i = 0; i < n; ++i) idx[i] = i + 1;

    std::stable_sort(idx.begin(), idx.end(), is_less);

    // Construct the permutation: p[k] = value at position k
    std::vector<int> perm(n + 1);
    for (int rank = 0; rank < n; ++rank) {
        perm[idx[rank]] = rank + 1;
    }

    // Output result
    std::cout << "1 ";
    for (int i = 1; i <= n; ++i) {
        std::cout << perm[i];
        if (i < n) std::cout << " ";
    }
    std::cout << "\n";

    return 0;
}

