//-------------------------------------------------------------------------
/// @brief Initializes the selected monitor backend and prepares it for use
//-------------------------------------------------------------------------
Error initialize() noexcept {
    // Register available monitor factory implementations
    if (auto registrationCode = Factory::registerFactory(Console::Factory,
                                                         App::Factory,
                                                         TestConsole::Factory))
        return registrationCode;

    auto backendName = MonitorBackend.val();
    auto instance = Factory::make<Monitor>(_location, backendName);
    if (!instance) return instance.ccode();

    config::monitor() = _mv(*instance);

