#include <iostream>
#include <unordered_map>
#include <queue>
using namespace std;

class Solution {
public:
    int firstUniqChar(string s) {
        unordered_map<char, int> frequency;
        queue<int> indexQueue;

        // Traverse the string to count frequencies and track potential unique characters
        for (int pos = 0; pos < s.length(); ++pos) {
            char currentChar = s[pos];

            // If character not seen before, record its first occurrence position
            if (frequency.find(currentChar) == frequency.end()) {
                frequency[currentChar] = 1;
                indexQueue.push(pos);
            } else {
                // Increment count for repeated character
                frequency[currentChar]++;
            }

            // Clean up queue by removing characters that have become non-unique
            while (!indexQueue.empty() && frequency[s[indexQueue.front()]] > 1) {
                indexQueue.pop();
            }
        }

        // Return index of first unique character or -1 if none exists
        return indexQueue.empty() ? -1 : indexQueue.front();
    }
};

