namespace {

// Helper to detect if container supports push_back (like vector)
template <typename ContainerT, typename... Args>
static auto try_emplace_back(ContainerT& c, Args&&... args)
    -> decltype(c.push_back(std::forward<Args>(args)...), void())
{
    c.push_back(std::forward<Args>(args)...);
}

// Fallback: use emplace for associative containers (like set)
template <typename ContainerT, typename... Args>
static auto try_emplace(ContainerT& c, Args&&... args)
    -> decltype(c.emplace(std::forward<Args>(args)...), void())
{
    c.emplace(std::forward<Args>(args)...);
}

// Overload resolver: prefers push_back/emplace_back over emplace
template <typename ContainerT, typename... Args>
static void emplace_back_like(ContainerT& c, Args&&... args) {
    try_emplace_back(c, std::forward<Args>(args)...);
}

// Reserve helper: only works for sequence containers with reserve()
template <typename ContainerT>
static bool attempt_reserve(ContainerT& c, size_t n) {
    c.reserve(n);
    return true;
}

template <typename ContainerT>
static bool attempt_reserve(...) {
    return false;
}

} // namespace

template <typename ContainerT>
ContainerT
delimit(const std::string& input_line, std::string_view delimiters)
{
    ContainerT result{};

    // Pre-count potential tokens by counting transitions from delimiter to non-delimiter
    size_t token_count = 0;
    bool in_token = false;

    for (char ch : input_line) {
        bool is_delim = false;
        for (char d : delimiters) {
            if (ch == d) {
                is_delim = true;
                break;
            }
        }
        if (!is_delim && !in_token) {
            ++token_count;
            in_token = true;
        } else if (is_delim) {
            in_token = false;
        }
    }

    // Attempt to reserve space if supported
    [[maybe_unused]] auto _ = attempt_reserve(result, token_count);

    size_t i = 0;
    size_t len = input_line.size();

    while (i < len) {
        // Skip leading delimiters
        while (i < len) {
            char c = input_line[i];
            bool is_delim = false;
            for (char d : delimiters) {
                if (c == d) {
                    is_delim = true;
                    break;
                }
            }
            if (!is_delim) break;
            ++i;
        }

        if (i >= len) break;

        // Mark start of token
        size_t start = i;

        // Scan until next delimiter
        while (i < len) {
            char c = input_line[i];
            bool is_delim = false;
            for (char d : delimiters) {
                if (c == d) {
                    is_delim = true;
                    break;
                }
            }
            if (is_delim) break;
            ++i;
        }

        // Extract substring manually
        std::string token{input_line.begin() + start, input_line.begin() + i};
        if (!token.empty()) {
            emplace_back_like(result, std::move(token));
        }
    }

    return result;
}

