#include <vector>
#include <numeric> // For std::gcd in C++17 and later, or use __gcd for compatibility

class Solution {
public:
    std::vector<int> replaceNonCoprimes(std::vector<int>& nums) {
        std::vector<int> stack;

        for (int current : nums) {
            stack.push_back(current);

            // Keep merging adjacent non-coprime elements from the end
            while (stack.size() >= 2) {
                int last = stack.back();
                int secondLast = stack[stack.size() - 2];
                int g = std::gcd(last, secondLast); // Use __gcd if std::gcd is unavailable

                if (g <= 1) {
                    break; // Elements are coprime, stop merging
                }

                // Remove the two elements
                stack.pop_back();
                stack.pop_back();

                // Compute LCM: (a * b) / gcd(a, b)
                long long lcm = static_cast<long long>(last) * secondLast / g;
                stack.push_back(static_cast<int>(lcm));
            }
        }

        return stack;
    }
};

