#include <vector>
using namespace std;

vector<int> subsetSums(vector<int>& arr) {
    vector<int> ans;
    int n = arr.size();

    // Iterate through all possible subsets using bitmasks
    for (int mask = 0; mask < (1 << n); ++mask) {
        int currentSum = 0;

        // Check each bit position to see which elements to include
        for (int i = 0; i < n; ++i) {
            if (mask & (1 << i)) {
                currentSum += arr[i];
            }
        }

        ans.push_back(currentSum);
    }

    return ans;
}

