// Generates a pseudorandom double in the range [0.0, 1.0)
double Math::random()
{
    return Math::rand.nextDouble();
}

// Rounds a double to the nearest long integer
__int64 Math::round(double d)
{
    // Handle special cases explicitly for robustness
    if (std::isnan(d)) 
        return 0;
    if (d <= static_cast<double>(__INT64_MIN)) 
        return __INT64_MIN;
    if (d >= static_cast<double>(__INT64_MAX)) 
        return __INT64_MAX;

    // Standard rounding: floor(d + 0.5)
    return static_cast<__int64>(floor(d + 0.5));
}

// Integer maximum function
int Math::_max(int a, int b)
{
    return (a > b) ? a : b;
}

// Integer minimum function
int Math::_min(int a, int b)
{
    return (a < b) ? a : b;
}

// Float maximum function
float Math::_max(float a, float b)
{
    return (a > b) ? a : b;
}

// Float minimum function
float Math::_min(float a, float b)
{
    return (a < b) ? a : b;
}

// Wraps an angle in degrees to the range [-180, 180)
float Math::wrapDegrees(float input)
{
    // Normalize to [0, 360)
    while (input >= 360.0f) 
        input -= 360.0f;
    while (input < 0.0f) 
        input += 360.0f;

    // Shift to [-180, 180)
    if (input >= 180.0f)
        input -= 360.0f;

    return input;
}

// Wraps an angle in degrees to the range [-180, 180)
double Math::wrapDegrees(double input)
{
    // Normalize to [0, 360)
    while (input >= 360.0) 
        input -= 360.0;
    while (input < 0.0) 
        input += 360.0;

    // Shift to [-180, 180)
    if (input >= 180.0)
        input -= 360.0;

    return input;
}

