namespace NLastGetopt {
    TString GenerateCompletionInfo(TStringBuf cmdName, TStringBuf flagName) {
        TString description = (
            "This command produces a shell script that implements tab-completion functionality and outputs it to standard output. "
            "Users can save this output to an appropriate file depending on their shell environment and OS."
            "\n"
            "\n"
            "\n"
            "{B}BASH (Linux){R}:"
            "\n"
            "\n"
            "System-wide completions go into `/etc/bash_completion.d/`, while user-specific ones belong in `~/.local/share/bash-completion/completions`. "
            "Example usage:"
            "\n"
            "\n"
            "    $ mkdir -p ~/.local/share/bash-completion/completions"
            "\n"
            "    $ {command} {completion} bash >"
            "\n"
            "          ~/.local/share/bash-completion/completions/{command}"
            "\n"
            "\n"
            "Reload your shell session for the changes to apply."
            "\n"
            "\n"
            "\n"
            "{B}BASH (macOS){R}:"
            "\n"
            "\n"
            "Install `bash-completion` or `bash-completion@2` via Homebrew if needed. Completions are stored at `/usr/local/etc/bash_completion.d`: "
            "\n"
            "\n"
            "    $ mkdir -p $(brew --prefix)/etc/bash_completion.d"
            "\n"
            "    $ {command} {completion} bash >"
            "\n"
            "          $(brew --prefix)/etc/bash_completion.d/{command}"
            "\n"
            "\n"
            "Alternatively, include the generated script directly in your `~/.bash_profile`."
            "\n"
            "\n"
            "Restart your shell to activate the new completion rules."
            "\n"
            "\n"
            "\n"
            "{B}ZSH{R}:"
            "\n"
            "\n"
            "Zsh uses directories listed in `$fpath` to locate completion functions. A common practice is to store them in `~/.zfunc`: "
            "\n"
            "\n"
            "    $ mkdir -m755 -p ~/.zfunc"
            "\n"
            "    $ {command} {completion} zsh > ~/.zfunc/_{command}"
            "\n"
            "\n"
            "Add these lines to `.zshrc`, just before calling `compinit`:"
            "\n"
            "\n"
            "    fpath+=(~/.zfunc)"
            "\n"
            "\n"
            "Then restart your shell to enable the new completions.");

        SubstGlobal(description, "{command}", cmdName);
        SubstGlobal(description, "{completion}", flagName);
        SubstGlobal(description, "{B}", NColorizer::StdErr().LightDefault());
        SubstGlobal(description, "{R}", NColorizer::StdErr().Reset());
        return description;
    }

    NComp::ICompleterPtr GetShellOptionsCompleter() {
        return NComp::Choice({{"bash"}, {"zsh"}});
    }

    TOpt BuildCompletionOption(const TOpts* globalOpts, TString cmd, TString optName) {
        return TOpt()
            .AddLongName(optName)
            .Help("produce shell completion scripts for bash or zsh")
            .CompletionHelp("generate shell completion script")
            .OptionalArgument("shell-type")
            .CompletionArgHelp("target shell type")
            .IfPresentDisableCompletion()
            .Completer(GetShellOptionsCompleter())
            .Handler1T<TString>([globalOpts, cmd, optName](TStringBuf shell) {
                if (shell.empty()) {
                    Cerr << Wrap(80, GenerateCompletionInfo(cmd, "--" + optName)) << Endl;
                } else if (shell == "bash") {
                    TBashCompletionGenerator(globalOpts).Generate(cmd, Cout);
                } else if (shell == "zsh") {
                    TZshCompletionGenerator(globalOpts).Generate(cmd, Cout);
                } else {
                    Cerr << "Unsupported shell: " << TString{shell}.Quote() << Endl;
                    exit(1);
                }
                exit(0);
            });
    }

    class TCompletionMode : public TMainClassArgs {
    public:
        TCompletionMode(const TModChooser* modSelector, TString programName, TString modeLabel)
            : ProgramName_(std::move(programName))
            , ModSelector_(modSelector)
            , ModeLabel_(std::move(modeLabel))
        {
        }

    protected:
        void SetupOptions(NLastGetopt::TOpts& opts) override {
            TMainClassArgs::SetupOptions(opts);
            opts.SetTitle("Create shell completion scripts for bash or zsh");
            opts.AddSection("Overview", GenerateCompletionInfo(ProgramName_, ModeLabel_));
            opts.SetFreeArgsNum(1);
            opts.GetFreeArgSpec(0)
                .Title("<shell-type>")
                .Help("target shell (bash or zsh)")
                .CompletionArgHelp("shell type")
                .Completer(GetShellOptionsCompleter());
        }

        int Execute(NLastGetopt::TOptsParseResult&& result) override {
            auto arg = result.GetFreeArgs()[0];
            arg.to_lower();
            if (arg == "bash") {
                TBashCompletionGenerator(ModSelector_).Generate(ProgramName_, Cout);
            } else if (arg == "zsh") {
                TZshCompletionGenerator(ModSelector_).Generate(ProgramName_, Cout);
            } else {
                Cerr << "Invalid shell identifier: " << arg.Quote() << Endl;
                result.PrintUsage();
                return 1;
            }
            return 0;
        }

    private:
