#include <iostream>

// This C++ program simulates an A=B-style substring matcher,
// but implemented directly in C++ using standard algorithms.
int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    // Read input strings s and t (though problem says Tid is ignored)
    std::string s, t;
    std::cin >> s >> t;

    // Naive substring search: check all possible starting positions
    bool found = false;
    for (size_t i = 0; i <= s.length() - t.length(); ++i) {
        bool match = true;
        for (size_t j = 0; j < t.length(); ++j) {
            if (s[i + j] != t[j]) {
                match = false;
                break;
            }
        }
        if (match) {
            found = true;
            break;
        }
    }

    // Output result: 1 if found, 0 otherwise
    std::cout << (found ? 1 : 0) << std::endl;
    return 0;
}

#include <iostream>
#include <cmath>
#include <algorithm>

class Solution {
public:
    // Alternative GCD implementation using standard Euclidean algorithm
    static int GCD(int x, int y) {
        while (y != 0) {
            int temp = y;
            y = x % y;
            x = temp;
        }
        return x;
    }

    static int countTriples(int n) {
        int count = 0;
        int limit = static_cast<int>(std::sqrt(n));

        // Iterate through possible values for generating Pythagorean triples
        for (int outer = 2; outer <= limit; outer++) {
            for (int inner = 1; inner < outer; inner++) {
                // Skip if both odd (to ensure one even, one odd for primitive triples)
                if ((outer % 2 == 1) && (inner % 2 == 1)) continue;

                // Check if coprime
                if (GCD(outer, inner) != 1) continue;

                // Calculate hypotenuse of primitive triple
                int hypotenuse = outer * outer + inner * inner;

                // Skip if hypotenuse exceeds n
                if (hypotenuse > n) break;

                // Count all multiples of this primitive triple
                int multiplier = n / hypotenuse;

                // Each primitive triple generates two distinct ordered pairs (a,b) and (b,a)
                count += 2 * multiplier;
            }
        }

        return count;
    }
};

