using namespace db;

EntityIDRebaser::EntityIDRebaser() = default;
EntityIDRebaser::~EntityIDRebaser() = default;
EntityIDRebaser::EntityIDRebaser(const EntityIDRebaser& other) = default;
EntityIDRebaser& EntityIDRebaser::operator=(const EntityIDRebaser& other) = default;
EntityIDRebaser::EntityIDRebaser(EntityIDRebaser&& other) noexcept = default;
EntityIDRebaser& EntityIDRebaser::operator=(EntityIDRebaser&& other) noexcept = default;

// When a @ref Change makes local commits, it assigns NodeIDs based on its own
// view of the next available ID — captured at the moment the change was forked.
// However, by the time the change is submitted, other changes may have already
// allocated new node IDs on main. For instance:
// @code
// CREATE (n:LOCALNODE)        <- Node created in this Change
// COMMIT                      <- LOCALNODE assigned ID 7 locally
// CREATE (n @ 7)-[r:LINK]->(m:ANOTHER) <- Edge referencing LOCALNODE (ID 7)
// @endcode
// If another change added nodes before this one submits, ID 7 on main might now
// refer to a different node. To prevent incorrect edge endpoints, we must adjust
// any IDs that were assigned *after* the branch point, based on how many new
// entities were introduced on main since then.

NodeID EntityIDRebaser::remapNodeId(NodeID originalId) const {
    bioassert(_branchTimeNextNodeID <= _newNextNodeID, "invalid _branchTimeNextNodeID");
    return (originalId >= _branchTimeNextNodeID)
               ? originalId + (_newNextNodeID - _branchTimeNextNodeID)
               : originalId;
}

EdgeID EntityIDRebaser::remapEdgeId(EdgeID originalId) const {
    bioassert(_branchTimeNextEdgeID <= _newNextEdgeID, "invalid _branchTimeNextEdgeID");
    return (originalId >= _branchTimeNextEdgeID)
               ? originalId + (_newNextEdgeID - _branchTimeNextEdgeID)
               : originalId;
}

