TEST_CASE(test_issue_211_preset_gain_migration, "Config") {
    std::cout << "\nTest: Issue #211 Preset Gain Migration" << std::endl;
    const char* temp_ini_file = "test_issue_211_presets.ini";
    std::string saved_config_path = Config::m_config_path;
    Config::m_config_path = temp_ini_file;

    // Step 1: Write legacy preset file (v0.7.66 format with 100Nm hack)
    {
        std::ofstream out_stream(temp_ini_file);
        out_stream << "[Preset:Legacy100Nm]\n";
        out_stream << "app_version=0.7.66\n";
        out_stream << "gain=1.0\n";
        out_stream << "max_torque_ref=100.0\n";
        out_stream.close();
    }

    // Step 2: Load presets and validate migration
    Config::LoadPresets();

    bool legacy_found = false;
    for (const auto& item : Config::presets) {
        if (item.name == "Legacy100Nm") {
            legacy_found = true;

            // After fix: wheelbase_max_nm should be 15.0f and gain scaled to 0.15f
            constexpr float expected_wheelbase = 15.0f;
            constexpr float expected_gain = 0.15f;
            constexpr float tolerance = 0.001f;

            if (std::abs(item.wheelbase_max_nm - expected_wheelbase) < tolerance) {
                if (std::abs(item.gain - expected_gain) < tolerance) {
                    std::cout << "[PASS] Legacy preset gain migrated correctly: " << item.gain << std::endl;
                    g_tests_passed++;
                } else {
                    std::cout << "[FAIL] Legacy preset gain NOT migrated. Got: " << item.gain << " (Expected ~0.15)" << std::endl;
                    g_tests_failed++;
                }
            } else {
                std::cout << "[FAIL] Legacy preset wheelbase_max_nm NOT reset. Got: " << item.wheelbase_max_nm << std::endl;
                g_tests_failed++;
            }

            break;
        }
    }

    if (!legacy_found) {
        std::cout << "[FAIL] Legacy100Nm preset not found." << std::endl;
        g_tests_failed++;
    }

    // Cleanup
    Config::m_config_path = saved_config_path;
    std::remove(temp_ini_file);
}

