#include <asio/dispatch.hpp>
#include <asio/execution_context.hpp>
#include <condition_variable>
#include <iostream>
#include <memory>
#include <mutex>
#include <queue>
using asio::dispatch;
using asio::execution_context;

class task_scheduler : public execution_context
{
public:
  // A class that satisfies the Executor requirements.
  class work_executor
  {
  public:
    work_executor(task_scheduler& ctx, int level) noexcept
      : owner_(ctx), priority_level_(level)
    {
    }

    task_scheduler& get_context() const noexcept
    {
      return owner_;
    }

    void on_work_started() const noexcept
    {
      // This executor doesn't count work. Instead, the scheduler simply runs
      // until explicitly stopped.
    }

    void on_work_finished() const noexcept
    {
      // This executor doesn't count work. Instead, the scheduler simply runs
      // until explicitly stopped.
    }

    template <class Func, class Alloc>
    void dispatch(Func&& f, const Alloc& a) const
    {
      submit(std::forward<Func>(f), a);
    }

    template <class Func, class Alloc>
    void post(Func f, const Alloc& a) const
    {
      auto p(std::allocate_shared<task_item<Func>>(
            typename std::allocator_traits<
              Alloc>::template rebind_alloc<char>(a),
            priority_level_, std::move(f)));
      std::lock_guard<std::mutex> guard(owner_.scheduler_mutex_);
      owner_.task_queue_.push(p);
      owner_.task_condition_.notify_one();
    }

    template <class Func, class Alloc>
    void defer(Func&& f, const Alloc& a) const
    {
      post(std::forward<Func>(f), a);
    }

    friend bool operator==(const work_executor& left,
        const work_executor& right) noexcept
    {
      return &left.owner_ == &right.owner_;
    }

    friend bool operator!=(const work_executor& left,
        const work_executor& right) noexcept
    {
      return &left.owner_ != &right.owner_;
    }

  private:
    task_scheduler& owner_;
    int priority_level_;
  };

  work_executor create_executor(int level = 0) noexcept
  {
    return work_executor(*const_cast<task_scheduler*>(this), level);
  }

  void start()
  {
    std::unique_lock<std::mutex> guard(scheduler_mutex_);
    for (;;)
    {
      task_condition_.wait(guard, [&]{ return shutdown_flag_ || !task_queue_.empty(); });
      if (shutdown_flag_)
        return;
      auto next_task(task_queue_.top());
      task_queue_.pop();
      guard.unlock();
      next_task->run_(next_task);
      guard.lock();
    }
  }

  void terminate()
  {
    std::lock_guard<std::mutex> guard(scheduler_mutex_);
    shutdown_flag_ = true;
    task_condition_.notify_all();
  }

private:
  struct base_task
  {
    int priority_value_;
    void (*run_)(std::shared_ptr<base_task>&);
  };

  template <class Func>
  struct task_item : base_task
  {
    task_item(int pri, Func f) : stored_function_(std::move(f))
    {
      priority_value_ = pri;
      run_ = [](std::shared_ptr<base_task>& ptr)
      {
        Func temp_func(std::move(static_cast<task_item*>(ptr.get())->stored_function_));
        ptr.reset();
        temp_func();
      };
    }
    Func stored_function_;
  };

  struct task_comparator
  {
    bool operator()(
        const std::shared_ptr<base_task>& first,
        const std::shared_ptr<base_task>& second)
    {
      return first->priority_value_ < second->priority_value_;
    }
  };

  std::mutex scheduler_mutex_;
  std::condition_variable task_condition_;
  std::priority_queue<
    std::shared_ptr<base_task>,
    std::vector<std::shared_ptr<base_task>>,
    task_comparator> task_queue_;
  bool shutdown_flag_ = false;
};

int main()
{
  task_scheduler scheduler;
  auto low_priority = scheduler.create_executor(0);
  auto medium_priority = scheduler.create_executor(1);
  auto high_priority = scheduler.create_executor(2);

  dispatch(low_priority, []{ std::cout << "1\n"; });
  dispatch(low_priority, []{ std::cout << "11\n"; });
  dispatch(medium_priority, []{ std::cout << "2\n"; });
  dispatch(medium_priority, []{ std::cout << "22\n"; });
  dispatch(high_priority, []{ std::cout << "3\n"; });
  dispatch(high_priority, []{ std::cout << "33\n"; });
  dispatch(high_priority, []{ std::cout << "333\n"; });
  dispatch(scheduler.create_executor(-1), [&]{ scheduler.terminate(); });

  scheduler.start();
}

