void test_network_manager_ap_activation() {
    NetworkManager manager;
    manager.begin();         // triggers START_AP queue (no stored credentials)
    manager.handleClient();  // processes START_AP and transitions to AP_MODE

    TEST_ASSERT_FALSE(manager.isConnected());
    TEST_ASSERT_TRUE(manager.getIPAddress().startsWith("192.168.4."));
    TEST_ASSERT_TRUE(manager.getSSID().startsWith("ESP32_"));
