void test_network_manager_credentials_storage() {
    NetworkManager manager;
    manager.saveCredentials("TestSSID", "TestPassword");

    // Process queued connection request
    manager.handleClient();  // CONNECT -> connect() -> state = CONNECTING

    // In non-AP context, getSSID() reflects stored SSID
    TEST_ASSERT_EQUAL_STRING("TestSSID", manager.getSSID().c_str());
    TEST_ASSERT_FALSE(manager.isConnected());  // WiFi stub prevents actual connection
