    // Initialize the module after it's loaded into memory
    // The precise timing is defined in the .uplugin configuration
    FString PluginBasePath = IPluginManager::Get().FindPlugin("PLUGIN_NAME")->GetBaseDir();

    FString DynamicLibraryPath;
#if PLATFORM_WINDOWS
    DynamicLibraryPath = FPaths::Combine(*PluginBasePath, TEXT("Binaries/ThirdParty/PLUGIN_NAMELibrary/Win64/ExampleLibrary.dll"));
