namespace Karm {

// FNV-1a 64-bit hash implementation per RFC draft-eastlake-fnv-21
export constexpr u64 fnv64(u8 const* buf, usize len) {
    u64 hash = 0xcbf29ce484222325ULL;
    for (usize i = 0; i < len; ++i) {
        hash ^= static_cast<u64>(buf[i]);
        hash *= 0x100000001b3ULL;
    }
    return hash;
}

template <typename T>
struct Hash;

// Generic hash function that delegates to member .hash() if available,
// otherwise uses the type-specific Hash<T> specialization
export template <typename T>
constexpr u64 hash(T const& value) {
    if constexpr (
        requires { 
            { value.hash() } -> Meta::Same<u64>; 
        }
    ) {
        return value.hash();
    } else {
        return Hash<T>::hash(value);
    }
}

// Specializations for standard categories using FNV-1a over raw bytes
export template <Meta::Boolean T>
struct Hash<T> {
    static constexpr u64 hash(T const& value) {
        return fnv64(reinterpret_cast<u8 const*>(&value), sizeof(T));
    }
};

export template <Meta::Integer T>
struct Hash<T> {
    static constexpr u64 hash(T const& value) {
        return fnv64(reinterpret_cast<u8 const*>(&value), sizeof(T));
    }
};

export template <Meta::Float T>
struct Hash<T> {
    static constexpr u64 hash(T const& value) {
        return fnv64(reinterpret_cast<u8 const*>(&value), sizeof(T));
    }
};

export template <Meta::Enum T>
struct Hash<T> {
    static constexpr u64 hash(T const& value) {
        return fnv64(reinterpret_cast<u8 const*>(&value), sizeof(T));
    }
};

// Special case for None type: hash as if it were 0x0
export template <>
struct Hash<None> {
    static constexpr u64 hash(None const&) {
        return Karm::hash(0x0ULL);
    }
};

