using namespace std;
using namespace std::chrono;

// Global flag to signal shutdown across threads
atomic<bool> terminateSignal(false);

// Custom lightweight task wrapper for coroutines
struct LightweightTask {
    struct promise_type {
        LightweightTask self;
        LightweightTask get_return_object() { return self; }
        suspend_always initial_suspend() noexcept { return {}; }

        struct FinalAwaiter {
            bool await_ready() const noexcept { return false; }
            void await_suspend(coroutine_handle<promise_type>) noexcept {}
            void await_resume() noexcept {}
        };
        FinalAwaiter final_suspend() noexcept { return {}; }
        void unhandled_exception() noexcept { terminate(); }
        void return_void() noexcept {}
    };

    coroutine_handle<promise_type> handle;

    LightweightTask() = default;
    LightweightTask(coroutine_handle<promise_type> h) : handle(h) {}
    ~LightweightTask() { if (handle) handle.destroy(); }
    bool isDone() const noexcept { return !handle || handle.done(); }
    void resume() noexcept { if (!isDone()) handle.resume(); }
};

// Time-ordered task scheduler using sorted insertion list instead of priority_queue
struct TaskScheduler {
    struct ScheduledItem {
        steady_clock::time_point fireTime;
        coroutine_handle<> taskHandle;
        bool operator<(const ScheduledItem& other) const { return fireTime > other.fireTime; } // min-heap semantics reversed for sort
    };

    vector<ScheduledItem> pendingTasks;

    void enqueueAt(steady_clock::time_point t, coroutine_handle<> h) {
        pendingTasks.push_back({t, h});
        ranges::sort(pendingTasks); // Sort by earliest fire time first
    }

    void enqueueNow(coroutine_handle<> h) {
        enqueueAt(steady_clock::now(), h);
    }

    void processReadyTasks() {
        auto now = steady_clock::now();
        while (!pendingTasks.empty() && pendingTasks.back().fireTime <= now) {
            auto item = pendingTasks.back();
            pendingTasks.pop_back();
            if (!item.taskHandle.done()) {
                item.taskHandle.resume();
            }
        }
    }

    void waitUntilNextOrYield() {
        if (pendingTasks.empty()) {
            this_thread::yield();
        } else {
            auto nextTime = pendingTasks.back().fireTime;
            auto now = steady_clock::now();
            if (nextTime > now) {
                auto dur = nextTime - now;
                if (dur > milliseconds(1)) {
                    this_thread::sleep_for(milliseconds(1));
                } else {
                    this_thread::yield();
                }
            } else {
                this_thread::yield();
            }
        }
    }

    bool hasWork() const noexcept { return !pendingTasks.empty(); }
};

// Sleep awaiter that schedules resumption at a future time
struct DelayAwaiter {
    TaskScheduler& sched;
    steady_clock::time_point targetTime;

    DelayAwaiter(TaskScheduler& s, microseconds duration)
        : sched(s), targetTime(steady_clock::now() + duration) {}

    bool await_ready() const noexcept { return steady_clock::now() >= targetTime; }
    void await_suspend(coroutine_handle<>) noexcept { sched.enqueueAt(targetTime, coroutine_handle<>::from_address(this)); }
    void await_resume() noexcept {}
};

// Coroutine that increments throughput counter periodically
LightweightTask transactionLoop(TaskScheduler& scheduler, atomic<int>& localCounter) {
    while (!terminateSignal.load(memory_order_relaxed)) {
        localCounter.fetch_add(1, memory_order_relaxed);
        co_await DelayAwaiter(scheduler, microseconds(15));
    }
}

// Worker thread: runs two coroutines in a shared scheduler loop
void workerThread(int id, atomic<int>& localCounter) {
    TaskScheduler scheduler;
    auto t1 = transactionLoop(scheduler, localCounter);
    auto t2 = transactionLoop(scheduler, localCounter);

    scheduler.enqueueNow(t1.handle);
    scheduler.enqueueNow(t2.handle);

    while (!terminateSignal.load(memory_order_relaxed)) {
        scheduler.processReadyTasks();
        scheduler.waitUntilNextOrYield();
    }
}

int main(int argc, char* argv[]) {
    int numWorkers = 4;
    vector<thread> workers;
    vector<atomic<int>> perThreadCounters(numWorkers, atomic<int>(0));

    for (int i = 0; i < numWorkers; ++i) {
        workers.emplace_back(workerThread, i, ref(perThreadCounters[i]));
    }

    int durationSeconds = 10;
    this_thread::sleep_for(seconds(durationSeconds));
    terminateSignal.store(true, memory_order_release);

    for (auto& w : workers) {
        w.join();
    }

    long long totalOps = 0;
    for (const auto& c : perThreadCounters) {
        totalOps += c.load(memory_order_acquire);
    }

    cout << "Throughput: " << (totalOps / durationSeconds) << " txn/sec" << endl;
    return 0;
}

