using namespace llvm;

#define DEBUG_TYPE "ssaupdaterbulk"

/// Retrieve the basic block associated with a use — either the parent block of
/// the instruction, or the predecessor for PHI nodes.
static BasicBlock *getBlockForUse(Use *U) {
  Instruction *Inst = cast<Instruction>(U->getUser());
  if (PHINode *Phi = dyn_cast<PHINode>(Inst))
    return Phi->getIncomingBlock(*U);
  return Inst->getParent();
}

/// Register a new variable to be rewritten. Returns an index (slot) for later reference.
unsigned SSAUpdaterBulk::AddVariable(StringRef VarName, Type *ElemTy) {
  unsigned Slot = RewritePlans.size();
  LLVM_DEBUG(dbgs() << "SSAUpdater: Slot=" << Slot << ": initialized with Ty = "
                    << *ElemTy << ", Name = " << VarName << "\n");
  RewritePlan Plan(VarName, ElemTy);
  RewritePlans.emplace_back(std::move(Plan));
  return Slot;
}

/// Mark that a concrete value is available at a specific block.
void SSAUpdaterBulk::AddAvailableValue(unsigned Slot, BasicBlock *BB, Value *Val) {
  assert(Slot < RewritePlans.size() && "Invalid slot!");
  LLVM_DEBUG(dbgs() << "SSAUpdater: Slot=" << Slot
                    << ": added available value " << *Val << " in "
                    << BB->getName() << "\n");
  RewritePlans[Slot].Definitions[BB] = Val;
}

/// Record a use site to be updated later.
void SSAUpdaterBulk::AddUse(unsigned Slot, Use *U) {
  assert(Slot < RewritePlans.size() && "Invalid slot!");
  LLVM_DEBUG(dbgs() << "SSAUpdater: Slot=" << Slot << ": recorded use " << *U->get()
                    << " in " << getBlockForUse(U)->getName() << "\n");
  RewritePlans[Slot].UseSites.push_back(U);
}

/// Determine the effective value at a given block during rewriting.
/// Falls back to dominator parent or undef if unreachable/undefined.
Value *SSAUpdaterBulk::getValueAt(BasicBlock *BB, RewritePlan &Plan, DominatorTree *DT) {
  auto It = Plan.Definitions.find(BB);
  if (It == Plan.Definitions.end()) {
    if (DT->isReachableFromEntry(BB) && PredCache.get(BB).size()) {
      BasicBlock *ImmediateDom = DT->getNode(BB)->getIDom()->getBlock();
      Value *V = getValueAt(ImmediateDom, Plan, DT);
      Plan.Definitions[BB] = V;
    } else {
      Plan.Definitions[BB] = UndefValue::get(Plan.Type);
    }
  }
  return Plan.Definitions[BB];
}

/// Compute the set of blocks where a value is live-in, given definitions and uses.
static void
DetermineLiveInRegions(const SmallPtrSetImpl<BasicBlock *> &UseBlocks,
                       const SmallPtrSetImpl<BasicBlock *> &DefBlocks,
                       SmallPtrSetImpl<BasicBlock *> &LiveInSet,
                       PredIteratorCache &PredCache) {
  SmallVector<BasicBlock *, 64> Worklist(UseBlocks.begin(), UseBlocks.end());

  while (!Worklist.empty()) {
    BasicBlock *BB = Worklist.pop_back_val();

    if (!LiveInSet.insert(BB).second)
      continue;

    for (BasicBlock *Pred : PredCache.get(BB)) {
      if (DefBlocks.count(Pred))
        continue;
      Worklist.push_back(Pred);
    }
  }
}

/// Perform full rewrite: insert PHIs, fill them in, and replace all uses.
void SSAUpdaterBulk::RewriteAllUses(DominatorTree *DT,
                                    SmallVectorImpl<PHINode *> *InsertedPHIs) {
  for (auto &Plan : RewritePlans) {
    ForwardIDFCalculator IDF(*DT);
    LLVM_DEBUG(dbgs() << "SSAUpdater: processing " << Plan.UseSites.size()
                      << " use(s)\n");

    // Collect definition and use sites.
    SmallPtrSet<BasicBlock *, 2> DefSites;
    for (const auto &Pair : Plan.Definitions)
      DefSites.insert(Pair.first);

    SmallPtrSet<BasicBlock *, 2> UseSites;
    for (Use *U : Plan.UseSites)
      UseSites.insert(getBlockForUse(U));

    // Compute live-in region and IDF.
    SmallVector<BasicBlock *, 32> IDFBlocks;
    SmallPtrSet<BasicBlock *, 32> LiveInBlocks;
    DetermineLiveInRegions(UseSites, DefSites, LiveInBlocks, PredCache);

    IDF.resetLiveInBlocks();
    IDF.setLiveInBlocks(LiveInBlocks);
    IDF.setDefiningBlocks(DefSites);
    IDF.calculate(IDFBlocks);

    // Insert PHI nodes at IDF blocks.
    SmallVector<PHINode *, 4> NewPHIs;
    for (BasicBlock *FrontierBB : IDFBlocks) {
      IRBuilder<> Builder(FrontierBB, FrontierBB->begin());
      PHINode *PN = Builder.CreatePHI(Plan.Type, 0, Plan.Name);
      Plan.Definitions[FrontierBB] = PN;
      NewPHIs.push_back(PN);
      if (InsertedPHIs)
        InsertedPHIs->push_back(PN);
    }

    // Populate PHI incoming values.
    for (PHINode *PN : NewPHIs) {
      BasicBlock *ParentBB = PN->getParent();
      for (BasicBlock *Pred : PredCache.get(ParentBB)) {
        PN->addIncoming(getValueAt(Pred, Plan, DT), Pred);
      }
    }

    // Replace original uses with computed values.
    SmallPtrSet<Use *, 4> Handled;
    for (Use *U : Plan.UseSites) {
      if (!Handled.insert(U).second)
        continue;

      BasicBlock *UserBB = getBlockForUse(U);
      Value *NewVal = getValueAt(UserBB, Plan, DT);
      Value *OldVal = U->get();
      assert(OldVal && "Use points to null!");

      if (OldVal != NewVal && OldVal->hasValueHandle())
        ValueHandleBase::ValueIsRAUWd(OldVal, NewVal);

      LLVM_DEBUG(dbgs() << "SSAUpdater: replacing " << *OldVal << " with " << *NewVal
                        << "\n");
      U->set(NewVal);
    }
  }
}

