// Rounds a double to the nearest long integer
// Implementation follows: (long)Math.floor(a + 0.5d)
// Handles special cases: NaN → 0, overflow → MIN/MAX values
__int64 Math::round(double d)
{
    // Use floor function after adding 0.5 for rounding
    return static_cast<__int64>(floor(d + 0.5));
}

// Integer maximum function
int Math::_max(int a, int b)
{
    return (a >= b) ? a : b;
}

// Integer minimum function
int Math::_min(int a, int b)
{
    return (a <= b) ? a : b;
}

// Floating-point maximum function
float Math::_max(float a, float b)
{
    return (a >= b) ? a : b;
}

// Floating-point minimum function
float Math::_min(float a, float b)
{
    return (a <= b) ? a : b;
}

// Wraps an angle in degrees to the range [-180, 180)
float Math::wrapDegrees(float input)
{
    // Normalize to [0, 360)
    while (input >= 360.0f) {
        input -= 360.0f;
    }
    while (input < 0.0f) {
        input += 360.0f;
    }

    // Shift to [-180, 180)
    if (input >= 180.0f) {
        input -= 360.0f;
    }

    return input;
}

// Wraps an angle in degrees to the range [-180, 180)
double Math::wrapDegrees(double input)
{
    // Normalize to [0, 360)
    while (input >= 360.0) {
        input -= 360.0;
    }
    while (input < 0.0) {
        input += 360.0;
    }

    // Shift to [-180, 180)
    if (input >= 180.0) {
        input -= 360.0;
    }

    return input;
}

