#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    // Optimize I/O operations for speed
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    // Use 1-based indexing for convenience
    vector<int> a(n + 1);
    for (int i = 1; i <= n; ++i) {
        cin >> a[i];
    }

    // Fixed reversal length pattern: use reversals of size 2 and 4
    cout << 3 << "\n";
    vector<pair<int, int>> operations;

    // Helper lambda to record and apply a reversal operation
    auto apply_reverse = [&](int left, int right) {
        operations.emplace_back(left, right);
        reverse(a.begin() + left, a.begin() + right + 1);
    };

    // Greedy sorting strategy: place correct values at boundaries step-by-step
    int left_bound = 1, right_bound = n;

    while (left_bound < right_bound) {
        // Locate positions of the smallest and largest remaining values
        int pos_min = -1, pos_max = -1;
        for (int idx = 1; idx <= n; ++idx) {
            if (a[idx] == left_bound) pos_min = idx;
            if (a[idx] == right_bound) pos_max = idx;
        }

        // Determine which move is more efficient based on distance
        int dist_to_left = pos_min - left_bound;
        int dist_to_right = right_bound - pos_max;

        if (dist_to_left <= dist_to_right) {
            // Move the minimum value to its correct position at left_bound
            int current_pos = pos_min;
            while (current_pos > left_bound) {
                if (current_pos - 3 >= left_bound) {
                    // Perform a 4-element reversal to shift left by 3 positions
                    apply_reverse(current_pos - 3, current_pos);
                    current_pos -= 3;
                } else {
                    // Fall back to adjacent swap (2-element reversal)
                    apply_reverse(current_pos - 1, current_pos);
                    current_pos -= 1;
                }
            }
            ++left_bound;
        } else {
            // Move the maximum value to its correct position at right_bound
            int current_pos = pos_max;
            while (current_pos < right_bound) {
                if (current_pos + 3 <= right_bound) {
                    // Perform a 4-element reversal to shift right by 3 positions
                    apply_reverse(current_pos, current_pos + 3);
                    current_pos += 3;
                } else {
                    // Fall back to adjacent swap (2-element reversal)
                    apply_reverse(current_pos, current_pos + 1);
                    current_pos += 1;
                }
            }
            --right_bound;
        }
    }

    // Output results
    cout << operations.size() << "\n";
    for (const auto& op : operations) {
        cout << op.first << " " << op.second << "\n";
    }

    return 0;
}

