#include <assert.h>
#include <math.h>
#include <mpi.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Generate an array of random floating-point values in [0, 1)
float*
generate_random_values(int count)
{
    float* values = (float*) malloc(sizeof(float) * count);
    assert(values != NULL);

    for(int idx = 0; idx < count; idx++)
    {
        values[idx] = static_cast<float>(rand()) / static_cast<float>(RAND_MAX);
    }
    return values;
}

int
main(int argc, char** argv)
{
    if(argc != 2)
    {
        fprintf(stderr, "Usage: avg num_elements_per_proc\n");
        exit(1);
    }

    int elements_per_process = atoi(argv[1]);

    MPI_Init(nullptr, nullptr);

    int process_rank;
    MPI_Comm_rank(MPI_COMM_WORLD, &process_rank);

    int total_processes;
    MPI_Comm_size(MPI_COMM_WORLD, &total_processes);

    // Initialize different random seeds per process
    srand(static_cast<unsigned>(time(NULL)) * process_rank);

    float* random_data = generate_random_values(elements_per_process);

    // Compute local sum
    float local_total = 0.0f;
    for(int i = 0; i < elements_per_process; ++i)
    {
        local_total += random_data[i];
    }

    // Aggregate all local sums to compute global sum
    float global_total;
    MPI_Allreduce(&local_total, &global_total, 1, MPI_FLOAT, MPI_SUM, MPI_COMM_WORLD);

    // Calculate overall mean
    float mean = global_total / (elements_per_process * total_processes);

    // Compute local sum of squared deviations from the mean
    float local_variance_sum = 0.0f;
    for(int i = 0; i < elements_per_process; ++i)
    {
        float diff = random_data[i] - mean;
        local_variance_sum += diff * diff;
    }

    // Reduce squared deviations to root process
    float global_variance_sum;
    MPI_Reduce(&local_variance_sum, &global_variance_sum, 1, MPI_FLOAT, MPI_SUM, 0, MPI_COMM_WORLD);

    // Root process computes and prints standard deviation
    if(process_rank == 0)
    {
        float variance = global_variance_sum / (elements_per_process * total_processes);
        float stddev = sqrt(variance);
        printf("Mean - %f, Standard deviation = %f\n", mean, stddev);
    }

    // Cleanup resources
    free(random_data);
    MPI_Barrier(MPI_COMM_WORLD);
    MPI_Finalize();

    return 0;
}

#include "ReduceGlobalVars.h"
#include "Utils.h"
#include "llvm/IR/Constants.h"
#include "llvm/Transforms/Utils/ModuleUtils.h"

using namespace llvm;

// Helper function to determine if a global variable must be preserved
static bool isEssential(const GlobalVariable &GV) {
  StringRef Name = GV.getName();
  return Name == "llvm.used" || Name == "llvm.compiler.used";
}

/// Eliminates global variables not belonging to the selected test chunks
static void pruneUnusedGlobals(Oracle &O, ReducerWorkItem &WorkItem) {
  Module &Program = WorkItem.getModule();

  // Collect global variables that should be retained
  std::vector<Constant *> PreservedGVs;
  for (auto &GV : Program.globals()) {
    if (isEssential(GV) || O.shouldKeep())
      PreservedGVs.push_back(&GV);
  }

  // Convert vector to set for efficient lookup
  DenseSet<Constant *> KeepList(PreservedGVs.begin(), PreservedGVs.end());

  // Identify globals to remove
  DenseSet<Constant *> RemoveCandidates;
  for (auto &GV : Program.globals()) {
    if (!KeepList.count(&GV))
      RemoveCandidates.insert(&GV);
  }

  // Clean up references in llvm.used / llvm.compiler.used lists
  removeFromUsedLists(Program,
    [&RemoveCandidates](Constant *C) { return RemoveCandidates.count(C); });

  // Replace uses and erase removed globals
  for (auto *GV : RemoveCandidates) {
    GV->replaceAllUsesWith(getDefaultValue(GV->getType()));
    cast<GlobalVariable>(GV)->eraseFromParent();
  }
}

// Expose the delta pass interface
void llvm::reduceGlobalsDeltaPass(TestRunner &Test) {
  runDeltaPass(Test, pruneUnusedGlobals, "Eliminating Unused GlobalVariables");
}

