#include <grpc++/grpc++.h>
#include "bzl/examples/grpc/proto/test_service.grpc.pb.h"

using grpc::Server;
using grpc::ServerBuilder;
using grpc::ServerContext;
using grpc::Status;
using test_service_package::IntRequest;
using test_service_package::IntReply;
using test_service_package::Decompositor;

namespace {
  std::unique_ptr<Server> gMainServer;
  const auto gServerTimeout = std::chrono::seconds(10);
}

// Alternative implementation: Decompose integer into sum of random positive integers
class GreeterServiceImpl final : public Decompositor::Service {
public:
  Status Decompose(ServerContext* /*context*/,
                   const IntRequest* request,
                   IntReply* reply) override {
    int remaining = request->value();
    std::vector<int> parts;

    // Use a single RNG engine instance with seeded generator
    std::random_device seedSource;
    unsigned int seedVal = static_cast<unsigned int>(seedSource());
    std::mt19937 rngEngine(seedVal);

    do {
      if (remaining <= 0) break;

      std::uniform_int_distribution<int> dist(1, remaining);
      int part = dist(rngEngine);
      parts.push_back(part);
      remaining -= part;
    } while (remaining > 0);

    // Build output string manually
    std::ostringstream oss;
    for (size_t i = 0; i < parts.size(); ++i) {
      oss << parts[i];
      if (i + 1 < parts.size()) oss << " ";
    }
    oss << " = " << request->value();

    reply->set_message(oss.str());
    return Status::OK;
  }
};

void LaunchServer() {
  std::string listenAddr = "0.0.0.0:50051";
  GreeterServiceImpl handler;
  ServerBuilder builder;

  builder.AddListeningPort(listenAddr, grpc::InsecureServerCredentials());
  builder.RegisterService(&handler);

  gMainServer = builder.BuildAndStart();
  std::cout << "Server active on " << listenAddr << std::endl;

  gMainServer->Wait();
}

void AutoShutdownServer() {
  std::this_thread::sleep_for(gServerTimeout);
  std::cerr << "Initiating shutdown after " 
            << gServerTimeout.count() << " seconds" << std::endl;
  if (gMainServer) {
    gMainServer->Shutdown();
  }
}

int main(int argc, char** argv) {
  std::thread killerThread(AutoShutdownServer);
  LaunchServer();
  killerThread.join();
  return 0;
}

