#include <asio/ts/executor.hpp>
#include <asio/thread_pool.hpp>
#include <iostream>
#include <string>

using asio::bind_executor;
using asio::dispatch;
using asio::make_work_guard;
using asio::post;
using asio::thread_pool;

// Asynchronously reads one line from input stream using a different approach
template <typename CompletionToken>
void read_line_async(std::istream& input, CompletionToken&& token)
{
  // Create work guard to keep the executor alive during operation
  auto guard = make_work_guard(token);

  // Schedule the actual I/O operation asynchronously
  post([&input, guard, token = std::forward<CompletionToken>(token)]() mutable
      {
        std::string buffer;
        std::getline(input, buffer);

        // Ensure handler runs on the target executor
        dispatch(guard.get_executor(),
            [data = std::move(buffer), token = std::forward<CompletionToken>(token)]() mutable
            {
              token(std::move(data));
            });
      });
}

int main()
{
  thread_pool worker_pool;

  std::cout << "Enter a line: ";

  // Use the new function name and bind to worker pool
  read_line_async(std::cin,
      bind_executor(worker_pool, [](std::string result)
        {
          std::cout << "Line: " << result << "\n";
        }));

  worker_pool.join();
}

