#include <string>
#include <sstream>
#include <sm/vvec>
#include <sm/bootstrap>
#include <sm/random>
#include <sm/histo>
#include <mplot/Visual.h>
#include <mplot/GraphVisual.h>
#include <sm/config>

int main() {
    int exit_code = -1;

    // Load configuration from JSON file
    sm::config settings("../examples/bootstrap.json");

    // --- First distribution setup ---
    double mean1 = settings.get<double>("dist1_mean", 5.0);
    double stddev1 = settings.get<double>("dist1_sigma", 2.0);
    size_t sample_count1 = settings.get<size_t>("dist1_n", 1000u);

    sm::rand_normal<double, std::mt19937_64> generator1(mean1, stddev1);
    sm::vvec<double> dataset1;
    dataset1.set_from(generator1.get(sample_count1));

    // Print basic statistics
    std::cout << "Dataset 1 standard deviation: " << dataset1.std() << "\n";
    std::cout << "SEM estimate (analytical): " << (dataset1.std() / std::sqrt(dataset1.size())) << "\n";

    // Bootstrap error of mean for dataset 1
    size_t resample_count = settings.get<size_t>("num_resamples", 1024u);
    double boot_se_mean1 = sm::bootstrap::error_of_mean<double>(dataset1, resample_count);
    std::cout << "Bootstrap SE of mean (dataset 1): " << boot_se_mean1 << "\n";

    // Visualization for dataset 1
    mplot::Visual viewer(1400, 768, "Bootstrap Analysis");
    sm::histo<double, float> histogram1(dataset1, 100);
    auto graph1 = std::make_unique<mplot::GraphVisual<float>>(sm::vec<float>({-2, 0, 0}));
    viewer.bindmodel(graph1);
    graph1->setdata(histogram1);
    graph1->xlabel = "Value";
    graph1->ylabel = "Proportion";

    // Add descriptive labels to first graph
    auto add_stat_label = [&](const std::string& prefix, double value, const sm::vec<float>& pos) {
        graph1->addLabel(prefix + std::to_string(value), pos, mplot::TextFeatures(0.05f));
    };

    add_stat_label("mean ", dataset1.mean(), sm::vec<float>({1.1f, 0.66f, 0}));
    add_stat_label("SD   ", dataset1.std(), sm::vec<float>({1.1f, 0.58f, 0}));
    std::string sem_str = "SD/" + mplot::unicode::toUtf8(mplot::unicode::sqrt) +
                          std::to_string(dataset1.size()) + " = " +
                          std::to_string(dataset1.std() / std::sqrt(dataset1.size()));
    graph1->addLabel(sem_str, sm::vec<float>({1.1f, 0.50f, 0}), mplot::TextFeatures(0.05f));
    graph1->addLabel("BS stderr: " + std::to_string(boot_se_mean1),
                     sm::vec<float>({1.1f, 0.42f, 0}), mplot::TextFeatures(0.05f));

    // --- Second distribution setup ---
    double mean2 = settings.get<double>("dist2_mean", 5.0);
    double stddev2 = settings.get<double>("dist2_sigma", 2.0);
    size_t sample_count2 = settings.get<size_t>("dist2_n", 1000u);

    sm::rand_normal<double, std::mt19937_64> generator2(mean2, stddev2);
    sm::vvec<double> dataset2;
    dataset2.set_from(generator2.get(sample_count2));

    double boot_se_mean2 = sm::bootstrap::error_of_mean<double>(dataset2, resample_count);
    std::cout << "Bootstrap SE of mean (dataset 2): " << boot_se_mean2 << "\n";

    // Two-sample bootstrap t-test
    sm::vec<double, 2> asl_result = sm::bootstrap::ttest_equalityofmeans<double>(
        dataset1, dataset2, resample_count);
    std::cout << "Achieved significance level: " << asl_result[0]
              << " (min possible ASL: " << asl_result[1] << ")\n";

    // Visualization for both datasets
    sm::histo<double, float> histogram2(dataset2, 100);
    auto graph2 = std::make_unique<mplot::GraphVisual<float>>(sm::vec<float>({0, 0, 0}));
    viewer.bindmodel(graph2);
    graph2->setdata(histogram1);
    graph2->setdata(histogram2);
    graph2->xlabel = "Value";
    graph2->ylabel = "Proportion";

    // Add labels to second graph
    add_stat_label("mean ", dataset2.mean(), sm::vec<float>({1.1f, 0.66f, 0}));
    add_stat_label("SD2  ", dataset2.std(), sm::vec<float>({1.1f, 0.58f, 0}));
    std::string sem2_str = "SD2/" + mplot::unicode::toUtf8(mplot::unicode::sqrt) +
                           std::to_string(dataset2.size()) + " = " +
                           std::to_string(dataset2.std() / std::sqrt(dataset2.size()));
    graph2->addLabel(sem2_str, sm::vec<float>({1.1f, 0.50f, 0}), mplot::TextFeatures(0.05f));
    graph2->addLabel("BS stderr2: " + std::to_string(boot_se_mean2),
                     sm::vec<float>({1.1f, 0.42f, 0}), mplot::TextFeatures(0.05f));
    graph2->addLabel("ASL: " + asl_result.str(),
                     sm::vec<float>({1.1f, 0.34f, 0}), mplot::TextFeatures(0.05f));

    // Significance interpretation
    double alpha = settings.get<double>("chosen_significance_level", 0.01);
    std::stringstream sig_msg;
    if (asl_result[0] < asl_result[1]) {
        sig_msg << "Reject H₀ at α = " << alpha << ".\n"
                << "Observed ASL < min measurable ASL (" << asl_result[1] << ").\n"
                << "With " << resample_count << " resamples, min detectable ASL is "
                << asl_result[1];
    } else if (asl_result[0] < alpha) {
        sig_msg << "Reject H₀ at α = " << alpha << ".\n"
                << "Probability of observing such extreme data under H₀ is " << asl_result[0];
    } else {
        sig_msg << "Fail to reject H₀.\n"
                << "ASL (" << asl_result[0] << ") ≥ α (" << alpha << ")";
    }
    graph2->addLabel(sig_msg.str(), sm::vec<float>({0.0f, -0.27f, 0}), mplot::TextFeatures(0.05f));

    // Finalize and display
    graph1->finalize();
    graph2->finalize();
    viewer.addVisualModel(graph1);
    viewer.addVisualModel(graph2);
    viewer.keepOpen();

    return exit_code;
}

#include <vector>
#include <algorithm>
using namespace std;

// Definition for a binary tree node.
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode() : val(0), left(nullptr), right(nullptr) {}
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
    TreeNode(int x, TreeNode *l, TreeNode *r) : val(x), left(l), right(r) {}
};

class Validator {
public:
    // Perform in-order traversal to collect node values
    void collectInOrder(TreeNode* node, vector<int>& result) {
        if (!node) return;
        collectInOrder(node->left, result);
        result.push_back(node->val);
        collectInOrder(node->right, result);
    }

    // Determine if the tree is a valid Binary Search Tree
    bool checkValidBST(TreeNode* root) {
        vector<int> sequence;
        collectInOrder(root, sequence);

        // Verify strictly increasing order by comparing adjacent elements
        for (size_t idx = 1; idx < sequence.size(); ++idx) {
            if (sequence[idx] <= sequence[idx - 1]) {
                return false;
            }
        }
        return true;
    }
};

#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <tuple>

// Stores the generated edges in the form (source, intermediate, target)
std::vector<std::tuple<int, int, int>> edge_list;

/**
 * @brief Adds an edge from 'start' to 'end' using intermediate node 'mid'
 *        Justification: edges start->mid and mid->end already exist.
 */
void generate_edge(int start, int mid, int end) {
    edge_list.emplace_back(start, mid, end);
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::cin >> n;

    // Handle trivial cases
    if (n <= 1) {
        std::cout << 0 << '\n';
        return 0;
    }

    // Determine optimal parameter k to minimize total edges
    // Approximate optimal k ~ n^(1/3), but ensure k >= 2 for non-triviality
    int k = static_cast<int>(std::round(std::pow(n, 1.0 / 3.0)));
    if (k < 2) k = 2;

    // Phase 1: Build small jumps [2, k-1]
    // Each jump of length i is built from jumps (i-1) and 1
    for (int jump_len = 2; jump_len < k; ++jump_len) {
        for (int u = 0; u + jump_len <= n; ++u) {
            generate_edge(u, u + jump_len - 1, u + jump_len);
        }
    }

    // Phase 2: Build multiples of k: [k, 2k, ..., (k-1)k]
    // First build jump k from (k-1) and 1
    if (k <= n) {
        for (int u = 0; u + k <= n; ++u) {
            generate_edge(u, u + k - 1, u + k);
        }
    }
    // Then build jumps i*k from (i-1)*k and k
    for (int multiplier = 2; multiplier < k; ++multiplier) {
        int jump_size = multiplier * k;
        if (jump_size > n) break;
        for (int u = 0; u + jump_size <= n; ++u) {
            generate_edge(u, u + (multiplier - 1) * k, u + jump_size);
        }
    }

    // Phase 3: Build multiples of k^2: [k^2, 2k^2, ..., A*k^2] where A = floor(n/k^2)
    int square_k = k * k;
    if (square_k <= n) {
        // First build jump k^2 from (k-1)*k and k
        for (int u = 0; u + square_k <= n; ++u) {
            generate_edge(u, u + (k - 1) * k, u + square_k);
        }
    }

    int max_multiplier = n / square_k;
    for (int multiplier = 2; multiplier <= max_multiplier; ++multiplier) {
        int jump_size = multiplier * square_k;
        if (jump_size > n) break;
        for (int u = 0; u + jump_size <= n; ++u) {
            generate_edge(u, u + (multiplier - 1) * square_k, u + jump_size);
        }
    }

    // Output results
    std::cout << edge_list.size() << '\n';
    for (const auto& edge : edge_list) {
        std::cout << std::get<0>(edge) << " "
                  << std::get<1>(edge) << " "
                  << std::get<2>(edge) << '\n';
    }

    return 0;
}

