class SearchModeToolButtonTest : public PlainTestSuite {
  Q_OBJECT

private slots:
  void initTestCase() override {
    qRegisterMetaType<SearchTools::SearchModeE>("SearchTools::SearchModeE");
    Configuration().reset(); // renamed clear() to reset()
  }

  void cleanupTestCase() override {
    Configuration().reset();
  }

  void test_initialState() {
    // Verify initial state before creating button
    const int expectedInitialMode = static_cast<int>(SearchTools::SearchModeE::NORMAL);
    QCOMPARE(MemoryKey::ADVANCE_SEARCH_MODE.v.toInt(), expectedInitialMode);

    SearchModeToolButton buttonInstance;
    QCOMPARE(buttonInstance.getCurrentSearchMode(), SearchTools::SearchModeE::NORMAL); // renamed curSearchMode()

    // Ensure all action pointers are non-null
    QVERIFY(buttonInstance.actionMatchEqual != nullptr);
    QVERIFY(buttonInstance.actionMatchRegex != nullptr);
    QVERIFY(buttonInstance.actionSearchScopeContent != nullptr);
  }

  void test_modeChangeSignals() {
    SearchModeToolButton buttonInstance;
    QSignalSpy modeChangeSpy(&buttonInstance, &SearchModeToolButton::searchModeChanged);

    // Simulate switching to regex mode via internal action mechanism
    QAction* regexAction = buttonInstance.mSearchModeIntAction.setCheckedIfActionExist(SearchTools::SearchModeE::REGEX);
    QVERIFY(regexAction != nullptr);
    QVERIFY(regexAction->isChecked());
    QCOMPARE(regexAction, buttonInstance.actionMatchRegex); // renamed MATCH_REGEX

    // Trigger the action manually
    emit regexAction->triggered(true);

    // Wait until signal is emitted (with timeout)
    QTRY_COMPARE(modeChangeSpy.count(), 1);

    // Validate signal payload
    QList<QVariant> lastSignalArgs = modeChangeSpy.takeLast();
    QCOMPARE(lastSignalArgs.size(), 1); // exactly one argument expected

    SearchTools::SearchModeE receivedMode = lastSignalArgs[0].value<SearchTools::SearchModeE>();
    QCOMPARE(receivedMode, SearchTools::SearchModeE::REGEX);
    QCOMPARE(buttonInstance.getCurrentSearchMode(), receivedMode);
  }

  void test_configurationPersistence() {
    // First block: set mode to FILE_CONTENTS and destroy object (triggers save on destruction)
    {
      SearchModeToolButton tempBtn;
      auto* contentAction = tempBtn.mSearchModeIntAction.setCheckedIfActionExist(SearchTools::SearchModeE::FILE_CONTENTS);
      QCOMPARE(contentAction, tempBtn.actionSearchScopeContent); // renamed SEARCH_SCOPE_CONTENT

      // Manually emit change to ensure persistence logic runs
      tempBtn.EmitSearchModeChanged(contentAction);
    }

    // Confirm config was saved
    QVERIFY(Configuration().hasKey(MemoryKey::ADVANCE_SEARCH_MODE.name)); // renamed contains() to hasKey()
    const int savedValue = Configuration().getValue(MemoryKey::ADVANCE_SEARCH_MODE.name).toInt(); // renamed value() to getValue()
    QCOMPARE(savedValue, static_cast<int>(SearchTools::SearchModeE::FILE_CONTENTS));

    // Second block: create new instance and verify restored state
    SearchModeToolButton restoredBtn;
    QCOMPARE(restoredBtn.getCurrentSearchMode(), SearchTools::SearchModeE::FILE_CONTENTS);
  }
};

