#include "json.h"
#include "wrapper.h"
#include <library/cpp/json/json_value.h>
using namespace NJson;

void NLua::PushJsonValue(TLuaStateHolder* state, const TJsonValue& json) {
    // Reserve stack space for the top-level value; recursive calls handle their own stack needs
    state->ensure_stack(1);

    switch (json.GetType()) {
        case JSON_UNDEFINED:
            ythrow yexception() << "cannot push undefined json value";

        case JSON_NULL:
            state->push_nil();
            break;

        case JSON_BOOLEAN:
            state->push_bool(json.GetBoolean());
            break;

        case JSON_INTEGER:
            state->push_number(static_cast<double>(json.GetInteger()));
            break;

        case JSON_UINTEGER:
            state->push_number(static_cast<double>(json.GetUInteger()));
            break;

        case JSON_DOUBLE:
            state->push_number(json.GetDouble());
            break;

        case JSON_STRING:
            state->push_string(json.GetString().c_str());
            break;

        case JSON_MAP: {
            state->create_table();
            int pos = 1;
            for (const auto& entry : json.GetMap()) {
                PushJsonValue(state, entry.second);
                state->set_field(-2, entry.first.c_str());
            }
            break;
        }

        case JSON_ARRAY: {
            state->create_table();
            int idx = 1;
            for (const auto& item : json.GetArray()) {
                PushJsonValue(state, item);
                state->rawseti(-2, idx++);
            }
            break;
        }

        default:
            ythrow yexception() << "Unexpected json value type encountered";
    }
}

#include <mplot/Visual.h>
#include <mplot/GraphVisual.h>
#include <sm/vvec>

int main() {
    // Initialize a visualization window with specified dimensions and title
    mplot::Visual scene(1024, 768, "Created using mplot::GraphVisual");

    // Construct a GraphVisual instance for double-precision data, positioned at origin
    auto graph = std::make_unique<mplot::GraphVisual<double>>(sm::vec<float>({0.0f, 0.0f, 0.0f}));

    // Establish the parent-child relationship and register necessary callbacks
    scene.bindmodel(graph);

    // Prepare x-axis data points using vvec (vector with vector-like operations)
    sm::vvec<double> abscissas;

    // Generate evenly spaced points between -0.5 and 0.8 (14 points total)
    abscissas.linspace(-0.5, 0.8, 14);

    // Define the cubic function y = x^3 and assign to the graph
    graph->setdata(abscissas, abscissas.pow(3));

    // Finalize graph geometry by computing OpenGL vertex data
    graph->finalize();

    // Transfer ownership of the graph model to the scene
    scene.addVisualModel(graph);

    // Display the visualization and wait for user to exit (Ctrl-q)
    scene.keepOpen();

    // Automatic cleanup occurs when 'scene' destructor runs, releasing the GraphVisual
    return 0;
}

