bool FConsoleCommands::Exec(UWorld* InWorld, const TCHAR* InputCmd, FOutputDevice& LogAr)
{
	const TCHAR* OriginalInput = InputCmd;

	// Helper lambda to handle deprecated command aliases
	auto HandleAlias = [&](const FString& OldName, const FString& NewName) -> bool
	{
		LogAr.Logf(ELogVerbosity::Warning, TEXT("%s is deprecated. Use %s instead"), OriginalInput, *NewName);
		return IConsoleManager::Get().ProcessUserConsoleInput(NewName, LogAr, InWorld);
	};

	if (FParse::Command(&InputCmd, TEXT("OVRGLOBALMENU")))
	{
		return HandleAlias(TEXT("OVRGLOBALMENU"), TEXT("vr.oculus.ShowGlobalMenu"));
	}
	else if (FParse::Command(&InputCmd, TEXT("OVRQUITMENU")))
	{
		return HandleAlias(TEXT("OVRQUITMENU"), TEXT("vr.oculus.ShowQuitMenu"));
	}
#if !UE_BUILD_SHIPPING
	else if (FParse::Command(&InputCmd, TEXT("vr.oculus.Debug.EnforceHeadTracking")))
	{
		return HandleAlias(TEXT("vr.oculus.Debug.EnforceHeadTracking"), TEXT("vr.HeadTracking.bEnforced"));
	}
#endif // !UE_BUILD_SHIPPING

	return false;
}
