#include <iostream>
#include "sophus/geometry.hpp"

int main() {
  // Compute the combined rotation from three elementary rotations
  const double pi = Sophus::Constants<double>::pi();

  // Define individual rotations around coordinate axes
  Sophus::SO3d Rx = Sophus::SO3d::rotX(pi / 4.0);
  Sophus::SO3d Ry = Sophus::SO3d::rotY(pi / 6.0);
  Sophus::SO3d Rz = Sophus::SO3d::rotZ(-pi / 3.0);

  std::cout << "Elementary rotation matrices:" << std::endl;
  std::cout << "Rx (x-axis, 45 degrees):\n" << Rx.matrix() << std::endl;
  std::cout << "Ry (y-axis, 30 degrees):\n" << Ry.matrix() << std::endl;
  std::cout << "Rz (z-axis, -60 degrees):\n" << Rz.matrix() << std::endl;

  // Combine rotations: first z, then y, then x (order matters)
  Sophus::SO3d R_combined = Rx * Ry * Rz;
  std::cout << "\nCombined rotation Rx*Ry*Rz:\n" << R_combined.matrix() << std::endl;

  // Apply rotations to a test vector
  Eigen::Vector3d point(0.0, 0.0, 1.0);
  std::cout << "\nApplying rotations to vector [0, 0, 1]:\n";
  std::cout << "Original vector:\n" << point << std::endl;

  // Sequential application
  Eigen::Vector3d temp = Ry * point;
  Eigen::Vector3d result_sequential = Rx * temp;
  std::cout << "After Ry then Rx: Rx(Ry(x))\n" << result_sequential << std::endl;

  // Combined application
  Eigen::Vector3d result_combined = R_combined * point;
  std::cout << "After combined rotation (Rx*Ry*Rz)*x:\n" << result_combined << std::endl;

  // Verify associativity: (Rx*Ry)*x == Rx*(Ry*x)
  Eigen::Vector3d left_assoc = (Rx * Ry) * point;
  std::cout << "Associativity check (Rx*Ry)*x:\n" << left_assoc << std::endl;

  std::cout << "\nQuaternion representation of Rx:\n";
  auto quat = Rx.unit_quaternion();
  std::cout << "Coefficients (i, j, k, w): " << quat.coeffs().transpose() << std::endl;

  return 0;
}

