namespace engine::store::filter::filesys::filesys {
//-----------------------------------------------------------------
// Register the filesys protocol config with the Url system. This
// enables usage of Url::toPath(...), Url::toUrl(...), etc. Only
// the osPath is registered here; generic conversions and capabilities
// are handled by the service manager.
//-----------------------------------------------------------------
static url::UrlConfig urlConfig{
    {//------------------------------------------------------------
     /// @details
     ///	Specify the protocol identifier
     //------------------------------------------------------------
     .protocol = Type,
     //-------------------------------------------------------------
     /// @details
     ///		Transforms a URL (with protocol prefix stripped) into
     ///		an OS-compatible absolute path string.
     ///
     ///		Under Linux:
     ///			input: ("usr", "dir", "file.txt")
     ///			output: /usr/dir/file
     ///
     ///		Under Windows:
     ///			input: ("C:", "dir", "file.txt")
     ///			output: //./C:/dir/file.txt
     ///
     ///	@param[in]  fromUrl
     ///		The source URL object
     ///	@param[out] toPath
     ///		Receives the resulting platform-specific path string
     ///	@returns
     ///		Error code indicating success or failure
     //-------------------------------------------------------------
     .osPath = [](const Url &fromUrl, Text &toPath) -> Error {
         // Extract internal path representation
         Path intermediatePath;
         if (auto err = urlConfig.toPath(fromUrl, intermediatePath)) return err;

#ifdef ROCKETRIDE_PLAT_WIN
         // On Windows, delegate directly to platform-specific conversion
         toPath = intermediatePath.plat();
#else
         // On Unix-like systems, ensure leading slash for relative paths
         // since URLs like filesys://FileSystem/dir/file.txt yield relative paths
         std::string rawPath = intermediatePath.plat();
         if (rawPath.empty() || rawPath[0] != '/') {
             toPath = "/" + rawPath;
         } else {
             toPath = rawPath;
         }
#endif
         return {};
     }}};
}  // namespace engine::store::filter::filesys::filesys

