            return CarAdaptor::CarState(this->getVehicleApi(vname)->getCarState());
        });

        // Bind setCarControls method
        srv->bind("setCarControls", [this](const CarAdaptor::CarControls& c, const std::string& vname) -> void {
            this->getVehicleApi(vname)->setCarControls(c.to());
        });

        // Bind getCarControls method
        srv->bind("getCarControls", [this](const std::string& vname) -> CarAdaptor::CarControls {
            return CarAdaptor::CarControls(this->getVehicleApi(vname)->getCarControls());
        });
    }

