int main(int argc, char** argv) {
  // Initialize autolink framework.
  ::autolink::Initialize(argv[0]);

  // Instantiate the Qt application object.
  QApplication app_instance(argc, argv);

  // Construct the visualizer application with an autolink client wrapper.
  std::unique_ptr<autonomy::common::AutolinkClientAbstraction> client_ptr =
      std::make_unique<autonomy::common::AutolinkClientAbstraction>();
  autonomy::common::VisualizerApp visualizer(std::move(client_ptr));
  visualizer.attachToApplication(&app_instance);

  // Attempt to initialize and run the visualizer.
