#include <iostream>
#include <vector>
#include <numeric>
#include <cmath>
#include <algorithm>

void process() {
    // First query: send 100000 words each of length 1
    std::cout << "? 100000";
    for (int idx = 0; idx < 100000; ++idx) {
        std::cout << " 1";
    }
    std::cout << std::endl;

    long long response1;
    std::cin >> response1;

    if (response1 == -1) { // Handle error condition
        return;
    }

    if (response1 == 1) {
        std::cout << "! 100000" << std::endl;
        return;
    }

    // Compute possible range for word count per article
    long long lower_bound = (100000LL + response1 - 1) / response1;
    long long upper_bound = (100000LL - 1) / (response1 - 1);

    if (lower_bound == upper_bound) {
        std::cout << "! " << lower_bound << std::endl;
        return;
    }

    // Second query: design a specific pattern to determine exact word count
    long long range_size = upper_bound - lower_bound + 1;
    long long second_query_size = 2 * (range_size - 1);

    std::cout << "? " << second_query_size;
    for (long long step = 1; step < range_size; ++step) {
        std::cout << " " << lower_bound << " " << step;
    }
    std::cout << std::endl;

    long long response2;
    std::cin >> response2;

    if (response2 == -1) { // Handle error condition
        return;
    }

    // Derive final answer using the second response
    long long result_word_count = 2 * upper_bound - lower_bound - response2;
    std::cout << "! " << result_word_count << std::endl;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int test_cases;
    std::cin >> test_cases;

    while (test_cases--) {
        process();
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <tuple>

// Store added edges as {source, intermediate, target}
std::vector<std::tuple<int, int, int>> new_edges;
// Track existing edges to prevent duplicates (n <= 4096)
bool edge_exists[4100][4100] = {{false}};

// Add an edge only if it doesn't already exist and source < target
void insert_edge_if_missing(int src, int mid, int dst) {
    if (src >= dst) return;
    if (!edge_exists[src][dst]) {
        new_edges.emplace_back(src, mid, dst);
        edge_exists[src][dst] = true;
    }
}

// Recursive function to construct required connections
void build_connections(int left, int right) {
    // Base case: no further splitting needed for adjacent nodes
    if (right - left <= 1) {
        return;
    }

    // Split the current interval into two halves
    int center = left + (right - left) / 2;

    // Process left and right subintervals recursively
    build_connections(left, center);
    build_connections(center, right);

    // Connect left partition to the center node
    int mid_left = left + (center - left) / 2;
    for (int i = left; i < center; ++i) {
        insert_edge_if_missing(i, mid_left, center);
    }

    // Connect center node to right partition
    int mid_right = center + (right - center) / 2;
    for (int j = center + 1; j <= right; ++j) {
        insert_edge_if_missing(center, mid_right, j);
    }
}

int main() {
    // Optimize I/O performance
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int size;
    std::cin >> size;

    if (size > 0) {
        // Initialize direct edges between consecutive nodes: i -> i+1
        for (int i = 0; i < size; ++i) {
            edge_exists[i][i + 1] = true;
        }

        // Build additional required edges
        build_connections(0, size);
    }

    // Output count and details of added edges
    std::cout << new_edges.size() << "\n";
    for (const auto& edge : new_edges) {
        std::cout << std::get<0>(edge) << " " 
                  << std::get<1>(edge) << " " 
                  << std::get<2>(edge) << "\n";
    }

    return 0;
}

