// Helper function to convert wide string path to narrow char* for POSIX systems
static char* wstrToNarrow(const std::wstring& wstr) {
    size_t len = wstr.size() + 1;
    char* result = new char[len];
    std::mbstate_t state = std::mbstate_t();
    const wchar_t* src = wstr.c_str();
    char* dst = result;
    std::size_t converted = std::wcsrtombs(dst, &src, len, &state);
    if (converted == static_cast<std::size_t>(-1)) {
        // Fallback: copy as ASCII if conversion fails
        for (size_t i = 0; i < len - 1; ++i)
            result[i] = static_cast<char>(wstr[i]);
        result[len - 1] = '\0';
    }
    return result;
}

// Constructs a FileOutputStream by opening the given file for writing.
// Throws an exception if file is a directory or cannot be opened.
FileOutputStream::FileOutputStream(const File& file) : m_fileHandle(nullptr) {
    if (file.exists() && file.isDirectory()) {
        // TODO: Implement proper exception handling (e.g., FileNotFoundException)
        return;
    }

#ifdef _DURANGO
    // Xbox One / Durango-specific file creation
    HANDLE h = CreateFileW(
        file.getPath().c_str(),
        GENERIC_WRITE,
        0,
        nullptr,
        OPEN_ALWAYS,
        FILE_ATTRIBUTE_NORMAL,
        nullptr
    );
    m_fileHandle = h;
#elif defined(_WIN32)
    // Standard Windows implementation
    std::string filename = wstringtofilename(file.getPath());
    HANDLE h = CreateFileA(
        filename.c_str(),
        GENERIC_WRITE,
        0,
        nullptr,
        OPEN_ALWAYS,
        FILE_ATTRIBUTE_NORMAL,
        nullptr
    );
    m_fileHandle = h;
#else
    // POSIX-compliant systems (Linux/macOS)
    std::wstring wpath = file.getPath();
    char* cpath = wstrToNarrow(wpath);
    int fd = ::open(cpath, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR);
    delete[] cpath;
    m_fileHandle = reinterpret_cast<void*>(fd);
#endif

    if (!isValidHandle()) {
        // TODO: Add robust error reporting/logging mechanism
#if defined(_WIN32) || defined(_DURANGO)
        DWORD err = GetLastError();
        (void)err;
#else
        int err = errno;
        (void)err;
#endif
    }
}

// Destructor ensures file handle is closed if still valid
FileOutputStream::~FileOutputStream() {
    if (isValidHandle()) {
        closeImpl();
    }
}

// Checks whether the current handle is valid
bool FileOutputStream::isValidHandle() const {
#ifdef _WIN32
    return m_fileHandle != nullptr && m_fileHandle != INVALID_HANDLE_VALUE;
#else
    int fd = reinterpret_cast<int>(m_fileHandle);
    return fd >= 0;
#endif
}

// Writes a single byte to the underlying file stream
void FileOutputStream::write(unsigned int b) {
    byte val = static_cast<byte>(b);

#ifdef _WIN32
    DWORD written = 0;
    BOOL ok = WriteFile(
        m_fileHandle,
        &val,
        1,
        &written,
        nullptr
    );
    if (!ok || written != 1) {
        // TODO: Handle write failure appropriately
    }
#else
    int fd = reinterpret_cast<int>(m_fileHandle);
    ssize_t written = ::write(fd, &val, 1);
    if (written != 1) {
        // TODO: Handle partial or failed write
    }
#endif
}

// Writes entire byte array to the file
void FileOutputStream::write(const byteArray& data) {
    if (data.data == nullptr || data.length == 0) return;

#ifdef _WIN32
    DWORD written = 0;
    BOOL ok = WriteFile(
        m_fileHandle,
        data.data,
        static_cast<DWORD>(data.length),
        &written,
        nullptr
    );
    if (!ok || written != data.length) {
        // TODO: Error handling
    }
#else
    int fd = reinterpret_cast<int>(m_fileHandle);
    ssize_t written = ::write(fd, data.data, data.length);
    if (written != static_cast<ssize_t>(data.length)) {
        // TODO: Partial write or error case
    }
#endif
}

// Writes a sub-range of the byte array starting at offset 'off' for 'len' bytes
void FileOutputStream::write(const byteArray& data, unsigned int off, unsigned int len) {
    assert(off + len <= data.length); // Bounds check

    if (len == 0) return;

#ifdef _WIN32
    DWORD written = 0;
    BOOL ok = WriteFile(
        m_fileHandle,
        reinterpret_cast<const BYTE*>(data.data) + off,
        static_cast<DWORD>(len),
        &written,
        nullptr
    );
    if (!ok || written != len) {
        // TODO: Error handling
    }
#else
    int fd = reinterpret_cast<int>(m_fileHandle);
    ssize_t written = ::write(fd, static_cast<const char*>(data.data) + off, len);
    if (written != static_cast<ssize_t>(len)) {
        // TODO: Partial write or error
    }
#endif
}

// Closes the file stream and invalidates the handle
void FileOutputStream::close() {
    if (isValidHandle()) {
        closeImpl();
        m_fileHandle = nullptr;
    }
}

// Internal helper to perform actual closing depending on platform
void FileOutputStream::closeImpl() {
#ifdef _WIN32
    CloseHandle(m_fileHandle);
#else
    int fd = reinterpret_cast<int>(m_fileHandle);
    ::close(fd);
#endif
}

#include <vector>
#include <set>
#include <algorithm>
#include <climits>

class Solution {
    std::multiset<long long> leftSet, rightSet;
public:
    long long minimumCost(std::vector<int>& nums, int k, int dist) {
        int n = nums.size();
        k--; // Adjust k as in original logic

        long long currentSum = nums[0];

        // Initialize with first window: indices 1 to dist+1
        for (int i = 1; i <= dist + 1; ++i) {
            currentSum += nums[i];
            leftSet.insert(nums[i]);
        }

        // Balance: move elements from leftSet to rightSet until leftSet has size k
        while (static_cast<int>(leftSet.size()) > k) {
            auto it = std::prev(leftSet.end());
            long long val = *it;
            currentSum -= val;
            rightSet.insert(val);
            leftSet.erase(it);
        }

        long long result = currentSum;

        // Slide the window from index dist+2 to n-1
        for (int i = dist + 2; i < n; ++i) {
            int outgoing = nums[i - dist - 1]; // element leaving the window

            // Remove outgoing element from appropriate set
            auto leftIt = leftSet.find(outgoing);
            if (leftIt != leftSet.end()) {
                currentSum -= outgoing;
                leftSet.erase(leftIt);
            } else {
                rightSet.erase(rightSet.find(outgoing));
            }

            int incoming = nums[i]; // element entering the window

            // Insert incoming element into appropriate set
            if (!leftSet.empty() && incoming < *std::prev(leftSet.end())) {
                currentSum += incoming;
                leftSet.insert(incoming);
            } else {
                rightSet.insert(incoming);
            }

            // Rebalance leftSet to have exactly k elements
            while (static_cast<int>(leftSet.size()) < k && !rightSet.empty()) {
                long long val = *rightSet.begin();
                currentSum += val;
                leftSet.insert(val);
                rightSet.erase(rightSet.begin());
            }

            while (static_cast<int>(leftSet.size()) > k) {
                auto it = std::prev(leftSet.end());
                long long val = *it;
                currentSum -= val;
                rightSet.insert(val);
                leftSet.erase(it);
            }

            result = std::min(result, currentSum);
        }

        return result;
    }
};

