#include <iostream>
#include <string>
#include <vector>
using namespace std;

// Approximate LCS using greedy skip-cost heuristic
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    string a, b;
    if (!(cin >> a >> b)) return 0;

    int lenA = a.size();
    int lenB = b.size();

    // Precompute positions for each character (ASCII range)
    vector<int> posA[128];
    vector<int> posB[128];

    for (int i = 0; i < lenA; ++i) {
        unsigned char ch = static_cast<unsigned char>(a[i]);
        posA[ch].push_back(i);
    }
    for (int i = 0; i < lenB; ++i) {
        unsigned char ch = static_cast<unsigned char>(b[i]);
        posB[ch].push_back(i);
    }

    // Track current position in each character's position list
    vector<int> idxA(128, 0);
    vector<int> idxB(128, 0);

    string result;
    result.reserve(min(lenA, lenB));

    int i = 0, j = 0;
    const int BIG = 1'000'000'000;

    while (i < lenA && j < lenB) {
        unsigned char ca = static_cast<unsigned char>(a[i]);
        unsigned char cb = static_cast<unsigned char>(b[j]);

        if (ca == cb) {
            result += a[i];
            ++i;
            ++j;
        } else {
            // Find next occurrence of 'ca' in string B starting from position j
            int nextInB = BIG;
            while (idxB[ca] < (int)posB[ca].size() && posB[ca][idxB[ca]] < j) {
                ++idxB[ca];
            }
            if (idxB[ca] < (int)posB[ca].size()) {
                nextInB = posB[ca][idxB[ca]];
            }

            // Find next occurrence of 'cb' in string A starting from position i
            int nextInA = BIG;
            while (idxA[cb] < (int)posA[cb].size() && posA[cb][idxA[cb]] < i) {
                ++idxA[cb];
            }
            if (idxA[cb] < (int)posA[cb].size()) {
                nextInA = posA[cb][idxA[cb]];
            }

            // Determine which option has lower "skip cost"
            int costMatchA = (nextInB == BIG) ? BIG : (nextInB - j);
            int costMatchB = (nextInA == BIG) ? BIG : (nextInA - i);

            if (costMatchA == BIG && costMatchB == BIG) {
                // Neither character appears later in the other string
                ++i;
                ++j;
            } else if (costMatchA <= costMatchB) {
                // Prefer matching character from string A
                result += a[i];
                ++i;
                j = nextInB + 1;
            } else {
                // Prefer matching character from string B
                result += b[j];
                i = nextInA + 1;
                ++j;
            }
        }
    }

    cout << result << '\n';
    return 0;
}

