#include "ELD/PluginAPI/OutputSectionIteratorPlugin.h"
#include "ELD/PluginAPI/PluginVersion.h"

class AddRule : public eld::plugin::OutputSectionIteratorPlugin {
public:
  AddRule() : eld::plugin::OutputSectionIteratorPlugin("AddRule") {}

  void Init(std::string config) override {
    // No initialization required for this plugin.
  }

  void processOutputSection(eld::plugin::OutputSection section) override {
    // Skip processing unless we're in the CreatingSections phase.
    if (Linker->getState() != eld::plugin::LinkerWrapper::State::CreatingSections)
      return;

    const std::string name = section.getName();
    if (name == "var")
      m_TargetSection = section;
    else if (name == "foo")
      m_SourceFoo = section;
    else if (name == "bar")
      m_SourceBar = section;
  }

  eld::plugin::Plugin::Status Run(bool /*trace*/) override {
    if (Linker->getState() != eld::plugin::LinkerWrapper::State::CreatingSections)
      return eld::plugin::Plugin::Status::SUCCESS;

    auto &rules = m_TargetSection.getLinkerScriptRules();
    if (rules.empty())
      return eld::plugin::Plugin::Status::SUCCESS;

    // Create a new rule at the end of the target section's rule list.
    eld::plugin::LinkerScriptRule newRule = Linker->createLinkerScriptRule(
        m_TargetSection, /*Annotation=*/"Move foo and bar chunks to var");

    // Insert the new rule after the last existing one.
    Linker->insertAfterRule(m_TargetSection, rules.back(), newRule);

    // Transfer all chunks from source sections' rules into the new rule.
    transferChunksFrom(m_SourceFoo, newRule);
    transferChunksFrom(m_SourceBar, newRule);

    return eld::plugin::Plugin::Status::SUCCESS;
  }

  void Destroy() override {
    // No cleanup needed here.
  }

  uint32_t GetLastError() override { return 0; }
  std::string GetLastErrorAsString() override { return "Success"; }
  std::string GetName() override { return "AddRule"; }

private:
  // Helper: move all chunks from a section’s rules into a new rule.
  void transferChunksFrom(eld::plugin::OutputSection srcSection,
                          eld::plugin::LinkerScriptRule dstRule) {
    for (auto &rule : srcSection.getLinkerScriptRules()) {
      for (auto chunk : rule.getChunks()) {
        Linker->addChunk(dstRule, chunk);
        Linker->removeChunk(rule, chunk);
      }
    }
  }

private:
  eld::plugin::OutputSection m_TargetSection = eld::plugin::OutputSection(nullptr);
  eld::plugin::OutputSection m_SourceFoo   = eld::plugin::OutputSection(nullptr);
  eld::plugin::OutputSection m_SourceBar   = eld::plugin::OutputSection(nullptr);
};

