#include "InputStream.h"
#include "DataInputStream.h"
#include "InputStreamReader.h"

// Constructs an InputStreamReader that wraps the provided InputStream using DataInputStream as the underlying reader
// Parameters:
//   in - Pointer to an InputStream object
InputStreamReader::InputStreamReader(InputStream *in) : stream(new DataInputStream(in))
{
}

// Closes the underlying input stream and frees associated system resources.
// After closing, any further operations (read, ready, mark, reset, skip) will result in undefined behavior or exceptions.
// Closing an already-closed stream is safe and has no effect.
void InputStreamReader::close()
{
    stream->close();
}

// Reads a single UTF character from the stream.
// Returns:
//   The 16-bit Unicode character read, or -1 if end-of-stream is reached.
int InputStreamReader::read()
{
    return stream->readUTFChar();
}

// Reads up to 'length' characters into the provided buffer starting at index 'offset'.
// Parameters:
//   cbuf     - Output buffer for wide characters (wchar_t array)
//   offset   - Starting position in the buffer where characters should be stored
//   length   - Maximum number of characters to attempt to read
// Returns:
//   Number of characters successfully read, or -1 if the end of the stream is reached before reading any characters.
int InputStreamReader::read(wchar_t cbuf[], unsigned int offset, unsigned int length)
{
    unsigned int totalRead = 0;
    unsigned int currentIndex = offset;

    while (totalRead < length && currentIndex < offset + length)
    {
        int rawChar = stream->readUTFChar();
        if (rawChar != -1)
        {
            cbuf[currentIndex] = static_cast<wchar_t>(rawChar);
            currentIndex++;
            totalRead++;
        }
        else
        {
            // End of stream reached
            break;
        }
    }

    return totalRead > 0 ? totalRead : -1;
}

