#include <QtWidgets/QApplication>
#include <sm/vvec>
#include <mplot/qt/viswidget.h>
#include <mplot/GraphVisual.h>

// Entry point for a minimal mplot visualization app using Qt
int main(int argc, char* argv[]) {
    QApplication app(argc, argv);

    // Instantiate the OpenGL-capable visualization widget (GL version selected at compile time)
    mplot::qt::viswidget<0> view;

    // Ensure initialization happens before adding models
    view.show();

    // Prepare a GraphVisual instance with 3D support
    auto graph = std::make_unique<mplot::GraphVisual<double, mplot::qt::gl_version>>(
        sm::vec<float>({0.0f, 0.0f, 0.0f})
    );

    // Register the model with the widget's visual manager
    view.v.bindmodel(graph);

    // Enable full 3D rendering (disable planar constraint)
    graph->twodimensional(false);

    // Generate x-values: from -0.5 to 0.8 in 14 evenly spaced steps
    sm::vvec<double> abscissae;
    abscissae.linspace(-0.5, 0.8, 14);

    // Compute corresponding y = x^3 values
    sm::vvec<double> ordinates = abscissae.pow(3);

    // Feed data into the graph model
    graph->setdata(abscissae, ordinates);

    // Finalize geometry generation (e.g., vertex buffer setup)
    graph->finalize();

    // Transfer ownership and integrate into scene
    view.v.addVisualModel(std::move(graph));

    // Start event loop
    return app.exec();
}

#include <iostream>
#include <queue>
#include <vector>
using namespace std;

int main() {
    // Create a max heap using priority_queue (default behavior)
    priority_queue<int> maxHeap;

    // Insert elements into the max heap
    maxHeap.push(1);
    maxHeap.push(2);
    maxHeap.push(3);
    maxHeap.push(4);
    maxHeap.emplace(5);

    // Extract and print elements in descending order
    while (!maxHeap.empty()) {
        cout << maxHeap.top() << " ";
        maxHeap.pop();
    }
    cout << endl;

    // Report status after emptying the max heap
    cout << "Remaining size of max heap: " << maxHeap.size() << endl;
    cout << "Is max heap empty? " << (maxHeap.empty() ? "Yes" : "No") << endl;

    // Create a min heap by specifying comparator
    priority_queue<int, vector<int>, greater<int>> minHeap;

    // Insert elements into the min heap
    minHeap.push(1);
    minHeap.push(2);
    minHeap.push(3);
    minHeap.push(4);
    minHeap.emplace(5);
    minHeap.emplace(6);

    // Extract and print elements in ascending order
    while (!minHeap.empty()) {
        cout << minHeap.top() << " ";
        minHeap.pop();
    }
    cout << endl;

    // Report status after emptying the min heap
    cout << "Remaining size of min heap: " << minHeap.size() << endl;
    cout << "Is min heap empty? " << (minHeap.empty() ? "Yes" : "No") << endl;

    return 0;
}

