#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

// Converts a character from the set {'A'-'Z', '0'-'9'} to an integer in [0, 35]
inline int char_to_index(char c) {
    if (c >= 'A' && c <= 'Z') {
        return c - 'A';
    }
    return c - '0' + 26;
}

// Constructs a common subsequence by scanning string 'a' and greedily matching characters in 'b'
// Time complexity: O(|a| + |b|)
std::string build_common_subseq(const std::string& src, const std::string& target) {
    // Build lookup table: for each character, store all its positions in 'target'
    std::vector<std::vector<int>> char_positions(36);
    for (int idx = 0; idx < static_cast<int>(target.size()); ++idx) {
        char_positions[char_to_index(target[idx])].push_back(idx);
    }

    std::string result;
    result.reserve(std::min(src.size(), target.size()));

    int last_matched_idx = -1;
    std::vector<int> char_pointers(36, 0);

    for (char ch : src) {
        int id = char_to_index(ch);

        // Advance pointer for this character until we find a position > last_matched_idx
        while (char_pointers[id] < static_cast<int>(char_positions[id].size()) &&
               char_positions[id][char_pointers[id]] <= last_matched_idx) {
            ++char_pointers[id];
        }

        // If found, include this character in the subsequence
        if (char_pointers[id] < static_cast<int>(char_positions[id].size())) {
            result.push_back(ch);
            last_matched_idx = char_positions[id][char_pointers[id]];
            ++char_pointers[id]; // Move past this occurrence for future searches
        }
    }

    return result;
}

int main() {
    // Optimize I/O performance
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::string input1, input2;
    std::cin >> input1 >> input2;

    // Generate two candidate subsequences by running the greedy method in both directions
    std::string candidate1 = build_common_subseq(input1, input2);
    std::string candidate2 = build_common_subseq(input2, input1);

    // Output the longer of the two candidates
    if (candidate1.length() >= candidate2.length()) {
        std::cout << candidate1 << '\n';
    } else {
        std::cout << candidate2 << '\n';
    }

    return 0;
}

