namespace NGTest::NInternal {
    namespace {
        void FormatActualExceptionDetails(const std::exception& err, const TBackTrace* bt, TStringBuilder& out) {
            out << "an exception of type " << TypeName(err) << " "
                << "with message " << TString(err.what()).Quote() << ".";
            if (bt) {
                out << "\n   Trace: ";
                auto lines = StringSplitter(bt->PrintToString()).Split('\n');
                for (auto&& line : lines) {
                    out << "          " << line.Token() << "\n";
                }
            }
        }

        void FormatActual(TStringBuilder& out) {
            out << "  Actual: it throws ";
            auto excPtr = std::current_exception();
            if (excPtr) {
                try {
                    std::rethrow_exception(excPtr);
                } catch (const yexception& e) {
                    FormatActualExceptionDetails(e, e.BackTrace(), out);
                    return;
                } catch (const std::exception& e) {
                    FormatActualExceptionDetails(e, nullptr, out);
                    return;
                } catch (...) {
                    out << "an unknown exception.";
                    return;
                }
            }
            out << "nothing.";
        }

        void FormatExpected(const char* stmt, const char* excType, const TString& msgFilter, TStringBuilder& out) {
            out << "Expected: ";
            if (TStringBuf(stmt).size() > 80) {
                out << "statement";
            } else {
                out << stmt;
            }
            out << " throws an exception of type " << excType;
            if (!msgFilter.empty()) {
                out << " with message containing " << msgFilter.Quote();
            }
            out << ".";
        }
    }

    TString FormatErrorWrongException(const char* statement, const char* type) {
        return FormatErrorWrongException(statement, type, "");
    }

    TString FormatErrorWrongException(const char* statement, const char* type, TString contains) {
        TStringBuilder result;
        FormatExpected(statement, type, contains, result);
        result << "\n";
        FormatActual(result);
        return result;
    }

    TString FormatErrorUnexpectedException(const char* statement) {
        TStringBuilder result;
        out << "Expected: ";
        if (TStringBuf(statement).size() > 80) {
            out << "statement";
        } else {
            out << statement;
        }
        out << " doesn't throw an exception.\n  ";
        FormatActual(result);
        return result;
    }

    bool ExceptionMessageContains(const std::exception& err, TString filter) {
        return TStringBuf(err.what()).Contains(filter);
    }
}

#include <iostream>
#include <asio.hpp>

class DualTimerPrinter
{
public:
    DualTimerPrinter(asio::io_context& context)
        : work_guard_(context),
          timer_a_(context),
          timer_b_(context),
          counter_(0)
    {
        // Initialize both timers with 1-second delay
        timer_a_.expires_after(std::chrono::seconds(1));
        timer_b_.expires_after(std::chrono::seconds(1));

        // Start async waits using lambda expressions instead of boost::bind
        start_timer_a();
        start_timer_b();
    }

    ~DualTimerPrinter()
    {
        std::cout << "Final count is " << counter_ << std::endl;
    }

private:
    void start_timer_a()
    {
        timer_a_.async_wait([this](const asio::error_code& ec)
        {
            if (!ec && counter_ < 10)
            {
                std::cout << "Timer 1: " << counter_ << std::endl;
                ++counter_;

                // Reschedule this timer for another second later
                timer_a_.expires_at(timer_a_.expiry() + std::chrono::seconds(1));
                start_timer_a();
            }
        });
    }

    void start_timer_b()
    {
        timer_b_.async_wait([this](const asio::error_code& ec)
        {
            if (!ec && counter_ < 10)
            {
                std::cout << "Timer 2: " << counter_ << std::endl;
                ++counter_;

                // Reschedule this timer for another second later
                timer_b_.expires_at(timer_b_.expiry() + std::chrono::seconds(1));
                start_timer_b();
            }
        });
    }

    asio::executor_work_guard<asio::io_context::executor_type> work_guard_;
    asio::steady_timer timer_a_;
    asio::steady_timer timer_b_;
    int counter_;
};

int main()
{
    asio::io_context io_context_obj;
    DualTimerPrinter printer_instance(io_context_obj);

    // Run the io_context in multiple threads for concurrency
    asio::thread worker_thread(
        [&io_context_obj]() { io_context_obj.run(); });

    io_context_obj.run();
    worker_thread.join();

    return 0;
}

