#include <vector>
#include <string>
#include <queue>

class Solution {
public:
    std::vector<std::string> generateParenthesis(int n) {
        std::vector<std::string> result;

        // Using BFS approach with queue to generate all valid combinations
        // Each queue element stores: current_string, open_count_remaining, close_count_remaining
        struct State {
            std::string str;
            int open_remaining;
            int close_remaining;
        };

        std::queue<State> q;
        q.push({"", n, n});

        while (!q.empty()) {
            State current = q.front();
            q.pop();

            // If no more parentheses needed, add to result
            if (current.close_remaining == 0) {
                result.push_back(current.str);
                continue;
            }

            // If we can add an opening parenthesis (still have some left)
            if (current.open_remaining > 0) {
                q.push({current.str + "(", current.open_remaining - 1, current.close_remaining});
            }

            // If we can add a closing parenthesis (only if it won't make string invalid)
            // This is when we have more closing remaining than opening (meaning we have unmatched opens)
            if (current.close_remaining > current.open_remaining) {
                q.push({current.str + ")", current.open_remaining, current.close_remaining - 1});
            }
        }

        return result;
    }
};

