#include <iostream>
#include <vector>
using namespace std;

// Leetcode 1352: Product of Last K Numbers (Type III Clone)
class ProductOfNumbers {
private:
    vector<long long> prefixProducts;  // Stores cumulative products, using long long to avoid overflow

public:
    ProductOfNumbers() {
        prefixProducts.push_back(1);  // Initialize with 1 as multiplicative identity
    }

    void add(int number) {
        if (number == 0) {
            // Reset the prefix products when encountering zero
            prefixProducts.clear();
            prefixProducts.push_back(1);
        } else {
            // Append the new product by multiplying current number with last product
            prefixProducts.push_back(prefixProducts.back() * number);
        }
    }

    int getProduct(int k) {
        // If k is greater than or equal to the size of prefix products, 
        // it means there were fewer than k numbers added since last zero
        if (k >= prefixProducts.size()) {
            return 0;
        }
        // Compute product using division of prefix products
        return static_cast<int>(prefixProducts.back() / prefixProducts[prefixProducts.size() - k - 1]);
    }
};

#include <iostream>
#include <vector>
// Function to enable fast I/O
void fast_io() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);
}
// Global variables for graph representation and DSATUR-related data
int vertex_count, edge_count;
std::vector<std::vector<bool>> adjacency_matrix;
std::vector<int> assigned_colors;
std::vector<int> complement_degrees;
std::vector<int> saturation_levels;
std::vector<std::vector<bool>> color_tracker;

// Input reading function: constructs the graph from standard input
void load_graph() {
    std::cin >> vertex_count >> edge_count;
    adjacency_matrix.assign(vertex_count + 1, std::vector<bool>(vertex_count + 1, false));
    for (int idx = 0; idx < edge_count; ++idx) {
        int u, v;
        std::cin >> u >> v;
        adjacency_matrix[u][v] = adjacency_matrix[v][u] = true;
    }
}

// Main solver using DSATUR on the complement graph
void compute_clique_cover() {
    // Step 1: Compute degrees in the complement graph
    complement_degrees.assign(vertex_count + 1, 0);
    for (int i = 1; i <= vertex_count; ++i) {
        for (int j = i + 1; j <= vertex_count; ++j) {
            if (!adjacency_matrix[i][j]) {
                complement_degrees[i]++;
                complement_degrees[j]++;
            }
        }
    }

    // Initialize DSATUR structures
    assigned_colors.assign(vertex_count + 1, 0); // 0 means uncolored
    saturation_levels.assign(vertex_count + 1, 0);
    color_tracker.assign(vertex_count + 1, std::vector<bool>(vertex_count + 2, false));

    // Process each vertex one by one
    for (int step = 0; step < vertex_count; ++step) {
        // Select next vertex: highest saturation degree, tie-break by complement degree
        int candidate = -1;
        for (int v = 1; v <= vertex_count; ++v) {
            if (assigned_colors[v] == 0) {
                if (candidate == -1 || 
                    saturation_levels[v] > saturation_levels[candidate] ||
                    (saturation_levels[v] == saturation_levels[candidate] && 
                     complement_degrees[v] > complement_degrees[candidate])) {
                    candidate = v;
                }
            }
        }
        int selected = candidate;

        // Determine smallest available color not used by neighbors in complement graph
        std::vector<bool> neighbor_color_flags(vertex_count + 2, false);
        for (int neighbor = 1; neighbor <= vertex_count; ++neighbor) {
            if (neighbor != selected && !adjacency_matrix[selected][neighbor] && assigned_colors[neighbor] != 0) {
                neighbor_color_flags[assigned_colors[neighbor]] = true;
            }
        }
        int chosen_color = 1;
        while (neighbor_color_flags[chosen_color]) {
            ++chosen_color;
        }
        assigned_colors[selected] = chosen_color;

        // Update saturation levels of uncolored neighbors in complement graph
        for (int neighbor = 1; neighbor <= vertex_count; ++neighbor) {
            if (neighbor != selected && !adjacency_matrix[selected][neighbor] && assigned_colors[neighbor] == 0) {
                if (!color_tracker[neighbor][chosen_color]) {
                    color_tracker[neighbor][chosen_color] = true;
                    saturation_levels[neighbor]++;
                }
            }
        }
    }
}

int main() {
    fast_io();
    load_graph();
    compute_clique_cover();
    for (int i = 1; i <= vertex_count; ++i) {
        std::cout << assigned_colors[i] << '\n';
    }
    return 0;
}

