namespace {

// Alternative implementation using a different loop structure and variable naming
template <typename Map>
void benchmark_swap(std::string_view map_name) {
    Map container1;
    Map container2;

    // Initialize with deterministic seed for reproducibility
    ankerl::nanobench::Rng random_generator(456);
    ankerl::nanobench::Bench performance_test;

    // Pre-populate maps using while-loop instead of for-loop
    size_t counter = 0;
    while (counter < 10000) {
        container1[random_generator()];
        container2[random_generator()];
        ++counter;
    }

    // Benchmark the swap operation
    performance_test.run(fmt::format("exchange {}", map_name), [&] {
        std::swap(container1, container2);
    });

    // Prevent compiler optimizations from eliminating the maps
    ankerl::nanobench::doNotOptimizeAway(&container1);
    ankerl::nanobench::doNotOptimizeAway(&container2);
}

} // namespace

