#include <pybind11/eigen.h>
#include <pybind11/numpy.h>
#include <pybind11/pybind11.h>
#include <pybind11/stl.h>
#include <Eigen/Dense>
#include <lapack.hh>
#include <vector>

namespace py = pybind11;

/**
 * @brief Compute eigenvalues and eigenvectors for a real symmetric matrix using LAPACK's syev.
 *
 * This function accepts a 2D NumPy array representing a square real symmetric matrix,
 * and returns its eigenvalues (sorted in ascending order) and corresponding eigenvectors.
 *
 * @param input_matrix Input dense symmetric matrix as a NumPy array.
 * @return A tuple of (eigenvalues, eigenvectors).
 */
py::tuple compute_symmetric_eigensystem(const py::array_t<double>& input_matrix) {
  // Ensure the input is a 2D array
  if (input_matrix.ndim() != 2) {
    throw std::invalid_argument("Input must be a 2-dimensional array.");
  }

  auto dims = input_matrix.shape();
  if (dims[0] != dims[1]) {
    throw std::invalid_argument("Matrix must be square.");
  }

  int size = dims[0];

  // Convert NumPy array to Eigen matrix
  Eigen::MatrixXd mat = Eigen::Map<const Eigen::MatrixXd>(input_matrix.data(), size, size);
  Eigen::VectorXd eigen_vals(size);

  // Call LAPACK's syev routine to compute eigenvalues and eigenvectors
  int status = lapack::syev(lapack::Job::Vec, lapack::Uplo::Lower, size,
                            mat.data(), size, eigen_vals.data());

  if (status != 0) {
    throw std::runtime_error("LAPACK syev failed to converge.");
  }

  return py::make_tuple(eigen_vals, mat);
}

/**
 * @brief Register the symmetric eigenvalue solver with the Python module.
 *
 * @param m The pybind11 module object to bind functions to.
 */
void register_symmetric_solver(py::module& m) {
  m.def("symmetric_eigensolve", &compute_symmetric_eigensystem,
        R"(
            Compute eigenvalues and eigenvectors of a real symmetric matrix via LAPACK's syev.

            Parameters
            ----------
            input_matrix : numpy.ndarray
                A square symmetric matrix represented as a 2D NumPy array of doubles.

            Returns
            -------
            tuple
                - eigenvalues: 1D numpy.ndarray of shape (n,) containing eigenvalues in ascending order
                - eigenvectors: 2D numpy.ndarray of shape (n, n), where column i is the eigenvector for eigenvalue i

            Raises
            ------
            ValueError
                If the input is not a square matrix or has incorrect dimensions.
            RuntimeError
                If the underlying LAPACK routine fails to compute all eigenvalues.
        )",
        py::arg("input_matrix"));
}

