typename IDisplayClusterSessionPacketHandler<FDisplayClusterPacketBinary, false>::ReturnType
FDisplayClusterClusterEventsBinaryService::HandleIncomingPacket(const TSharedPtr<FDisplayClusterPacketBinary>& InPacket)
{
	// Validate input
	if (!InPacket.IsValid())
	{
		UE_LOG(LogDisplayClusterNetwork, Error, TEXT("%s - Null packet received"), *GetName());
		return typename IDisplayClusterSessionPacketHandler<FDisplayClusterPacketBinary, false>::ReturnType();
	}

	// Decode binary packet into internal event format
	FDisplayClusterClusterEventBinary DecodedEvent;
	if (!DisplayClusterNetworkDataConversion::BinaryPacketToBinaryEvent(InPacket, DecodedEvent))
	{
		UE_LOG(LogDisplayClusterNetwork, Error, TEXT("%s - Failed to decode incoming binary packet"), *GetName());
		return typename IDisplayClusterSessionPacketHandler<FDisplayClusterPacketBinary, false>::ReturnType();
	}

	// Log and forward for internal use
	UE_LOG(LogDisplayClusterNetwork, Verbose, TEXT("%s - Forwarding cluster event internally..."), *GetName());
	ForwardClusterEventBinary(DecodedEvent);

	return typename IDisplayClusterSessionPacketHandler<FDisplayClusterPacketBinary, false>::ReturnType();
}

