#include <cstdlib>
#include <iostream>
#include <memory>
#include <utility>
#include <asio/ts/buffer.hpp>
#include <asio/ts/internet.hpp>

using asio::ip::tcp;

// Echo session that handles bidirectional communication
class echo_session
  : public std::enable_shared_from_this<echo_session>
{
public:
  echo_session(tcp::socket socket)
    : socket_(std::move(socket))
  {
  }

  void begin()
  {
    initiate_read();
  }

private:
  void initiate_read()
  {
    auto self(shared_from_this());
    socket_.async_read_some(asio::buffer(buffer_, buffer_size),
        [this, self](std::error_code error, std::size_t bytes_transferred)
        {
          if (!error)
          {
            handle_read(bytes_transferred);
          }
        });
  }

  void handle_read(std::size_t length)
  {
    auto self(shared_from_this());
    asio::async_write(socket_, asio::buffer(buffer_, length),
        [this, self](std::error_code error, std::size_t /*bytes_sent*/)
        {
          if (!error)
          {
            initiate_read(); // Continue echoing
          }
        });
  }

  tcp::socket socket_;
  static constexpr std::size_t buffer_size = 1024;
  char buffer_[buffer_size];
};

// Server accepting incoming connections
class echo_server
{
public:
  echo_server(asio::io_context& context, unsigned short port_number)
    : acceptor_(context, tcp::endpoint(tcp::v4(), port_number)),
      connection_socket_(context)
  {
    await_connection();
  }

private:
  void await_connection()
  {
    acceptor_.async_accept(connection_socket_,
        [this](std::error_code error)
        {
          if (!error)
          {
            std::make_shared<echo_session>(std::move(connection_socket_))->begin();
          }
          await_connection(); // Accept next connection
        });
  }

  tcp::acceptor acceptor_;
  tcp::socket connection_socket_;
};

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 2)
    {
      std::cerr << "Usage: async_echo_server <port>\n";
      return 1;
    }

    asio::io_context io_context;
    echo_server server(io_context, static_cast<unsigned short>(std::atoi(argv[1])));
    io_context.run();
  }
  catch (const std::exception& exception)
  {
    std::cerr << "Error: " << exception.what() << "\n";
    return 1;
  }

  return 0;
}

