using namespace llvm;

namespace {
/// NVPTXAssignValidGlobalNames - Ensures global variables and functions with local linkage have PTX-valid names
class NVPTXAssignValidGlobalNames : public ModulePass {
public:
  static char ID;
  NVPTXAssignValidGlobalNames() : ModulePass(ID) {}

  bool runOnModule(Module &M) override;

  /// Sanitize a name by replacing invalid characters with safe alternatives
  std::string sanitizeName(StringRef original);
};
}

char NVPTXAssignValidGlobalNames::ID = 0;

namespace llvm {
void initializeNVPTXAssignValidGlobalNamesPass(PassRegistry &);
}

INITIALIZE_PASS(NVPTXAssignValidGlobalNames, "nvptx-assign-valid-global-names",
                "Assign valid PTX identifiers to module-level entities", false, false)

bool NVPTXAssignValidGlobalNames::runOnModule(Module &M) {
  // Process all global variables first
  for (auto &GV : M.globals()) {
    if (GV.hasLocalLinkage()) {
      GV.setName(sanitizeName(GV.getName()));
    }
  }

  // Then process local functions
  for (auto &F : M.functions()) {
    if (F.hasLocalLinkage()) {
      F.setName(sanitizeName(F.getName()));
    }
  }

  return true;
}

std::string NVPTXAssignValidGlobalNames::sanitizeName(StringRef input) {
  std::string result;
  raw_string_ostream stream(result);

  for (char ch : input) {
    switch (ch) {
      case '.':
      case '@':
      case '<':
      case '>':
        stream << "_$_";
        break;
      default:
        stream << ch;
    }
  }

  return stream.str();
}

ModulePass *llvm::createNVPTXAssignValidGlobalNamesPass() {
  return new NVPTXAssignValidGlobalNames();
}

#include <iostream>
#include <vector>
#include <string>

// Generates a 20x20 grid map for the "Kangaroos" problem with a comb-like structure
int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    const int rows = 20;
    const int cols = 20;

    // Output dimensions
    std::cout << rows << " " << cols << "\n";

    // Initialize grid with '0's
    std::vector<std::string> grid(rows, std::string(cols, '0'));

    // Position the horizontal spine in the middle (row index 9 for 20 rows)
    const int spine_row = rows / 2 - 1;

    // Create the central horizontal backbone
    for (int col = 0; col < cols; ++col) {
        grid[spine_row][col] = '1';
    }

    // Add vertical teeth at even column positions to maintain tree structure
    for (int col = 0; col < cols; col += 2) {
        // Extend upward from spine to top edge
        for (int row = 0; row < spine_row; ++row) {
            grid[row][col] = '1';
        }
        // Extend downward from spine to bottom edge
        for (int row = spine_row + 1; row < rows; ++row) {
            grid[row][col] = '1';
        }
    }

    // Output the final map
    for (const auto& line : grid) {
        std::cout << line << "\n";
    }

    return 0;
}
